fn cap_ctl_selection(mut text: String) -> (String, bool) {
    if text.len() <= MAX_CTL_SELECTION_BYTES {
        return (text, false);
    }
    let mut end = MAX_CTL_SELECTION_BYTES;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    text.truncate(end);
    (text, true)
}

fn cap_utf8_bytes(mut text: String, cap: usize) -> (String, bool) {
    if text.len() <= cap {
        return (text, false);
    }
    let mut end = cap;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    text.truncate(end);
    (text, true)
}

/// Merge independently-owned placement classes without letting a saturated
/// class hide every item from the others. This preserves all three bounded
/// registries for visibility culling; the renderer applies the smaller shared
/// frame quota after removing offscreen placements.
fn round_robin_bounded<T, const N: usize>(groups: [Vec<T>; N], limit: usize) -> Vec<T> {
    let mut groups = groups.map(Vec::into_iter);
    let mut out = Vec::with_capacity(
        groups
            .iter()
            .map(|group| group.len())
            .sum::<usize>()
            .min(limit),
    );
    while out.len() < limit {
        let before = out.len();
        for group in &mut groups {
            if let Some(item) = group.next() {
                out.push(item);
                if out.len() == limit {
                    break;
                }
            }
        }
        if out.len() == before {
            break;
        }
    }
    out
}

fn ctl_snapshot(kind: &str, value: &(impl serde::Serialize + ?Sized)) -> String {
    // Stable FNV-1a is sufficient here: the token detects live-state drift; it
    // is not an authentication primitive.
    struct Hasher(u64);
    impl std::io::Write for Hasher {
        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
            for &byte in bytes {
                self.0 ^= u64::from(byte);
                self.0 = self.0.wrapping_mul(0x100000001b3);
            }
            Ok(bytes.len())
        }

        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }
    let mut hasher = Hasher(0xcbf29ce484222325);
    let _ = std::io::Write::write_all(&mut hasher, kind.as_bytes());
    let _ = serde_json::to_writer(&mut hasher, value);
    format!("{:016x}", hasher.0)
}

fn media_receipt_accessibility_label(
    kind: &kettle_render::MediaPasteReceiptKind,
    remote: bool,
    tr: &kettle_i18n::Translator,
) -> String {
    let mut label = match kind {
        kettle_render::MediaPasteReceiptKind::Image {
            original_width,
            original_height,
        } => tr.receipt_a11y_image(u64::from(*original_width), u64::from(*original_height)),
        kettle_render::MediaPasteReceiptKind::Video {
            extension,
            size,
            count,
            ..
        } if *count > 1 => tr.receipt_a11y_videos(
            *count as u64,
            extension,
            &kettle_render::format_media_size(*size),
        ),
        kettle_render::MediaPasteReceiptKind::Video {
            extension, size, ..
        } => tr.receipt_a11y_video(extension, &kettle_render::format_media_size(*size)),
    };
    if remote {
        label.push_str(", ");
        label.push_str(tr.text(kettle_i18n::Text::ReceiptA11yRemote));
    }
    label
}

/// Sum a lazily-produced inventory while stopping as soon as the budget is
/// crossed. Keeping this lazy is important: the limit exists to bound the
/// enumeration itself, not merely the result allocation that follows it.
fn ctl_bounded_sum(counts: impl IntoIterator<Item = usize>, limit: usize) -> Option<usize> {
    let mut total = 0usize;
    for count in counts {
        total = total.checked_add(count)?;
        if total > limit {
            return None;
        }
    }
    Some(total)
}

#[cfg(test)]
fn ctl_page_values(
    req: &kettle_ctl::protocol::Request,
    key: &str,
    values: Vec<serde_json::Value>,
) -> kettle_ctl::protocol::Response {
    use kettle_ctl::protocol::{PageRequest, Response, error_codes as ec};

    let page = match PageRequest::from_params(&req.params) {
        Ok(page) => page,
        Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
    };
    ctl_page_values_with_page(req, key, values, page)
}

/// `get_state`'s `media` field: whether media previews are available, and a
/// fixed reason code when they are not. Asking never waits on a check.
/// Why `show` cannot render now, if it cannot: no worker, or one that
/// failed its checks. A worker still being checked is waited for.
fn media_unavailable(
    media: Option<&kettle_media::client::WorkerClient>,
) -> Option<kettle_media::FailureCode> {
    use kettle_media::FailureCode;
    use kettle_media::client::{MediaAvailability, UnavailableCause};
    match media.map(kettle_media::client::WorkerClient::availability) {
        None => Some(FailureCode::WorkerUnavailable),
        Some(MediaAvailability::Checking | MediaAvailability::Available) => None,
        Some(MediaAvailability::Unavailable(UnavailableCause::UnsupportedPlatform)) => {
            Some(FailureCode::UnsupportedPlatform)
        }
        Some(MediaAvailability::Unavailable(_)) => Some(FailureCode::WorkerUnavailable),
    }
}

/// The shelf items on screen in any window, whose pixels eviction spares:
/// each preview lane's, and each item whose card the last frame drew.
fn media_visible_items<'a>(
    windows: impl Iterator<Item = &'a WindowState>,
    cards: &crate::media::CardLedger,
) -> Vec<u64> {
    let mut visible = Vec::new();
    for window in windows {
        visible.extend(window.preview_panels.values().map(|panel| panel.item));
        if let Some(renderer) = &window.renderer {
            visible.extend(
                renderer
                    .drawn_cards()
                    .iter()
                    .filter_map(|card| cards.item(card.pane, card.nonce)),
            );
        }
    }
    visible
}

/// Whether the release of a press card `pressed` took opens it: only over the
/// very card it pressed, and only while nothing that owns the pointer (a
/// dialog, a menu, the viewer) has opened over it since the press.
fn card_release_opens(
    pressed: (u64, kettle_core::InlineNonce),
    over: Option<kettle_render::PaintedCard>,
    covered: bool,
) -> bool {
    !covered && over.is_some_and(|card| (card.pane, card.nonce) == pressed)
}

/// What an item is, in a lane's detail line or a card's screen-reader label:
/// its kind and size, and for a video its own size (not its poster's),
/// codec, length and whether it has sound.
fn media_item_detail(
    tr: kettle_i18n::Translator,
    kind: &str,
    item: &crate::media::ShelfItem,
) -> String {
    let Some(video) = &item.video else {
        let (width, height) = item.size;
        return format!("{kind} · {width}×{height}");
    };
    let mut detail = format!("{kind} · {}×{}", video.width, video.height);
    if let Some(codec) = video.codec.name() {
        detail.push_str(" · ");
        detail.push_str(codec);
    }
    detail.push_str(" · ");
    detail.push_str(&kettle_render::duration_label(video.duration_ms));
    detail.push_str(" · ");
    detail.push_str(tr.text(if video.has_audio {
        kettle_i18n::Text::MediaVideoWithAudio
    } else {
        kettle_i18n::Text::MediaVideoNoAudio
    }));
    detail
}

/// Register an inline card for a published item and build the message its
/// harness prints. `None` when the harness is over its limits, the pane
/// cannot hold a card, no nonce could be had, or the message would not
/// print whole: the item stays on the shelf either way.
#[allow(clippy::too_many_arguments)]
fn register_card(
    cards: &mut crate::media::CardLedger,
    (pane_id, pane_cards, grid): (u64, &mut kettle_render::InlineCards, (usize, usize)),
    cell: (f32, f32),
    item: (u64, u64),
    (kind, video): (kettle_media::MediaKind, Option<&kettle_media::VideoInfo>),
    image: &kettle_core::ImageData,
    inline: crate::media::InlineDraft,
    now: std::time::Instant,
) -> Option<kettle_ctl::show::InlineDelivery> {
    cards.admit(inline.owner, now).ok()?;
    let size = crate::media::card_size(inline.harness, grid, cell, (image.width, image.height))?;
    let nonce = cards.mint(|pool| getrandom::fill(pool).is_ok())?;
    let room = grid.0.saturating_sub(inline.harness.left() + 1);
    let caption = crate::media::card_caption(
        inline.name.as_deref(),
        kind,
        video.map_or((image.width, image.height), |video| {
            (video.width, video.height)
        }),
        video.map(|video| video.duration_ms),
        room,
    );
    let delivery = kettle_ctl::show::InlineDelivery {
        permit: None,
        message: crate::media::card_message(nonce, size, &caption)?,
    };
    if !delivery.fits() {
        return None;
    }
    pane_cards
        .insert(
            nonce,
            kettle_render::CardSpec {
                rows: size.0,
                columns: size.1,
                harness: inline.harness,
                caption,
                poster: Some(kettle_render::CardPoster::new(image)),
                duration_ms: video.map(|video| video.duration_ms),
            },
        )
        .ok()?;
    cards.record(
        nonce,
        crate::media::CardRecord {
            pane: pane_id,
            item,
            owner: inline.owner,
        },
        now,
    );
    Some(delivery)
}

/// The window holding `pane`: `ws` or one of `windows`.
fn window_with_pane<'a>(
    ws: &'a mut WindowState,
    windows: &'a mut std::collections::BTreeMap<u64, WindowState>,
    pane: u64,
) -> Option<&'a mut WindowState> {
    if ws.mux.panes.contains_key(&pane) {
        return Some(ws);
    }
    windows
        .values_mut()
        .find(|window| window.mux.panes.contains_key(&pane))
}

/// `get_state`'s `media`: whether the worker is there, and which video
/// decoders a worker here has, which is release policy, not a search: the
/// user's ffmpeg is looked for when a worker starts, and no GStreamer is used.
fn ctl_media_state(media: Option<&kettle_media::client::WorkerClient>) -> serde_json::Value {
    use kettle_media::client::MediaAvailability;
    let mut state = match media.map(kettle_media::client::WorkerClient::availability) {
        None => serde_json::json!({ "availability": "unavailable", "reason": "not_configured" }),
        Some(MediaAvailability::Checking) => serde_json::json!({ "availability": "checking" }),
        Some(MediaAvailability::Available) => serde_json::json!({ "availability": "available" }),
        Some(MediaAvailability::Unavailable(cause)) => {
            serde_json::json!({ "availability": "unavailable", "reason": cause.code() })
        }
    };
    state["video"] = serde_json::json!({
        "decoders": kettle_media::video::DECODERS,
        "gstreamer": "not_used",
    });
    state
}

fn ctl_page_values_with_page(
    req: &kettle_ctl::protocol::Request,
    key: &str,
    values: Vec<serde_json::Value>,
    page: kettle_ctl::protocol::PageRequest,
) -> kettle_ctl::protocol::Response {
    use kettle_ctl::protocol::{Response, error_codes as ec};

    if values.len() > MAX_CTL_COLLECTION_ITEMS {
        return Response::err(
            req.id,
            ec::RESPONSE_TOO_LARGE,
            "live-state collection exceeds the control enumeration budget",
        );
    }
    let snapshot = ctl_snapshot(key, &values);
    if page
        .snapshot
        .as_deref()
        .is_some_and(|want| want != snapshot)
    {
        return Response::err(
            req.id,
            ec::STALE_SNAPSHOT,
            "live state changed between pages; restart without cursor/snapshot",
        );
    }
    let total = values.len();
    let (start, end, next_cursor, truncated) = page.bounds(total);
    let mut result = serde_json::Map::new();
    result.insert(
        key.into(),
        serde_json::Value::Array(values[start..end].to_vec()),
    );
    result.insert("snapshot".into(), serde_json::Value::String(snapshot));
    result.insert("next_cursor".into(), next_cursor.into());
    result.insert("truncated".into(), truncated.into());
    result.insert("total".into(), total.into());
    Response::ok(req.id, serde_json::Value::Object(result))
}

/// A paste made while a clipboard image was still being encoded. It waits
/// its turn so pastes land in the order they were made.
struct QueuedPaste {
    window: u64,
    target: Option<u64>,
    receipt_pane: Option<u64>,
    broadcast: crate::mux::BroadcastScope,
    /// The panes a broadcast paste reaches, every window's, when it was made.
    recipients: Vec<u64>,
    content: QueuedPasteContent,
}

enum QueuedPasteContent {
    /// The PNG of encoder job `id`, once it is kept or has failed, and the
    /// clipboard's text to paste instead if it failed.
    Image {
        id: u64,
        fallback: String,
        path: Option<std::io::Result<std::path::PathBuf>>,
    },
    Text(String),
    Paths {
        paths: Vec<std::path::PathBuf>,
        trailing_space: bool,
        video: Option<crate::video_preview::VideoPasteRequest>,
    },
}

impl QueuedPasteContent {
    /// The bytes it holds while it waits.
    fn bytes(&self) -> usize {
        match self {
            Self::Image { fallback, .. } => fallback.len(),
            Self::Text(text) => text.len(),
            Self::Paths { paths, .. } => paths
                .iter()
                .map(|path| path.as_os_str().len())
                .fold(0, usize::saturating_add),
        }
    }

    /// Whether it is an image still being encoded.
    fn encoding(&self) -> bool {
        matches!(self, Self::Image { path: None, .. })
    }
}

/// Most pastes that may wait behind encoding images, and their text bytes.
const QUEUED_PASTES_MAX: usize = 64;
const QUEUED_PASTE_BYTES_MAX: usize = 4 * LOCAL_PASTE_MAX;

#[derive(Debug, Clone)]
pub enum UserEvent {
    Wakeup,
    /// The paste encoder finished a clipboard image's PNG.
    PastedImageEncoded,
    #[cfg(target_os = "linux")]
    Wayland,
    /// The coalescing process-tree worker published a new remote/cwd snapshot.
    /// Kept distinct from PTY output wakeups so an idle window consumes the
    /// result even when no output generation advanced.
    RemoteScanReady,
    ReloadConfig,
    VideoPreviewReady {
        window_seq: u64,
        pane_id: u64,
        generation: u64,
        candidate: Option<crate::video_preview::VideoPasteCandidate>,
        preview: Option<kettle_core::ImageData>,
    },
    NativeFullscreenExited {
        window_seq: u64,
        generation: u64,
    },
    /// An assistive-technology action addressed to a specific OS window.
    /// AccessKit can invoke this callback off the winit dispatch path, so it is
    /// re-serialized through the event-loop proxy before touching UI state.
    AccessibilityAction {
        window_seq: u64,
        request: ActionRequest,
    },
    /// A compatible bare Kettle launch asked this primary process to open a
    /// fresh OS window. The bounded inbox carries the request and completion.
    Activation,
    /// Remote control: the remote-command file changed and
    /// the watcher needs the main thread to read + process new lines.
    /// One event per change (notify coalesces consecutive writes), so
    /// the main thread can batch-read all pending lines at once.
    RemoteCommand,
    /// The control server enqueued a message
    /// (new connection / request / disconnect). The main thread drains the
    /// server channel and dispatches each request against `ws.mux`.
    Ctl,
    /// The media lane finished a `show` render; publish it and start the
    /// next.
    MediaRendered,
    /// A lane's video playback has something new: a frame, or a change of
    /// state. Coalesced by the session until the lane looks.
    LanePlayback,
    /// The background update-check thread found a newer GitHub
    /// release. Carries the tag (e.g. `v2.6.0`) + the release-page URL so the
    /// UI can show a passive bottom banner. The banner is mouse-driven
    /// (left-click opens the release page + dismisses, right-click dismisses);
    /// keyboard users can bind the `open_update` / `dismiss_update` actions —
    /// it stays non-modal so it never steals the terminal's keys.
    UpdateAvailable {
        tag: String,
        url: String,
    },
    /// An automatic update completed. Existing windows keep running the
    /// current image; the next kettle launch uses the installed release.
    /// `first_time` is set on the first automatic install so the UI can show a
    /// one-time "auto-update is on; disable with `update-policy = off`" note.
    UpdateInstalled {
        tag: String,
        staged: bool,
        first_time: bool,
    },
    /// An automatic update failed after a newer signed release was found.
    UpdateFailed {
        message: String,
    },
    /// The recurring in-session update timer fired; re-run the due check with
    /// the current config so a long-lived window keeps itself current.
    UpdateCheckTick,
    /// A row in the macOS Dock context menu was chosen. AppKit delivers that on
    /// the main thread but outside winit's dispatch, with no `ActiveEventLoop`
    /// and no `&mut App`, so it is re-serialized through the event-loop proxy
    /// exactly as `AccessibilityAction` is.
    #[cfg(target_os = "macos")]
    DockCommand(crate::macos_dock::DockCommand),
}

/// Decode kettle's embedded 256px PNG (the dark or light variant) into the
/// *running* window's icon: the title-bar system-menu glyph (top-left), the
/// taskbar button, and the Alt-Tab thumbnail. winit leaves this icon unset by
/// default. `build.rs` embeds the same art as an `.exe` resource, but that
/// covers only Explorer, the file glyph and pinned shortcuts, not the live
/// window's `WM_SETICON`. Without this, Windows shows a generic placeholder.
/// The OS downscales the source for the small title-bar icon and picks the
/// right size for the taskbar and switcher. Best-effort: a decode failure
/// leaves the icon unset rather than aborting startup. No-op on Wayland (uses
/// the `.desktop` app_id); effective on Windows and X11.
///
/// macOS returns `None` without decoding. An AppKit window has no icon of its
/// own (the Dock and the app switcher use the bundle's), and winit's macOS
/// backend drops whatever it is given, at creation and in `set_window_icon`,
/// so the decode would only delay the first window.
fn load_window_icon(dark: bool) -> Option<winit::window::Icon> {
    #[cfg(target_os = "macos")]
    {
        let _ = dark;
        None
    }
    #[cfg(not(target_os = "macos"))]
    {
        const DARK_ICON_PNG: &[u8] = include_bytes!("../../../packaging/linux/kettle-256.png");
        const LIGHT_ICON_PNG: &[u8] =
            include_bytes!("../../../packaging/linux/kettle-light-256.png");
        let icon_png = if dark { DARK_ICON_PNG } else { LIGHT_ICON_PNG };
        let img = image::load_from_memory(icon_png).ok()?.into_rgba8();
        let (w, h) = img.dimensions();
        winit::window::Icon::from_rgba(img.into_raw(), w, h).ok()
    }
}

/// macOS `sticky = true` — make the window appear on every Space
/// (Mission Control workspace). winit 0.30 dropped the native method, so we
/// reach the underlying `NSWindow` through the raw AppKit handle and set its
/// collection behavior — exactly what `set_visible_on_all_workspaces` did. The
/// objc2 / objc2-app-kit versions are pinned to winit's own (0.5 / 0.2) so the
/// ObjC class layout matches. Best-effort: a missing handle just leaves the
/// window on its current Space.
#[cfg(target_os = "macos")]
fn set_visible_on_all_spaces(window: &winit::window::Window) {
    use objc2_app_kit::{NSView, NSWindowCollectionBehavior};
    // winit re-exports raw-window-handle, so we don't need it as a direct dep.
    use winit::raw_window_handle::{HasWindowHandle, RawWindowHandle};

    let Ok(handle) = window.window_handle() else {
        return;
    };
    let RawWindowHandle::AppKit(appkit) = handle.as_raw() else {
        return;
    };
    // SAFETY: on macOS winit hands us a live `NSView*`, and `resumed` runs on
    // the main thread where AppKit requires UI mutations. We only borrow it.
    let view: &NSView = unsafe { &*appkit.ns_view.as_ptr().cast::<NSView>() };
    if let Some(ns_window) = view.window() {
        // SAFETY: `setCollectionBehavior:` is an objc2 `unsafe fn` (any ObjC
        // message send is). The behavior bits are valid and the window is live.
        unsafe {
            ns_window.setCollectionBehavior(
                NSWindowCollectionBehavior::CanJoinAllSpaces
                    | NSWindowCollectionBehavior::Stationary,
            );
        }
    }
}

/// Turn off AppKit's persistent UI ("Resume") before the application
/// launches. Kettle restores its own session, and AppKit cannot rebuild a
/// winit window anyway. Left on, a bundled Kettle kept encoding its window
/// state for the persistent-UI service while idle: 0.04 % CPU and 0.2 extra
/// wakeups a second. `ApplePersistence` goes in the registration domain,
/// which lives only in memory and loses to anything the user sets.
#[cfg(target_os = "macos")]
fn disable_app_state_restoration() {
    use objc2::rc::Retained;
    use objc2_foundation::{NSDictionary, NSNumber, NSString, NSUserDefaults};

    let key = NSString::from_str("ApplePersistence");
    let off = Retained::into_super(Retained::into_super(Retained::into_super(
        NSNumber::numberWithBool(false),
    )));
    let defaults = NSDictionary::from_vec(&[&*key], vec![off]);
    // SAFETY: `registerDefaults:` copies a property-list dictionary of
    // NSString keys, and this runs on the main thread before AppKit starts.
    unsafe { NSUserDefaults::standardUserDefaults().registerDefaults(&defaults) };
}

fn rect_contains(rect: kettle_render::Rect4, x: f32, y: f32) -> bool {
    x >= rect.0 && x < rect.0 + rect.2 && y >= rect.1 && y < rect.1 + rect.3
}

fn rounded_window_corner_policy(
    is_macos: bool,
    live_decorated: bool,
    live_fullscreen: bool,
) -> bool {
    is_macos && live_decorated && !live_fullscreen
}

fn rect_json(rect: kettle_render::Rect4) -> serde_json::Value {
    serde_json::json!({
        "x": rect.0,
        "y": rect.1,
        "width": rect.2,
        "height": rect.3,
    })
}

fn ctl_mouse_button(params: &serde_json::Value) -> std::result::Result<u8, String> {
    let button = params
        .get("button")
        .and_then(|v| v.as_str())
        .unwrap_or("left")
        .to_ascii_lowercase();
    match button.as_str() {
        "left" => Ok(0),
        "middle" => Ok(1),
        "right" => Ok(2),
        // The report codes the physical buttons send, not xterm's button
        // numbers: 8 and 9 would encode as a modified left or middle press.
        "back" => Ok(MOUSE_BACK),
        "forward" => Ok(MOUSE_FORWARD),
        other => Err(format!(
            "unknown button '{other}' (expected left, middle, right, back, or forward)"
        )),
    }
}

/// Terminator parity (`terminal.py:real_copy_clipboard` +
/// `config.py:smart_copy`): what `Action::Copy` writes to the clipboard.
///
///   * `selection`: the selected text, or `None` when the pane has none.
///   * `smart_copy`: `cfg.smart_copy`. With no selection, `true` (default)
///     keeps the existing clipboard and `false` clobbers it with an empty
///     string (Terminator's deliberate-UX-choice mode).
///
/// Returns the text to write, or `None` to leave the clipboard untouched.
/// On the `Some("")` clobber path the caller writes the empty string but does
/// not count it as a real copy, so the `clear_select_on_copy` follow-up is
/// skipped (no selection existed to clear). Pure; unit-testable without a
/// clipboard fixture.
fn copy_clipboard_decision(
    selection: Option<String>,
    smart_copy: bool,
) -> Result<Option<String>, std::collections::TryReserveError> {
    match (selection, smart_copy) {
        (Some(s), _) => kettle_core::scrub_card_markers(s).map(Some),
        (None, false) => Ok(Some(String::new())),
        (None, true) => Ok(None),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PasteSource {
    Clipboard,
    Primary,
}

/// Terminator parity for `putty_paste_style_source_clipboard`: right-click
/// PuTTY paste defaults to the PRIMARY selection on Linux, matching terminal
/// mouse-paste convention. Users who expect Windows/PuTTY-style clipboard
/// paste can opt into the regular clipboard source.
fn putty_paste_source(source_clipboard: bool) -> PasteSource {
    if source_clipboard {
        PasteSource::Clipboard
    } else {
        PasteSource::Primary
    }
}

/// Terminator parity (`key_zoom_in` / `key_zoom_out` via
/// Ctrl+wheel): pure decision for whether the wheel notch should resize
/// the font.
///
///   * `ctrl` — Ctrl modifier held (the canonical zoom modifier across
///     gnome-terminal, Terminator, xterm-via-ctrl-shift-plus, etc.).
///   * `notches` — whole detents drained from `WheelAccum`; sign drives
///     the zoom direction, zero short-circuits. Deliberately detents and
///     not scaled lines: one physical notch must be one font step
///     regardless of `scroll-multiplier`, and a sub-detent touchpad event
///     must not zoom at all.
///   * `disabled` — `cfg.disable_mousewheel_zoom`. Opt-out for users
///     who scroll-zoom by accident (laptop touchpads + a Ctrl-meta
///     remap is a common collision).
///
/// Returns `Some(+1)` to grow, `Some(-1)` to shrink, `None` for no-op.
/// Extracted as a pure helper so the policy is unit-testable without
/// constructing a full App + winit event loop.
fn should_zoom_font(ctrl: bool, notches: i32, disabled: bool) -> Option<i32> {
    if !ctrl || disabled || notches == 0 {
        None
    } else if notches > 0 {
        Some(1)
    } else {
        Some(-1)
    }
}

/// Terminator parity (`plugins/auto_theme.py`):
/// pick the theme to switch to on `Action::ToggleLightDark`.
///
/// Rules (case-insensitive):
///   - both `light` and `dark` set:
///       - current matches `dark`  → return `light`
///       - current matches `light` → return `dark`
///       - otherwise               → return `dark` (default landing)
///   - only one set: return that one (so a half-configured user
///     still gets a one-way switch).
///   - neither set: return `None`; dispatch logs a warn.
///
/// Pure — unit-testable without constructing a Config or App.
/// Bridge from kettle-config's `SearchCaseSensitivity`
/// to kettle-core's `CaseSensitivity`. Kept as a pure helper so
/// the two crates don't grow a circular trait dependency.
fn map_case_sensitivity(m: kettle_config::SearchCaseSensitivity) -> kettle_core::CaseSensitivity {
    match m {
        kettle_config::SearchCaseSensitivity::Smart => kettle_core::CaseSensitivity::Smart,
        kettle_config::SearchCaseSensitivity::Always => kettle_core::CaseSensitivity::Always,
        kettle_config::SearchCaseSensitivity::Never => kettle_core::CaseSensitivity::Never,
    }
}

fn search_compile_error_status(
    error: kettle_core::SearchCompileError,
) -> kettle_render::SearchStatus {
    match error {
        kettle_core::SearchCompileError::QueryTooLong { .. } => {
            kettle_render::SearchStatus::TooLong
        }
        kettle_core::SearchCompileError::InvalidRegex => kettle_render::SearchStatus::Invalid,
        kettle_core::SearchCompileError::PatternTooComplex => {
            kettle_render::SearchStatus::TooComplex
        }
    }
}

fn map_search_case_mode(
    mode: kettle_config::SearchCaseSensitivity,
) -> kettle_render::SearchCaseMode {
    match mode {
        kettle_config::SearchCaseSensitivity::Smart => kettle_render::SearchCaseMode::Smart,
        kettle_config::SearchCaseSensitivity::Always => kettle_render::SearchCaseMode::Match,
        kettle_config::SearchCaseSensitivity::Never => kettle_render::SearchCaseMode::Ignore,
    }
}

fn effective_search_status(
    search: &crate::search_input::SearchState,
) -> kettle_render::SearchStatus {
    if search.visible_truncated
        && matches!(
            search.status,
            kettle_render::SearchStatus::Match | kettle_render::SearchStatus::Wrapped
        )
    {
        kettle_render::SearchStatus::Limited
    } else {
        search.status
    }
}

/// The status the bar paints. Automation reads `effective_search_status`,
/// which reports `Searching` at once; the bar waits until a scan is actually
/// slow (see `SearchState::searching_label_at`).
fn displayed_search_status(
    search: &crate::search_input::SearchState,
    now: std::time::Instant,
) -> kettle_render::SearchStatus {
    search.painted_status(effective_search_status(search), now)
}

fn should_start_nearby_search(search: &crate::search_input::SearchState) -> bool {
    search.typing_scanned_revision != Some(search.revision)
        && !search.quiet_retry_pending
        && search.background.is_none()
}

/// Synchronize a live Search surface after a global config reload.
///
/// Returns true when the scan direction changed and the caller must derive a fresh viewport
/// anchor after resize. Closed windows consume these values the next time Search opens.
fn sync_reloaded_search_preferences(
    search: &mut crate::search_input::SearchState,
    wrap: bool,
    case_mode: kettle_config::SearchCaseSensitivity,
    invert: bool,
    now: std::time::Instant,
) -> bool {
    if !search.open {
        return false;
    }
    let wrap_changed = search.wrap != wrap;
    let case_changed = search.case_mode != case_mode;
    let direction_changed = search.invert != invert;
    search.wrap = wrap;
    search.case_mode = case_mode;
    search.invert = invert;

    if case_changed {
        search.note_edit(now);
    } else if wrap_changed || direction_changed {
        search.restart_navigation(now);
    }
    direction_changed
}

fn search_viewport_anchor(
    display_offset: usize,
    screen_lines: usize,
    last_column: usize,
    direction: kettle_core::SearchDirection,
) -> kettle_core::SearchPoint {
    let offset = i32::try_from(display_offset).unwrap_or(i32::MAX);
    match direction {
        kettle_core::SearchDirection::Forward => kettle_core::SearchPoint::new(-offset, 0),
        kettle_core::SearchDirection::Reverse => kettle_core::SearchPoint::new(
            i32::try_from(screen_lines.saturating_sub(1))
                .unwrap_or(i32::MAX)
                .saturating_sub(offset),
            last_column,
        ),
    }
}

/// Wrapping changes only where the next step goes, so the match on screen
/// stays, and a step status that described the old setting (`End reached`,
/// `Wrapped`) is cleared. With no match, search again, so turning wrap on
/// after a typing `No match` finds one past the end.
fn search_wrap_toggled(search: &mut crate::search_input::SearchState, now: std::time::Instant) {
    // A step that has already wrapped past the end would land on a match the
    // user just asked not to reach. Stop it at the edge instead, with the
    // status the step would have ended on without wrap.
    if !search.wrap
        && let Some(job) = search
            .background
            .take_if(|job| job.navigation && job.wrapped)
    {
        let unwrapped = crate::search_input::BackgroundSearch {
            wrapped: false,
            ..job
        };
        let (status, retry_at) = finished_background_search(&unwrapped, now);
        search.status = status;
        search.unlimited_retry_at = retry_at;
        return;
    }
    if search.focused.is_none() {
        search.restart_navigation(now);
    } else if matches!(
        search.status,
        kettle_render::SearchStatus::Start
            | kettle_render::SearchStatus::End
            | kettle_render::SearchStatus::Wrapped
    ) {
        search.status = kettle_render::SearchStatus::Match;
    }
}

/// Where a search restarted by a toggle begins. The match on screen, from its
/// start (its end when `invert`), so a search that still finds it keeps it.
/// A match scrolled out of `viewport` (display offset, screen lines, last
/// column) is not where the user is looking, so the search starts from the
/// viewport's edge in the current direction instead.
fn search_anchor_for(
    focused: Option<kettle_core::SearchSpan>,
    invert: bool,
    viewport: Option<(usize, usize, usize)>,
) -> Option<kettle_core::SearchPoint> {
    let on_screen = |span: &kettle_core::SearchSpan| {
        viewport.is_none_or(|(display_offset, screen_lines, _)| {
            let top = -i32::try_from(display_offset).unwrap_or(i32::MAX);
            let bottom = top.saturating_add(i32::try_from(screen_lines).unwrap_or(i32::MAX)) - 1;
            span.end.line >= top && span.start.line <= bottom
        })
    };
    if let Some(span) = focused.filter(on_screen) {
        return Some(if invert { span.end } else { span.start });
    }
    let direction = if invert {
        kettle_core::SearchDirection::Reverse
    } else {
        kettle_core::SearchDirection::Forward
    };
    viewport.map(|(display_offset, screen_lines, last_column)| {
        search_viewport_anchor(display_offset, screen_lines, last_column, direction)
    })
}

fn search_point_after(
    point: kettle_core::SearchPoint,
    direction: kettle_core::SearchDirection,
    top_line: i32,
    bottom_line: i32,
    last_column: usize,
) -> Option<kettle_core::SearchPoint> {
    match direction {
        kettle_core::SearchDirection::Forward if point.column < last_column => {
            Some(kettle_core::SearchPoint::new(point.line, point.column + 1))
        }
        kettle_core::SearchDirection::Forward if point.line < bottom_line => {
            Some(kettle_core::SearchPoint::new(point.line + 1, 0))
        }
        kettle_core::SearchDirection::Reverse if point.column > 0 => {
            Some(kettle_core::SearchPoint::new(point.line, point.column - 1))
        }
        kettle_core::SearchDirection::Reverse if point.line > top_line => {
            Some(kettle_core::SearchPoint::new(point.line - 1, last_column))
        }
        _ => None,
    }
}

fn clamp_search_point(
    point: kettle_core::SearchPoint,
    top_line: i32,
    bottom_line: i32,
    last_column: usize,
) -> kettle_core::SearchPoint {
    kettle_core::SearchPoint::new(
        point.line.clamp(top_line, bottom_line),
        point.column.min(last_column),
    )
}

fn continue_background_after_output(
    job: &mut crate::search_input::BackgroundSearch,
    token: kettle_core::SearchScanToken,
    top_line: i32,
    bottom_line: i32,
    last_column: usize,
) {
    job.token = token;
    job.output_drifted = true;
    job.cursor = clamp_search_point(job.cursor, top_line, bottom_line, last_column);
    job.wrap_anchor = clamp_search_point(job.wrap_anchor, top_line, bottom_line, last_column);
    job.edge = if job.wrapped {
        clamp_search_point(job.edge, top_line, bottom_line, last_column)
    } else {
        match job.direction {
            kettle_core::SearchDirection::Forward => {
                kettle_core::SearchPoint::new(bottom_line, last_column)
            }
            kettle_core::SearchDirection::Reverse => kettle_core::SearchPoint::new(top_line, 0),
        }
    };
}

fn bounded_search_edge(
    origin: kettle_core::SearchPoint,
    direction: kettle_core::SearchDirection,
    top_line: i32,
    bottom_line: i32,
    last_column: usize,
    max_lines: usize,
) -> kettle_core::SearchPoint {
    let lines = i32::try_from(max_lines).unwrap_or(i32::MAX);
    match direction {
        kettle_core::SearchDirection::Forward => kettle_core::SearchPoint::new(
            origin.line.saturating_add(lines).min(bottom_line),
            last_column,
        ),
        kettle_core::SearchDirection::Reverse => {
            kettle_core::SearchPoint::new(origin.line.saturating_sub(lines).max(top_line), 0)
        }
    }
}

fn wrapped_background_search(
    token: kettle_core::SearchScanToken,
    direction: kettle_core::SearchDirection,
    anchor: kettle_core::SearchPoint,
    grid_bounds: (i32, i32, usize),
    navigation: bool,
    had_focus: bool,
    output_drifted: bool,
) -> Option<crate::search_input::BackgroundSearch> {
    let (top_line, bottom_line, last_column) = grid_bounds;
    let (cursor, edge) = match direction {
        kettle_core::SearchDirection::Forward => (
            kettle_core::SearchPoint::new(top_line, 0),
            search_point_after(
                anchor,
                kettle_core::SearchDirection::Reverse,
                top_line,
                bottom_line,
                last_column,
            )?,
        ),
        kettle_core::SearchDirection::Reverse => (
            kettle_core::SearchPoint::new(bottom_line, last_column),
            search_point_after(
                anchor,
                kettle_core::SearchDirection::Forward,
                top_line,
                bottom_line,
                last_column,
            )?,
        ),
    };
    let ordered = match direction {
        kettle_core::SearchDirection::Forward => cursor <= edge,
        kettle_core::SearchDirection::Reverse => cursor >= edge,
    };
    ordered.then_some(crate::search_input::BackgroundSearch {
        token,
        direction,
        cursor,
        edge,
        wrap_anchor: anchor,
        wrapped: true,
        nearby: false,
        navigation,
        had_focus,
        output_drifted,
    })
}

fn exhausted_search_status(
    job: &crate::search_input::BackgroundSearch,
) -> kettle_render::SearchStatus {
    if job.navigation && job.had_focus && !job.wrapped {
        match job.direction {
            kettle_core::SearchDirection::Forward => kettle_render::SearchStatus::End,
            kettle_core::SearchDirection::Reverse => kettle_render::SearchStatus::Start,
        }
    } else {
        kettle_render::SearchStatus::NoMatch
    }
}

fn should_retry_output_drift(job: &crate::search_input::BackgroundSearch) -> bool {
    job.output_drifted && !job.navigation
}

fn prepare_initial_search_retry_after_output(
    search: &mut crate::search_input::SearchState,
    job: &crate::search_input::BackgroundSearch,
    anchor: kettle_core::SearchPoint,
) -> bool {
    if !should_retry_output_drift(job) {
        return false;
    }
    search.anchor = Some(anchor);
    search.quiet_retry_pending = true;
    true
}

fn activate_quiet_search_retry(search: &mut crate::search_input::SearchState) -> bool {
    if !search.quiet_retry_pending {
        return false;
    }
    search.quiet_retry_pending = false;
    search.typing_scanned_revision = None;
    // The nearby scan runs first. If it misses, the full scan follows on the
    // next turn instead of leaving the search at `Searching` with nothing
    // scheduled.
    search.unlimited_retry_at = Some(std::time::Instant::now());
    search.set_status_at(
        kettle_render::SearchStatus::Searching,
        std::time::Instant::now(),
    );
    true
}

fn cancel_deferred_search_retry(search: &mut crate::search_input::SearchState) {
    search.quiet_retry_pending = false;
    search.unlimited_retry_at = None;
}

fn finished_background_search(
    job: &crate::search_input::BackgroundSearch,
    now: std::time::Instant,
) -> (kettle_render::SearchStatus, Option<std::time::Instant>) {
    if job.output_drifted && !should_retry_output_drift(job) {
        // Output destroyed the stable ordering required by an explicit Previous/Next request.
        // Re-running the default-direction typing search would verify a different operation, so
        // keep the honest bounded result and let the user's next navigation start a fresh job.
        (kettle_render::SearchStatus::Limited, None)
    } else if should_retry_output_drift(job) {
        // The retained cursor guarantees progress under a continuously-writing PTY, but rows may
        // have shifted between chunks. Never turn that best-effort pass into a definitive miss;
        // once output is quiet, restart the initial search from a fresh viewport anchor.
        (
            kettle_render::SearchStatus::Searching,
            Some(now + std::time::Duration::from_millis(500)),
        )
    } else {
        (exhausted_search_status(job), None)
    }
}

/// Terminator parity (`plugins/run_cmd_on_match.py`):
/// fire the configured argv as a fire-and-forget subprocess.
///
/// Security posture:
///   - argv form (no shell). The configured command is treated as
///     data, not as a shell string — kettle never invokes `sh -c`
///     on it. A configured `trigger = .* :: rm -rf $HOME` would
///     spawn `rm -rf $HOME` *literally*, with `$HOME` as a literal
///     argv element, not as the user's home dir.
///   - empty argv ⇒ no-op (parser already rejects, but be safe).
///   - spawn errors logged but otherwise ignored so a missing
///     binary doesn't loop-fail.
///
/// Stripped into a free fn so the dispatch arm stays small.
fn spawn_trigger_command(argv: &[String]) {
    if argv.is_empty() {
        return;
    }
    static ACTIVE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    let Some(slot) = TriggerCommandSlot::acquire(&ACTIVE) else {
        log::warn!("trigger run-command skipped: too many running commands");
        return;
    };
    let mut cmd = std::process::Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    // Don't capture stdout/stderr; the child inherits kettle's
    // file descriptors (where applicable). On Unix this means
    // stdout goes to wherever kettle was launched from — which
    // is acceptable for a user-configured fire-and-forget hook.
    if let Err(error) = std::thread::Builder::new()
        .name("kettle-trigger".into())
        .spawn(move || {
            let _slot = slot;
            if let Err(error) = cmd.spawn().and_then(|mut child| child.wait()) {
                log::warn!("trigger run-command spawn/wait failed: {error}");
            }
        })
    {
        log::warn!("trigger run-command reaper failed to start: {error}");
    }
}

struct TriggerCommandSlot<'a>(&'a std::sync::atomic::AtomicUsize);

impl<'a> TriggerCommandSlot<'a> {
    fn acquire(active: &'a std::sync::atomic::AtomicUsize) -> Option<Self> {
        use std::sync::atomic::Ordering::Relaxed;

        // Rust 1.99 renames fetch_update to try_update; the MSRV (1.95) predates it.
        #[allow(deprecated)]
        let acquired =
            active.fetch_update(Relaxed, Relaxed, |count| (count < 32).then_some(count + 1));
        acquired.ok().map(|_| Self(active))
    }
}

impl Drop for TriggerCommandSlot<'_> {
    fn drop(&mut self) {
        self.0.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
    }
}

/// Phase 4 of [`TERMINATOR-CONFIRM-DIALOG-DESIGN.md`](
/// ../../../docs/TERMINATOR-CONFIRM-DIALOG-DESIGN.md): which named
/// key was pressed in the confirm-modal keyboard handler. Lifted out
/// of winit's `NamedKey` so the pure helper isn't coupled to a UI
/// framework type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfirmKey {
    Escape,
    Enter,
    Tab,
    ShiftTab,
    Left,
    Right,
    /// `y` (with `vim-menu-nav`): answer the dialog's QUESTION with yes,
    /// regardless of which button is focused.
    Yes,
    /// `n` (with `vim-menu-nav`): dismiss without dispatching.
    No,
}

/// Outcome of a key press in the confirm dialog.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfirmKeyResult {
    /// Update `focus_idx` to the new value + redraw.
    Move(usize),
    /// Dispatch `on_confirm` + close the modal.
    Confirm,
    /// Close the modal without dispatching.
    Cancel,
    /// Key wasn't a nav key for the modal — caller can pass through
    /// or ignore (we suppress non-nav input while a modal is open).
    Ignore,
}

/// The group name Terminator's `group_all` uses (`window.py:936`, `_('All')`).
///
/// A named constant so the importer, the dispatch, and any future "is
/// everything grouped?" check cannot disagree about the spelling — the name is
/// user-visible in the titlebar pill.
fn kettle_ui_group_all_name() -> &'static str {
    "All"
}

/// How much a close of the tab at `idx` would take: `(panes, busy)`.
///
/// `busy` counts only panes that are NOT sitting idle at an integrated-shell
/// prompt — an idle prompt has no work to lose. A pane with no shell
/// integration cannot prove it is idle, so it reports busy and the prompt
/// still fires; the same goes for a missing tab, where prompting is the
/// conservative answer.
fn tab_close_scope(ws: &WindowState, idx: usize) -> (usize, usize) {
    let Some(tab) = ws.mux.tabs.get(idx) else {
        return (1, 1);
    };
    let ids = tab.root.leaf_ids();
    let busy = ids
        .iter()
        .filter(|id| {
            ws.mux
                .panes
                .get(id)
                .map(|p| !p.term.shell_idle())
                .unwrap_or(true)
        })
        .count();
    (ids.len(), busy)
}

/// How much closing this whole window would take: `(panes, busy)` across
/// every tab. Same idle rule as [`tab_close_scope`].
fn window_close_scope(ws: &WindowState) -> (usize, usize) {
    (
        ws.mux.panes.len(),
        ws.mux
            .panes
            .values()
            .filter(|p| !p.term.shell_idle())
            .count(),
    )
}

/// Pure helper that maps a (current_focus, num_buttons,
/// key) tuple to the next action for the confirm-dialog state
/// machine, wired to the App's winit key handler.
fn confirm_dialog_keypress(
    current_focus: usize,
    num_buttons: usize,
    key: ConfirmKey,
) -> ConfirmKeyResult {
    if num_buttons == 0 {
        return ConfirmKeyResult::Cancel;
    }
    match key {
        ConfirmKey::Escape => ConfirmKeyResult::Cancel,
        // Enter activates the FOCUSED button, not always Confirm. The
        // close-confirm dialogs open focused on `Cancel` (index 0, the safe
        // default the renderer highlights), so firing the destructive action
        // regardless of focus would contradict that highlight and risk data
        // loss. Buttons are `[Cancel, Confirm]`, so only the last button
        // confirms; any other focused button (Cancel) cancels.
        ConfirmKey::Enter => {
            if current_focus + 1 == num_buttons {
                ConfirmKeyResult::Confirm
            } else {
                ConfirmKeyResult::Cancel
            }
        }
        ConfirmKey::Tab => ConfirmKeyResult::Move((current_focus + 1) % num_buttons),
        ConfirmKey::ShiftTab => {
            ConfirmKeyResult::Move((current_focus + num_buttons - 1) % num_buttons)
        }
        ConfirmKey::Left => {
            if current_focus == 0 {
                ConfirmKeyResult::Ignore
            } else {
                ConfirmKeyResult::Move(current_focus - 1)
            }
        }
        ConfirmKey::Right => {
            if current_focus + 1 >= num_buttons {
                ConfirmKeyResult::Ignore
            } else {
                ConfirmKeyResult::Move(current_focus + 1)
            }
        }
        // `y`/`n` (`vim-menu-nav`) answer the dialog directly. Unlike Enter,
        // which fires the FOCUSED button, `y` is an explicit answer to the
        // question, so focus is irrelevant.
        ConfirmKey::Yes => ConfirmKeyResult::Confirm,
        ConfirmKey::No => ConfirmKeyResult::Cancel,
    }
}

/// Phase 3 of [`TERMINATOR-VERTICAL-TABS-DESIGN.md`](
/// ../../../docs/TERMINATOR-VERTICAL-TABS-DESIGN.md): default
/// strip width for vertical (Left / Right) tab bars when the
/// config doesn't supply one. The `cfg.tab_bar_width`
/// config key supersedes this in production; this constant is
/// the documented Firefox-sidebar-style fallback (180 px) the
/// unit-tested layout helpers use when
/// invoked without an app-level cfg handle.
#[allow(dead_code)] // doc-only reference + layout-helper test fixture; production uses cfg.tab_bar_width
pub const VERTICAL_TAB_STRIP_W: f32 = 180.0;

/// The tab bar's band: where it draws and where a dragged tab docks. A bottom
/// bar sits above the search bar and a bottom status bar, and a side strip
/// stops above the search bar, so the docking target matches what is painted.
fn tab_band_rect(
    surface: (u32, u32),
    pos: TabBarPos,
    height: f32,
    strip_width: f32,
    search_height: f32,
    bottom_status_height: f32,
) -> Rect {
    let (sw, sh) = (surface.0 as f32, surface.1 as f32);
    match pos {
        TabBarPos::Top => (0.0, 0.0, sw, height),
        TabBarPos::Bottom => (
            0.0,
            sh - search_height - bottom_status_height - height,
            sw,
            height,
        ),
        TabBarPos::Left => (0.0, 0.0, strip_width, sh - search_height),
        TabBarPos::Right => (sw - strip_width, 0.0, strip_width, sh - search_height),
    }
}

/// Pure helper that computes the pane-content rect from the surface size, bar
/// metrics, and the edge each bar occupies.
///
/// Returns `(x, y, width, height)` in pixel coordinates.
///
/// A `TabBarPos::Left` or `Right` strip claims a per-side width slice
/// (`VERTICAL_TAB_STRIP_W`, 180 px) rather than a per-edge height.
///
/// Pure (no `&self`, renderer, or winit) so the layout math can be unit-tested
/// without constructing a full App. `App::area` calls
/// [`content_rect_for_with_strip`] directly with the configured strip width.
#[allow(dead_code)]
// production callers use content_rect_for_with_strip; this wrapper drives the layout-math drift guards (app.rs:9411+)
fn content_rect_for(
    surface: (u32, u32),
    tab_bar_h: f32,
    status_bar_h: f32,
    tab_bar_pos: kettle_config::TabBarPos,
    status_bar_mode: kettle_config::StatusBarMode,
) -> Rect {
    content_rect_for_with_strip(
        surface,
        ContentBands {
            tab_bar_h,
            status_bar_h,
            ..ContentBands::default()
        },
        tab_bar_pos,
        status_bar_mode,
        VERTICAL_TAB_STRIP_W,
    )
}

/// Horizontal chrome bands that reduce the pane-content area.
#[derive(Clone, Copy, Default)]
struct ContentBands {
    tab_bar_h: f32,
    status_bar_h: f32,
    update_banner_h: f32,
    vertical_title_edit_h: f32,
}

/// Explicit strip-width variant, so callers with `cfg.tab_bar_width` in scope
/// can pass it through. The non-`_with_strip` wrapper above keeps the same
/// signature for code paths without a Config.
fn content_rect_for_with_strip(
    surface: (u32, u32),
    bands: ContentBands,
    tab_bar_pos: kettle_config::TabBarPos,
    status_bar_mode: kettle_config::StatusBarMode,
    strip_w: f32,
) -> Rect {
    let (sw, sh) = (surface.0 as f32, surface.1 as f32);
    let tb_on_top = matches!(tab_bar_pos, kettle_config::TabBarPos::Top);
    let tb_on_bottom = matches!(tab_bar_pos, kettle_config::TabBarPos::Bottom);
    let tb_on_left = matches!(tab_bar_pos, kettle_config::TabBarPos::Left);
    let tb_on_right = matches!(tab_bar_pos, kettle_config::TabBarPos::Right);
    let sb_on_top = matches!(status_bar_mode, kettle_config::StatusBarMode::Top);
    let sb_on_bottom = matches!(status_bar_mode, kettle_config::StatusBarMode::Bottom);

    // Vertical: status bar and title editing claim y-bands (status is always
    // horizontal in v1); the persistent tab strip claims only an x-band.
    let top_offset = (if tb_on_top { bands.tab_bar_h } else { 0.0 })
        + (if sb_on_top { bands.status_bar_h } else { 0.0 })
        + (if tb_on_left || tb_on_right {
            bands.vertical_title_edit_h.max(0.0)
        } else {
            0.0
        });
    let bot_offset = (if tb_on_bottom { bands.tab_bar_h } else { 0.0 })
        + (if sb_on_bottom {
            bands.status_bar_h
        } else {
            0.0
        })
        + bands.update_banner_h.max(0.0);
    let left_offset = if tb_on_left { strip_w } else { 0.0 };
    let right_offset = if tb_on_right { strip_w } else { 0.0 };
    let content_h = (sh - top_offset - bot_offset).max(1.0);
    let content_w = (sw - left_offset - right_offset).max(1.0);
    (left_offset, top_offset, content_w, content_h)
}

/// Build the per-pane screenshot path ([`TERMINATOR-TERMINALSHOT-DESIGN.md`](
/// ../../../docs/TERMINATOR-TERMINALSHOT-DESIGN.md)). Lives under
/// `<cache>/kettle/shots/` (mirrors the `session_log_path` scheme below); falls
/// back to `./kettle-shots/` when no cache dir resolves.
///
/// File name shape: `kettle-<unix-secs>-<pid>.png`. `Action::TakeScreenshot`
/// and a ctl `screenshot` request without a `path` capture to it.
///
/// Pure modulo `unix_secs` + `cache_dir` — caller pins both.
fn session_screenshot_path(
    unix_secs: u64,
    pid: u32,
    cache_dir: Option<&std::path::Path>,
) -> std::path::PathBuf {
    let dir = cache_dir
        .map(|p| p.to_path_buf().join("kettle").join("shots"))
        .unwrap_or_else(|| std::path::PathBuf::from("kettle-shots"));
    dir.join(format!("kettle-{unix_secs}-{pid}.png"))
}

/// Validate a caller-supplied `screenshot` destination. `path` reaches here
/// verbatim from the ctl `screenshot` method and the `kettle_screenshot` MCP
/// tool built on it, both reachable by an agent whose instructions can be
/// steered by prompt-injected terminal content. Writing to an existing sensitive
/// file (`~/.bashrc`, `~/.ssh/authorized_keys`, a Windows Startup-folder item)
/// or through a symlink planted ahead of time would make this a silent
/// arbitrary-file-overwrite primitive.
///
/// `std::fs::symlink_metadata` (NOT `Path::exists`, which follows symlinks and
/// would miss a dangling one) detects ANY existing entry at the destination
/// (file, directory, or symlink) without following it, so a pre-planted symlink
/// is caught even when its target doesn't exist yet. Requiring a brand-new
/// destination is the same never-follow-an-existing-path discipline used
/// elsewhere in this codebase (`kettle_state::atomic_replace`, the recorder).
/// The cost is that a second capture to the same `path` fails instead of
/// clobbering the first. This probe is an up-front fast-fail; the renderer's
/// create-new publish is the security boundary.
///
/// Pure (no filesystem writes, only a metadata probe), so it is unit-testable
/// against a real temp directory.
fn validate_screenshot_path(s: &str) -> Result<std::path::PathBuf, &'static str> {
    if s.trim().is_empty() {
        return Err("'path' is empty");
    }
    let path = std::path::PathBuf::from(s);
    if std::fs::symlink_metadata(&path).is_ok() {
        return Err(
            "'path' already exists — refusing to overwrite an existing file or follow an \
             existing symlink; choose a new destination",
        );
    }
    Ok(path)
}

/// Terminator parity (`plugins/logger.py`): build the
/// per-pane session-log path. Lives under `<cache>/kettle/logs/`
/// (XDG-respecting via env probe; falls back to `./kettle-logs/`
/// when no cache dir is available).
///
/// File name shape: `kettle-<unix-secs>-<pid>-<sequence>.log`. The process-wide
/// sequence distinguishes panes and repeated logging sessions in one second.
fn session_log_path(
    unix_secs: u64,
    pid: u32,
    cache_dir: Option<&std::path::Path>,
) -> std::path::PathBuf {
    static NEXT_SESSION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let sequence = NEXT_SESSION.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let dir = cache_dir
        .map(|p| p.to_path_buf().join("kettle").join("logs"))
        .unwrap_or_else(|| std::path::PathBuf::from("kettle-logs"));
    dir.join(format!("kettle-{unix_secs}-{pid}-{sequence}.log"))
}

/// Locate the XDG cache dir for the current user without
/// pulling in the `dirs` crate. Probes `$XDG_CACHE_HOME` first
/// (the spec-canonical var) then `$HOME/.cache` on Linux/macOS,
/// then `$LOCALAPPDATA` on Windows-ish, returning `None` if none
/// are set (CI / container envs). Pure modulo the env-var reader
/// fn so tests can pin the env.
fn cache_dir_from_env<F: Fn(&str) -> Option<String>>(get: F) -> Option<std::path::PathBuf> {
    let var = |k: &str| get(k).filter(|s| !s.is_empty());
    // XDG_CACHE_HOME is the explicit cross-platform override.
    if let Some(p) = var("XDG_CACHE_HOME") {
        return Some(std::path::PathBuf::from(p));
    }
    // Per-OS fallback, matching `default_path_from`. On
    // Windows the canonical per-user cache dir is `%LOCALAPPDATA%`; a stray
    // `HOME` (git-bash / MSYS / WSL-interop export one) must NOT redirect
    // screenshots / crash logs to `~/.cache` — the same config-dir split-brain
    // that bit the config path (a shell launch vs a Start-menu launch would
    // disagree). On Unix, `HOME/.cache` is the standard XDG fallback.
    if cfg!(windows) {
        var("LOCALAPPDATA").map(std::path::PathBuf::from)
    } else {
        var("HOME").map(|h| std::path::PathBuf::from(h).join(".cache"))
    }
}

/// Horizontal tab-bar layout. Tabs divide `strip` evenly and **fill the bar**
/// (two tabs each take half). There is intentionally no max width; tabs always
/// maximize width. When `scroll` is on and they would shrink below `min_w`, the
/// bar overflows: tabs stay at `min_w`, `‹ ›` arrow buttons (each `arrow_w`
/// wide) reserve the strip ends, and only whole tabs that fit between them are
/// shown, chosen so the active tab is visible (pinned to the trailing edge once
/// it scrolls past the first page). Pure (no `&self`, renderer, or winit), so
/// it is unit-testable.
struct TabStripLayout {
    /// Per-tab width for every tab EXCEPT the last one.
    width: f32,
    /// Width of the LAST tab. Equal to `width` in every layout except the
    /// full-width-aligned one, where the last tab yields the trailing `▾`/`+`
    /// button reservation so the other tab boundaries land on the same grid as
    /// vertical pane splits.
    last_width: f32,
    /// On-screen left x per tab, or `None` when scrolled out of view.
    xs: Vec<Option<f32>>,
    /// Left x of the `‹` / `›` scroll buttons when the bar overflows.
    arrow_left: Option<f32>,
    arrow_right: Option<f32>,
}

fn tab_strip_layout(
    n: usize,
    active: usize,
    strip: f32,
    trailing_reserve: f32,
    arrow_w: f32,
    min_w: f32,
    scroll: bool,
) -> TabStripLayout {
    let n = n.max(1);
    let strip = strip.max(1.0);
    let min_w = min_w.max(1.0);
    let reserve = trailing_reserve.max(0.0);
    // Preferred layout: divide the FULL bar width (the button-trimmed `strip`
    // PLUS the trailing `▾`/`+` reservation) evenly, so tab boundaries fall on
    // the same grid as vertical pane splits — with 2 tabs the tab1/tab2
    // boundary lands at the window centre, in line with a 50/50 split's
    // divider. Only the LAST tab is shortened to yield the button reservation
    // (its right edge stops at `strip`); every other tab is `even_full` wide.
    // Used whenever the shortened last tab still clears `min_w` (so no tab is
    // driven below the floor). `reserve == 0` degrades to plain even fill.
    let full = strip + reserve;
    let even_full = full / n as f32;
    let last_full = even_full - reserve;
    if last_full >= min_w {
        let xs = (0..n).map(|i| Some(i as f32 * even_full)).collect();
        return TabStripLayout {
            width: even_full,
            last_width: last_full,
            xs,
            arrow_left: None,
            arrow_right: None,
        };
    }
    let even = strip / n as f32;
    if !scroll || even >= min_w {
        // Full-width alignment would shrink the last tab below `min_w`, so fall
        // back to the original behavior: tabs divide the button-trimmed `strip`
        // evenly and fill it, left-packed. (With scrolling off and many tabs,
        // width may fall below min_w — they just keep shrinking, no overflow.)
        let width = even;
        let xs = (0..n).map(|i| Some(i as f32 * width)).collect();
        return TabStripLayout {
            width,
            last_width: width,
            xs,
            arrow_left: None,
            arrow_right: None,
        };
    }
    // Overflow: tabs at `min_w`, arrows reserve both ends, whole tabs only.
    let width = min_w;
    let arrow_w = arrow_w.clamp(1.0, strip / 2.0);
    let visible_w = (strip - 2.0 * arrow_w).max(width);
    let count = ((visible_w / width).floor() as usize).clamp(1, n);
    // Pin the active tab to the trailing edge once it scrolls past page one.
    let first = if active < count {
        0
    } else {
        (active + 1 - count).min(n - count)
    };
    let x0 = arrow_w;
    let xs = (0..n)
        .map(|i| {
            if i >= first && i < first + count {
                Some(x0 + (i - first) as f32 * width)
            } else {
                None
            }
        })
        .collect();
    TabStripLayout {
        width,
        last_width: width,
        xs,
        arrow_left: Some(0.0),
        arrow_right: Some(strip - arrow_w),
    }
}

/// Split the trailing new-tab button into `(arrow_left, plus_right)`
/// hit-rects — the `▾` dropdown on the LEFT, the `+` on the RIGHT. `arrow_w` is
/// clamped to the button width so a degenerate (tiny) button can't yield a
/// negative `+` width. Pure → unit-tested and shared by the renderer geometry
/// + the click hit-test (single source of truth).
fn split_new_tab_button(
    button: kettle_render::Rect4,
    arrow_w: f32,
) -> (kettle_render::Rect4, kettle_render::Rect4) {
    let (x, y, w, h) = button;
    let aw = arrow_w.clamp(0.0, w);
    ((x, y, aw, h), (x + aw, y, (w - aw).max(0.0), h))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NewTabHoverTarget {
    Menu,
    Plus,
}

fn new_tab_hover_target(bar: &TabBar, x: f32, y: f32) -> Option<NewTabHoverTarget> {
    if bar.new_tab_menu.2 > 0.0 && rect_contains(bar.new_tab_menu, x, y) {
        Some(NewTabHoverTarget::Menu)
    } else if rect_contains(bar.new_tab, x, y) {
        Some(NewTabHoverTarget::Plus)
    } else {
        None
    }
}

/// Whether a pointer event belongs to the tab-bar chrome. `bar.height` is the
/// row height, not the full extent of a vertical strip, so using
/// `bar.y..bar.y + bar.height` silently makes every vertical row after the
/// first (including the new-tab button) non-interactive. `band` is the layout's
/// actual horizontal row or vertical column and is shared with rendering.
fn tab_bar_pointer_region_contains(bar: &TabBar, x: f32, y: f32) -> bool {
    bar.height > 0.0 && rect_contains(bar.band, x, y)
}

/// Terminator parity (key_next_profile / key_previous_profile):
/// pick the next profile name after `current`, wrapping at the end.
/// If `current` isn't in the list (e.g. user launched without `--profile`,
/// or with an explicit `--config FILE`), the cycle starts at index 0.
/// Pure — unit-testable without touching disk.
fn pick_next_profile(current: Option<&str>, names: &[String], forward: bool) -> String {
    let n = names.len();
    let cur_idx = current
        .and_then(|c| names.iter().position(|x| x == c))
        .unwrap_or(0);
    let next_idx = if forward {
        (cur_idx + 1) % n
    } else {
        (cur_idx + n - 1) % n
    };
    names[next_idx].clone()
}

fn pick_light_dark_target(current: &str, light: &str, dark: &str) -> Option<String> {
    let cur = current.trim().to_ascii_lowercase();
    let l = light.trim();
    let d = dark.trim();
    match (l.is_empty(), d.is_empty()) {
        (true, true) => None,
        (false, true) => Some(l.to_string()),
        (true, false) => Some(d.to_string()),
        (false, false) => {
            // Current dark switches to light. Light and any third-party theme
            // switch to dark, so only the dark match needs its own arm.
            if cur == d.to_ascii_lowercase() {
                Some(l.to_string())
            } else {
                Some(d.to_string())
            }
        }
    }
}

/// The hint winit gets at window creation, which on macOS is not the hint the
/// window ends up with.
///
/// macOS gets `None` here and picks its appearance up later, from
/// [`native_theme_sync_is_due`]. winit applies a creation-time hint as an
/// `NSWindow` appearance override before AppKit has built the titlebar's
/// container view, and the native material view kettle adds to the frame view
/// right afterwards then locks in the container-less layout: AppKit centres
/// the title over the 72pt traffic-light cluster instead of the caption, so
/// `~ — kettle` is drawn across the red and yellow buttons and clipped at the
/// window edge (Reddimus/kettle#251).
///
/// Every other platform still seeds the caption at creation, where it costs
/// nothing and avoids a first-frame flash.
///
/// Pure — unit-testable without a window.
fn creation_theme_hint(hint: Option<WindowTheme>, is_macos: bool) -> Option<WindowTheme> {
    if is_macos { None } else { hint }
}

/// Whether this window may be handed the native theme hint yet.
///
/// Only the *first* appearance a macOS window is given has to wait for the
/// window to be on screen and key, which is when AppKit builds its titlebar
/// container. That one can leave the window permanently without a caption —
/// removing the material view again does not bring it back — so a window that
/// has never been focused keeps the system appearance rather than a broken
/// caption. See [`creation_theme_hint`].
///
/// Every later change is unconditional. The caption exists by then, and this
/// is the path the runtime light/dark toggle always took. Holding those back
/// too would strand a background window on a stale appearance until someone
/// clicked it, since a schedule boundary, Lua, or a config reload can move the
/// hint while another window has focus.
///
/// Pure — unit-testable without a window.
fn native_theme_sync_is_due(window_is_key: bool, already_synced: bool, is_macos: bool) -> bool {
    !is_macos || window_is_key || already_synced
}

/// Decide the native window-theme hint (winit
/// `WindowAttributes::preferred_theme` / `Window::set_theme`) so the OS
/// titlebar — the Windows DWM caption, the Wayland Adwaita CSD frame —
/// matches the palette kettle is actually rendering, instead of staying on
/// the OS-wide setting under a forced dark/light theme.
///
///   - `Auto` without a schedule → `None`: the palette follows the OS, so
///     let the titlebar follow the OS natively too. Forcing a value here
///     would also stop winit's `ThemeChanged` events on some backends,
///     which the palette auto-switcher depends on.
///   - everything else (Explicit / Light / Dark / Auto+schedule) → the
///     titlebar matches the active theme's background darkness.
///
/// Pure — unit-testable without a window.
fn native_theme_hint(
    mode: kettle_config::ThemeMode,
    has_schedule: bool,
    theme_is_dark: bool,
) -> Option<WindowTheme> {
    if mode == kettle_config::ThemeMode::Auto && !has_schedule {
        None
    } else if theme_is_dark {
        Some(WindowTheme::Dark)
    } else {
        Some(WindowTheme::Light)
    }
}

/// Cap an OSC 52 clipboard payload so a hostile program can't make the
/// terminal allocate/set an unbounded clipboard. Truncates on a UTF-8
/// char boundary at or below `max` bytes (xterm/kitty also bound this).
fn clamp_osc52(s: &str, max: usize) -> &str {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

/// 1 MiB — generous for real copies, bounded against abuse.
const OSC52_MAX: usize = 1 << 20;

/// 4 MiB limit on a *local* clipboard paste. The OSC 52 cap above guards
/// against a hostile remote program pushing an unbounded payload into
/// the system clipboard; this guards the reverse direction — a user
/// accidentally pastes a multi-GB file and kettle would otherwise feed
/// every byte into the PTY in one shot, freezing the terminal until
/// the program at the other end (cat? vim?) drained the pipe. 4 MiB
/// fits any realistic code-review / log-snippet paste with room to spare.
/// Larger payloads are rejected with visible feedback rather than truncated,
/// since silently shortening a command, patch, or encoded file is unsafe.
const LOCAL_PASTE_MAX: usize = 4 << 20;

fn local_paste_within_limit(text: &str) -> bool {
    text.len() <= LOCAL_PASTE_MAX
}

fn group_scope_is_globally_stale(
    autoclean: bool,
    scope: &BroadcastScope,
    populated_groups: &HashSet<&str>,
) -> bool {
    autoclean
        && matches!(scope, BroadcastScope::Group(name) if !populated_groups.contains(name.as_str()))
}

fn any_group_scope_needs_hoover<'a>(windows: impl IntoIterator<Item = &'a WindowState>) -> bool {
    windows.into_iter().any(|window| {
        window.mux.autoclean_groups && matches!(window.mux.broadcast, BroadcastScope::Group(_))
    })
}

fn stamp_accepted_input(
    last_typed: &mut Option<std::time::Instant>,
    delivery: PaneInputDelivery,
    input_time: std::time::Instant,
) {
    if delivery.accepted {
        *last_typed = Some(input_time);
    }
}

/// The pane a single-pane paste goes to: the focused one. Broadcast names no
/// pane and keeps its live group semantics.
fn paste_target(mux: &Mux) -> Option<u64> {
    if mux.is_broadcast_on() {
        None
    } else {
        mux.active_focus()
    }
}

/// Apply a terminal control, such as Reset's RIS or Clear Scrollback's
/// CSI 3 J, to each target pane's terminal.
///
/// Nothing is written to the child, so read-only panes are included. This is
/// VTE's model, which Terminator's Reset uses: `vte_terminal_reset` changes the
/// terminal and ignores `input-enabled`.
fn apply_terminal_control(mux: &Mux, targets: &[u64], bytes: &[u8]) {
    for id in targets {
        if let Some(pane) = mux.panes.get(id)
            && !pane.term.apply_local_output(bytes)
        {
            log::debug!("pane {id}: terminal control dropped; its reader is busy or stopped");
        }
    }
}

/// Deliver a confirmed non-broadcast text paste to the pane named when the
/// prompt opened. Mode lookup and delivery use the same stable id.
fn paste_text_into_target(
    mux: &mut Mux,
    target: Option<u64>,
    text: &str,
) -> Option<PaneInputResult> {
    let pane = mux.panes.get_mut(&target?)?;
    let bracketed = pane
        .term
        .term
        .lock()
        .ok()
        .map(|term| term.mode().contains(kettle_core::TermMode::BRACKETED_PASTE))
        .unwrap_or(false);
    let bytes = input::paste_payload(text, bracketed);
    Some(pane.feed_input(&bytes))
}

/// Deliver a confirmed non-broadcast path paste to the pane named when the
/// prompt opened. Shell formatting, mode lookup, and delivery all use it.
fn paste_paths_into_target(
    mux: &mut Mux,
    target: Option<u64>,
    paths: &[std::path::PathBuf],
    trailing_space: bool,
) -> Option<PaneInputDelivery> {
    let pane = mux.panes.get_mut(&target?)?;
    let mut text = crate::mux::format_paths_for_paste(&pane.argv, paths);
    if trailing_space {
        text.push(' ');
    }
    let bracketed = pane
        .term
        .term
        .lock()
        .ok()
        .map(|term| term.mode().contains(kettle_core::TermMode::BRACKETED_PASTE))
        .unwrap_or(false);
    let bytes = input::paste_payload(&text, bracketed);
    let result = pane.feed_input(&bytes);
    Some(PaneInputDelivery {
        result,
        accepted: result.is_queued(),
        receipt_accepted: result.is_queued(),
    })
}

/// Pure: when the mouse is over chrome (tab bar, status bar, update banner, or
/// any modal overlay), the OS cursor should be the standard arrow rather than
/// the text I-beam. Matches iTerm2 / WezTerm / Ghostty / kitty: chrome surfaces
/// are clickable, not selectable, so the I-beam is visually misleading there.
/// Returns `Some(Default)` for chrome, `None` to let the content-area caller
/// decide between `Pointer` (URL-hover) and `Text`.
fn chrome_cursor_icon(in_chrome_band: bool, modal_open: bool) -> Option<CursorIcon> {
    if in_chrome_band || modal_open {
        Some(CursorIcon::Default)
    } else {
        None
    }
}

/// Pure: when the cursor is over a tab's `✕` close-button zone, override the
/// chrome `Default` with `Pointer` — the same "hand" icon every browser
/// (Chrome / Firefox / Safari) uses to telegraph "this glyph is clickable."
/// Composes with `chrome_cursor_icon`: close-hover wins over the bar's
/// `Default` so the affordance is visible the moment the cursor lands on
/// the close zone. Returns `None` when not over a close button so the
/// content-area decision still gets a chance.
fn tab_close_hover_icon(over_close: bool) -> Option<CursorIcon> {
    if over_close {
        Some(CursorIcon::Pointer)
    } else {
        None
    }
}

/// Pure: while a tab-drag gesture is armed or in
/// progress, override every other cursor decision with the "holding
/// something" hand: `Grab` the moment a press arms the FSM (the gesture
/// could still resolve to a plain click), `Grabbing` once movement promotes
/// it to a real drag. In-window reorder and cross-window tear share
/// `detach::DragState`, so one helper covers both. `None` from `Idle`
/// defers to every other rule. No `detachable-tabs` re-check needed: the
/// press handler only arms the FSM when the config gate is on, so a
/// non-`Idle` state already implies it (see
/// `detachable_tabs_config_gates_all_detach_paths`).
fn tab_drag_cursor_icon(state: &crate::detach::DragState) -> Option<CursorIcon> {
    match state {
        crate::detach::DragState::Idle => None,
        crate::detach::DragState::ArmedInside { .. } => Some(CursorIcon::Grab),
        crate::detach::DragState::DraggingInside { .. }
        | crate::detach::DragState::DraggingOutside { .. } => Some(CursorIcon::Grabbing),
    }
}

/// The text a confirmation button shows. Painting and hit testing both use it,
/// so a click lands on what is drawn in every language.
fn confirm_button_label<'a>(button: &'a ConfirmButton, tr: &kettle_i18n::Translator) -> &'a str {
    match button {
        ConfirmButton::Cancel => tr.text(kettle_i18n::Text::ConfirmButtonCancel),
        ConfirmButton::Confirm { label, .. } => label.as_str(),
    }
}

/// The title editor's label for `scope`. The overlay paints it and the
/// input-method placement measures it, so both use this.
fn title_edit_label(scope: TitleEditScope, tr: &kettle_i18n::Translator) -> &'static str {
    use kettle_i18n::Text;
    tr.text(match scope {
        TitleEditScope::Window => Text::EditTitleWindow,
        TitleEditScope::Tab => Text::EditTitleTab,
        TitleEditScope::Pane => Text::EditTitlePane,
        TitleEditScope::Group => Text::EditTitleGroup,
    })
}

/// The column of the title editor's caret: the painted prefix in the UI's
/// language, the input, then any composition before the focus point.
fn title_edit_caret_cols(
    scope: TitleEditScope,
    input: &str,
    preedit_before_focus: &str,
    tr: &kettle_i18n::Translator,
) -> usize {
    use unicode_width::UnicodeWidthStr as _;
    kettle_render::title_edit_prefix(title_edit_label(scope, tr)).width()
        + input.width()
        + preedit_before_focus.width()
}

/// Where the title-edit overlay is painted.
///
/// Pure so the geometry can be tested.
///
/// Under a VERTICAL tab bar this must span the full window width, not the tab
/// strip. The renderer composes
/// `"  ✎ {label} {input}_   (Enter apply · Esc cancel)"` into
/// `overlay_label_cols(rect.2, cw)`; a strip is `tab-bar-width` wide (default
/// 180px, ~22 columns) and the trailing hint alone is 30 columns, so the budget
/// cannot hold even the prefix. The input would render zero columns (no text,
/// no caret, no horizontal scroll) while Enter still commits the invisible
/// buffer. For `EditPaneGroup` that buffer names the broadcast group, so it
/// decides which panes receive subsequent keystrokes.
fn title_edit_rect_for(
    vertical: bool,
    bar_y: f32,
    bar_height: f32,
    content_y: f32,
    sw: f32,
    sh: f32,
    row_h: f32,
) -> kettle_render::Rect4 {
    if bar_height > 0.0 {
        if vertical {
            let height = row_h.max(0.0).min(sh);
            let y = (content_y - height).clamp(0.0, (sh - height).max(0.0));
            (0.0, y, sw, height)
        } else {
            (0.0, bar_y, sw, bar_height)
        }
    } else {
        (0.0, 0.0, sw, row_h)
    }
}

fn confirm_dialog_button_cells(button: &ConfirmButton, tr: &kettle_i18n::Translator) -> usize {
    // Renderer format is `[<marker> <label>]`, where marker is either `▶` or a
    // single space. The hit-test uses the same cell budget so clicks track the
    // visible right-aligned button row.
    confirm_button_label(button, tr).width() + 4
}

fn confirm_dialog_button_hit(
    buttons: &[ConfirmButton],
    (px, py): (f32, f32),
    (window_w, window_h): (f32, f32),
    (cell_w, cell_h): (f32, f32),
    tr: &kettle_i18n::Translator,
) -> Option<usize> {
    if buttons.is_empty() || window_w <= 0.0 || window_h <= 0.0 || cell_w <= 0.0 || cell_h <= 0.0 {
        return None;
    }

    let bar_h = cell_h + 10.0;
    let bar_y = window_h - bar_h;
    if py < bar_y || py >= window_h {
        return None;
    }

    let gap_cells = 2usize;
    let buttons_cells = buttons
        .iter()
        .map(|button| confirm_dialog_button_cells(button, tr))
        .sum::<usize>()
        + gap_cells.saturating_mul(buttons.len().saturating_sub(1));
    // Use the renderer's exact painted budget: one column narrower than the
    // window to allow for glyph overhang and fractional cell metrics.
    let cols = kettle_render::confirm_bar_columns(window_w, cell_w);
    if buttons_cells == 0 || buttons_cells > cols {
        return None;
    }

    let mut x_cells = cols - buttons_cells;
    for (idx, button) in buttons.iter().enumerate() {
        let w_cells = confirm_dialog_button_cells(button, tr);
        let x0 = x_cells as f32 * cell_w;
        let x1 = (x_cells + w_cells) as f32 * cell_w;
        if px >= x0 && px < x1 {
            return Some(idx);
        }
        x_cells += w_cells;
        if idx + 1 < buttons.len() {
            x_cells += gap_cells;
        }
    }
    None
}

/// Pure: which tab segment's close-button (`✕`) rect contains the cursor,
/// if any. Walks `segments` once and returns the first hit (segments don't
/// overlap in the tab bar layout; cycle-tab-bar invariant). Used both to
/// drive the OS pointer-cursor swap and the renderer's hover-background
/// quad — the visual affordance that makes the `✕` read as a button rather
/// than a trailing character in the title text.
fn hovered_close_button(segments: &[kettle_render::TabSeg], px: f32, py: f32) -> Option<usize> {
    let in_rect = |(rx, ry, rw, rh): (f32, f32, f32, f32)| {
        px >= rx && px < rx + rw && py >= ry && py < ry + rh
    };
    segments.iter().find(|s| in_rect(s.close)).map(|s| s.idx)
}

/// Per-pane titlebar hit test (Terminator parity): returns the id of the pane
/// whose titlebar band contains the click, or `None`. Pure so the hit test
/// behind `App::pane_at_titlebar_click` can be drift-guarded.
#[allow(clippy::type_complexity)]
pub(crate) fn pane_titlebar_hit(
    px: f32,
    py: f32,
    pane_rects: &[(u64, (f32, f32, f32, f32))],
    title_at_bottom: bool,
    bar_h: f32,
) -> Option<u64> {
    for (id, (rx, ry, rw, rh)) in pane_rects {
        let (bar_top, bar_bot) = if title_at_bottom {
            (*ry + *rh - bar_h, *ry + *rh)
        } else {
            (*ry + 1.0, *ry + 1.0 + bar_h)
        };
        if px >= *rx && px < *rx + *rw && py >= bar_top && py < bar_bot {
            return Some(*id);
        }
    }
    None
}

/// SGR mouse base code for the extra "side" mouse buttons, or `None` for any
/// button kettle handles locally (left/middle/right) or doesn't forward.
///
/// Forwarding these lets a 5-button mouse's Back / Forward reach a
/// mouse-tracking TUI (tmux/vim bindings, pagers). xterm encodes buttons 8–11
/// as `128 + (button - 8)`; winit's `Back` is XBUTTON1 (button 8 → 128) and
/// `Forward` is XBUTTON2 (button 9 → 129). These have no local UI meaning, so
/// they only do anything while mouse tracking is on.
fn extra_mouse_sgr(button: MouseButton) -> Option<u8> {
    match button {
        MouseButton::Back => Some(MOUSE_BACK),
        MouseButton::Forward => Some(MOUSE_FORWARD),
        _ => None,
    }
}

/// The report code of xterm's button 8, the Back button.
const MOUSE_BACK: u8 = 128;
/// The report code of xterm's button 9, the Forward button.
const MOUSE_FORWARD: u8 = 129;

/// What a mouse event did on its way to a pane's terminal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MouseReport {
    /// A report went to the terminal.
    Written,
    /// Kettle kept the event from the terminal, and nothing else handles it.
    Swallowed,
    /// No report was due; Kettle handles the event itself.
    Declined,
}

impl MouseReport {
    /// Whether nothing else should handle the event.
    fn consumed(self) -> bool {
        self != Self::Declined
    }
}

/// Where a mouse report lands in its pane.
#[derive(Clone, Copy, Debug, PartialEq)]
enum MouseAt {
    /// The pointer's cell in the pane's rect.
    Pointer(Rect),
    /// The drag or release of a held button whose press the pane's program
    /// got: the pointer's cell in its rect while it is on screen, else the
    /// cell it was last told of.
    Held {
        rect: Option<Rect>,
        cell: (usize, usize),
    },
}

/// Whether an OSC 7 working directory is safe to turn into a `file://` URL and
/// hand to the OS opener.
///
/// The cwd comes from untrusted PTY output (`parse_osc7`
/// stores whatever a program reports), and a crafted `file://x//evil.host/share`
/// yields a stored cwd of `//evil.host/share`. Building `file://{cwd}` from that
/// produces a UNC-style URL that, when opened on Windows, connects to the
/// attacker over SMB and leaks the user's NTLM hash. The
/// `is_safe_url` locality check already rejects the resulting URL, but this is
/// the one call site that *constructs* `file://` from raw untrusted input, so
/// it gets an explicit local-only guard too (defense-in-depth). Crucially this
/// check does NO filesystem stat — `Path::is_dir` on a `//host` path would
/// itself route over SMB — it's a pure string check: reject UNC/authority
/// (`//`, leading `\`) and traversal.
fn cwd_is_local(cwd: &str) -> bool {
    !cwd.is_empty() && !cwd.starts_with("//") && !cwd.starts_with('\\') && !cwd.contains("..")
}

/// What opening a local file link would do, decided on the opener thread.
#[derive(Debug, PartialEq)]
enum FileLinkCheck {
    /// Open this resolved path: a document or a folder.
    Open(std::path::PathBuf),
    /// Refuse: it is a program or a shortcut. Holds the name to report.
    Program(String),
    /// Refuse quietly: it does not resolve to a local file or folder.
    Unresolved,
}

/// Whether opening the local file `path` would run a program or follow a
/// shortcut. Symlinks are resolved first, because the OS opener follows them:
/// `notes.md` linking to an application must not launch it. Refused when
/// either the name or the resolved name names a program or a shortcut (see
/// [`kettle_core::links::names_program_or_shortcut`]), when a folder is a
/// macOS bundle by its contents, when a file is a shortcut by its first bytes
/// (a macOS alias, which the opener follows whatever its name, or a Linux
/// launcher), or when an executable file lacks a known document extension:
/// macOS runs `a.out` in Terminal. A document whose executable bits are set,
/// as every file on a FAT or exFAT volume is, still opens.
///
/// This looks at an untrusted path, which can stall on a network mount, so
/// it runs off the UI thread. What it resolves is what opens, but a local
/// process that rewrites the file between the check and the open is not
/// stopped.
fn check_file_link(path: &std::path::Path) -> FileLinkCheck {
    use kettle_core::links::names_program_or_shortcut;
    let Ok(resolved) = std::fs::canonicalize(path) else {
        return FileLinkCheck::Unresolved;
    };
    let Some(resolved) = local_resolved_path(resolved) else {
        return FileLinkCheck::Unresolved;
    };
    let Ok(metadata) = std::fs::metadata(&resolved) else {
        return FileLinkCheck::Unresolved;
    };
    let is_dir = metadata.is_dir();
    let program = names_program_or_shortcut(path, is_dir)
        || names_program_or_shortcut(&resolved, is_dir)
        || (is_dir && resolved.join("Contents").join("Info.plist").exists())
        || (metadata.is_file()
            && (starts_like_a_shortcut(&resolved)
                || (is_executable(&metadata) && !names_a_document(&resolved))));
    if program {
        let name = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default();
        FileLinkCheck::Program(name)
    } else {
        FileLinkCheck::Open(resolved)
    }
}

/// `resolved` as a path the opener may take: on Windows a canonical path is
/// a verbatim `\\?\C:\…`, kept as `C:\…`, while a share (`\\?\UNC\…`) or a
/// volume GUID is refused. Elsewhere, any absolute path.
fn local_resolved_path(resolved: std::path::PathBuf) -> Option<std::path::PathBuf> {
    if !cfg!(windows) {
        return resolved.is_absolute().then_some(resolved);
    }
    let text = resolved.to_str()?;
    let drive = |path: &str| {
        let b = path.as_bytes();
        b.len() >= 3 && b[0].is_ascii_alphabetic() && b[1] == b':' && matches!(b[2], b'\\' | b'/')
    };
    let local = text.strip_prefix(r"\\?\").unwrap_or(text);
    (drive(local) && win32_keeps_path(local)).then(|| std::path::PathBuf::from(local))
}

/// Whether Win32 reads the drive path `local` as written once the verbatim
/// `\\?\` prefix is gone: no name ends with a dot or a space, which Win32
/// drops, and none is a reserved device name (`CON`, `NUL`, `COM1`…), which
/// Win32 opens as the device.
fn win32_keeps_path(local: &str) -> bool {
    local.split(['\\', '/']).skip(1).all(|name| {
        let stem = name.split('.').next().unwrap_or(name).trim_end();
        let device = matches!(
            stem.to_ascii_uppercase().as_str(),
            "CON" | "PRN" | "AUX" | "NUL"
        ) || (stem.len() == 4
            && ["COM", "LPT"].iter().any(|prefix| {
                stem.get(..3)
                    .is_some_and(|head| head.eq_ignore_ascii_case(prefix))
            })
            && matches!(stem.as_bytes()[3], b'1'..=b'9'));
        !name.ends_with(['.', ' ']) && !device
    })
}

/// Whether a file's mode lets it run (Unix); never on Windows, which runs by
/// extension.
fn is_executable(metadata: &std::fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        metadata.permissions().mode() & 0o111 != 0
    }
    #[cfg(not(unix))]
    {
        let _ = metadata;
        false
    }
}

/// Whether `path` has the extension of a common document, image, media,
/// archive, text or source file, which the OS opener shows in an app rather
/// than runs even when its executable bits are set.
fn names_a_document(path: &std::path::Path) -> bool {
    const DOCUMENTS: &[&str] = &[
        "pdf", "png", "jpg", "jpeg", "gif", "webp", "svg", "bmp", "tif", "tiff", "heic", "ico",
        "psd", "mp4", "mov", "m4v", "mkv", "webm", "avi", "mp3", "m4a", "wav", "flac", "ogg",
        "opus", "aac", "txt", "md", "markdown", "rst", "adoc", "org", "tex", "html", "htm", "css",
        "json", "jsonl", "yaml", "yml", "toml", "xml", "csv", "tsv", "log", "rtf", "doc", "docx",
        "xls", "xlsx", "ppt", "pptx", "odt", "ods", "odp", "pages", "numbers", "key", "epub",
        "zip", "tar", "gz", "tgz", "bz2", "xz", "zst", "7z", "rar", "c", "h", "cc", "cpp", "hpp",
        "rs", "go", "java", "kt", "swift", "ts", "tsx", "jsx", "sql", "ini", "conf", "cfg", "lock",
        "ipynb", "diff", "patch", "mmd", "dot",
    ];
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| {
            DOCUMENTS
                .iter()
                .any(|known| extension.eq_ignore_ascii_case(known))
        })
}

/// Whether a file is a shortcut an opener follows: a macOS alias, by its
/// Finder flag (a classic alias keeps its data in the resource fork) or by
/// its bookmark data, or a Linux desktop launcher, whose first group, past
/// blank and comment lines, is `[Desktop Entry]`.
fn starts_like_a_shortcut(path: &std::path::Path) -> bool {
    use std::io::Read as _;
    if finder_alias_flag(path) {
        return true;
    }
    let mut head = Vec::with_capacity(4096);
    let Ok(file) = std::fs::File::open(path) else {
        return false;
    };
    if file.take(4096).read_to_end(&mut head).is_err() {
        return false;
    }
    if head.starts_with(b"book") && head.get(8..12) == Some(b"mark") {
        return true;
    }
    let head = head.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(&head);
    head.split(|&byte| byte == b'\n')
        .map(<[u8]>::trim_ascii)
        .find(|line| !line.is_empty() && !line.starts_with(b"#"))
        .is_some_and(|group| {
            [
                &b"[Desktop Entry]"[..],
                b"[Desktop Action",
                b"[KDE Desktop Entry]",
            ]
            .iter()
            .any(|launcher| group.starts_with(launcher))
        })
}

/// Whether macOS marks `path` as a Finder alias (`kIsAlias` in the Finder
/// flags of its `com.apple.FinderInfo` attribute).
#[cfg(target_os = "macos")]
fn finder_alias_flag(path: &std::path::Path) -> bool {
    use std::os::unix::ffi::OsStrExt as _;
    const IS_ALIAS: u16 = 0x8000;
    let Ok(c_path) = std::ffi::CString::new(path.as_os_str().as_bytes()) else {
        return false;
    };
    let mut info = [0u8; 32];
    // SAFETY: both names are NUL-terminated C strings that outlive the call,
    // and `info` is writable for the length passed.
    let read = unsafe {
        libc::getxattr(
            c_path.as_ptr(),
            c"com.apple.FinderInfo".as_ptr(),
            info.as_mut_ptr().cast(),
            info.len(),
            0,
            0,
        )
    };
    read >= 10 && u16::from_be_bytes([info[8], info[9]]) & IS_ALIAS != 0
}

#[cfg(not(target_os = "macos"))]
fn finder_alias_flag(_path: &std::path::Path) -> bool {
    false
}

/// At most this many file links are checked and opened at once; a stalled
/// network path cannot pile up threads click by click.
const MAX_FILE_LINK_OPENERS: usize = 4;
static FILE_LINK_OPENERS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// A slot among `limit` concurrent users of `counter`, released on drop, or
/// `None` when all are taken.
fn take_opener_slot(
    counter: &'static std::sync::atomic::AtomicUsize,
    limit: usize,
) -> Option<OpenerSlot> {
    use std::sync::atomic::Ordering;
    // Rust 1.99 renames fetch_update to try_update; the MSRV (1.95) predates it.
    #[allow(deprecated)]
    let taken = counter.fetch_update(Ordering::AcqRel, Ordering::Acquire, |taken| {
        (taken < limit).then_some(taken + 1)
    });
    taken.ok().map(|_| OpenerSlot(counter))
}

struct OpenerSlot(&'static std::sync::atomic::AtomicUsize);

impl Drop for OpenerSlot {
    fn drop(&mut self) {
        self.0.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
    }
}

/// Check the local file link `path` and open what it resolves to, on its own
/// thread: with the custom URL handler, if one is set, given a file URL for
/// the resolved path, or with the system opener. A program or shortcut is
/// refused with a notification.
fn spawn_file_link_opener(
    path: std::path::PathBuf,
    handler: Option<String>,
    tr: kettle_i18n::Translator,
) {
    let Some(slot) = take_opener_slot(&FILE_LINK_OPENERS, MAX_FILE_LINK_OPENERS) else {
        log::warn!("too many file links are still opening; ignoring this one");
        return;
    };
    let spawned = std::thread::Builder::new()
        .name("kettle-open-link".into())
        .spawn(move || {
            let _slot = slot;
            match check_file_link(&path) {
                FileLinkCheck::Program(name) => fire_notify(
                    tr.text(kettle_i18n::Text::NotifyTitleProgramNotOpened),
                    &tr.notify_body_program_not_opened(&name),
                ),
                FileLinkCheck::Unresolved => {
                    log::warn!("not opening a file link that names no local file or folder");
                    // Say so: from behind tmux this is usually a path an ssh
                    // inside it printed, which names a file on that machine.
                    let name = kettle_core::links::file_url_for_path(&path)
                        .map(|url| link_display_name(&url, 48))
                        .unwrap_or_default();
                    fire_notify(
                        tr.text(kettle_i18n::Text::NotifyTitleRemoteFileNotOpened),
                        &tr.notify_body_file_link_not_found(&name),
                    );
                }
                FileLinkCheck::Open(resolved) => open_checked_file(&resolved, handler.as_deref()),
            }
        });
    if let Err(e) = spawned {
        log::warn!("could not start the link opener: {e}");
    }
}

// Start the waiter before its child so a thread-spawn failure cannot lose a child handle.
fn spawn_custom_url_handler(cmd: &str, target: &str) -> std::io::Result<()> {
    let cmd = cmd.to_string();
    let target = target.to_string();
    let (tx, rx) = std::sync::mpsc::sync_channel(1);
    std::thread::Builder::new()
        .name("kettle-url-handler".into())
        .spawn(move || {
            match std::process::Command::new(&cmd)
                .arg(&target)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
            {
                Ok(mut child) => {
                    let _ = tx.send(Ok(()));
                    if let Err(e) = child.wait() {
                        log::warn!("custom-url-handler {cmd:?}: could not reap child: {e}");
                    }
                }
                Err(e) => {
                    let _ = tx.send(Err(e));
                }
            }
        })?;
    rx.recv().map_err(std::io::Error::other)?
}

/// Open a checked, resolved local file: through `handler` with a file URL
/// built from the resolved path, falling back to the system opener, which
/// takes the path itself. Neither sees the link's own text, so neither can
/// read a different path out of it.
fn open_checked_file(resolved: &std::path::Path, handler: Option<&str>) {
    if let (Some(cmd), Some(url)) = (handler, kettle_core::links::file_url_for_path(resolved)) {
        match spawn_custom_url_handler(cmd, &url) {
            Ok(_) => return,
            Err(e) => {
                log::warn!("custom-url-handler {cmd:?}: {e}; opening the file with the system")
            }
        }
    }
    if let Err(e) = open::that_detached(resolved) {
        log::warn!("failed to open a terminal-supplied file link: {e}");
    }
}

/// Record a keystroke into the dev recorder as a privacy-preserving
/// token. Named keys (`Enter`, `ArrowUp`, `Ctrl+ArrowUp`) are recorded by name;
/// they aren't secret. A printable character, bare or with modifiers, is
/// recorded only as a redacted class glyph (after any modifier prefix, e.g.
/// `Ctrl+·`) unless raw-input was opted into, so a typed password never lands
/// in the trace (its keystroke count + timing still do).
fn dev_record_key(
    rec: &mut crate::dev_record::Recorder,
    key: &winit::keyboard::Key,
    mods: ModifiersState,
) {
    use winit::keyboard::Key;
    let mut prefix = String::new();
    if mods.control_key() {
        prefix.push_str("Ctrl+");
    }
    if mods.alt_key() {
        prefix.push_str("Alt+");
    }
    if mods.super_key() {
        prefix.push_str("Super+");
    }
    let token = match key {
        Key::Named(nk) => Some(format!("{prefix}{nk:?}")),
        // Redact the PAYLOAD of a modifier+printable key
        // unless raw-input recording is on, keeping only the modifier prefix +
        // timing. AltGr is reported as Ctrl+Alt on Windows, so a non-US-layout
        // symbol / accented letter typed via AltGr would otherwise land in the
        // always-on trace in cleartext — breaking the documented "a typed
        // password never reaches the trace" guarantee.
        Key::Character(s) if !prefix.is_empty() => Some(format!(
            "{prefix}{}",
            crate::dev_record::printable_token(s.as_str(), rec.raw_input())
        )),
        Key::Character(s) => Some(crate::dev_record::printable_token(
            s.as_str(),
            rec.raw_input(),
        )),
        _ => None,
    };
    if let Some(t) = token {
        rec.record_input(&t);
    }
}

/// Neutralize an OSC-set window/tab title before it reaches
/// the OS titlebar, the tab label, and the status bar. Replaces control
/// characters AND Unicode bidirectional-override format characters (the U+202E
/// titlebar / Alt-Tab spoofing vector) with a space, and caps the length so a
/// pathological program can't set a multi-kilobyte title. Mirrors the
/// notification path's control-stripping + length-cap policy.
fn sanitize_title(t: &str) -> String {
    const MAX_TITLE_CHARS: usize = 512;
    t.chars()
        .map(|c| {
            if c.is_control() || is_bidi_format_char(c) {
                ' '
            } else {
                c
            }
        })
        .take(MAX_TITLE_CHARS)
        .collect()
}

/// Native window-manager titlebars use the desktop UI font, not kettle's
/// terminal font stack. Strip Unicode Private Use glyphs (Nerd Font icons,
/// Powerline variants, etc.) from the OS title only so GNOME/Ubuntu titlebars
/// do not show tofu boxes while in-app tabs/pane titlebars can still render
/// those glyphs through kettle's embedded font path.
fn sanitize_native_window_title(t: &str) -> String {
    let out = t
        .chars()
        .filter(|&c| !is_private_use_char(c))
        .collect::<String>();
    let out = out.trim();
    if out.is_empty() {
        "kettle".to_string()
    } else {
        out.to_string()
    }
}

fn is_private_use_char(c: char) -> bool {
    matches!(
        c,
        '\u{E000}'..='\u{F8FF}' | '\u{F0000}'..='\u{FFFFD}' | '\u{100000}'..='\u{10FFFD}'
    )
}

/// Unicode bidirectional formatting / override code points. These are NOT
/// `char::is_control()` (they are general category Cf) but enable right-to-left
/// titlebar / Alt-Tab spoofing, so a sanitized title must neutralize them too.
pub(crate) fn is_bidi_format_char(c: char) -> bool {
    matches!(
        c,
        '\u{202A}'..='\u{202E}'      // LRE RLE PDF LRO RLO
            | '\u{2066}'..='\u{2069}' // LRI RLI FSI PDI
            | '\u{200E}' | '\u{200F}' // LRM RLM
    )
}

/// Pure pointer → `(col, line, side)` math for a pane, shared by `px_to_point` so
/// the per-pane-titlebar inset is drift-tested.
///
/// The renderer and hit testing share [`kettle_render::pane_grid_origin`] (a top
/// titlebar moves row zero down; a bottom one leaves it at the pane padding), so
/// selection, link targeting, mouse reporting, and IME projection never drift a
/// row from the drawn grid. Col/line clamp to ≥ 0 so a click in the
/// chrome/padding doesn't underflow.
///
/// `side` is which half of the hit cell the pointer sits in, derived from the
/// sub-cell x offset: the left half is `Side::Left`, the right half (and the
/// exact midpoint) is `Side::Right`. This matches xterm / Alacritty / iTerm2 and
/// is exactly what alacritty's `Selection::to_range` (`range_simple`/`range_block`)
/// needs to decide whether each boundary cell is included. Without it a drag is
/// biased one cell wide. The side is computed from the SAME clamped non-negative
/// offset as `col`, so a pointer left of the content origin maps to
/// `(col 0, Side::Left)` and the first cell is included, never trimmed. NOTE:
/// only Simple/Block *drag* selections consume this side; word / line /
/// smart-select snap to token boundaries and ignore it (see `begin_selection` /
/// `apply_smart_selection`).
fn px_to_cell(
    px: f32,
    py: f32,
    terminal: Rect,
    cell: (f32, f32),
    pad: (f32, f32),
) -> (usize, i32, kettle_core::Side) {
    let (cw, ch) = cell;
    let (ox, oy) = (terminal.0 + pad.0, terminal.1 + pad.1);
    // Derive BOTH col and side from the same non-negative offset so they agree at
    // the left clamp: a pointer in the left padding (offset < 0) maps to
    // (col 0, Side::Left) — the first cell is included, not trimmed. Computing the
    // side from the raw (negative) offset via `rem_euclid` would wrap it into the
    // cell's right half and wrongly drop column 0 from a drag.
    let offx = (px - ox).max(0.0);
    let col = (offx / cw).floor() as usize;
    let line = ((py - oy) / ch).floor().max(0.0) as i32;
    let side = if offx.rem_euclid(cw) < cw / 2.0 {
        kettle_core::Side::Left
    } else {
        kettle_core::Side::Right
    };
    (col, line, side)
}

/// Map a VIEWPORT-relative point (line 0 = top visible row, what `px_to_point`
/// returns) to the GRID-ABSOLUTE point that alacritty's `Selection` /
/// `selection_to_string` / `to_range` and `grid[..]` indexing expect, by
/// subtracting the focused pane's `display_offset` via alacritty's own
/// `viewport_to_point`. Without it, a selection or grid-row read taken while
/// scrolled into history addresses the active-screen row instead of the
/// scrolled-to row, so the copy returns wrong or empty text and the highlight
/// slips down by the scroll amount. The bug is invisible at the bottom, where
/// `display_offset == 0` makes viewport and absolute coincide. Pure
/// (drift-tested in `viewport_point_to_grid_applies_display_offset`).
fn viewport_point_to_grid(
    viewport: kettle_core::Point,
    display_offset: usize,
) -> kettle_core::Point {
    let line = viewport.line.0.max(0) as usize;
    kettle_core::viewport_to_point(
        display_offset,
        kettle_core::Point::new(line, viewport.column),
    )
}

/// Grid-absolute `(top-left, bottom-right)` points spanning the whole buffer —
/// scrollback included — for keyboard "select to top/bottom" and "select all".
/// Alacritty's convention: the active screen is `Line(0)..Line(screen_lines)` and
/// history is *negative* down to `Line(-history_size)`, so the oldest line is
/// `Line(-(history_size))` col 0 and the last cell is `Line(screen_lines-1)` at the
/// final column. Pure so the boundary math is unit-testable without a GPU/Term.
fn selection_buffer_bounds(
    history_size: usize,
    screen_lines: usize,
    columns: usize,
) -> (kettle_core::Point, kettle_core::Point) {
    let top = kettle_core::Point::new(
        kettle_core::Line(-(history_size as i32)),
        kettle_core::Column(0),
    );
    let bottom = kettle_core::Point::new(
        kettle_core::Line(screen_lines.saturating_sub(1) as i32),
        kettle_core::Column(columns.saturating_sub(1)),
    );
    (top, bottom)
}

/// Fallback output frame budget when the platform cannot identify the current
/// monitor's refresh rate. This is the ceiling-rounded period of a 60 Hz
/// display; a flat 16 ms would schedule slightly faster than a 60 Hz
/// compositor can present.
const OUTPUT_FRAME_BUDGET: std::time::Duration = std::time::Duration::from_nanos(16_666_667);
const MIN_OUTPUT_FRAME_BUDGET: std::time::Duration = std::time::Duration::from_millis(4);
const MAX_OUTPUT_FRAME_BUDGET: std::time::Duration = std::time::Duration::from_nanos(33_333_334);
/// Small dispatch/preparation lead so a deadline does not first become runnable
/// exactly at vblank and miss the compositor's next present opportunity.
/// Deliberately sub-millisecond; comparative live validation still decides
/// whether a backend/display needs a different policy.
const OUTPUT_PRESENT_HEADROOM: std::time::Duration = std::time::Duration::from_micros(250);
const MONITOR_REFRESH_PROBE_INTERVAL: std::time::Duration = std::time::Duration::from_millis(250);
const MID_FLOOD_MIN_BUDGET: std::time::Duration = std::time::Duration::from_nanos(16_666_667);
const MID_FLOOD_MAX_BUDGET: std::time::Duration = std::time::Duration::from_nanos(33_333_334);
const DEEP_FLOOD_MIN_BUDGET: std::time::Duration = std::time::Duration::from_nanos(33_333_334);
const DEEP_FLOOD_MAX_BUDGET: std::time::Duration = std::time::Duration::from_millis(50);

/// Convert winit's monitor refresh rate (millihertz) into a per-window output
/// deadline one small dispatch lead before the frame period. The 4–33.33 ms
/// bounds cover 30–250 Hz displays while
/// preventing an implausible/driver-corrupt mode from creating a busy loop or
/// making output feel stalled. A window updates this whenever it is created,
/// moved, resized, or changes DPI, so two Kettle windows on different monitors
/// can pace independently.
fn output_frame_budget_for_refresh(refresh_millihertz: Option<u32>) -> std::time::Duration {
    let Some(refresh_millihertz) = refresh_millihertz.filter(|rate| *rate > 0) else {
        return OUTPUT_FRAME_BUDGET;
    };
    const NANOS_PER_MILLIHERTZ_PERIOD: u64 = 1_000_000_000_000;
    let nanos = NANOS_PER_MILLIHERTZ_PERIOD.div_ceil(u64::from(refresh_millihertz));
    std::time::Duration::from_nanos(nanos)
        .saturating_sub(OUTPUT_PRESENT_HEADROOM)
        .clamp(MIN_OUTPUT_FRAME_BUDGET, MAX_OUTPUT_FRAME_BUDGET)
}

fn monitor_refresh_probe_wait(
    last_probe: Option<std::time::Instant>,
    now: std::time::Instant,
    force: bool,
) -> Option<std::time::Duration> {
    if force {
        return None;
    }
    last_probe
        .map(|last| {
            MONITOR_REFRESH_PROBE_INTERVAL.saturating_sub(now.saturating_duration_since(last))
        })
        .filter(|remaining| !remaining.is_zero())
}

/// Whether an output-driven repaint should be DEFERRED
/// (coalesced) rather than painted now — true when the previous frame painted
/// less than `budget` ago. Capping PTY-output paints to one per budget lets a
/// non-atomic repaint burst (an app that doesn't bracket frames with DEC 2026
/// synchronized output, e.g. Claude Code) settle before kettle snapshots the
/// grid, avoiding the transient mid-repaint cursor jump. Pure (drift-tested in
/// `output_paint_coalesces_within_frame_budget`).
fn should_defer_output_paint(
    now: std::time::Instant,
    last_paint: Option<std::time::Instant>,
    budget: std::time::Duration,
) -> bool {
    match last_paint {
        Some(t) => now.saturating_duration_since(t) < budget,
        None => false,
    }
}

/// The output-paint budget GROWS under a sustained flood.
/// Each output-driven frame that had to be coalesced — i.e. output arriving
/// faster than the monitor-derived base budget — bumps the window's
/// `flood_paints` counter. A high-refresh window steps down no further than
/// 60 fps and then 30 fps; a 60 Hz window retains the established 30/20 fps
/// backoff. On-screen content during a flood is unreadable scrolling anyway,
/// and every frame NOT painted is one fewer O(cells) `PaneSnapshot::capture`
/// taken under the pane's `Term` mutex — the SAME mutex the PTY reader thread
/// must hold to run `Processor::advance`. At 60 fps the main thread grabs that
/// lock ~60×/s under flood, throttling the parser on a CPU-contended box;
/// stretching the budget hands the lock (and the cores) back to the reader, so
/// flood throughput rises. A brief burst (< 4 coalesced frames) never
/// throttles, so keystroke echo and short bursts stay at the monitor rate, and the
/// counter resets the instant output drops below the budget (see `redraw`), so
/// the settled post-flood frame paints within one budget. Pure; drift-tested in
/// `effective_output_budget_grows_under_sustained_flood`.
fn effective_output_budget(base: std::time::Duration, flood_paints: u32) -> std::time::Duration {
    match flood_paints {
        0..=3 => base,
        4..=15 => base
            .saturating_mul(2)
            .clamp(MID_FLOOD_MIN_BUDGET, MID_FLOOD_MAX_BUDGET),
        _ => base
            .saturating_mul(3)
            .clamp(DEEP_FLOOD_MIN_BUDGET, DEEP_FLOOD_MAX_BUDGET),
    }
}

/// Output that lands within this window of a keystroke is ECHO and paints
/// immediately, skipping the coalescer, so key repeat doesn't stutter. Long
/// enough to bridge OS key-repeat intervals (~33ms at default rates) plus
/// ConPTY echo latency; short enough that an unrelated burst (a build log
/// kicking in a beat after you pressed Enter twice) re-enters the coalescer
/// quickly.
const TYPING_ECHO_WINDOW: std::time::Duration = std::time::Duration::from_millis(150);

/// Pure (drift-tested in `typed_echo_bypasses_the_output_coalescer`): is
/// `now` inside the typing-echo window after the last keystroke?
fn typed_recently(
    now: std::time::Instant,
    last_typed: Option<std::time::Instant>,
    window: std::time::Duration,
) -> bool {
    last_typed.is_some_and(|t| now.saturating_duration_since(t) < window)
}

fn pane_snapshot_keys_match(
    cached: &[(u64, u64, usize, usize)],
    current: impl IntoIterator<Item = (u64, u64, usize, usize)>,
) -> bool {
    let mut current = current.into_iter();
    for cached_key in cached {
        match current.next() {
            Some(current_key) if *cached_key == current_key => {}
            _ => return false,
        }
    }
    current.next().is_none()
}

fn cached_pane_cursor_blinking(
    active_pane: Option<u64>,
    keys: &[(u64, u64, usize, usize)],
    snapshots: &[PaneSnapshot],
) -> Option<bool> {
    let active_pane = active_pane?;
    keys.iter()
        .position(|(pane_id, ..)| *pane_id == active_pane)
        .and_then(|index| snapshots.get(index))
        .map(|snapshot| snapshot.cursor_blinking)
}

fn pane_cursor_blinking_with<F>(
    active_pane: Option<u64>,
    keys: &[(u64, u64, usize, usize)],
    snapshots: &[PaneSnapshot],
    use_pane_snapshots: bool,
    live: F,
) -> bool
where
    F: FnOnce(u64) -> Option<bool>,
{
    let Some(active_pane) = active_pane else {
        return true;
    };
    if use_pane_snapshots {
        return cached_pane_cursor_blinking(Some(active_pane), keys, snapshots).unwrap_or(true);
    }
    live(active_pane).unwrap_or(true)
}

/// Snapshot reuse is safe only when the context menu owns the pointer.
///
/// These gesture states can mutate terminal selection, scrollback, or layout
/// from a `CursorMoved` event. Cursor movement is intentionally allowed to
/// preserve the one-shot menu-hover hint, so an active gesture must block the
/// fast path even when output generation and grid dimensions still match.
fn context_menu_snapshot_reuse_safe(ws: &WindowState) -> bool {
    !ws.selecting
        && ws.scrollbar_drag_offset.is_none()
        && ws.dragging_split.is_none()
        && !ws.held_buttons.any()
        && !ws.tab_drag_active
        && ws.tab_drag_press.is_none()
        && ws.drag_press.is_none()
        && ws.pane_drag.is_none()
        && matches!(&ws.detach_drag, crate::detach::DragState::Idle)
}

/// Pure cols/rows-that-fit math for a terminal rect, shared by `grid_of`. The
/// terminal is already clear of the pane's titlebar and lane, so only the
/// padding comes off. `max(1)` keeps a degenerate tiny pane at ≥ 1×1.
fn grid_dims_px(size: (f32, f32), cell: (f32, f32), pad: (f32, f32)) -> (usize, usize) {
    let (w, h) = size;
    let (cw, ch) = cell;
    let (pad_x, pad_y) = pad;
    let cols = ((w - pad_x * 2.0) / cw).floor().max(1.0) as usize;
    let rows = ((h - pad_y * 2.0) / ch).floor().max(1.0) as usize;
    (cols, rows)
}

/// Round a fractional renderer cell metric only after multiplying by the
/// complete grid dimension. ConPTY and Unix `winsize` pixel fields are `u16`,
/// but truncating each cell first compounds the error across every row/column
/// (9.6 px × 100 columns must report 960 px, not 900 px).
fn pty_pixel_extent(cell: f32, count: usize) -> u16 {
    let cell = if cell.is_finite() {
        f64::from(cell.max(1.0))
    } else {
        1.0
    };
    let count = count.min(u16::MAX as usize) as f64;
    (cell * count).round().clamp(1.0, f64::from(u16::MAX)) as u16
}

fn pty_pixel_size(cell: (f32, f32), grid: (usize, usize)) -> (u16, u16) {
    (
        pty_pixel_extent(cell.0, grid.0),
        pty_pixel_extent(cell.1, grid.1),
    )
}

const STARTUP_GEOMETRY_CELL_W: f64 = 8.0;
const STARTUP_GEOMETRY_CELL_H: f64 = 16.0;
const STARTUP_GEOMETRY_TAB_BAR_H: f64 = 24.0;
const STARTUP_GEOMETRY_STATUS_BAR_H: f64 = 22.0;
/// The grid a fresh window aims for when the config sets no size, and the
/// value a half-specified `window-width`/`window-height` fills its other axis
/// from. Sized for agent TUIs: Claude Code's fullscreen diff panel toggles at
/// 110 columns and auto-opens at 144, and Codex CLI lays out two columns
/// above ~120, so the classic 80x24 (or winit's ~800x600, 93 columns at the
/// default font) left every fresh window too narrow for the tools Kettle
/// targets. 160x45 baseline cells are 1296x760 logical px with the default
/// chrome: about 152x41 real cells at the 14 px font on a 1080p monitor.
pub(crate) const STARTUP_DEFAULT_COLS: u32 = 160;
pub(crate) const STARTUP_DEFAULT_ROWS: u32 = 45;
/// The default window never covers more of the monitor than this: a fixed
/// target rather than a monitor fraction keeps a 3440-wide ultrawide from
/// opening a 285-column canvas, and the fit keeps a 1366x768 laptop honest
/// (its 90 % is 1229 px, about 144 columns at the default font). There is no
/// floor on purpose: a monitor smaller than the target wins.
const STARTUP_MONITOR_WIDTH_FRACTION: f64 = 0.90;
const STARTUP_MONITOR_HEIGHT_FRACTION: f64 = 0.85;

/// Convert a startup grid into an inner-window size in **logical** pixels.
/// This runs before renderer/font metrics exist, so it intentionally uses the
/// same conservative 8x16 baseline as `geometry-hinting`; the first normal
/// layout pass reconciles exact metrics after the renderer starts. Logical
/// rather than physical so a HiDPI display gets the same grid as a 1x one; a
/// physical conversion would give a 2x display half the requested columns.
fn startup_cells_to_logical_px(cfg: &Config, cols: u32, rows: u32) -> (f64, f64) {
    let cols = cols.clamp(
        kettle_config::WINDOW_WIDTH_MIN,
        kettle_config::WINDOW_WIDTH_MAX,
    );
    let rows = rows.clamp(
        kettle_config::WINDOW_HEIGHT_MIN,
        kettle_config::WINDOW_HEIGHT_MAX,
    );

    let mut width = f64::from(cols) * STARTUP_GEOMETRY_CELL_W + f64::from(cfg.padding_x) * 2.0;
    let mut height = f64::from(rows) * STARTUP_GEOMETRY_CELL_H + f64::from(cfg.padding_y) * 2.0;

    if matches!(cfg.tab_bar, TabBarMode::Always) {
        match cfg.tab_bar_pos {
            TabBarPos::Top | TabBarPos::Bottom => height += STARTUP_GEOMETRY_TAB_BAR_H,
            TabBarPos::Left | TabBarPos::Right => {
                width += f64::from(cfg.tab_bar_width.clamp(40.0, 600.0));
            }
        }
    }

    if !matches!(cfg.status_bar, StatusBarMode::Off) {
        height += STARTUP_GEOMETRY_STATUS_BAR_H;
    }

    (width.ceil().max(1.0), height.ceil().max(1.0))
}

/// The inner size an explicit `window-width` / `window-height` asks for, in
/// logical pixels, or `None` when the config sets neither. A missing axis
/// comes from the default grid so `window-width = 200` alone still opens
/// tall enough for an agent TUI. Explicit values are honoured as typed: the
/// monitor fit below applies to the default only.
fn startup_inner_size_px(cfg: &Config) -> Option<(u32, u32)> {
    if cfg.window_width.is_none() && cfg.window_height.is_none() {
        return None;
    }
    let (width, height) = startup_cells_to_logical_px(
        cfg,
        cfg.window_width.unwrap_or(STARTUP_DEFAULT_COLS),
        cfg.window_height.unwrap_or(STARTUP_DEFAULT_ROWS),
    );
    Some((width as u32, height as u32))
}

/// The fresh-window default when the config sets no size: the default grid
/// with this config's chrome, fitted to the monitor it will most likely open
/// on. `monitor_logical` is the monitor's logical size; `None` (no monitor
/// enumerable yet) keeps the bare target.
fn default_startup_inner_size(cfg: &Config, monitor_logical: Option<(f64, f64)>) -> (f64, f64) {
    let (width, height) =
        startup_cells_to_logical_px(cfg, STARTUP_DEFAULT_COLS, STARTUP_DEFAULT_ROWS);
    let Some((monitor_w, monitor_h)) = monitor_logical else {
        return (width, height);
    };
    let max_w = (monitor_w * STARTUP_MONITOR_WIDTH_FRACTION)
        .floor()
        .max(1.0);
    let max_h = (monitor_h * STARTUP_MONITOR_HEIGHT_FRACTION)
        .floor()
        .max(1.0);
    (width.min(max_w), height.min(max_h))
}

/// The one startup size both window constructors use, in logical pixels:
/// the configured grid when the user set one, else the monitor-fitted default.
fn startup_inner_size(cfg: &Config, monitor: Option<StartupMonitor>) -> (f64, f64) {
    match startup_inner_size_px(cfg) {
        Some((w, h)) => (f64::from(w), f64::from(h)),
        None => default_startup_inner_size(cfg, monitor.map(|m| m.logical)),
    }
}

/// The surface size, in physical pixels, whose content area holds exactly
/// `grid` cells of `cell` inside `pad` and the chrome `bands` describe.
///
/// `content_rect_for_with_strip` subtracts fixed bands, so their total is read
/// off a probe surface and added back. Half a pixel of slack before rounding
/// up keeps float error from costing a column; the slack stays under a cell.
fn surface_for_grid(
    grid: (usize, usize),
    cell: (f32, f32),
    pad: (f32, f32),
    bands: ContentBands,
    tab_bar_pos: kettle_config::TabBarPos,
    status_bar: kettle_config::StatusBarMode,
    strip_w: f32,
) -> (u32, u32) {
    const PROBE: u32 = 1 << 16;
    let (_, _, content_w, content_h) =
        content_rect_for_with_strip((PROBE, PROBE), bands, tab_bar_pos, status_bar, strip_w);
    let chrome_w = PROBE as f32 - content_w;
    let chrome_h = PROBE as f32 - content_h;
    let width = grid.0 as f32 * cell.0 + pad.0 * 2.0 + chrome_w;
    let height = grid.1 as f32 * cell.1 + pad.1 * 2.0 + chrome_h;
    (
        (width + 0.5).ceil().max(1.0) as u32,
        (height + 0.5).ceil().max(1.0) as u32,
    )
}

/// What the startup sizing needs to know about the monitor a fresh window
/// will most likely land on.
#[derive(Debug, Clone, Copy, PartialEq)]
pub(crate) struct StartupMonitor {
    /// Logical size (physical pixels divided by the scale factor).
    logical: (f64, f64),
    scale: f64,
}

impl StartupMonitor {
    /// CoreGraphics points converted exactly as winit's macOS monitor size.
    #[cfg(any(target_os = "macos", test))]
    pub(crate) fn from_display_points(width: usize, height: usize, scale: f64) -> Self {
        let physical = winit::dpi::PhysicalSize::<u32>::from_logical::<_, f64>(
            (width as f64, height as f64),
            scale,
        );
        Self::from_physical(physical.width, physical.height, scale)
    }

    fn from_physical(width: u32, height: u32, scale: f64) -> Self {
        let scale = if scale.is_finite() && scale > 0.0 {
            scale
        } else {
            1.0
        };
        Self {
            logical: (f64::from(width) / scale, f64::from(height) / scale),
            scale,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StartupPlan {
    launch_override: bool,
    may_restore: bool,
    pre_launch: bool,
}

fn startup_plan(options: &crate::Options, cfg: &Config) -> StartupPlan {
    let launch_override = options.command.is_some() || options.cwd.is_some();
    let may_restore = !launch_override
        && (options.tab_handoff_fd.is_some()
            || options.tab_handoff.is_some()
            || options.layout.is_some()
            || should_restore_session(options.restore, cfg.restore_session));
    StartupPlan {
        launch_override,
        may_restore,
        pre_launch: !may_restore
            && matches!(
                cfg.window_state,
                kettle_config::WindowState::Normal | kettle_config::WindowState::Hidden
            )
            && cfg.window_position_x.is_none()
            && cfg.window_position_y.is_none(),
    }
}

fn fits_monitor(surface: (u32, u32), monitor: Option<StartupMonitor>) -> bool {
    let (width, height) = surface;
    monitor.is_some_and(|m| {
        f64::from(width) <= (m.logical.0 * STARTUP_MONITOR_WIDTH_FRACTION).floor() * m.scale + 1.0
            && f64::from(height)
                <= (m.logical.1 * STARTUP_MONITOR_HEIGHT_FRACTION).floor() * m.scale + 1.0
    })
}

/// The monitor to fit a fresh window to: the primary monitor where the
/// platform has one, else the largest by area (Wayland has no primary; a
/// mixed multi-monitor setup then gets a deterministic answer instead of
/// whichever output the compositor listed first).
fn startup_monitor(event_loop: &ActiveEventLoop) -> Option<StartupMonitor> {
    let describe = |m: winit::monitor::MonitorHandle| {
        let size = m.size();
        StartupMonitor::from_physical(size.width, size.height, m.scale_factor())
    };
    event_loop.primary_monitor().map(describe).or_else(|| {
        event_loop
            .available_monitors()
            .map(describe)
            .max_by(|a, b| {
                let area = |m: &StartupMonitor| m.logical.0 * m.logical.1;
                area(a).total_cmp(&area(b))
            })
    })
}

fn cursor_in_tab_bar_band(y: f32, bar_h: f32, surface_h: f32, pos: TabBarPos) -> bool {
    if bar_h <= 0.0 {
        return false;
    }
    // Left/Right strips span the full window height, so every in-window y is in
    // the band. `cursor_in_tab_bar` checks x against the strip's edge.
    match pos {
        TabBarPos::Top => y >= 0.0 && y < bar_h,
        TabBarPos::Bottom => y >= (surface_h - bar_h) && y <= surface_h,
        TabBarPos::Left | TabBarPos::Right => y >= 0.0 && y <= surface_h,
    }
}

/// Sibling of `cursor_in_tab_bar_band` for the status bar, so the
/// chrome-cursor logic treats both bars uniformly. The status strip is outside
/// every pane rect and the tab-bar band, so without this check hovering it
/// falls through to the "over a pane" branch and shows the I-beam.
fn cursor_in_status_bar_band(
    y: f32,
    bar_h: f32,
    surface_h: f32,
    pos: kettle_config::StatusBarMode,
) -> bool {
    if bar_h <= 0.0 {
        return false;
    }
    match pos {
        kettle_config::StatusBarMode::Off => false,
        kettle_config::StatusBarMode::Top => y >= 0.0 && y < bar_h,
        kettle_config::StatusBarMode::Bottom => y >= (surface_h - bar_h) && y <= surface_h,
    }
}

/// Auto-scroll rate when a selection reaches or passes a pane's vertical edge.
/// A six-point inner drag zone keeps full-height panes scrollable even though
/// the pointer cannot move below their client area.
///
/// Speed scales with how far past the edge the cursor sits — a small
/// overshoot crawls (1 line/frame), a big one (40+ px) chases at 3 lines
/// per frame. Pure so the cadence is unit-tested without spinning up a
/// renderer or PTY.
fn selection_autoscroll_lines(
    y: f32,
    rect_top: f32,
    rect_bottom: f32,
    scale_factor: f32,
    selection_dragged: bool,
) -> i32 {
    const EDGE_ZONE_PT: f32 = 6.0;

    let pane_height = rect_bottom - rect_top;
    if !selection_dragged || pane_height <= 0.0 {
        return 0;
    }
    let scale_factor = if scale_factor.is_finite() && scale_factor > 0.0 {
        scale_factor
    } else {
        1.0
    };
    let edge_zone = (EDGE_ZONE_PT * scale_factor).min(pane_height * 0.25);
    let (overshoot, direction) = if y < rect_top || y <= rect_top + edge_zone {
        ((rect_top - y).max(0.0), 1)
    } else if y > rect_bottom || y >= rect_bottom - edge_zone {
        ((y - rect_bottom).max(0.0), -1)
    } else {
        return 0;
    };
    // Magnitude → 1..=3 lines/frame ladder.
    let mag = if overshoot >= 40.0 {
        3
    } else if overshoot >= 10.0 {
        2
    } else {
        1
    };
    direction * mag
}

/// Whether pointer travel since the selection press is large enough to count
/// as a drag. Native backends may emit a cursor-moved event after mouse-down at
/// the same (or fractionally rounded) coordinate, so event arrival alone is
/// not evidence that the user dragged. The threshold is in logical points and
/// converted to physical pixels for the addressed window.
fn selection_drag_motion_started(
    origin: Option<winit::dpi::PhysicalPosition<f64>>,
    cursor: winit::dpi::PhysicalPosition<f64>,
    scale_factor: f64,
) -> bool {
    const DRAG_START_PT: f64 = 2.0;

    let Some(origin) = origin else {
        return false;
    };
    if !(origin.x.is_finite()
        && origin.y.is_finite()
        && cursor.x.is_finite()
        && cursor.y.is_finite())
    {
        return false;
    }
    let scale_factor = if scale_factor.is_finite() && scale_factor > 0.0 {
        scale_factor
    } else {
        1.0
    };
    let threshold = DRAG_START_PT * scale_factor;
    let dx = cursor.x - origin.x;
    let dy = cursor.y - origin.y;
    dx * dx + dy * dy >= threshold * threshold
}

fn note_selection_drag_motion(ws: &mut WindowState) {
    if ws.selection_dragged {
        return;
    }
    let scale_factor = ws
        .window
        .as_ref()
        .map_or(1.0, |window| window.scale_factor());
    ws.selection_dragged =
        selection_drag_motion_started(ws.selection_drag_origin, ws.cursor, scale_factor);
}

/// Which vertical edge an in-progress selection most likely crossed when the
/// backend reports `CursorLeft` without an out-of-client coordinate. Corners
/// resolve vertically on ties because horizontal selection overflow does not
/// scroll, while losing the vertical intent freezes the gesture entirely. A
/// window exit only latches after measured drag travel; otherwise a press on
/// the last client pixel plus sub-threshold outward jitter could scroll.
fn selection_leave_edge(selection_dragged: bool, x: f32, y: f32, width: f32, height: f32) -> i8 {
    if !selection_dragged || !(x.is_finite() && y.is_finite() && width > 0.0 && height > 0.0) {
        return 0;
    }
    let top = y.max(0.0);
    let bottom = (height - y).max(0.0);
    let left = x.max(0.0);
    let right = (width - x).max(0.0);
    if top <= bottom && top <= left && top <= right {
        1
    } else if bottom <= top && bottom <= left && bottom <= right {
        -1
    } else {
        0
    }
}

fn arm_selection_gesture(ws: &mut WindowState, pane_id: u64, button: u8) {
    // A fresh grid gesture owns Copy, including Shift+right-click extension.
    if ws.search.open {
        ws.search.editor.clear_selection();
    }
    ws.selecting = true;
    ws.selecting_pane = Some(pane_id);
    ws.selection_autoscroll_edge = 0;
    ws.selection_dragged = false;
    ws.selection_drag_origin = Some(ws.cursor);
    ws.selection_button = Some(button);
}

fn selection_release_matches(owner: Option<u8>, button: u8) -> bool {
    owner == Some(button)
}

fn selection_copy_owner(selecting: bool, pane_id: Option<u64>) -> Option<u64> {
    if selecting { pane_id } else { None }
}

fn clear_selection_gesture(ws: &mut WindowState) {
    ws.selecting = false;
    ws.selecting_pane = None;
    ws.selection_autoscroll_edge = 0;
    ws.selection_dragged = false;
    ws.selection_drag_origin = None;
    ws.selection_button = None;
}

fn take_window_close_request(pending: &mut std::collections::BTreeSet<u64>, seq: u64) -> bool {
    pending.remove(&seq)
}

/// Select the terminal pane addressed by a wheel event without mutating
/// keyboard focus. A pane under the pointer wins; chrome, gaps and coordinates
/// outside the client area fall back to the focused pane.
fn wheel_target_at(
    layout: &[(u64, Rect)],
    focused: Option<u64>,
    x: f32,
    y: f32,
) -> Option<(u64, Rect)> {
    layout
        .iter()
        .copied()
        .find(|&(_, (rx, ry, rw, rh))| x >= rx && x < rx + rw && y >= ry && y < ry + rh)
        .or_else(|| {
            let focused = focused?;
            layout.iter().copied().find(|(pane, _)| *pane == focused)
        })
}

/// Render the OS window title from the user's `window-title-format`
/// template with the active pane's title / cwd / 1-based tab index. While
/// the pane title is still the initial placeholder ("kettle") and the cwd
/// is known, substitute the cwd's basename so `~/Repos/kettle` shows up
/// as `kettle — kettle` and `~/Documents` as `Documents — kettle`,
/// matching the cwd-basename tab-title fallback so the OS window title and
/// the in-app tab agree pre-OSC 2. Real shell-set titles still win the
/// moment they arrive.
fn window_title(template: &str, pane_title: &str, cwd: &str, tab: usize) -> String {
    let home = crate::mux::home_dir_string();
    window_title_with_home(template, pane_title, cwd, home.as_deref(), tab)
}

/// Expand a leading `~` / `~/…` in a config-file path to the user's home dir.
/// Config values (unlike `--record-dir` / `KETTLE_RECORD_DIR`, which a shell
/// expands before Kettle sees them) are never shell-expanded, so a literal
/// `record-dir = ~/.cache/kettle/records` would otherwise create a `~`-named
/// directory under the launch CWD. Falls back to the raw path if `HOME` /
/// `USERPROFILE` is unset.
fn expand_user_path(path: &std::path::Path) -> std::path::PathBuf {
    expand_user_path_with(path, crate::mux::home_dir_string())
}

/// Pure core of [`expand_user_path`], parameterized on the home dir for testing.
fn expand_user_path_with(path: &std::path::Path, home: Option<String>) -> std::path::PathBuf {
    let Some(s) = path.to_str() else {
        return path.to_path_buf();
    };
    if (s == "~" || s.starts_with("~/"))
        && let Some(home) = home.filter(|h| !h.is_empty())
    {
        let mut expanded = std::path::PathBuf::from(home);
        if let Some(rest) = s.strip_prefix("~/") {
            expanded.push(rest);
        }
        return expanded;
    }
    path.to_path_buf()
}

const RECORDING_TITLE_SUFFIX: &str = " [REC]";
// A distinct suffix while RAW keystroke capture is active, so literal-keystroke
// (potentially password-capturing) recording is never visually silent.
const RECORDING_RAW_TITLE_SUFFIX: &str = " [REC RAW]";
const RECORDING_LIMIT_TITLE_SUFFIX: &str = " [REC LIMIT]";
const RECORDING_OVERLOAD_TITLE_SUFFIX: &str = " [REC INCOMPLETE]";
const RECORDING_ERROR_TITLE_SUFFIX: &str = " [REC ERROR]";

fn recording_window_title(
    mut title: String,
    status: Option<crate::dev_record::RecordStatus>,
    raw_input: bool,
) -> String {
    match status {
        Some(crate::dev_record::RecordStatus::Recording) => title.push_str(if raw_input {
            RECORDING_RAW_TITLE_SUFFIX
        } else {
            RECORDING_TITLE_SUFFIX
        }),
        Some(crate::dev_record::RecordStatus::LimitReached) => {
            title.push_str(RECORDING_LIMIT_TITLE_SUFFIX)
        }
        Some(crate::dev_record::RecordStatus::Overloaded) => {
            title.push_str(RECORDING_OVERLOAD_TITLE_SUFFIX)
        }
        Some(crate::dev_record::RecordStatus::IoError) => {
            title.push_str(RECORDING_ERROR_TITLE_SUFFIX)
        }
        None => {}
    }
    title
}

fn effective_record_status(
    recorder: Option<crate::dev_record::RecordStatus>,
    start_failed: bool,
) -> Option<crate::dev_record::RecordStatus> {
    recorder.or(start_failed.then_some(crate::dev_record::RecordStatus::IoError))
}

fn activation_recording_available(
    required: bool,
    status: Option<crate::dev_record::RecordStatus>,
) -> bool {
    !required || status == Some(crate::dev_record::RecordStatus::Recording)
}

fn window_title_with_home(
    template: &str,
    pane_title: &str,
    cwd: &str,
    home: Option<&str>,
    tab: usize,
) -> String {
    let t_raw = pane_title.trim();
    let pane_placeholder = t_raw.is_empty() || t_raw == "kettle";
    let cwd_basename = std::path::Path::new(cwd)
        .file_name()
        .and_then(|s| s.to_str())
        .filter(|s| !s.is_empty());
    let cwd_display = crate::mux::abbreviate_home(cwd, home);
    // Until the shell sets a real title, use the cwd basename, matching the
    // tab-title fallback so the OS window title and the in-app tab agree
    // pre-OSC 2. Only the pane title is checked against the "kettle"
    // placeholder; a cwd basename of "kettle" (`~/Repos/kettle`) is a real
    // directory and still fills the template.
    if pane_placeholder {
        return match cwd_basename {
            Some(name) => {
                let tab = tab.to_string();
                kettle_config::template::fill(
                    template,
                    &[("title", name), ("cwd", &cwd_display), ("tab", &tab)],
                )
            }
            None => "kettle".to_string(),
        };
    }
    if !cwd.is_empty()
        && let Some(label) = crate::mux::cwd_label_for_shell_title(t_raw, cwd, home)
        && let Some(path) = label.path.as_deref()
    {
        let tab = tab.to_string();
        return kettle_config::template::fill(
            template,
            &[("title", path), ("cwd", &cwd_display), ("tab", &tab)],
        );
    }
    let tab = tab.to_string();
    kettle_config::template::fill(
        template,
        &[("title", t_raw), ("cwd", &cwd_display), ("tab", &tab)],
    )
}

/// Vi-mode UI ownership. Cursor, viewport following, and selection coordinates
/// live in alacritty_terminal's `Term`; that engine rotates them with output,
/// history eviction, and reflow. Keeping only the owning pane id and visual
/// state here prevents a second coordinate model from drifting.
#[derive(Debug, Clone, Copy)]
pub(crate) struct ViState {
    pane_id: u64,
    visual: bool,
}

/// Truncate a status-bar title to `max` chars, appending `…` so the elision
/// is visible. Counts chars, not bytes, so UTF-8 multibyte glyphs aren't split.
/// A title that already fits is returned unchanged.
///
/// Without this, a long pane title wraps past the status strip's 1-cell
/// height and the rest is hidden with no indication.
fn cap_title_for_status_bar(title: &str, max: usize) -> String {
    if title.chars().count() <= max {
        return title.to_string();
    }
    let mut out: String = title.chars().take(max).collect();
    out.push('…');
    out
}

/// Peacock: a STABLE per-window seed for `accent-color = auto`,
/// hashed from the window's working directory (the launch `-d DIR`, else the
/// process cwd). Same project → same seed → same accent across launches;
/// different projects → different accents. Pure given the cwd.
fn accent_seed_from_cwd(cwd: Option<&std::path::Path>) -> u64 {
    use std::hash::{Hash, Hasher};
    let dir = cwd
        .map(|p| p.to_path_buf())
        .or_else(|| std::env::current_dir().ok())
        .unwrap_or_default();
    // Canonicalize so every spelling of the same project
    // (`-d .`, `-d C:\proj`, a relative path, a trailing slash) hashes to the
    // SAME seed — the documented "same project → same accent" stability.
    // Falls back to the raw path when it doesn't resolve (nonexistent dir).
    let dir = std::fs::canonicalize(&dir).unwrap_or(dir);
    let mut h = std::collections::hash_map::DefaultHasher::new();
    dir.hash(&mut h);
    h.finish()
}

/// Terminator parity ("Read only"):
/// the per-pane titlebar label, composed from the pane's state badges —
/// `[RO] ` while the pane is read-only (input dropped before the PTY), then
/// the `agent-badge` when an agent control connection has the pane attached.
/// Pure (unit-tested). No badges → the title unchanged (zero cost for the
/// common case).
#[cfg(test)]
fn compose_pane_title(badge: &str, attached: bool, read_only: bool, title: &str) -> String {
    let prefix = pane_title_prefix(badge, attached, read_only);
    if prefix.is_empty() {
        title.to_string()
    } else {
        format!("{prefix}{title}")
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PaneTitleParts {
    prefix: String,
    title: String,
    path: Option<String>,
}

/// The pane titlebar's mark for media on the pane's shelf that the user has
/// not looked at yet: `▣` and how many, or nothing.
fn media_shelf_badge(unseen: usize) -> String {
    if unseen == 0 {
        String::new()
    } else {
        format!("▣{unseen} ")
    }
}

fn pane_title_prefix(badge: &str, attached: bool, read_only: bool) -> String {
    let agent = attached && !badge.is_empty();
    if !read_only && !agent {
        return String::new();
    }
    let mut out = String::new();
    if read_only {
        out.push_str("[RO] ");
    }
    if agent {
        out.push_str(badge);
    }
    out
}

fn pane_title_parts(
    agent_badge: &str,
    attached: bool,
    read_only: bool,
    pane_title: &str,
    placeholder: bool,
    cwd: Option<&str>,
    home: Option<&str>,
) -> PaneTitleParts {
    let prefix = pane_title_prefix(agent_badge, attached, read_only);
    let raw = pane_title.trim();
    if let Some(cwd) = cwd.filter(|c| !c.is_empty()) {
        if placeholder || raw.is_empty() {
            let path = crate::mux::abbreviate_home(cwd, home);
            let title = cwd
                .rsplit(['/', '\\'])
                .find(|s| !s.is_empty())
                .unwrap_or(raw)
                .to_string();
            return PaneTitleParts {
                prefix,
                title,
                path: Some(path),
            };
        }
        if let Some(label) = crate::mux::cwd_label_for_shell_title(raw, cwd, home) {
            return PaneTitleParts {
                prefix,
                title: label.text,
                path: label.path,
            };
        }
    }
    PaneTitleParts {
        prefix,
        title: if raw.is_empty() {
            "kettle".to_string()
        } else {
            raw.to_string()
        },
        path: None,
    }
}

/// Does this OSC 2 title look like the bogus full-exe-path that
/// conhost/ConPTY injects at startup for a native Windows shell, rather than a
/// title the program set deliberately? When a stock `pwsh`/`cmd` launches,
/// ConPTY seeds the window title with the launched executable's absolute path
/// (e.g. `C:\Program Files\…\pwsh.exe`); kettle would otherwise show that ugly
/// path and never fall back to the working directory.
///
/// Returns true when the title is that injected launch path:
///   - with an explicit launch `argv`, the title must equal argv0 (case-
///     insensitive, `/`+`\` normalized) OR be an absolute `X:\…\<leaf>.exe`
///     whose leaf matches argv0's leaf — tight, so a program that sets its own
///     title to some other path is never mistaken for the injection;
///   - for the default shell (empty `argv`, argv0 unknown), any absolute
///     `X:\…\*.exe` path qualifies — safe because the caller only consults this
///     while the pane title is still the placeholder (the first title seen), and
///     a real shell title is virtually never a bare absolute `.exe` path.
///
/// Pure (unit-tested). Never fires on Unix/macOS — those shells don't emit an
/// absolute-Windows-path title and conhost doesn't exist there.
fn is_conhost_startup_title(title: &str, argv: &[String]) -> bool {
    let t = title.trim().trim_matches('"');
    if t.is_empty() {
        return false;
    }
    let tl = t.replace('/', "\\").to_ascii_lowercase();
    let looks_abs_exe = {
        let b = tl.as_bytes();
        b.len() >= 3 && b[1] == b':' && b[2] == b'\\' && tl.ends_with(".exe")
    };
    let leaf = |s: &str| {
        s.rsplit(['/', '\\'])
            .find(|p| !p.is_empty())
            .unwrap_or(s)
            .to_ascii_lowercase()
    };
    match argv.first().map(String::as_str) {
        Some(arg0) => {
            let a_n = arg0.replace('/', "\\").to_ascii_lowercase();
            tl == a_n || (looks_abs_exe && leaf(t) == leaf(arg0))
        }
        None => looks_abs_exe,
    }
}

/// Is this argv launching `ssh` (by argv0 basename)? An ssh pane has no
/// local working directory, so the native-cwd poll skips it (a native read would
/// surface kettle's launch dir, not the remote host's). OSC 7 from the remote
/// shell remains the only meaningful cwd there.
fn argv_is_ssh(argv: &[String]) -> bool {
    argv.first()
        .map(|p| {
            let last = p.rsplit(['/', '\\']).next().unwrap_or(p);
            last.eq_ignore_ascii_case("ssh") || last.eq_ignore_ascii_case("ssh.exe")
        })
        .unwrap_or(false)
}

fn update_window_remote_contexts(
    snapshot: &kettle_remote::RemoteProbeSnapshot,
    applied: &mut std::collections::HashMap<(u64, u32), kettle_remote::RemoteProbe>,
    ws: &mut WindowState,
) -> bool {
    let mut changed = false;
    for (&pane_id, pane) in &mut ws.mux.panes {
        let Some(pid) = pane.term.child_pid() else {
            continue;
        };
        let Some(probe) = snapshot.probes.get(&pid) else {
            continue;
        };
        let context_changed = applied.get(&(pane_id, pid)).is_none_or(|previous| {
            previous.remote != probe.remote
                || previous.native_cwd != probe.native_cwd
                || previous.foreground_shell != probe.foreground_shell
        });
        stage_applied_remote_probe(applied, pane_id, pid, probe);
        if context_changed {
            pane.term.set_native_cwd(probe.native_cwd.clone());
        }
        if probe.remote != pane.remote_context {
            apply_remote_title_transition(
                &mut pane.title,
                &mut pane.title_is_placeholder,
                &mut pane.title_origin,
                &mut pane.title_before_remote,
                probe.remote.as_ref(),
            );
            pane.remote_context = probe.remote.clone();
            changed = true;
        }
        if probe.foreground_process != pane.foreground_process {
            pane.foreground_process = probe.foreground_process.clone();
        }
        // Foreground argv drives input policy but has no visual representation;
        // changing commands must not schedule a title sync and redraw at 5 Hz.
        changed |= context_changed;
    }
    changed
}

/// May a shell-emitted OSC 0/2 title replace the pane's current one?
///
/// Everything except a hand-set title, which the user typed and expects to
/// stay. Shells emit OSC 0/2 on every prompt, so without this rule a manual
/// name survived less than a second.
///
/// A REMOTE title still takes precedence over a manual one, deliberately:
/// `apply_remote_title_transition` saves the previous title and restores it
/// when the remote context ends, so the manual name comes back on exit rather
/// than being lost, and while connected the host is worth showing.
fn osc_title_may_replace(origin: PaneTitleOrigin) -> bool {
    origin != PaneTitleOrigin::Manual
}

/// Apply a shell-driven title change: `Some(t)` for an OSC 0/2 set, `None`
/// for a reset.
///
/// Both doors need the same two rules, which is why they share one function:
///
/// * A `Manual` title is the user's, and the shell may not touch it by either
///   door. Shells also emit reset sequences at prompts, so gating only the set
///   would keep a hand-set name alive only until the next reset.
/// * Inside a remote context the change IS applied (the remote shell's own
///   title, `user@host:~/work`, beats kettle's synthetic label), but the origin
///   stays `Remote` and the saved pre-remote title is left alone. Overwriting
///   the saved title would lose the title to restore on disconnect. Demoting
///   the origin would stop `apply_remote_title_transition` from recognising the
///   pane as leaving a remote context, leaving the remote host's name on a
///   local pane after ssh exits.
fn apply_shell_title(
    title: &mut String,
    title_is_placeholder: &mut bool,
    origin: &mut PaneTitleOrigin,
    title_before_remote: &mut Option<(String, PaneTitleOrigin)>,
    new: Option<&str>,
) {
    if !osc_title_may_replace(*origin) {
        return;
    }
    let in_remote = *origin == PaneTitleOrigin::Remote;
    match new {
        // Sanitize before storing; this string flows to
        // set_title(), the tab label, and the status bar.
        Some(t) => {
            *title = sanitize_title(t);
            *title_is_placeholder = false;
        }
        None => {
            *title = "kettle".into();
            *title_is_placeholder = true;
        }
    }
    if in_remote {
        return;
    }
    *origin = match new {
        Some(_) => PaneTitleOrigin::Osc,
        None => PaneTitleOrigin::Placeholder,
    };
    *title_before_remote = None;
}

fn apply_remote_title_transition(
    title: &mut String,
    title_is_placeholder: &mut bool,
    origin: &mut PaneTitleOrigin,
    title_before_remote: &mut Option<(String, PaneTitleOrigin)>,
    remote: Option<&kettle_remote::RemoteContext>,
) {
    if let Some(context) = remote {
        if *origin != PaneTitleOrigin::Remote {
            *title_before_remote = Some((title.clone(), *origin));
        }
        *title = sanitize_title(&kettle_remote::format_remote_title(context));
        *title_is_placeholder = false;
        *origin = PaneTitleOrigin::Remote;
        return;
    }

    if *origin == PaneTitleOrigin::Remote {
        let (restored_title, restored_origin) = title_before_remote
            .take()
            .unwrap_or_else(|| ("kettle".to_string(), PaneTitleOrigin::Placeholder));
        *title = restored_title;
        *title_is_placeholder = restored_origin == PaneTitleOrigin::Placeholder;
        *origin = restored_origin;
    } else {
        *title_before_remote = None;
    }
}

fn stage_applied_remote_probe(
    applied: &mut std::collections::HashMap<(u64, u32), kettle_remote::RemoteProbe>,
    pane_id: u64,
    pid: u32,
    probe: &kettle_remote::RemoteProbe,
) -> bool {
    let key = (pane_id, pid);
    if applied.get(&key) == Some(probe) {
        false
    } else {
        applied.insert(key, probe.clone());
        true
    }
}

fn argv_is_nonlocal_client(argv: &[String]) -> bool {
    if crate::mux::argv_is_wsl(argv) || argv_is_ssh(argv) {
        return true;
    }
    let Some(argv0) = argv.first() else {
        return false;
    };
    let basename = argv0
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(argv0)
        .to_ascii_lowercase();
    let basename = basename.strip_suffix(".exe").unwrap_or(&basename);
    matches!(basename, "docker" | "podman" | "kubectl" | "lxc-attach")
}

fn remote_probe_target(pane: &crate::mux::Pane) -> Option<kettle_remote::RemoteProbeTarget> {
    #[cfg(unix)]
    let foreground_pid = pane.term.foreground_process_group().ok();
    #[cfg(not(unix))]
    let foreground_pid = None;
    Some(kettle_remote::RemoteProbeTarget {
        pid: pane.term.child_pid()?,
        foreground_pid,
        allow_native_cwd: !argv_is_nonlocal_client(&pane.argv),
    })
}

fn stage_remote_targets(
    scratch: &mut Vec<kettle_remote::RemoteProbeTarget>,
    checked_out: impl IntoIterator<Item = Option<kettle_remote::RemoteProbeTarget>>,
    stored_windows: impl IntoIterator<Item = Option<kettle_remote::RemoteProbeTarget>>,
) {
    scratch.clear();
    scratch.extend(checked_out.into_iter().flatten());
    scratch.extend(stored_windows.into_iter().flatten());
}

/// Map a click count + the Alt modifier to a selection type: double =
/// word, triple = line, single = a normal drag, and Alt+single =
/// rectangular/block selection (iTerm2/Alacritty/WezTerm parity).
fn selection_kind(clicks: u8, alt: bool) -> kettle_core::SelectionType {
    use kettle_core::SelectionType::*;
    match clicks {
        2 => Semantic,
        3 => Lines,
        _ if alt => Block,
        _ => Simple,
    }
}

/// Compile each configured `OutputTrigger`'s pattern to a
/// `regex::Regex`, log + drop invalid patterns. Pure helper so the
/// App constructor + `reload_config` path use exactly the same
/// regex set after a config edit. An empty input returns an empty
/// vec — `match_triggers` short-circuits on that.
fn compile_triggers(
    triggers: &[kettle_config::OutputTrigger],
) -> Vec<(regex::Regex, kettle_config::TriggerAction)> {
    let mut out = Vec::with_capacity(triggers.len());
    for t in triggers {
        // Multi-line: the snapshot joins viewport rows with '\n', and `^` / `$`
        // should anchor to each row.
        match regex::RegexBuilder::new(&t.pattern)
            .multi_line(true)
            .build()
        {
            Ok(re) => out.push((re, t.action.clone())),
            Err(e) => {
                log::warn!("trigger pattern {:?} failed to compile: {e}", t.pattern);
            }
        }
    }
    out
}

const CONFIG_RELOAD_DEBOUNCE: std::time::Duration = std::time::Duration::from_millis(75);

/// Should a live config reload fire a "malformed values ignored" notification?
/// Only when the diagnostics are non-empty AND differ from the set surfaced on
/// the previous reload — kettle's own settings-persistence writes (theme /
/// preferences toggles) reload the config, and an unchanged malformed set must
/// not re-notify on every one of them. Pure so the edge-trigger rule is tested.
fn should_notify_malformed(new: &[String], last: &[String]) -> bool {
    !new.is_empty() && new != last
}

/// Filesystem watchers observe the containing directory so atomic replacement
/// works across platforms. Only content/name changes to the exact file are
/// actionable. Accepting `Access(Open)` creates a read -> reload -> read
/// feedback loop on Linux inotify; accepting `Modify(Metadata)` creates the
/// same loop on macOS because opening a private state file re-applies its mode.
fn watcher_event_matches(event: &notify::Event, watched: &std::path::Path) -> bool {
    use notify::EventKind;
    use notify::event::ModifyKind;

    if !event.paths.iter().any(|path| path == watched) {
        return false;
    }
    match event.kind {
        EventKind::Any | EventKind::Create(_) | EventKind::Remove(_) => true,
        EventKind::Modify(ModifyKind::Metadata(_)) => false,
        EventKind::Modify(_) => true,
        EventKind::Access(_) | EventKind::Other => false,
    }
}

/// Queue at most one event until the main thread re-arms the latch. Re-open it
/// when the event loop has already closed so a failed send cannot strand the
/// watcher in a permanently pending state.
fn queue_watcher_event(
    pending: &std::sync::atomic::AtomicBool,
    send: impl FnOnce() -> bool,
) -> bool {
    use std::sync::atomic::Ordering;

    if pending
        .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
        .is_err()
    {
        return false;
    }
    if send() {
        true
    } else {
        pending.store(false, Ordering::Release);
        false
    }
}

fn registered_watcher<W, E>(
    mut watcher: W,
    register: impl FnOnce(&mut W) -> Result<(), E>,
) -> Result<W, E> {
    register(&mut watcher)?;
    Ok(watcher)
}

fn prepare_config_directory(path: &std::path::Path, trust: ConfigTrust) -> std::io::Result<()> {
    if trust == ConfigTrust::ExplicitPath {
        return Ok(());
    }
    let directory = path.parent().ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("config path has no parent: {}", path.display()),
        )
    })?;
    if let Err(error) = kettle_state::create_private_dirs(directory) {
        log::debug!(
            "config directory repair skipped for {}: {error}",
            directory.display()
        );
    }
    kettle_state::validate_trusted_directory(directory)
}

fn resolved_init_lua_script(
    explicit: Option<std::path::PathBuf>,
    default_config: Option<std::path::PathBuf>,
) -> Option<(std::path::PathBuf, ConfigTrust)> {
    explicit
        .map(|path| (path, ConfigTrust::ExplicitPath))
        .or_else(|| {
            default_config
                .and_then(|path| path.parent().map(|dir| dir.join("init.lua")))
                .filter(|path| path.exists())
                .map(|path| (path, ConfigTrust::VerifyDirectory))
        })
}

fn reloaded_font_size(configured_changed: bool, configured: f32, runtime: Option<f32>) -> f32 {
    if configured_changed {
        configured
    } else {
        runtime.unwrap_or(configured)
    }
}

/// Scan `text` for any compiled trigger match, returning the
/// first action that fires. Pure helper used by `App::run_triggers` and
/// the drift guard. Returns `None` when no trigger fires so the caller
/// can skip the urgency-attention call.
fn match_triggers(
    text: &str,
    triggers: &[(regex::Regex, kettle_config::TriggerAction)],
) -> Option<kettle_config::TriggerAction> {
    triggers.iter().find_map(|(re, action)| {
        let caps = re.captures(text)?;
        Some(match action {
            // The matched pattern's capture groups substitute into the
            // command's argv (`{0}` whole match, `{1}`… numbered groups),
            // like `cmd.format(*groups)` in Terminator's `run_cmd_on_match.py`.
            kettle_config::TriggerAction::RunCommand(argv) => {
                kettle_config::TriggerAction::RunCommand(substitute_trigger_groups(argv, &caps))
            }
            other => other.clone(),
        })
    })
}

/// Replace `{0}`/`{1}`… in each argv element with the trigger match's
/// capture groups. `{0}` is the whole match and a non-participating group
/// substitutes empty. An out-of-range reference like `{9}` with two groups
/// stays literal, so the config typo shows in the spawned command instead of
/// silently vanishing. Substitution is per element, so argv stays argv.
/// Matched output can inject an argument's value but never new arguments or
/// shell metacharacters (the spawn is `std::process::Command`, no shell).
/// Pure (unit-tested).
fn substitute_trigger_groups(argv: &[String], caps: &regex::Captures) -> Vec<String> {
    argv.iter()
        .map(|a| {
            if !a.contains('{') {
                return a.clone();
            }
            // Single left-to-right pass over the template. Substituted text is
            // emitted verbatim and never re-scanned, so a capture whose matched
            // text contains `{2}` cannot expand again with attacker-controlled
            // content.
            let bytes = a.as_bytes();
            let mut out = String::with_capacity(a.len());
            let mut i = 0;
            while i < bytes.len() {
                if bytes[i] == b'{' {
                    let mut j = i + 1;
                    while j < bytes.len() && bytes[j].is_ascii_digit() {
                        j += 1;
                    }
                    if j > i + 1
                        && j < bytes.len()
                        && bytes[j] == b'}'
                        && let Ok(idx) = a[i + 1..j].parse::<usize>()
                        && idx < caps.len()
                    {
                        out.push_str(caps.get(idx).map(|m| m.as_str()).unwrap_or(""));
                        i = j + 1;
                        continue;
                    }
                    // Not a valid in-range placeholder: the `{` stays
                    // literal (an out-of-range `{9}` keeps the typo visible).
                    out.push('{');
                    i += 1;
                } else {
                    let ch = a[i..].chars().next().expect("in-bounds char");
                    out.push(ch);
                    i += ch.len_utf8();
                }
            }
            out
        })
        .collect()
}

/// One on-screen quick-select target: where its label sits and what it is.
#[derive(Clone)]
pub(crate) struct HintTarget {
    row: usize,
    col: usize,
    label: String,
    /// The pane the target was read from, whose directory a relative path
    /// resolves against, even if focus moved or that pane exited since.
    pane: u64,
    what: HintWhat,
}

/// What a quick-select target is.
#[derive(Clone)]
enum HintWhat {
    /// Text the detector found: a URL, a path, or something to copy.
    Text {
        kind: kettle_core::hints::Kind,
        text: String,
        /// The text meets a boundary on both sides (see `HintSpan::bounded`).
        bounded: bool,
    },
    /// An inline card on screen: picking it opens its item in the viewer.
    Card(kettle_core::InlineNonce),
}

/// A card's place in a pane for quick select: its first and last visible
/// cells, as (row, column), and its nonce.
type CardCells = ((usize, usize), (usize, usize), kettle_core::InlineNonce);

/// The quick-select targets in a pane, in reading order: each text span the
/// detector found outside every card, and each card at its first visible
/// cell. A card's rows hold its marks, not text a user would pick.
fn hint_targets_with_cards(
    spans: Vec<kettle_core::hints::HintSpan>,
    cards: &[CardCells],
) -> Vec<(usize, usize, HintWhat)> {
    let inside_card = |row: usize, col: usize| {
        cards.iter().any(|((top, left), (bottom, right), _)| {
            (*top..=*bottom).contains(&row) && (*left..=*right).contains(&col)
        })
    };
    let mut found: Vec<(usize, usize, HintWhat)> = spans
        .into_iter()
        .filter(|span| !inside_card(span.row, span.start))
        .map(|span| {
            (
                span.row,
                span.start,
                HintWhat::Text {
                    kind: span.kind,
                    text: span.text,
                    bounded: span.bounded,
                },
            )
        })
        .collect();
    found.extend(
        cards
            .iter()
            .map(|((row, col), _, nonce)| (*row, *col, HintWhat::Card(*nonce))),
    );
    found.sort_by_key(|(row, col, _)| (*row, *col));
    found
}

/// What picking a quick-select hint does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HintAction {
    OpenUrl,
    OpenPath,
    Copy,
}

/// A URL opens and anything else is copied; a label typed with Shift
/// (`alternate`) copies a URL and opens a path. A path that may not name a
/// whole local file (`unsafe_path`: from a pane that may be remote, or cut
/// short by a character the pattern does not take) is copied, never opened.
fn hint_action(kind: kettle_core::hints::Kind, alternate: bool, unsafe_path: bool) -> HintAction {
    use kettle_core::hints::Kind;
    match (kind, alternate) {
        (Kind::Url, false) => HintAction::OpenUrl,
        (Kind::Path, true) if !unsafe_path => HintAction::OpenPath,
        _ => HintAction::Copy,
    }
}

/// Whether a file named `name` is one a lane can preview, by its extension:
/// the raster formats the media worker decodes, SVG, Mermaid, Markdown,
/// whose Mermaid diagrams are a gallery, and the common video containers,
/// shown as a poster (`.ts` is left out: it names TypeScript far more often).
/// The worker still decides by the bytes; this only picks what to offer.
fn previewable_name(name: &str) -> bool {
    let extension = name
        .rsplit_once('.')
        .map(|(_, extension)| extension.to_ascii_lowercase());
    matches!(
        extension.as_deref(),
        Some(
            "png"
                | "jpg"
                | "jpeg"
                | "webp"
                | "bmp"
                | "gif"
                | "svg"
                | "mmd"
                | "mermaid"
                | "md"
                | "markdown"
                | "mp4"
                | "m4v"
                | "mov"
                | "webm"
                | "mkv"
                | "avi"
                | "mpg"
                | "mpeg"
                | "m2ts"
                | "mts"
                | "ogv"
                | "wmv"
                | "flv"
        )
    )
}

/// What quick select for previews offers: text naming a local file a lane
/// can preview, a path or a `file://` link, as `preview_link` labels it. A
/// path off Windows only, where `hint_path_url` resolves one.
fn hint_previews(what: &HintWhat) -> bool {
    use kettle_core::hints::Kind;
    match what {
        HintWhat::Text {
            kind: Kind::Path,
            text,
            bounded: true,
        } => !cfg!(windows) && previewable_name(text),
        HintWhat::Text {
            kind: Kind::Url,
            text,
            ..
        } => kettle_core::links::local_file_path(text)
            .is_some_and(|path| previewable_name(&path.to_string_lossy())),
        _ => false,
    }
}

/// What the clipboard names for a lane to show.
#[derive(Debug, PartialEq, Eq)]
enum CopiedPreview {
    /// A file a file manager copied: on this computer, as no pane's output
    /// can put a file on the clipboard.
    File(std::path::PathBuf),
    /// A copied path or `file://` link, as a `file://` URL. It names a file
    /// wherever the pane it was copied from runs, so the pane's gate decides.
    Link(String),
}

/// The lane control a lane action works as, for the focused pane's lane.
fn lane_action_hit(action: &Action) -> Option<kettle_render::MediaLaneHit> {
    use kettle_render::MediaLaneHit as Hit;
    match action {
        Action::PreviewNext => Some(Hit::Next),
        Action::PreviewPrevious => Some(Hit::Previous),
        Action::PreviewNextDiagram => Some(Hit::NextPage),
        Action::PreviewPreviousDiagram => Some(Hit::PreviousPage),
        Action::ClosePreview => Some(Hit::Close),
        Action::PreviewSource => Some(Hit::Mode),
        Action::PreviewCanvas => Some(Hit::Canvas),
        Action::PreviewCopy => Some(Hit::Copy),
        Action::PreviewReload => Some(Hit::Reload),
        Action::VideoPlay => Some(Hit::Play),
        Action::VideoMute => Some(Hit::Sound),
        Action::PreviewZoomIn => Some(Hit::ZoomIn),
        Action::PreviewZoomOut => Some(Hit::ZoomOut),
        Action::PreviewFit => Some(Hit::Fit),
        _ => None,
    }
}

/// The modifiers physically held. On macOS, Option counts whether or not it
/// composes text (`macos-option-as-alt`), so an Option chord is a chord.
fn held_modifiers(ws: &WindowState) -> winit::keyboard::ModifiersState {
    #[cfg(target_os = "macos")]
    {
        ws.macos_raw_mods
    }
    #[cfg(not(target_os = "macos"))]
    {
        ws.mods
    }
}

/// Why a control client's keys or text are refused while a preview lane in
/// the pane's window holds the keyboard.
const PREVIEW_HOLDS_KEYBOARD: &str =
    "a preview lane in this pane's window holds the keyboard; nothing is typed until Esc";

/// Longest copied text read as a path, in bytes.
const MAX_COPIED_PATH: usize = 4096;

/// The file the clipboard names for a lane to show: the first of `files`, as
/// a file manager copies them, that a lane can show, or else the one path or
/// `file://` link `text` holds. A path is resolved from the pane's `cwd` as
/// quick select resolves one, after one pair of quotes around it, or a
/// shell's backslash escapes, are undone. `None` when neither names one.
fn copied_preview(
    files: &[std::path::PathBuf],
    text: Option<&str>,
    cwd: Option<&str>,
    home: Option<&str>,
) -> Option<CopiedPreview> {
    let shows = |path: &std::path::Path| previewable_name(&path.to_string_lossy());
    if !files.is_empty() {
        // Through a file URL and back, so a listed file meets the checks a
        // link does: absolute, on this computer (no `\\host\share`), no `..`.
        // It must come back as itself: a Linux file list can name `C:/x`,
        // which is relative there. The CR a CRLF list leaves on a line is no
        // part of the name.
        return files.iter().find_map(|file| {
            let name = file.to_str()?;
            let file = std::path::Path::new(name.strip_suffix('\r').unwrap_or(name));
            kettle_core::links::file_url_for_path(file)
                .and_then(|url| kettle_core::links::local_file_path(&url))
                .filter(|path| path == file && shows(path))
                .map(CopiedPreview::File)
        });
    }
    // Two lines are no one path: a line break decodes to a control
    // character, which `local_file_path` refuses below. A path longer than
    // any URL Kettle accepts is dropped before it is unescaped and encoded.
    let text = text?.trim();
    if text.len() > MAX_COPIED_PATH {
        return None;
    }
    let url = if text
        .get(..7)
        .is_some_and(|scheme| scheme.eq_ignore_ascii_case("file://"))
    {
        text.to_string()
    } else if text.contains("://") {
        return None;
    } else {
        copied_path_url(&unquote_copied_path(text), cwd, home)?
    };
    kettle_core::links::local_file_path(&url)
        .is_some_and(|path| shows(&path))
        .then_some(CopiedPreview::Link(url))
}

/// A copied path without one pair of matching quotes around it or, off
/// Windows, without a shell's backslash escapes (`my\ plot.png`).
fn unquote_copied_path(text: &str) -> String {
    for quote in ['"', '\''] {
        if let Some(inner) = text
            .strip_prefix(quote)
            .and_then(|rest| rest.strip_suffix(quote))
        {
            return inner.to_string();
        }
    }
    if cfg!(windows) {
        return text.to_string();
    }
    let mut unescaped = String::with_capacity(text.len());
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        unescaped.push(match c {
            '\\' => chars.next().unwrap_or(c),
            _ => c,
        });
    }
    unescaped
}

/// The `file://` URL a copied path names: off Windows as quick select
/// resolves a path (`hint_path_url`); on Windows only a drive path, never a
/// share or a relative path.
fn copied_path_url(text: &str, cwd: Option<&str>, home: Option<&str>) -> Option<String> {
    if cfg!(windows) {
        let bytes = text.as_bytes();
        let drive = bytes.len() > 2
            && bytes[0].is_ascii_alphabetic()
            && bytes[1] == b':'
            && matches!(bytes[2], b'\\' | b'/');
        return drive
            .then(|| kettle_core::links::file_url_for_path(std::path::Path::new(text)))
            .flatten();
    }
    hint_path_url(text, cwd, home)
}

/// Most previews the user asked for that wait for their window to open them.
const MAX_PREVIEWS_READY: usize = 8;

/// Tell the user why a preview they asked for did not open; nothing for a
/// request that answers a control client (`None`).
fn notify_preview_failure(tr: kettle_i18n::Translator, failure: Option<kettle_media::FailureCode>) {
    let Some(failure) = failure else {
        return;
    };
    fire_notify(
        tr.text(kettle_i18n::Text::NotifyTitlePreviewFailed),
        tr.text(preview_failure_body(failure)),
    );
}

/// What a failed preview's notice says, by its failure.
fn preview_failure_body(failure: kettle_media::FailureCode) -> kettle_i18n::Text {
    use kettle_i18n::Text as T;
    use kettle_media::FailureCode as F;
    match failure {
        F::FileNotFound => T::NotifyBodyPreviewMissing,
        F::FilePermission | F::FileNotRegular | F::Changed => T::NotifyBodyPreviewUnreadable,
        F::TooLarge | F::FileTooLarge => T::NotifyBodyPreviewTooLarge,
        // Only a video's decoders answer these: which one a user can install.
        F::UnsupportedContainer | F::CodecUnavailable | F::BackendUnavailable => {
            T::NotifyBodyPreviewNeedsDecoder
        }
        // Installing anything would not help: the system has no sandbox.
        F::SandboxUnavailable => T::NotifyBodyPreviewNeedsSandbox,
        F::UnsupportedMedia | F::RenderParse | F::IndexOutOfRange => {
            T::NotifyBodyPreviewUnsupported
        }
        F::WorkerUnavailable | F::RestartRequired | F::UnsupportedPlatform => {
            T::NotifyBodyPreviewUnavailable
        }
        _ => T::NotifyBodyPreviewFailed,
    }
}

/// Where a link handed to `App::open_url` came from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LinkSource {
    /// Kettle's own link (the release page).
    Kettle,
    /// A pane's output, with that pane's origin (`None`: it has gone).
    Pane(Option<PathOrigin>),
}

/// What opening a link from a pane's output does (see `App::open_pane_link`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LinkGate {
    Open,
    /// A local file link from a remote pane, or one that has gone.
    Refuse,
}

/// Whether a link from a pane with `origin` (`None`: the pane has gone) may
/// open. Only a `file://` link names a local file; web and mail links open
/// wherever they were printed. A multiplexer's server runs on this computer,
/// so its panes' file links open as local ones do; a file an ssh inside it
/// named is usually missing here, which the opener reports.
fn link_gate(uri: &str, origin: Option<PathOrigin>) -> LinkGate {
    let file_link = uri
        .get(..7)
        .is_some_and(|scheme| scheme.eq_ignore_ascii_case("file://"));
    match (file_link, origin) {
        (false, _) | (true, Some(PathOrigin::Local)) => LinkGate::Open,
        (true, Some(PathOrigin::Remote) | None) => LinkGate::Refuse,
    }
}

/// The name a prompt or notification shows for a file link: its file name,
/// or the link itself when it names none. The text is untrusted, so
/// characters that reorder or hide text (bidirectional controls, zero-width
/// and other format characters) show as `\u{FFFD}`, and a name wider than
/// `max_cols` columns keeps its start and end around an ellipsis, so the
/// warning beside it stays readable.
fn link_display_name(uri: &str, max_cols: usize) -> String {
    use unicode_width::UnicodeWidthChar as _;
    let name = kettle_core::links::local_file_path(uri)
        .and_then(|path| {
            path.file_name()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| uri.to_string());
    let shown = name
        .chars()
        .map(|c| {
            let format = matches!(
                c,
                '\u{00AD}'
                    | '\u{061C}'
                    | '\u{180E}'
                    | '\u{200B}'..='\u{200F}'
                    | '\u{2028}'..='\u{202E}'
                    | '\u{2060}'..='\u{206F}'
                    | '\u{FEFF}'
                    | '\u{FFF9}'..='\u{FFFB}'
            );
            if c.is_control() || format {
                '\u{FFFD}'
            } else {
                c
            }
        })
        .collect::<Vec<_>>();
    let width = |chars: &[char]| chars.iter().map(|c| c.width().unwrap_or(0)).sum::<usize>();
    if width(&shown) <= max_cols {
        return shown.into_iter().collect();
    }
    // Half the budget, less the ellipsis, from each end.
    let side = max_cols.saturating_sub(1) / 2;
    let mut head = 0;
    let mut used = 0;
    while let Some(c) = shown.get(head) {
        let w = c.width().unwrap_or(0);
        if used + w > side {
            break;
        }
        used += w;
        head += 1;
    }
    let mut tail = shown.len();
    used = 0;
    while tail > head {
        let w = shown[tail - 1].width().unwrap_or(0);
        if used + w > side {
            break;
        }
        used += w;
        tail -= 1;
    }
    shown[..head]
        .iter()
        .chain(['…'].iter())
        .chain(&shown[tail..])
        .collect()
}

/// The pane `ws.links` were scanned from: the focused pane at the last scan.
fn links_pane(ws: &WindowState) -> Option<u64> {
    ws.links_scan_key.as_ref().and_then(|key| key.0.1)
}

/// Where the files a pane's output names live, as far as Kettle can tell.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PathOrigin {
    /// This computer, including behind tmux, screen or zellij, whose server
    /// runs here.
    Local,
    /// Another machine or a container: a detected remote session, or a
    /// remote shell or container client in the pane.
    Remote,
}

/// Where a pane's printed paths live: remote when it runs a detected remote
/// session or a remote or container client, and local otherwise.
///
/// What runs now decides: the foreground program, shell scripts included
/// (`sh -c 'tmux attach'`). The command the pane was launched with counts
/// only when it is itself a client (`ssh host`, `env TERM=x ssh host`): a
/// launch script that ran ssh and then `exec bash` must not mark the pane
/// remote for good. Output a pane printed while it was remote stays on
/// screen after it returns local; links are gated by what runs when they are
/// opened.
fn pane_path_origin(pane: &crate::mux::Pane) -> PathOrigin {
    path_origin(
        pane.remote_context.is_some() || argv_is_nonlocal_client(&pane.argv),
        &pane.argv,
        pane.foreground_process
            .as_ref()
            .map(|process| process.argv.as_slice()),
    )
}

/// [`pane_path_origin`] from its parts: whether a remote session is known,
/// the launch command and the foreground program's command line.
fn path_origin(remote: bool, launch: &[String], foreground: Option<&[String]>) -> PathOrigin {
    let launch_client = argv_client_with(launch, 0, false);
    let foreground_client = foreground.and_then(|argv| argv_client(argv, 0));
    match (
        remote,
        any_client([launch_client, foreground_client].into_iter()),
    ) {
        (true, _) | (false, Some(Client::Remote)) => PathOrigin::Remote,
        (false, None) => PathOrigin::Local,
    }
}

/// What kind of client a command line runs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Client {
    Remote,
}

/// The remote or container client `argv` runs, looking through a shell's
/// `-c` script, every command in it (`sh -c 'cd ~ && "ssh" host'`), and
/// through wrappers that run another command (`env TERM=xterm ssh host`,
/// `sudo -u me ssh host`, `nice -n 5 mosh host`). Nesting deeper than four
/// levels counts as remote: it fails closed rather than reading as local.
fn argv_client(argv: &[String], depth: usize) -> Option<Client> {
    argv_client_with(argv, depth, true)
}

/// [`argv_client`], reading shell `-c` scripts only when `scripts` is set: a
/// pane's launch command counts only when it is itself a client, wrapped or
/// not, since a launch script may long since have moved on.
fn argv_client_with(argv: &[String], depth: usize, scripts: bool) -> Option<Client> {
    if depth > 4 {
        return Some(Client::Remote);
    }
    let argv0 = argv.first()?;
    let name = argv0
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(argv0)
        .to_ascii_lowercase();
    let name = name.strip_suffix(".exe").unwrap_or(&name);
    let rest = &argv[1..];
    match name {
        "ssh" | "autossh" | "mosh" | "mosh-client" | "et" | "telnet" | "docker" | "podman"
        | "kubectl" | "lxc-attach" => Some(Client::Remote),
        "sh" | "bash" | "zsh" | "dash" | "ksh" | "mksh" | "fish" if !scripts => None,
        "sh" | "bash" | "zsh" | "dash" | "ksh" | "mksh" | "fish" => {
            // The argument after a flag cluster holding `c` (`-c`, `-lc`).
            let flag = rest.iter().position(|arg| {
                arg.len() > 1
                    && arg.starts_with('-')
                    && !arg.starts_with("--")
                    && arg[1..].contains('c')
            })?;
            // A script past the parser's bounds fails closed.
            let Some(commands) = shell_commands(rest.get(flag + 1)?) else {
                return Some(Client::Remote);
            };
            any_client(commands.iter().map(|words| {
                let words = command_words(words);
                // A command the parser cannot name (`$cmd`, `` `cmd` ``,
                // `eval …`) fails closed.
                match words.first() {
                    Some(first) if first == "eval" || first.contains(['$', '`']) => {
                        Some(Client::Remote)
                    }
                    _ => argv_client(words, depth + 1),
                }
            }))
        }
        "env" | "nohup" | "nice" | "caffeinate" | "sudo" | "doas" | "time" | "sshpass" => {
            // Options that take a separate value, per wrapper.
            let takes_value: &[&str] = match name {
                "env" => &["-u", "-C", "--unset", "--chdir"],
                "nice" => &["-n", "--adjustment"],
                "caffeinate" => &["-t", "-w"],
                "sudo" => &[
                    "-u",
                    "-g",
                    "-h",
                    "-p",
                    "-C",
                    "-D",
                    "-r",
                    "-t",
                    "-U",
                    "-T",
                    "--user",
                    "--group",
                    "--host",
                    "--prompt",
                    "--close-from",
                    "--chdir",
                    "--role",
                    "--type",
                    "--other-user",
                    "--command-timeout",
                ],
                "doas" => &["-u", "-C", "-a"],
                "time" => &["-o", "-f", "--output", "--format"],
                "sshpass" => &["-p", "-f", "-d", "-P"],
                _ => &[],
            };
            let mut index = 0;
            while let Some(arg) = rest.get(index) {
                if arg == "--" {
                    index += 1;
                    break;
                } else if arg.starts_with('-') {
                    index += if takes_value.contains(&arg.as_str()) {
                        2
                    } else {
                        1
                    };
                } else if name == "env" && arg.contains('=') {
                    index += 1;
                } else {
                    break;
                }
            }
            // An option this table does not know (`--preserve-env X`) may
            // have taken the next word as its value: then the command starts
            // one word later.
            let uncertain = index
                .checked_sub(1)
                .and_then(|before| rest.get(before))
                .is_some_and(|option| {
                    option.starts_with('-')
                        && option != "--"
                        && !option.contains('=')
                        && !takes_value.contains(&option.as_str())
                });
            argv_client_with(rest.get(index..)?, depth + 1, scripts).or_else(|| {
                uncertain
                    .then(|| argv_client_with(rest.get(index + 1..)?, depth + 1, scripts))
                    .flatten()
            })
        }
        _ => None,
    }
}

/// The client any of `clients` runs.
fn any_client(mut clients: impl Iterator<Item = Option<Client>>) -> Option<Client> {
    clients.find_map(|client| client)
}

/// A command's words past leading redirections and assignments, the shell
/// keywords before a
/// command (`if`, `then`, `do`, `!`, `{`…), and the precommand words the shell
/// runs it through (`exec`, `command`, `builtin`, `nohup`, `noglob`,
/// `nocorrect`) with their options (`command -p`, `exec -a NAME`).
fn command_words(words: &[String]) -> &[String] {
    let mut index = 0;
    while let Some(word) = words.get(index) {
        // A redirection (`2>/dev/null`, `>out`, `&>log`), and its target when
        // it stands apart (`2> /dev/null`).
        let redirection = word.trim_start_matches(|c: char| c.is_ascii_digit() || c == '&');
        if redirection.starts_with(['<', '>']) {
            let operator_only = redirection
                .trim_start_matches(['<', '>', '&', '|'])
                .is_empty();
            index += if operator_only { 2 } else { 1 };
        } else if word.contains('=') && !word.starts_with('=') && !word.starts_with('-') {
            index += 1;
        } else if matches!(
            word.as_str(),
            "if" | "then"
                | "else"
                | "elif"
                | "do"
                | "while"
                | "until"
                | "!"
                | "{"
                | "not"
                | "and"
                | "or"
                | "begin"
        ) {
            // Shell keywords that come before a command, fish's included.
            index += 1;
        } else if matches!(
            word.as_str(),
            "exec" | "command" | "builtin" | "nohup" | "noglob" | "nocorrect"
        ) {
            let precommand = word.as_str();
            index += 1;
            while let Some(option) = words.get(index).filter(|option| option.starts_with('-')) {
                // `command -v ssh` names a program without running it.
                if precommand == "command" && option.contains(['v', 'V']) {
                    return &[];
                }
                index += if precommand == "exec" && option == "-a" {
                    2
                } else {
                    1
                };
                if option == "--" {
                    break;
                }
            }
        } else {
            break;
        }
    }
    words.get(index..).unwrap_or_default()
}

/// The simple commands in a shell script, as words with their quotes
/// removed: `;`, `&`, `|`, newlines and parentheses separate commands, and
/// single quotes, double quotes and backslashes quote. Command substitutions
/// (`$(…)`, `` `…` ``) are commands too, nested at most four deep; in command
/// position one reads as `$SUBST`, which a caller cannot name. `None` for a
/// script past the bounds (4 KiB, 16 commands, the nesting) or with a
/// substitution left open, which a caller must not read as holding no
/// client.
fn shell_commands(script: &str) -> Option<Vec<Vec<String>>> {
    shell_commands_at(script, 0)
}

fn shell_commands_at(script: &str, depth: usize) -> Option<Vec<Vec<String>>> {
    if script.len() > 4096 || depth > 4 {
        return None;
    }
    let (outer, substitutions) = split_substitutions(script)?;
    let mut commands = split_commands(&outer)?;
    for substitution in substitutions {
        commands.extend(shell_commands_at(&substitution, depth + 1)?);
        if commands.len() > 16 {
            return None;
        }
    }
    Some(commands)
}

/// `script` with each command substitution outside single quotes replaced by
/// `$SUBST`, and the substitutions' own text. `None` for one left open.
fn split_substitutions(script: &str) -> Option<(String, Vec<String>)> {
    let mut outer = String::with_capacity(script.len());
    let mut substitutions = Vec::new();
    let mut chars = script.chars().peekable();
    let (mut single, mut double) = (false, false);
    while let Some(c) = chars.next() {
        match c {
            '\\' if !single => {
                outer.push(c);
                outer.extend(chars.next());
            }
            '\'' if !double => {
                single = !single;
                outer.push(c);
            }
            '"' if !single => {
                double = !double;
                outer.push(c);
            }
            '$' if !single && chars.peek() == Some(&'(') => {
                chars.next();
                let mut depth = 1usize;
                let mut body = String::new();
                // Parentheses inside quotes do not count (`$(printf ')')`).
                let (mut inner_single, mut inner_double) = (false, false);
                loop {
                    let c = chars.next()?;
                    match c {
                        '\\' if !inner_single => {
                            body.push(c);
                            body.extend(chars.next());
                            continue;
                        }
                        '\'' if !inner_double => inner_single = !inner_single,
                        '"' if !inner_single => inner_double = !inner_double,
                        '(' if !inner_single && !inner_double => depth += 1,
                        ')' if !inner_single && !inner_double => depth -= 1,
                        _ => {}
                    }
                    if depth == 0 {
                        break;
                    }
                    body.push(c);
                }
                substitutions.push(body);
                outer.push_str("$SUBST");
            }
            '`' if !single => {
                let mut body = String::new();
                loop {
                    match chars.next()? {
                        '`' => break,
                        '\\' => body.extend(chars.next()),
                        c => body.push(c),
                    }
                }
                substitutions.push(body);
                outer.push_str("$SUBST");
            }
            c => outer.push(c),
        }
    }
    Some((outer, substitutions))
}

/// The simple commands in a script with no substitutions left (see
/// [`shell_commands`]).
fn split_commands(script: &str) -> Option<Vec<Vec<String>>> {
    let mut commands = vec![Vec::new()];
    let mut word = String::new();
    let mut in_word = false;
    let mut chars = script.chars();
    let end_word = |word: &mut String, in_word: &mut bool, commands: &mut Vec<Vec<String>>| {
        if *in_word {
            commands
                .last_mut()
                .expect("a command")
                .push(std::mem::take(word));
            *in_word = false;
        }
    };
    while let Some(c) = chars.next() {
        match c {
            '\'' => {
                in_word = true;
                word.extend(chars.by_ref().take_while(|&c| c != '\''));
            }
            '"' => {
                in_word = true;
                while let Some(c) = chars.next() {
                    match c {
                        '"' => break,
                        // A backslash-newline continues the line.
                        '\\' => match chars.next() {
                            Some('\n') | None => {}
                            Some(c) => word.push(c),
                        },
                        c => word.push(c),
                    }
                }
            }
            '\\' => match chars.next() {
                // A backslash-newline continues the word.
                Some('\n') | None => {}
                Some(c) => {
                    in_word = true;
                    word.push(c);
                }
            },
            // A redirection starts a word of its own (`tmux</dev/tty`),
            // keeping a file descriptor before it (`2>`).
            '<' | '>' if in_word && !word.chars().all(|c| c.is_ascii_digit() || c == '&') => {
                end_word(&mut word, &mut in_word, &mut commands);
                in_word = true;
                word.push(c);
            }
            // `2>&1` and `&>file` are redirections, not command separators.
            '&' if word.ends_with(['>', '<']) || chars.clone().next() == Some('>') => {
                in_word = true;
                word.push(c);
            }
            ';' | '&' | '|' | '\n' | '(' | ')' => {
                end_word(&mut word, &mut in_word, &mut commands);
                if commands.last().is_some_and(|command| !command.is_empty()) {
                    if commands.len() == 16 {
                        return None;
                    }
                    commands.push(Vec::new());
                }
            }
            c if c.is_whitespace() => end_word(&mut word, &mut in_word, &mut commands),
            c => {
                in_word = true;
                word.push(c);
            }
        }
    }
    end_word(&mut word, &mut in_word, &mut commands);
    commands.retain(|command| !command.is_empty());
    Some(commands)
}

/// The local `file://` URL a path hint names: `~/` resolved from `home`, a
/// relative path from the pane's `cwd`, `.` segments dropped. This touches no
/// filesystem: the path and an OSC 7 `cwd` are untrusted terminal text, and a
/// stat would let them reach a network share or an automount (`/net/host`),
/// leaking the user's address and stalling the UI thread. The OS opener, run
/// detached, resolves symlinks. `None`, so the hint is copied instead, when
/// the base is unknown or not local, or the path climbs with `..`, whose
/// meaning after a symlink only the filesystem knows; always on Windows,
/// where a link to a `\\host\share` would contact that host.
fn hint_path_url(text: &str, cwd: Option<&str>, home: Option<&str>) -> Option<String> {
    use std::path::{Component, Path, PathBuf};
    if cfg!(windows) {
        return None;
    }
    let local = |base: &str| cwd_is_local(base).then(|| Path::new(base).to_path_buf());
    let joined = if let Some(rest) = text.strip_prefix("~/") {
        local(home?)?.join(rest)
    } else if text.starts_with('/') {
        PathBuf::from(text)
    } else if text.as_bytes().get(1) == Some(&b':') {
        // A drive-letter path names nothing local off Windows.
        return None;
    } else {
        local(cwd?)?.join(text)
    };
    let mut resolved = PathBuf::new();
    for component in joined.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => return None,
            other => resolved.push(other),
        }
    }
    let text = resolved.to_str()?;
    if !cwd_is_local(text) || !resolved.is_absolute() {
        return None;
    }
    // Percent-encode everything but the characters a file URL's path keeps.
    let mut url = String::from("file://");
    for byte in text.bytes() {
        if byte.is_ascii_alphanumeric() || b"/-._~:".contains(&byte) {
            url.push(char::from(byte));
        } else {
            url.push_str(&format!("%{byte:02X}"));
        }
    }
    Some(url)
}

/// What a context-menu click dispatches, such as a kettle Action (built-in
/// items) or a Lua callback index (kettle.add_menu_item entries).
/// The rows a right-click on the link `url` from pane `pane`'s output leads
/// the menu with: open it, preview it in Kettle when it is a local file a lane
/// can show from a pane still known, copy its address, then a separator.
fn link_menu_rows(
    url: &str,
    pane: Option<u64>,
    tr: kettle_i18n::Translator,
) -> Vec<ContextMenuItem> {
    use kettle_i18n::Text as T;
    let row = |label: T, how: UrlHow| ContextMenuItem::UrlItem {
        label: tr.text(label),
        url: url.to_string(),
        how,
        pane,
    };
    let previewable = pane.is_some()
        && kettle_core::links::local_file_path(url)
            .is_some_and(|path| previewable_name(&path.to_string_lossy()));
    let mut rows = vec![row(T::MenuOpenLink, UrlHow::Open)];
    if previewable {
        rows.push(row(T::MenuPreviewInKettle, UrlHow::Preview));
    }
    rows.push(row(T::MenuCopyLink, UrlHow::Copy));
    rows.push(ContextMenuItem::Separator);
    rows
}

/// What a link row of the context menu does with its address.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UrlHow {
    Open,
    Copy,
    /// Preview the local file it names in the pane's lane.
    Preview,
}

#[derive(Clone)]
enum ContextMenuClick {
    Action(Action),
    /// A media row: what it does, and to which shelf item.
    Media {
        target: MediaTarget,
        action: MediaMenuAction,
    },
    LuaMenuItem(usize),
    /// Terminator parity (`custom_commands.py`): a
    /// `menu-item = LABEL = CMD` config entry. Dispatch writes
    /// `CMD\n` to the focused pane's PTY.
    ConfigCommand(String),
    /// Profile picked from the right-click "Profile ▸" submenu.
    /// Dispatch sets `App::config_path` via the profile-path
    /// resolution helper and calls `reload_config`.
    SetProfile(String),
    MoveTabToWindow {
        window: u64,
        panes: Arc<[u64]>,
    },
    /// Drill into a `Submenu` row by index. The click handler pushes
    /// the current items onto `drill_stack` + replaces them
    /// with the submenu's items.
    DrillIntoSubmenu(usize),
    /// Open a new tab running an explicit argv (a shell picked from
    /// the new-tab `▾` dropdown). Dispatch calls `Mux::new_tab_with` with the
    /// focused tab's current working directory.
    NewTabWithArgv(Vec<String>),
    /// Terminator parity (terminal_popup_menu.py "Open link" /
    /// "Copy address"): a click on one of the URL-aware leading rows.
    /// `how` says what the row does with the address: open it through the
    /// `open_url` chain (Lua handler → custom_url_handler → system open,
    /// `is_safe_url`-guarded), copy it, or preview the local file it names
    /// in the pane's lane.
    Url {
        url: String,
        how: UrlHow,
        /// The pane whose output held the link; `None` for Kettle's own
        /// links (About).
        pane: Option<u64>,
    },
}

/// One entry in the right-click context menu. `Separator` rows render
/// as a thin divider in the menu and are skipped during keyboard nav
/// and click dispatch; `Item` rows carry the action to fire.
#[derive(Clone)]
enum ContextMenuItem {
    Item {
        label: &'static str,
        action: Action,
        enabled: bool,
    },
    /// Like `Item` but with an owned `String` label, so dynamic state
    /// markers (radio `● / ○`, check `✓ /  `) can be baked into the
    /// label at build time without leaking memory via `Box::leak`.
    /// Same dispatch surface as `Item` (typed `Action`).
    DynamicItem {
        label: String,
        action: Action,
        enabled: bool,
    },
    Separator,
    /// Terminator plugin parity:
    /// menu item supplied by a Lua plugin via `kettle.add_menu_item(
    /// label, callback)`. Dispatch invokes the registered Lua
    /// callback (looked up by `lua_idx` in the kettle_menu_items
    /// table) instead of an Action.
    LuaItem {
        label: String,
        lua_idx: usize,
    },
    /// Terminator parity (`custom_commands.py`): user-
    /// defined menu entry from a config-file `menu-item = LABEL =
    /// CMD` line. Dispatch writes `command + "\n"` to the focused
    /// PTY. Simpler than `LuaItem` — no callback, just literal
    /// text. Use this for "Run `clear`" / "Open `~/.bashrc` in
    /// `$EDITOR`" / etc.
    ConfigItem {
        label: String,
        command: String,
    },
    /// Terminator parity, per
    /// [`TERMINATOR-THEME-SUBMENU-DESIGN.md`](
    /// ../../../docs/TERMINATOR-THEME-SUBMENU-DESIGN.md):
    /// recursive variant carrying a nested item list. The row
    /// renders with a trailing "▸", and clicking it drills in,
    /// replacing the visible items instead of opening a flyout.
    Submenu {
        label: String,
        // Consumed by the drill-in dispatch
        // (`ContextMenuClick::DrillIntoSubmenu`), which pushes the
        // parent items onto `drill_stack` and replaces them with
        // these.
        items: Vec<ContextMenuItem>,
    },
    WindowChoice {
        label: String,
        window: u64,
        panes: Arc<[u64]>,
    },
    /// A profile-choice leaf row used inside a
    /// `Submenu { label: "Profile", … }`. Clicking dispatches
    /// `ContextMenuClick::SetProfile(profile)` which switches the
    /// active profile (`App::config_path` + reload_config).
    ProfileChoice {
        label: String,
        profile: String,
    },
    /// A shell-choice leaf in the new-tab `▾` dropdown. Clicking
    /// dispatches `ContextMenuClick::NewTabWithArgv(argv)` to open a tab
    /// running that shell.
    NewTabShell {
        label: String,
        argv: Vec<String>,
    },
    /// Terminator parity (terminal_popup_menu.py "Open link" /
    /// "Copy address"): URL-aware leading rows, present only when the
    /// right-click landed on a detected hyperlink. The URL is captured at
    /// menu-open time so a subsequent output scroll can't retarget the click.
    /// Clicking dispatches `ContextMenuClick::Url { url, how }`.
    UrlItem {
        label: &'static str,
        url: String,
        how: UrlHow,
        /// The pane whose output held the link, captured with it.
        pane: Option<u64>,
    },
    /// A row of an inline card's menu: open its item in Kettle, or a copy of
    /// it in the permitted image viewer. The card and its item, with the
    /// item's generation, are captured when the menu opens.
    Media {
        label: &'static str,
        target: MediaTarget,
        action: MediaMenuAction,
    },
    /// A static, non-dispatchable information line
    /// (the About panel's version/update rows). Rendered like a disabled row
    /// (dimmed), survives `filter_disabled`, never highlighted, claims no
    /// mnemonic, and maps to no click.
    Info {
        label: String,
    },
}

/// The card a media menu row acts on, and the shelf item it showed when the
/// menu opened.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct MediaTarget {
    pane: u64,
    nonce: kettle_core::InlineNonce,
    item: u64,
    generation: u64,
}

/// What a media menu row does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MediaMenuAction {
    /// Open the item in Kettle's viewer.
    View,
    /// Open a copy of it in the permitted image viewer, or of a video in
    /// the permitted video player.
    OpenOutside(crate::media::Outside),
}

/// What the title-edit overlay edits (Terminator parity).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TitleEditScope {
    /// Edit the OS window title (winit Window::set_title).
    Window,
    /// Edit the tab active when the overlay opens (overrides what the
    /// tab-bar shows independent of any OSC 1/2 from a pane).
    Tab,
    /// Edit the pane focused when the overlay opens (shown in its per-pane
    /// titlebar; the OSC-1 equivalent).
    Pane,
    /// Edit the opening pane's broadcast-group name (Terminator parity).
    /// Writes to pane.group_name. Empty input clears the group.
    Group,
}

/// Which panes a `Group` edit's typed name applies to. See
/// [`TERMINATOR-NAMED-GROUPS-DESIGN.md`](
/// ../../../docs/TERMINATOR-NAMED-GROUPS-DESIGN.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum GroupBulkScope {
    /// Default: just the pane focused when the overlay opens (existing
    /// `EditPaneGroup` / `CreateGroup` behavior).
    #[default]
    Single,
    /// Every pane in the tab active when the overlay opens gets the typed name.
    Tab,
    /// Every pane in every tab.
    Window,
}

#[derive(Debug, Clone)]
pub struct TitleEditState {
    pub scope: TitleEditScope,
    /// Stable identity captured when the edit opens. Pane ids are never reused;
    /// a tab is named by every pane it held so it survives index shifts and one
    /// of its panes exiting.
    pub target: TitleEditTarget,
    /// Current text the user has typed. Pre-filled with the existing
    /// title so the user can edit in place vs starting blank.
    pub input: String,
    /// When `scope == Group`, which panes Apply writes
    /// to. Single = opening pane only (existing behavior); Tab/Window
    /// = bulk-assign via `Action::GroupTab`/`GroupWindow`.
    pub bulk: GroupBulkScope,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TitleEditTarget {
    /// The owning `WindowState`. Window-title edits and window-bulk group edits
    /// deliberately keep live window membership: the state itself cannot move
    /// to another window, and `GroupWindow` still means every pane present in
    /// this window when the name is applied.
    Window,
    /// All pane ids held by the target tab when the edit opened. Resolving any
    /// surviving id finds the same tab after reordering or sibling exits.
    Tab(Vec<u64>),
    /// One pane, used by pane-title and single-pane group edits.
    Pane(u64),
}

fn begin_title_edit(
    mux: &Mux,
    scope: TitleEditScope,
    bulk: GroupBulkScope,
    window_title: &str,
) -> Option<TitleEditState> {
    let target = match (scope, bulk) {
        (TitleEditScope::Window, _) | (TitleEditScope::Group, GroupBulkScope::Window) => {
            TitleEditTarget::Window
        }
        (TitleEditScope::Tab, _) | (TitleEditScope::Group, GroupBulkScope::Tab) => {
            let panes = mux.tab_anchor_panes(mux.active);
            if panes.is_empty() {
                return None;
            }
            TitleEditTarget::Tab(panes)
        }
        (TitleEditScope::Pane, _) | (TitleEditScope::Group, GroupBulkScope::Single) => {
            TitleEditTarget::Pane(mux.active_focus()?)
        }
    };
    let input = match (scope, bulk, &target) {
        (TitleEditScope::Window, _, TitleEditTarget::Window) => window_title.to_string(),
        (TitleEditScope::Tab, _, TitleEditTarget::Tab(panes)) => {
            let idx = mux.tab_index_of_any_pane(panes)?;
            mux.tabs[idx].title_override.clone().unwrap_or_default()
        }
        (TitleEditScope::Pane, _, TitleEditTarget::Pane(id)) => mux.panes.get(id)?.title.clone(),
        (TitleEditScope::Group, GroupBulkScope::Single, TitleEditTarget::Pane(id)) => {
            mux.panes.get(id)?.group_name.clone().unwrap_or_default()
        }
        (TitleEditScope::Group, GroupBulkScope::Tab, TitleEditTarget::Tab(_))
        | (TitleEditScope::Group, GroupBulkScope::Window, TitleEditTarget::Window) => String::new(),
        _ => return None,
    };
    Some(TitleEditState {
        scope,
        target,
        input,
        bulk,
    })
}

fn title_edit_target_is_live(mux: &Mux, state: &TitleEditState) -> bool {
    match (state.scope, state.bulk, &state.target) {
        (TitleEditScope::Window, _, TitleEditTarget::Window)
        | (TitleEditScope::Group, GroupBulkScope::Window, TitleEditTarget::Window) => true,
        (TitleEditScope::Tab, _, TitleEditTarget::Tab(panes))
        | (TitleEditScope::Group, GroupBulkScope::Tab, TitleEditTarget::Tab(panes)) => {
            mux.tab_index_of_any_pane(panes).is_some()
        }
        (TitleEditScope::Pane, _, TitleEditTarget::Pane(id))
        | (TitleEditScope::Group, GroupBulkScope::Single, TitleEditTarget::Pane(id)) => {
            mux.panes.contains_key(id)
        }
        _ => false,
    }
}

fn clear_stale_title_edit(mux: &Mux, editing: &mut Option<TitleEditState>) -> bool {
    if editing
        .as_ref()
        .is_some_and(|state| !title_edit_target_is_live(mux, state))
    {
        *editing = None;
        true
    } else {
        false
    }
}

fn apply_mux_title_edit(mux: &mut Mux, state: &TitleEditState) -> bool {
    let value = &state.input;
    match (state.scope, state.bulk, &state.target) {
        (TitleEditScope::Window, _, _) => false,
        (TitleEditScope::Tab, _, TitleEditTarget::Tab(panes)) => {
            let Some(idx) = mux.tab_index_of_any_pane(panes) else {
                return false;
            };
            let tab = &mut mux.tabs[idx];
            tab.title_override = if value.is_empty() {
                None
            } else {
                Some(value.clone())
            };
            true
        }
        (TitleEditScope::Pane, _, TitleEditTarget::Pane(id)) => {
            let Some(pane) = mux.panes.get_mut(id) else {
                return false;
            };
            // Empty restores shell-driven titles; anything else pins the name
            // against the next OSC 0/2.
            if value.trim().is_empty() {
                pane.title = "kettle".into();
                pane.title_is_placeholder = true;
                pane.title_origin = PaneTitleOrigin::Placeholder;
            } else {
                pane.title = value.clone();
                pane.title_is_placeholder = false;
                pane.title_origin = PaneTitleOrigin::Manual;
            }
            true
        }
        (TitleEditScope::Group, bulk, target) => {
            let next = if value.is_empty() {
                None
            } else {
                Some(value.clone())
            };
            match (bulk, target) {
                (GroupBulkScope::Single, TitleEditTarget::Pane(id)) => {
                    let Some(pane) = mux.panes.get_mut(id) else {
                        return false;
                    };
                    pane.group_name = next;
                    true
                }
                (GroupBulkScope::Tab, TitleEditTarget::Tab(panes)) => {
                    let Some(idx) = mux.tab_index_of_any_pane(panes) else {
                        return false;
                    };
                    let ids = mux
                        .tabs
                        .get(idx)
                        .map(|tab| tab.root.leaf_ids())
                        .unwrap_or_default();
                    let applied = !ids.is_empty();
                    for id in ids {
                        if let Some(pane) = mux.panes.get_mut(&id) {
                            pane.group_name = next.clone();
                        }
                    }
                    applied
                }
                (GroupBulkScope::Window, TitleEditTarget::Window) => {
                    for pane in mux.panes.values_mut() {
                        pane.group_name = next.clone();
                    }
                    true
                }
                _ => false,
            }
        }
        _ => false,
    }
}

/// Whether a window close should also empty the mux before the session is
/// saved.
///
/// `close_window` means "this window is finished" and saves an empty session so
/// the next launch starts fresh. The titlebar ✕ / Alt+F4 means "put this away"
/// and leaves the session restorable. Both close the window and differ only in
/// what the next launch shows. That must not depend on whether the
/// `ask-before-closing` prompt appeared in between, so the confirm action
/// carries this choice.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DropPanes {
    Yes,
    No,
}

/// The action a confirmed modal dispatches when the user accepts. Used by
/// the `ask_before_closing` flow (`Action::CloseWindow` / `CloseTab` /
/// `ClosePane`) and keybind rebind conflicts. See
/// [`TERMINATOR-CONFIRM-DIALOG-DESIGN.md`](
/// ../../../docs/TERMINATOR-CONFIRM-DIALOG-DESIGN.md).
#[allow(clippy::enum_variant_names)] // close-family prefix is intentional
#[derive(Debug, Clone)]
pub enum ConfirmAction {
    /// Close the entire window (every tab + every pane).
    ///
    /// `drop_panes` carries the requester's intent through the prompt, so
    /// confirming does what the gesture would have done unprompted.
    CloseWindow { drop_panes: DropPanes },
    /// Close whichever tab holds any of these panes.
    ///
    /// Every tab close routes through here, including the focused-tab one.
    /// A prompt can sit unanswered for as long as the user takes, and in that
    /// time a shell exiting renumbers the tabs — so "the tab at index N" and
    /// "the focused tab" both stop meaning what they meant when the prompt
    /// went up. Naming the tab by the panes it held is stable across that; an
    /// empty resolution means the tab is already gone.
    CloseTabHolding(Vec<u64>),
    /// Close this specific pane.
    ///
    /// Carries the id for the same reason: while the prompt is up, the
    /// focused pane can change — the target's own shell exiting promotes a
    /// sibling into focus — and confirming would then close the sibling, which
    /// may be a tmux or agent session the user never selected.
    ClosePane(u64),
    /// Finish a Settings keybind rebind that would otherwise silently steal
    /// a chord already bound to a different action. Once the user confirms
    /// the reassignment, applies via `App::apply_keybind_rebind`, the same
    /// call as the direct (no-conflict) rebind path.
    RebindKeybind {
        trig: Trigger,
        act: Action,
        action_name: &'static str,
    },
}

/// Which buttons a confirm modal shows. v1 is just
/// the two-button [Cancel] / [Confirm] shape; future additions can
/// add a third "Apply to all" or similar without rippling.
#[derive(Debug, Clone)]
pub enum ConfirmButton {
    /// Dismiss the modal without action. Always the safe default.
    Cancel,
    /// Dispatch the dialog's `on_confirm` action. `destructive: true`
    /// draws the label in bold (Close/Delete); `false` keeps the regular
    /// weight (OK/Apply).
    Confirm { label: String, destructive: bool },
}

/// Live state for an open confirm dialog. `focus_idx`
/// points into `buttons` and the renderer / keyboard nav follow it.
#[derive(Debug, Clone)]
pub struct ConfirmDialogState {
    pub prompt: String,
    pub buttons: Vec<ConfirmButton>,
    pub focus_idx: usize,
    pub on_confirm: ConfirmAction,
}

/// UI-side context-menu state (Terminator / GNOME / iTerm2 parity).
/// Anchor is the post-clamp panel top-left; rows mirror the renderer's
/// `ContextMenu` slice but carry the live `Action` for dispatch.
pub(crate) struct ContextMenuState {
    anchor: (f32, f32),
    /// DPI scale at which `anchor` was captured. Anchors are physical pixels;
    /// rescale them across monitor transitions before clamping so the menu
    /// keeps the same logical relationship to the pointer.
    anchor_scale: f64,
    items: Vec<ContextMenuItem>,
    /// Index of the currently highlighted item — always points at an
    /// enabled `Item`, never a `Separator` or disabled row. Updated by
    /// keyboard nav (`↑↓`) and mouse hover.
    highlight: usize,
    /// Drill-in stack. When the user clicks a `Submenu` row, the
    /// parent's items are pushed here and replaced by the submenu's
    /// items. Esc / "Back" pops back to the parent.
    ///
    /// Menus nest one level deep today (see "no nested-nested
    /// submenus" in [`TERMINATOR-THEME-SUBMENU-DESIGN.md`](
    /// ../../../docs/TERMINATOR-THEME-SUBMENU-DESIGN.md)), but the
    /// stack works at any depth.
    drill_stack: Vec<Vec<ContextMenuItem>>,
    /// Scroll offset for long submenus (Theme has ~512 entries).
    /// `panel_h` is clamped to fit the surface, the visible window
    /// is `[scroll_offset, scroll_offset + max_visible_rows)`, and
    /// wheel / `↑↓` past the last visible row advances `scroll_offset`.
    /// Drill-in resets it to 0; drill-pop restores the parent's value
    /// from `scroll_stack`.
    scroll_offset: usize,
    /// Parallel stack to `drill_stack`: the scroll_offset to restore
    /// when popping back to each level. Same length as `drill_stack`
    /// at all times.
    scroll_stack: Vec<usize>,
    /// Typeahead buffer (Terminator menu UX). As the
    /// user types A-Z chars, we accumulate them here and best-match
    /// against item labels (case-insensitive prefix). A single char
    /// also resolves to a mnemonic (first matchable char of any
    /// row), so common items like Copy = 'C' / Theme = 'T' are
    /// one-keystroke; multi-char "th" → Theme by prefix.
    ///
    /// Cleared after 750ms of inactivity (`typeahead_until`) so a
    /// pause restarts the buffer instead of accumulating forever.
    typeahead_buf: String,
    /// Deadline after which `typeahead_buf` is cleared
    /// on the next key. `None` when the buffer is empty.
    typeahead_until: Option<std::time::Instant>,
}

/// Pure: which segment index the tab-bar cursor falls in,
/// using the same rendered segment rects that hit-testing and painting use.
/// Used by the drag-to-reorder handler — the user grabs a tab,
/// drags, and the bar reorders to keep the dragged segment under the cursor.
/// Clamped to the first/last rendered segment so a cursor that overshoots
/// either edge still produces a valid target. Returns 0 for an empty bar.
fn tab_drag_target_index(
    cursor_x: f32,
    cursor_y: f32,
    segments: &[kettle_render::TabSeg],
) -> usize {
    let Some(first) = segments.first() else {
        return 0;
    };
    // Which way the strip runs is a property of what was drawn: a vertical bar
    // stacks its segments down a shared column, a horizontal one lays them
    // across a shared row. Reading it back off the segments means the drag can
    // never disagree with the geometry the user is looking at.
    //
    // Testing `cursor_x` alone would break vertical bars, where every segment
    // shares one x span and the first one would always match.
    let vertical = segments.iter().any(|seg| seg.rect.1 != first.rect.1);
    for seg in segments {
        let (x, y, w, h) = seg.rect;
        let (cursor, end) = if vertical {
            (cursor_y, y + h)
        } else {
            (cursor_x, x + w)
        };
        if cursor < end {
            return seg.idx;
        }
    }
    segments.last().map(|seg| seg.idx).unwrap_or(0)
}

/// Pixel distance a held tab press must move before Kettle promotes the click
/// into the in-window reorder gesture. This is intentionally larger than the
/// low-level detachable-tab FSM threshold: a tab click should stay visually
/// anchored to the selected segment through normal hand jitter, while a real
/// drag still starts quickly at typical tab-bar heights.
fn tab_reorder_drag_threshold_px(tab_bar_h: f32) -> f32 {
    (tab_bar_h * 0.5).clamp(8.0, 16.0)
}

/// Pixel distance a held per-pane-titlebar press must move before it becomes a
/// pane drag rather than a click.
///
/// A flat constant, unlike [`tab_reorder_drag_threshold_px`], because the
/// competing gesture is different: a tab press competes with a reorder along a
/// strip whose height sets the natural scale, while a titlebar press competes
/// with "click again to rename". Renaming is the destructive-to-undo one, so the
/// slop is generous enough that ordinary hand jitter during a double click never
/// picks the pane up.
const PANE_DRAG_THRESHOLD_PX: f32 = 12.0;

/// Euclidean distance from a point to the nearest
/// edge of a rect — `0.0` when the point is inside. The tear decision is
/// "distance from the tab band ≥ threshold", which gives UNIFORM hysteresis
/// in every direction away from the band (the Chromium model): drag along
/// the strip = reorder, drag perpendicular past the slop = tear. Because a
/// `Top` band's upper edge coincides with the window's top edge, "above the
/// window" falls out of the same math — no separate outside-the-window
/// clause needed.
fn dist_to_rect(cx: f32, cy: f32, rect: (f32, f32, f32, f32)) -> f32 {
    let (rx, ry, rw, rh) = rect;
    let dx = (rx - cx).max(cx - (rx + rw)).max(0.0);
    let dy = (ry - cy).max(cy - (ry + rh)).max(0.0);
    (dx * dx + dy * dy).sqrt()
}

/// Has the cursor moved far enough from the tab
/// band to tear the dragged tab off into its own window? Pure so the
/// per-orientation cases are unit-testable without a window.
fn tear_threshold_crossed(cx: f32, cy: f32, band: (f32, f32, f32, f32), threshold: f32) -> bool {
    threshold > 0.0 && dist_to_rect(cx, cy, band) >= threshold
}

/// How far (0.0..=1.0) the cursor has travelled from
/// the tab band toward the tear threshold. 0.0 at/inside the band, 1.0 at
/// (or past) the exact distance `tear_threshold_crossed` fires at, so the
/// ghost's visual lift saturates precisely where the tear happens. A
/// non-positive threshold can never tear, so it also never lifts. Pure for
/// the same unit-testability reason as `tear_threshold_crossed`.
fn tear_lift_ratio(cx: f32, cy: f32, band: (f32, f32, f32, f32), threshold: f32) -> f32 {
    if threshold <= 0.0 {
        return 0.0;
    }
    (dist_to_rect(cx, cy, band) / threshold).clamp(0.0, 1.0)
}

/// Re-dock insertion index for a torn-off tab dropped at
/// `cursor` (main-axis coordinate) given the existing segments' main-axis
/// midpoints, in order. First segment whose midpoint exceeds the cursor
/// wins; past every midpoint appends. Distinct from `tab_drag_target_index`
/// (which picks the segment UNDER the cursor for reorder): docking inserts
/// BETWEEN segments, so a strip of n tabs has n+1 valid slots.
fn dock_insertion_index(seg_mids: &[f32], cursor: f32) -> usize {
    seg_mids
        .iter()
        .position(|&m| cursor < m)
        .unwrap_or(seg_mids.len())
}

/// Width of the strip that horizontal tab segments tile across, given the
/// surface width and the trailing new-tab button geometry.
///
/// `tab_bar()` lays segments out across this width, and the drag-to-reorder
/// handler hit-tests those rendered segments, so the drag target can't drift
/// from what is drawn. `arrow_w` is `0.0` when the dropdown is absent
/// (vertical bars). Floored at `plus_w` so a very narrow bar still reserves room
/// for the `+` button.
fn tab_segment_strip_width(surface_w: f32, plus_w: f32, arrow_w: f32) -> f32 {
    (surface_w - plus_w - arrow_w).max(plus_w)
}

/// The ✕ hit zone for one tab segment, or an EMPTY rect when the button is
/// configured off.
///
/// With `close-button-on-tab = false`, a full-size hit rect would still be
/// probed by the press handler, the `ctl` press handler, and the pointer-cursor
/// hover test. Clicking a tab's trailing square would then close it through an
/// invisible button, killing every pane in that tab. A zero-size rect fixes all
/// three, because every consumer tests with a strict `px < rx + rw`, which no
/// zero-width rect can satisfy. `tab_title_rect` reads `close.0` only when the
/// button is visible, so the reclaimed label space is unaffected.
fn tab_close_rect(
    trailing_x: f32,
    y: f32,
    height: f32,
    close_visible: bool,
) -> kettle_render::Rect4 {
    if close_visible {
        (trailing_x, y, height, height)
    } else {
        (trailing_x, y, 0.0, 0.0)
    }
}

/// Text lane inside a tab segment. The close button is visible chrome, so the
/// label must be centered in the lane that remains before that button rather
/// than centered against the full segment and visually drifting under `✕`.
fn tab_title_rect(
    segment: kettle_render::Rect4,
    close: kettle_render::Rect4,
    close_visible: bool,
) -> kettle_render::Rect4 {
    let (x, y, w, h) = segment;
    let left = x + 8.0;
    let right = if close_visible { close.0 } else { x + w - 8.0 };
    (left, y, (right - left).max(0.0), h)
}

/// Should the new-tab `▾` dropdown arrow be shown? Always yes. Besides the
/// shells, the dropdown carries Settings / Command palette / About rows
/// (Windows Terminal's bottom section), so it is never a pointless one-item
/// menu, even on a bash-only Ubuntu.
fn new_tab_dropdown_visible() -> bool {
    true
}

/// Letters the menu's vim navigation layer (`vim-menu-nav`) consumes
/// (`g`/`G` first/last, `h` back, `j`/`k` move, `l` activate). While the
/// setting is on, `assign_mnemonics` must not hand any of these to a row.
/// The nav layer intercepts them before mnemonic dispatch, so a row keyed on
/// one would silently lose its hotkey.
const VIM_NAV_RESERVED: &[char] = &['g', 'h', 'j', 'k', 'l'];

/// Display-column budget for one context-menu item, kept in lockstep with the
/// row constructed by `context_menu_overlay` and the renderer's
/// `menu_row_chars`. Centralizing this prevents the initial anchor clamp,
/// resize/DPI reclamp, hit testing, ellipsis, and draw width from disagreeing.
fn context_menu_item_columns(item: &ContextMenuItem, hint: &str) -> usize {
    let (label, suffix, shows_hint): (&str, &str, bool) = match item {
        ContextMenuItem::Item { label, .. } => (label, "", true),
        ContextMenuItem::DynamicItem { label, .. } => (label, "", true),
        ContextMenuItem::LuaItem { label, .. } => (label, "", false),
        ContextMenuItem::ConfigItem { label, .. } => (label, "", false),
        ContextMenuItem::Submenu { label, .. } => (label, " ▸", false),
        ContextMenuItem::ProfileChoice { label, .. }
        | ContextMenuItem::WindowChoice { label, .. } => (label, "", false),
        ContextMenuItem::NewTabShell { label, .. } => (label, "", true),
        ContextMenuItem::UrlItem { label, .. } => (label, "", false),
        ContextMenuItem::Media { label, .. } => (label, "", false),
        ContextMenuItem::Info { label } => (label, "", false),
        ContextMenuItem::Separator => return 0,
    };
    label.width()
        + suffix.width()
        + if shows_hint && !hint.is_empty() {
            hint.width() + 2
        } else {
            0
        }
}

/// Compute mnemonics for the context-menu rows. For each row, returns
/// `Some((byte_index, char))` where `char` is the first lowercase A-Z
/// letter in the label that hasn't already been claimed by an earlier row,
/// or `None` for rows without any A-Z (separators, choice rows with no
/// label letters, etc.).
///
/// First-letter is the canonical priority (matches GTK / Win32);
/// fall through to subsequent letters only if the first letter is
/// already taken by an earlier row. Pure so the collision rules
/// are unit-tested without spinning up App.
fn assign_mnemonics(items: &[ContextMenuItem], reserved: &[char]) -> Vec<Option<(usize, char)>> {
    let labels: Vec<&str> = items
        .iter()
        .map(|it| match it {
            ContextMenuItem::Item { label, .. } => *label,
            ContextMenuItem::DynamicItem { label, .. } => label.as_str(),
            ContextMenuItem::LuaItem { label, .. } => label.as_str(),
            ContextMenuItem::ConfigItem { label, .. } => label.as_str(),
            ContextMenuItem::Submenu { label, .. } => label.as_str(),
            ContextMenuItem::ProfileChoice { label, .. }
            | ContextMenuItem::WindowChoice { label, .. } => label.as_str(),
            ContextMenuItem::NewTabShell { label, .. } => label.as_str(),
            ContextMenuItem::UrlItem { label, .. } => *label,
            ContextMenuItem::Media { label, .. } => *label,
            // Info rows are non-dispatchable — no mnemonic to claim.
            ContextMenuItem::Info { .. } => "",
            ContextMenuItem::Separator => "",
        })
        .collect();
    let mut claimed: std::collections::HashSet<char> = std::collections::HashSet::new();
    let mut out: Vec<Option<(usize, char)>> = vec![None; labels.len()];
    // Two rounds. The stable core rows claim their letters first, then the
    // context-dependent UrlItem rows (present only when the right-click landed
    // on a link) claim from what's left. Otherwise "Open Link" / "Copy Link
    // Address", which lead the menu, would take 'o'/'c' and silently remap
    // muscle-memory mnemonics ('p' would fire Copy instead of Paste).
    let round = |items: &[ContextMenuItem], idx: usize| -> usize {
        usize::from(matches!(
            items[idx],
            ContextMenuItem::UrlItem { .. } | ContextMenuItem::Media { .. }
        ))
    };
    for pass in 0..2 {
        for (i, label) in labels.iter().enumerate() {
            if round(items, i) != pass {
                continue;
            }
            let mut chosen: Option<(usize, char)> = None;
            for (bi, c) in label.char_indices() {
                if !c.is_ascii_alphabetic() {
                    continue;
                }
                let low = c.to_ascii_lowercase();
                // Letters owned by vim-menu-nav are never assignable.
                if reserved.contains(&low) {
                    continue;
                }
                if !claimed.contains(&low) {
                    claimed.insert(low);
                    chosen = Some((bi, low));
                    break;
                }
            }
            out[i] = chosen;
        }
    }
    out
}

/// Match the user's typeahead buffer to a row by
/// case-insensitive prefix on the label. Returns the first
/// dispatchable row whose label (lowercased) starts with `buf`
/// (also lowercased). Separators/empty labels are skipped.
fn typeahead_match(items: &[ContextMenuItem], buf: &str) -> Option<usize> {
    if buf.is_empty() {
        return None;
    }
    let needle = buf.to_ascii_lowercase();
    items.iter().position(|it| match it {
        ContextMenuItem::Item {
            label,
            enabled: true,
            ..
        } => label.to_ascii_lowercase().starts_with(&needle),
        ContextMenuItem::DynamicItem {
            label,
            enabled: true,
            ..
        } => label.to_ascii_lowercase().starts_with(&needle),
        ContextMenuItem::LuaItem { label, .. }
        | ContextMenuItem::ConfigItem { label, .. }
        | ContextMenuItem::Submenu { label, .. }
        | ContextMenuItem::WindowChoice { label, .. }
        | ContextMenuItem::ProfileChoice { label, .. }
        | ContextMenuItem::NewTabShell { label, .. } => {
            label.to_ascii_lowercase().starts_with(&needle)
        }
        ContextMenuItem::UrlItem { label, .. } | ContextMenuItem::Media { label, .. } => {
            label.to_ascii_lowercase().starts_with(&needle)
        }
        // Info rows aren't dispatchable, so typeahead skips them.
        _ => false,
    })
}

/// How many context-menu rows starting at
/// `start` fit within `panel_h` pixels. Separators take `sep_h`,
/// every other row takes `row_h`. Used by `step_context_menu_highlight`
/// and `scroll_context_menu` to keep `scroll_offset` honest when the
/// panel is height-clamped by `context_menu_geometry`. Pure so the
/// arithmetic is drift-guarded without standing up the App.
fn count_rows_fitting(
    items: &[ContextMenuItem],
    start: usize,
    panel_h: f32,
    row_h: f32,
    sep_h: f32,
) -> usize {
    let mut used = 0.0_f32;
    let mut count = 0;
    for it in items.iter().skip(start) {
        let h = context_menu_item_height(it, row_h, sep_h);
        if used + h > panel_h {
            break;
        }
        used += h;
        count += 1;
    }
    count
}

fn context_menu_item_height(item: &ContextMenuItem, row_h: f32, sep_h: f32) -> f32 {
    if matches!(item, ContextMenuItem::Separator) {
        sep_h
    } else {
        row_h
    }
}

/// Earliest suffix that fits through the final row. Scrolling past it would
/// leave avoidable blank space below the menu. This is O(items) even for the
/// 512-entry theme submenu.
fn context_menu_max_scroll_offset(
    items: &[ContextMenuItem],
    panel_h: f32,
    row_h: f32,
    sep_h: f32,
) -> usize {
    if items.is_empty() {
        return 0;
    }
    let mut suffix_height = 0.0;
    let mut max_offset = items.len() - 1;
    for candidate in (0..items.len()).rev() {
        let next = suffix_height + context_menu_item_height(&items[candidate], row_h, sep_h);
        if next > panel_h {
            break;
        }
        suffix_height = next;
        max_offset = candidate;
    }
    max_offset
}

fn context_menu_scroll_for_highlight(
    items: &[ContextMenuItem],
    current_offset: usize,
    highlight: usize,
    panel_h: f32,
    row_h: f32,
    sep_h: f32,
) -> usize {
    if items.is_empty() {
        return 0;
    }
    let highlight = highlight.min(items.len() - 1);
    let max_offset = context_menu_max_scroll_offset(items, panel_h, row_h, sep_h);
    let mut offset = current_offset.min(max_offset);
    let visible = count_rows_fitting(items, offset, panel_h, row_h, sep_h);
    if highlight < offset {
        offset = highlight;
    } else if highlight >= offset.saturating_add(visible) {
        // Pull back until the highlight is the last fully visible row. This
        // keeps Enter bound to a visible choice after a window/DPI shrink.
        let mut used = 0.0;
        offset = highlight;
        for candidate in (0..=highlight).rev() {
            let next = used + context_menu_item_height(&items[candidate], row_h, sep_h);
            if next > panel_h {
                break;
            }
            used = next;
            offset = candidate;
        }
    }
    offset.min(max_offset)
}

fn ellipsize_menu_label(label: &str, max_columns: usize) -> String {
    use unicode_segmentation::UnicodeSegmentation as _;

    if label.width() <= max_columns {
        return label.to_string();
    }
    if max_columns == 0 {
        return String::new();
    }
    if max_columns == 1 {
        return "…".to_string();
    }
    let content_columns = max_columns - 1;
    let mut used: usize = 0;
    let mut output = String::new();
    for grapheme in label.graphemes(true) {
        let width = grapheme.width();
        if used.saturating_add(width) > content_columns {
            break;
        }
        output.push_str(grapheme);
        used += width;
    }
    output.push('…');
    output
}

/// Drop disabled rows from the context menu and collapse the separators
/// they would orphan. Hiding them instead of greying them out matches
/// Terminator / GNOME Terminal, which show only what you can click.
///
/// Three passes:
///   1. drop any disabled `Item` or `DynamicItem`. Other variants (LuaItem,
///      ConfigItem, Submenu, Theme/ProfileChoice, Separator) stay.
///   2. collapse runs of `Separator` to a single one.
///   3. trim leading + trailing separators (orphaned by step 1).
///
/// Pure so the contract is unit-tested without spinning up App.
fn filter_disabled(items: Vec<ContextMenuItem>) -> Vec<ContextMenuItem> {
    // Step 1: drop disabled Items.
    let kept: Vec<ContextMenuItem> = items
        .into_iter()
        .filter(|it| {
            !matches!(
                it,
                ContextMenuItem::Item { enabled: false, .. }
                    | ContextMenuItem::DynamicItem { enabled: false, .. }
            )
        })
        .collect();
    // Step 2: collapse separator runs. Walk linearly; only push a
    // Separator when the previous pushed item wasn't already one.
    let mut collapsed: Vec<ContextMenuItem> = Vec::with_capacity(kept.len());
    let mut last_was_sep = true; // pretend the "before-start" was a sep so leading sep gets dropped
    for it in kept {
        let is_sep = matches!(it, ContextMenuItem::Separator);
        if is_sep && last_was_sep {
            continue;
        }
        last_was_sep = is_sep;
        collapsed.push(it);
    }
    // Step 3: trim a trailing separator (orphan).
    if let Some(ContextMenuItem::Separator) = collapsed.last() {
        collapsed.pop();
    }
    collapsed
}

/// Terminator menu UX, hover-to-highlight. Walk the
/// vertical pixel layout of a context-menu's rows and return the
/// row index containing `cursor_y`, or `None` if the cursor landed
/// on a separator (visual gap) or beyond the last row. Pure so the
/// arithmetic + the separator-skip contract is unit-tested without
/// standing up an App + a winit window. A `true` item flags a separator (uses
/// `sep_h` instead of `row_h`). Accepting an iterator lets the live pointer path
/// project item kinds without allocating a temporary vector.
pub(crate) fn find_menu_row_y(
    cursor_y: f32,
    anchor_y: f32,
    panel_h: f32,
    row_h: f32,
    sep_h: f32,
    kinds: impl IntoIterator<Item = bool>,
) -> Option<usize> {
    let mut row_y = anchor_y;
    let panel_bottom = anchor_y + panel_h.max(0.0);
    for (idx, is_sep) in kinds.into_iter().enumerate() {
        let h = if is_sep { sep_h } else { row_h };
        // The renderer draws only complete rows. A clamped panel can leave a
        // short blank strip at the bottom; never dispatch the next invisible
        // row through that strip.
        if row_y + h > panel_bottom {
            break;
        }
        if cursor_y >= row_y && cursor_y < row_y + h {
            return if is_sep { None } else { Some(idx) };
        }
        row_y += h;
    }
    None
}

/// Terminator parity (`layoutlauncher.py`): rank saved
/// layouts against the user-typed query. Empty query returns
/// every layout in original (alphabetical) order; non-empty query
/// keeps only entries whose lower-cased name contains every
/// lower-cased query token. Same shape as
/// `kettle_config::palette::rank` but layouts have only a name
/// field (no description), so the inner predicate is simpler.
/// Pure and separate from `layout_picker_key` so a drift guard
/// can exercise it without touching App state.
pub(crate) fn rank_layouts(q: &str, layouts: &[String]) -> Vec<usize> {
    let q = q.trim().to_ascii_lowercase();
    if q.is_empty() {
        return (0..layouts.len()).collect();
    }
    let tokens: Vec<&str> = q.split_whitespace().collect();
    layouts
        .iter()
        .enumerate()
        .filter(|(_, name)| {
            let lower = name.to_ascii_lowercase();
            tokens.iter().all(|t| lower.contains(t))
        })
        .map(|(i, _)| i)
        .collect()
}

/// Indices into the configured SSH-host list, best fuzzy match first. Ties
/// preserve config order so an empty query has a stable initial selection.
fn rank_ssh_hosts(query: &str, hosts: &[(String, String)]) -> Vec<usize> {
    let query = query.trim();
    let mut ranked: Vec<(usize, i32)> = hosts
        .iter()
        .enumerate()
        .filter_map(|(index, (name, _))| {
            kettle_config::fuzzy::score(query, name).map(|score| (index, score))
        })
        .collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    ranked.into_iter().map(|(index, _)| index).collect()
}

fn selected_ssh_target(query: &str, selected: usize, hosts: &[(String, String)]) -> Option<String> {
    let ranked = rank_ssh_hosts(query, hosts);
    let selected = selected.min(ranked.len().saturating_sub(1));
    ranked
        .get(selected)
        .map(|&index| hosts[index].1.clone())
        .or_else(|| {
            let query = query.trim();
            (!query.is_empty()).then(|| query.to_string())
        })
}

struct PickerList {
    rows: Vec<ContextMenuRow>,
    selected: usize,
}

/// A picker's key hint: each key followed by what it does. The keys are the
/// same in every language.
fn picker_hint(tr: &kettle_i18n::Translator, hints: &[(&str, kettle_i18n::Text)]) -> String {
    let parts: Vec<String> = hints
        .iter()
        .map(|(keys, what)| format!("{keys} {}", tr.text(*what)))
        .collect();
    format!("({})", parts.join(" · "))
}

const PICKER_MAX_VISIBLE_ROWS: usize = 8;

fn command_picker_list(
    query: &str,
    selected: usize,
    bindings: &Bindings,
    tr: &kettle_i18n::Translator,
) -> PickerList {
    let commands = kettle_config::palette::commands();
    let ranked = kettle_config::palette::rank(query, &commands, tr);
    let rows = ranked
        .iter()
        .map(|&index| {
            let (label, action) = &commands[index];
            ContextMenuRow {
                label: tr.text(*label).to_string(),
                separator: false,
                enabled: true,
                hint: kettle_config::keybinds::hint_label(bindings, action).unwrap_or_default(),
            }
        })
        .collect::<Vec<_>>();
    if rows.is_empty() {
        PickerList {
            rows: vec![ContextMenuRow {
                label: tr
                    .text(kettle_i18n::Text::PickerNoMatchingCommand)
                    .to_string(),
                separator: false,
                enabled: false,
                hint: String::new(),
            }],
            selected: 0,
        }
    } else {
        PickerList {
            selected: selected.min(rows.len() - 1),
            rows,
        }
    }
}

fn layout_picker_list(
    query: &str,
    selected: usize,
    layouts: &[String],
    tr: &kettle_i18n::Translator,
) -> PickerList {
    let ranked = rank_layouts(query, layouts);
    let rows = ranked
        .iter()
        .map(|&index| ContextMenuRow {
            label: layouts[index].clone(),
            separator: false,
            enabled: true,
            hint: String::new(),
        })
        .collect::<Vec<_>>();
    if rows.is_empty() {
        let label = if layouts.is_empty() {
            kettle_i18n::Text::PickerNoSavedLayouts
        } else {
            kettle_i18n::Text::PickerNoMatchingLayout
        };
        PickerList {
            rows: vec![ContextMenuRow {
                label: tr.text(label).to_string(),
                separator: false,
                enabled: false,
                hint: if layouts.is_empty() {
                    "kettle --save-layout NAME".to_string()
                } else {
                    String::new()
                },
            }],
            selected: 0,
        }
    } else {
        PickerList {
            selected: selected.min(rows.len() - 1),
            rows,
        }
    }
}

/// The themes the theme picker lists for `query`, each with whether it is
/// dark. An empty query lists every theme of `opened_on`'s appearance in look
/// order, then the other appearance, so the arrows step between similar
/// palettes and reach the other appearance only at the end. A query ranks by
/// fuzzy match, ties keeping that order, except that a theme named exactly by
/// the query comes first: `dracula` scores the same against "Dracula+".
fn theme_picker_matches(query: &str, opened_on: &str) -> Vec<(&'static str, bool)> {
    let opened_dark = kettle_config::Theme::by_name(opened_on).is_dark();
    let order = [opened_dark, !opened_dark].into_iter().flat_map(|dark| {
        kettle_config::Theme::look_order(dark)
            .iter()
            .map(move |name| (*name, dark))
    });
    let query = query.trim();
    if query.is_empty() {
        return order.collect();
    }
    let mut ranked: Vec<(bool, i32, usize, (&'static str, bool))> = order
        .enumerate()
        .filter_map(|(index, theme)| {
            let exact = theme.0.eq_ignore_ascii_case(query);
            kettle_config::fuzzy::score(query, theme.0).map(|score| (exact, score, index, theme))
        })
        .collect();
    ranked.sort_by(|a, b| b.0.cmp(&a.0).then(b.1.cmp(&a.1)).then(a.2.cmp(&b.2)));
    ranked.into_iter().map(|(_, _, _, theme)| theme).collect()
}

/// The theme picker's rows. The theme it opened on is ticked, and each row
/// says whether it is dark or light.
fn theme_picker_list(
    query: &str,
    selected: usize,
    opened_on: &str,
    tr: &kettle_i18n::Translator,
) -> PickerList {
    use kettle_i18n::Text;
    let rows: Vec<ContextMenuRow> = theme_picker_matches(query, opened_on)
        .into_iter()
        .map(|(name, dark)| {
            let appearance = tr.text(if dark {
                Text::PickerThemeDark
            } else {
                Text::PickerThemeLight
            });
            let tick = if name.eq_ignore_ascii_case(opened_on.trim()) {
                "✓ "
            } else {
                ""
            };
            ContextMenuRow {
                label: name.to_string(),
                separator: false,
                enabled: true,
                hint: format!("{tick}{appearance}"),
            }
        })
        .collect();
    if rows.is_empty() {
        return PickerList {
            rows: vec![ContextMenuRow {
                label: tr.text(Text::PickerNoMatchingTheme).to_string(),
                separator: false,
                enabled: false,
                hint: String::new(),
            }],
            selected: 0,
        };
    }
    let selected = selected.min(rows.len() - 1);
    PickerList { rows, selected }
}

/// The theme the picker's highlighted row names, if any row matches. Clamped
/// like the painted highlight, so the preview and Enter use the row shown.
fn theme_picker_selection(state: &crate::window_state::ThemePickerState) -> Option<&'static str> {
    let matches = theme_picker_matches(&state.query, &state.opened_on);
    let last = matches.len().checked_sub(1)?;
    Some(matches[state.selected.min(last)].0)
}

/// A theme the window can wear: its name and colours.
type ThemeState = (String, kettle_config::Theme);

/// Open the theme picker on `live`, the theme the window wears, and keep it as
/// the baseline Esc restores. A preview still running from an earlier picker
/// is cancelled first, so the new picker opens on, ticks and restores the
/// theme from before that preview. Returns the theme to put back, if any.
fn begin_theme_picker(ws: &mut WindowState, live: ThemeState) -> Option<ThemeState> {
    let restore = ws.theme_preview.take();
    let opened = restore.clone().unwrap_or(live);
    ws.theme_picker_input = Some(crate::window_state::ThemePickerState {
        query: String::new(),
        selected: theme_picker_start(&opened.0),
        opened_on: opened.0.clone(),
    });
    ws.theme_preview = Some(opened);
    restore
}

/// The theme the window must switch to after an event, if any, while
/// `live_name` is the one it wears. An open picker shows its selection, or its
/// baseline while nothing matches the query; the baseline stays until the
/// picker closes. A picker that closed without keeping a theme (a kept one
/// clears the baseline first) puts the baseline back.
fn theme_preview_change(ws: &mut WindowState, live_name: &str) -> Option<ThemeState> {
    let Some(state) = ws.theme_picker_input.as_ref() else {
        return ws.theme_preview.take();
    };
    match theme_picker_selection(state) {
        Some(name) if name == live_name => None,
        Some(name) => Some((name.to_string(), kettle_config::Theme::by_name(name))),
        None => ws
            .theme_preview
            .as_ref()
            .filter(|(name, _)| name != live_name)
            .cloned(),
    }
}

/// End an input-method composition when the modal that owned it closes (see
/// `remember_closing_key`). A late Commit no longer matches the focus
/// generation, so it is dropped instead of typed into whatever the modal
/// covered.
fn end_modal_composition(ws: &mut WindowState) {
    ws.ime_focus_generation = ws.ime_focus_generation.wrapping_add(1);
    if ws.ime_preedit_owner.is_some() {
        ws.ime_preedit = None;
    }
}

/// Where the theme picker opens: on the current theme, so the first arrow
/// press steps to its nearest look.
fn theme_picker_start(current: &str) -> usize {
    theme_picker_matches("", current)
        .iter()
        .position(|(name, _)| name.eq_ignore_ascii_case(current.trim()))
        .unwrap_or(0)
}

fn ssh_picker_list(
    query: &str,
    selected: usize,
    hosts: &[(String, String)],
    tr: &kettle_i18n::Translator,
) -> PickerList {
    let ranked = rank_ssh_hosts(query, hosts);
    let rows = ranked
        .iter()
        .map(|&index| ContextMenuRow {
            label: hosts[index].0.clone(),
            separator: false,
            enabled: true,
            hint: String::new(),
        })
        .collect::<Vec<_>>();
    if rows.is_empty() {
        PickerList {
            rows: vec![ContextMenuRow {
                label: tr
                    .text(if hosts.is_empty() {
                        kettle_i18n::Text::PickerNoConfiguredHosts
                    } else {
                        kettle_i18n::Text::PickerNoMatchingHost
                    })
                    .to_string(),
                separator: false,
                enabled: false,
                hint: tr.text(kettle_i18n::Text::PickerTypedTarget).to_string(),
            }],
            selected: 0,
        }
    } else {
        PickerList {
            selected: selected.min(rows.len() - 1),
            rows,
        }
    }
}

/// Keep the selected picker row inside the visible suffix. Picker rows have no
/// separators, so this is the context-menu scroll rule reduced to equal-height
/// rows and can be recomputed from selection on each frame.
fn picker_scroll_offset(
    row_count: usize,
    selected: usize,
    panel_height: f32,
    row_height: f32,
) -> usize {
    if row_count == 0
        || !panel_height.is_finite()
        || !row_height.is_finite()
        || panel_height <= 0.0
        || row_height <= 0.0
    {
        return 0;
    }
    let visible = ((panel_height / row_height).floor() as usize)
        .max(1)
        .min(row_count);
    let selected = selected.min(row_count - 1);
    selected
        .saturating_add(1)
        .saturating_sub(visible)
        .min(row_count - visible)
}

/// Place a picker list above its bottom input lane using the same rows, width
/// budget, clipping, selection rail, and overflow cues as the context menu.
fn picker_context_menu(
    mut list: PickerList,
    surface: (f32, f32),
    cell: (f32, f32),
) -> Option<ContextMenu> {
    let (surface_w, surface_h) = surface;
    let (cell_w, cell_h) = cell;
    let input_height = cell_h + 10.0;
    let list_surface = (surface_w, (surface_h - input_height - 4.0).max(0.0));
    if !context_menu_surface_can_fit_row(list_surface, cell) || list.rows.is_empty() {
        return None;
    }

    let row_height = cell_h + kettle_render::menu::ROW_PAD;
    let max_columns = list
        .rows
        .iter()
        .map(kettle_render::menu_row_chars)
        .max()
        .unwrap_or(0) as f32;
    let natural_width = kettle_render::menu::panel_width(max_columns, cell_w);
    let natural_height = row_height * list.rows.len().min(PICKER_MAX_VISIBLE_ROWS) as f32;
    let panel = clamp_context_menu_panel((natural_width, natural_height), list_surface);
    let max_columns = kettle_render::menu::panel_columns(panel.0, cell_w);
    for row in &mut list.rows {
        fit_context_menu_row(row, max_columns);
    }
    let scroll_offset = picker_scroll_offset(list.rows.len(), list.selected, panel.1, row_height);
    let requested_anchor = (
        (surface_w - panel.0) * 0.5,
        (list_surface.1 - panel.1 - 4.0).max(4.0),
    );
    let anchor = clamp_context_menu_anchor(requested_anchor, panel, list_surface);
    Some(ContextMenu {
        anchor,
        rows: list.rows,
        highlight: list.selected,
        scroll_offset,
        panel_w_clamped: panel.0,
        panel_h_clamped: panel.1,
    })
}

/// The open picker's rows as a menu panel: the first of `pickers` that is
/// open, in key-routing order.
fn picker_overlay_context_menu(
    pickers: [Option<PickerList>; 4],
    surface: (f32, f32),
    cell: (f32, f32),
) -> Option<ContextMenu> {
    pickers
        .into_iter()
        .flatten()
        .next()
        .and_then(|list| picker_context_menu(list, surface, cell))
}

/// The `vim-menu-nav` `Ctrl+d`/`Ctrl+u` half-page target. Moves
/// `current` by `rows` items in `dir` (no wrap — vim half-page semantics
/// clamp at the ends), then snaps to the nearest dispatchable row in the
/// direction of travel (falling back to the other direction so a
/// trailing separator can't strand the highlight). Pure so the
/// clamp+snap math is unit-testable without App state.
fn half_page_menu_target(
    items: &[ContextMenuItem],
    current: usize,
    rows: usize,
    dir: isize,
) -> usize {
    if items.is_empty() {
        return current;
    }
    let n = items.len() as isize;
    let step = rows.max(1) as isize;
    let raw = (current as isize + dir * step).clamp(0, n - 1) as usize;
    let scan_down = |from: usize| (from..items.len()).find(|&i| item_is_dispatchable(&items[i]));
    let scan_up = |from: usize| (0..=from).rev().find(|&i| item_is_dispatchable(&items[i]));
    let snapped = if dir > 0 {
        scan_down(raw).or_else(|| scan_up(raw))
    } else {
        scan_up(raw).or_else(|| scan_down(raw))
    };
    snapped.unwrap_or(current)
}

/// Whether keyboard nav can land on `item` and Enter / click can dispatch it.
fn item_is_dispatchable(item: &ContextMenuItem) -> bool {
    matches!(
        item,
        ContextMenuItem::Item { enabled: true, .. }
            | ContextMenuItem::DynamicItem { enabled: true, .. }
            | ContextMenuItem::LuaItem { .. }
            | ContextMenuItem::ConfigItem { .. }
            // Submenu rows are dispatchable for keyboard
            // nav (↑↓ lands on them); click / Enter drills in.
            | ContextMenuItem::Submenu { .. }
            // Profile choice leaves are the *contents* of a drilled-in
            // Profile ▸ submenu. Without them, keyboard nav inside that
            // submenu could not land on any row or pick a profile.
            | ContextMenuItem::WindowChoice { .. }
            | ContextMenuItem::ProfileChoice { .. }
            // New-tab ▾ shell choices are always clickable + keyboard-
            // navigable.
            | ContextMenuItem::NewTabShell { .. }
            // The URL-aware "Open Link" / "Copy Link Address" rows.
            | ContextMenuItem::UrlItem { .. }
            // A card's or the viewer's media rows.
            | ContextMenuItem::Media { .. } // ContextMenuItem::Info is deliberately absent: a static info line
                                            // (About panel) is not highlightable or clickable.
    )
}

/// Map a context-menu row at position `idx` (within the current level)
/// to the click it dispatches. Shared by the mouse hit-test
/// ([`App::context_menu_click_action`]) and the keyboard Enter / Space and
/// mnemonic paths so every dispatchable row type (submenu, Lua,
/// config-command, theme/profile choice, new-tab shell) is reachable
/// identically from mouse and keyboard. One mapper keeps the three input
/// paths from drifting apart.
fn item_to_click(item: &ContextMenuItem, idx: usize) -> Option<ContextMenuClick> {
    match item {
        ContextMenuItem::Item {
            action,
            enabled: true,
            ..
        }
        | ContextMenuItem::DynamicItem {
            action,
            enabled: true,
            ..
        } => Some(ContextMenuClick::Action(action.clone())),
        ContextMenuItem::LuaItem { lua_idx, .. } => Some(ContextMenuClick::LuaMenuItem(*lua_idx)),
        ContextMenuItem::ConfigItem { command, .. } => {
            Some(ContextMenuClick::ConfigCommand(command.clone()))
        }
        ContextMenuItem::Submenu { .. } => Some(ContextMenuClick::DrillIntoSubmenu(idx)),
        ContextMenuItem::WindowChoice { window, panes, .. } => {
            Some(ContextMenuClick::MoveTabToWindow {
                window: *window,
                panes: Arc::clone(panes),
            })
        }
        ContextMenuItem::ProfileChoice { profile, .. } => {
            Some(ContextMenuClick::SetProfile(profile.clone()))
        }
        ContextMenuItem::NewTabShell { argv, .. } => {
            Some(ContextMenuClick::NewTabWithArgv(argv.clone()))
        }
        ContextMenuItem::UrlItem { url, how, pane, .. } => Some(ContextMenuClick::Url {
            url: url.clone(),
            how: *how,
            pane: *pane,
        }),
        ContextMenuItem::Media { target, action, .. } => Some(ContextMenuClick::Media {
            target: *target,
            action: *action,
        }),
        ContextMenuItem::Item { enabled: false, .. }
        | ContextMenuItem::DynamicItem { enabled: false, .. }
        | ContextMenuItem::Info { .. }
        | ContextMenuItem::Separator => None,
    }
}

/// Pure: walk the menu item list to find the next enabled, non-
/// separator row index, given a `delta` (±1) and a wrap-around at the
/// list ends. Used by both `↑` and `↓` keyboard nav. Returns `current`
/// unchanged if no enabled rows exist at all (defensive; the menu
/// shouldn't have been opened with zero actionable rows).
fn next_context_menu_highlight(items: &[ContextMenuItem], current: usize, delta: isize) -> usize {
    if items.is_empty() {
        return current;
    }
    let len = items.len() as isize;
    let step = if delta >= 0 { 1 } else { -1 };
    let mut i = current as isize;
    for _ in 0..len {
        i = (i + step).rem_euclid(len);
        if item_is_dispatchable(&items[i as usize]) {
            return i as usize;
        }
    }
    current
}

/// Pure: clamp the requested panel anchor so the panel of size
/// `(panel_w, panel_h)` stays fully inside a surface of size
/// `(surface_w, surface_h)`. A 4-px screen-edge margin so the panel
/// reads as floating rather than glued to the edge. Right-click near
/// the bottom-right corner therefore flips the menu up-and-left
/// instead of rendering off-screen.
fn clamp_context_menu_anchor(
    (req_x, req_y): (f32, f32),
    (panel_w, panel_h): (f32, f32),
    (surface_w, surface_h): (f32, f32),
) -> (f32, f32) {
    let margin = 4.0_f32;
    let max_x = (surface_w - panel_w - margin).max(margin);
    let max_y = (surface_h - panel_h - margin).max(margin);
    let x = req_x.clamp(margin, max_x);
    let y = req_y.clamp(margin, max_y);
    (x, y)
}

fn clamp_context_menu_panel(
    (panel_w, panel_h): (f32, f32),
    (surface_w, surface_h): (f32, f32),
) -> (f32, f32) {
    let available_w = (surface_w - 8.0).max(1.0);
    let available_h = (surface_h - 8.0).max(1.0);
    (panel_w.min(available_w), panel_h.min(available_h))
}

fn context_menu_surface_can_fit_row(
    (surface_w, surface_h): (f32, f32),
    (cell_w, cell_h): (f32, f32),
) -> bool {
    surface_w.is_finite()
        && surface_h.is_finite()
        && cell_w.is_finite()
        && cell_h.is_finite()
        && surface_w >= 8.0 + kettle_render::menu::H_PAD + cell_w.max(1.0)
        && surface_h >= 8.0 + cell_h.max(1.0) + kettle_render::menu::ROW_PAD
}

fn fit_context_menu_row(row: &mut ContextMenuRow, max_columns: usize) {
    if row.separator {
        return;
    }
    let hint_columns = if row.hint.is_empty() {
        0
    } else {
        row.hint.width().saturating_add(2)
    };
    let hint_columns = if hint_columns >= max_columns {
        row.hint.clear();
        0
    } else {
        hint_columns
    };
    row.label = ellipsize_menu_label(&row.label, max_columns.saturating_sub(hint_columns));
}

fn scale_context_menu_anchor(
    (x, y): (f32, f32),
    previous_scale: f64,
    current_scale: f64,
) -> (f32, f32) {
    if !previous_scale.is_finite()
        || previous_scale <= 0.0
        || !current_scale.is_finite()
        || current_scale <= 0.0
    {
        return (x, y);
    }
    let ratio = (current_scale / previous_scale) as f32;
    (x * ratio, y * ratio)
}

/// `(active-tab-index, focused-leaf-id)` — the value `App::focus_key` returns.
pub(crate) type FocusKey = (usize, Option<u64>);
/// Cache key for the viewport link re-scan: `(focus, focused pane's
/// output_generation, its geometry_generation, scroll display_offset,
/// focused cwd)`. It uses the focused pane's generation, not the tab's
/// `last_output_at`, because the activity latch updates that only for
/// background tabs, so active-tab output would never invalidate the scan. The
/// geometry generation covers a resize, which reflows text with no output:
/// zooming a pane, splitting next to it, or resizing the window.
pub(crate) type LinksScanKey = (
    FocusKey,
    Option<u64>,
    Option<u64>,
    Option<usize>,
    Option<String>,
);

/// Re-scan the focused pane's visible links into `ws.links` unless the key
/// shows nothing they depend on has changed. The brief lock to read
/// display_offset is cheap; the avoided work is `kettle_core::links`'
/// per-cell regex pass.
fn scan_links(ws: &mut WindowState) {
    let key: LinksScanKey = {
        let focus = (ws.mux.active, ws.mux.active_focus());
        let focused = ws.mux.focused().map(|pane| &*pane);
        (
            focus,
            // Cheap atomic and short-lock reads.
            focused.map(|p| p.term.output_generation()),
            focused.map(|p| p.term.geometry_generation()),
            focused.and_then(|p| p.term.term.lock().ok().map(|t| t.grid().display_offset())),
            focused.and_then(|p| p.term.current_dir_or_native()),
        )
    };
    if ws.links_scan_key.as_ref() == Some(&key) {
        return;
    }
    // Focused interactive apps like `less -R` redraw visible text by writing
    // output, not by changing terminal scrollback display_offset, and a
    // resize reflows it with no output at all. Re-scan on either so path and
    // URL underline rects stay attached to the current text.
    ws.links = ws
        .mux
        .focused()
        .and_then(|p| {
            p.term
                .term
                .lock()
                .ok()
                .map(|t| kettle_core::links::links_with_cwd(&t, key.4.as_deref()))
        })
        .unwrap_or_default();
    ws.links_scan_key = Some(key);
}

/// How long the transient `cols×rows` chip stays up after the last resize
/// event. Ghostty `resize-overlay` parity, using Ghostty's
/// `resize-overlay-duration` default.
pub(crate) const RESIZE_OVERLAY_DURATION: std::time::Duration =
    std::time::Duration::from_millis(750);
/// How long a pane's visual-bell flash lasts from the frame it rang. One
/// constant for the redraw pacing and the ramp, so the two cannot drift.
pub(crate) const BELL_FLASH_DURATION: std::time::Duration = std::time::Duration::from_millis(300);

/// The visual-bell flash's remaining strength `elapsed` after the bell: 1.0
/// the frame it rang, 0.0 once `BELL_FLASH_DURATION` has passed. Instant on,
/// then an ease-out (quadratic) decay: the peak is what the eye notices, so
/// the wash leaves it quickly and spends the rest of the window in a soft
/// tail rather than lingering near the peak the way a linear ramp does. The
/// renderer scales the configured lightness step by this value, so the fade
/// is perceptually linear as well.
pub(crate) fn bell_flash_ramp(elapsed: std::time::Duration) -> f32 {
    let t = elapsed.as_secs_f32() / BELL_FLASH_DURATION.as_secs_f32();
    if t >= 1.0 {
        return 0.0;
    }
    let remaining = 1.0 - t.max(0.0);
    remaining * remaining
}
const INPUT_REJECTION_NOTICE_INTERVAL: std::time::Duration = std::time::Duration::from_secs(3);
const MAX_PENDING_LUA_COMMANDS: usize = 1024;
const MAX_PENDING_LUA_SEND_BYTES: usize = 8 << 20;
const MAX_LUA_SEND_TEXT_BYTES: usize = 1 << 20;
const AUTOMATION_WORK_ITEMS_PER_TURN: usize = 16;
const AUTOMATION_WORK_BYTES_PER_TURN: usize = 1 << 20;
const AUTOMATION_RETRY_MIN: std::time::Duration = std::time::Duration::from_millis(10);
const AUTOMATION_RETRY_MAX: std::time::Duration = std::time::Duration::from_millis(250);
const AUTOMATION_YIELD: std::time::Duration = std::time::Duration::from_millis(1);
const MAX_REMOTE_COMMANDS_PER_BATCH: usize = 1024;

#[derive(Debug)]
enum PendingLuaCommand {
    SendText {
        origin_window: u64,
        target_pane: Option<u64>,
        bytes: Arc<[u8]>,
    },
    ExecAction {
        origin_window: u64,
        action: Action,
    },
    Notify {
        origin_window: u64,
        title: String,
        body: String,
    },
    /// Kettle's own notice that it retired runaway Lua callbacks.
    CallbackStopped {
        origin_window: u64,
        event: String,
        dropped: u64,
    },
    SetTheme {
        origin_window: u64,
        name: String,
    },
}

impl PendingLuaCommand {
    fn origin_window(&self) -> u64 {
        match self {
            Self::SendText { origin_window, .. }
            | Self::ExecAction { origin_window, .. }
            | Self::Notify { origin_window, .. }
            | Self::CallbackStopped { origin_window, .. }
            | Self::SetTheme { origin_window, .. } => *origin_window,
        }
    }

    fn send_len(&self) -> usize {
        match self {
            Self::SendText { bytes, .. } => bytes.len(),
            _ => 0,
        }
    }
}

#[derive(Debug, Default)]
struct PendingLuaCommands {
    commands: VecDeque<PendingLuaCommand>,
    send_bytes: usize,
}

#[derive(Debug)]
enum PendingRemoteCommand {
    SendText {
        origin_window: u64,
        target_pane: Option<u64>,
        bytes: Arc<[u8]>,
    },
    ToggleWindow {
        origin_window: u64,
    },
    NewTab {
        origin_window: u64,
    },
}

impl PendingRemoteCommand {
    fn origin_window(&self) -> u64 {
        match self {
            Self::SendText { origin_window, .. }
            | Self::ToggleWindow { origin_window }
            | Self::NewTab { origin_window } => *origin_window,
        }
    }
}

#[derive(Debug)]
enum ParsedRemoteCommandBatch {
    Accepted {
        commands: VecDeque<PendingRemoteCommand>,
        unknown_lines: usize,
    },
    RejectedTooMany {
        operation_count: usize,
        unknown_lines: usize,
    },
}

/// Parse one already byte-bounded spool claim without allowing short control
/// lines to amplify into an unbounded operation queue. The parser scans the
/// full batch to produce one coalesced unknown-line count, but retains at most
/// `MAX_REMOTE_COMMANDS_PER_BATCH` operations. Exceeding that count rejects the
/// whole batch before any retained prefix can be dispatched.
fn parse_remote_command_batch(text: &str, origin_window: u64) -> ParsedRemoteCommandBatch {
    let mut commands = VecDeque::new();
    let mut operation_count = 0usize;
    let mut unknown_lines = 0usize;
    for line in text.lines() {
        let line = line.trim_end_matches('\r');
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(payload) = line.strip_prefix("send-text-json ") {
            match serde_json::from_str::<String>(payload) {
                Ok(payload) => {
                    operation_count = operation_count.saturating_add(1);
                    if operation_count <= MAX_REMOTE_COMMANDS_PER_BATCH {
                        commands.push_back(PendingRemoteCommand::SendText {
                            origin_window,
                            target_pane: None,
                            bytes: Arc::from(payload.into_bytes()),
                        });
                    }
                }
                Err(_) => {
                    unknown_lines = unknown_lines.saturating_add(1);
                }
            }
        } else if let Some(payload) = line.strip_prefix("send-text ") {
            operation_count = operation_count.saturating_add(1);
            if operation_count <= MAX_REMOTE_COMMANDS_PER_BATCH {
                commands.push_back(PendingRemoteCommand::SendText {
                    origin_window,
                    target_pane: None,
                    bytes: Arc::from(payload.replace("\\n", "\n").into_bytes()),
                });
            }
        } else if line == "toggle-window" {
            operation_count = operation_count.saturating_add(1);
            if operation_count <= MAX_REMOTE_COMMANDS_PER_BATCH {
                commands.push_back(PendingRemoteCommand::ToggleWindow { origin_window });
            }
        } else if line == "new-tab" {
            operation_count = operation_count.saturating_add(1);
            if operation_count <= MAX_REMOTE_COMMANDS_PER_BATCH {
                commands.push_back(PendingRemoteCommand::NewTab { origin_window });
            }
        } else {
            unknown_lines = unknown_lines.saturating_add(1);
        }
    }
    if operation_count > MAX_REMOTE_COMMANDS_PER_BATCH {
        ParsedRemoteCommandBatch::RejectedTooMany {
            operation_count,
            unknown_lines,
        }
    } else {
        ParsedRemoteCommandBatch::Accepted {
            commands,
            unknown_lines,
        }
    }
}

#[derive(Debug, Eq, PartialEq)]
enum RemoteBatchClaim {
    Empty,
    Busy,
    Claimed(String),
    RejectedMalformed,
    RejectedOversize,
}

fn claim_remote_command_file(path: &std::path::Path) -> std::io::Result<RemoteBatchClaim> {
    use std::io::{Read as _, Seek as _};

    let lock_path = kettle_state::remote_command_lock_path(path);
    let Some(_lock) = kettle_state::ExclusiveFileLock::try_acquire(&lock_path)? else {
        return Ok(RemoteBatchClaim::Busy);
    };
    let mut file = kettle_state::open_existing_private_file(path)?;
    let size = file.metadata()?.len();
    if size > kettle_state::MAX_REMOTE_COMMAND_BYTES {
        file.set_len(0)?;
        return Ok(RemoteBatchClaim::RejectedOversize);
    }
    let mut bytes = Vec::with_capacity(usize::try_from(size).unwrap_or(0));
    file.seek(std::io::SeekFrom::Start(0))?;
    file.by_ref()
        .take(kettle_state::MAX_REMOTE_COMMAND_BYTES + 1)
        .read_to_end(&mut bytes)?;
    if bytes.len() as u64 > kettle_state::MAX_REMOTE_COMMAND_BYTES {
        file.set_len(0)?;
        return Ok(RemoteBatchClaim::RejectedOversize);
    }
    if bytes.is_empty() {
        return Ok(RemoteBatchClaim::Empty);
    }
    let text = match String::from_utf8(bytes) {
        Ok(text) => text,
        Err(_) => {
            file.set_len(0)?;
            return Ok(RemoteBatchClaim::RejectedMalformed);
        }
    };
    file.set_len(0)?;
    Ok(RemoteBatchClaim::Claimed(text))
}

fn should_poll_remote_window(
    has_claimed_fifo: bool,
    claim_pending: bool,
    retry_pending: bool,
    window_seq: u64,
    focused_seq: u64,
) -> bool {
    has_claimed_fifo || ((claim_pending || retry_pending) && window_seq == focused_seq)
}

impl PendingLuaCommands {
    fn push(&mut self, command: PendingLuaCommand) -> PaneInputResult {
        let send_len = command.send_len();
        if send_len > MAX_LUA_SEND_TEXT_BYTES {
            return PaneInputResult::Oversize;
        }
        if self.commands.len() >= MAX_PENDING_LUA_COMMANDS
            || self
                .send_bytes
                .checked_add(send_len)
                .is_none_or(|next| next > MAX_PENDING_LUA_SEND_BYTES)
        {
            return PaneInputResult::Backpressured;
        }
        self.send_bytes += send_len;
        self.commands.push_back(command);
        PaneInputResult::Queued
    }

    fn front(&self) -> Option<&PendingLuaCommand> {
        self.commands.front()
    }

    fn front_mut(&mut self) -> Option<&mut PendingLuaCommand> {
        self.commands.front_mut()
    }

    fn pop_front(&mut self) -> Option<PendingLuaCommand> {
        let command = self.commands.pop_front()?;
        self.send_bytes = self.send_bytes.saturating_sub(command.send_len());
        Some(command)
    }

    fn is_empty(&self) -> bool {
        self.commands.is_empty()
    }

    #[cfg(test)]
    fn len(&self) -> usize {
        self.commands.len()
    }
}

#[derive(Debug)]
struct AutomationRetry {
    next_at: Option<std::time::Instant>,
    backoff: std::time::Duration,
}

impl Default for AutomationRetry {
    fn default() -> Self {
        Self {
            next_at: None,
            backoff: AUTOMATION_RETRY_MIN,
        }
    }
}

impl AutomationRetry {
    fn is_ready(&self, now: std::time::Instant) -> bool {
        self.next_at.is_none_or(|deadline| now >= deadline)
    }

    fn backpressured(&mut self, now: std::time::Instant) {
        self.next_at = Some(now + self.backoff);
        self.backoff = self.backoff.saturating_mul(2).min(AUTOMATION_RETRY_MAX);
    }

    fn progressed(&mut self) {
        self.next_at = None;
        self.backoff = AUTOMATION_RETRY_MIN;
    }

    fn yield_soon(&mut self, now: std::time::Instant) {
        let deadline = now + AUTOMATION_YIELD;
        if self.next_at.is_none_or(|current| deadline < current) {
            self.next_at = Some(deadline);
        }
    }

    fn expedite_if_idle(&mut self, now: std::time::Instant) {
        if self.next_at.is_none() {
            self.next_at = Some(now);
        }
    }

    fn remaining(&self, now: std::time::Instant) -> Option<std::time::Duration> {
        self.next_at.map(|deadline| {
            deadline
                .saturating_duration_since(now)
                .max(std::time::Duration::from_nanos(1))
        })
    }
}

fn input_rejection_message(result: PaneInputResult) -> Option<&'static str> {
    match result {
        PaneInputResult::Queued | PaneInputResult::ReadOnly => None,
        PaneInputResult::Backpressured => Some(
            "Input could not be delivered because a child is not accepting it fast enough. If broadcast mode is active, some panes may already have received it; verify before retrying.",
        ),
        PaneInputResult::Oversize => Some(
            "Input exceeded Kettle's per-message safety limit and was not delivered. If broadcast mode is active, verify the other panes before retrying.",
        ),
        PaneInputResult::Failed => {
            Some("The pane's input transport failed. Kettle will close the failed pane.")
        }
    }
}

/// The notification for a rejected input, in the UI's language. Logs keep
/// [`input_rejection_message`]'s English.
fn input_rejection_text(
    result: PaneInputResult,
    tr: &kettle_i18n::Translator,
) -> Option<&'static str> {
    use kettle_i18n::Text;
    input_rejection_message(result)?;
    Some(tr.text(match result {
        PaneInputResult::Backpressured => Text::NotifyBodyInputBackpressured,
        PaneInputResult::Oversize => Text::NotifyBodyInputOversize,
        _ => Text::NotifyBodyInputFailed,
    }))
}

fn should_notify_input_rejection(
    last: Option<(PaneInputResult, std::time::Instant)>,
    result: PaneInputResult,
    now: std::time::Instant,
) -> bool {
    input_rejection_message(result).is_some()
        && last.is_none_or(|(prior, at)| {
            prior != result || now.saturating_duration_since(at) >= INPUT_REJECTION_NOTICE_INTERVAL
        })
}

fn ctl_input_error(result: PaneInputResult) -> Option<(&'static str, &'static str)> {
    use kettle_ctl::protocol::error_codes as ec;
    match result {
        PaneInputResult::Queued => None,
        PaneInputResult::ReadOnly => Some((
            ec::READ_ONLY,
            "pane is read-only (user toggled 'Read only')",
        )),
        PaneInputResult::Backpressured => Some((
            ec::BUSY,
            "pane input is backpressured; no bytes were sent (retry later)",
        )),
        PaneInputResult::Oversize => Some((
            ec::BAD_PARAMS,
            "input exceeds the per-message safety limit; no bytes were sent",
        )),
        PaneInputResult::Failed => Some((
            ec::INTERNAL,
            "pane input transport failed; the pane is being closed",
        )),
    }
}

#[cfg(test)]
use crate::window_accent::pick_accent_slot;

pub struct App {
    #[cfg(target_os = "linux")]
    wayland: Option<crate::wayland::Bridge>,
    #[cfg(target_os = "linux")]
    wayland_tab_drag: Option<WaylandTabDrag>,
    #[cfg(target_os = "linux")]
    wayland_file_drops: std::collections::BTreeMap<u64, (u64, WaylandDropTarget)>,
    cfg: Config,
    /// The file this launch's session was read from, if any.
    ///
    /// Held so a restore that fails can move that exact file aside. It is not
    /// recoverable later: `session_write_target` decides where a *save* goes
    /// from state this never sees, and a one-shot tab handoff is deleted as it
    /// is read.
    restore_source: Option<std::path::PathBuf>,
    /// All per-window state, keyed by the
    /// window's stable sequence number (`WindowState::seq`, 1-based, never
    /// reused). BTreeMap so iteration order is deterministic (window 1, 2,
    /// ...). The `ApplicationHandler` entry points remove the addressed entry,
    /// run the inner handler with disjoint `&mut self` (globals) +
    /// `&mut WindowState` borrows, then reinsert — see window_state.rs for the
    /// dispatch contract.
    windows: std::collections::BTreeMap<u64, WindowState>,
    accent_registry: crate::window_accent::AccentRegistry,
    /// Seq of the window that has (or most recently had) OS focus. Routes
    /// window-less events (UserEvent wakeups, remote/ctl/Lua commands).
    focused_seq: u64,
    /// Next `WindowState::seq` to assign (consumed by `open_window`).
    next_window_seq: u64,
    /// The shared GPU context, cached when window 1's renderer comes up
    /// in `resumed`; `open_window` reuses it for the synchronous (no
    /// adapter/device request) renderer init of windows 2..N.
    gpu: Option<kettle_render::GpuContext>,
    /// The system fonts, loading on their own thread since `run_with`
    /// began. Window 1 takes them before its first spawn; later windows load their own.
    font_preload: Option<crate::font_preload::FontPreload>,
    /// Decided before the first spawn consumes command/cwd.
    launch_override: bool,
    pre_launch_eligible: bool,
    /// Detected GPUs as `(token, label)` pairs for the Settings →
    /// Graphics device picker. Enumerated ONCE when the settings overlay first
    /// opens (a wgpu instance + adapter walk is ~tens of ms — too heavy per
    /// frame) and cached for the session; `categories()` reads it. Empty until
    /// the overlay is first opened (the picker then shows just "Automatic").
    gpu_choices: Vec<(String, String)>,
    /// The UI's language, fixed for the process. Kettle-owned text goes
    /// through it; terminal content, user names and config values do not.
    ui_text: kettle_i18n::Translator,
    /// Pure settle/backoff state after a GPU device loss.
    gpu_recovery: RecoveryState,
    /// Fault-only local record for the current device-loss incident.
    gpu_incident: Option<IncidentLog>,
    /// Prevent repeated filesystem attempts if diagnostics cannot be created.
    gpu_incident_started_for_loss: bool,
    /// True once recovery had to fall back to software rendering.
    gpu_software_fallback: bool,
    /// Last palette variant installed as the live Windows/X11 window icon.
    /// macOS and Wayland ignore this winit hook and use their bundle/desktop
    /// assets, but keeping one lazy theme-sync path makes native platforms that
    /// do expose it change immediately with the rest of the chrome.
    window_icon_dark_synced: Option<bool>,
    /// Window ids awaiting removal after their checked-out dispatch finishes.
    /// This must be keyed by window: a process-global boolean can be set while
    /// ctl/Lua dispatches into one mapped window and then consumed by another
    /// window's epilogue, closing a sibling the user never asked to close.
    pending_window_closes: std::collections::BTreeSet<u64>,
    /// Quit drops every window and exits, regardless of how many are open.
    quit_requested: bool,
    /// Session recorder (asciicast trace). `Some` when recording is active for
    /// this window — requested via `--record PATH` / `KETTLE_RECORD` or the
    /// persistent `record = on` config key. `None` (the default) records
    /// nothing at zero cost.
    recorder: Option<crate::dev_record::Recorder>,
    /// A requested recorder that failed before construction still needs a
    /// persistent visible error state; there is no `Recorder` to carry it.
    recording_start_failed: bool,
    /// Desktop notifications are edge-triggered so a stopped recorder does
    /// not emit one notification per redraw or stale-flush timer tick.
    recording_error_reported: bool,
    /// Throttles visible PTY input rejection feedback. A child which has
    /// stopped reading can reject a burst of key-repeat events; the user needs
    /// one explicit notice, not a desktop-toast storm.
    last_input_rejection_notice: Option<(PaneInputResult, std::time::Instant)>,
    system_motion: std::sync::OnceLock<crate::motion::SystemMotion>,
    #[cfg(target_os = "linux")]
    agent_launches: kettle_ctl::agent_launch::LaunchScopes,
    proxy: EventLoopProxy<UserEvent>,
    /// Private, bounded bare-launch activation inbox. The IPC thread waits for
    /// this event-loop thread to confirm window creation before telling the
    /// secondary launcher it may exit.
    activation: Option<crate::activation_server::ActivationInbox>,
    /// Privacy-safe event-loop phase tracker. A separate watchdog records a
    /// bounded incident when a callback stops making progress; it never
    /// captures terminal contents, command lines, or paths.
    runtime_tracker: crate::runtime_diagnostics::RuntimeTracker,
    /// Wakeup-dedup latch shared by every pane's `Waker`.
    /// Under output flood the PTY readers fire once per 64KiB read — dozens
    /// of queued `UserEvent::Wakeup`s per paint window, each one fanning out
    /// over every window just to discover the generations already matched.
    /// The waker enqueues only when it flips this false→true; the Wakeup arm
    /// re-opens the latch BEFORE reading generations, so output that lands
    /// after the clear enqueues a fresh event (no lost wakeups).
    wake_pending: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// Exactly one config watcher notification may be queued or debouncing.
    /// The main thread clears this immediately before it rereads the file.
    config_reload_pending: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// Short, non-blocking settle window for atomic-save event bursts.
    config_reload_deadline: Option<std::time::Instant>,
    /// Remote-file counterpart to `config_reload_pending`. Commands accumulate
    /// in the bounded file, so one drain notification is sufficient.
    remote_command_pending: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// Claimed remote-file operations awaiting ordered dispatch. The receiver
    /// never claims another bounded batch while this FIFO has a retained suffix.
    pending_remote_commands: VecDeque<PendingRemoteCommand>,
    /// A watcher event (or startup lock timeout) promised that the spool still
    /// needs a claim. This remains true while an older in-memory suffix is
    /// backpressured, so consuming the one watcher event cannot strand a later
    /// batch in the file.
    remote_spool_claim_pending: bool,
    /// Deadline/backoff for a busy spool lock or backpressured target pane.
    remote_command_retry: AutomationRetry,
    /// The in-process control server, present when the control policy allows
    /// anything (`agent-server`, `agent-display` or their launch flags).
    /// `None` keeps the zero-cost default path. Started in `resumed`, or when
    /// display is turned on later; dropped on exit (which unregisters the
    /// discovery entry).
    ctl: Option<crate::ctl_server::CtlServer>,
    /// The control policy in force, resolved at launch from config and the
    /// `--agent-server`/`--agent-display` flags. `agent-server` applies only
    /// at launch; display can only be turned on while Kettle runs (see
    /// `reconcile_agent_display`), so this never narrows.
    ctl_policy: kettle_ctl::CtlPolicy,
    /// Whether the control server may start yet, and whether it has tried.
    ctl_start: CtlStart,
    /// Pending `run_command` correlations keyed by
    /// pane id. A request writes `cmd\n`, records the start line + deadline
    /// here, and the next OSC-133 `CommandFinished` for that pane resolves it.
    pending_runs: std::collections::HashMap<u64, PendingRun>,
    /// `show` pushes: their render queue and the thread that renders them.
    media: crate::media::MediaService,
    /// The one-time tip that a click opens an inline card.
    cards_tip: crate::media::CardsTip,
    clipboard: Option<arboard::Clipboard>,
    /// Temporary PNGs materialized from clipboard bitmaps. Owner-only, bounded,
    /// and removed on exit — see [`crate::paste_image`].
    pasted_images: crate::paste_image::PastedImages,
    /// Encodes clipboard images off the window thread; started on first use.
    png_encoder: Option<crate::paste_image::PngEncoder>,
    png_jobs: u64,
    /// Pastes waiting, in order, for the images ahead of them to encode.
    queued_pastes: std::collections::VecDeque<QueuedPaste>,
    /// The PNG copies handed to the image viewer, made off the window thread.
    /// Owner-only, bounded, oldest dropped first, and removed on exit.
    viewer_copies: std::sync::Arc<std::sync::Mutex<crate::paste_image::PastedImages>>,
    /// The private copies of videos handed to the video player, made off
    /// the window thread. Owner-only, bounded, oldest dropped first, and
    /// removed on exit.
    video_copies: std::sync::Arc<crate::media::VideoCopies>,
    /// Previews the user asked for that are on their pane's shelf, waiting
    /// for that pane's window to open them: window, pane and item.
    previews_ready: Vec<(u64, u64, u64)>,
    /// Whether a control client's request is being handled: what it
    /// drives is never the user's own gesture.
    ctl_driving: bool,
    /// Whether a Lua script's action is being run: such an action is no
    /// gesture of the user's, and starts no preview that reads a file.
    lua_driving: bool,
    /// The last ticket a lane took for sharper pixels.
    crop_tickets: u64,
    /// The last gallery page request a lane made, counting from 0, so two
    /// requests for one page are told apart.
    page_tickets: u64,
    /// The last ticket a lane took for a video's silent preview.
    preview_tickets: u64,
    /// The thread that copies a lane's image or source, from the first copy.
    preview_copy: Option<crate::media::CopyService>,
    /// Bounded native-poster jobs. Paths cross only the private child-worker
    /// protocol; decoded pixels return through the event loop.
    video_previewer: crate::video_preview::VideoPreviewer,
    next_video_preview_generation: u64,
    /// Triggers: compiled regex set built from `cfg.triggers` at App
    /// construction (and after live reload). Invalid patterns are logged via
    /// `log::warn!` and dropped.
    compiled_triggers: Vec<(regex::Regex, kettle_config::TriggerAction)>,
    /// Last trigger fire, or `None` before the first fire / after a
    /// config reload. Dedupes a fast-arriving match flood without fabricating
    /// an `Instant` before the OS monotonic clock's origin.
    last_trigger_fire: Option<std::time::Instant>,
    /// Coalescing worker for periodic remote/cwd detection. Process enumeration
    /// and procfs reads never block the window event loop.
    remote_scan_worker: Option<kettle_remote::RemoteScanWorker>,
    /// Last snapshot values actually applied to panes. This is the redraw and
    /// stale-result baseline; worker results may overwrite each other before
    /// the event loop consumes them.
    remote_applied: std::collections::HashMap<(u64, u32), kettle_remote::RemoteProbe>,
    remote_live_panes_scratch: std::collections::HashSet<u64>,
    /// Reused target collection for the cross-window remote poll.
    remote_targets_scratch: Vec<kettle_remote::RemoteProbeTarget>,
    /// Throttle the remote-detect poll to ~5 Hz. `None` makes the
    /// first poll immediately eligible, including during the first minute
    /// after Windows boots.
    last_remote_poll: Option<std::time::Instant>,
    /// When a poll the throttle skipped must run. `about_to_wait` wakes for it.
    remote_poll_due: Option<std::time::Instant>,
    /// The most-recent auto-theme "schedule decision" (true=dark)
    /// we've applied, so a boundary-crossing fires the swap exactly once.
    last_schedule_decision: Option<bool>,
    /// Resolved non-default config file (explicit path or named profile).
    config_path: Option<std::path::PathBuf>,
    /// Provenance paired with `config_path`; profile switching resets this to
    /// directory verification even when the process started with `--config`.
    config_trust: ConfigTrust,
    /// The malformed-value diagnostics surfaced on the previous live reload,
    /// so the reload notification is edge-triggered — kettle's own
    /// settings-persistence writes reload the config and must not re-fire an
    /// identical warning every time. See [`should_notify_malformed`].
    config_malformed_last: Vec<String>,
    /// First-tab CLI overrides (`-e cmd`, `-d dir`); consumed once.
    startup: crate::Options,
    /// May this session write back to the `--layout NAME` file?
    ///
    /// `false` when a launch override (`-e` / `-d`) meant the named layout was
    /// never loaded. Otherwise `kettle --layout dev -d ~/work` would open a
    /// plain window and overwrite `dev.json` with that single pane on the first
    /// save. The write is gated the same way as the load.
    ///
    /// Recorded here rather than recomputed at save time because the startup
    /// command/cwd fields are consumed once and are gone by then.
    named_layout_writable: bool,
    _watcher: Option<notify::RecommendedWatcher>,
    /// Drop guard for the remote-control watcher.
    _remote_watcher: Option<notify::RecommendedWatcher>,
    /// Ordered, bounded Lua side effects. Each send remains a distinct shared
    /// message so retry cannot merge calls into an oversize allocation, while
    /// actions/notifications/theme changes retain script order.
    pending_lua_commands: PendingLuaCommands,
    /// Retry state for a child that temporarily stops accepting Lua-generated
    /// input. Capacity release has no event-loop wake of its own.
    lua_command_retry: AutomationRetry,
    /// The live LuaEngine persisted across the App's lifetime so
    /// `kettle.on(event, callback)` registrations stay in scope. All event
    /// hooks share `drain_lua_hook_commands` for the LuaCommand dispatch.
    lua_engine: Option<crate::LuaEngine>,
    /// Set after LuaEvent::Startup fired once (Wayland can re-emit
    /// `resumed`).
    lua_startup_fired: bool,
    /// `Some((tag, url))` while the "a newer kettle release is
    /// available" banner is showing. Esc dismisses; Enter opens the URL.
    update_available: Option<(String, String)>,
    /// The full version string the About panel shows —
    /// the bin crate passes its `KETTLE_VERSION` (version + git hash, exactly
    /// what `--version` prints); falls back to the bare crate version.
    version_line: String,
    /// `Some` while a torn-off window is riding an OS-native move loop
    /// (`drag_window()`) or the manual-follow fallback. Drives the re-dock:
    /// hit-testing sibling tab bands on `Moved`, the insertion preview, and
    /// the drop-merge. App-level (not per-window) because exactly one tear-off
    /// drag can be in flight per pointer.
    torn_drag: Option<TornDrag>,
    /// When the session was last considered for writing. Drives the sweep
    /// described on [`SESSION_SWEEP`]; `None` until the first one runs.
    last_session_sweep: Option<std::time::Instant>,
}

/// How much of the saved session can be stale before the next event-loop turn
/// writes it out.
///
/// Most of what `session.json` holds is announced by a gesture that already
/// saves — splitting, closing, opening a tab. Some of it is not: a shell `cd`
/// moves a pane's recorded directory, a divider drag moves a split ratio, a
/// renamed tab moves its title. Without the sweep, each would reach disk only
/// if some *later* gesture happened to save, so restoring a workspace could
/// bring back directories the user left an hour ago.
///
/// Saving on every turn instead would serialize the whole tree at PTY-output
/// rates, and arming a timer for it would keep the process awake and show up as
/// idle CPU — kettle measures that. So the sweep rides on turns the event loop
/// was running anyway: it never wakes the process on its own account, and an
/// idle kettle simply saves the moment anything next happens. The write itself
/// is skipped when the serialized text matches what is already on disk, so a
/// sweep over an unchanged workspace costs one serialization and no I/O.
const SESSION_SWEEP: std::time::Duration = std::time::Duration::from_secs(2);

fn about_update_status_label(available_tag: Option<&str>, tr: &kettle_i18n::Translator) -> String {
    available_tag.map_or_else(
        || tr.text(kettle_i18n::Text::AboutUpdateUnknown).to_string(),
        |tag| tr.about_update_available(tag),
    )
}

/// The right-click row that reopens a detected remote session. Users, hosts,
/// runtimes and containers are shown as detected.
fn remote_reconnect_label(
    ctx: &kettle_remote::RemoteContext,
    tr: &kettle_i18n::Translator,
) -> String {
    match ctx {
        kettle_remote::RemoteContext::Ssh { host, user, .. } => match user {
            Some(user) => tr.menu_reconnect_ssh_user(user, host),
            None => tr.menu_reconnect_ssh(host),
        },
        kettle_remote::RemoteContext::Container {
            runtime, container, ..
        } => tr.menu_reattach(runtime.name(), container),
    }
}

/// Which broadcast scope the group chord turns on, from `broadcast-default`.
///
/// Terminator stores this key as the *initial* groupsend mode
/// (`terminator.py`: `groupsend = groupsend_type[config['broadcast_default']]`).
/// kettle reads it as the scope the chord selects instead, because a window
/// that started in `all` would mirror every keystroke into every pane before
/// the user had touched anything.
///
/// For Terminator's own default the two readings are the same thing — its
/// `group` mode with no groups yet assigned sends only to the focused terminal
/// — so the divergence is visible only under `broadcast-default = all`, where
/// kettle waits to be asked. `group` maps to kettle's per-tab broadcast, which
/// is what a kettle "group" has always meant to the chord.
fn broadcast_scope_for_default(
    default: kettle_config::BroadcastDefault,
) -> crate::mux::BroadcastScope {
    match default {
        kettle_config::BroadcastDefault::All => crate::mux::BroadcastScope::All,
        kettle_config::BroadcastDefault::Group => crate::mux::BroadcastScope::Tab,
        kettle_config::BroadcastDefault::Off => crate::mux::BroadcastScope::Off,
    }
}

/// Whether a session sweep is owed as of `now`. The first turn always sweeps,
/// so a workspace that changes and then goes quiet is written once rather than
/// waiting for a second turn that may never come.
///
/// A window with no tabs is never swept, whatever the clock says. A sweep is a
/// background refresh of what is on screen, and an empty window is one that has
/// not opened yet or is on its way out — writing that snapshot would put
/// `{"tabs":[],"windows":[]}` over the saved session the user is about to have
/// restored. The paths that genuinely mean to erase — `close_window`, and the
/// reap that precedes this — still save explicitly, and this does not touch
/// them. Same rule as the named-layout guard in `session_write_target`.
///
/// Returning `false` here deliberately leaves the caller's timestamp alone, so
/// a window that is skipped does not consume the interval for the others.
fn session_sweep_due(
    last: Option<std::time::Instant>,
    now: std::time::Instant,
    window_has_tabs: bool,
) -> bool {
    window_has_tabs && last.is_none_or(|then| now.saturating_duration_since(then) >= SESSION_SWEEP)
}

/// Rescue-tick cadence (one frame at 60Hz) while a torn drag is in flight or
/// a silent native handoff is being watched.
const TORN_TICK_MS: u64 = 16;

/// Diagnostics/test override: `KETTLE_TEAR_MANUAL_FOLLOW=1` skips the native
/// `drag_window()` handoff so a tear always takes the manual-follow/rescue-tick
/// path. Otherwise demotion is a nondeterministic race (the WM silently
/// dropping `_NET_WM_MOVERESIZE` for a just-mapped window) that cannot be
/// triggered on demand, so the live tear-off smoke pins BOTH paths by
/// launching one instance per mode. Read per tear, not cached: trivially
/// cheap, and it keeps the override in one place.
fn tear_native_handoff_disabled() -> bool {
    std::env::var_os("KETTLE_TEAR_MANUAL_FOLLOW").is_some_and(|v| v == "1")
}

/// Real pointer travel (px) required, alongside the 400ms grace, before a
/// silent native handoff is demoted to manual follow. A WM that took the grab
/// moves the frame with the pointer, so travel-without-`Moved` is proof it
/// never did; the floor keeps a stationary hover from demoting a
/// healthy-but-quiet grab.
const DEMOTION_TRAVEL_PX: f64 = 24.0;

#[cfg(any(target_os = "linux", test))]
#[derive(PartialEq, Eq)]
struct WaylandDropTarget {
    pane: Option<u64>,
    broadcast: crate::mux::BroadcastScope,
    input_generation: u64,
    preview: Option<crate::media::PreviewFocus>,
    pane_input: Option<u64>,
}

#[cfg(any(target_os = "linux", test))]
impl WaylandDropTarget {
    fn capture(ws: &WindowState) -> Self {
        Self {
            pane: ws.mux.active_focus(),
            broadcast: ws.mux.broadcast.clone(),
            input_generation: ws.ime_focus_generation,
            preview: ws.preview_focus,
            pane_input: ws
                .mux
                .active_focus()
                .and_then(|id| ws.mux.panes.get(&id))
                .map(|pane| pane.input_generation()),
        }
    }
}

#[cfg(target_os = "linux")]
struct WaylandTabDrag {
    source: u64,
    source_index: usize,
    panes: Vec<u64>,
    carrier: u64,
    preview: Option<u64>,
}

struct TornDrag {
    /// Seq of the torn-off window being dragged.
    seq: u64,
    /// Seq of the mouse-capture holder: the tear's SOURCE window (it keeps
    /// streaming CursorMoved while the button is held), or `seq` itself
    /// for a lone-tab whole-window drag. Manual-follow only listens to the
    /// carrier — without this gate, stale tracking would hijack EVERY
    /// window's cursor stream.
    carrier: u64,
    /// Handoff instant. The X11/macOS pointer-event drop heuristics are
    /// suppressed for a short window after it (a stray client motion can
    /// race the WM actually taking the move grab), and the native→manual
    /// demotion fires off it when the WM never takes the drag at all.
    started: std::time::Instant,
    /// Cursor offset from the torn window's FRAME top-left in drag coordinates
    /// (macOS desktop points, physical pixels on Windows/X11),
    /// chosen at tear time so the pointer holds the tab. `Moved(pos) + grab`
    /// approximates the live screen cursor during the native move loop
    /// (winit's `Moved` reports the frame position on Windows — verified in
    /// the vendored 0.30.13 WM_WINDOWPOSCHANGED handler).
    grab: (f64, f64),
    /// Latched dock target: (sibling window seq, insertion index). Updated
    /// by every hit-test; the drop commits whatever is latched.
    dock: Option<(u64, usize)>,
    /// `drag_window()` succeeded — the OS carries the window. The drop then
    /// arrives as winit's synthesized post-WM_EXITSIZEMOVE left-release
    /// (Windows) or as the first client pointer event after the WM's pointer
    /// grab ends (X11/macOS — the client receives NO pointer events while
    /// the WM moves the window). `false` = manual-follow: the SOURCE window
    /// still holds mouse capture, repositions the torn window from its own
    /// CursorMoved stream, and its left-release is the drop.
    native: bool,
    /// A native caption gesture is OS-owned and must never be demoted to
    /// the manual-follow rescue used for failed tab-drag handoffs.
    caption: bool,
    /// At least one `Moved` arrived since the handoff. Gates the
    /// pointer-event drop heuristic against the PostMessage race on
    /// Windows (a stray client mouse-move can slip in between
    /// `drag_window()`'s posted WM_NCLBUTTONDOWN and the modal loop
    /// actually starting) and against an X11 tear the user never moved.
    saw_move: bool,
    /// Last signal (tear or `Moved`) — the stale-tracking failsafe: a
    /// torn drag with no movement for 120s is abandoned by `about_to_wait`
    /// (covers an X11 tear whose release we never observe). The rescue
    /// tick also arbitrates on it (a fresh CursorMoved-driven follow
    /// suppresses the tick for 30ms).
    last_signal: std::time::Instant,
    /// The torn window's HWND (Windows; `None` elsewhere) — the dock-hover
    /// translucency and the z-order walk both key off it, and tracking
    /// teardown needs it to restore full opacity from any code path.
    /// Only Windows code reads it; populated unconditionally so the
    /// struct shape stays identical across platforms.
    #[cfg_attr(not(target_os = "windows"), allow(dead_code))]
    hwnd: Option<isize>,
    /// X11: the real cursor position at the last tracking signal, refreshed
    /// by every `Moved` that pairs with a live-cursor query, or by the rescue
    /// tick's first look. Demotion evidence: if the pointer has since
    /// travelled while no further `Moved` arrived, the WM is not actually
    /// moving the window (an accepted-but-ignored `_NET_WM_MOVERESIZE`, an
    /// unmapped-window race, or a grab dropped after one incidental placement
    /// `Moved`) and the tick takes over. Purely time-based demotion would
    /// fight a WM that DID take the grab over a pointer simply holding still.
    signal_cursor: Option<(f64, f64)>,
}

/// Queue a desktop notification without ever waiting on an OS notification
/// service from Kettle's UI thread. The single bounded worker preserves order;
/// a stalled backend fills the queue and drops later notifications instead of
/// freezing rendering, input, and control replies.
pub(crate) fn fire_notify(title: &str, body: &str) {
    crate::queue_desktop_notification(title, body);
}

/// A split that cannot spawn leaves the layout exactly as it was, so all the
/// user sees is a keystroke that did nothing. That is indistinguishable from a
/// split that appeared and never drew, and a `warn!` line is invisible at the
/// default log level, so the two reports arrive looking identical. Say it out
/// loud instead, the way a failed preference write already does.
pub(crate) fn report_split_failure(
    direction: &str,
    error: &dyn std::fmt::Display,
    tr: &kettle_i18n::Translator,
) {
    log::error!("could not split pane ({direction}): {error}");
    fire_notify(
        tr.text(kettle_i18n::Text::NotifyTitleSplitFailed),
        &error.to_string(),
    );
}

fn persist_keybind_rebind(
    path: Option<&std::path::Path>,
    stale: &[String],
    label: &str,
    action_name: &str,
) -> bool {
    let Some(path) = path else {
        log::warn!(
            "apply_keybind_rebind: no config path resolved \
             (set $XDG_CONFIG_HOME or pass --config)"
        );
        return false;
    };

    let mut saved = true;
    for old in stale {
        if let Err(e) = kettle_config::append_keybind(path, old, "unbind") {
            log::warn!("append_keybind({old}=unbind) failed: {e}");
            saved = false;
        }
    }
    if let Err(e) = kettle_config::append_keybind(path, label, action_name) {
        log::warn!("append_keybind({label}={action_name}) failed: {e}");
        saved = false;
    }
    saved
}

fn completion_surface_available(mode: kettle_core::TermMode, display_offset: usize) -> bool {
    !mode.contains(kettle_core::TermMode::ALT_SCREEN) && display_offset == 0
}

fn completion_anchor_col(cursor_col: usize, input_prefix: &str) -> usize {
    cursor_col.saturating_sub(unicode_width::UnicodeWidthStr::width(input_prefix))
}

#[cfg(test)]
mod completion_surface_tests;

impl App {
    /// The map key of the WindowState whose OS window is `wid`, if any.
    /// Returns `WindowState::seq`, which is the map key by invariant.
    fn seq_of_window(&self, wid: WindowId) -> Option<u64> {
        self.windows
            .values()
            .find_map(|w| (w.window.as_ref().map(|x| x.id()) == Some(wid)).then_some(w.seq))
    }

    fn request_window_close(&mut self, seq: u64) {
        self.pending_window_closes.insert(seq);
    }

    fn window_close_pending(&self, seq: u64) -> bool {
        self.pending_window_closes.contains(&seq)
    }

    /// The dispatch wrappers' epilogue. Reinserts the checked-out window
    /// — or, when the inner handler flagged this window for close
    /// or a quit, drops it (panes' PTYs die with their Mux) and exits the
    /// event loop once no windows remain. This is the ONLY place a window
    /// close reaches `event_loop.exit()`, so "exit only when the map is
    /// empty" holds by construction (drift-guarded in
    /// `event_loop_exit_sites_are_allowlisted`).
    fn finish_window_dispatch(&mut self, event_loop: &ActiveEventLoop, seq: u64, ws: WindowState) {
        if self.quit_requested {
            drop(ws);
            self.windows.clear();
            event_loop.exit();
            return;
        }
        if take_window_close_request(&mut self.pending_window_closes, seq) {
            // A dying window that is the torn window or the manual-follow
            // capture holder takes its drag with it. Abandon eagerly (clears
            // the latched preview on the still-mapped target and restores
            // opacity) instead of leaving stale tracking for the heuristics to
            // trip over.
            if self
                .torn_drag
                .as_ref()
                .is_some_and(|t| t.seq == seq || t.carrier == seq)
            {
                self.abandon_torn_drag(None);
            }
            drop(ws);
            self.hoover_mapped_groups();
            if self.windows.is_empty() {
                event_loop.exit();
            } else if self.focused_seq == seq
                && let Some(&next) = self.windows.keys().next_back()
            {
                // Focus falls to the most recently opened remaining window;
                // the OS will confirm with a Focused(true) shortly.
                self.focused_seq = next;
            }
            return;
        }
        let mut ws = ws;
        self.sync_pane_focus_reports(&mut ws);
        self.windows.insert(seq, ws);
    }

    /// Keep focus-event reports (DEC mode 1004) in step with the pane that
    /// holds the keyboard: the focused pane of the active tab while the window
    /// has OS focus. A pane that enabled the mode hears `CSI O` when that
    /// stops being it, whether the window lost focus or focus moved to
    /// another pane or tab (a key, a click, a control request or a close),
    /// and `CSI I` when it becomes it again. tmux `focus-events`, Neovim's
    /// `FocusGained`/`FocusLost` and the agent CLIs' notification state all
    /// rely on that. Every dispatch passes through `finish_window_dispatch`,
    /// so one check there covers every route, and a pane hears each change
    /// once.
    fn sync_pane_focus_reports(&mut self, ws: &mut WindowState) {
        let focused = (ws.os_focus_known && ws.window_focused)
            .then(|| ws.mux.active_focus())
            .flatten();
        let (lost, gained) = focus_report_transition(ws.focus_reported_pane, focused);
        ws.focus_reported_pane = focused;
        for (pane_id, focus) in [(lost, false), (gained, true)] {
            let Some(pane_id) = pane_id else {
                continue;
            };
            if !self
                .pane_mode(ws, pane_id)
                .is_some_and(|mode| mode.contains(kettle_core::TermMode::FOCUS_IN_OUT))
            {
                continue;
            }
            if let Some(pane) = ws.mux.panes.get(&pane_id) {
                let result = pane.feed_focus_report(focus);
                if !result.is_queued() {
                    self.report_input_result(result);
                }
            }
        }
    }

    /// A tab leaving this window takes its panes with it. If one of them holds
    /// the reported focus, tell it focus left now, through the detached tab,
    /// so the window that adopts it starts from "not focused" and its first
    /// `CSI I` follows a `CSI O`. Called only after a detach succeeded, so a
    /// failed transfer reports nothing.
    fn release_focus_report_to(&mut self, ws: &mut WindowState, dt: &crate::mux::DetachedTab) {
        let Some(reported) = ws.focus_reported_pane else {
            return;
        };
        let Some((_, pane)) = dt.panes.iter().find(|(id, _)| *id == reported) else {
            return;
        };
        ws.focus_reported_pane = None;
        let reporting = pane
            .term
            .term
            .lock()
            .ok()
            .is_some_and(|t| t.mode().contains(kettle_core::TermMode::FOCUS_IN_OUT));
        if reporting {
            let result = pane.feed_focus_report(false);
            if !result.is_queued() {
                self.report_input_result(result);
            }
        }
    }

    fn drain_activation_requests(&mut self, event_loop: &ActiveEventLoop) {
        // Keep requests queued while window 1 is still creating the shared GPU
        // context. `resumed` calls this again immediately after initialization.
        if self.gpu.is_none() {
            return;
        }
        let pending = self
            .activation
            .as_ref()
            .map(crate::activation_server::ActivationInbox::drain)
            .unwrap_or_default();
        for request in pending {
            if !request.claim() {
                continue;
            }
            if !activation_recording_available(
                request.request.requires_recording(),
                self.recording_status(),
            ) {
                log::warn!(
                    "bare-launch activation rejected because the requested dev recorder is not active"
                );
                let _ = request.completion.send(false);
                continue;
            }
            let cwd = request.request.cwd().map(str::to_string);
            let opened = self
                .open_window(event_loop, WindowOpen::Fresh { cwd }, None, None)
                .is_ok();
            if opened {
                log::info!("bare-launch activation opened a new window");
                if let Some(recorder) = self.recorder.as_mut() {
                    recorder.record_marker("kettle:activation_window");
                }
            }
            let _ = request.completion.send(opened);
        }
    }

    pub fn run() -> Result<()> {
        Self::run_with(crate::Options::default())
    }

    pub fn run_with(mut startup: crate::Options) -> Result<()> {
        crate::startup_trace::mark(crate::startup_trace::Phase::RunWith);
        let _trace = crate::startup_trace::FlushOnDrop;
        // Enumerate the system fonts while the event loop starts (AppKit's
        // launch, on macOS) instead of after it.
        let mut font_preload = crate::font_preload::FontPreload::start();
        // Reclaim pasted-image directories from a run that died before its own
        // cleanup. Age-gated, so a sibling instance mid-session is untouched.
        crate::paste_image::sweep_stale();
        #[cfg(target_os = "macos")]
        disable_app_state_restoration();
        let event_loop = EventLoop::<UserEvent>::with_user_event().build()?;
        crate::startup_trace::mark(crate::startup_trace::Phase::EventLoopBuilt);
        event_loop.set_control_flow(ControlFlow::Wait);
        let proxy = event_loop.create_proxy();
        let activation = startup.activation.take().and_then(|primary| {
            match crate::activation_server::ActivationInbox::start(primary, proxy.clone()) {
                Ok(inbox) => Some(inbox),
                Err(error) => {
                    log::warn!("bare-launch activation server unavailable: {error}");
                    None
                }
            }
        });

        // Watch the chosen config file's directory for live reload, but reload
        // only on events whose `paths` contain the config file itself. Other
        // files there change often (session.json saves, palette edits, the
        // theme cache, editor swap files), and each atomic `save_session`
        // alone writes `session.json.tmp.*` then renames it, firing 3+ events.
        let mut watcher = None;
        let config_reload_pending = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        if let Some(path) = startup.config.clone().or_else(Config::default_path)
            && let Some(dir) = path.parent().map(|p| p.to_path_buf())
        {
            match prepare_config_directory(&path, startup.config_trust) {
                Err(error) => {
                    log::warn!("config live-reload disabled for {}: {error}", dir.display())
                }
                Ok(()) => {
                    let p = proxy.clone();
                    let watched = path.clone();
                    let pending = config_reload_pending.clone();
                    use notify::Watcher;
                    let built =
                        notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
                            if let Ok(ev) = res
                                && watcher_event_matches(&ev, &watched)
                            {
                                queue_watcher_event(&pending, || {
                                    p.send_event(UserEvent::ReloadConfig).is_ok()
                                });
                            }
                        });
                    match built.and_then(|w| {
                        registered_watcher(w, |w| {
                            w.watch(&dir, notify::RecursiveMode::NonRecursive)
                        })
                    }) {
                        Ok(w) => watcher = Some(w),
                        Err(error) => log::warn!(
                            "config live-reload unavailable for {}: {error}",
                            dir.display()
                        ),
                    }
                }
            }
        }

        // Remote-control watcher. Same notify pattern as the
        // config-reload watcher above. When startup.remote_file is
        // Some, watch its parent directory; on a change to the file
        // itself, send UserEvent::RemoteCommand so the main thread
        // reads + dispatches lines.
        let mut remote_watcher = None;
        let mut remote_startup_retry = false;
        let remote_command_pending = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        if let Some(path) = startup.remote_file.clone()
            && let Some(dir) = path.parent().map(|p| p.to_path_buf())
        {
            let p = proxy.clone();
            let watched = path.clone();
            let pending = remote_command_pending.clone();
            // `remote.cmd` is a command channel into this terminal, so its
            // parent must be private before the lock below touches anything.
            // Repairing here rather than relying on some other subsystem
            // having run first is the difference between the watcher working
            // on this launch and on the next one.
            let _ = kettle_state::create_private_dirs(&dir);
            use notify::Watcher;
            let built = notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
                if let Ok(ev) = res
                    && watcher_event_matches(&ev, &watched)
                {
                    queue_watcher_event(&pending, || {
                        p.send_event(UserEvent::RemoteCommand).is_ok()
                    });
                }
            });
            // Same silent constructor as the config watcher above, and the same
            // reason to report it: this one carries remote commands, so a
            // channel that never subscribes is worth a line in the log.
            if let Err(error) = &built {
                log::warn!("remote-command watcher unavailable: {error}");
            }
            if let Ok(mut w) = built {
                // Create or harden the control file before registering its
                // watcher, and truncate through that verified handle so a
                // reparse/path swap cannot redirect startup cleanup. Commands
                // left after a previous crash must not replay into this run.
                let lock_path = kettle_state::remote_command_lock_path(&path);
                match kettle_state::ExclusiveFileLock::try_acquire(&lock_path) {
                    Ok(Some(_lock)) => {
                        // Keep the sender/receiver lock through watcher
                        // registration. Once it is released, every later
                        // append is observed; there is no truncate→watch gap
                        // in which a valid command can be stranded.
                        let initialized = kettle_state::open_private_file(&path)
                            .and_then(|file| file.set_len(0))
                            .and_then(|()| {
                                w.watch(&dir, notify::RecursiveMode::NonRecursive)
                                    .map_err(std::io::Error::other)
                            });
                        match initialized {
                            Ok(()) => remote_watcher = Some(w),
                            Err(error) => log::warn!(
                                "remote-command watcher disabled for {}: {error}",
                                path.display()
                            ),
                        }
                    }
                    Ok(None) => {
                        // A live sender owns the spool. Register the watcher
                        // immediately and claim asynchronously once it releases
                        // the lock; waiting and then truncating would erase the
                        // command that sender just finished appending.
                        match w
                            .watch(&dir, notify::RecursiveMode::NonRecursive)
                            .map_err(std::io::Error::other)
                        {
                            Ok(()) => {
                                log::warn!(
                                    "remote-command startup lock at {} is busy; \
                                     watcher is active and the spool will be claimed asynchronously",
                                    lock_path.display()
                                );
                                remote_startup_retry = true;
                                remote_watcher = Some(w);
                            }
                            Err(watch_error) => log::warn!(
                                "remote-command watcher disabled for {} while its startup lock \
                                 was busy: {watch_error}",
                                path.display()
                            ),
                        }
                    }
                    Err(error) => log::warn!(
                        "remote-command watcher disabled for {}: {error}",
                        path.display()
                    ),
                }
            }
        }

        // Load the config into a local so the trigger compile and the `cfg`
        // field below can both use it; inside the struct init, a bare `cfg.…`
        // would hit the `cfg!()` macro instead.
        let initial_path = startup.config.clone().or_else(Config::default_path);
        let mut initial_cfg = match initial_path.as_deref().filter(|path| path.exists()) {
            Some(path) => match prepare_config_directory(path, startup.config_trust)
                .and_then(|()| Config::read_from_with_trust(path, startup.config_trust))
            {
                Ok(loaded) => {
                    if !loaded.unknown_keys.is_empty() {
                        log::warn!(
                            "{}: unrecognized config keys: {}",
                            path.display(),
                            loaded.unknown_keys.join(", ")
                        );
                    }
                    if !loaded.malformed_values.is_empty() {
                        log::warn!(
                            "{}: malformed values (ignored): {}",
                            path.display(),
                            loaded.malformed_values.join(", ")
                        );
                    }
                    loaded.config
                }
                Err(error) => {
                    log::warn!("config {} ignored: {error}", path.display());
                    // No `language` to read, so the notice follows the OS.
                    let tr = kettle_i18n::Translator::new(
                        kettle_config::LanguagePreference::Auto.resolve(kettle_i18n::os_locale),
                    );
                    fire_notify(
                        tr.text(kettle_i18n::Text::NotifyTitleConfigIgnored),
                        &tr.notify_body_config_ignored(
                            &path.display().to_string(),
                            &error.to_string(),
                        ),
                    );
                    Config::default()
                }
            },
            None => Config::default(),
        };
        // The process's UI language, fixed for its lifetime: a config reload
        // keeps it, and Settings says a change applies on restart.
        let ui_text =
            kettle_i18n::Translator::new(initial_cfg.language.resolve(kettle_i18n::os_locale));
        // `EventLoop::build` registers and installs winit's application
        // delegate, so the Dock menu can only be grafted on after it; its rows
        // need the UI language, so after the config is read too.
        crate::macos_dock::install(proxy.clone(), &ui_text);
        // Peacock parity: the --accent CLI flag wins over the config
        // `accent-color` key. Applied here at startup and again on every
        // config reload, since CLI flags are launch-time intent.
        if let Some(rgb) = startup.accent_override {
            initial_cfg.accent_color = Some(rgb);
        }
        // Terminator parity: launch-time window-state CLI flags
        // (`-m/-f/-H/-b/-T`) override the config for THIS launch — same
        // "CLI flags are launch-time intent" precedent as --accent above.
        if let Some(wstate) = startup.window_state_override {
            initial_cfg.window_state = wstate;
        }
        if let Some(b) = startup.borderless_override {
            initial_cfg.borderless = b;
        }
        if let Some(title) = startup.title_override.clone() {
            // A literal title (no `{title}` placeholder) renders verbatim.
            initial_cfg.window_title_format = title;
        }
        // Peacock: seed the per-window accent variation from this
        // window's working directory, so `accent-color = auto` gives a window
        // in a different project a different (but per-project stable) accent.
        initial_cfg.accent_seed = accent_seed_from_cwd(startup.cwd.as_deref());
        crate::startup_trace::mark(crate::startup_trace::Phase::ConfigLoaded);
        font_preload.request_family(&initial_cfg.font_family);
        let initial_triggers = compile_triggers(&initial_cfg.triggers);
        // Dropdown-parity: capture before `startup` moves into the App.
        let startup_version = startup
            .version
            .clone()
            .unwrap_or_else(|| env!("CARGO_PKG_VERSION").to_string());
        let runtime_tracker = crate::runtime_diagnostics::RuntimeTracker::start(
            cache_dir_from_env(|key| std::env::var(key).ok()),
            startup_version.clone(),
        );
        // Lua scripting foundation. If `--lua-script PATH`
        // was set, init a LuaEngine + run the script once. Failures
        // log::warn but don't block the launch (same shape as
        // `compile_triggers`'s per-pattern warn-and-skip fallthrough).
        //
        // Also drain pending side-effect commands queued
        // by Lua and stash them on App so the first focused pane
        // gets them written to its PTY once it's ready (the pane
        // doesn't exist yet at this point in `run_with`).
        let mut pending_lua_commands = PendingLuaCommands::default();
        let mut initial_lua_queue_rejection_reported = false;
        // Keep the LuaEngine alive on App so kettle.on(...) registrations
        // survive startup and can be fire_event'd from emission sites. With no
        // --lua-script and no `<config-dir>/init.lua`, engine init is skipped
        // so non-Lua runs stay zero-cost.
        //
        // Script resolution:
        //   1. --lua-script PATH (explicit; overrides)
        //   2. <config-dir>/init.lua  (auto-loaded; default for plugins)
        // where <config-dir> is the parent of Config::default_path().
        let init_lua = resolved_init_lua_script(
            startup.lua_script.clone(),
            kettle_config::Config::default_path(),
        );
        let mut lua_engine: Option<crate::LuaEngine> = None;
        if let Some((script, trust)) = &init_lua {
            match crate::LuaEngine::new_with_sandbox(
                &initial_cfg.theme_name,
                initial_cfg.lua_sandbox,
            ) {
                Ok(eng) => {
                    let executed = match trust {
                        ConfigTrust::ExplicitPath => eng.exec_file(script),
                        ConfigTrust::VerifyDirectory => eng.exec_trusted_file(script),
                    };
                    if let Err(e) = executed {
                        log::warn!("lua script {}: {e:#}", script.display());
                    } else {
                        log::info!("lua script {}: executed", script.display());
                    }
                    for cmd in eng.drain_commands() {
                        let result = match cmd {
                            crate::LuaCommand::SendText(s) => {
                                pending_lua_commands.push(PendingLuaCommand::SendText {
                                    origin_window: 1,
                                    target_pane: None,
                                    bytes: Arc::from(s.into_bytes()),
                                })
                            }
                            crate::LuaCommand::ExecAction(name) => {
                                if let Some(a) = kettle_config::Action::from_name(&name) {
                                    pending_lua_commands.push(PendingLuaCommand::ExecAction {
                                        origin_window: 1,
                                        action: a,
                                    })
                                } else {
                                    log::warn!(
                                        "lua kettle.exec_action: unknown action name {name:?}"
                                    );
                                    PaneInputResult::Queued
                                }
                            }
                            crate::LuaCommand::Notify { title, body } => {
                                pending_lua_commands.push(PendingLuaCommand::Notify {
                                    origin_window: 1,
                                    title,
                                    body,
                                })
                            }
                            crate::LuaCommand::CallbackStopped { event, dropped } => {
                                pending_lua_commands.push(PendingLuaCommand::CallbackStopped {
                                    origin_window: 1,
                                    event,
                                    dropped,
                                })
                            }
                            crate::LuaCommand::SetTheme(name) => {
                                pending_lua_commands.push(PendingLuaCommand::SetTheme {
                                    origin_window: 1,
                                    name,
                                })
                            }
                        };
                        if result != PaneInputResult::Queued
                            && !initial_lua_queue_rejection_reported
                            && let Some(message) = input_rejection_message(result)
                        {
                            log::warn!("lua startup command rejected ({result:?}): {message}");
                            fire_notify(
                                ui_text.text(kettle_i18n::Text::NotifyTitleLuaNotQueued),
                                input_rejection_text(result, &ui_text).unwrap_or(message),
                            );
                            initial_lua_queue_rejection_reported = true;
                        }
                    }
                    lua_engine = Some(eng);
                }
                Err(e) => {
                    log::warn!("lua engine init failed: {e:#}");
                }
            }
        }
        // If a LuaEngine is active,
        // the Mux must subscribe to per-PTY output bytes so the
        // App can fire LuaEvent::Output. Set before the Mux moves
        // into the struct.
        let lua_output_subscribed = lua_engine.is_some();
        // Also subscribe to per-pane PTY output when recording is requested for
        // this launch — either the one-shot CLI/env target (`startup.record`) OR
        // the persistent `record = on` config key (`initial_cfg.record`) — so the
        // recorder can tee output into the asciicast trace. The first pane is
        // spawned (with this flag baked in) BEFORE the recorder starts in
        // `resumed_inner`, so a missing config check here would leave the `o`
        // (terminal output) channel permanently empty while still showing `[REC]`.
        let recording_requested = startup.record.is_some() || initial_cfg.record.enabled();
        // Retention budgets are process-wide in kettle-core, so publish them
        // before any recorder can be constructed.
        crate::dev_record::apply_retention_config(&initial_cfg);
        let lua_output_subscribed = lua_output_subscribed || recording_requested;
        // Broadcast always starts off; `broadcast-default` only picks the
        // scope the toggle chord turns on (`broadcast_scope_for_default`).
        // Resolve clipboard availability before constructing the first Mux:
        // DA1 extension 52 is a runtime capability, not merely compiled code,
        // and must not be advertised when policy or the platform denies writes.
        let clipboard = match arboard::Clipboard::new() {
            Ok(cb) => Some(cb),
            Err(e) => {
                log::warn!(
                    "clipboard unavailable ({e}); copy/paste and OSC 52 \
                     will no-op — no DISPLAY/Wayland, headless SSH, or a \
                     sandbox without clipboard-portal access?"
                );
                None
            }
        };
        let osc52_copy_allowed = osc52_copy_is_available(initial_cfg.osc52, clipboard.is_some());

        // Per-window state lives in a WindowState; the first window is seq 1.
        // The Mux is built here because its construction flags
        // (`lua_output_subscribed`, `record_lossless`) are process-global
        // decisions.
        let mux = {
            let mut m = Mux::new();
            m.lua_output_subscribed = lua_output_subscribed;
            // A recording needs a lossless output channel so the asciicast
            // trace can't drop chunks under a fast burst (CLI/env target or the
            // `record = on` config key — see `recording_requested` above).
            {
                m.record_lossless = recording_requested;
            }
            m.osc52_copy_allowed = osc52_copy_allowed;
            m.autoclean_groups = initial_cfg.autoclean_groups;
            m
        };
        let mut windows = std::collections::BTreeMap::new();
        let mut initial_window = WindowState::new(1, mux);
        initial_window.cursor_exit_log = crate::cursor_exit_log::CursorExitLog::from_env(1);
        windows.insert(1, initial_window);
        let remote_proxy = proxy.clone();
        let remote_scan_worker =
            match kettle_remote::RemoteScanWorker::spawn_with_notifier(move || {
                let _ = remote_proxy.send_event(UserEvent::RemoteScanReady);
            }) {
                Ok(worker) => Some(worker),
                Err(error) => {
                    log::warn!(
                        "remote-context detection disabled: cannot start scanner worker: {error}"
                    );
                    None
                }
            };
        let video_previewer =
            crate::video_preview::VideoPreviewer::new(proxy.clone(), startup.media.clone());
        let plan = startup_plan(&startup, &initial_cfg);
        let ctl_policy = ctl_overrides(&startup).resolve(initial_cfg.ctl_policy());
        let mut app = App {
            #[cfg(target_os = "linux")]
            wayland: None,
            #[cfg(target_os = "linux")]
            wayland_tab_drag: None,
            #[cfg(target_os = "linux")]
            wayland_file_drops: std::collections::BTreeMap::new(),
            restore_source: None,
            cfg: initial_cfg,
            // Assume writable; `resumed` clears it when a launch override
            // means the named layout was never loaded.
            named_layout_writable: true,
            windows,
            accent_registry: crate::window_accent::AccentRegistry::default(),
            focused_seq: 1,
            next_window_seq: 2,
            gpu: None,
            font_preload: Some(font_preload),
            launch_override: plan.launch_override,
            pre_launch_eligible: plan.pre_launch && !plan.may_restore,
            gpu_choices: Vec::new(),
            ui_text,
            gpu_recovery: RecoveryState::default(),
            gpu_incident: None,
            gpu_incident_started_for_loss: false,
            gpu_software_fallback: false,
            window_icon_dark_synced: None,
            pending_window_closes: std::collections::BTreeSet::new(),
            quit_requested: false,
            recorder: None,
            recording_start_failed: false,
            recording_error_reported: false,
            last_input_rejection_notice: None,
            system_motion: std::sync::OnceLock::new(),
            #[cfg(target_os = "linux")]
            agent_launches: kettle_ctl::agent_launch::LaunchScopes::default(),
            proxy,
            activation,
            runtime_tracker,
            wake_pending: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
            config_reload_pending,
            config_reload_deadline: None,
            remote_command_pending,
            pending_remote_commands: VecDeque::new(),
            remote_spool_claim_pending: remote_startup_retry,
            remote_command_retry: {
                let mut retry = AutomationRetry::default();
                if remote_startup_retry {
                    retry.expedite_if_idle(std::time::Instant::now());
                }
                retry
            },
            // Server is started later in `resumed`
            // (needs the pid + a live event-loop proxy for the waker).
            ctl: None,
            ctl_policy,
            ctl_start: CtlStart::NotReady,
            pending_runs: std::collections::HashMap::new(),
            media: crate::media::MediaService::default(),
            cards_tip: crate::media::CardsTip::load(),
            clipboard,
            pasted_images: crate::paste_image::PastedImages::new(crate::paste_image::PASTED),
            png_encoder: None,
            png_jobs: 0,
            queued_pastes: std::collections::VecDeque::new(),
            viewer_copies: std::sync::Arc::new(std::sync::Mutex::new(
                crate::paste_image::PastedImages::new(crate::paste_image::OPENED),
            )),
            video_copies: std::sync::Arc::new(crate::media::VideoCopies::new()),
            previews_ready: Vec::new(),
            ctl_driving: false,
            lua_driving: false,
            crop_tickets: 0,
            page_tickets: 0,
            preview_tickets: 0,
            preview_copy: None,
            video_previewer,
            next_video_preview_generation: 1,
            compiled_triggers: initial_triggers,
            last_trigger_fire: None,
            remote_scan_worker,
            remote_applied: std::collections::HashMap::new(),
            remote_live_panes_scratch: std::collections::HashSet::new(),
            remote_targets_scratch: Vec::new(),
            last_remote_poll: None,
            remote_poll_due: None,
            last_schedule_decision: None,
            config_path: startup.config.clone(),
            config_trust: startup.config_trust,
            config_malformed_last: Vec::new(),
            startup,
            _watcher: watcher,
            _remote_watcher: remote_watcher,
            pending_lua_commands,
            lua_command_retry: AutomationRetry::default(),
            lua_engine,
            lua_startup_fired: false,
            update_available: None,
            version_line: startup_version,
            torn_drag: None,
            last_session_sweep: None,
        };
        app.runtime_tracker.set_window_count(app.windows.len());
        // Before the first pane, which may start Claude Code or Codex.
        app.reconcile_claude_plugin();
        app.reconcile_codex_shell();
        crate::startup_trace::mark(crate::startup_trace::Phase::AppBuilt);
        let result: Result<()> = match app.start_first_pane_before_launch() {
            Ok(_) => event_loop.run_app(&mut app).map_err(Into::into),
            Err(error) => {
                log::error!("{error}");
                Err(anyhow::anyhow!(error))
            }
        };
        app.runtime_tracker.set_phase("exiting");
        // Pasted screenshots are captured screen content, so they do not outlive
        // the session that produced them. Runs on the error path too — an exit
        // caused by a failure is exactly when leftovers would go unnoticed.
        // PNGs still being encoded are stopped and kept first, so cleanup
        // takes them too.
        if let Some(encoder) = app.png_encoder.take() {
            for encoded in encoder.close() {
                let _ = app.pasted_images.keep_png(encoded);
            }
        }
        app.pasted_images.cleanup();
        // So are the copies handed to the image viewer, and the store closes
        // so an open still on its way cannot leave a new one.
        app.viewer_copies
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .close();
        // And the copies handed to the video player; a copy on its way
        // stops first.
        app.video_copies.close();
        if let Err(error) = &result {
            app.runtime_tracker.record_exit(&error.to_string());
        }
        app.runtime_tracker.stop();
        crate::notifications::flush_desktop_notifications(std::time::Duration::from_millis(250));
        result
    }

    /// Drain commands a Lua callback (event hook or menu-item) just enqueued.
    /// Handles every LuaCommand variant: SendText, ExecAction, Notify, SetTheme.
    ///
    /// This is the shared drain path. `fire_lua_event` routes every event hook
    /// here, and the URL handler and the lua menu-item click call it directly.
    /// Startup in `run_with` cannot use it (early init operates on locals
    /// before `self` exists); every other LuaCommand consumer routes here.
    ///
    /// `hook_name` is the hook label used in unknown-action warn
    /// messages (e.g. "tab_add hook", "lua menu-item").
    fn drain_lua_hook_commands(&mut self, ws: &WindowState, hook_name: &str) {
        let commands = self
            .lua_engine
            .as_ref()
            .map(crate::LuaEngine::drain_commands)
            .unwrap_or_default();
        let mut admitted = false;
        for command in commands {
            let pending = match command {
                crate::LuaCommand::SendText(text) => PendingLuaCommand::SendText {
                    origin_window: ws.seq,
                    // Resolve only when this FIFO entry reaches the head: an
                    // earlier Lua action may intentionally change focus first.
                    // The first attempt latches the id so a retry cannot type
                    // into a different pane after a focus change.
                    target_pane: None,
                    bytes: Arc::from(text.into_bytes()),
                },
                crate::LuaCommand::ExecAction(name) => {
                    let Some(action) = kettle_config::Action::from_name(&name) else {
                        log::warn!("lua kettle.exec_action ({hook_name}): unknown action {name:?}");
                        continue;
                    };
                    PendingLuaCommand::ExecAction {
                        origin_window: ws.seq,
                        action,
                    }
                }
                crate::LuaCommand::Notify { title, body } => PendingLuaCommand::Notify {
                    origin_window: ws.seq,
                    title,
                    body,
                },
                crate::LuaCommand::CallbackStopped { event, dropped } => {
                    PendingLuaCommand::CallbackStopped {
                        origin_window: ws.seq,
                        event,
                        dropped,
                    }
                }
                crate::LuaCommand::SetTheme(name) => PendingLuaCommand::SetTheme {
                    origin_window: ws.seq,
                    name,
                },
            };
            let result = self.pending_lua_commands.push(pending);
            admitted |= result == PaneInputResult::Queued;
            self.report_input_result(result);
        }
        if admitted {
            self.lua_command_retry
                .expedite_if_idle(std::time::Instant::now());
        }
    }

    /// Fire one Lua event and immediately transfer every side effect it queued
    /// into App's bounded FIFO. Keeping the pair inseparable prevents a callback
    /// from accumulating commands until an unrelated event happens to drain it.
    fn fire_lua_event(&mut self, ws: &WindowState, event: crate::LuaEvent, hook_name: &str) {
        if let Some(engine) = &self.lua_engine {
            engine.fire_event(&event);
        }
        self.drain_lua_hook_commands(ws, hook_name);
    }

    fn report_lua_target_gone(&mut self, pane_id: u64) {
        let now = std::time::Instant::now();
        if should_notify_input_rejection(
            self.last_input_rejection_notice,
            PaneInputResult::Failed,
            now,
        ) {
            let message = format!(
                "A queued Lua send_text target pane ({pane_id}) closed before the command could be delivered. The command was dropped and was not rerouted."
            );
            log::warn!("{message}");
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleLuaNotDelivered),
                &self.ui_text.notify_body_lua_not_delivered(pane_id),
            );
            self.last_input_rejection_notice = Some((PaneInputResult::Failed, now));
        }
    }

    /// Run a bounded slice of the process-global Lua side-effect FIFO for this
    /// window. A stalled PTY retains the head message byte-for-byte and arms an
    /// exponential retry; later commands cannot overtake it.
    fn poll_pending_lua_commands(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        if self.pending_lua_commands.is_empty() {
            self.lua_command_retry.progressed();
            return None;
        }
        if !self.lua_command_retry.is_ready(now) {
            return self.lua_command_retry.remaining(now);
        }

        let mut processed = 0usize;
        let mut processed_send_bytes = 0usize;
        while processed < AUTOMATION_WORK_ITEMS_PER_TURN
            && processed_send_bytes < AUTOMATION_WORK_BYTES_PER_TURN
        {
            let Some(origin_window) = self
                .pending_lua_commands
                .front()
                .map(PendingLuaCommand::origin_window)
            else {
                break;
            };
            if origin_window != ws.seq {
                if !self.windows.contains_key(&origin_window) {
                    log::warn!(
                        "dropping queued Lua command because its originating window \
                         {origin_window} no longer exists"
                    );
                    self.pending_lua_commands.pop_front();
                    self.lua_command_retry.progressed();
                    processed += 1;
                    continue;
                }
                // The outer multi-window pass will dispatch this FIFO head when
                // it reaches the owning window. A 1 ms deadline covers the case
                // where that window was already visited in this pass.
                return Some(AUTOMATION_YIELD);
            }

            if matches!(
                self.pending_lua_commands.front(),
                Some(PendingLuaCommand::SendText { .. })
            ) {
                let fallback = ws.mux.active_focus();
                let target_pane = match self.pending_lua_commands.front_mut() {
                    Some(PendingLuaCommand::SendText { target_pane, .. }) => {
                        if target_pane.is_none() {
                            *target_pane = fallback;
                        }
                        *target_pane
                    }
                    _ => unreachable!("front was checked as SendText"),
                };
                let Some(target_pane) = target_pane else {
                    self.lua_command_retry.backpressured(now);
                    return self.lua_command_retry.remaining(now);
                };
                let bytes = match self.pending_lua_commands.front() {
                    Some(PendingLuaCommand::SendText { bytes, .. }) => bytes.clone(),
                    _ => unreachable!("front was checked as SendText"),
                };
                // An action earlier in this batch may have moved focus.
                self.sync_pane_focus_reports(ws);
                let result = if let Some(pane) = ws.mux.panes.get(&target_pane) {
                    Some(pane.feed_input_shared(bytes.clone()))
                } else {
                    self.windows
                        .values()
                        .find_map(|window| window.mux.panes.get(&target_pane))
                        .map(|pane| pane.feed_input_shared(bytes.clone()))
                };
                let Some(result) = result else {
                    self.pending_lua_commands.pop_front();
                    self.lua_command_retry.progressed();
                    self.report_lua_target_gone(target_pane);
                    processed += 1;
                    processed_send_bytes += bytes.len();
                    continue;
                };
                match result {
                    PaneInputResult::Queued | PaneInputResult::ReadOnly => {
                        self.pending_lua_commands.pop_front();
                        self.lua_command_retry.progressed();
                        processed += 1;
                        processed_send_bytes += bytes.len();
                    }
                    PaneInputResult::Backpressured => {
                        self.report_input_result(result);
                        self.lua_command_retry.backpressured(now);
                        return self.lua_command_retry.remaining(now);
                    }
                    PaneInputResult::Oversize | PaneInputResult::Failed => {
                        self.pending_lua_commands.pop_front();
                        self.lua_command_retry.progressed();
                        self.report_input_result(result);
                        processed += 1;
                        processed_send_bytes += bytes.len();
                    }
                }
                continue;
            }

            let Some(command) = self.pending_lua_commands.pop_front() else {
                break;
            };
            self.lua_command_retry.progressed();
            processed += 1;
            match command {
                PendingLuaCommand::ExecAction { action, .. } => {
                    self.lua_driving = true;
                    self.handle_action(ws, action, event_loop);
                    self.lua_driving = false;
                    if self.window_close_pending(ws.seq) || self.quit_requested {
                        break;
                    }
                }
                PendingLuaCommand::Notify { title, body, .. } => {
                    fire_notify(&title, &body);
                }
                PendingLuaCommand::CallbackStopped { event, dropped, .. } => {
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleLuaCallbackStopped),
                        &self
                            .ui_text
                            .notify_body_lua_callback_stopped(dropped, &event),
                    );
                }
                PendingLuaCommand::SetTheme { name, .. } => {
                    if let Some(canonical) = kettle_config::Theme::find_name(&name) {
                        self.set_runtime_theme_name(ws, canonical);
                    } else {
                        log::warn!("lua kettle.set_theme: unknown theme {name:?}");
                    }
                }
                PendingLuaCommand::SendText { .. } => {
                    unreachable!("SendText is handled without removing a retryable head")
                }
            }
        }

        if self.pending_lua_commands.is_empty() {
            self.lua_command_retry.progressed();
            None
        } else {
            self.lua_command_retry.yield_soon(now);
            self.lua_command_retry.remaining(now)
        }
    }

    /// Fire LuaEvent::TabAdd + drain commands.
    /// Every Mux::new_tab / new_tab_with call site that USER-VISIBLY
    /// creates a tab (i.e. NOT startup-time first-tab init before
    /// plugins load) should call this. Centralizes the plugin-
    /// contract dispatch so future new_tab callers can't drift. It also
    /// recomputes chrome hover from the new layout: on a vertical tab bar the
    /// `+` moves down one row when a tab is added, so retaining the old hover
    /// would leave the relocated button highlighted and the cursor as a hand
    /// while the pointer is actually over the new tab.
    fn fire_tab_add_event(&mut self, ws: &mut WindowState) {
        if let Some(rec) = self.recorder.as_mut() {
            rec.record_marker("kettle:tab_add");
        }
        self.fire_lua_event(ws, crate::LuaEvent::TabAdd(ws.mux.active), "tab_add hook");
        self.sync_cursor_icon(ws);
    }

    /// Fire LuaEvent::TabClose + drain commands.
    /// Every close_tab call site should call this so plugins
    /// listening for tab_close see every close regardless of
    /// trigger source.
    fn fire_tab_close_event(&mut self, ws: &WindowState, closing_idx: usize) {
        if let Some(rec) = self.recorder.as_mut() {
            rec.record_marker("kettle:tab_close");
        }
        self.fire_lua_event(ws, crate::LuaEvent::TabClose(closing_idx), "tab_close hook");
    }

    /// The shell the focused pane has effectively entered (e.g. the
    /// user opened pwsh then typed `wsl`) — its argv + cwd, so a split can clone
    /// it in the same directory instead of a fresh default shell. Reads the
    /// latest background process snapshot, so a split keystroke never performs
    /// process enumeration on the event-loop thread. `None` before the first
    /// snapshot or for a plain pane; the split then clones the pane's launch
    /// command.
    fn focused_foreground_shell(
        &mut self,
        ws: &mut WindowState,
    ) -> Option<kettle_remote::ShellLaunch> {
        let (pane_id, pid, pane_cwd) = {
            let pane_id = ws.mux.active_focus()?;
            let pane = ws.mux.panes.get(&pane_id)?;
            (
                pane_id,
                pane.term.child_pid()?,
                pane.term.reported_current_dir(),
            )
        };
        let mut shell = self
            .remote_applied
            .get(&(pane_id, pid))?
            .foreground_shell
            .clone()?;
        // Assert the interactive-shell contract at the boundary.
        // The detector already rejects one-shot helpers, but re-checking here
        // means a split can never clone a non-interactive argv into a dead pane —
        // `None` routes the caller to `Mux::split`, which clones the pane's own
        // launch shell (falling back to the configured default).
        if !kettle_remote::shell_launch_is_interactive(&shell.argv) {
            return None;
        }
        // Prefer the pane's OSC 7-reported cwd — where the user actually is (e.g.
        // the WSL bash dir) — over the detected process's cwd, which Windows
        // sysinfo typically can't read for `wsl.exe` (it returned None, so the
        // split fell back to WSL's home `~`). `launch_cwd` carries this via
        // `wsl --cd`, which accepts both `/mnt/c/...` and native Linux paths.
        if pane_cwd.is_some() {
            shell.cwd = pane_cwd;
        }
        Some(shell)
    }

    /// Fire LuaEvent::PaneClose + drain commands — the pane analog
    /// of `fire_tab_close_event`. Every close-pane call site calls this with
    /// the id captured *before* `Mux::close_focused` removes the pane, so
    /// plugins listening for `pane_close` see the right id regardless of
    /// trigger source (keybind, confirm dialog, menu).
    fn fire_pane_close_event(&mut self, ws: &WindowState, pane_id: u64) {
        self.fire_lua_event(ws, crate::LuaEvent::PaneClose(pane_id), "pane_close hook");
    }

    fn waker(&self) -> kettle_core::Waker {
        let p = self.proxy.clone();
        let pending = self.wake_pending.clone();
        Arc::new(move || {
            // Enqueue at most ONE Wakeup per paint window. A queued Wakeup
            // re-checks every pane's output generation when it lands, so every
            // enqueue past the first is pure event-loop spam (a flood would
            // send one per 64KiB read). `swap` returning false means this call
            // owns the enqueue; the Wakeup arm reopens the latch before it
            // reads generations, so nothing is ever missed. Events the proxy
            // queues on the crossbeam channel before waking are drained by
            // that same pending Wakeup, so suppression never delays them.
            if !pending.swap(true, std::sync::atomic::Ordering::AcqRel) {
                let _ = p.send_event(UserEvent::Wakeup);
            }
        })
    }

    fn sync_output_frame_budget(&self, ws: &mut WindowState, force: bool) {
        let Some(window) = ws.window.clone() else {
            ws.output_monitor = None;
            ws.output_frame_budget = OUTPUT_FRAME_BUDGET;
            return;
        };
        // `current_monitor()` is the cheap identity probe. Querying the mode's
        // refresh rate is the expensive part on Windows, so same-monitor move
        // and resize storms share the rate limiter while a true same-DPI
        // monitor transition refreshes immediately.
        let monitor = window.current_monitor();
        let monitor_changed = monitor != ws.output_monitor;
        if monitor_changed {
            ws.output_monitor = monitor.clone();
        }
        let force = force || monitor_changed;
        let now = std::time::Instant::now();
        if monitor_refresh_probe_wait(ws.output_refresh_probe_at, now, force).is_some() {
            // Preserve one trailing probe so a quick same-DPI move from a
            // 60 Hz to a 165 Hz monitor cannot be lost to the rate limiter.
            ws.output_refresh_probe_pending = true;
            return;
        }
        ws.output_refresh_probe_at = Some(now);
        ws.output_refresh_probe_pending = false;
        let refresh_millihertz = monitor.and_then(|monitor| monitor.refresh_rate_millihertz());
        let next = output_frame_budget_for_refresh(refresh_millihertz);
        if next != ws.output_frame_budget {
            log::debug!(
                "window {} output pacing changed: refresh={refresh_millihertz:?} mHz, \
                 budget={next:?}",
                ws.seq
            );
            ws.output_frame_budget = next;
            // A monitor move begins a new pacing regime. Do not carry the old
            // monitor's sustained-flood tier into the first frame on the new
            // display.
            ws.flood_paints = 0;
        }
    }

    fn cell_px(&self, ws: &WindowState) -> (u16, u16) {
        ws.renderer
            .as_ref()
            .map(|r| {
                (
                    r.cell_w.round().clamp(1.0, u16::MAX as f32) as u16,
                    r.cell_h.round().clamp(1.0, u16::MAX as f32) as u16,
                )
            })
            .unwrap_or((8, 16))
    }

    /// Hide the OS mouse cursor; idempotent. Called when the user starts
    /// typing if `mouse-hide-while-typing` is on. The cursor reappears on
    /// the next mouse move or window-enter event.
    fn hide_mouse_cursor(&mut self, ws: &mut WindowState) {
        if ws.mouse_hidden || !self.cfg.mouse_hide_while_typing {
            return;
        }
        if let Some(w) = &ws.window {
            w.set_cursor_visible(false);
            ws.mouse_hidden = true;
        }
    }

    /// Show the OS mouse cursor; idempotent. Called whenever the mouse
    /// moves or re-enters the window.
    fn show_mouse_cursor(&mut self, ws: &mut WindowState) {
        if !ws.mouse_hidden {
            return;
        }
        if let Some(w) = &ws.window {
            w.set_cursor_visible(true);
            ws.mouse_hidden = false;
        }
    }

    /// True when the cursor is over the status bar. Used
    /// by `cursor_in_chrome_band` so the OS arrow icon overrides
    /// the terminal I-beam over the status strip too.
    fn cursor_in_status_bar(&self, ws: &WindowState) -> bool {
        let h = self.status_bar_h(ws);
        if h <= 0.0 {
            return false;
        }
        let (_, sh) = ws
            .renderer
            .as_ref()
            .map(|r| r.surface_size())
            .unwrap_or((800, 600));
        cursor_in_status_bar_band(ws.cursor.y as f32, h, sh as f32, self.cfg.status_bar)
    }

    fn cursor_in_update_banner(&self, ws: &WindowState) -> bool {
        let Some((x, y, w, h)) = self.update_banner_rect(ws) else {
            return false;
        };
        let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
        px >= x && px < x + w && py >= y && py < y + h
    }

    /// Combined chrome-band hit-test. True when the cursor is over the tab
    /// bar, the status bar, or the update banner, which all belong in the
    /// "OS arrow cursor" group.
    fn cursor_in_chrome_band(&self, ws: &WindowState) -> bool {
        self.cursor_in_tab_bar(ws)
            || self.cursor_in_status_bar(ws)
            || self.cursor_in_update_banner(ws)
    }

    fn cursor_in_tab_bar(&self, ws: &WindowState) -> bool {
        let h = self.tab_bar_h(ws);
        if h <= 0.0 {
            return false;
        }
        let (sw, sh) = ws
            .renderer
            .as_ref()
            .map(|r| r.surface_size())
            .unwrap_or((800, 600));
        // For Left/Right strips, the cursor must be within
        // `cfg.tab_bar_width` of the configured edge.
        match self.cfg.tab_bar_pos {
            TabBarPos::Left => {
                let x = ws.cursor.x as f32;
                (0.0..self.cfg.tab_bar_width).contains(&x)
            }
            TabBarPos::Right => {
                let x = ws.cursor.x as f32;
                x >= sw as f32 - self.cfg.tab_bar_width && x <= sw as f32
            }
            TabBarPos::Top | TabBarPos::Bottom => {
                cursor_in_tab_bar_band(ws.cursor.y as f32, h, sh as f32, self.cfg.tab_bar_pos)
            }
        }
    }

    /// The resize cursor for a split of the given
    /// orientation. A Horizontal split places panes side-by-side (a vertical
    /// divider you drag left/right → column resize); a Vertical split stacks
    /// them (a horizontal divider you drag up/down → row resize).
    fn resize_cursor_for(dir: Dir) -> CursorIcon {
        match dir {
            Dir::Horizontal => CursorIcon::ColResize,
            Dir::Vertical => CursorIcon::RowResize,
        }
    }

    /// A SplitDrag for the divider seam under content-area pixel
    /// `(px, py)`, or None. Used to start a drag-to-resize on left-press.
    fn split_drag_at(&self, ws: &WindowState, area: Rect, px: f32, py: f32) -> Option<SplitDrag> {
        let seams = ws.mux.split_seams(ws.mux.active, area);
        let i = crate::mux::seam_at(&seams, px, py, SPLIT_SEAM_TOL)?;
        let s = &seams[i];
        Some(SplitDrag {
            path: s.path.clone(),
            dir: s.dir,
        })
    }

    /// The resize cursor to show while merely HOVERING a divider
    /// seam (no drag yet), or None when the cursor isn't over one. Suppressed
    /// while a modal owns the pointer. Cheap in the common single-pane case —
    /// `split_seams` returns empty when the tab root is a lone leaf.
    fn split_seam_hover_icon(&self, ws: &WindowState) -> Option<CursorIcon> {
        if self.any_modal_open(ws) {
            return None;
        }
        let area = self.area(ws);
        let seams = ws.mux.split_seams(ws.mux.active, area);
        let i = crate::mux::seam_at(
            &seams,
            ws.cursor.x as f32,
            ws.cursor.y as f32,
            SPLIT_SEAM_TOL,
        )?;
        Some(Self::resize_cursor_for(seams[i].dir))
    }

    fn confirm_button_hovered(&self, ws: &WindowState) -> bool {
        let Some(dialog) = ws.confirm_dialog.as_ref() else {
            return false;
        };
        let Some(window) = ws.window.as_ref() else {
            return false;
        };
        let size = window.inner_size();
        let (cw, ch) = self.cell_px(ws);
        confirm_dialog_button_hit(
            &dialog.buttons,
            (ws.cursor.x as f32, ws.cursor.y as f32),
            (size.width as f32, size.height as f32),
            (cw as f32, ch as f32),
            &self.ui_text,
        )
        .is_some()
    }

    fn confirm_button_click_result(&self, ws: &WindowState) -> Option<ConfirmKeyResult> {
        let dialog = ws.confirm_dialog.as_ref()?;
        let window = ws.window.as_ref()?;
        let size = window.inner_size();
        let (cw, ch) = self.cell_px(ws);
        let idx = confirm_dialog_button_hit(
            &dialog.buttons,
            (ws.cursor.x as f32, ws.cursor.y as f32),
            (size.width as f32, size.height as f32),
            (cw as f32, ch as f32),
            &self.ui_text,
        )?;
        match dialog.buttons.get(idx)? {
            ConfirmButton::Cancel => Some(ConfirmKeyResult::Cancel),
            ConfirmButton::Confirm { .. } => Some(ConfirmKeyResult::Confirm),
        }
    }

    fn confirm_mouse_press(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        bcode: u8,
    ) -> bool {
        if ws.confirm_dialog.is_none() {
            return false;
        }
        if bcode == 0
            && let Some(result) = self.confirm_button_click_result(ws)
        {
            match result {
                ConfirmKeyResult::Confirm => {
                    if let Some(to_run) = ws.confirm_dialog.as_ref().map(|s| s.on_confirm.clone()) {
                        ws.confirm_dialog = None;
                        self.dispatch_confirm_action(ws, to_run, event_loop);
                    }
                }
                ConfirmKeyResult::Cancel => self.cancel_confirm_dialog(ws),
                ConfirmKeyResult::Move(_) | ConfirmKeyResult::Ignore => {}
            }
        }
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        true
    }

    fn media_paste_receipt_geometry(
        &self,
        ws: &WindowState,
    ) -> Option<kettle_render::MediaPasteReceiptGeometry> {
        let (receipt, completion) = self.media_paste_receipt_projection(ws)?;
        kettle_render::media_paste_receipt_geometry(
            &receipt,
            completion.as_ref(),
            self.menu_cell(ws),
            self.overlay_text_cell_width(ws),
            self.overlay_text_line_height(ws),
        )
    }

    fn media_paste_receipt_hovered(&self, ws: &WindowState) -> bool {
        self.media_paste_receipt_geometry(ws)
            .is_some_and(|geometry| {
                rect_contains(geometry.rect, ws.cursor.x as f32, ws.cursor.y as f32)
            })
    }

    fn update_media_paste_receipt_hover(&self, ws: &mut WindowState) -> bool {
        let hovered = self.media_paste_receipt_hovered(ws);
        let changed = ws
            .media_paste_receipt
            .as_mut()
            .is_some_and(|receipt| receipt.set_hover(hovered, std::time::Instant::now()));
        if changed {
            ws.accessibility_pending = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        hovered
    }

    /// Note the card a primary press at the pointer would take, for the hand
    /// cursor and the hover outline: one settled under it, with no Shift,
    /// dialog, menu or viewer in the way. One that has not settled yet
    /// leaves a wake for when it does, so a still pointer gets the hand
    /// then.
    fn note_card_hover(&self, ws: &mut WindowState) -> bool {
        let now = std::time::Instant::now();
        let card = ws
            .native_pointer
            .filter(|_| !ws.mods.shift_key() && !self.pointer_modal_open(ws))
            .and_then(|pointer| {
                ws.renderer
                    .as_ref()?
                    .card_at(pointer.x as f32, pointer.y as f32)
            });
        let settled = card.filter(|card| ws.card_sightings.settled(Some(*card), now).is_some());
        ws.card_settle_wake = card
            .filter(|_| settled.is_none())
            .and_then(|card| ws.card_sightings.settles_at(&card, now));
        if ws.card_hover != settled {
            ws.card_hover = settled;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        settled.is_some()
    }

    /// Set the OS mouse-cursor icon, deduped against the last value pushed
    /// to the window. Called on CursorMoved (position changes the
    /// hit-test) and on ModifiersChanged (the modifier state gates the
    /// click-to-open affordance). The icon, and the hover state these hit
    /// tests set, are the physical pointer's: every hit test reads where it
    /// is, not where a control client last moved the cursor, and with the
    /// pointer outside the window there is nothing to set.
    fn sync_cursor_icon(&mut self, ws: &mut WindowState) {
        let Some(pointer) = ws.native_pointer else {
            return;
        };
        let control = std::mem::replace(&mut ws.cursor, pointer);
        let media_receipt_hovered = self.media_paste_receipt_hovered(ws);
        self.sync_cursor_icon_with_media_receipt_hover(ws, media_receipt_hovered);
        ws.cursor = control;
    }

    /// CursorMoved already computed the receipt hit test to update its hover
    /// timer. Reuse that answer instead of building a second full overlay for
    /// the same physical event.
    fn sync_cursor_icon_with_media_receipt_hover(
        &mut self,
        ws: &mut WindowState,
        media_receipt_action_hovered: bool,
    ) {
        // Browser / iTerm2 / Ghostty convention: the OS cursor turns into
        // a "pointing hand" while the user holds the same modifier that
        // would open a URL on click (Ctrl on Linux/Windows, Cmd on
        // macOS — winit's `super_key` maps Cmd) and the pointer sits on
        // a clickable link. Otherwise show the standard text-I-beam, the
        // affordance every modern terminal uses for "this surface accepts
        // mouse selection."
        //
        // Chrome surfaces (tab bar, open modal overlays) override that —
        // they're clickable, not selectable, so the I-beam there is
        // visually misleading. `chrome_cursor_icon` is the pure decision.
        //
        // Tab close-buttons (`✕`) override the chrome `Default` with
        // `Pointer` so the trailing glyph reads as a clickable
        // affordance rather than a character in the title. Recomputed
        // here every cursor-move so the chip-hover state in the
        // renderer stays in sync (the renderer reads
        // `tabbar.hovered_close_idx`, which we pass through in
        // `tab_bar()`).
        let bar = self.tab_bar(ws);
        let prior_hover = (
            ws.hovered_close_idx,
            ws.hovered_new_tab,
            ws.hovered_new_tab_menu,
        );
        ws.hovered_close_idx =
            hovered_close_button(&bar.segments, ws.cursor.x as f32, ws.cursor.y as f32);
        let (cursor_x, cursor_y) = (ws.cursor.x as f32, ws.cursor.y as f32);
        let new_tab_hover = new_tab_hover_target(&bar, cursor_x, cursor_y);
        ws.hovered_new_tab = new_tab_hover == Some(NewTabHoverTarget::Plus);
        ws.hovered_new_tab_menu = new_tab_hover == Some(NewTabHoverTarget::Menu);
        if prior_hover
            != (
                ws.hovered_close_idx,
                ws.hovered_new_tab,
                ws.hovered_new_tab_menu,
            )
            && let Some(window) = &ws.window
        {
            window.request_redraw();
        }
        let close_hover = tab_close_hover_icon(ws.hovered_close_idx.is_some());
        let new_tab_hover_icon =
            (ws.hovered_new_tab || ws.hovered_new_tab_menu).then_some(CursorIcon::Pointer);
        let confirm_hover = if self.confirm_button_hovered(ws) {
            Some(CursorIcon::Pointer)
        } else {
            None
        };
        let search_hover = self.search_geometry(ws).and_then(|geometry| {
            let (x, y) = (ws.cursor.x as f32, ws.cursor.y as f32);
            geometry
                .hit_test(x, y)
                .map(|control| {
                    if control == kettle_render::SearchControl::Editor {
                        CursorIcon::Text
                    } else {
                        CursorIcon::Pointer
                    }
                })
                .or_else(|| rect_contains(geometry.rect, x, y).then_some(CursorIcon::Default))
        });
        let media_receipt_hover = media_receipt_action_hovered.then_some(CursorIcon::Pointer);
        // A settled card under the pointer takes a click: the pointing hand.
        let card_hover = self.note_card_hover(ws).then_some(CursorIcon::Pointer);
        let chrome =
            chrome_cursor_icon(self.cursor_in_chrome_band(ws), self.pointer_modal_open(ws));
        // A live tab-drag owns the cursor, FIRST in the chain. Mid-drag the
        // pointer can briefly cross another tab's ✕ hit-zone or a split seam,
        // and without the priority the icon would flicker Pointer/resize while
        // the user is holding a tab. Restore is automatic because `want` is
        // recomputed from live state on every cursor move, so the next event
        // after the FSM returns to `Idle` falls through to the rules below.
        let drag_icon = tab_drag_cursor_icon(&ws.detach_drag);
        // A split divider under the cursor shows the resize cursor
        // (after chrome/close-button, before the link-pointer / I-beam default).
        let want = drag_icon
            .or(close_hover)
            .or(new_tab_hover_icon)
            .or(confirm_hover)
            .or(search_hover)
            .or(media_receipt_hover)
            .or(chrome)
            // A card takes a press before a split seam does, so its hand
            // wins where the two overlap.
            .or(card_hover)
            // A lane takes every press over it.
            .or_else(|| self.lane_cursor_icon(ws))
            .or_else(|| self.split_seam_hover_icon(ws))
            .unwrap_or_else(|| {
                let want_pointer = (ws.mods.control_key() || ws.mods.super_key())
                    && self.link_at_cursor(ws).is_some();
                if want_pointer {
                    CursorIcon::Pointer
                } else {
                    CursorIcon::Text
                }
            });
        let want = if ws.preview_overlay.is_some() && !self.non_search_modal_open(ws) {
            self.lane_cursor_icon(ws).unwrap_or(CursorIcon::Default)
        } else {
            want
        };
        if ws.last_cursor_icon != Some(want)
            && let Some(w) = &ws.window
        {
            w.set_cursor(want);
            ws.last_cursor_icon = Some(want);
        }
    }

    /// Consume presses over receipt chrome. A primary press opens or dismisses
    /// as appropriate; other buttons do nothing rather than reaching terminal
    /// content hidden behind the card.
    /// Shared by native and ctl mouse input so automation cannot click through.
    fn activate_media_paste_receipt_at(
        &mut self,
        ws: &mut WindowState,
        x: f32,
        y: f32,
        bcode: u8,
    ) -> bool {
        let Some((receipt, completion)) = self.media_paste_receipt_projection(ws) else {
            return false;
        };
        let (pane_x, pane_y, pane_w, pane_h) = receipt.pane_rect;
        if receipt.right_gutter > 0.0
            && x >= pane_x + pane_w - receipt.right_gutter
            && x <= pane_x + pane_w
            && y >= pane_y
            && y <= pane_y + pane_h
        {
            return false;
        }
        let Some(geometry) = kettle_render::media_paste_receipt_geometry(
            &receipt,
            completion.as_ref(),
            self.menu_cell(ws),
            self.overlay_text_cell_width(ws),
            self.overlay_text_line_height(ws),
        ) else {
            return false;
        };
        let Some(hit) = geometry.hit_test(x, y) else {
            return false;
        };
        if bcode == 0 {
            if matches!(
                hit,
                kettle_render::MediaPasteReceiptHit::Dismiss
                    | kettle_render::MediaPasteReceiptHit::Body
            ) {
                ws.media_paste_receipt = None;
                ws.accessibility_pending = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            } else if hit == kettle_render::MediaPasteReceiptHit::Open {
                self.open_media_paste_receipt(ws);
            }
        }
        true
    }

    /// Open the focused pane's media shelf in its preview lane, on its
    /// newest item, or close the lane if it has one. Only a user action
    /// opens a lane; a push never does.
    fn open_media_shelf(&mut self, ws: &mut WindowState) {
        let Some(pane) = ws.mux.active_focus() else {
            return;
        };
        if ws.preview_panels.contains_key(&pane) {
            self.close_preview(ws, pane);
            return;
        }
        let Some(item) = ws
            .mux
            .panes
            .get(&pane)
            .and_then(|state| state.media_shelf.latest())
            .map(|item| item.id)
        else {
            return;
        };
        self.close_all_modals(ws);
        self.show_media_item(ws, pane, item);
    }

    /// Open a manual preview in its chosen presentation and mark it viewed.
    fn show_media_item(&mut self, ws: &mut WindowState, pane: u64, item: u64) {
        let overlay = ws.preview_overlay.is_some_and(|open| open.pane == pane)
            || (!ws.preview_panels.contains_key(&pane)
                && self.cfg.media_open_mode == kettle_config::MediaOpenMode::Overlay);
        if overlay {
            // An asynchronous render must not interrupt another tab or dialog.
            let visible = self
                .pane_layout(ws, self.area(ws))
                .iter()
                .any(|(id, _)| *id == pane);
            if !visible || self.non_search_modal_open(ws) || ws.search.open {
                return;
            }
            if let Some(open) = ws.preview_overlay.filter(|open| open.pane != pane) {
                self.close_preview(ws, open.pane);
            }
        }
        // The item already showing keeps its mode, canvas and place, and
        // what was last said about it goes: it may just have been read again.
        let panel = match ws.preview_panels.get(&pane) {
            Some(panel) if panel.item == item => crate::window_state::PreviewPanel {
                notice: None,
                page: None,
                ..*panel
            },
            // Another item: the sharper pixels were the last one's.
            _ => {
                ws.lane_crops.remove(&pane);
                crate::window_state::PreviewPanel::new(item)
            }
        };
        let had_panel = ws.preview_panels.insert(pane, panel).is_some();
        let side = match self.cfg.preview_lane_side {
            kettle_config::PreviewLaneSide::Bottom => crate::pane_partition::LaneSide::Bottom,
            kettle_config::PreviewLaneSide::Right => crate::pane_partition::LaneSide::Right,
        };
        let resized = if overlay {
            if ws.preview_overlay.is_none() {
                ws.preview_overlay = Some(crate::media::Overlay {
                    pane,
                    origin: ws.mux.active_focus(),
                    control: None,
                });
            }
            self.release_held_buttons(ws, |_| true);
            self.finish_selection_gesture(ws);
            ws.mux.focus_pane(pane);
            ws.mux.close_lane(pane)
        } else {
            ws.mux.open_lane(pane, side)
        };
        // A pane too small for even the strip shows no lane: say so rather
        // than keep one nobody can see, and leave the item unseen. Measured
        // where the pane is, or will be: a preview the user asked for may
        // finish after they switched tabs or zoomed another pane.
        let shown = if overlay {
            self.preview_lane_geometry_of(ws, pane)
                .is_some_and(|geometry| geometry.full)
        } else {
            ws.mux
                .partition_of(pane, self.area(ws), self.layout_style(ws))
                .and_then(|partition| partition.lane)
                .is_some_and(|lane| lane.rect().is_some())
        };
        if !shown && !had_panel {
            ws.preview_panels.remove(&pane);
            self.restore_overlay_origin(ws, pane);
            let resized = ws.mux.close_lane(pane) || resized;
            self.lanes_changed(ws, resized);
            let tr = self.ui_text;
            fire_notify(
                tr.text(kettle_i18n::Text::NotifyTitlePreviewNoRoom),
                tr.text(kettle_i18n::Text::NotifyBodyPreviewNoRoom),
            );
            return;
        }
        if let Some(state) = ws.mux.panes.get_mut(&pane) {
            state.media_shelf.viewed(item);
        }
        if overlay {
            self.focus_preview(ws);
        }
        self.lanes_changed(ws, resized);
    }

    fn restore_overlay_origin(&mut self, ws: &mut WindowState, pane: u64) {
        if let Some(open) = ws.preview_overlay.filter(|open| open.pane == pane) {
            ws.preview_overlay = None;
            if ws.preview_focus.is_some_and(|focus| focus.pane == pane) {
                self.exit_preview_focus(ws);
            }
            if ws.mux.active_focus() == Some(pane)
                && let Some(origin) = open.origin
                && ws.mux.panes.get(&origin).is_some_and(|pane| !pane.closed)
                && self
                    .pane_layout(ws, self.area(ws))
                    .iter()
                    .any(|(pane, _)| *pane == origin)
            {
                ws.mux.focus_pane(origin);
            }
        }
    }

    fn pin_preview(&mut self, ws: &mut WindowState, pane: u64) {
        if !ws.preview_overlay.is_some_and(|open| open.pane == pane) {
            return;
        }
        self.restore_overlay_origin(ws, pane);
        let side = match self.cfg.preview_lane_side {
            kettle_config::PreviewLaneSide::Bottom => crate::pane_partition::LaneSide::Bottom,
            kettle_config::PreviewLaneSide::Right => crate::pane_partition::LaneSide::Right,
        };
        let resized = ws.mux.open_lane(pane, side);
        self.lanes_changed(ws, resized);
    }

    /// After a lane opened, closed, collapsed or changed item: give the
    /// terminals their new size when the geometry moved, and repaint.
    fn lanes_changed(&mut self, ws: &mut WindowState, resized: bool) {
        if resized {
            self.resize_all(ws);
        }
        self.lanes_moved(ws);
        ws.accessibility_pending = true;
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    /// Close the preview, restoring terminal room only for a pinned lane.
    fn close_preview(&mut self, ws: &mut WindowState, pane: u64) {
        self.restore_overlay_origin(ws, pane);
        // Motion banked toward a scroll of the lane goes with it, as do its
        // sharper pixels. A press on it still owns the pointer until its
        // release, which is the lane's.
        ws.lane_wheel.reset();
        ws.lane_crops.remove(&pane);
        self.end_lane_preview(ws, pane);
        ws.lane_playbacks.remove(&pane);
        let had_panel = ws.preview_panels.remove(&pane).is_some();
        let resized = ws.mux.close_lane(pane);
        if had_panel || resized {
            self.lanes_changed(ws, resized);
        }
    }

    /// The stills job a silent preview of what `pane`'s lane shows asks
    /// for: the item, its generation, the job and the longest reply it can
    /// send. `None` unless the lane shows a video with a length, rendered,
    /// whose source it can read again.
    fn lane_preview_job(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Option<(u64, u64, crate::media::JobSpec, usize)> {
        let panel = ws.preview_panels.get(&pane)?;
        let item = preview_item(ws, pane)?;
        lane_previews_item(item, panel)?;
        let info = item.video?;
        let stills = crate::media::preview_stills(&info)?;
        let limit = crate::media::preview_reply_limit(&stills)?;
        let mut spec = item.source.spec.clone();
        spec.kind = kettle_media::JobKind::VideoStills(stills);
        Some((item.id, item.generation, spec, limit))
    }

    /// Start `pane`'s silent preview, or stop the one that is made or plays:
    /// the lane's button, key and action.
    fn toggle_lane_preview(&mut self, ws: &mut WindowState, pane: u64) {
        if ws
            .lane_previews
            .get(&pane)
            .is_some_and(crate::media::LanePreview::active)
        {
            if let Some(preview) = ws.lane_previews.get_mut(&pane)
                && !preview.stop()
            {
                ws.lane_previews.remove(&pane);
                self.media.withdraw_lane_preview(pane);
            }
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = None;
            }
            return self.lanes_changed(ws, false);
        }
        self.start_lane_preview(ws, pane);
    }

    /// Start a silent preview of the video `pane`'s lane shows: from frames
    /// it holds for the item as it is, else from one stills job, which reads
    /// the item's source again. That happens only on the user's own
    /// gesture, never while a control client's request or a Lua script's
    /// action is handled, and never for a file found changed, which a
    /// reload reads again.
    fn start_lane_preview(&mut self, ws: &mut WindowState, pane: u64) {
        if self.ctl_driving || self.lua_driving {
            return;
        }
        let start = crate::media::PreviewStart::User;
        let Some((item, generation, spec, limit)) = self.lane_preview_job(ws, pane) else {
            return;
        };
        let reads_a_file = matches!(spec.input, crate::media::SourceInput::Path { .. });
        if reads_a_file && preview_item(ws, pane).is_some_and(|item| item.source.changed) {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = Some(crate::window_state::LaneNotice::Changed);
            }
            return self.lanes_changed(ws, false);
        }
        let now = std::time::Instant::now();
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            panel.notice = None;
        }
        // One decoder a lane: a video playing there lets its session go,
        // keeping its frame for when the preview stops.
        if let Some(playback) = ws.lane_playbacks.get_mut(&pane) {
            playback.park();
        }
        // Frames held for the item as it is play again without a job.
        if ws
            .lane_previews
            .get_mut(&pane)
            .filter(|preview| preview.serves(item, generation))
            .is_some_and(|preview| preview.replay(now, start))
        {
            return self.lanes_changed(ws, false);
        }
        self.end_lane_preview(ws, pane);
        self.preview_tickets += 1;
        let ticket = self.preview_tickets;
        let deadline = now + crate::media::PREVIEW_FIRST_FRAME_WITHIN;
        let control =
            kettle_media::client::RenderControl::with_deadline(deadline).limit_reply(limit);
        let render = crate::media::LaneRender {
            window: ws.seq,
            pane,
            item,
            generation,
            tile: None,
            page: None,
            preview: Some(ticket),
        };
        let push = crate::media::Push::new(
            crate::media::Requester::Lane(render),
            crate::media::Route {
                pane,
                window: ws.seq,
                verified: true,
            },
            crate::media::Draft {
                key: None,
                title: String::new(),
                provenance: crate::media::Provenance::User,
                inline: None,
                gallery: None,
            },
            spec,
            control.clone(),
        );
        ws.lane_previews.insert(
            pane,
            crate::media::LanePreview::loading(item, generation, ticket, control, now, start),
        );
        self.media
            .admit(crate::media::Sender::LanePreview(pane), deadline, push);
        self.media_tick(ws);
        self.lanes_changed(ws, false);
    }

    /// What opens the video `pane`'s lane shows, from `start_ms`: the item,
    /// its generation and length, and the request, its frames fitted to the
    /// room the lane's picture has now. `None` unless the lane shows a video
    /// with a length, rendered, read from a file it can read again.
    fn lane_play_open(
        &self,
        ws: &WindowState,
        pane: u64,
        start_ms: u64,
    ) -> Option<(u64, u64, u64, kettle_media::PlayOpen)> {
        let panel = ws.preview_panels.get(&pane)?;
        let item = preview_item(ws, pane)?;
        lane_previews_item(item, panel)?;
        let info = item.video?;
        let crate::media::SourceInput::Path {
            path,
            authorization,
        } = &item.source.spec.input
        else {
            return None;
        };
        let edge = |value: f32| {
            if value.is_finite() {
                (value.round() as u32).clamp(1, kettle_media::MAX_PLAY_EDGE)
            } else {
                1
            }
        };
        let room = self
            .preview_lane_geometry_of(ws, pane)
            .map(|geometry| geometry.content)
            .filter(|content| content.2 >= 1.0 && content.3 >= 1.0)
            .map_or((item.size.0 as f32, item.size.1 as f32), |content| {
                (content.2, content.3)
            });
        Some((
            item.id,
            item.generation,
            info.duration_ms,
            kettle_media::PlayOpen {
                source: kettle_media::Source::Path {
                    path: path.clone(),
                    authorization: authorization.clone(),
                },
                max_width: edge(room.0),
                max_height: edge(room.1),
                start_ms: start_ms.min(info.duration_ms),
                max_fps_milli: kettle_media::MAX_PLAY_FPS_MILLI,
                // Its sound, as the user last left it for this item; none
                // on macOS for a container only an external decoder reads,
                // since only Apple's decoder plays sound.
                audio: if apple_reads(info.container) {
                    ws.lane_playbacks
                        .get(&pane)
                        .filter(|playback| playback.serves(item.id, item.generation))
                        .map_or(
                            kettle_media::AudioRequest::On,
                            crate::media::LanePlayback::audio_request,
                        )
                } else {
                    kettle_media::AudioRequest::Off
                },
            },
        ))
    }

    /// The lane's play button, Space while it holds the keyboard, and
    /// `video_play`: stop a silent preview that plays, else play or pause
    /// the video itself, opening it where it stands when it has no session.
    fn toggle_lane_play(&mut self, ws: &mut WindowState, pane: u64) {
        if ws
            .lane_previews
            .get(&pane)
            .is_some_and(crate::media::LanePreview::active)
        {
            return self.toggle_lane_preview(ws, pane);
        }
        let now = std::time::Instant::now();
        let current = preview_item(ws, pane).map(|item| (item.id, item.generation));
        let changed = preview_item(ws, pane).is_some_and(|item| item.source.changed);
        let playback = ws.lane_playbacks.get_mut(&pane).filter(|playback| {
            current.is_some_and(|(item, generation)| playback.serves(item, generation))
        });
        // A control client or a Lua script may pause a video, but only the
        // user plays one, and never from a file found changed, which a
        // reload reads again: resuming reads the file as opening it does.
        let pauses = playback
            .as_ref()
            .is_some_and(|playback| playback.button() == crate::media::PlaybackButton::Pause);
        if !pauses && (self.ctl_driving || self.lua_driving) {
            return;
        }
        if !pauses && changed {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = Some(crate::window_state::LaneNotice::Changed);
            }
            return self.lanes_changed(ws, false);
        }
        let at_ms = match playback {
            Some(playback) => match playback.toggle(now) {
                crate::media::PlaybackToggled::Done => {
                    if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                        panel.notice = None;
                    }
                    return self.lanes_changed(ws, false);
                }
                crate::media::PlaybackToggled::Open { at_ms } => at_ms,
            },
            None => 0,
        };
        self.open_lane_playback(ws, pane, at_ms, true);
    }

    /// The lane's sound button, M while it holds the keyboard, and
    /// `video_mute`: mute the sound of the video playing in the lane, or let
    /// it be heard again, the video playing on. A control client or a Lua
    /// script may mute it, but only the user lets it be heard.
    fn toggle_lane_sound(&mut self, ws: &mut WindowState, pane: u64) {
        let current = preview_item(ws, pane).map(|item| (item.id, item.generation));
        let Some(playback) = ws.lane_playbacks.get_mut(&pane).filter(|playback| {
            current.is_some_and(|(item, generation)| playback.serves(item, generation))
        }) else {
            return;
        };
        if playback.muted() && (self.ctl_driving || self.lua_driving) {
            return;
        }
        if playback.toggle_mute() {
            ws.accessibility_pending = true;
            self.lanes_changed(ws, false);
        }
    }

    /// Open the video `pane`'s lane shows from `at_ms`, playing when
    /// `play`, in a session of its own. Only on the user's own gesture:
    /// never while a control client's request or a Lua script's action is
    /// handled, and never for a file found changed, which a reload reads
    /// again. Its silent preview ends first, and a lane past the most that
    /// play at once gives its session up, the one played least recently.
    fn open_lane_playback(&mut self, ws: &mut WindowState, pane: u64, at_ms: u64, play: bool) {
        use crate::window_state::LaneNotice;
        if self.ctl_driving || self.lua_driving {
            return;
        }
        let Some((item, generation, duration_ms, open)) = self.lane_play_open(ws, pane, at_ms)
        else {
            return;
        };
        let tell = |ws: &mut WindowState, notice: Option<LaneNotice>| {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = notice;
            }
        };
        if preview_item(ws, pane).is_some_and(|item| item.source.changed) {
            tell(ws, Some(LaneNotice::Changed));
            return self.lanes_changed(ws, false);
        }
        let Some(client) = self.startup.media.clone() else {
            tell(ws, Some(LaneNotice::VideoFailed));
            return self.lanes_changed(ws, false);
        };
        self.end_lane_preview(ws, pane);
        // The lane's own session goes first: it is the one replaced.
        if let Some(playback) = ws.lane_playbacks.get_mut(&pane) {
            playback.park();
        }
        self.make_room_for_playback(ws);
        let proxy = self.proxy.clone();
        let wake: Box<dyn Fn() + Send + Sync> = Box::new(move || {
            let _ = proxy.send_event(UserEvent::LanePlayback);
        });
        let now = std::time::Instant::now();
        match client.play(&open, wake) {
            Ok(session) => {
                let session: Box<dyn crate::media::PlaybackSession> = Box::new(session);
                match ws
                    .lane_playbacks
                    .get_mut(&pane)
                    .filter(|playback| playback.serves(item, generation))
                {
                    Some(playback) => playback.reopen(session, open.start_ms, play, now),
                    None => {
                        ws.lane_playbacks.insert(
                            pane,
                            crate::media::LanePlayback::new(
                                item,
                                generation,
                                duration_ms,
                                session,
                                open.start_ms,
                                play,
                                now,
                            ),
                        );
                    }
                }
                // Asked for no sound: only an external decoder plays it.
                if open.audio == kettle_media::AudioRequest::Off
                    && let Some(playback) = ws.lane_playbacks.get_mut(&pane)
                {
                    playback.play_silently();
                }
                tell(ws, None);
            }
            Err(failure) => tell(ws, Some(playback_failure_notice(failure))),
        }
        ws.accessibility_pending = true;
        self.lanes_changed(ws, false);
    }

    /// Park playbacks, least recently played first, until fewer than the
    /// most that play at once have a session, here and in every other
    /// window: each keeps its frame and where it stands.
    fn make_room_for_playback(&mut self, ws: &mut WindowState) {
        loop {
            let mut live = 0;
            let mut oldest: Option<(std::time::Instant, Option<u64>, u64)> = None;
            let mut consider = |touched, window, pane| {
                live += 1;
                if oldest.is_none_or(|(at, _, _)| touched < at) {
                    oldest = Some((touched, window, pane));
                }
            };
            for (&pane, playback) in &ws.lane_playbacks {
                if playback.has_session() {
                    consider(playback.touched, None, pane);
                }
            }
            for (&seq, window) in &self.windows {
                for (&pane, playback) in &window.lane_playbacks {
                    if playback.has_session() {
                        consider(playback.touched, Some(seq), pane);
                    }
                }
            }
            if live < crate::media::MAX_PLAYING {
                return;
            }
            let Some((_, window, pane)) = oldest else {
                return;
            };
            let window = match window {
                None => &mut *ws,
                Some(seq) => match self.windows.get_mut(&seq) {
                    Some(window) => window,
                    None => return,
                },
            };
            if let Some(playback) = window.lane_playbacks.get_mut(&pane) {
                playback.park();
            }
            window.accessibility_pending = true;
            if let Some(handle) = &window.window {
                handle.request_redraw();
            }
        }
    }

    /// An assistive technology's move along `pane`'s bar: to the value it
    /// sets, in seconds, or a step either way, the video opened there and
    /// playing if it played. Only while the lane shows the bar.
    fn seek_lane_by_accessibility(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        request: &accesskit::ActionRequest,
    ) {
        let shown = self
            .preview_lane_projections(ws)
            .into_iter()
            .find(|lane| lane.pane == pane)
            .is_some_and(|lane| {
                lane.scrubber.is_some()
                    && self
                        .preview_lane_geometry(ws, &lane)
                        .is_some_and(|geometry| geometry.scrubber.is_some())
            });
        let Some(playback) = ws.lane_playbacks.get_mut(&pane).filter(|_| shown) else {
            return;
        };
        let at = playback.position_ms();
        let step = LANE_SEEK_STEP.as_millis() as u64;
        let target = match (request.action, &request.data) {
            (AccessibilityAction::SetValue, Some(accesskit::ActionData::NumericValue(seconds)))
                if seconds.is_finite() =>
            {
                (seconds.max(0.0) * 1000.0).round() as u64
            }
            (AccessibilityAction::Increment, _) => at.saturating_add(step),
            (AccessibilityAction::Decrement, _) => at.saturating_sub(step),
            _ => return,
        };
        let (at_ms, play) = playback.seek_target(target);
        self.open_lane_playback(ws, pane, at_ms, play);
    }

    /// The release of a drag along `pane`'s bar: open the video where it
    /// ended, playing if it played.
    fn seek_lane_playback(&mut self, ws: &mut WindowState, pane: u64) {
        let Some((at_ms, play)) = ws
            .lane_playbacks
            .get_mut(&pane)
            .and_then(crate::media::LanePlayback::release_scrub)
        else {
            return;
        };
        self.open_lane_playback(ws, pane, at_ms, play);
    }

    /// Take what each lane's session has: its newest frame and where it is.
    /// One that ended keeps its last frame; one that failed says why.
    fn poll_lane_playbacks(&mut self, ws: &mut WindowState) {
        let budget = kettle_core::GraphicsBudget::previews();
        let mut redraw = false;
        let mut failed = Vec::new();
        let mut reopen = Vec::new();
        for (&pane, playback) in &mut ws.lane_playbacks {
            let before = (playback.button(), playback.notice());
            redraw |= playback.poll(&budget);
            if let Some((at_ms, play)) = playback.take_reopen() {
                reopen.push((pane, at_ms, play));
            }
            let after = (playback.button(), playback.notice());
            if before != after {
                ws.accessibility_pending = true;
                if let Some(crate::media::PlaybackNotice::Failed(failure)) = after.1 {
                    failed.push((pane, failure));
                }
            }
        }
        for (pane, failure) in failed {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = Some(playback_failure_notice(failure));
            }
            // A file found changed is read no more for its item, played or
            // previewed, until a reload replaces it.
            if failure == kettle_media::FailureCode::Changed
                && let Some(playback) = ws.lane_playbacks.get(&pane)
                && let Some(item) = ws
                    .mux
                    .panes
                    .get_mut(&pane)
                    .and_then(|pane| pane.media_shelf.get_mut(playback.item))
                    .filter(|item| item.generation == playback.generation)
            {
                item.source.changed = true;
            }
        }
        // A session Apple's decoder turned down opens again, silent, as the
        // user had it.
        for (pane, at_ms, play) in reopen {
            self.open_lane_playback(ws, pane, at_ms, play);
        }
        if redraw && let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    /// Keep each lane's session while this window's loop runs, pause it
    /// while its lane cannot be seen, and drop a playback whose lane shows
    /// another item. When the loop should come round again to keep them.
    fn tick_lane_playbacks(
        &mut self,
        ws: &mut WindowState,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        if ws.lane_playbacks.is_empty() {
            return None;
        }
        let stale: Vec<u64> = ws
            .lane_playbacks
            .iter()
            .filter(|(pane, playback)| {
                preview_item(ws, **pane)
                    .is_none_or(|item| !playback.serves(item.id, item.generation))
            })
            .map(|(pane, _)| *pane)
            .collect();
        for pane in stale {
            ws.lane_playbacks.remove(&pane);
        }
        let hidden = window_is_render_hidden(ws);
        let visible: std::collections::HashSet<u64> = if hidden {
            std::collections::HashSet::new()
        } else {
            ws.lane_playbacks
                .keys()
                .copied()
                .filter(|&pane| {
                    self.preview_lane_geometry_of(ws, pane)
                        .is_some_and(|geometry| geometry.full && geometry.image.is_some())
                })
                .collect()
        };
        // A drag along a bar that ended without its release, by a menu
        // opening or another press, leaves the video where it was.
        let scrubbing = ws.lane_drag.filter(|drag| drag.scrub).map(|drag| drag.pane);
        let mut live = false;
        for (pane, playback) in &mut ws.lane_playbacks {
            if scrubbing != Some(*pane) {
                playback.cancel_scrub();
            }
            playback.set_hidden(!visible.contains(pane));
            playback.keep();
            live |= playback.has_session();
        }
        let _ = now;
        live.then_some(LANE_PLAYBACK_KEEP)
    }

    /// Let `pane`'s preview go, frames and all: a job still making frames is
    /// cancelled, and one still waiting is withdrawn.
    fn end_lane_preview(&mut self, ws: &mut WindowState, pane: u64) {
        if let Some(mut preview) = ws.lane_previews.remove(&pane) {
            preview.stop();
            self.media.withdraw_lane_preview(pane);
        }
    }

    /// Take a lane's silent preview frames. They stay the lane's, shown in
    /// the poster's place, only while the lane still waits on this job for
    /// the item as it was, read from the source the item came from, and
    /// only a sheet laid out as the job asked; the item and its cards keep
    /// their poster. A failure says why in the lane, and the poster stays.
    fn finish_lane_preview(
        &mut self,
        ws: &mut WindowState,
        render: crate::media::LaneRender,
        ticket: u64,
        spec: crate::media::JobSpec,
        result: Result<kettle_media::RenderOutput, kettle_media::client::RenderError>,
    ) {
        use crate::window_state::LaneNotice;
        use kettle_media::FailureCode;
        use kettle_media::client::RenderError;
        let waited = self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.lane_previews.get(&render.pane))
            .is_some_and(|preview| {
                preview.waits_on() == Some(ticket) && preview.serves(render.item, render.generation)
            });
        if !waited {
            return;
        }
        let fail = |app: &mut Self, ws: &mut WindowState, notice| {
            if let Some(window) = app.window_by_seq(ws, render.window) {
                window.lane_previews.remove(&render.pane);
            }
            app.tell_lane(ws, render.window, render.pane, render.item, notice);
        };
        let output = match result {
            Ok(output) => output,
            // Stopped: its lane already let it go.
            Err(RenderError::Cancelled) => return,
            Err(RenderError::Failure(FailureCode::Changed)) => {
                self.mark_preview_changed(ws, &render);
                return fail(self, ws, LaneNotice::Changed);
            }
            Err(RenderError::Failure(failure)) => {
                return fail(self, ws, preview_failure_notice(failure));
            }
        };
        let rendered = output.rendered;
        let verdict = self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.mux.panes.get(&render.pane))
            .map_or(LaneRenderVerdict::Gone, |pane| {
                lane_render_verdict(pane.media_shelf.items(), &render, &rendered.digest)
            });
        match verdict {
            LaneRenderVerdict::Gone => {
                if let Some(window) = self.window_by_seq(ws, render.window) {
                    window.lane_previews.remove(&render.pane);
                }
                return;
            }
            LaneRenderVerdict::Changed => {
                self.mark_preview_changed(ws, &render);
                return fail(self, ws, LaneNotice::Changed);
            }
            LaneRenderVerdict::Same => {}
        }
        // Frames that came after their two seconds are as late as none.
        let now = std::time::Instant::now();
        if self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.lane_previews.get(&render.pane))
            .is_some_and(|preview| preview.overdue(now))
        {
            return fail(self, ws, LaneNotice::PreviewTimedOut);
        }
        let kettle_media::JobKind::VideoStills(stills) = spec.kind else {
            return fail(self, ws, LaneNotice::PreviewFailed);
        };
        let Some(layout) = crate::media::PreviewLayout::of(&stills, &rendered) else {
            return fail(self, ws, LaneNotice::PreviewFailed);
        };
        let Ok(sheet) =
            self.admit_preview_pixels(ws, rendered.width, rendered.height, rendered.rgba)
        else {
            return fail(self, ws, LaneNotice::PreviewFailed);
        };
        let Some(frames) = crate::media::PreviewFrames::new(sheet, layout) else {
            return fail(self, ws, LaneNotice::PreviewFailed);
        };
        let Some(window) = self.window_by_seq(ws, render.window) else {
            return;
        };
        if window
            .lane_previews
            .get_mut(&render.pane)
            .is_some_and(|preview| preview.ready(ticket, frames, now))
        {
            window.accessibility_pending = true;
            if let Some(handle) = &window.window {
                handle.request_redraw();
            }
        }
    }

    /// Move every lane preview on to `now` and say how long until one next
    /// needs it. A preview goes when its lane closes, shows another item,
    /// or its item changes; one whose frames are late says so; frames play
    /// only while their lane shows its picture in a visible window; and,
    /// with `video-preview-hover` on and motion allowed, the real pointer
    /// resting on a video lane's picture starts a hover loop, once a rest.
    fn tick_lane_previews(
        &mut self,
        ws: &mut WindowState,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        if ws.lane_previews.is_empty() && !self.cfg.video_preview_hover {
            ws.lane_hover = None;
            return None;
        }
        let stale: Vec<u64> = ws
            .lane_previews
            .iter()
            .filter(|(pane, preview)| {
                preview_item(ws, **pane)
                    .is_none_or(|item| !preview.serves(item.id, item.generation))
            })
            .map(|(pane, _)| *pane)
            .collect();
        for pane in stale {
            self.end_lane_preview(ws, pane);
        }
        let hidden = window_is_render_hidden(ws);
        let hovered = self.hovered_lane_picture(ws);
        let at = ws.native_pointer.map(|pointer| (pointer.x, pointer.y));
        ws.lane_hover = next_hover(ws.lane_hover, hovered, at, now);
        let motion = self.cfg.video_preview_hover && self.motion_allowed();
        let visible: std::collections::HashSet<u64> = if hidden {
            std::collections::HashSet::new()
        } else {
            ws.lane_previews
                .keys()
                .copied()
                .filter(|&pane| {
                    self.preview_lane_geometry_of(ws, pane)
                        .is_some_and(|geometry| geometry.full && geometry.image.is_some())
                })
                .collect()
        };
        let mut wake: Option<std::time::Instant> = None;
        let mut redraw = false;
        let mut late = Vec::new();
        for (&pane, preview) in &mut ws.lane_previews {
            let tick = preview.tick(
                now,
                crate::media::PreviewSeen {
                    visible: visible.contains(&pane),
                    hovered: hovered == Some(pane),
                    motion,
                },
            );
            redraw |= tick.redraw;
            if tick.timed_out {
                late.push(pane);
            }
            wake = earliest(wake, preview.wake());
        }
        for pane in late {
            if let Some(item) = ws.lane_previews.remove(&pane).map(|preview| preview.item) {
                self.media.withdraw_lane_preview(pane);
                self.tell_lane(
                    ws,
                    ws.seq,
                    pane,
                    item,
                    crate::window_state::LaneNotice::PreviewTimedOut,
                );
                redraw = true;
            }
        }
        // A rest long enough loops the frames a preview the user started
        // left, once; a hover never makes frames, which would read the file.
        if motion
            && let Some(hover) = ws.lane_hover.filter(|hover| !hover.used)
            && !ws.lane_playbacks.contains_key(&hover.pane)
            && ws
                .lane_previews
                .get(&hover.pane)
                .is_some_and(|preview| !preview.active())
        {
            let due = hover.since + crate::media::PREVIEW_HOVER_DWELL;
            if now >= due {
                ws.lane_hover = Some(crate::window_state::LaneHover {
                    used: true,
                    ..hover
                });
                if let Some(preview) = ws.lane_previews.get_mut(&hover.pane)
                    && preview.replay(now, crate::media::PreviewStart::Hover)
                {
                    wake = earliest(wake, preview.wake());
                    redraw = true;
                }
            } else {
                wake = earliest(wake, Some(due));
            }
        }
        if redraw {
            ws.accessibility_pending = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        wake.map(|at| {
            at.saturating_duration_since(now)
                .max(std::time::Duration::from_millis(1))
        })
    }

    /// The lane whose video picture the real pointer rests on, never a
    /// position a control client moved.
    fn hovered_lane_picture(&self, ws: &WindowState) -> Option<u64> {
        // Nothing under a dialog or a menu, or in a window not drawn, is in
        // reach of the pointer.
        if window_is_render_hidden(ws) || self.pointer_modal_open(ws) || ws.context_menu.is_some() {
            return None;
        }
        let pointer = ws.native_pointer?;
        let (x, y) = (pointer.x as f32, pointer.y as f32);
        let (pane, _, _) = self.preview_lane_at(ws, x, y)?;
        let geometry = self.preview_lane_geometry_of(ws, pane)?;
        let picture = geometry.shown()?;
        let offered = ws
            .preview_panels
            .get(&pane)
            .zip(preview_item(ws, pane))
            .is_some_and(|(panel, item)| lane_previews_item(item, panel).is_some());
        (offered && rect_contains(picture, x, y)).then_some(pane)
    }

    /// What a screen reader hears that `pane`'s lane last did: its notice,
    /// or that a silent preview is being made. A preview that plays is said
    /// by its button's name, never frame by frame.
    fn lane_announcement(&self, ws: &WindowState, pane: u64) -> Option<String> {
        // A video opening says so, as a preview being made does; one that
        // plays is said by its button's name, never frame by frame.
        // A video playing without sound says why, once.
        match ws
            .lane_playbacks
            .get(&pane)
            .and_then(crate::media::LanePlayback::notice)
        {
            Some(crate::media::PlaybackNotice::Opening) => {
                return Some(
                    self.ui_text
                        .text(kettle_i18n::Text::MediaLaneNoticeVideoLoading)
                        .to_string(),
                );
            }
            Some(crate::media::PlaybackNotice::Silent(why)) => {
                return Some(self.ui_text.text(silence_text(why)).to_string());
            }
            _ => {}
        }
        lane_announced(
            ws.lane_previews.get(&pane),
            ws.preview_panels.get(&pane).and_then(|panel| panel.notice),
            &self.ui_text,
        )
    }

    /// Whether Kettle may start motion on its own: `reduce-motion`, and for
    /// `auto` the system's Reduce Motion where it has one; where it has
    /// none, motion is held back.
    fn motion_allowed(&self) -> bool {
        crate::motion::allowed(self.cfg.reduce_motion, || {
            self.system_motion
                .get_or_init(|| crate::motion::SystemMotion::new(self.waker()))
                .allows()
        })
    }

    /// Show `pane`'s item as its source, or rendered again; only an item
    /// whose source the lane holds has the choice.
    fn switch_preview_mode(&mut self, ws: &mut WindowState, pane: u64) {
        use kettle_render::MediaLaneMode as Mode;
        let has_text = preview_item(ws, pane).is_some_and(|item| item.source.text().is_some());
        let Some(panel) = ws.preview_panels.get_mut(&pane).filter(|_| has_text) else {
            return;
        };
        panel.mode = match panel.mode {
            Mode::Rendered => Mode::Source,
            Mode::Source => Mode::Rendered,
        };
        panel.notice = None;
        self.lanes_changed(ws, false);
    }

    /// Show `pane`'s item on the next canvas: the pane's background, white,
    /// then a checkerboard. A raster's or an SVG's is drawn behind its
    /// pixels; a diagram's colors follow its canvas, so it is rendered
    /// again for it, from the same source.
    fn next_preview_canvas(&mut self, ws: &mut WindowState, pane: u64) {
        use kettle_render::MediaCanvas as C;
        let Some((item, panel)) = preview_item(ws, pane).zip(ws.preview_panels.get(&pane)) else {
            return;
        };
        if item.image().is_none() {
            return;
        }
        let next = match chosen_canvas(item, panel) {
            C::Theme => C::White,
            C::White => C::Checker,
            C::Checker => C::Theme,
        };
        let diagram = item.kind == kettle_media::MediaKind::Mermaid;
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            panel.canvas = Some(next);
            panel.notice = None;
        }
        if diagram {
            self.render_preview_again(ws, pane, media_canvas(next));
        }
        self.lanes_changed(ws, false);
    }

    /// Render `pane`'s item again from its source on `canvas`, for its lane.
    /// The result replaces the item's pixels only if the item is still the
    /// one shown, unreplaced, and its source unchanged (see
    /// [`Self::finish_lane_render`]). A file is read again only on the user's
    /// own gesture, never while a control client's request is handled.
    fn render_preview_again(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        canvas: kettle_media::Canvas,
    ) {
        let Some(item) = preview_item(ws, pane) else {
            return;
        };
        let mut spec = item.source.spec.clone();
        let reads_a_file = matches!(spec.input, crate::media::SourceInput::Path { .. });
        // A file found changed is read again only by a reload.
        if reads_a_file && item.source.changed {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = Some(crate::window_state::LaneNotice::Changed);
            }
            return;
        }
        if self.ctl_driving && reads_a_file
            || matches!(spec.input, crate::media::SourceInput::Released)
        {
            if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                panel.notice = Some(crate::window_state::LaneNotice::RenderFailed);
            }
            return;
        }
        // A gallery page asked for and not yet shown is what the lane will
        // show: it is asked for again on this canvas, taking the waiting
        // request's place rather than leaving it to be dropped unsaid.
        let (id, generation) = (item.id, item.generation);
        let waited = ws
            .preview_panels
            .get(&pane)
            .and_then(|panel| page_waited_on(panel, generation))
            .and_then(|ask| item.source.page_spec(ask.page).map(|spec| (ask.page, spec)));
        let page = match waited {
            Some((page, page_spec)) => {
                spec = page_spec;
                self.page_tickets += 1;
                let ask = crate::media::PageAsk {
                    page,
                    ticket: self.page_tickets,
                };
                if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                    panel.page = Some((generation, ask));
                }
                Some(ask)
            }
            None => None,
        };
        spec.canvas = canvas;
        let render = crate::media::LaneRender {
            window: ws.seq,
            pane,
            item: id,
            generation,
            preview: None,
            tile: None,
            page,
        };
        self.render_for_lane(ws, render, spec, crate::window_state::LaneNotice::Rendering);
    }

    /// Ask the worker for `render` of `spec`, for `pane`'s lane, which says
    /// `notice` (what it is rendering) until it comes back. A newer render
    /// for the lane takes the place of one still waiting.
    fn render_for_lane(
        &mut self,
        ws: &mut WindowState,
        render: crate::media::LaneRender,
        spec: crate::media::JobSpec,
        notice: crate::window_state::LaneNotice,
    ) {
        let pane = render.pane;
        let deadline = std::time::Instant::now() + kettle_ctl::show::SHOW_SERVER_DEADLINE;
        let push = crate::media::Push::new(
            crate::media::Requester::Lane(render),
            crate::media::Route {
                pane,
                window: ws.seq,
                verified: true,
            },
            crate::media::Draft {
                key: None,
                title: String::new(),
                provenance: crate::media::Provenance::User,
                inline: None,
                gallery: None,
            },
            spec,
            kettle_media::client::RenderControl::with_deadline(deadline),
        );
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            panel.notice = Some(notice);
        }
        self.media
            .admit(crate::media::Sender::Lane(pane), deadline, push);
        self.media_tick(ws);
    }

    /// Ask for the page of `pane`'s gallery `step` pages from the one asked
    /// for last and not yet shown, else from the one shown. It renders from
    /// the pages kept, never the file, on the canvas shown, and replaces the
    /// shown page once it comes back (see [`Self::finish_lane_render`]);
    /// until then the lane shows its page and says it is rendering. Past the
    /// first or last page nothing happens; back to the page shown, what was
    /// asked for is let go.
    fn page_preview(&mut self, ws: &mut WindowState, pane: u64, step: i32) {
        let Some(item) = preview_item(ws, pane) else {
            return;
        };
        let Some((shown, count)) = item.source.gallery_page() else {
            return;
        };
        let (id, generation) = (item.id, item.generation);
        let asked = ws
            .preview_panels
            .get(&pane)
            .and_then(|panel| page_waited_on(panel, generation))
            .map(|ask| ask.page);
        let Some(page) = gallery_step(shown, count, asked, step) else {
            return;
        };
        // On the canvas the user chose, which a canvas render still waiting
        // would have drawn: this request takes its place.
        let canvas = ws
            .preview_panels
            .get(&pane)
            .map(|panel| media_canvas(chosen_canvas(item, panel)));
        let spec = item.source.page_spec(page).map(|mut spec| {
            if let Some(canvas) = canvas {
                spec.canvas = canvas;
            }
            spec
        });
        let Some(panel) = ws.preview_panels.get_mut(&pane) else {
            return;
        };
        if page == shown {
            panel.page = None;
            panel.notice = None;
            return self.lanes_changed(ws, false);
        }
        let Some(spec) = spec else {
            return;
        };
        self.page_tickets += 1;
        let ask = crate::media::PageAsk {
            page,
            ticket: self.page_tickets,
        };
        panel.page = Some((generation, ask));
        let render = crate::media::LaneRender {
            window: ws.seq,
            pane,
            item: id,
            generation,
            preview: None,
            tile: None,
            page: Some(ask),
        };
        self.render_for_lane(
            ws,
            render,
            spec,
            crate::window_state::LaneNotice::RenderingPage,
        );
        self.lanes_changed(ws, false);
    }

    /// Whether `render` is of the gallery page `pane`'s lane asked for last,
    /// or of the page it shows (drawn again on another canvas), for the item
    /// and generation it shows; true for any other render.
    fn lane_wants(&mut self, ws: &mut WindowState, render: &crate::media::LaneRender) -> bool {
        let Some(ask) = render.page else {
            return true;
        };
        let Some(window) = self.window_by_seq(ws, render.window) else {
            return false;
        };
        let shown = window
            .mux
            .panes
            .get(&render.pane)
            .and_then(|pane| pane.media_shelf.get(render.item))
            .filter(|item| item.generation == render.generation)
            .and_then(|item| item.source.gallery_page())
            .map(|(shown, _)| shown);
        window
            .preview_panels
            .get(&render.pane)
            .is_some_and(|panel| lane_takes_page(panel, render, ask, shown))
    }

    /// Let go of the gallery page request `render` made, if it is the one
    /// its lane still waits on; a request asked again since is not.
    fn forget_lane_page(&mut self, ws: &mut WindowState, render: &crate::media::LaneRender) {
        let Some(ask) = render.page else {
            return;
        };
        if let Some(panel) = self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.preview_panels.get_mut(&render.pane))
            .filter(|panel| {
                panel.item == render.item && page_waited_on(panel, render.generation) == Some(ask)
            })
        {
            panel.page = None;
        }
    }

    /// Copy what `pane`'s lane shows: the item's image, or its source in
    /// source mode, on the clipboard thread.
    fn copy_preview(&mut self, ws: &mut WindowState, pane: u64) {
        use crate::window_state::LaneNotice;
        let Some((item, panel)) = preview_item(ws, pane).zip(ws.preview_panels.get(&pane)) else {
            return;
        };
        let content = match lane_mode(item, panel) {
            kettle_render::MediaLaneMode::Source => item
                .source
                .text_backing()
                .map(|text| crate::media::CopyContent::Text(Arc::clone(text))),
            kettle_render::MediaLaneMode::Rendered => {
                item.image().cloned().map(crate::media::CopyContent::Image)
            }
        };
        let Some(content) = content else {
            return;
        };
        if self.preview_copy.is_none() {
            let proxy = self.proxy.clone();
            self.preview_copy = crate::media::CopyService::with_platform_clipboard(
                std::sync::Arc::new(move || {
                    let _ = proxy.send_event(UserEvent::MediaRendered);
                }),
            );
        }
        let started = self
            .preview_copy
            .as_ref()
            .map_or(crate::media::CopyStarted::Unavailable, |copy| {
                copy.copy(ws.seq, pane, item.id, item.generation, content)
            });
        let notice = match started {
            crate::media::CopyStarted::Started => None,
            crate::media::CopyStarted::Busy => Some(LaneNotice::CopyBusy),
            crate::media::CopyStarted::Unavailable => Some(LaneNotice::CopyFailed),
        };
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            panel.notice = notice;
        }
        self.lanes_changed(ws, false);
    }

    /// Scroll the source the lane under the pointer shows by `steps`: a line
    /// per scrollback line, toward the end for the wheel down; sideways for
    /// a horizontal swipe, or the wheel with Shift held. Over a lane showing
    /// no source it does nothing.
    fn scroll_preview_lane(&mut self, ws: &mut WindowState, steps: input::WheelSteps) {
        let Some((pane, _, _)) = self.preview_lane_at(ws, ws.cursor.x as f32, ws.cursor.y as f32)
        else {
            return;
        };
        let Some(total) = preview_item(ws, pane)
            .zip(ws.preview_panels.get(&pane))
            .filter(|(item, panel)| lane_mode(item, panel) == kettle_render::MediaLaneMode::Source)
            .map(|(item, _)| item.source.text_rows())
        else {
            return;
        };
        let (rows, columns) = source_scroll_by(steps, ws.mods.shift_key());
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            let scroll = scrolled_source(panel.scroll, rows, columns, total);
            if scroll != panel.scroll {
                panel.scroll = scroll;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
        }
    }

    /// Change how `pane`'s lane shows its rendered item: `change` gets the
    /// view, the item's fitted rectangle and the content it shows in.
    /// Whether the lane shows a rendered item to change.
    fn change_preview_view(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        change: impl FnOnce(
            kettle_render::MediaViewport,
            kettle_render::Rect4,
            kettle_render::Rect4,
        ) -> kettle_render::MediaViewport,
    ) -> bool {
        let Some(geometry) = self.preview_lane_geometry_of(ws, pane) else {
            return false;
        };
        let (Some(fit), Some(panel)) = (geometry.fit, ws.preview_panels.get_mut(&pane)) else {
            return false;
        };
        let view = change(panel.view, fit, geometry.content);
        if view != panel.view {
            panel.view = view;
            self.want_lane_crop(ws, pane);
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        true
    }

    /// What shows of a zoomed item may have moved, or another item may show:
    /// each zoomed lane asks again for sharper pixels once it settles.
    fn lanes_moved(&mut self, ws: &mut WindowState) {
        let zoomed: Vec<u64> = ws
            .preview_panels
            .iter()
            .filter(|(_, panel)| !panel.view.is_fit())
            .map(|(pane, _)| *pane)
            .collect();
        let control = self.ctl_driving;
        let now = std::time::Instant::now();
        for pane in zoomed {
            ws.lane_crops.entry(pane).or_default().again(now, control);
        }
    }

    /// `pane`'s lane view changed: ask for sharper pixels once it settles,
    /// for the view of whoever changed it.
    fn want_lane_crop(&mut self, ws: &mut WindowState, pane: u64) {
        let control = self.ctl_driving;
        ws.lane_crops
            .entry(pane)
            .or_default()
            .view_changed(std::time::Instant::now(), control);
    }

    /// Ask for the sharper pixels whose time has come at `now`; how long
    /// until the next is due.
    fn ask_due_lane_crops(
        &mut self,
        ws: &mut WindowState,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        let due: Vec<(u64, bool)> = ws
            .lane_crops
            .iter_mut()
            .filter_map(|(pane, crop)| crop.take_due(now).map(|control| (*pane, control)))
            .collect();
        for (pane, control) in due {
            self.ask_lane_crop(ws, pane, control);
        }
        ws.lane_crops
            .values()
            .filter_map(crate::media::LaneCrop::due)
            .min()
            .map(|at| {
                at.saturating_duration_since(now)
                    .max(std::time::Duration::from_millis(1))
            })
    }

    /// Ask the worker for the part of `pane`'s zoomed item in view at the
    /// size it shows, unless the lane's own pixels, or the sharper ones it
    /// holds, show it well enough; with nothing sharper needed, let those go.
    /// A file is read only for the user's own view: never when a control
    /// client changed it last (`control`), nor once the file changed since
    /// the item was rendered, until a reload.
    fn ask_lane_crop(&mut self, ws: &mut WindowState, pane: u64, control: bool) {
        // Whatever this asks, or finds no need to, a render asked for
        // before is no longer wanted.
        if let Some(crop) = ws.lane_crops.get_mut(&pane) {
            crop.asked = None;
        }
        let Some(geometry) = self.preview_lane_geometry_of(ws, pane) else {
            return;
        };
        let Some(item) = preview_item(ws, pane) else {
            return;
        };
        let (Some(placed), Some(visible), Some(layout), Some(held)) = (
            geometry.image,
            geometry.visible(),
            item.layout,
            item.image().map(|image| (image.width, image.height)),
        ) else {
            return;
        };
        let plan = crate::media::plan_crop(
            item.kind,
            &layout,
            held,
            (f64::from(placed.2), f64::from(placed.3)),
            visible,
            item.source.spec.target.scale,
        );
        let (id, generation, changed) = (item.id, item.generation, item.source.changed);
        let mut spec = item.source.spec.clone();
        let crop = ws.lane_crops.entry(pane).or_default();
        let Some(target) = plan else {
            crop.tile = None;
            return;
        };
        let reads_file = matches!(spec.input, crate::media::SourceInput::Path { .. });
        if (reads_file && (changed || control))
            || matches!(spec.input, crate::media::SourceInput::Released)
            || crop.tile.as_ref().is_some_and(|tile| {
                tile.serves(id, generation, spec.canvas) && tile.suffices(visible, &target)
            })
        {
            return;
        }
        self.crop_tickets += 1;
        let ticket = self.crop_tickets;
        crop.asked = Some(ticket);
        spec.target = target;
        let render = crate::media::LaneRender {
            window: ws.seq,
            pane,
            item: id,
            generation,
            preview: None,
            tile: Some(ticket),
            page: None,
        };
        let deadline = std::time::Instant::now() + kettle_ctl::show::SHOW_SERVER_DEADLINE;
        let push = crate::media::Push::new(
            crate::media::Requester::Lane(render),
            crate::media::Route {
                pane,
                window: ws.seq,
                verified: true,
            },
            crate::media::Draft {
                key: None,
                title: String::new(),
                provenance: crate::media::Provenance::User,
                inline: None,
                gallery: None,
            },
            spec,
            kettle_media::client::RenderControl::with_deadline(deadline),
        );
        self.media
            .admit(crate::media::Sender::LaneTile(pane), deadline, push);
        self.media_tick(ws);
    }

    /// Zoom `pane`'s rendered item by `factor` about the content's center.
    fn zoom_preview(&mut self, ws: &mut WindowState, pane: u64, factor: f64) {
        self.change_preview_view(ws, pane, |view, fit, content| {
            view.zoomed(factor, fit, content)
        });
    }

    /// Show `pane`'s rendered item fitted to its lane again.
    fn fit_preview(&mut self, ws: &mut WindowState, pane: u64) {
        self.change_preview_view(ws, pane, |_, _, _| kettle_render::MediaViewport::FIT);
    }

    /// The wheel over the lane under the pointer: over its rendered item it
    /// zooms at the pointer with Cmd held on macOS, Ctrl elsewhere, and pans
    /// otherwise; over its source it scrolls. A lane showing neither takes
    /// the wheel and does nothing with it.
    fn wheel_over_lane(&mut self, ws: &mut WindowState, delta: &winit::event::MouseScrollDelta) {
        let pointer = (ws.cursor.x as f32, ws.cursor.y as f32);
        let Some((pane, _, _)) = self.preview_lane_at(ws, pointer.0, pointer.1) else {
            return;
        };
        let wheel = lane_wheel(
            delta,
            lane_zoom_modifier(ws.mods),
            ws.mods.shift_key(),
            self.menu_cell(ws),
            self.cfg.scroll_multiplier,
        );
        let rendered = self.change_preview_view(ws, pane, |view, fit, content| match wheel {
            LaneWheel::Zoom(factor) => view.zoomed_at(factor, pointer, fit, content),
            LaneWheel::Pan(by) => view.panned(by, fit, content),
        });
        if rendered {
            ws.lane_wheel.reset();
            return;
        }
        let steps = ws.lane_wheel.feed(delta, self.cfg.scroll_multiplier);
        self.scroll_preview_lane(ws, steps);
    }

    /// Whole wheel `steps` a control client sent over the lane under the
    /// pointer: a rendered item zooms or pans by them as by the wheel (see
    /// [`lane_wheel_steps`]); a source scrolls.
    fn wheel_steps_over_lane(&mut self, ws: &mut WindowState, steps: input::WheelSteps) {
        let Some((pane, _, _)) = self.preview_lane_at(ws, ws.cursor.x as f32, ws.cursor.y as f32)
        else {
            return;
        };
        let pointer = (ws.cursor.x as f32, ws.cursor.y as f32);
        let wheel = lane_wheel_steps(
            steps,
            lane_zoom_modifier(ws.mods),
            ws.mods.shift_key(),
            self.menu_cell(ws),
        );
        let rendered = self.change_preview_view(ws, pane, |view, fit, content| match wheel {
            LaneWheel::Zoom(factor) => view.zoomed_at(factor, pointer, fit, content),
            LaneWheel::Pan(by) => view.panned(by, fit, content),
        });
        if !rendered {
            self.scroll_preview_lane(ws, steps);
        }
    }

    /// A pinch over the lane under the pointer zooms its rendered item at
    /// the pointer.
    fn pinch_over_lane(&mut self, ws: &mut WindowState, delta: f64) {
        let pointer = (ws.cursor.x as f32, ws.cursor.y as f32);
        if let Some((pane, _, _)) = self.preview_lane_at(ws, pointer.0, pointer.1) {
            let factor = pinch_zoom(delta);
            self.change_preview_view(ws, pane, |view, fit, content| {
                view.zoomed_at(factor, pointer, fit, content)
            });
        }
    }

    /// Follow the pointer for a press on a lane's rendered item: past a few
    /// logical pixels from the press it pans the item. Whether a press of
    /// the lane's is held, which then owns the pointer's motion.
    fn drag_preview_lane(&mut self, ws: &mut WindowState) -> bool {
        let Some(mut drag) = ws.lane_drag else {
            return false;
        };
        // A menu or dialog that opened since owns the pointer.
        if ws.context_menu.is_some() || self.non_search_modal_open(ws) {
            ws.lane_drag = None;
            return false;
        }
        let at = (ws.cursor.x, ws.cursor.y);
        // A drag along a playing video's bar moves where it says the video
        // is; the release opens it there.
        if drag.scrub {
            let fraction = self
                .preview_lane_geometry_of(ws, drag.pane)
                .and_then(|geometry| geometry.scrub_at(at.0 as f32));
            if let (Some(fraction), Some(playback)) =
                (fraction, ws.lane_playbacks.get_mut(&drag.pane))
            {
                playback.scrub(fraction, std::time::Instant::now());
                self.lanes_changed(ws, false);
            }
            ws.lane_drag = Some(drag);
            return true;
        }
        let scale = ws
            .window
            .as_ref()
            .map_or(1.0, |window| window.scale_factor());
        if !drag.panning && past_drag_slop(drag.from, at, scale) {
            drag.panning = true;
        }
        if drag.panning {
            let by = (at.0 - drag.last.0, at.1 - drag.last.1);
            drag.last = at;
            self.change_preview_view(ws, drag.pane, |view, fit, content| {
                view.panned(by, fit, content)
            });
        }
        ws.lane_drag = Some(drag);
        true
    }

    /// The release of a press a lane took for a drag: a drag along a playing
    /// video's bar opens the video where it ended; a pan is already done.
    fn end_lane_drag(&mut self, ws: &mut WindowState, drag: crate::window_state::LaneDrag) {
        if drag.scrub {
            self.seek_lane_playback(ws, drag.pane);
        }
    }

    /// Follow the pointer for a press on a lane's edge: the lane takes the
    /// share of its pane the pointer leaves it, repainting at once and
    /// resizing the PTYs at most every [`LANE_RESIZE_PTY_INTERVAL`]. Whether
    /// such a press is held, which then owns the pointer's motion.
    ///
    /// [`LANE_RESIZE_PTY_INTERVAL`]: crate::window_state::LANE_RESIZE_PTY_INTERVAL
    fn resize_preview_lane(&mut self, ws: &mut WindowState) -> bool {
        let Some(mut resize) = ws.lane_resize else {
            return false;
        };
        // A menu or dialog that opened since owns the pointer.
        if ws.context_menu.is_some() || self.non_search_modal_open(ws) {
            self.end_lane_resize(ws);
            return false;
        }
        let (area, style) = (self.area(ws), self.layout_style(ws));
        let pointer = (ws.cursor.x as f32, ws.cursor.y as f32);
        if ws.mux.drag_lane_edge(resize.pane, area, style, pointer) {
            let now = std::time::Instant::now();
            if now.duration_since(resize.resized) >= crate::window_state::LANE_RESIZE_PTY_INTERVAL {
                self.resize_all(ws);
                resize.resized = now;
                resize.pending = false;
            } else {
                resize.pending = true;
            }
            self.lanes_changed(ws, false);
        }
        ws.lane_resize = Some(resize);
        true
    }

    /// End a lane's edge drag, resizing the PTYs for where it ended.
    fn end_lane_resize(&mut self, ws: &mut WindowState) {
        if ws.lane_resize.take().is_some_and(|resize| resize.pending) {
            self.resize_all(ws);
        }
    }

    /// Resize the PTYs for a lane's edge drag that has waited its interval
    /// at `now`; how long until one that has not is due.
    fn flush_lane_resize(
        &mut self,
        ws: &mut WindowState,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        let resize = ws.lane_resize.as_mut().filter(|resize| resize.pending)?;
        let due = resize.resized + crate::window_state::LANE_RESIZE_PTY_INTERVAL;
        if due > now {
            return Some(due - now);
        }
        resize.resized = now;
        resize.pending = false;
        self.resize_all(ws);
        None
    }

    /// The cursor over a lane: resize arrows over its edge or while it is
    /// dragged, a pointing hand over a control, a hand over a rendered item
    /// that zooms, grabbing while it pans, and the arrow elsewhere in it.
    fn lane_cursor_icon(&self, ws: &WindowState) -> Option<CursorIcon> {
        let edge_icon = |pane: u64| match ws.mux.lane(pane).map(|lane| lane.side) {
            Some(crate::pane_partition::LaneSide::Right) => CursorIcon::ColResize,
            _ => CursorIcon::RowResize,
        };
        if let Some(resize) = ws.lane_resize {
            return Some(edge_icon(resize.pane));
        }
        if ws.lane_drag.is_some_and(|drag| drag.panning) {
            return Some(CursorIcon::Grabbing);
        }
        let (x, y) = (ws.cursor.x as f32, ws.cursor.y as f32);
        let (pane, rect, collapsed) = self.preview_lane_at(ws, x, y)?;
        let geometry = self
            .preview_lane_panel(ws, pane, rect, collapsed)
            .and_then(|lane| self.preview_lane_geometry(ws, &lane));
        Some(
            match geometry
                .as_ref()
                .and_then(|geometry| geometry.hit_test(x, y))
            {
                Some(kettle_render::MediaLaneHit::Resize) => edge_icon(pane),
                Some(kettle_render::MediaLaneHit::Inside) => match geometry {
                    Some(geometry)
                        if geometry.fit.is_some() && rect_contains(geometry.content, x, y) =>
                    {
                        CursorIcon::Grab
                    }
                    _ => CursorIcon::Default,
                },
                Some(_) => CursorIcon::Pointer,
                None => CursorIcon::Default,
            },
        )
    }

    /// Give the focused pane's preview lane the keyboard, while it shows its
    /// item expanded with room for it: keys then move, zoom, fit or copy
    /// what it shows, and reach nothing else, until Esc. An input method's
    /// composition ends, and it stays off meanwhile.
    fn focus_preview(&mut self, ws: &mut WindowState) {
        let Some(pane) = ws.mux.active_focus() else {
            return;
        };
        let Some(item) = ws.preview_panels.get(&pane).map(|panel| panel.item) else {
            return;
        };
        if !self
            .preview_lane_geometry_of(ws, pane)
            .is_some_and(|geometry| geometry.full)
        {
            return;
        }
        ws.preview_focus = Some(crate::media::PreviewFocus { pane, item });
        end_modal_composition(ws);
        if let Some(window) = &ws.window {
            window.set_ime_allowed(false);
        }
        self.lanes_changed(ws, false);
    }

    /// Release a pinned lane's keyboard. A viewer remains modal until closed,
    /// including across focus loss or a refused file drop.
    fn exit_preview_focus(&mut self, ws: &mut WindowState) {
        if ws.preview_overlay.is_some() {
            return;
        }
        if ws.preview_focus.take().is_none() {
            return;
        }
        end_modal_composition(ws);
        if let Some(window) = &ws.window {
            window.set_ime_allowed(true);
        }
        self.lanes_changed(ws, false);
    }

    /// A press anywhere but on the lane holding the keyboard gives the
    /// keyboard back first, then goes where it would.
    fn leave_preview_focus_for_press(&mut self, ws: &mut WindowState) {
        if ws.preview_overlay.is_some() {
            return;
        }
        let Some(focus) = ws.preview_focus else {
            return;
        };
        let (x, y) = (ws.cursor.x as f32, ws.cursor.y as f32);
        if self.preview_lane_at(ws, x, y).map(|(pane, _, _)| pane) != Some(focus.pane) {
            self.exit_preview_focus(ws);
        }
    }

    /// Whether a preview lane holds the keyboard in the window `pane` is in.
    fn preview_holds_keyboard(&self, ws: &WindowState, pane: u64) -> bool {
        if ws.mux.panes.contains_key(&pane) {
            return ws.preview_focus.is_some();
        }
        self.windows
            .values()
            .find(|window| window.mux.panes.contains_key(&pane))
            .is_some_and(|window| window.preview_focus.is_some())
    }

    /// Keep the keyboard with a lane only while it can use it: its pane
    /// focused, showing the same item expanded with room, and no other modal
    /// open over it. Run on each pass of the event loop.
    fn check_preview_focus(&mut self, ws: &mut WindowState) {
        let Some(focus) = ws.preview_focus else {
            return;
        };
        let usable = top_modal(ws) == Some(KeyModal::Preview)
            && ws.mux.active_focus() == Some(focus.pane)
            && ws
                .preview_panels
                .get(&focus.pane)
                .is_some_and(|panel| panel.item == focus.item)
            && self
                .preview_lane_geometry_of(ws, focus.pane)
                .is_some_and(|geometry| geometry.full);
        if !usable {
            if ws
                .preview_overlay
                .is_some_and(|open| open.pane == focus.pane)
            {
                self.close_preview(ws, focus.pane);
            } else {
                self.exit_preview_focus(ws);
            }
        }
    }

    /// A key while a lane holds the keyboard: Esc gives it back, arrows move
    /// the picture or scroll a source, Page Up and Page Down show a gallery's
    /// diagram before or after, `+`, `-` and `0` zoom and fit, and `c`
    /// copies; every other key does nothing. A held key that acts once a
    /// press does not repeat.
    fn handle_viewer_key(&mut self, ws: &mut WindowState, key: &Key, repeat: bool) -> bool {
        use crate::media::ViewerKey;
        let Some(open) = ws.preview_overlay else {
            return false;
        };
        let Some(action) = crate::media::viewer_key(key, held_modifiers(ws)) else {
            return false;
        };
        if repeat && !matches!(action, ViewerKey::Focus(_)) {
            return true;
        }
        match action {
            ViewerKey::Focus(forward) => {
                let shown: Vec<u64> = self
                    .shown_preview_controls(ws, open.pane)
                    .into_iter()
                    .map(|(part, _, _)| part)
                    .collect();
                if let Some(open) = &mut ws.preview_overlay {
                    open.step_control(&shown, forward);
                }
                self.lanes_changed(ws, false);
            }
            ViewerKey::Pin => self.pin_preview(ws, open.pane),
            ViewerKey::Activate => {
                let hit = open.control.and_then(|part| {
                    self.shown_preview_controls(ws, open.pane)
                        .into_iter()
                        .find(|(at, _, _)| *at == part)
                        .map(|(_, _, hit)| hit)
                });
                if hit == Some(kettle_render::MediaLaneHit::Scrub)
                    && key == &Key::Named(NamedKey::Space)
                {
                    self.toggle_lane_play(ws, open.pane);
                } else if let Some(hit) = hit {
                    self.act_on_preview(ws, open.pane, hit);
                } else if open.control.is_none() && key == &Key::Named(NamedKey::Space) {
                    return false;
                }
            }
        }
        true
    }

    fn preview_focus_key(&mut self, ws: &mut WindowState, key: &Key, repeat: bool) {
        if self.handle_viewer_key(ws, key, repeat) {
            return;
        }
        use crate::media::PreviewKey as K;
        let Some(focus) = ws.preview_focus else {
            return;
        };
        let pane = focus.pane;
        let action = crate::media::preview_key(key, held_modifiers(ws));
        if repeat && action.once() {
            return;
        }
        let source = preview_item(ws, pane)
            .zip(ws.preview_panels.get(&pane))
            .is_some_and(|(item, panel)| {
                lane_mode(item, panel) == kettle_render::MediaLaneMode::Source
            });
        // A video playing in the lane, paused in place, or stopped where it
        // stood shows its frame, which never pans: left and right step it.
        let playing = preview_item(ws, pane).is_some_and(|item| {
            ws.lane_playbacks
                .get(&pane)
                .is_some_and(|playback| playback.serves(item.id, item.generation))
        });
        match action {
            K::Exit if ws.preview_overlay.is_some() => self.close_preview(ws, pane),
            K::Exit => self.exit_preview_focus(ws),
            K::Move(right, 0) if playing && !source => {
                let step = LANE_SEEK_STEP.as_millis() as u64;
                if let Some(playback) = ws.lane_playbacks.get_mut(&pane) {
                    let at = playback.position_ms();
                    let target = if right < 0 {
                        at.saturating_sub(step)
                    } else {
                        at.saturating_add(step)
                    };
                    let (at_ms, play) = playback.seek_target(target);
                    self.open_lane_playback(ws, pane, at_ms, play);
                }
            }
            K::Move(right, down) if source => {
                if let Some(total) = preview_item(ws, pane).map(|item| item.source.text_rows())
                    && let Some(panel) = ws.preview_panels.get_mut(&pane)
                {
                    panel.scroll = scrolled_source(panel.scroll, down, right, total);
                }
            }
            K::Move(right, down) => {
                // Three cells a press, as a wheel's notch pans; the picture
                // moves the other way, showing what lies toward the arrow.
                let cell = self.menu_cell(ws);
                let step = f64::from(input::LINES_PER_NOTCH);
                let by = (
                    -f64::from(right) * step * f64::from(cell.0),
                    -f64::from(down) * step * f64::from(cell.1),
                );
                self.change_preview_view(ws, pane, |view, fit, content| {
                    view.panned(by, fit, content)
                });
            }
            K::ZoomIn => self.zoom_preview(ws, pane, kettle_render::MEDIA_ZOOM_STEP),
            K::ZoomOut => self.zoom_preview(ws, pane, 1.0 / kettle_render::MEDIA_ZOOM_STEP),
            K::Fit if source => {
                if let Some(panel) = ws.preview_panels.get_mut(&pane) {
                    panel.scroll = (0, 0);
                }
            }
            K::Fit => self.fit_preview(ws, pane),
            K::Page(step) => self.page_preview(ws, pane, step),
            K::Copy => self.copy_preview(ws, pane),
            K::Play => self.toggle_lane_play(ws, pane),
            K::Mute => self.toggle_lane_sound(ws, pane),
            K::Swallow => {}
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    /// Collapse `pane`'s lane to its strip, or expand it.
    fn toggle_preview(&mut self, ws: &mut WindowState, pane: u64) {
        let Some(lane) = ws.mux.lane(pane) else {
            return;
        };
        let resized = ws.mux.set_lane_expanded(pane, !lane.expanded);
        self.lanes_changed(ws, resized);
    }

    /// Take a primary press on a settled inline card, before focus, links,
    /// selection and mouse reporting, so nothing behind it gets the press.
    /// Shift passes the press on, as does a card that only just appeared.
    fn press_card(&mut self, ws: &mut WindowState, px: f32, py: f32, bcode: u8) -> bool {
        if !matches!(bcode, 0 | 2) || ws.mods.shift_key() {
            return false;
        }
        let card = ws
            .renderer
            .as_ref()
            .and_then(|renderer| renderer.card_at(px, py));
        let Some(card) = ws.card_sightings.settled(card, std::time::Instant::now()) else {
            return false;
        };
        if bcode == 2 {
            // A right-press on a card opens the card's menu, not the
            // terminal's; its release is Kettle's own gesture's.
            return self.open_card_menu(ws, card, (px, py));
        }
        ws.card_press = Some(card);
        true
    }

    /// End a press a card took. Released over the same card, it opens the
    /// card's item in the viewer; anywhere else, or once a dialog or the
    /// viewer has opened over it, it is dropped. Either way the terminal saw
    /// neither the press nor the release.
    fn release_card(&mut self, ws: &mut WindowState, px: f32, py: f32, bcode: u8) -> bool {
        if bcode != 0 {
            return false;
        }
        let Some((pane, nonce)) = ws.card_press.take() else {
            return false;
        };
        let over = ws
            .renderer
            .as_ref()
            .and_then(|renderer| renderer.card_at(px, py));
        let covered = self.pointer_modal_open(ws);
        if card_release_opens((pane, nonce), over, covered) {
            self.open_card(ws, pane, nonce);
        }
        true
    }

    /// Open the item `pane`'s card `nonce` shows in the pane's preview lane,
    /// for a click, a hint or assistive technology. Nothing opens while a
    /// dialog or a menu owns the pointer, or once the card's item has left
    /// the shelf.
    fn open_card(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        nonce: kettle_core::InlineNonce,
    ) -> bool {
        if self.pointer_modal_open(ws) {
            return false;
        }
        let Some(item) = self.media.cards.item(pane, nonce) else {
            return false;
        };
        if !ws
            .mux
            .panes
            .get(&pane)
            .is_some_and(|state| state.media_shelf.items().iter().any(|it| it.id == item))
        {
            return false;
        }
        self.close_all_modals(ws);
        self.show_media_item(ws, pane, item);
        // Opening a card is what the tip taught.
        self.end_cards_tip(ws);
        true
    }

    /// End the tip that a click opens a card, and take it off its card in
    /// whichever window holds that pane.
    fn end_cards_tip(&mut self, ws: &mut WindowState) {
        let Some(pane) = self.cards_tip.end() else {
            return;
        };
        for window in std::iter::once(&mut *ws).chain(self.windows.values_mut()) {
            if let Some(state) = window.mux.panes.get_mut(&pane) {
                state.inline_cards.set_tip(None);
                if let Some(handle) = &window.window {
                    handle.request_redraw();
                }
            }
        }
    }

    /// Open the menu of the card `nonce` in `pane` at (`px`, `py`): open its
    /// item in Kettle, and open a copy of it in the permitted image viewer,
    /// or of a video in the permitted video player, where this platform has
    /// one. False when the card's item has left the shelf, so the press goes
    /// where it would have.
    fn open_card_menu(
        &mut self,
        ws: &mut WindowState,
        (pane, nonce): (u64, kettle_core::InlineNonce),
        (px, py): (f32, f32),
    ) -> bool {
        let Some(item) = self.media.cards.item(pane, nonce) else {
            return false;
        };
        let Some((generation, outside)) = ws.mux.panes.get(&pane).and_then(|state| {
            state
                .media_shelf
                .items()
                .iter()
                .find(|it| it.id == item)
                .map(|it| (it.generation, crate::media::Outside::of(it)))
        }) else {
            return false;
        };
        let target = MediaTarget {
            pane,
            nonce,
            item,
            generation,
        };
        let tr = self.ui_text;
        let mut items = vec![ContextMenuItem::Media {
            label: tr.text(kettle_i18n::Text::MenuOpenInKettle),
            target,
            action: MediaMenuAction::View,
        }];
        if let Some(outside) = outside {
            items.push(ContextMenuItem::Media {
                label: outside.label(&tr),
                target,
                action: MediaMenuAction::OpenOutside(outside),
            });
        }
        self.show_context_menu(ws, items, px, py);
        true
    }

    /// Act on a card menu row, if the card still shows the item the menu
    /// named: open it as a click would, or a copy of it outside Kettle.
    fn act_on_media(&mut self, ws: &mut WindowState, target: MediaTarget, action: MediaMenuAction) {
        if self.media.cards.item(target.pane, target.nonce) != Some(target.item) {
            return;
        }
        let Some(item) = ws.mux.panes.get(&target.pane).and_then(|state| {
            state
                .media_shelf
                .items()
                .iter()
                .find(|it| it.id == target.item && it.generation == target.generation)
        }) else {
            return;
        };
        match action {
            MediaMenuAction::View => {
                self.open_card(ws, target.pane, target.nonce);
            }
            MediaMenuAction::OpenOutside(outside) => self.open_item_outside(item, outside),
        }
    }

    /// The item `pane`'s lane shows, if it has one and the item is still
    /// on the shelf.
    fn preview_item<'a>(
        &self,
        ws: &'a WindowState,
        pane: u64,
    ) -> Option<&'a crate::media::ShelfItem> {
        let panel = ws.preview_panels.get(&pane)?;
        ws.mux
            .panes
            .get(&pane)?
            .media_shelf
            .items()
            .iter()
            .find(|it| it.id == panel.item)
    }

    /// What `pane`'s lane offers to open its item in outside Kettle: none
    /// when this platform has nothing permitted for it, or an image's pixels
    /// were let go. A video opens from its file, not its poster.
    fn preview_opens_outside(&self, ws: &WindowState, pane: u64) -> Option<crate::media::Outside> {
        let item = self.preview_item(ws, pane)?;
        let outside = crate::media::Outside::of(item)?;
        (matches!(outside, crate::media::Outside::Video(_)) || item.image().is_some())
            .then_some(outside)
    }

    /// Open `pane`'s lane item outside Kettle, when it offers to.
    fn open_preview_outside(&self, ws: &WindowState, pane: u64) {
        let Some(outside) = self.preview_opens_outside(ws, pane) else {
            return;
        };
        if let Some(item) = self.preview_item(ws, pane) {
            self.open_item_outside(item, outside);
        }
    }

    /// Open a copy of `item` `outside`: a PNG of an image's pixels in the
    /// image viewer, or a private copy of a video's file in the video
    /// player. A notice says why if it does not open.
    fn open_item_outside(&self, item: &crate::media::ShelfItem, outside: crate::media::Outside) {
        let tr = self.ui_text;
        let video = matches!(outside, crate::media::Outside::Video(_));
        let failed = move |why: crate::media::OpenFailure| {
            let (title, body) = why.notice(video);
            fire_notify(tr.text(title), tr.text(body));
        };
        match outside {
            crate::media::Outside::Image(viewer) => match item.image() {
                Some(image) => crate::media::open_externally(
                    std::sync::Arc::clone(&self.viewer_copies),
                    image.clone(),
                    viewer,
                    failed,
                ),
                // Its pixels were let go to stay within the budget.
                None => failed(crate::media::OpenFailure::Copy),
            },
            crate::media::Outside::Video(player) => match crate::media::VideoSource::of(item) {
                Some(source) => crate::media::open_video(
                    std::sync::Arc::clone(&self.video_copies),
                    source,
                    player,
                    failed,
                ),
                // Shown from no file Kettle can name: nothing to copy.
                None => failed(crate::media::OpenFailure::Changed),
            },
        }
    }

    /// The cards on screen that assistive technology can reach, in paint
    /// order: each placement's instance, where it is, and the shelf item it
    /// shows. None while a dialog or a menu covers them.
    fn accessible_cards<'a>(
        &self,
        ws: &'a WindowState,
    ) -> Vec<(u64, kettle_render::PaintedCard, &'a crate::media::ShelfItem)> {
        if self.pointer_modal_open(ws) {
            return Vec::new();
        }
        let Some(renderer) = ws.renderer.as_ref() else {
            return Vec::new();
        };
        // The last frame may still show a tab or pane that has since gone
        // from view; only what the layout shows now is reachable.
        let shown: Vec<u64> = ws
            .mux
            .leaves(ws.mux.active, self.area(ws))
            .into_iter()
            .map(|(pane, _)| pane)
            .collect();
        renderer
            .painted_cards()
            .iter()
            .filter(|card| shown.contains(&card.pane))
            .filter_map(|card| {
                let instance = ws.card_sightings.instance(card)?;
                let item = self.media.cards.item(card.pane, card.nonce)?;
                let item = ws
                    .mux
                    .panes
                    .get(&card.pane)?
                    .media_shelf
                    .items()
                    .iter()
                    .find(|it| it.id == item)?;
                Some((instance, *card, item))
            })
            .collect()
    }

    /// The viewer's detail line for a card's item, as assistive technology
    /// hears it: kind, size and sender.
    fn card_accessibility_detail(&self, item: &crate::media::ShelfItem) -> String {
        let (kind, sender) = self.media_item_kind_and_sender(item);
        format!(
            "{} · {}",
            media_item_detail(self.ui_text, kind, item),
            sender.text
        )
    }

    /// Show the shelf item `step` places along from the one `pane`'s lane
    /// shows, stopping at either end.
    fn step_preview(&mut self, ws: &mut WindowState, pane: u64, step: isize) {
        let Some(panel) = ws.preview_panels.get(&pane).copied() else {
            return;
        };
        let Some(items) = ws
            .mux
            .panes
            .get(&pane)
            .map(|state| state.media_shelf.items())
        else {
            return;
        };
        let Some(at) = items.iter().position(|item| item.id == panel.item) else {
            return;
        };
        let Some(next) = at
            .checked_add_signed(step)
            .and_then(|index| items.get(index))
            .map(|item| item.id)
        else {
            return;
        };
        self.show_media_item(ws, pane, next);
    }

    /// Close every lane that has nothing to show: its pane closed or left
    /// this window, or its item left the shelf. A lane without a panel, or a
    /// panel without a lane, goes too. Run on each pass of the event loop.
    fn prune_previews(&mut self, ws: &mut WindowState) {
        let before = ws.preview_panels.len();
        let live: Vec<u64> = ws
            .preview_panels
            .keys()
            .copied()
            .filter(|pane| {
                (ws.mux.lane(*pane).is_some()
                    || ws.preview_overlay.is_some_and(|open| open.pane == *pane))
                    && ws.mux.panes.get(pane).is_some_and(|state| !state.closed)
                    && self.preview_item(ws, *pane).is_some()
            })
            .collect();
        ws.preview_panels.retain(|pane, _| live.contains(pane));
        if let Some(open) = ws.preview_overlay.filter(|open| !live.contains(&open.pane)) {
            self.restore_overlay_origin(ws, open.pane);
        }
        ws.lane_crops.retain(|pane, _| live.contains(pane));
        let gone: Vec<u64> = ws
            .lane_previews
            .keys()
            .copied()
            .filter(|pane| !live.contains(pane))
            .collect();
        for pane in gone {
            self.end_lane_preview(ws, pane);
        }
        ws.lane_playbacks.retain(|pane, _| live.contains(pane));
        let resized = ws.mux.retain_lanes(|pane| live.contains(&pane));
        if resized || ws.preview_panels.len() != before {
            self.lanes_changed(ws, resized);
        }
    }

    /// The active tab's preview lanes, projected for painting: each pane
    /// whose lane has room to show more than a badge.
    fn preview_lane_projections(&self, ws: &WindowState) -> Vec<kettle_render::MediaLanePanel> {
        self.pane_layout(ws, self.area(ws))
            .into_iter()
            .filter_map(|(pane, partition)| {
                let (rect, collapsed) = self.preview_placement(ws, pane, partition)?;
                self.preview_lane_panel(ws, pane, rect, collapsed)
            })
            .collect()
    }

    fn preview_placement(
        &self,
        ws: &WindowState,
        pane: u64,
        partition: crate::pane_partition::PanePartition,
    ) -> Option<(Rect, bool)> {
        if ws
            .preview_overlay
            .is_some_and(|overlay| overlay.pane == pane)
        {
            return crate::media::centered_preview_rect(partition.terminal)
                .map(|rect| (rect, false));
        }
        let share = partition.lane?;
        Some((
            share.rect()?,
            matches!(share, crate::pane_partition::LaneShare::Strip(_)),
        ))
    }

    /// `pane`'s lane in `rect`, projected for painting.
    fn preview_lane_panel(
        &self,
        ws: &WindowState,
        pane: u64,
        rect: Rect,
        collapsed: bool,
    ) -> Option<kettle_render::MediaLanePanel> {
        let panel = ws.preview_panels.get(&pane)?;
        let items = ws.mux.panes.get(&pane)?.media_shelf.items();
        let index = items.iter().position(|item| item.id == panel.item)?;
        let item = &items[index];
        let tr = &self.ui_text;
        let (kind, sender) = self.media_item_kind_and_sender(item);
        let text = item.source.text();
        let mode = lane_mode(item, panel);
        let mut lane = kettle_render::MediaLanePanel {
            focused_control: None,
            pin_label: ws
                .preview_overlay
                .filter(|open| open.pane == pane)
                .map(|_| tr.text(kettle_i18n::Text::MediaViewerPinShort).to_string()),
            play: None,
            sound: None,
            frame: None,
            scrubber: None,
            pane,
            rect,
            collapsed,
            title: item.title.clone(),
            detail: media_item_detail(*tr, kind, item),
            sender,
            // Where keys go: the terminal, or this lane while it holds the
            // keyboard.
            hint: tr
                .text(
                    if ws.preview_overlay.is_some_and(|open| open.pane == pane) {
                        kettle_i18n::Text::MediaViewerOverlayHint
                    } else if ws.preview_focus.is_some_and(|focus| focus.pane == pane) {
                        kettle_i18n::Text::MediaLaneHintFocused
                    } else {
                        kettle_i18n::Text::MediaLaneHint
                    },
                )
                .to_string(),
            position: (index + 1, items.len()),
            // The page asked for and not yet shown, else the one shown: where
            // a step counts from.
            page: item.source.gallery_page().map(|(shown, count)| {
                let asked = page_waited_on(panel, item.generation).map_or(shown, |ask| ask.page);
                (usize::from(asked) + 1, count)
            }),
            image: item.image().cloned(),
            status: tr.text(kettle_i18n::Text::MediaViewerReleased).to_string(),
            open_outside: self.preview_opens_outside(ws, pane).is_some(),
            canvas: preview_canvas(item, panel),
            mode,
            source: text.map(|_| kettle_render::MediaLaneSource::default()),
            copy: match mode {
                kettle_render::MediaLaneMode::Rendered => item.image().is_some(),
                kettle_render::MediaLaneMode::Source => true,
            },
            notice: panel
                .notice
                .map(|notice| lane_notice_text(notice, tr).to_string()),
            reload: preview_reloads(item),
            view: panel.view,
            // Sharper pixels for this item as it is now, if the lane holds
            // them.
            // An expanded lane resizes by the edge it shares with its
            // terminal.
            edge: ws
                .mux
                .lane(pane)
                .filter(|_| !collapsed)
                .map(|lane| match lane.side {
                    crate::pane_partition::LaneSide::Bottom => kettle_render::MediaLaneEdge::Top,
                    crate::pane_partition::LaneSide::Right => kettle_render::MediaLaneEdge::Left,
                }),
            tile: ws
                .lane_crops
                .get(&pane)
                .and_then(|crop| crop.tile.as_ref())
                .filter(|tile| tile.serves(item.id, item.generation, item.source.spec.canvas))
                .map(|tile| kettle_render::MediaLaneTile {
                    image: tile.image.clone(),
                    coverage: tile.coverage,
                }),
        };
        // A video's silent preview: its button, its frame in the poster's
        // place while it plays, and what it is doing in the footer.
        if lane_previews_item(item, panel).is_some() {
            let preview = ws
                .lane_previews
                .get(&pane)
                .filter(|preview| preview.serves(item.id, item.generation));
            lane.play = Some(match preview {
                Some(preview) if preview.active() => kettle_render::MediaLanePlay::Stop,
                _ => kettle_render::MediaLanePlay::Play,
            });
            if let Some(preview) = preview.filter(|preview| preview.active()) {
                match preview.frame() {
                    Some(frame) => {
                        lane.frame = Some(kettle_render::MediaLaneFrame {
                            sheet: frame.sheet.clone(),
                            source: frame.source,
                            size: item.size,
                        });
                        lane.notice = Some(tr.media_lane_notice_preview_playing(
                            &kettle_render::duration_label(frame.at_ms),
                            &kettle_render::duration_label(frame.length_ms),
                        ));
                    }
                    None => {
                        lane.notice = Some(
                            tr.text(kettle_i18n::Text::MediaLaneNoticePreviewLoading)
                                .to_string(),
                        );
                    }
                }
            }
        }
        // A video playing in its lane, paused in place, or stopped where it
        // stood, while no silent preview plays: its frame in the poster's
        // place, its bar, and what it does in the footer.
        let previewing = ws
            .lane_previews
            .get(&pane)
            .is_some_and(|preview| preview.serves(item.id, item.generation) && preview.active());
        if lane_previews_item(item, panel).is_some()
            && !previewing
            && let Some(playback) = ws
                .lane_playbacks
                .get(&pane)
                .filter(|playback| playback.serves(item.id, item.generation))
        {
            lane.play = Some(match playback.button() {
                crate::media::PlaybackButton::Pause => kettle_render::MediaLanePlay::Pause,
                crate::media::PlaybackButton::Play => kettle_render::MediaLanePlay::Play,
            });
            // Only sound that can play has a button.
            lane.sound = match playback.sound() {
                Some(crate::media::PlaybackSound::Heard) => {
                    Some(kettle_render::MediaLaneSound::Heard)
                }
                Some(crate::media::PlaybackSound::Muted) => {
                    Some(kettle_render::MediaLaneSound::Muted)
                }
                Some(crate::media::PlaybackSound::Silent(_)) | None => None,
            };
            if let Some(frame) = playback.frame() {
                lane.frame = Some(kettle_render::MediaLaneFrame {
                    sheet: frame.clone(),
                    source: (0, 0, frame.width, frame.height),
                    size: item.size,
                });
            }
            let (at, length) = (playback.position_ms(), playback.duration_ms());
            lane.scrubber = Some(kettle_render::MediaLaneScrubber {
                position_ms: at,
                duration_ms: length,
                label: tr.media_lane_video_time(
                    &kettle_render::duration_label(at),
                    &kettle_render::duration_label(length),
                ),
            });
            match playback.notice() {
                Some(crate::media::PlaybackNotice::Opening) => {
                    lane.notice = Some(
                        tr.text(kettle_i18n::Text::MediaLaneNoticeVideoLoading)
                            .to_string(),
                    );
                }
                Some(crate::media::PlaybackNotice::Muted) => {
                    lane.notice = Some(
                        tr.text(kettle_i18n::Text::MediaLaneNoticeVideoMuted)
                            .to_string(),
                    );
                }
                Some(crate::media::PlaybackNotice::Silent(why)) => {
                    lane.notice = Some(tr.text(silence_text(why)).to_string());
                }
                Some(crate::media::PlaybackNotice::Failed(failure)) => {
                    lane.notice =
                        Some(lane_notice_text(playback_failure_notice(failure), tr).to_string());
                }
                None => {}
            }
        }
        // The source rows in view, for the room the lane has: only those are
        // read out of the text.
        if mode == kettle_render::MediaLaneMode::Source
            && text.is_some()
            && let Some(geometry) = self.preview_lane_geometry(ws, &lane)
        {
            let glyph = self.overlay_text_cell_width(ws).max(1.0);
            let columns = (geometry.image_area.2 / glyph).ceil() as usize + 1;
            lane.source = Some(lane_source(
                &item.source,
                panel.scroll,
                geometry.source_rows,
                columns,
            ));
        }
        if let Some(control) = ws
            .preview_overlay
            .filter(|open| open.pane == pane)
            .and_then(|open| open.control)
            && let Some(geometry) = self.preview_lane_geometry(ws, &lane)
        {
            lane.focused_control = lane_interactive_controls(&lane, &geometry)
                .into_iter()
                .find(|(part, _, _)| *part == control)
                .map(|(_, rect, _)| rect);
        }
        Some(lane)
    }

    /// How the viewer and assistive technology describe a shelf item: its
    /// kind, and who sent it.
    fn media_item_kind_and_sender(
        &self,
        item: &crate::media::ShelfItem,
    ) -> (&'static str, kettle_render::MediaLaneSender) {
        let tr = &self.ui_text;
        let kind = tr.text(match item.kind {
            kettle_media::MediaKind::Raster => kettle_i18n::Text::MediaViewerKindImage,
            kettle_media::MediaKind::Svg => kettle_i18n::Text::MediaViewerKindSvg,
            kettle_media::MediaKind::Mermaid => kettle_i18n::Text::MediaViewerKindMermaid,
            kettle_media::MediaKind::Video => kettle_i18n::Text::MediaViewerKindVideo,
            kettle_media::MediaKind::Markdown => kettle_i18n::Text::MediaViewerKindMedia,
        });
        let sender = match &item.provenance {
            crate::media::Provenance::Verified => kettle_render::MediaLaneSender {
                text: tr.text(kettle_i18n::Text::MediaViewerFromPane).to_string(),
                program: None,
                signer: None,
            },
            crate::media::Provenance::User => kettle_render::MediaLaneSender {
                text: tr.text(kettle_i18n::Text::MediaViewerFromUser).to_string(),
                program: None,
                signer: None,
            },
            crate::media::Provenance::Unverified(sender) => {
                let pid = u64::from(sender.pid);
                let line = |program: &str, signer: Option<&str>| match signer {
                    Some(signer) => tr.media_viewer_unverified_signed(program, pid, signer),
                    None => tr.media_viewer_unverified(program, pid),
                };
                let signer = sender.signer.as_deref();
                match sender.executable.as_deref() {
                    Some(path) => media_viewer_sender_line(line, path, signer),
                    None => media_viewer_sender_line(
                        line,
                        tr.text(kettle_i18n::Text::MediaViewerUnknownProgram),
                        signer,
                    ),
                }
            }
        };
        (kind, sender)
    }

    /// Where `lane`'s controls are.
    fn preview_lane_geometry(
        &self,
        ws: &WindowState,
        lane: &kettle_render::MediaLanePanel,
    ) -> Option<kettle_render::MediaLaneGeometry> {
        kettle_render::media_lane_geometry(
            lane,
            self.menu_cell(ws),
            (
                self.overlay_text_cell_width(ws),
                self.overlay_text_line_height(ws),
            ),
        )
    }

    /// `pane`'s lane geometry as it shows in the active tab, when it has
    /// room to draw.
    fn preview_diagnostics(
        &self,
        ws: &WindowState,
        pane: u64,
        rect: Option<Rect>,
        collapsed: bool,
        state: &str,
    ) -> serde_json::Value {
        let mut lane = serde_json::json!({
            "pane": pane,
            "rect": rect.map(rect_json),
            "state": state,
        });
        // What the lane shows and where its controls are: names and
        // rectangles only, never a title, a source or pixels.
        if let Some(panel) =
            rect.and_then(|rect| self.preview_lane_panel(ws, pane, rect, collapsed))
        {
            lane["mode"] = match panel.mode {
                kettle_render::MediaLaneMode::Rendered => "rendered",
                kettle_render::MediaLaneMode::Source => "source",
            }
            .into();
            lane["canvas"] = match panel.canvas {
                kettle_render::MediaCanvas::Theme => "theme",
                kettle_render::MediaCanvas::White => "white",
                kettle_render::MediaCanvas::Checker => "checker",
            }
            .into();
            lane["zoom"] = panel.view.zoom().into();
            if let Some(geometry) = self.preview_lane_geometry(ws, &panel) {
                // Where the content is and the item is drawn in it:
                // rectangles, never pixels.
                lane["content"] = rect_json(geometry.content);
                lane["image"] = geometry.image.map(rect_json).into();
                lane["sharp"] = geometry.tile.map(rect_json).into();
                lane["edge"] = geometry.resize.map(rect_json).into();
                lane["keyboard"] = if ws.preview_focus.is_some_and(|focus| focus.pane == pane) {
                    "preview"
                } else {
                    "terminal"
                }
                .into();
                let mut controls: serde_json::Map<String, serde_json::Value> =
                    lane_controls(&geometry)
                        .into_iter()
                        .filter_map(|(_, rect, hit)| {
                            Some((lane_control_name(hit).to_string(), rect_json(rect?)))
                        })
                        .collect();
                if let Some(bar) = geometry.scrubber {
                    controls.insert(
                        lane_control_name(kettle_render::MediaLaneHit::Scrub).to_string(),
                        rect_json(bar),
                    );
                }
                lane["controls"] = controls.into();
            }
            // A video playing in the lane, paused in place, or
            // stopped where it stood: where it is, never a frame.
            if let Some(bar) = &panel.scrubber {
                let state = match (
                    panel.play,
                    ws.lane_playbacks
                        .get(&pane)
                        .is_some_and(crate::media::LanePlayback::has_session),
                ) {
                    (Some(kettle_render::MediaLanePlay::Pause), _) => "playing",
                    (_, true) => "paused",
                    (_, false) => "stopped",
                };
                let sound = ws
                    .lane_playbacks
                    .get(&pane)
                    .and_then(crate::media::LanePlayback::sound)
                    .map(playback_sound_name);
                lane["playback"] = serde_json::json!({
                    "state": state,
                    "position_ms": bar.position_ms,
                    "duration_ms": bar.duration_ms,
                    "frame": panel.frame.is_some(),
                    "sound": sound,
                });
            }
        }
        lane
    }

    fn preview_panel_of(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Option<kettle_render::MediaLanePanel> {
        let partition = self
            .pane_layout(ws, self.area(ws))
            .into_iter()
            .find(|(id, _)| *id == pane)?
            .1;
        let (rect, collapsed) = self.preview_placement(ws, pane, partition)?;
        self.preview_lane_panel(ws, pane, rect, collapsed)
    }

    fn preview_lane_geometry_of(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Option<kettle_render::MediaLaneGeometry> {
        let lane = self.preview_panel_of(ws, pane)?;
        self.preview_lane_geometry(ws, &lane)
    }

    fn shown_preview_controls(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Vec<(u64, Rect, kettle_render::MediaLaneHit)> {
        let Some(lane) = self.preview_panel_of(ws, pane) else {
            return Vec::new();
        };
        self.preview_lane_geometry(ws, &lane)
            .map(|geometry| lane_interactive_controls(&lane, &geometry))
            .unwrap_or_default()
    }

    fn preview_is_reachable(&self, ws: &WindowState, pane: u64) -> bool {
        !self.non_search_modal_open(ws) && ws.preview_overlay.is_none_or(|open| open.pane == pane)
    }

    /// The lane under `(x, y)` in the active tab, with its pane and whether
    /// it shows as a strip: the whole lane, whether or not its panel has room
    /// to draw.
    fn preview_lane_at(&self, ws: &WindowState, x: f32, y: f32) -> Option<(u64, Rect, bool)> {
        self.pane_layout(ws, self.area(ws))
            .into_iter()
            .find_map(|(pane, partition)| {
                if ws
                    .preview_overlay
                    .is_some_and(|overlay| overlay.pane != pane)
                {
                    return None;
                }
                let (rect, strip) = self.preview_placement(ws, pane, partition)?;
                (x >= rect.0 && x < rect.0 + rect.2 && y >= rect.1 && y < rect.1 + rect.3)
                    .then_some((pane, rect, strip))
            })
    }

    /// Whether the wheel at the pointer is a preview lane's: over a lane that
    /// nothing covers, so the terminal beside it never scrolls from a wheel
    /// over the lane. A menu or dialog open over it takes the wheel instead.
    fn lane_takes_wheel(&self, ws: &WindowState) -> bool {
        ws.context_menu.is_none()
            && !self.non_search_modal_open(ws)
            && (ws.preview_overlay.is_some() || self.preview_lane_under_pointer(ws))
    }

    fn preview_lane_under_pointer(&self, ws: &WindowState) -> bool {
        self.preview_lane_at(ws, ws.cursor.x as f32, ws.cursor.y as f32)
            .is_some()
    }

    /// A press over a preview lane belongs to it, whichever button, so the
    /// terminal beside it never receives it. The primary button acts on the
    /// control under it. Shared by native and ctl mouse input.
    fn press_preview_lane(&mut self, ws: &mut WindowState, x: f32, y: f32, bcode: u8) -> bool {
        let Some((pane, rect, collapsed)) = self.preview_lane_at(ws, x, y) else {
            if bcode == 0
                && let Some(open) = ws.preview_overlay
            {
                self.close_preview(ws, open.pane);
                return true;
            }
            return ws.preview_overlay.is_some();
        };
        if let Some(open) = &mut ws.preview_overlay {
            open.control = None;
        }
        if bcode != 0 {
            return true;
        }
        let geometry = self
            .preview_lane_panel(ws, pane, rect, collapsed)
            .and_then(|lane| self.preview_lane_geometry(ws, &lane));
        let hit = geometry
            .as_ref()
            .and_then(|geometry| geometry.hit_test(x, y));
        // A press on a playing video's bar moves it there, and a drag
        // along the bar after it, until the release opens the video there.
        if hit == Some(kettle_render::MediaLaneHit::Scrub)
            && let Some(fraction) = geometry.as_ref().and_then(|geometry| geometry.scrub_at(x))
            && let Some(playback) = ws.lane_playbacks.get_mut(&pane)
        {
            playback.scrub(fraction, std::time::Instant::now());
            let at = (f64::from(x), f64::from(y));
            ws.lane_drag = Some(crate::window_state::LaneDrag {
                pane,
                from: at,
                last: at,
                panning: false,
                scrub: true,
            });
            self.lanes_changed(ws, false);
            return true;
        }
        // A press on the lane's edge drags it.
        if hit == Some(kettle_render::MediaLaneHit::Resize) {
            ws.lane_resize = Some(crate::window_state::LaneResize {
                pane,
                resized: std::time::Instant::now() - crate::window_state::LANE_RESIZE_PTY_INTERVAL,
                pending: false,
            });
            return true;
        }
        // A press on the content of a lane showing a rendered item may
        // become a drag that pans it.
        if hit == Some(kettle_render::MediaLaneHit::Inside)
            && let Some(geometry) = geometry
            && geometry.fit.is_some()
            && rect_contains(geometry.content, x, y)
        {
            let at = (f64::from(x), f64::from(y));
            ws.lane_drag = Some(crate::window_state::LaneDrag {
                pane,
                from: at,
                last: at,
                panning: false,
                scrub: false,
            });
        }
        if let Some(hit) = hit {
            self.act_on_preview(ws, pane, hit);
        }
        true
    }

    /// Do what a lane control does, from the pointer or assistive technology.
    fn act_on_preview(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        hit: kettle_render::MediaLaneHit,
    ) {
        use kettle_render::MediaLaneHit as Hit;
        match hit {
            Hit::Close => self.close_preview(ws, pane),
            Hit::Toggle => self.toggle_preview(ws, pane),
            Hit::Pin => self.pin_preview(ws, pane),
            Hit::Previous => self.step_preview(ws, pane, -1),
            Hit::Next => self.step_preview(ws, pane, 1),
            Hit::PreviousPage => self.page_preview(ws, pane, -1),
            Hit::NextPage => self.page_preview(ws, pane, 1),
            Hit::OpenOutside => self.open_preview_outside(ws, pane),
            Hit::Mode => self.switch_preview_mode(ws, pane),
            Hit::Canvas => self.next_preview_canvas(ws, pane),
            Hit::Copy => self.copy_preview(ws, pane),
            Hit::Reload => self.reload_preview(ws, pane),
            Hit::Play => self.toggle_lane_play(ws, pane),
            Hit::Sound => self.toggle_lane_sound(ws, pane),
            Hit::ZoomOut => self.zoom_preview(ws, pane, 1.0 / kettle_render::MEDIA_ZOOM_STEP),
            Hit::ZoomIn => self.zoom_preview(ws, pane, kettle_render::MEDIA_ZOOM_STEP),
            Hit::Fit => self.fit_preview(ws, pane),
            // The edge moves with a drag, and the bar with a press or a
            // drag, not a click.
            Hit::Resize | Hit::Scrub | Hit::Inside => {}
        }
    }

    /// Preview the retained bitmap in its pane without changing the command line.
    /// Video receipts remain informational.
    fn open_media_paste_receipt(&mut self, ws: &mut WindowState) {
        let Some(active) = ws.media_paste_receipt.as_ref().filter(|receipt| {
            ws.mux.active_focus() == Some(receipt.pane_id)
                && matches!(
                    &receipt.kind,
                    crate::window_state::MediaPasteReceiptKind::Image { .. }
                )
        }) else {
            return;
        };
        let pane = active.pane_id;
        let path = active.path.clone();
        if !self.pasted_images.path_still_matches(&path) {
            ws.media_paste_receipt = None;
            ws.accessibility_pending = true;
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleImagePreviewUnavailable),
                self.ui_text.text(kettle_i18n::Text::NotifyBodyImageGone),
            );
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
            return;
        }
        self.pull_preview(ws, pane, &path, None);
    }

    /// Clear the focused pane's selection (called when the user types —
    /// every modern terminal does this so a stale highlight doesn't
    /// confuse the next copy/paste). No-op when nothing is selected.
    fn clear_selection_on_input(&mut self, ws: &mut WindowState) {
        if let Some(p) = ws.mux.focused()
            && let Ok(mut t) = p.term.term.lock()
            && t.selection.is_some()
        {
            t.selection = None;
        }
    }

    /// A receipt describes the command line at the instant Kettle pasted it.
    /// The next authored input can edit, submit, or cancel that line, so keeping
    /// the card would turn a receipt into stale success chrome. A later media
    /// paste installs its own fresh receipt after delivery.
    fn dismiss_media_paste_receipt_on_input(ws: &mut WindowState) {
        drop(Self::take_media_paste_receipt_on_input(ws));
    }

    fn take_media_paste_receipt_on_input(
        ws: &mut WindowState,
    ) -> Option<crate::window_state::MediaPasteReceiptState> {
        let (receipt, _) = Self::take_media_paste_state_on_input(ws);
        receipt
    }

    fn take_media_paste_state_on_input(
        ws: &mut WindowState,
    ) -> (
        Option<crate::window_state::MediaPasteReceiptState>,
        Option<crate::window_state::PendingVideoPasteReceipt>,
    ) {
        let previous = ws.media_paste_receipt.take();
        let pending = ws.pending_video_paste_receipt.take();
        if previous.is_some() {
            ws.accessibility_pending = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        (previous, pending)
    }

    fn dismiss_media_paste_receipt_for_pane(&mut self, ws: &mut WindowState, pane_id: u64) {
        if ws
            .media_paste_receipt
            .as_ref()
            .is_some_and(|receipt| receipt.pane_id == pane_id)
            || ws
                .pending_video_paste_receipt
                .as_ref()
                .is_some_and(|receipt| receipt.pane_id == pane_id)
        {
            Self::dismiss_media_paste_receipt_on_input(ws);
            return;
        }
        if let Some(window) = self.windows.values_mut().find(|window| {
            window
                .media_paste_receipt
                .as_ref()
                .is_some_and(|receipt| receipt.pane_id == pane_id)
                || window
                    .pending_video_paste_receipt
                    .as_ref()
                    .is_some_and(|receipt| receipt.pane_id == pane_id)
        }) {
            Self::dismiss_media_paste_receipt_on_input(window);
        }
    }

    fn media_paste_receipt_pane(ws: &WindowState) -> Option<u64> {
        ws.media_paste_receipt
            .as_ref()
            .map(|receipt| receipt.pane_id)
            .or_else(|| {
                ws.pending_video_paste_receipt
                    .as_ref()
                    .map(|receipt| receipt.pane_id)
            })
    }

    fn dismiss_media_paste_receipt_after_input(
        ws: &mut WindowState,
        pane_id: u64,
        result: PaneInputResult,
    ) {
        if result.is_queued() && Self::media_paste_receipt_pane(ws) == Some(pane_id) {
            Self::dismiss_media_paste_receipt_on_input(ws);
        }
    }

    fn dismiss_media_paste_receipt_after_delivery(
        ws: &mut WindowState,
        delivery: PaneInputDelivery,
    ) {
        if delivery.receipt_accepted {
            Self::dismiss_media_paste_receipt_on_input(ws);
        }
    }

    fn report_input_result(&mut self, result: PaneInputResult) {
        let Some(message) = input_rejection_message(result) else {
            return;
        };
        let now = std::time::Instant::now();
        if should_notify_input_rejection(self.last_input_rejection_notice, result, now) {
            log::warn!("terminal input rejected ({result:?}): {message}");
            let tr = &self.ui_text;
            fire_notify(
                tr.text(kettle_i18n::Text::NotifyTitleInputNotDelivered),
                input_rejection_text(result, tr).unwrap_or(message),
            );
            self.last_input_rejection_notice = Some((result, now));
        }
    }

    /// Deliver user-authored bytes with the same selection, cursor, broadcast,
    /// read-only, and scroll behavior for keyboard and IME commit paths.
    fn write_terminal_input(&mut self, ws: &mut WindowState, bytes: &[u8]) {
        self.sync_pane_focus_reports(ws);
        if bytes.is_empty() {
            return;
        }
        self.clear_selection_on_input(ws);
        self.reset_blink_phase(ws);
        self.hide_mouse_cursor(ws);
        let input_time = std::time::Instant::now();
        let result = if ws.mux.is_broadcast_on() {
            self.broadcast_input(ws, bytes, self.cfg.scroll_on_keystroke, input_time)
        } else if let Some(pane_id) = ws.mux.active_focus() {
            let Some(pane) = ws.mux.panes.get(&pane_id) else {
                return;
            };
            let result = pane.feed_input(bytes);
            if result.is_queued() {
                ws.last_typed = Some(input_time);
            }
            if result.is_queued()
                && self.cfg.scroll_on_keystroke
                && let Ok(mut term) = pane.term.term.lock()
            {
                term.scroll_display(Scroll::Bottom);
            }
            Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
            result
        } else {
            PaneInputResult::Queued
        };
        self.report_input_result(result);
    }

    fn write_terminal_key_event(
        &mut self,
        ws: &mut WindowState,
        event: &winit::event::KeyEvent,
        prepare_input: bool,
    ) {
        self.sync_pane_focus_reports(ws);
        let mods = pty_key_modifiers(ws, &event.logical_key);
        let modified_enter = key_is_modified_enter(&event.logical_key, mods);
        if !ws.mux.is_broadcast_on() {
            let mode = ws
                .mux
                .focused()
                .map(|pane| pane.effective_key_mode(self.cfg.modify_other_keys, modified_enter))
                .unwrap_or_else(kettle_core::TermMode::empty);
            let Some(bytes) = encode_key_event_for_mode(&self.cfg, event, mods, mode) else {
                return;
            };
            if prepare_input {
                self.write_terminal_input(ws, &bytes);
            } else if let Some(pane) = ws.mux.focused() {
                let result = pane.feed_input(&bytes);
                self.report_input_result(result);
            }
            return;
        }

        if prepare_input {
            self.clear_selection_on_input(ws);
            self.reset_blink_phase(ws);
            self.hide_mouse_cursor(ws);
        }
        let input_time = prepare_input.then(std::time::Instant::now);
        let scroll_to_bottom = prepare_input && self.cfg.scroll_on_keystroke;
        let scope = ws.mux.broadcast.clone();
        let cfg = &self.cfg;
        let receipt_pane = prepare_input
            .then(|| Self::media_paste_receipt_pane(ws))
            .flatten();
        let mut delivery = ws.mux.broadcast_encoded(
            self.cfg.modify_other_keys,
            modified_enter,
            scroll_to_bottom,
            receipt_pane,
            |mode| encode_key_event_for_mode(cfg, event, mods, mode),
        );
        Self::dismiss_media_paste_receipt_after_delivery(ws, delivery);
        if let Some(input_time) = input_time {
            stamp_accepted_input(&mut ws.last_typed, delivery, input_time);
        }
        if Mux::scope_crosses_windows(&scope) {
            for other in self.windows.values_mut() {
                let receipt_pane = prepare_input
                    .then(|| Self::media_paste_receipt_pane(other))
                    .flatten();
                let foreign = other.mux.broadcast_encoded_foreign(
                    &scope,
                    self.cfg.modify_other_keys,
                    modified_enter,
                    scroll_to_bottom,
                    receipt_pane,
                    |mode| encode_key_event_for_mode(cfg, event, mods, mode),
                );
                Self::dismiss_media_paste_receipt_after_delivery(other, foreign);
                if let Some(input_time) = input_time {
                    stamp_accepted_input(&mut other.last_typed, foreign, input_time);
                }
                delivery.result = delivery.result.merge(foreign.result);
                delivery.accepted |= foreign.accepted;
            }
        }
        self.report_input_result(delivery.result);
    }

    fn commit_ime_text(&mut self, ws: &mut WindowState, text: &str, event_loop: &ActiveEventLoop) {
        if text.is_empty() {
            return;
        }
        let key = Key::Character(text.into());
        if ws.context_menu.is_some() || ws.vi_mode.is_some() || ws.hint_state.is_some() {
            return;
        }
        // The modal handlers below filter typed text by the modifiers that
        // produced it. A committed composition has none: the input method
        // decides when to commit, and whatever is latched at that instant did
        // not type the phrase. Committing with `⌘Space` (switch input source)
        // would otherwise drop the whole thing. Present the handlers with the
        // empty modifier set for the duration and restore it afterwards, so
        // `ws.mods` stays truthful for the next real keystroke.
        let latched_mods = ws.mods;
        ws.mods = ModifiersState::empty();
        // The modal outranks whatever raised it. Rebinding a key onto a chord
        // that is already taken raises a confirm dialog from inside the
        // Settings overlay. If the Settings arms below claimed the keyboard
        // first, the question could not be answered, by `y`/`n` or by anything
        // else, while the panel that asked it stayed open. The dialog's own
        // handler (the named-key path) reads `y`/`n`; this arm only has to
        // stop the text from going somewhere else.
        if ws.confirm_dialog.is_some() {
            ws.mods = latched_mods;
            return;
        } else if ws.palette_input.is_some() {
            self.palette_key(ws, &key, Some(text), event_loop);
        } else if ws.theme_picker_input.is_some() {
            self.theme_picker_key(ws, &key, Some(text));
        } else if ws.settings_nav.is_some() && ws.settings_text_edit.is_some() {
            self.settings_text_key(ws, &key, Some(text));
        } else if ws.settings_nav.is_some() {
            ws.mods = latched_mods;
            return;
        } else if ws.layout_picker_input.is_some() {
            self.layout_picker_key(ws, &key, Some(text));
        } else if ws.ssh_input.is_some() {
            self.ssh_key(ws, &key, Some(text));
        } else if ws.editing_title.is_some() {
            // Route through the shared helper rather than extending the buffer
            // inline, so an IME commit cannot bypass the 4 KiB cap the typed
            // path enforces.
            if let Some(accepted) = crate::modal_input::accept_committed_text(text)
                && let Some(state) = ws.editing_title.as_mut()
            {
                crate::modal_input::push_text(&mut state.input, accepted);
            }
        } else if ws.search.open {
            self.search_key(ws, &key, None, Some(text));
        } else {
            ws.mods = latched_mods;
            self.write_terminal_input(ws, text.as_bytes());
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
            return;
        }
        ws.mods = latched_mods;
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    fn tab_bar_h(&self, ws: &WindowState) -> f32 {
        let show = match self.cfg.tab_bar {
            // Title-edit needs a real chrome strip so the input never covers
            // terminal rows. Honor `off` during normal operation, but materialize
            // the strip while the modal owns keyboard focus.
            TabBarMode::Off => ws.editing_title.is_some(),
            // A live dock preview MATERIALIZES the bar on a single-tab auto
            // window. The strip appears under the hovering torn window so the
            // drop target is visible before the drop (Chrome's always-on
            // strip affordance, on demand).
            TabBarMode::Auto => {
                ws.mux.tabs.len() > 1 || ws.dock_preview.is_some() || ws.editing_title.is_some()
            }
            TabBarMode::Always => true,
        };
        if show {
            Self::cell_size(ws).map_or(24.0, |(_, ch)| ch + 8.0)
        } else {
            0.0
        }
    }

    /// Status-bar height (0 when off, cell_h + 6 px when
    /// enabled). Pair with `cfg.status_bar` (StatusBarMode) for
    /// position. Slightly shorter than the tab bar so the two strips
    /// read as distinct horizontal bands.
    fn status_bar_h(&self, ws: &WindowState) -> f32 {
        match self.cfg.status_bar {
            kettle_config::StatusBarMode::Off => 0.0,
            _ => Self::cell_size(ws).map_or(22.0, |(_, ch)| ch + 6.0),
        }
    }

    /// Height of the passive update banner while it is visible. The renderer
    /// uses the same `cell_h + 10px` formula, so the PTY grid, pixels, and
    /// hit-test agree instead of letting the banner cover the bottom row.
    fn update_banner_h(&self, ws: &WindowState) -> f32 {
        // Renderer chrome gives an active Search lane priority over this
        // passive notice. Match that precedence in PTY sizing instead of
        // reserving an invisible extra strip between content and Search.
        if self.update_available.is_some() && !ws.search.open {
            ws.renderer
                .as_ref()
                .map(|r| r.cell_h + 10.0)
                .unwrap_or(26.0)
        } else {
            0.0
        }
    }

    fn vertical_title_edit_h(&self, ws: &WindowState) -> f32 {
        if self.cfg.tab_bar_pos.is_vertical() && ws.editing_title.is_some() {
            self.tab_bar_h(ws)
        } else {
            0.0
        }
    }

    /// Height reserved by the responsive search lane. The renderer owns the
    /// layout formula; the app reuses it for PTY sizing and hit-testing so no
    /// terminal row can be painted underneath the controls.
    fn search_bar_h(&self, ws: &WindowState) -> f32 {
        if !ws.search.open {
            return 0.0;
        }
        let Some(renderer) = ws.renderer.as_ref() else {
            return 26.0;
        };
        let (width, height) = renderer.surface_size();
        kettle_render::search_bar_geometry(
            width as f32,
            height as f32,
            renderer.cell_w,
            renderer.cell_h,
            &self.ui_text,
        )
        .reserved_height
    }

    fn update_banner_rect(&self, ws: &WindowState) -> Option<Rect> {
        self.update_available.as_ref()?;
        let (sw, sh) = ws.renderer.as_ref()?.surface_size();
        let banner_h = self.update_banner_h(ws);
        if banner_h <= 0.0 {
            return None;
        }
        let bottom_tabbar_h = if matches!(self.cfg.tab_bar_pos, TabBarPos::Bottom) {
            self.tab_bar_h(ws)
        } else {
            0.0
        };
        let bottom_status_h = if matches!(self.cfg.status_bar, kettle_config::StatusBarMode::Bottom)
        {
            self.status_bar_h(ws)
        } else {
            0.0
        };
        let y =
            kettle_render::update_banner_top(sh as f32, banner_h, bottom_tabbar_h, bottom_status_h);
        Some((0.0, y, sw as f32, banner_h))
    }

    /// Content area for panes (excludes the tab bar, status bar, and
    /// passive update banner), in physical pixels.
    /// Terminator parity: hit-test for a click in any pane's per-pane titlebar region.
    /// Returns the pane id whose titlebar was clicked, or None if
    /// the click fell outside titlebar regions. Honors the
    /// `cfg.show_titlebar` gate + the `cfg.title_at_bottom` flip.
    /// Used by the click handler to dispatch EditPaneTitle on the
    /// clicked pane.
    fn pane_at_titlebar_click(&self, ws: &WindowState, px: f32, py: f32) -> Option<u64> {
        if !self.cfg.show_titlebar {
            return None;
        }
        let active = ws.mux.active;
        let rects = ws.mux.leaves(active, self.area(ws));
        if rects.len() < 2 {
            // Single-pane tab: titlebar isn't rendered (the renderer's
            // titlebar gate requires `show_titlebar` and more than one pane).
            return None;
        }
        let bar_h = ws.renderer.as_ref().map(|r| r.cell_h + 6.0).unwrap_or(20.0);
        pane_titlebar_hit(px, py, &rects, self.cfg.title_at_bottom, bar_h)
    }

    /// The cell size in physical pixels: the renderer's, or the one measured
    /// before it existed.
    fn cell_size(ws: &WindowState) -> Option<(f32, f32)> {
        ws.renderer
            .as_ref()
            .map(|r| (r.cell_w, r.cell_h))
            .or(ws.startup_cell)
    }

    /// The surface size in physical pixels: the renderer's, or the one chosen
    /// before it existed.
    fn surface_size(ws: &WindowState) -> Option<(u32, u32)> {
        ws.renderer
            .as_ref()
            .map(|r| r.surface_size())
            .or(ws.startup_surface)
    }

    /// The first window's surface in physical pixels, before the renderer
    /// exists. An axis `window-width` or `window-height` sets holds exactly
    /// that many cells at the startup cell size. An axis the config leaves
    /// alone keeps the default window's pixel size, fitted to the monitor
    /// when neither is set. `None` before the cell is measured.
    fn startup_surface(
        &self,
        ws: &WindowState,
        monitor: Option<StartupMonitor>,
    ) -> Option<(u32, u32)> {
        let cell = Self::cell_size(ws)?;
        let scale = monitor.map_or(1.0, |m| m.scale);
        let (default_w, default_h) = startup_inner_size(&self.cfg, monitor);
        let physical = |logical: f64| (logical * scale).round().max(1.0) as u32;
        let cols = self.cfg.window_width.map(|cols| {
            cols.clamp(
                kettle_config::WINDOW_WIDTH_MIN,
                kettle_config::WINDOW_WIDTH_MAX,
            )
        });
        let rows = self.cfg.window_height.map(|rows| {
            rows.clamp(
                kettle_config::WINDOW_HEIGHT_MIN,
                kettle_config::WINDOW_HEIGHT_MAX,
            )
        });
        let (exact_w, exact_h) = surface_for_grid(
            (
                cols.unwrap_or(STARTUP_DEFAULT_COLS) as usize,
                rows.unwrap_or(STARTUP_DEFAULT_ROWS) as usize,
            ),
            cell,
            (self.cfg.padding_x, self.cfg.padding_y),
            self.content_bands(ws),
            self.cfg.tab_bar_pos,
            self.cfg.status_bar,
            self.cfg.tab_bar_width,
        );
        Some((
            if cols.is_some() {
                exact_w
            } else {
                physical(default_w)
            },
            if rows.is_some() {
                exact_h
            } else {
                physical(default_h)
            },
        ))
    }

    fn prepare_startup_fonts(&mut self, ws: &mut WindowState, startup_scale: f32) {
        let fonts = match ws.startup_fonts.take() {
            Some(fonts) if fonts.matches(&self.cfg, startup_scale) => fonts,
            Some(fonts) => fonts.remeasure(&self.cfg, startup_scale),
            None => match self.font_preload.take() {
                Some(preload) => preload.finish(&self.cfg, startup_scale),
                None => kettle_render::StartupFonts::load(&self.cfg, startup_scale),
            },
        };
        ws.startup_cell = Some(fonts.cell);
        ws.startup_fonts = Some(fonts);
    }

    fn start_first_pane_before_launch(&mut self) -> Result<bool, String> {
        #[cfg(not(target_os = "macos"))]
        {
            let _ = self.pre_launch_eligible;
            Ok(false)
        }
        #[cfg(target_os = "macos")]
        {
            let decline = crate::startup_trace::note_pre_launch_decline;
            if !self.pre_launch_eligible {
                decline("ineligible".to_owned());
                return Ok(false);
            }
            let Some(monitor) = crate::macos_display::startup_display() else {
                decline("display".to_owned());
                return Ok(false);
            };
            crate::startup_trace::mark(crate::startup_trace::Phase::DisplayRead);
            let Some(mut ws) = self.windows.remove(&1) else {
                decline("window".to_owned());
                return Ok(false);
            };
            self.prepare_startup_fonts(&mut ws, monitor.scale as f32);
            let surface = self.startup_surface(&ws, Some(monitor));
            let result = if surface.is_some_and(|size| fits_monitor(size, Some(monitor))) {
                ws.startup_surface = surface;
                self.spawn_first_tab(&mut ws, self.launch_override)
                    .map(|()| {
                        ws.pre_launch = Some(monitor);
                        crate::startup_trace::mark(crate::startup_trace::Phase::PaneSpawned);
                        crate::startup_trace::note_path(
                            crate::startup_trace::StartupPath::PreLaunch,
                        );
                        true
                    })
            } else {
                // Keep the font system for the resumed path's measurement.
                ws.startup_cell = None;
                decline(match surface {
                    Some((width, height)) => format!(
                        "fit surface={width}x{height} monitor={:.0}x{:.0} scale={}",
                        monitor.logical.0, monitor.logical.1, monitor.scale
                    ),
                    None => "fit surface=none".to_owned(),
                });
                Ok(false)
            };
            self.windows.insert(1, ws);
            result
        }
    }

    /// Start the first tab at the current startup grid: the `-e` command and
    /// working directory when given, else the shell.
    fn spawn_first_tab(
        &mut self,
        ws: &mut WindowState,
        launch_override: bool,
    ) -> Result<(), String> {
        let area = self.area(ws);
        let (cols, rows) = self.grid_of(ws, area);
        let geometry = self.pty_geometry_for_grid(ws, cols, rows);
        if launch_override {
            let argv = self.startup.command.take().unwrap_or_default();
            let cwd = self
                .startup
                .cwd
                .take()
                .map(|p| p.to_string_lossy().into_owned());
            ws.mux
                .new_tab_with_geometry(&self.cfg, geometry, self.waker(), &argv, cwd.as_deref())
                .map_err(|e| format!("failed to spawn `-e` command: {e}"))
        } else {
            ws.mux
                .new_tab_geometry(&self.cfg, geometry, self.waker())
                .map_err(|e| format!("failed to spawn shell: {e}"))
        }
    }

    fn content_bands(&self, ws: &WindowState) -> ContentBands {
        ContentBands {
            tab_bar_h: self.tab_bar_h(ws),
            status_bar_h: self.status_bar_h(ws),
            update_banner_h: self.update_banner_h(ws),
            vertical_title_edit_h: self.vertical_title_edit_h(ws),
        }
    }

    fn area(&self, ws: &WindowState) -> Rect {
        let surface = Self::surface_size(ws).unwrap_or((800, 600));
        // Delegate to the pure helper, threading
        // `cfg.tab_bar_width` so a user-configured strip width
        // is honored.
        let mut area = content_rect_for_with_strip(
            surface,
            self.content_bands(ws),
            self.cfg.tab_bar_pos,
            self.cfg.status_bar,
            self.cfg.tab_bar_width,
        );
        area.3 = (area.3 - self.search_bar_h(ws)).max(0.0);
        area
    }

    /// Lift the drag ghost toward the same threshold that triggers tear-off.
    /// A window without its own active drag has no lift.
    fn tear_lift_for(&self, ws: &WindowState) -> f32 {
        if !self.cfg.detachable_tabs {
            return 0.0;
        }
        match ws.detach_drag {
            crate::detach::DragState::DraggingInside { .. }
            | crate::detach::DragState::DraggingOutside { .. } => self
                .dock_band(ws)
                .map(|band| {
                    tear_lift_ratio(
                        ws.cursor.x as f32,
                        ws.cursor.y as f32,
                        band,
                        1.5 * self.tab_bar_h(ws),
                    )
                })
                .unwrap_or(0.0),
            _ => 0.0,
        }
    }

    fn tab_bar(&self, ws: &WindowState) -> TabBar {
        let height = self.tab_bar_h(ws);
        if height <= 0.0 {
            return TabBar::hidden();
        }
        let band = self.tab_band(ws, height);
        let sw = band.2;
        let y = band.1;
        let is_vertical = self.cfg.tab_bar_pos.is_vertical();
        // Left/Right strips route through a separate vertical-stacked path;
        // Top/Bottom use the `tab_strip_layout` flow below.
        if is_vertical {
            return self.tab_bar_vertical(ws, band, height);
        }
        if ws.editing_title.is_some() {
            let strip_w = if is_vertical {
                self.cfg.tab_bar_width
            } else {
                0.0
            };
            let strip_x = match self.cfg.tab_bar_pos {
                TabBarPos::Right => sw - strip_w,
                _ => 0.0,
            };
            return TabBar {
                height,
                y,
                segments: Vec::new(),
                new_tab: (strip_x, y, strip_w, height),
                new_tab_menu: (0.0, 0.0, 0.0, 0.0),
                hovered_new_tab: false,
                hovered_new_tab_menu: false,
                broadcast: ws.mux.is_broadcast_on(),
                hovered_close_idx: None,
                drag_cursor_x: None,
                drag_cursor_y: None,
                // The title-edit modal owns the bar — no drag can be live.
                tear_lift: 0.0,
                insert_marker: None,
                band,
                scroll_left: (0.0, 0.0, 0.0, 0.0),
                scroll_right: (0.0, 0.0, 0.0, 0.0),
            };
        }
        let labels = ws.mux.tab_labels(&self.ui_text);
        let n = labels.len().max(1);
        // Trailing "▾ +" button: a `▾` dropdown arrow (left) + the `+` (right),
        // each `height` wide. The strip must reserve the WHOLE
        // button (arrow + plus), not just `plus_w`, or the last tab segment
        // overlaps it.
        let plus_w = height;
        // Hide the ▾ shell-dropdown when only one shell is
        // available (e.g. stock Ubuntu = just bash). A zero-width arrow drops it
        // from both the render pass (`new_tab_menu.2 > 0.0`) and the click
        // hit-test, and the `+` button reclaims the space.
        let arrow_w = if new_tab_dropdown_visible() {
            height
        } else {
            0.0
        };
        let button_w = plus_w + arrow_w;
        // The drag-to-reorder handler derives its strip width from
        // the same helper, so the two can't disagree on where segments end.
        let strip = tab_segment_strip_width(sw, plus_w, arrow_w);
        let (arrow_rect, plus_rect) =
            split_new_tab_button((sw - button_w, y, button_w, height), arrow_w);
        // Tabs divide the strip evenly and fill the bar; once they would
        // shrink below `tab_min_width` the bar overflows and — when `scroll_tabbar`
        // — scrolls with `‹ ›` arrows, showing only whole tabs (active kept in
        // view). See `tab_strip_layout`. Scroll arrows are `height`-wide squares.
        let active = ws.mux.active;
        let layout = tab_strip_layout(
            n,
            active,
            strip,
            button_w,
            height,
            self.cfg.tab_min_width,
            self.cfg.scroll_tabbar,
        );
        // Tabs scrolled out of view are parked off-screen (kept in the segment
        // list, idx-indexed, so reorder / dock / ghost logic is undisturbed).
        const OFFSCREEN_X: f32 = -100_000.0;
        let now = std::time::Instant::now();
        let silence = std::time::Duration::from_millis(self.cfg.tab_silence_threshold_ms);
        let segments: Vec<TabSeg> = labels
            .iter()
            .enumerate()
            .map(|(i, label)| {
                let x = layout.xs.get(i).copied().flatten().unwrap_or(OFFSCREEN_X);
                // Per-tab activity dot. Active tabs short-circuit to
                // Normal (the focused-tab accent already signals "you are here").
                let activity = ws
                    .mux
                    .tabs
                    .get(i)
                    .map(|tab| {
                        match crate::mux::classify_tab_activity(
                            i == active,
                            tab.bell,
                            tab.last_output_at,
                            tab.last_seen_at,
                            now,
                            silence,
                        ) {
                            crate::mux::TabActivity::Normal => RenderTabActivity::Normal,
                            crate::mux::TabActivity::Output => RenderTabActivity::Output,
                            crate::mux::TabActivity::Bell => RenderTabActivity::Bell,
                            crate::mux::TabActivity::Silent => RenderTabActivity::Silent,
                        }
                    })
                    .unwrap_or(RenderTabActivity::Normal);
                // The last tab yields the trailing `▾`/`+` button reservation
                // in the full-width-aligned layout, so it is narrower than the
                // rest; every other layout has `last_width == width`.
                let seg_w = if i + 1 == n {
                    layout.last_width
                } else {
                    layout.width
                };
                let rect = (x, y, seg_w, height);
                let close =
                    tab_close_rect(x + seg_w - height, y, height, self.cfg.close_button_on_tab);
                TabSeg {
                    idx: i,
                    rect,
                    title_rect: tab_title_rect(rect, close, self.cfg.close_button_on_tab),
                    // ✕ hit zone = the trailing `height`-wide square.
                    close,
                    title: label.text.clone(),
                    path: label.path.clone(),
                    active: i == active,
                    activity,
                }
            })
            .collect();
        let to_btn = |ox: Option<f32>| ox.map_or((0.0, 0.0, 0.0, 0.0), |x| (x, y, height, height));
        TabBar {
            height,
            y,
            segments,
            new_tab: plus_rect,
            new_tab_menu: arrow_rect,
            hovered_new_tab: ws.hovered_new_tab,
            hovered_new_tab_menu: ws.hovered_new_tab_menu,
            // Broadcast indicator on the active tab.
            broadcast: ws.mux.is_broadcast_on(),
            // Hover-on-✕ chip: renderer paints a red highlight behind
            // the close glyph; UI's `sync_cursor_icon` flips the OS
            // cursor to Pointer at the same time.
            hovered_close_idx: ws.hovered_close_idx,
            // While a tab-bar drag is in progress, hand
            // the renderer the cursor x so it paints a translucent
            // ghost of the dragged segment under the cursor.
            drag_cursor_x: if ws.tab_drag_active && ws.tab_drag_press.is_none() {
                Some(ws.cursor.x as f32)
            } else {
                None
            },
            drag_cursor_y: None,
            // Tear-off UX: pre-tear ghost escalation.
            tear_lift: self.tear_lift_for(ws),
            // Re-dock: vertical insertion line at the docked tab's landing slot,
            // anchored to the target tab's on-screen x when visible (overflow
            // scrolling), else to the leftmost visible edge.
            insert_marker: ws.dock_preview.map(|idx| {
                let x = layout
                    .xs
                    .get(idx)
                    .copied()
                    .flatten()
                    .or_else(|| layout.xs.iter().copied().flatten().next())
                    .unwrap_or(0.0)
                    .clamp(0.0, strip - kettle_render::tab_drag::INSERT_MARKER_PX);
                (x, y, kettle_render::tab_drag::INSERT_MARKER_PX, height)
            }),
            // Tear-off UX: the dock-highlight canvas.
            band,
            scroll_left: to_btn(layout.arrow_left),
            scroll_right: to_btn(layout.arrow_right),
        }
    }

    fn title_edit_rect(&self, ws: &WindowState) -> kettle_render::Rect4 {
        let (w, h) = ws
            .renderer
            .as_ref()
            .map(|r| r.surface_size())
            .unwrap_or((800, 600));
        let (sw, sh) = (w as f32, h as f32);
        let bar = self.tab_bar(ws);
        let row_h = ws.renderer.as_ref().map(|r| r.cell_h + 8.0).unwrap_or(24.0);
        let content_y = self.area(ws).1;
        title_edit_rect_for(
            self.cfg.tab_bar_pos.is_vertical(),
            bar.y,
            bar.height,
            content_y,
            sw,
            sh,
            row_h,
        )
    }

    /// Tab-bar layout for `TabBarPos::Left` / `Right`. Stacks segments
    /// vertically, each `cfg.tab_bar_width` × `tab_bar_h`. The new-tab `+`
    /// button follows the last tab, clamped to the bottom of the strip.
    fn tab_bar_vertical(&self, ws: &WindowState, band: Rect, height: f32) -> TabBar {
        let (strip_x, _, strip_w, sh) = band;
        let labels = ws.mux.tab_labels(&self.ui_text);
        let active = ws.mux.active;
        let now = std::time::Instant::now();
        let silence = std::time::Duration::from_millis(self.cfg.tab_silence_threshold_ms);
        let segments: Vec<TabSeg> = labels
            .iter()
            .enumerate()
            .map(|(i, label)| {
                let seg_y = i as f32 * height;
                let activity = ws
                    .mux
                    .tabs
                    .get(i)
                    .map(|tab| {
                        match crate::mux::classify_tab_activity(
                            i == active,
                            tab.bell,
                            tab.last_output_at,
                            tab.last_seen_at,
                            now,
                            silence,
                        ) {
                            crate::mux::TabActivity::Normal => RenderTabActivity::Normal,
                            crate::mux::TabActivity::Output => RenderTabActivity::Output,
                            crate::mux::TabActivity::Bell => RenderTabActivity::Bell,
                            crate::mux::TabActivity::Silent => RenderTabActivity::Silent,
                        }
                    })
                    .unwrap_or(RenderTabActivity::Normal);
                let rect = (strip_x, seg_y, strip_w, height);
                let close = tab_close_rect(
                    strip_x + strip_w - height,
                    seg_y,
                    height,
                    self.cfg.close_button_on_tab,
                );
                TabSeg {
                    idx: i,
                    rect,
                    title_rect: tab_title_rect(rect, close, self.cfg.close_button_on_tab),
                    // ✕ hit zone = the trailing-right square of the
                    // segment (same axis convention as horizontal).
                    close,
                    title: label.text.clone(),
                    path: label.path.clone(),
                    active: i == active,
                    activity,
                }
            })
            .collect();
        // `+` button at the bottom of the strip.
        let plus_y = (labels.len() as f32 * height).min(sh - height);
        TabBar {
            height,
            // `y` is the *band start* (top of the strip) for the
            // renderer; for vertical strips the band spans the
            // whole window height, so `y = 0`.
            y: 0.0,
            segments,
            new_tab: (strip_x, plus_y, strip_w, height),
            // No dropdown arrow on vertical bars — the bottom-of-
            // strip full-width `+` has nowhere sensible for a left-side arrow.
            new_tab_menu: (0.0, 0.0, 0.0, 0.0),
            hovered_new_tab: ws.hovered_new_tab,
            hovered_new_tab_menu: false,
            broadcast: ws.mux.is_broadcast_on(),
            hovered_close_idx: ws.hovered_close_idx,
            // A vertical strip's ghost rides the cursor's y down a fixed
            // column, so the main-axis coordinate is `y` here and `x` on the
            // horizontal bar. Using `x` here would pin the ghost to the top of
            // the strip and slide it sideways out of the bar.
            drag_cursor_x: None,
            drag_cursor_y: if ws.tab_drag_active && ws.tab_drag_press.is_none() {
                Some(ws.cursor.y as f32)
            } else {
                None
            },
            tear_lift: self.tear_lift_for(ws),
            // Re-dock: horizontal insertion line across the strip at the docked
            // tab's landing slot.
            insert_marker: ws.dock_preview.map(|idx| {
                let iy = (idx.min(labels.len()) as f32 * height)
                    .min(sh - kettle_render::tab_drag::INSERT_MARKER_PX)
                    .max(0.0);
                (
                    strip_x,
                    iy,
                    strip_w,
                    kettle_render::tab_drag::INSERT_MARKER_PX,
                )
            }),
            // Tear-off UX: the dock-highlight canvas is the whole vertical strip.
            band,
            // Vertical bars don't overflow-scroll (yet), so they have no arrows.
            scroll_left: (0.0, 0.0, 0.0, 0.0),
            scroll_right: (0.0, 0.0, 0.0, 0.0),
        }
    }

    /// The columns and rows that fit in `terminal`, a pane's terminal (or a
    /// whole area with nothing carved from it), inside its padding.
    fn grid_of(&self, ws: &WindowState, terminal: Rect) -> (usize, usize) {
        let (cw, ch) = Self::cell_size(ws).unwrap_or((8.0, 16.0));
        let (_, _, w, h) = terminal;
        grid_dims_px((w, h), (cw, ch), (self.cfg.padding_x, self.cfg.padding_y))
    }

    fn pty_geometry_for_grid(&self, ws: &WindowState, columns: usize, rows: usize) -> PtyGeometry {
        let fractional_cell = Self::cell_size(ws).unwrap_or((8.0, 16.0));
        let (pixel_width, pixel_height) = pty_pixel_size(fractional_cell, (columns, rows));
        PtyGeometry::new(columns, rows, pixel_width, pixel_height)
    }

    fn pty_geometry_for_terminal(&self, ws: &WindowState, terminal: Rect) -> PtyGeometry {
        let (columns, rows) = self.grid_of(ws, terminal);
        self.pty_geometry_for_grid(ws, columns, rows)
    }

    fn prospective_split_geometry(
        &self,
        ws: &WindowState,
        dir: Dir,
        new_first: bool,
    ) -> PtyGeometry {
        // The new pane's leaf in a tab one pane larger, with no lane of its own.
        let area = self.area(ws);
        let leaf = ws
            .mux
            .prospective_split_rect(dir, new_first, area)
            .unwrap_or(area);
        let metrics = self
            .layout_style(ws)
            .metrics(ws.mux.active_pane_count().saturating_add(1));
        let terminal = crate::pane_partition::partition_leaf(leaf, metrics, None).terminal;
        self.pty_geometry_for_terminal(ws, terminal)
    }

    fn restore_geometries(
        &self,
        ws: &WindowState,
        session: &crate::session::Session,
    ) -> Vec<Vec<PtyGeometry>> {
        // A restored tab has no lanes: each pane's terminal is its leaf less
        // its titlebar.
        let area = self.area(ws);
        let style = self.layout_style(ws);
        let terminal = |leaf: Rect, panes: usize| {
            crate::pane_partition::partition_leaf(leaf, style.metrics(panes), None).terminal
        };
        session
            .tabs
            .iter()
            .map(|tab| {
                let rectangles = tab.root.leaf_rects(area);
                let pane_count = rectangles.len();
                let mut geometries: Vec<_> = rectangles
                    .into_iter()
                    .map(|leaf| self.pty_geometry_for_terminal(ws, terminal(leaf, pane_count)))
                    .collect();
                if tab.zoomed
                    && let Some(focused_index) =
                        (!geometries.is_empty()).then(|| tab.focus.min(geometries.len() - 1))
                    && let Some(focused) = geometries.get_mut(focused_index)
                {
                    *focused = self.pty_geometry_for_terminal(ws, terminal(area, 1));
                }
                geometries
            })
            .collect()
    }

    fn pane_snapshots_match_current_layout(&self, ws: &WindowState) -> bool {
        if ws.renderer.is_none() || ws.pane_snapshots.len() != ws.pane_snapshot_keys.len() {
            return false;
        }
        let area = self.area(ws);
        let layout = self.pane_layout(ws, area);
        let current = layout.iter().filter_map(|(id, partition)| {
            let pane = ws.mux.panes.get(id)?;
            let (columns, screen_lines) = self.grid_of(ws, partition.terminal);
            Some((*id, pane.term.output_generation(), columns, screen_lines))
        });
        pane_snapshot_keys_match(&ws.pane_snapshot_keys, current)
            && ws
                .pane_snapshot_keys
                .iter()
                .zip(&ws.pane_snapshots)
                .all(|((id, ..), snap)| {
                    ws.mux.panes.get(id).is_some_and(|pane| {
                        snap.captures_card_marks() == pane.inline_cards.needs_marks()
                    })
                })
    }

    fn pane_cursor_layer_eligible(ws: &WindowState) -> bool {
        use kettle_core::CursorShape;
        use kettle_core::TermMode;
        ws.vi_mode.is_none()
            && ws
                .mux
                .active_focus()
                .and_then(|id| ws.mux.panes.get(&id))
                .is_some_and(|pane| {
                    let Ok(term) = pane.term.term.try_lock() else {
                        return false;
                    };
                    let content = term.renderable_content();
                    let row = i64::from(content.cursor.point.line.0)
                        .saturating_add(i64::try_from(content.display_offset).unwrap_or(i64::MAX));
                    !content.mode.contains(TermMode::VI)
                        && content.cursor.shape != CursorShape::Hidden
                        && (0..i64::try_from(term.grid().screen_lines()).unwrap_or(0))
                            .contains(&row)
                })
    }

    fn pane_cursor_blinking(&self, ws: &WindowState, use_pane_snapshots: bool) -> bool {
        pane_cursor_blinking_with(
            ws.mux.active_focus(),
            &ws.pane_snapshot_keys,
            &ws.pane_snapshots,
            use_pane_snapshots,
            |id| {
                ws.mux
                    .panes
                    .get(&id)
                    .map(|pane| pane.term.cursor_blinking())
            },
        )
    }

    /// Which way `split_auto` should cut the focused pane.
    ///
    /// Terminator's rule is the pane's LONGER axis: a wide pane splits into a
    /// left/right pair, a tall one into top/bottom. Every user-facing
    /// description promises this (`docs/CONFIG.md` "pick by aspect ratio", the
    /// palette's "Split automatically", the context-menu row, and the default
    /// Ctrl+Shift+A binding).
    ///
    /// Ties go to a vertical cut, the same as `split_down`, so the default
    /// binding keeps that meaning where the aspect ratio favours neither side.
    fn auto_split_dir(&self, ws: &WindowState) -> Dir {
        let area = self.area(ws);
        let rect = ws
            .mux
            .active_focus()
            .and_then(|focus| {
                ws.mux
                    .leaves(ws.mux.active, area)
                    .into_iter()
                    .find(|(id, _)| *id == focus)
            })
            .map_or(area, |(_, leaf)| leaf);
        if rect.2 > rect.3 {
            Dir::Horizontal
        } else {
            Dir::Vertical
        }
    }

    /// How this window measures its panes: its cells and padding, and the
    /// titlebar a pane shows beside another.
    fn layout_style(&self, ws: &WindowState) -> LayoutStyle {
        let cell = Self::cell_size(ws).unwrap_or((8.0, 16.0));
        let padding = (self.cfg.padding_x, self.cfg.padding_y);
        let titlebar = self
            .cfg
            .show_titlebar
            .then(|| ws.renderer.as_ref().map(|r| r.cell_h + 6.0).unwrap_or(20.0));
        LayoutStyle::new(cell, padding, titlebar, self.cfg.title_at_bottom)
            .or_else(|| LayoutStyle::new((8.0, 16.0), padding, titlebar, self.cfg.title_at_bottom))
            .unwrap_or_else(LayoutStyle::fallback)
    }

    /// The active tab's panes laid out over `area`, each divided between its
    /// titlebar, terminal and preview lane.
    fn pane_layout(&self, ws: &WindowState, area: Rect) -> Vec<(u64, PanePartition)> {
        ws.mux.layout(ws.mux.active, area, self.layout_style(ws))
    }

    /// The partition of `pane_id` in the active tab.
    fn pane_partition(&self, ws: &WindowState, area: Rect, pane_id: u64) -> Option<PanePartition> {
        self.pane_layout(ws, area)
            .into_iter()
            .find(|(id, _)| *id == pane_id)
            .map(|(_, partition)| partition)
    }

    /// The terminal of `pane_id` in the active tab: its grid with the
    /// padding around it, clear of the titlebar and lane.
    fn pane_terminal(&self, ws: &WindowState, area: Rect, pane_id: u64) -> Option<Rect> {
        self.pane_partition(ws, area, pane_id)
            .map(|partition| partition.terminal)
    }

    /// The focused pane's terminal.
    fn focused_terminal(&self, ws: &WindowState, area: Rect) -> Option<Rect> {
        self.pane_terminal(ws, area, ws.mux.active_focus()?)
    }

    /// Terminal pane addressed by a wheel event. Pointer ownership is
    /// independent of keyboard focus: a split under the cursor wins, while
    /// chrome/gaps/out-of-window coordinates fall back to the focused pane.
    /// Modal, tab-bar and Ctrl-zoom handling run before this helper is used.
    fn wheel_target(&self, ws: &WindowState) -> Option<(u64, Rect)> {
        // The pane under the pointer is found by its whole leaf; the wheel
        // then scrolls that pane's terminal.
        let area = self.area(ws);
        let layout = self.pane_layout(ws, area);
        let leaves: Vec<(u64, Rect)> = layout
            .iter()
            .map(|(id, partition)| (*id, partition.leaf))
            .collect();
        let (pane, _) = wheel_target_at(
            &leaves,
            ws.mux.active_focus(),
            ws.cursor.x as f32,
            ws.cursor.y as f32,
        )?;
        layout
            .into_iter()
            .find(|(id, _)| *id == pane)
            .map(|(id, partition)| (id, partition.terminal))
    }

    /// Start a scrollbar drag and return the pointer's offset inside the thumb.
    fn scrollbar_jump(
        &mut self,
        ws: &mut WindowState,
        area: Rect,
        px: f32,
        py: f32,
    ) -> Option<f32> {
        self.scrollbar_at(ws, area, px, py, true, None)
    }

    /// Map a pointer position to a viewport jump on the focused pane's
    /// scrollbar. With `require_zone`, only the DPI-scaled invisible hit strip
    /// counts. During a drag X is ignored and `grab_offset` keeps the pointer at
    /// the same position inside the thumb instead of snapping to its top edge.
    fn scrollbar_at(
        &mut self,
        ws: &mut WindowState,
        area: Rect,
        px: f32,
        py: f32,
        require_zone: bool,
        grab_offset: Option<f32>,
    ) -> Option<f32> {
        if self.cfg.scrollbar == kettle_config::ScrollbarMode::Never {
            return None;
        }
        let (rx, ry, rw, rh) = self.focused_terminal(ws, area)?;
        let scale = ws
            .window
            .as_ref()
            .map(|window| window.scale_factor() as f32)
            .unwrap_or(1.0);
        let painted = self.cfg.scrollbar_width.clamp(2.0, 40.0) * scale;
        let zone = painted.max(12.0 * scale);
        if require_zone && (px < rx + rw - zone || px > rx + rw || py < ry || py > ry + rh) {
            return None;
        }
        let p = ws.mux.focused()?;
        let Ok(mut t) = p.term.term.lock() else {
            return None;
        };
        use kettle_core::Dimensions;
        let g = t.grid();
        let (rows, hist, off) = (g.screen_lines(), g.history_size(), g.display_offset());
        // Interactable whenever there is something to scroll. `Auto` paints the
        // bar whenever history is present (not only while scrolled back), so a
        // click anywhere on the gutter jumps the viewport.
        if rows + hist <= rows {
            return None;
        }
        let (thumb_y, thumb_h) =
            kettle_core::scrollbar::thumb_with_min(rows, hist, off, rh, 24.0 * scale)?;
        let pointer_y = py - ry;
        let grab = grab_offset.unwrap_or_else(|| {
            if (thumb_y..=thumb_y + thumb_h).contains(&pointer_y) {
                pointer_y - thumb_y
            } else {
                thumb_h / 2.0
            }
        });
        let grab = grab.clamp(0.0, thumb_h);
        let target =
            kettle_core::scrollbar::target_offset_for_drag(pointer_y, grab, rh, thumb_h, hist);
        let delta = target as i32 - off as i32;
        if delta != 0 {
            t.scroll_display(kettle_core::Scroll::Delta(delta));
        }
        Some(grab)
    }

    /// Whether `(px, py)` is within the focused pane's scrollbar grab
    /// zone (right edge, painted width floored at 12 logical px). Pure geometry
    /// so it is cheap to call on every `CursorMoved` to drive the
    /// overlay scrollbar's hover-brighten without affecting the scroll state.
    fn scrollbar_zone_contains(&self, ws: &WindowState, area: Rect, px: f32, py: f32) -> bool {
        if self.cfg.scrollbar == kettle_config::ScrollbarMode::Never {
            return false;
        }
        let Some((rx, ry, rw, rh)) = self.focused_terminal(ws, area) else {
            return false;
        };
        let scale = ws
            .window
            .as_ref()
            .map(|window| window.scale_factor() as f32)
            .unwrap_or(1.0);
        let zone = (self.cfg.scrollbar_width.clamp(2.0, 40.0) * scale).max(12.0 * scale);
        px >= rx + rw - zone && px <= rx + rw && py >= ry && py <= ry + rh
    }

    fn px_to_point(
        &self,
        ws: &WindowState,
        rect: Rect,
        px: f32,
        py: f32,
    ) -> (kettle_core::Point, kettle_core::Side) {
        let (cw, ch) = ws
            .renderer
            .as_ref()
            .map(|r| (r.cell_w, r.cell_h))
            .unwrap_or((8.0, 16.0));
        // `rect` is the pane's terminal, clear of its titlebar and lane, so
        // the grid starts inside its padding, as the renderer draws it.
        let (col, line, side) = px_to_cell(
            px,
            py,
            rect,
            (cw, ch),
            (self.cfg.padding_x, self.cfg.padding_y),
        );
        (
            kettle_core::Point::new(kettle_core::Line(line), kettle_core::Column(col)),
            side,
        )
    }

    fn smart_selection_for_cell(
        &self,
        ws: &WindowState,
        row: usize,
        col: usize,
    ) -> Option<(usize, usize)> {
        use kettle_core::Dimensions;
        let pane = ws.mux.panes.get(&ws.mux.active_focus()?)?;
        let term = pane.term.term.lock().ok()?;
        if row >= term.screen_lines() {
            return None;
        }
        let point = viewport_point_to_grid(
            kettle_core::Point::new(kettle_core::Line(row as i32), kettle_core::Column(col)),
            term.grid().display_offset(),
        );
        kettle_core::hints::selection_at(term.grid(), point.line.0, col)
    }

    /// Install a `Simple` selection from `(row, start)` to
    /// `(row, end)` inclusive in the focused pane. Returns true if the
    /// selection was set, false if there's no focused pane or the lock
    /// failed (in which case the caller falls through to its normal
    /// `begin_selection` path).
    fn apply_smart_selection(
        &mut self,
        ws: &mut WindowState,
        area: Rect,
        row: usize,
        start: usize,
        end: usize,
    ) -> bool {
        // `area` is unused but kept in the signature to mirror
        // `begin_selection`'s API; future viewport-aware variants may
        // need it for clamping.
        let _ = area;
        clear_selection_gesture(ws);
        let Some(pane) = ws.mux.focused() else {
            return false;
        };
        let Ok(mut t) = pane.term.term.lock() else {
            return false;
        };
        // The click `row` is viewport-relative; convert both ends to
        // grid-absolute so a double-click word-select while scrolled back
        // selects (and copies) the row the user actually clicked.
        let off = t.grid().display_offset();
        let anchor = viewport_point_to_grid(
            kettle_core::Point::new(kettle_core::Line(row as i32), kettle_core::Column(start)),
            off,
        );
        let end_pt = viewport_point_to_grid(
            kettle_core::Point::new(kettle_core::Line(row as i32), kettle_core::Column(end)),
            off,
        );
        let mut sel = kettle_core::Selection::new(
            kettle_core::SelectionType::Simple,
            anchor,
            kettle_core::Side::Left,
        );
        sel.update(end_pt, kettle_core::Side::Right);
        t.selection = Some(sel);
        // Like Semantic, a smart selection resolves on press; the
        // caller treats `selecting=false` so motion doesn't extend it.
        true
    }

    fn begin_selection(
        &mut self,
        ws: &mut WindowState,
        area: Rect,
        ty: kettle_core::SelectionType,
    ) {
        let dragging = matches!(
            ty,
            kettle_core::SelectionType::Simple | kettle_core::SelectionType::Block
        );
        let Some(pane_id) = ws.mux.active_focus() else {
            clear_selection_gesture(ws);
            return;
        };
        let Some(rect) = self.pane_terminal(ws, area, pane_id) else {
            clear_selection_gesture(ws);
            return;
        };
        let mut installed = false;
        {
            let (vp, side) = self.px_to_point(ws, rect, ws.cursor.x as f32, ws.cursor.y as f32);
            if let Some(pane) = ws.mux.panes.get(&pane_id)
                && let Ok(mut t) = pane.term.term.lock()
            {
                // Store the grid-absolute point (viewport − display_offset)
                // so a selection started while scrolled back anchors on the
                // history row the user sees, not the active screen.
                let p = viewport_point_to_grid(vp, t.grid().display_offset());
                // The anchor carries the pointer's sub-cell side so a Simple/Block
                // drag trims the start cell when the press lands in its right half
                // (Semantic/Lines ignore the side — they snap to token bounds).
                t.selection = Some(kettle_core::Selection::new(ty, p, side));
                installed = true;
            }
        }
        if installed && dragging {
            arm_selection_gesture(ws, pane_id, 0);
        } else {
            clear_selection_gesture(ws);
        }
    }

    /// Click count for the press at `(row,col)` within ~400 ms of the last.
    fn click_count(&mut self, ws: &mut WindowState, row: usize, col: usize) -> u8 {
        let now = std::time::Instant::now();
        let n = match ws.last_click {
            Some((t, r, c, n))
                if r == row
                    && c == col
                    && now.duration_since(t) < std::time::Duration::from_millis(400) =>
            {
                n % 3 + 1
            }
            _ => 1,
        };
        ws.last_click = Some((now, row, col, n));
        n
    }

    /// Open a link taken from pane `pane`'s output. A local file link from a
    /// remote pane is refused with a notification, since the path names a file
    /// on that machine; a pane that has gone counts as remote. Other links open
    /// through [`Self::open_url`].
    fn open_pane_link(&mut self, ws: &mut WindowState, pane: Option<u64>, uri: &str) {
        let origin = pane
            .and_then(|id| ws.mux.panes.get(&id))
            .map(pane_path_origin);
        let tr = self.ui_text;
        match link_gate(uri, origin) {
            LinkGate::Open => self.open_url(ws, uri, LinkSource::Pane(origin)),
            LinkGate::Refuse => fire_notify(
                tr.text(kettle_i18n::Text::NotifyTitleRemoteFileNotOpened),
                &tr.notify_body_remote_file_not_opened(&link_display_name(uri, 48)),
            ),
        }
    }

    /// Open a URL. Unsafe URLs are refused, and Lua URL handlers may claim or
    /// rewrite it first. Then, for Terminator parity
    /// (terminatorlib/config.py:86-87 `use_custom_url_handler` +
    /// `custom_url_handler`), open it via the custom external program if
    /// configured and non-empty, else via the cross-platform `open` crate.
    /// The custom program is invoked as
    ///   <custom_url_handler> <uri>
    /// detached, so kettle doesn't block on the handler exiting.
    /// Errors log::warn.
    fn open_url(&mut self, ws: &WindowState, uri: &str, source: LinkSource) {
        if !kettle_core::links::is_safe_url(uri) {
            warn_refused_terminal_url(uri, |message| log::warn!("{message}"));
            return;
        }
        // Terminator plugin parity: fire
        // `LuaEvent::UrlClicked`. Fired before pattern-handler
        // dispatch so analytics / logging / workflow-trigger
        // plugins see ALL URL clicks, regardless of which
        // handler eventually opens them. The
        // `try_url_handler` chain below still owns the "actually
        // launch" decision; this event is observation-only.
        self.fire_lua_event(
            ws,
            crate::LuaEvent::UrlClicked(uri.to_string()),
            "url_clicked hook",
        );
        // Terminator plugin parity: Lua URL handlers get first dispatch. A
        // handler that claims the URL either handles it itself or returns a
        // URL for the custom-handler / system-open paths below.
        let outcome = self
            .lua_engine
            .as_ref()
            .map(|engine| engine.try_url_handler(uri))
            .unwrap_or(crate::lua::UrlHandlerOutcome::Fallthrough);
        // URL-handler callbacks are distinct from UrlClicked observers and can
        // queue the same side effects. Drain before any claimed-handler return.
        self.drain_lua_hook_commands(ws, "URL handler");
        // A handler may REWRITE the URL — that is the documented contract in
        // `docs/examples/init.lua` and the shape every example there uses.
        let rewritten;
        let uri = match &outcome {
            crate::lua::UrlHandlerOutcome::Handled => return,
            crate::lua::UrlHandlerOutcome::Open(target) => {
                // Re-check the allowlist. The handler is the user's own code,
                // but it is fed untrusted terminal text, so it must not be a
                // way to turn that text into a URL kettle would have refused.
                if !kettle_core::links::is_safe_url(target) {
                    log::warn!("lua url_handler returned an unsafe URL; refusing to open it");
                    return;
                }
                // A handler may turn a web link from a remote pane into a local
                // file link, or a confirmed file into another, so the pane's
                // gate applies to any different link it returns.
                if let LinkSource::Pane(origin) = source
                    && target != uri
                    && link_gate(target, origin) != LinkGate::Open
                {
                    log::warn!(
                        "lua url_handler returned a local file link for a pane whose files \
                         may be elsewhere; refusing to open it"
                    );
                    return;
                }
                rewritten = target.clone();
                rewritten.as_str()
            }
            crate::lua::UrlHandlerOutcome::Fallthrough => uri,
        };
        // A local file link is checked before anything opens it, the custom
        // handler included: a program or a shortcut is refused, since opening
        // it would run it or follow it elsewhere. One that does not decode to
        // a local path is refused here. The check looks at an untrusted path,
        // which can stall on a network mount, so it and the open run off the
        // UI thread.
        if uri
            .get(..7)
            .is_some_and(|scheme| scheme.eq_ignore_ascii_case("file://"))
        {
            let Some(path) = kettle_core::links::local_file_path(uri) else {
                log::warn!("refusing a file link that names no local path");
                return;
            };
            let handler = (self.cfg.use_custom_url_handler
                && !self.cfg.custom_url_handler.is_empty())
            .then(|| self.cfg.custom_url_handler.clone());
            spawn_file_link_opener(path, handler, self.ui_text);
            return;
        }
        if self.cfg.use_custom_url_handler && !self.cfg.custom_url_handler.is_empty() {
            // Custom handler — spawn detached so a long-running
            // browser launch doesn't freeze kettle.
            let cmd = self.cfg.custom_url_handler.clone();
            match spawn_custom_url_handler(&cmd, uri) {
                Ok(_) => return,
                Err(e) => log::warn!("custom-url-handler {cmd:?}: {e}; falling through to system"),
            }
        }
        if let Err(e) = open::that_detached(uri) {
            log::warn!("failed to open a terminal-supplied URL: {e}");
        }
    }

    fn paste_clipboard(&mut self, ws: &mut WindowState) {
        // A copied file arrives as CF_HDROP or `text/uri-list`, not text. Paste
        // its quoted path and translate it for WSL. A text clipboard falls
        // through to the normal paste path below.
        if self.cfg.paste_files.enabled()
            && let Some(paths) = self.clipboard_file_paste_paths()
        {
            let video = self.cfg.paste_video_preview.then(|| {
                crate::video_preview::VideoPasteRequest::from_user_paths(
                    &paths,
                    crate::video_preview::VideoPasteSource::Clipboard,
                )
            });
            self.paste_paths(ws, paths, false, video.flatten());
            return;
        }
        // Bitmap paste: a screenshot puts raw pixels on the clipboard with no
        // file and no text behind it, so neither the file branch nor the text
        // path can see it. Materialize it as a PNG and paste the path, reusing
        // the same shell-quoting / WSL-translation pipeline. Ordered after the
        // file branch so a genuine copied file always wins.
        if self.cfg.paste_images.enabled() && self.paste_clipboard_image(ws) {
            return;
        }
        let text = self
            .clipboard
            .as_mut()
            .and_then(|c| c.get_text().ok())
            .unwrap_or_default();
        self.paste_text(ws, text);
    }

    /// Paste the clipboard's bitmap as the path of a temporary PNG. False
    /// when the clipboard holds no image, or it cannot be stored, so the
    /// paste falls through to text rather than silently doing nothing — the
    /// failure mode this whole path exists to remove.
    ///
    /// A large screenshot takes long enough to encode to stall the window,
    /// so the PNG is made on the encoder thread and the paste waits in
    /// [`App::queued_pastes`], with any made after it.
    fn paste_clipboard_image(&mut self, ws: &mut WindowState) -> bool {
        let Some(image) = self.clipboard.as_mut().and_then(|c| c.get_image().ok()) else {
            return false;
        };
        // Read now: by the time the PNG is ready the clipboard may have changed.
        let fallback = self
            .clipboard
            .as_mut()
            .and_then(|c| c.get_text().ok())
            .filter(|text| local_paste_within_limit(text))
            .unwrap_or_default();
        if !self.paste_queue_admits(fallback.len()) {
            self.report_input_result(PaneInputResult::Oversize);
            return true;
        }
        let png = match self.pasted_images.reserve_png(
            image.width,
            image.height,
            image.bytes.len(),
            self.cfg.paste_image_preview,
        ) {
            Ok(png) => png,
            Err(error) => {
                log::warn!("clipboard image paste failed: {error}");
                return false;
            }
        };
        let id = self.png_jobs;
        self.png_jobs = self.png_jobs.wrapping_add(1);
        let rgba = image.bytes.into_owned();
        let submitted = match self.png_encoder() {
            Some(encoder) => encoder.submit(id, png, rgba),
            None => Err((png, rgba)),
        };
        if let Err((png, rgba)) = submitted {
            // No encoder thread: encode here, as a paste always did once.
            let encoded = png.encode(&rgba, &|| false);
            return match self.pasted_images.keep_png(encoded) {
                Ok(path) => {
                    self.paste_paths(ws, vec![path], false, None);
                    true
                }
                Err(error) => {
                    log::warn!("clipboard image paste failed: {error}");
                    false
                }
            };
        }
        self.queue_paste(
            ws,
            QueuedPasteContent::Image {
                id,
                fallback,
                path: None,
            },
        );
        true
    }

    /// The clipboard-image encoder, started on first use.
    fn png_encoder(&mut self) -> Option<&crate::paste_image::PngEncoder> {
        if self.png_encoder.is_none() {
            let proxy = self.proxy.clone();
            match crate::paste_image::PngEncoder::new(Box::new(move || {
                let _ = proxy.send_event(UserEvent::PastedImageEncoded);
            })) {
                Ok(encoder) => self.png_encoder = Some(encoder),
                Err(error) => log::warn!("clipboard image encoder could not start: {error}"),
            }
        }
        self.png_encoder.as_ref()
    }

    /// Whether one more paste of `bytes` may wait in the queue.
    fn paste_queue_admits(&self, bytes: usize) -> bool {
        let waiting = self
            .queued_pastes
            .iter()
            .map(|paste| paste.content.bytes())
            .fold(bytes, usize::saturating_add);
        self.queued_pastes.len() < QUEUED_PASTES_MAX && waiting <= QUEUED_PASTE_BYTES_MAX
    }

    /// Queue `content` to paste where a paste made now would go, once the
    /// images ahead of it are encoded. Refused when too much is waiting.
    fn queue_paste(&mut self, ws: &WindowState, content: QueuedPasteContent) {
        if !matches!(content, QueuedPasteContent::Image { .. })
            && !self.paste_queue_admits(content.bytes())
        {
            self.discard_queued_paste(content);
            self.report_input_result(PaneInputResult::Oversize);
            return;
        }
        let recipients = self.broadcast_recipients(ws);
        self.queued_pastes.push_back(QueuedPaste {
            window: ws.seq,
            target: paste_target(&ws.mux),
            receipt_pane: ws.mux.active_focus(),
            broadcast: ws.mux.broadcast.clone(),
            recipients,
            content,
        });
    }

    /// Every pane, in this window and the others, that a broadcast from `ws`
    /// reaches now, in order. Empty with broadcast off. `ws` must be checked
    /// out of `self.windows`, as during dispatch.
    fn broadcast_recipients(&self, ws: &WindowState) -> Vec<u64> {
        if !ws.mux.is_broadcast_on() {
            return Vec::new();
        }
        let mut panes = ws.mux.broadcast_target_ids();
        if Mux::scope_crosses_windows(&ws.mux.broadcast) {
            for other in self.windows.values() {
                panes.extend(other.mux.foreign_target_ids(&ws.mux.broadcast));
            }
        }
        panes.sort_unstable();
        panes.dedup();
        panes
    }

    /// Take the PNGs the encoder finished, then deliver the pastes at the
    /// front of the queue that are ready, in order.
    fn drain_queued_pastes(&mut self, el: &ActiveEventLoop) {
        while let Some((id, encoded)) = self.png_encoder.as_ref().and_then(|e| e.try_recv()) {
            let kept = self.pasted_images.keep_png(encoded);
            let waiting =
                self.queued_pastes
                    .iter_mut()
                    .find_map(|paste| match &mut paste.content {
                        QueuedPasteContent::Image {
                            id: queued, path, ..
                        } if *queued == id => Some(path),
                        _ => None,
                    });
            match (waiting, kept) {
                (Some(path), kept) => *path = Some(kept),
                // Its paste is gone, so its PNG goes too.
                (None, Ok(path)) => {
                    let _ = self.pasted_images.remove(&path);
                }
                (None, Err(_)) => {}
            }
        }
        while self
            .queued_pastes
            .front()
            .is_some_and(|paste| !paste.content.encoding())
        {
            let Some(paste) = self.queued_pastes.pop_front() else {
                break;
            };
            self.deliver_queued_paste(el, paste);
        }
    }

    fn deliver_queued_paste(&mut self, el: &ActiveEventLoop, paste: QueuedPaste) {
        let QueuedPaste {
            window,
            target,
            receipt_pane,
            broadcast,
            recipients,
            content,
        } = paste;
        // A single-pane paste follows its pane, which may have changed window.
        let window = target
            .and_then(|pane| {
                self.windows
                    .iter()
                    .find_map(|(&seq, ws)| ws.mux.panes.contains_key(&pane).then_some(seq))
            })
            .unwrap_or(window);
        let Some(mut ws) = self.windows.remove(&window) else {
            self.discard_queued_paste(content);
            return;
        };
        // Broadcast goes where its scope reaches now. A different scope, or
        // the same scope over other panes (another tab, a group that changed),
        // could reach panes the paste was never meant for.
        if ws.mux.broadcast != broadcast || self.broadcast_recipients(&ws) != recipients {
            self.discard_queued_paste(content);
            self.finish_window_dispatch(el, window, ws);
            return;
        }
        match content {
            QueuedPasteContent::Image {
                path: Some(Ok(path)),
                ..
            } => self.paste_paths_to(&mut ws, target, receipt_pane, vec![path], false, None),
            QueuedPasteContent::Image {
                path: Some(Err(error)),
                fallback,
                ..
            } => {
                log::warn!("clipboard image paste failed: {error}");
                self.paste_text_to(&mut ws, target, &fallback);
            }
            QueuedPasteContent::Image { path: None, .. } => {}
            QueuedPasteContent::Text(text) => self.paste_text_to(&mut ws, target, &text),
            QueuedPasteContent::Paths {
                paths,
                trailing_space,
                video,
            } => self.paste_paths_to(&mut ws, target, receipt_pane, paths, trailing_space, video),
        }
        self.finish_window_dispatch(el, window, ws);
    }

    /// Let go of what a paste that will not be delivered holds.
    fn discard_queued_paste(&mut self, content: QueuedPasteContent) {
        match content {
            QueuedPasteContent::Image {
                path: Some(Ok(path)),
                ..
            } => {
                self.pasted_images
                    .discard_previews_for_paths(std::slice::from_ref(&path));
                let _ = self.pasted_images.remove(&path);
            }
            QueuedPasteContent::Paths { paths, .. } => {
                self.pasted_images.discard_previews_for_paths(&paths);
            }
            QueuedPasteContent::Image { .. } | QueuedPasteContent::Text(_) => {}
        }
    }

    /// Read a file list from the clipboard (CF_HDROP on Windows,
    /// `text/uri-list` elsewhere), or `None` if the clipboard holds no files.
    fn clipboard_file_paste_paths(&mut self) -> Option<Vec<std::path::PathBuf>> {
        self.clipboard
            .as_mut()?
            .get()
            .file_list()
            .ok()
            .filter(|paths| !paths.is_empty())
    }

    /// Paste selected X11 text, falling back to the full clipboard pipeline
    /// when PRIMARY is empty or unavailable. Other platforms have one clipboard.
    fn paste_primary(&mut self, ws: &mut WindowState) {
        #[cfg(target_os = "linux")]
        {
            use arboard::{GetExtLinux, LinuxClipboardKind};
            let primary = self
                .clipboard
                .as_mut()
                .and_then(|c| c.get().clipboard(LinuxClipboardKind::Primary).text().ok())
                .filter(|text| !text.is_empty());
            if let Some(text) = primary {
                self.paste_text(ws, text);
                return;
            }
        }
        self.paste_clipboard(ws);
    }

    /// Shared paste path — size validation, broadcast scoping, bracketed-paste
    /// wrap, and stable single-pane targeting. Extracted so `paste_clipboard`
    /// and `paste_primary` (and any future paste channel) can't drift on the
    /// safety/scoping rules.
    fn paste_text(&mut self, ws: &mut WindowState, text: String) {
        if !self.queued_pastes.is_empty() && !text.is_empty() && local_paste_within_limit(&text) {
            self.queue_paste(ws, QueuedPasteContent::Text(text));
            return;
        }
        let target = paste_target(&ws.mux);
        self.paste_text_to(ws, target, &text);
    }

    fn paste_text_to(&mut self, ws: &mut WindowState, target: Option<u64>, text: &str) {
        if text.is_empty() {
            return;
        }
        // Reject rather than silently truncate. A truncated shell command,
        // patch, or encoded file can be more dangerous than no paste, and the
        // explicit notice tells the user to pass the data by file instead.
        if !local_paste_within_limit(text) {
            self.report_input_result(PaneInputResult::Oversize);
            return;
        }
        self.deliver_text_paste(ws, target, text);
    }

    fn deliver_text_paste(&mut self, ws: &mut WindowState, target: Option<u64>, text: &str) {
        self.sync_pane_focus_reports(ws);
        if text.is_empty() {
            return;
        }
        // A paste is user input even when it comes from the pointer.
        self.reset_blink_phase(ws);
        // Broadcast owns a group scope, not one pane. It deliberately ignores
        // the optional single-pane target and retains its per-pane mode
        // encoding plus cross-window named-group fan-out.
        if ws.mux.is_broadcast_on() {
            if let Some(rec) = self.recorder.as_mut() {
                rec.record_marker(&format!("kettle:paste len={}", text.chars().count()));
            }
            let receipt_pane = Self::media_paste_receipt_pane(ws);
            let local = ws.mux.broadcast_paste_delivery(text, receipt_pane);
            Self::dismiss_media_paste_receipt_after_delivery(ws, local);
            let mut result = local.result;
            if crate::mux::Mux::scope_crosses_windows(&ws.mux.broadcast) {
                let scope = ws.mux.broadcast.clone();
                for other in self.windows.values_mut() {
                    let receipt_pane = Self::media_paste_receipt_pane(other);
                    let delivery =
                        other
                            .mux
                            .broadcast_paste_foreign_delivery(&scope, text, receipt_pane);
                    Self::dismiss_media_paste_receipt_after_delivery(other, delivery);
                    result = result.merge(delivery.result);
                }
            }
            self.report_input_result(result);
            return;
        }
        // A broadcast prompt carries no pane id. If its scope was disabled
        // while the modal was open, fail closed instead of choosing focus.
        if target.is_none_or(|id| !ws.mux.panes.contains_key(&id)) {
            return;
        }
        // Record that a paste happened and its length — NEVER the
        // pasted content (a common secret vector). The per-key hook captures
        // the Ctrl+V chord; this marker captures the size without the bytes.
        if let Some(rec) = self.recorder.as_mut() {
            rec.record_marker(&format!("kettle:paste len={}", text.chars().count()));
        }
        if let Some(result) = paste_text_into_target(&mut ws.mux, target, text) {
            self.report_input_result(result);
            if let Some(pane_id) = target {
                Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
            }
        }
    }

    fn paste_paths(
        &mut self,
        ws: &mut WindowState,
        paths: Vec<std::path::PathBuf>,
        trailing_space: bool,
        video: Option<crate::video_preview::VideoPasteRequest>,
    ) {
        if paths.is_empty() {
            return;
        }
        if !self.queued_pastes.is_empty() {
            self.queue_paste(
                ws,
                QueuedPasteContent::Paths {
                    paths,
                    trailing_space,
                    video,
                },
            );
            return;
        }
        let target = paste_target(&ws.mux);
        let receipt_pane = ws.mux.active_focus();
        self.paste_paths_to(ws, target, receipt_pane, paths, trailing_space, video);
    }

    fn paste_paths_to(
        &mut self,
        ws: &mut WindowState,
        target: Option<u64>,
        receipt_pane: Option<u64>,
        paths: Vec<std::path::PathBuf>,
        trailing_space: bool,
        video: Option<crate::video_preview::VideoPasteRequest>,
    ) {
        let argv = target
            .and_then(|pane| ws.mux.panes.get(&pane))
            .map_or_else(|| ws.mux.focused_argv(), |pane| pane.argv.clone());
        let mut preview = crate::mux::format_paths_for_paste(&argv, &paths);
        if trailing_space {
            preview.push(' ');
        }
        let within_limit = if ws.mux.is_broadcast_on() {
            ws.mux
                .broadcast_paste_paths_within_limit(&paths, trailing_space, LOCAL_PASTE_MAX)
                && (!Mux::scope_crosses_windows(&ws.mux.broadcast)
                    || self.windows.values().all(|other| {
                        other.mux.broadcast_paste_paths_foreign_within_limit(
                            &ws.mux.broadcast,
                            &paths,
                            trailing_space,
                            LOCAL_PASTE_MAX,
                        )
                    }))
        } else {
            local_paste_within_limit(&preview)
        };
        if !within_limit {
            self.pasted_images.discard_previews_for_paths(&paths);
            self.report_input_result(PaneInputResult::Oversize);
            return;
        }

        self.deliver_path_paste(ws, target, receipt_pane, &paths, trailing_space, video);
    }

    fn deliver_path_paste(
        &mut self,
        ws: &mut WindowState,
        target: Option<u64>,
        receipt_pane: Option<u64>,
        paths: &[std::path::PathBuf],
        trailing_space: bool,
        video: Option<crate::video_preview::VideoPasteRequest>,
    ) {
        self.sync_pane_focus_reports(ws);
        // Path delivery authors new terminal input. Keep the old receipt only
        // long enough to coalesce the separate DroppedFile events one OS drag
        // emits; every other outcome drops it here.
        let previous = Self::take_media_paste_state_on_input(ws);
        self.reset_blink_phase(ws);
        if ws.mux.is_broadcast_on() {
            if let Some(recorder) = self.recorder.as_mut() {
                recorder.record_marker(&format!("kettle:paste paths={}", paths.len()));
            }
            let scope = ws.mux.broadcast.clone();
            let mut delivery = ws.mux.broadcast_paste_paths_delivery(
                paths,
                trailing_space,
                LOCAL_PASTE_MAX,
                receipt_pane,
            );
            if Mux::scope_crosses_windows(&scope) {
                for other in self.windows.values_mut() {
                    delivery = delivery.merge(other.mux.broadcast_paste_paths_foreign_delivery(
                        &scope,
                        paths,
                        trailing_space,
                        LOCAL_PASTE_MAX,
                    ));
                }
            }
            self.report_input_result(delivery.result);
            self.show_media_paste_receipt(
                ws,
                receipt_pane,
                paths,
                delivery.receipt_accepted,
                video,
                previous,
            );
            return;
        }

        if target.is_none_or(|id| !ws.mux.panes.contains_key(&id)) {
            self.show_media_paste_receipt(ws, receipt_pane, paths, false, video, previous);
            return;
        }
        if let Some(recorder) = self.recorder.as_mut() {
            recorder.record_marker(&format!("kettle:paste paths={}", paths.len()));
        }
        match paste_paths_into_target(&mut ws.mux, target, paths, trailing_space) {
            Some(delivery) => {
                self.report_input_result(delivery.result);
                self.show_media_paste_receipt(
                    ws,
                    receipt_pane,
                    paths,
                    delivery.receipt_accepted,
                    video,
                    previous,
                );
            }
            None => self.show_media_paste_receipt(ws, receipt_pane, paths, false, video, previous),
        }
    }

    fn show_media_paste_receipt(
        &mut self,
        ws: &mut WindowState,
        receipt_pane: Option<u64>,
        paths: &[std::path::PathBuf],
        accepted_by_receipt_pane: bool,
        video: Option<crate::video_preview::VideoPasteRequest>,
        previous: (
            Option<crate::window_state::MediaPasteReceiptState>,
            Option<crate::window_state::PendingVideoPasteReceipt>,
        ),
    ) {
        let (previous_receipt, previous_pending) = previous;
        let image_preview = if paths.len() == 1 {
            // Move bounded pixels out even when presentation is rejected. A
            // managed PNG gets one chance to create a receipt.
            self.pasted_images.take_preview_for_path(&paths[0])
        } else {
            self.pasted_images.discard_previews_for_paths(paths);
            None
        };
        if !accepted_by_receipt_pane {
            ws.media_paste_receipt = previous_receipt;
            ws.pending_video_paste_receipt = previous_pending;
            if ws.media_paste_receipt.is_some() {
                ws.accessibility_pending = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            log::debug!("media paste receipt skipped: initiating pane did not accept the path");
            return;
        }
        let Some(pane_id) = receipt_pane.filter(|id| ws.mux.panes.contains_key(id)) else {
            log::debug!("media paste receipt skipped: initiating pane is no longer live");
            return;
        };
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            log::debug!("media paste receipt skipped: initiating pane lookup failed");
            return;
        };
        let remote = pane.remote_context.is_some();
        let prefer_top = pane.term.term.lock().ok().is_some_and(|term| {
            let cursor_row = term.renderable_content().cursor.point.line.0.max(0) as usize;
            cursor_row >= term.screen_lines() / 2
        });
        let now = std::time::Instant::now();
        let handled = if let Some(preview) = image_preview.filter(|_| self.cfg.paste_image_preview)
        {
            ws.media_paste_receipt = Some(crate::window_state::MediaPasteReceiptState::new_image(
                pane_id,
                paths[0].clone(),
                preview,
                remote,
                prefer_top,
                now,
            ));
            true
        } else if let Some(request) = video.filter(|_| self.cfg.paste_video_preview) {
            if let Some(mut pending) = previous_pending
                && pending.merge_drop(pane_id, &request, now)
            {
                ws.pending_video_paste_receipt = Some(pending);
                true
            } else {
                let generation = self.next_video_preview_generation;
                self.next_video_preview_generation = generation.wrapping_add(1).max(1);
                let queued =
                    self.video_previewer
                        .request(ws.seq, pane_id, generation, request.clone());
                if queued {
                    ws.pending_video_paste_receipt =
                        Some(crate::window_state::PendingVideoPasteReceipt {
                            pane_id,
                            generation,
                            request,
                            remote,
                            prefer_top,
                            created_at: now,
                            previous_receipt,
                        });
                }
                queued
            }
        } else {
            false
        };
        if !handled {
            log::debug!("media paste receipt skipped: no eligible preview payload");
            return;
        }
        ws.accessibility_pending = true;
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        log::debug!("media paste receipt queued or shown for pane {pane_id}");
    }

    fn copy_selection(&mut self, ws: &mut WindowState) {
        let target = ws.selecting_pane.or_else(|| ws.mux.active_focus());
        let sel = target
            .and_then(|id| ws.mux.panes.get(&id))
            .and_then(|p| {
                p.term
                    .term
                    .lock()
                    .ok()
                    .and_then(|t| t.selection_to_string())
            })
            .filter(|s| !s.is_empty());
        let sel = match copy_clipboard_decision(sel, true) {
            Ok(selection) => selection,
            Err(error) => {
                log::warn!("selection copy: could not prepare text: {error}");
                return;
            }
        };
        if let (Some(s), Some(cb)) = (sel, self.clipboard.as_mut()) {
            // On Linux also write the X11 PRIMARY selection that `paste_primary`
            // reads, so the select→middle-click-paste loop works. No PRIMARY on
            // Wayland/macOS/Windows; those keep clipboard-only.
            #[cfg(target_os = "linux")]
            {
                use arboard::{LinuxClipboardKind, SetExtLinux};
                if let Err(e) = cb
                    .set()
                    .clipboard(LinuxClipboardKind::Primary)
                    .text(s.clone())
                {
                    log::warn!("clipboard set PRIMARY failed (selection copy): {e}");
                }
            }
            // Log clipboard failures so a broken clipboard is diagnosable,
            // matching the vi-mode yank path.
            if let Err(e) = cb.set_text(s) {
                log::warn!("clipboard set_text failed (selection copy): {e}");
            }
        }
    }

    /// Commit copy-on-select before another UI surface takes pointer ownership,
    /// then disarm every selection gesture latch. The ordering matters because
    /// `copy_selection` uses `selecting_pane` to preserve the pane the drag
    /// started in rather than whichever pane gained focus meanwhile.
    fn finish_selection_gesture(&mut self, ws: &mut WindowState) {
        if self.cfg.copy_on_select
            && selection_copy_owner(ws.selecting, ws.selecting_pane).is_some()
        {
            self.copy_selection(ws);
        }
        clear_selection_gesture(ws);
    }

    fn install_confirm_dialog(&mut self, ws: &mut WindowState, dialog: ConfirmDialogState) {
        // A confirmation takes exclusive pointer ownership just like every
        // other modal. Commit a completed selection before ending its gesture;
        // otherwise the visible highlight survives while copy-on-select is
        // silently lost.
        self.finish_selection_gesture(ws);
        ws.card_press = None;
        // And the keyboard, from a preview lane holding it.
        self.exit_preview_focus(ws);
        ws.confirm_dialog = Some(dialog);
    }

    fn update_selection(&mut self, ws: &mut WindowState, area: Rect) {
        if !ws.selecting {
            return;
        }
        let Some(pane_id) = ws.selecting_pane else {
            self.finish_selection_gesture(ws);
            return;
        };
        let Some(rect) = self.pane_terminal(ws, area, pane_id) else {
            // A tab switch can make the owning pane temporarily absent from
            // the active layout while its selection is still available in
            // the mux. Commit copy-on-select before dropping that ownership.
            self.finish_selection_gesture(ws);
            return;
        };
        let (vp, side) = self.px_to_point(ws, rect, ws.cursor.x as f32, ws.cursor.y as f32);
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            // A removed pane has nothing left to copy, but using the shared
            // transition keeps invalidation ordered with every other exit.
            self.finish_selection_gesture(ws);
            return;
        };
        if let Ok(mut t) = pane.term.term.lock() {
            // Convert to grid-absolute before the mutable `selection`
            // borrow so the dragged end-point tracks scrollback too.
            let p = viewport_point_to_grid(vp, t.grid().display_offset());
            if let Some(sel) = t.selection.as_mut() {
                // The drag end carries the pointer's sub-cell side so the
                // boundary cell is included only once the pointer crosses its
                // midpoint (xterm/Alacritty parity) — not always.
                sel.update(p, side);
            }
        }
    }

    fn begin_or_extend_mouse_selection(&mut self, ws: &mut WindowState, area: Rect) {
        // The grid press is the newer gesture: drop any editor selection so
        // the search bar's Copy shortcut reaches the grid selection instead.
        if ws.search.open {
            ws.search.editor.clear_selection();
        }
        if ws.mods.shift_key() && !ws.mods.alt_key() && self.extend_selection_to_cursor(ws, area, 0)
        {
            return;
        }
        let cell = self.cursor_cell(ws);
        let clicks = cell.map(|(r, c)| self.click_count(ws, r, c)).unwrap_or(1);
        let kind = selection_kind(clicks, ws.mods.alt_key());
        let mut smart_selected = false;
        if clicks == 2
            && !ws.mods.alt_key()
            && let Some((row, col)) = cell
            && let Some((start, end)) = self.smart_selection_for_cell(ws, row, col)
            && self.apply_smart_selection(ws, area, row, start, end)
        {
            smart_selected = true;
        }
        if !smart_selected {
            self.begin_selection(ws, area, kind);
        }
        if self.cfg.copy_on_select
            && (smart_selected
                || matches!(
                    kind,
                    kettle_core::SelectionType::Semantic | kettle_core::SelectionType::Lines
                ))
        {
            self.copy_selection(ws);
        }
    }

    /// Extend the existing selection to the cursor point (Shift+Click).
    /// Returns `true` when a selection was present *and* extended — the
    /// caller falls back to a fresh `begin_selection` when no selection
    /// existed (so Shift+Click on empty space starts a normal selection).
    /// Matches xterm / Alacritty / iTerm2: Shift+Click anchors the
    /// existing selection's start and pulls the end to the click.
    /// Where the pointer is against the focused pane's selection: `None`
    /// when nothing is selected (the empty selection a click leaves is
    /// nothing), else whether the pointer is on it.
    fn pointer_on_selection(&self, ws: &WindowState, area: Rect) -> Option<bool> {
        let rect = self.focused_terminal(ws, area)?;
        let (vp, _) = self.px_to_point(ws, rect, ws.cursor.x as f32, ws.cursor.y as f32);
        let pane = ws.mux.active_focus().and_then(|id| ws.mux.panes.get(&id))?;
        let term = pane.term.term.lock().ok()?;
        let point = viewport_point_to_grid(vp, term.grid().display_offset());
        let range = term.selection.as_ref()?.to_range(&term)?;
        Some(range.contains(point))
    }

    fn extend_selection_to_cursor(&mut self, ws: &mut WindowState, area: Rect, button: u8) -> bool {
        let rect = match self.focused_terminal(ws, area) {
            Some(r) => r,
            None => return false,
        };
        let (vp, side) = self.px_to_point(ws, rect, ws.cursor.x as f32, ws.cursor.y as f32);
        if let Some(pane_id) = ws.mux.active_focus() {
            let extended = if let Some(pane) = ws.mux.panes.get(&pane_id)
                && let Ok(mut t) = pane.term.term.lock()
            {
                // Grid-absolute end-point so Shift+Click extends to the
                // right history row while scrolled back.
                let p = viewport_point_to_grid(vp, t.grid().display_offset());
                if let Some(sel) = t.selection.as_mut() {
                    // Sub-cell side so Shift+Click lands the boundary on the
                    // same half-cell rule as a drag.
                    sel.update(p, side);
                    true
                } else {
                    false
                }
            } else {
                false
            };
            if extended {
                // Enter drag mode so a follow-up mouse-move keeps extending —
                // matches every Mac/Linux text-control: shift-click, then drag.
                arm_selection_gesture(ws, pane_id, button);
                return true;
            }
        }
        false
    }

    /// Resize every pane's PTY to match its tile in the layout.
    fn resize_all(&mut self, ws: &mut WindowState) {
        // Never synthesize a layout from the helper fallbacks while the
        // renderer is temporarily absent during GPU recovery. Existing PTYs
        // retain their last good geometry; the atomic renderer rebuild calls
        // this once with the real surface and fractional cell metrics.
        if ws.renderer.is_none() {
            return;
        }
        let (cw, ch) = self.cell_px(ws);
        let fractional_cell = ws
            .renderer
            .as_ref()
            .map(|r| (r.cell_w, r.cell_h))
            .unwrap_or((f32::from(cw), f32::from(ch)));
        let area = self.area(ws);
        let mut plan: Vec<(u64, usize, usize, u16, u16)> = Vec::new();
        let style = self.layout_style(ws);
        for ti in 0..ws.mux.tabs.len() {
            // Each PTY gets the rows and columns of its pane's terminal, clear
            // of its titlebar and lane.
            for (id, partition) in ws.mux.layout(ti, area, style) {
                let (cols, rows) = self.grid_of(ws, partition.terminal);
                let (pixel_width, pixel_height) = pty_pixel_size(fractional_cell, (cols, rows));
                plan.push((id, cols, rows, pixel_width, pixel_height));
            }
        }
        let mut native_resize_failed = false;
        for (id, cols, rows, pixel_width, pixel_height) in plan {
            if let Some(p) = ws.mux.panes.get_mut(&id)
                && let Err(error) = p.term.try_resize_geometry(PtyGeometry::new(
                    cols,
                    rows,
                    pixel_width,
                    pixel_height,
                ))
            {
                native_resize_failed = true;
                log::warn!(
                    "pane {id} PTY resize failed; a bounded deadline retry is scheduled: {error:#}"
                );
            }
        }
        ws.pty_resize_retry
            .record_result(std::time::Instant::now(), native_resize_failed);
        // The window, its font or its splits changed what a zoomed lane
        // shows.
        self.lanes_moved(ws);
    }

    /// Shared zoom transition for `Action::ToggleZoom` and
    /// `Action::ScaledZoom`. Both actions flip the SAME `ws.mux` zoom flag, so
    /// they must share `ws.scaled_zoom_prev_font_size`. Otherwise a plain
    /// `ToggleZoom` could un-zoom a pane that `ScaledZoom` had enlarged without
    /// restoring the font or clearing the stale baseline, leaving the pane
    /// un-zoomed but oversized and corrupting any later `ScaledZoom` call's
    /// save/restore pairing.
    ///
    /// `scale` is `Some(factor)` for `ScaledZoom`, which bumps the live font by
    /// `factor` on zoom-in and saves the pre-bump size the first time. It is
    /// `None` for plain `ToggleZoom`, which never bumps the font on zoom-in.
    /// Either action, on zoom-*out*, restores the font from
    /// `scaled_zoom_prev_font_size` and clears it if a scaled-zoom baseline is
    /// pending, so the pairing never desyncs whichever action toggled the flag.
    fn toggle_zoom_with_scale(&mut self, ws: &mut WindowState, scale: Option<f32>) {
        ws.mux.toggle_zoom();
        let now_zoomed = ws.mux.is_zoomed();
        if let Some(r) = ws.renderer.as_mut() {
            if now_zoomed {
                if let Some(factor) = scale {
                    // Baseline off the LIVE renderer size, not
                    // `self.cfg.font_size`. Increase/DecreaseFontSize only
                    // call `r.set_font_size` (they never write
                    // `cfg.font_size`), so a prior manual zoom left the
                    // config value stale — scaling from it would otherwise
                    // discard the user's manual zoom on restore.
                    let cur = r.font_size();
                    if ws.scaled_zoom_prev_font_size.is_none() {
                        ws.scaled_zoom_prev_font_size = Some(cur);
                    }
                    let new_size = (cur * factor).clamp(6.0, 96.0);
                    r.set_font_size(new_size);
                }
            } else if let Some(prev) = ws.scaled_zoom_prev_font_size.take() {
                r.set_font_size(prev);
            }
        }
        // Grid and pixel geometry must be derived after any scaled-zoom font
        // change. Resizing first would leave the PTY at the previous cell
        // metrics until an unrelated resize event, so TUIs and CSI 14 t would
        // disagree with the pixels actually rendered.
        self.resize_all(ws);
    }

    fn apply_window_resize(&mut self, ws: &mut WindowState, width: u32, height: u32) {
        // Never reconfigure a dead surface. A Resized event after a GPU device
        // loss would otherwise drive a surface configure on the lost device. The
        // grid resize below still runs so the layout is correct if the user
        // reopens.
        let gpu_lost = self.gpu.as_ref().is_some_and(|g| g.is_lost());
        if !gpu_lost
            && !ws.frame_recovery.renderer_rebuild_pending()
            && let Some(r) = ws.renderer.as_mut()
        {
            r.resize(width, height);
        }
        self.reclamp_context_menu(ws, (width as f32, height as f32));
        self.resize_all(ws);
        let show_chip = match self.cfg.resize_overlay {
            kettle_config::ResizeOverlayMode::Never => false,
            kettle_config::ResizeOverlayMode::Always => true,
            kettle_config::ResizeOverlayMode::AfterFirst => {
                ws.seen_first_resize
                    && ws.spawned_at.elapsed() > std::time::Duration::from_millis(1500)
            }
        };
        ws.seen_first_resize = true;
        if show_chip {
            let (cols, rows) = self.grid_of(ws, self.area(ws));
            ws.resize_overlay = Some((cols as u16, rows as u16, std::time::Instant::now()));
        }
    }

    fn commit_window_resize(&mut self, ws: &mut WindowState, width: u32, height: u32) {
        ws.frame_recovery.expedite(std::time::Instant::now());
        self.apply_window_resize(ws, width, height);
        // Record the new grid size into the asciicast trace.
        if self.recorder.is_some() {
            let (cols, rows) = self.grid_of(ws, self.area(ws));
            if let Some(rec) = self.recorder.as_mut() {
                rec.record_resize(cols as u16, rows as u16);
            }
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    fn dpi_resize_renderer_ready(&self, ws: &WindowState) -> bool {
        ws.renderer.is_some()
            && !self.gpu.as_ref().is_some_and(|gpu| gpu.is_lost())
            && !ws.frame_recovery.renderer_rebuild_pending()
    }

    /// Fan one destructive drain of the shared PTY-output sidechannel out to
    /// every enabled consumer. Both redraw-time and close-time drains must use
    /// this path; otherwise whichever path receives a chunk first can starve
    /// recorder or Lua output hooks of the same bytes.
    fn dispatch_output_chunks(
        &mut self,
        _ws: &mut WindowState,
        output_chunks: Vec<(u64, Vec<u8>)>,
    ) {
        for (pane_id, bytes) in output_chunks {
            if let Some(rec) = self.recorder.as_mut() {
                rec.record_output(&bytes);
            }
            self.fire_lua_event(_ws, crate::LuaEvent::Output(pane_id, bytes), "output hook");
        }
        let body = self
            .ui_text
            .text(kettle_i18n::Text::NotifyBodyRecordingWriteFailed);
        self.sync_recording_state(_ws, body);
    }

    fn sync_session_log_failures(&self, ws: &WindowState) {
        for (&pane_id, pane) in &ws.mux.panes {
            let Some(failure) = pane.term.take_session_log_failure() else {
                continue;
            };
            let tr = &self.ui_text;
            let body = match failure {
                kettle_core::SessionLogFailure::Overloaded => {
                    tr.notify_body_session_log_overloaded(pane_id)
                }
                kettle_core::SessionLogFailure::IoError => tr.notify_body_session_log_io(pane_id),
            };
            fire_notify(
                tr.text(kettle_i18n::Text::NotifyTitleSessionLogStopped),
                &body,
            );
        }
    }

    fn drain_events(&mut self, ws: &mut WindowState) {
        self.sync_session_log_failures(ws);
        let mut bell = false;
        // Pane ids that fired `TermEvent::Bell` this drain
        // pass — latched onto their containing tabs *after* the
        // iter_mut() loop so we don't double-borrow mux.panes.
        let mut bell_panes: Vec<u64> = Vec::new();
        // Pane ids + raw-output chunks accumulated during this drain pass.
        // Keep the PTY reader's bounded chunks intact instead of concatenating
        // a whole backlog into a second potentially huge allocation.
        let mut output_chunks: Vec<(u64, Vec<u8>)> = Vec::new();
        // Collect OSC-133 CommandFinished events per
        // pane so the App is the SINGLE drainer — `drain_command_finished_events`
        // is destructive, so the command-notify, the run_command correlator, and
        // event subscribers must all be fed from one place, AFTER this pane loop.
        let mut command_finished_local: Vec<(u64, kettle_core::CommandFinished)> = Vec::new();
        // Protocol desktop notifications (OSC 9 / OSC 777) drained once per
        // pass and dispatched after the pane loop so the UI owns all toasts.
        let mut protocol_notifications_local: Vec<(u64, kettle_core::ProtocolNotification)> =
            Vec::new();
        // Pane ids whose shell exited with cfg.exit_action
        // = Restart. Queued during the drain; appended to
        // ws.pending_pane_restarts after the iteration so the
        // post-drain handler can process them with a fresh borrow.
        let mut pending_restarts_local: Vec<u64> = Vec::new();
        for (&pane_id, pane) in ws.mux.panes.iter_mut() {
            if pane.term.event_queue_overflowed() || pane.pty_input_failed() {
                log::error!(
                    "closing pane {pane_id}: bounded terminal event/input transport failed"
                );
                pane.closed = true;
                while pane.rx.try_recv().is_ok() {}
                continue;
            }
            // Drain the optional output sidechannel before regular events.
            if let Some(out_rx) = &pane.output_rx {
                while let Ok(chunk) = out_rx.try_recv() {
                    output_chunks.push((pane_id, chunk));
                }
            }
            while let Ok(ev) = pane.rx.try_recv() {
                match ev {
                    TermEvent::Title(t) => {
                        // Ignore the bogus full-exe-path title conhost/
                        // ConPTY injects at startup for a native Windows shell —
                        // keeping the "kettle" placeholder so the tab/window/pane
                        // label falls back to the working directory (the OSC 7/9;9
                        // cwd, else the natively-polled cwd) instead of showing an
                        // ugly `…\pwsh.exe` path. Only a still-placeholder pane is
                        // checked; ANY genuine OSC 2 title (incl. a later one from
                        // the shell's own prompt) is stored and permanently ends
                        // suppression, so a program-set title is never lost.
                        if pane.title_is_placeholder && is_conhost_startup_title(&t, &pane.argv) {
                            // keep the placeholder seed; do not store the exe path
                        } else {
                            apply_shell_title(
                                &mut pane.title,
                                &mut pane.title_is_placeholder,
                                &mut pane.title_origin,
                                &mut pane.title_before_remote,
                                Some(&t),
                            );
                        }
                    }
                    TermEvent::ResetTitle => {
                        apply_shell_title(
                            &mut pane.title,
                            &mut pane.title_is_placeholder,
                            &mut pane.title_origin,
                            &mut pane.title_before_remote,
                            None,
                        );
                    }
                    TermEvent::PtyWrite(s) => {
                        if !pane.queue_protocol_reply(s.as_bytes()).is_queued() {
                            log::error!("closing pane {pane_id}: bounded PTY input queue failed");
                            pane.closed = true;
                            break;
                        }
                    }
                    TermEvent::ClipboardStore(target, s) => {
                        // Normalize complete card clusters before clipping so a
                        // byte limit cannot leave a partial placeholder behind.
                        if self.cfg.osc52.can_copy()
                            && let Some(cb) = &mut self.clipboard
                        {
                            match prepare_osc52_copy(s, OSC52_MAX) {
                                Ok(text) => {
                                    if let Err(error) = set_osc52_clipboard(cb, target, text) {
                                        log::warn!(
                                            "clipboard write failed (OSC 52 {target:?} target): {error}"
                                        );
                                    }
                                }
                                Err(error) => log::warn!("OSC 52: could not prepare text: {error}"),
                            }
                        }
                    }
                    TermEvent::ClipboardLoad(target, fmt) => {
                        // OSC 52 read lets a (remote) program exfiltrate the
                        // clipboard; denied by default — reply empty so the
                        // protocol stays well-formed without leaking.
                        let text = if self.cfg.osc52.can_paste() {
                            self.clipboard
                                .as_mut()
                                .and_then(|c| match get_osc52_clipboard(c, target) {
                                    Ok(text) => Some(text),
                                    Err(error) => {
                                        log::warn!(
                                            "clipboard read failed (OSC 52 {target:?} target): \
                                             {error}"
                                        );
                                        None
                                    }
                                })
                                .unwrap_or_default()
                        } else {
                            String::new()
                        };
                        // Bound the reply symmetrically with the write path
                        // above: the OS clipboard is outside kettle's control
                        // (a big log/diff/webpage copy is plausible with no
                        // attacker involved, and a malicious remote program
                        // querying via OSC 52 `?` shouldn't be able to force an
                        // unbounded base64 encode + single PTY write either
                        // way).
                        let text = clamp_osc52(&text, OSC52_MAX);
                        let reply = fmt(text);
                        if !pane.queue_protocol_reply(reply.as_bytes()).is_queued() {
                            log::error!("closing pane {pane_id}: bounded PTY input queue failed");
                            pane.closed = true;
                            break;
                        }
                    }
                    TermEvent::TextAreaSizeRequest(fmt) => {
                        // CSI 14 t — text-area size in pixels. Sixel / kitty
                        // graphics / iTerm2-OSC-1337 apps probe this to do
                        // pixel-perfect image placements. Use the exact totals
                        // already published through PtySize: at fractional DPI
                        // a 9.6 px cell across 100 columns is 960 px, not the
                        // 1000 px produced by multiplying a rounded 10 px cell.
                        let (pixel_width, pixel_height) = pane.term.pty_pixel_size();
                        let reply = kettle_render::reply_for_text_area_size(
                            pixel_width,
                            pixel_height,
                            &*fmt,
                        );
                        if !pane.queue_protocol_reply(reply.as_bytes()).is_queued() {
                            log::error!("closing pane {pane_id}: bounded PTY input queue failed");
                            pane.closed = true;
                            break;
                        }
                    }
                    TermEvent::ColorRequest(idx, fmt) => {
                        // OSC 4 ; n ; ? / OSC 10 / 11 / 12 — resolve against
                        // the active theme + any runtime overrides, then let
                        // the engine-supplied formatter render the canonical
                        // xparsecolor reply and write it back to the PTY. No
                        // reply for out-of-range indices keeps the protocol
                        // well-formed (apps that probe just see a timeout,
                        // exactly as on terminals that don't support OSC).
                        let reply = pane.term.term.lock().ok().and_then(|t| {
                            kettle_render::reply_for_query(idx, &self.cfg.theme, t.colors(), &*fmt)
                        });
                        if let Some(s) = reply
                            && !pane.queue_protocol_reply(s.as_bytes()).is_queued()
                        {
                            log::error!("closing pane {pane_id}: bounded PTY input queue failed");
                            pane.closed = true;
                            break;
                        }
                    }
                    TermEvent::CursorBlinkingChange => {
                        // DEC mode 12 (`CSI ?12 h/l`) just flipped. The next
                        // redraw picks up the new state from
                        // `Terminal::cursor_blinking()`, but reset the blink
                        // phase now so *blink-on* starts visible and
                        // *blink-off* makes the cursor solid right away, not on
                        // whatever half-period we'd otherwise land in. It is
                        // program output, so it does not restart the blink
                        // timeout; only typing, focus, and settings do.
                        ws.blink_on = true;
                        ws.last_blink = std::time::Instant::now();
                    }
                    // Terminator parity (terminatorlib/
                    // config.py:103 `force_no_bell`): silence every
                    // bell flavor regardless of cfg.bell mode. The
                    // match-guard combines the variant + the cfg
                    // check so a future tweak doesn't fight clippy's
                    // collapsible-if lint.
                    TermEvent::Bell if !self.cfg.force_no_bell => {
                        bell = true;
                        bell_panes.push(pane_id);
                    }
                    TermEvent::Bell => {}
                    // Terminator parity (terminatorlib/config.py:118
                    // `exit_action`): when the shell exits, close the pane,
                    // restart the shell, or hold the dead shell visible so the
                    // user can read its final output and scrollback.
                    //
                    // Hold: don't mark closed; the pane shows its last output
                    // until the user closes it (Ctrl+Shift+W).
                    // Restart: mark closed and queue the pane id so this loop
                    // never double-borrows ws.mux; the post-drain handler
                    // respawns the same argv and cwd in a new tab.
                    // Close (default): mark closed.
                    TermEvent::Exit => {
                        // The reader emits this only after preceding PTY bytes
                        // have crossed its bounded parser queue. `Mux::reap`
                        // keys off this latch instead of polling the process,
                        // so a fast child cannot disappear before its final
                        // output or exit policy is applied.
                        apply_pane_exit_action(
                            self.cfg.exit_action,
                            pane_id,
                            pane,
                            &mut pending_restarts_local,
                        );
                    }
                    TermEvent::ChildExit(_) => {
                        // Process status is advisory, not a pane-lifecycle
                        // boundary. alacritty_terminal can publish ChildExit
                        // before its final PTY drain; only the ordered Exit
                        // event above may apply exit policy or make this pane
                        // reapable.
                    }
                    _ => {}
                }
            }
            #[cfg(windows)]
            if !pane.exit_observed
                && let Some(child_exit_at) = pane.term.direct_child_exit_at()
            {
                let now = std::time::Instant::now();
                let phase = match pane.pty_output_close_phase {
                    PtyOutputClosePhase::NotStarted => BoundedPtyExitPhase::NotStarted,
                    PtyOutputClosePhase::InProgress(started) => {
                        BoundedPtyExitPhase::InProgress(now.saturating_duration_since(started))
                    }
                    PtyOutputClosePhase::Failed { retry_at } => BoundedPtyExitPhase::Failed {
                        retry_in: retry_at.saturating_duration_since(now),
                    },
                };
                match bounded_pty_exit_action(now.saturating_duration_since(child_exit_at), phase) {
                    BoundedPtyExitAction::Wait => {}
                    BoundedPtyExitAction::BeginClose => {
                        log::warn!(
                            "PTY output stayed open after pane {pane_id}'s direct child exited; \
                             starting bounded ConPTY close"
                        );
                        match pane.term.begin_pty_output_close() {
                            Ok(_) => {
                                pane.pty_output_close_phase =
                                    PtyOutputClosePhase::InProgress(std::time::Instant::now())
                            }
                            Err(error) => {
                                log::error!("cannot close pane {pane_id}'s ConPTY output: {error}");
                                pane.pty_output_close_phase = PtyOutputClosePhase::Failed {
                                    retry_at: std::time::Instant::now()
                                        + std::time::Duration::from_secs(1),
                                };
                            }
                        }
                    }
                    BoundedPtyExitAction::ApplyPolicy => {
                        // Older ConPTY builds may park ClosePseudoConsole while
                        // an inherited client remains attached. The close
                        // worker is detached specifically for that platform
                        // behavior; do not let it also park GUI exit policy.
                        log::error!(
                            "pane {pane_id}'s PTY did not finish within the bounded drain; final \
                             output may be incomplete"
                        );
                        apply_pane_exit_action(
                            self.cfg.exit_action,
                            pane_id,
                            pane,
                            &mut pending_restarts_local,
                        );
                    }
                }
            }
            if pane.term.event_queue_overflowed() || pane.pty_input_failed() {
                log::error!(
                    "closing pane {pane_id}: bounded terminal event/input transport failed"
                );
                pane.closed = true;
                while pane.rx.try_recv().is_ok() {}
            }
            // Drain OSC 133 D (CommandEnd) events ONCE here and
            // defer processing to after the pane loop, where the App can fan a
            // single drain out to the command-notify, the run_command
            // correlator, and event subscribers (each consumer would otherwise
            // race for the destructive drain). Always drain (not gated on the
            // notify threshold) so a pending run_command still resolves when
            // notifications are off.
            for ev in pane.term.drain_command_finished_events() {
                command_finished_local.push((pane_id, ev));
            }
            for ev in pane.term.drain_protocol_notifications() {
                protocol_notifications_local.push((pane_id, ev));
            }
        }
        if bell {
            if self.cfg.bell.visual() {
                // Only the pane that rang flashes; a sibling split's bell
                // then tells you which one it was. Panes outside the current
                // layout keep the tab dot and titlebar glyph as their cue.
                let now = std::time::Instant::now();
                for id in &bell_panes {
                    ws.bell_flashes.insert(*id, now);
                }
            }
            if self.cfg.bell.attention()
                && !ws.window_focused
                && let Some(w) = &ws.window
            {
                w.request_user_attention(Some(UserAttentionType::Informational));
                ws.attention_active = true;
            }
        }
        // Latch any per-pane bells onto their tab's
        // activity flag so the tab-bar dot survives even on tabs the
        // user isn't currently looking at. Active-tab bells were
        // already handled visually (`bell_flashes` above drives the
        // per-pane flash); the latching helper skips the active
        // tab so we don't double-signal.
        //
        // Terminator plugin parity:
        // fire LuaEvent::Bell(pane_id) for every belled pane after
        // the kettle-side bell handling is done. Callbacks may queue
        // LuaCommands (kettle.notify, kettle.send_text); they get
        // transferred immediately into the bounded App FIFO by
        // `fire_lua_event`, then dispatched in order on the event loop.
        // `fire_lua_event` drains through `drain_lua_hook_commands`, the one
        // canonical LuaCommand-match path that every Lua hook shares.
        for id in bell_panes {
            ws.mux.touch_tab_bell(id);
            self.fire_lua_event(ws, crate::LuaEvent::Bell(id), "bell hook");
        }
        // The focused pane is being looked at, so its bell is answered.
        //
        // Deliberately here rather than on focus-change events: focus moves by
        // far more routes than those fire on — a tab switch, `reap` promoting a
        // sibling when the focused shell exits, the ctl API, a layout restore —
        // and every one of them would have to remember. This runs each drain
        // against the true current focus, so none of them can leave the latch
        // lit on a pane the user is staring at.
        ws.mux.clear_focused_pane_bell();
        // A single destructive drain fans out to Lua and the
        // optional recorder so neither consumer can steal bytes from the other.
        self.dispatch_output_chunks(ws, output_chunks);
        // Fan out the OSC-133 CommandFinished events
        // drained above — command-notify (existing behavior), the run_command
        // correlator, and event subscribers all from this single place.
        for (pane_id, ev) in command_finished_local {
            // (a) Desktop notification for a long background command.
            if self.cfg.command_notify_threshold_ms > 0 {
                let elapsed_ms = ev.duration.as_millis() as u64;
                if !ws.window_focused && elapsed_ms >= self.cfg.command_notify_threshold_ms {
                    let secs = ev.duration.as_secs();
                    let tr = &self.ui_text;
                    let exit_text = match ev.exit_code {
                        Some(0) => tr.text(kettle_i18n::Text::NotifyBodyCommandOk).to_string(),
                        Some(code) => tr.notify_body_command_exit(&code.to_string()),
                        None => String::new(),
                    };
                    let body = if exit_text.is_empty() {
                        tr.notify_body_command_ran(pane_id, secs)
                    } else {
                        tr.notify_body_command_result(pane_id, secs, &exit_text)
                    };
                    fire_notify(
                        tr.text(kettle_i18n::Text::NotifyTitleCommandFinished),
                        &body,
                    );
                }
            }
            // (b) Resolve a pending run_command for this pane.
            self.resolve_pending_run(ws, pane_id, &ev);
            // (c) Notify event subscribers.
            self.ctl_broadcast(
                "command_finished",
                Some(pane_id),
                serde_json::json!({
                    "exit_code": ev.exit_code,
                    "duration_ms": ev.duration.as_millis() as u64,
                }),
            );
        }
        for (pane_id, ev) in protocol_notifications_local {
            fire_notify(&ev.title, &ev.body);
            if !ws.window_focused
                && let Some(w) = &ws.window
            {
                w.request_user_attention(Some(UserAttentionType::Informational));
                ws.attention_active = true;
            }
            self.ctl_broadcast(
                "protocol_notification",
                Some(pane_id),
                serde_json::json!({
                    "title": ev.title,
                    "body": ev.body,
                }),
            );
        }
        // Stash the restart list on the window so the post-drain handler can
        // process it with a fresh &mut ws.mux borrow. The pane loop above holds a
        // &mut iterator into ws.mux.panes, so spawn_pane can't run there.
        if !pending_restarts_local.is_empty() {
            ws.pending_pane_restarts.extend(pending_restarts_local);
        }
    }

    fn process_pending_pane_restarts(&mut self, ws: &mut WindowState) {
        if ws.pending_pane_restarts.is_empty() {
            return;
        }
        let pane_ids: Vec<u64> = std::mem::take(&mut ws.pending_pane_restarts);
        let waker = self.waker();
        let (cols, rows) = self.grid_of(ws, self.area(ws));
        let geometry = self.pty_geometry_for_grid(ws, cols, rows);
        for pane_id in pane_ids {
            let restart_info: Option<(Vec<String>, Option<String>)> = ws
                .mux
                .panes
                .get(&pane_id)
                .map(|pane| (pane.argv.clone(), pane.term.current_dir_or_native()));
            if let Some((argv, cwd)) = restart_info {
                if let Err(error) = ws.mux.new_tab_with_geometry(
                    &self.cfg,
                    geometry,
                    waker.clone(),
                    &argv,
                    cwd.as_deref(),
                ) {
                    log::warn!("exit-action = restart: spawn failed for pane {pane_id}: {error}");
                } else {
                    self.fire_tab_add_event(ws);
                }
            }
        }
    }

    /// Fan out PTY output still queued in
    /// the shared output sidechannels right now. Output that lands after the
    /// last redraw drain and before a pane is reaped or its window closes would
    /// otherwise be lost to both the recorder and Lua hooks. Call this before
    /// `mux.reap()` and on close so both consumers keep their tail. Recorder
    /// events batch on the bounded persistence worker; clean close paths hand
    /// finalization to that worker.
    fn flush_recorder_output(&mut self, ws: &mut WindowState) {
        // Always drain what's queued right now (cheap, non-blocking).
        self.drain_recorder_output_once(ws);
        // A pane marked `closed` (its shell exited under exit-action = close /
        // restart) is about to be reaped + its sidechannel dropped. The PTY
        // reader may still be teeing the shell's FINAL output: the child-exit
        // signal can beat the reader's last write, so a sub-frame-lifetime
        // session (e.g. `-e cmd /c echo x`) would lose its output entirely.
        // Give the reader a brief BOUNDED window to finish, draining as we go.
        // Bounded to ~60 ms worst case and gated on a closed pane being present,
        // so steady-state frames (and exit-action = hold dead panes, which keep
        // `closed = false`) pay nothing. Early-out after 3 idle rounds.
        let mut idle = 0u8;
        let mut rounds = 0u8;
        while rounds < 30
            && ws
                .mux
                .panes
                .values()
                .any(|p| p.closed && p.output_rx.is_some())
        {
            std::thread::sleep(std::time::Duration::from_millis(2));
            if self.drain_recorder_output_once(ws) {
                idle = 0;
            } else {
                idle += 1;
                if idle >= 3 {
                    break;
                }
            }
            rounds += 1;
        }
    }

    /// Drain every pane's shared output sidechannel and fan each chunk out to
    /// the recorder and Lua once. Returns whether any bytes were captured.
    /// Keep this active after recorder startup failure: Lua may still be
    /// subscribed to the same destructive channel.
    fn drain_recorder_output_once(&mut self, ws: &mut WindowState) -> bool {
        // Collect first (immutable borrow of the panes), then dispatch through
        // `self` after that borrow ends.
        let mut tail: Vec<(u64, Vec<u8>)> = Vec::new();
        for (&pane_id, pane) in &ws.mux.panes {
            if let Some(rx) = &pane.output_rx {
                while let Ok(chunk) = rx.try_recv() {
                    tail.push((pane_id, chunk));
                }
            }
        }
        let got = !tail.is_empty();
        self.dispatch_output_chunks(ws, tail);
        got
    }

    fn recording_status(&self) -> Option<crate::dev_record::RecordStatus> {
        effective_record_status(
            self.recorder.as_ref().map(|rec| rec.status()),
            self.recording_start_failed,
        )
    }

    /// Reflect terminal recorder failures in both persistent window state and
    /// an edge-triggered desktop notification during the same event-loop turn.
    fn sync_recording_state(&mut self, ws: &mut WindowState, io_error_body: &str) {
        let status = self.recording_status();
        if matches!(
            status,
            Some(
                crate::dev_record::RecordStatus::Overloaded
                    | crate::dev_record::RecordStatus::IoError
            )
        ) && !self.recording_error_reported
        {
            self.recording_error_reported = true;
            let tr = &self.ui_text;
            let (title, body) = if status == Some(crate::dev_record::RecordStatus::Overloaded) {
                (
                    tr.text(kettle_i18n::Text::NotifyTitleRecordingStopped),
                    tr.text(kettle_i18n::Text::NotifyBodyRecordingOverloaded),
                )
            } else {
                (
                    tr.text(kettle_i18n::Text::NotifyTitleRecordingError),
                    io_error_body,
                )
            };
            fire_notify(title, body);
        }
        self.sync_window_title(ws);
    }

    /// Keep the OS window title in sync with the *active* pane's title —
    /// including after tab/focus switches, not only on OSC title events.
    /// Deduped so it isn't a syscall every frame.
    fn sync_window_title(&mut self, ws: &mut WindowState) {
        let want = self.desired_window_title(ws);
        if want != ws.last_title {
            if let Some(w) = &ws.window {
                w.set_title(&want);
            }
            ws.last_title = want;
        }
    }

    fn desired_window_title(&self, ws: &WindowState) -> String {
        let pane = ws.mux.active_focus().and_then(|id| ws.mux.panes.get(&id));
        let title = pane.map(|p| p.title.as_str()).unwrap_or("kettle");
        // OSC 7/9;9 cwd if the shell reported one, else the natively
        // polled cwd — so the OS window title tracks the directory for a stock
        // pwsh/cmd just like the tab label does.
        let cwd = pane
            .and_then(|p| p.term.current_dir_or_native())
            .unwrap_or_default();
        let tab = ws.mux.active + 1;
        let want = match &ws.window_title_override {
            Some(forced) => sanitize_title(forced),
            None => window_title(&self.cfg.window_title_format, title, &cwd, tab),
        };
        // An always-visible recording indicator in the title bar so the
        // recorder is never silently capturing (and `[REC RAW]` when raw
        // keystroke capture is on). Keep it ASCII because Linux window-manager
        // title fonts do not reliably carry symbol glyphs.
        let raw = self.recorder.as_ref().is_some_and(|rec| rec.raw_input());
        let want = recording_window_title(want, self.recording_status(), raw);
        // New media on the focused pane's shelf, in ASCII like the
        // recording mark, until the user opens it.
        let unseen = pane.map_or(0, |pane| pane.media_shelf.unseen());
        let want = if unseen > 0 {
            format!(
                "{} {want}",
                self.ui_text.window_title_new_media(unseen as u64)
            )
        } else {
            want
        };
        let want = sanitize_native_window_title(&want);
        if self.gpu_software_fallback {
            format!(
                "{want} - {}",
                self.ui_text
                    .text(kettle_i18n::Text::WindowTitleSoftwareFallback)
            )
        } else {
            want
        }
    }

    fn start_gpu_incident_if_needed(&mut self) {
        if self.gpu_incident_started_for_loss {
            return;
        }
        self.gpu_incident_started_for_loss = true;
        let Some(gpu) = self.gpu.as_ref() else {
            return;
        };
        let cache = cache_dir_from_env(|key| std::env::var(key).ok());
        match IncidentLog::start(
            cache.as_deref(),
            &self.version_line,
            gpu.adapter_info(),
            gpu.fault(),
        ) {
            Ok(log) => {
                log::warn!("GPU fault diagnostics: {}", log.path().display());
                self.gpu_incident = Some(log);
            }
            Err(error) => {
                log::warn!("GPU fault diagnostics unavailable: {error}");
            }
        }
    }

    fn stash_renderer_for_gpu_recovery(ws: &mut WindowState) {
        Self::retire_cursor_layer(ws);
        let live = ws.renderer.as_ref().map(Renderer::recovery_state);
        retain_renderer_recovery_snapshot(&mut ws.renderer_recovery, live);
        ws.renderer = None;
    }

    fn finish_gpu_renderer_recovery(&mut self, ws: &mut WindowState) {
        ws.renderer_recovery = None;
        // The accent claim may have changed while the window had no renderer.
        crate::window_accent::apply_accent(ws);
        ws.frame_recovery.clear();
        ws.pending_output_gen.clear();
        ws.pane_snapshots.clear();
        ws.pane_snapshot_keys.clear();
        ws.reuse_pane_snapshots_once = false;
        ws.output_pacer.reset();
        ws.flood_paints = 0;
        ws.last_paint = None;

        // Recompute every pane grid from the replacement renderer's restored
        // live font/cell metrics. The constructor already configured the
        // surface at the current window size and scale; RendererRebuilt also
        // resolves any DPI transition that arrived while the device was lost.
        let Some(window) = ws.window.as_ref() else {
            return;
        };
        let size = window.inner_size();
        self.reclamp_context_menu(ws, (size.width as f32, size.height as f32));
        if ws.dpi_resize_surface_suspended {
            return;
        }
        if ws.dpi_resize.on_event(DpiResizeEvent::RendererRebuilt {
            width: size.width,
            height: size.height,
        }) == DpiResizeAction::ApplyLayout
        {
            self.resize_all(ws);
        }
    }

    /// Recreate one window's surface and retained renderer resources while
    /// keeping the healthy process-wide adapter/device/queue. wgpu 30 requires
    /// this for `CurrentSurfaceTexture::Lost`; it is also the bounded repair
    /// path for non-device renderer errors whose retained damage keys may have
    /// advanced before a fallible glyph preparation step.
    fn try_recover_window_renderer(&mut self, ws: &mut WindowState) -> Result<(), String> {
        let Some(gpu) = self.gpu.as_ref() else {
            return Err("shared GPU context is unavailable".to_string());
        };
        if gpu.is_lost() {
            return Err("shared GPU device is lost".to_string());
        }
        let Some(window) = ws.window.clone() else {
            return Err("window is unavailable".to_string());
        };
        let Some(old_renderer) = ws.renderer.as_ref() else {
            return Err("window renderer is unavailable".to_string());
        };

        let recovery_state = old_renderer.recovery_state();
        let size = window.inner_size();
        let scale = window.scale_factor() as f32;
        let mut replacement = Renderer::new_with_gpu(
            gpu,
            window,
            size.width.max(1),
            size.height.max(1),
            scale,
            &self.cfg,
            None,
        )
        .map_err(|error| error.to_string())?;

        // These values can diverge from Config at runtime (font zoom, cell
        // scaling, and the resolved per-window accent). A queued screenshot
        // also owns a ctl completion sender that must survive the rebuild.
        replacement.restore_recovery_state(&recovery_state);

        // Commit only after the replacement is fully initialized. A failed
        // candidate leaves the old renderer in place while the state machine
        // backs off and tries again.
        Self::retire_cursor_layer(ws);
        ws.renderer = Some(replacement);
        crate::window_accent::apply_accent(ws);
        self.reclamp_context_menu(ws, (size.width as f32, size.height as f32));
        if ws.dpi_resize_surface_suspended {
            return Ok(());
        }
        if ws.dpi_resize.on_event(DpiResizeEvent::RendererRebuilt {
            width: size.width,
            height: size.height,
        }) == DpiResizeAction::ApplyLayout
        {
            self.resize_all(ws);
        }
        Ok(())
    }

    fn try_recover_gpu(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        escalation: kettle_render::AdapterEscalation,
        attempt: u32,
    ) -> Result<GpuRecoveryOutcome, String> {
        let Some(window) = ws.window.clone() else {
            return Err("primary window is unavailable".to_string());
        };
        let avoid = self.gpu.as_ref().map(|gpu| gpu.adapter_key());
        log::warn!("GPU recovery attempt {attempt} ({escalation:?})");

        Self::stash_renderer_for_gpu_recovery(ws);
        for other in self.windows.values_mut() {
            Self::stash_renderer_for_gpu_recovery(other);
        }

        let cfg = self.cfg.clone();
        let size = window.inner_size();
        let scale = window.scale_factor() as f32;
        let mut new_renderer = match pollster::block_on(
            kettle_render::Renderer::new_with_escalation_and_display_handle(
                window.clone(),
                event_loop.owned_display_handle(),
                size.width.max(1),
                size.height.max(1),
                scale,
                &cfg,
                kettle_render::AdapterSelection::new(escalation, avoid),
            ),
        ) {
            Ok(renderer) => renderer,
            Err(err) => {
                log::error!("GPU recovery: renderer rebuild failed: {err}");
                return Err(err.to_string());
            }
        };
        if let Some(snapshot) = ws.renderer_recovery.as_ref() {
            new_renderer.restore_recovery_state(snapshot);
        }
        let new_gpu = new_renderer.gpu().clone();
        let targets = self.windows.values().filter_map(|other| {
            let window = other.window.clone()?;
            let size = window.inner_size();
            let scale = window.scale_factor() as f32;
            Some((
                other.seq,
                (window, size, scale, other.renderer_recovery.clone()),
            ))
        });
        let secondary_renderers = build_recovery_set(targets, |(window, size, scale, snapshot)| {
            let mut renderer = kettle_render::Renderer::new_with_gpu(
                &new_gpu,
                window,
                size.width.max(1),
                size.height.max(1),
                scale,
                &cfg,
                None,
            )
            .map_err(|error| error.to_string())?;
            if let Some(snapshot) = snapshot.as_ref() {
                renderer.restore_recovery_state(snapshot);
            }
            Ok::<_, String>(renderer)
        })
        .map_err(|errors| {
            for (seq, error) in &errors {
                log::error!(
                    "GPU recovery: window {seq} could not rebind to the new device: {error}"
                );
            }
            format!(
                "{} secondary window renderer(s) could not rebind: {}",
                errors.len(),
                errors
                    .into_iter()
                    .map(|(seq, error)| format!("window {seq}: {error}"))
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        })?;

        // Commit the replacement only after every live window can present on
        // the candidate adapter. A partial commit would leave some windows
        // permanently blank and stop the escalation loop on a "success".
        ws.renderer = Some(new_renderer);
        let secondary_seqs: Vec<u64> = secondary_renderers.iter().map(|(seq, _)| *seq).collect();
        for (seq, renderer) in secondary_renderers {
            if let Some(other) = self.windows.get_mut(&seq) {
                other.renderer = Some(renderer);
            }
        }
        self.gpu_software_fallback = new_gpu.is_software();
        let adapter = new_gpu.adapter_info();
        let adapter_name = new_gpu.adapter_name();
        let recovery_proxy = self.proxy.clone();
        new_gpu.set_recovery_wake(kettle_render::ScreenshotRecoveryWake::new(move || {
            let _ = recovery_proxy.send_event(UserEvent::Wakeup);
        }));
        self.gpu = Some(new_gpu);

        self.finish_gpu_renderer_recovery(ws);
        for seq in secondary_seqs {
            let Some(mut other) = self.windows.remove(&seq) else {
                continue;
            };
            self.finish_gpu_renderer_recovery(&mut other);
            self.windows.insert(seq, other);
        }

        log::info!(
            "GPU recovery succeeded on {} (software={})",
            adapter_name,
            self.gpu_software_fallback
        );

        if !window_is_render_hidden(ws)
            && let Some(window) = &ws.window
        {
            window.request_redraw();
        }
        for other in self.windows.values() {
            if !window_is_render_hidden(other)
                && let Some(window) = &other.window
            {
                window.request_redraw();
            }
        }
        Ok(GpuRecoveryOutcome {
            adapter,
            secondary_window_failures: 0,
        })
    }

    fn update_search(&mut self, ws: &mut WindowState) {
        if !ws.search.open {
            return;
        }
        const TYPING_SEARCH_LINES: usize = 1_000;
        const BACKGROUND_CHUNK_LINES: usize = 1_000;
        const VISIBLE_CONTEXT_LINES: i32 = 100;
        const MAX_LOGICAL_LINE_EXPANSION: usize = kettle_core::MAX_SEARCH_LOGICAL_LINE_CONTEXT;

        let Some(pane_id) = ws.search.target_pane else {
            self.close_search(ws);
            return;
        };
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            self.close_search(ws);
            return;
        };

        // Compile untrusted input before taking the terminal-grid lock. Compilation has explicit
        // engine limits, but it still does allocation and Unicode automata construction that must
        // not delay the PTY reader.
        if ws.search.compiled_revision != Some(ws.search.revision) {
            let query = ws.search.query().to_string();
            match kettle_core::CompiledSearch::compile(
                &query,
                map_case_sensitivity(ws.search.case_mode),
            ) {
                Ok(compiled) => {
                    ws.search.compiled = compiled;
                    ws.search.compiled_revision = Some(ws.search.revision);
                    ws.search.status = if query.is_empty() {
                        kettle_render::SearchStatus::Typing
                    } else {
                        kettle_render::SearchStatus::Searching
                    };
                }
                Err(error) => {
                    ws.search.compiled = None;
                    ws.search.compiled_revision = Some(ws.search.revision);
                    ws.search.status = search_compile_error_status(error);
                }
            }
        }
        if ws.search.compiled.is_none() {
            ws.search.visible.clear();
            ws.search.visible_scan = None;
            ws.search.visible_turn_pending = false;
            // Empty and rejected patterns have no deferred work. Leaving a due retry armed makes
            // about_to_wait request a 1 ms redraw forever even though every frame exits here.
            ws.search.background = None;
            ws.search.unlimited_retry_at = None;
            ws.search.quiet_retry_pending = false;
            return;
        }

        let output_generation = pane.term.output_generation();
        let Ok(mut term) = pane.term.term.lock() else {
            ws.search.set_status_at(
                kettle_render::SearchStatus::Searching,
                std::time::Instant::now(),
            );
            return;
        };
        use kettle_core::Dimensions as _;

        let now = std::time::Instant::now();
        let top_line = term.topmost_line().0;
        let bottom_line = term.bottommost_line().0;
        let last_column = term.last_column().0;
        let screen_lines = term.screen_lines();
        let display_offset = term.grid().display_offset();
        let default_direction = if ws.search.invert {
            kettle_core::SearchDirection::Reverse
        } else {
            kettle_core::SearchDirection::Forward
        };
        let current_token =
            kettle_core::SearchScanToken::capture(&term, ws.search.revision, output_generation);

        // Reflow invalidates grid coordinates and restarts from the viewport. Plain PTY output is
        // different: retain a chunked job and advance its token so a process that prints every
        // few milliseconds cannot keep a deep-history search behind the 500 ms typing debounce.
        // An output-drifted exhausted pass is verified again after the stream becomes quiet before
        // we claim No match/Start/End.
        if let Some(previous_token) = ws.search.scan_token
            && previous_token != current_token
        {
            ws.search.focused = None;
            ws.search.revealed_focus = None;
            ws.search.visible.clear();
            ws.search.visible_scan = None;
            ws.search.visible_key = None;
            let reflowed = previous_token.query_revision != current_token.query_revision
                || previous_token.layout.columns != current_token.layout.columns
                || previous_token.layout.screen_lines != current_token.layout.screen_lines;
            let rejected = matches!(
                ws.search.status,
                kettle_render::SearchStatus::Invalid
                    | kettle_render::SearchStatus::TooComplex
                    | kettle_render::SearchStatus::TooLong
            );
            if reflowed {
                ws.search.typing_scanned_revision = None;
                ws.search.background = None;
                ws.search.anchor = Some(search_viewport_anchor(
                    display_offset,
                    screen_lines,
                    last_column,
                    default_direction,
                ));
                ws.search.unlimited_retry_at = (!rejected && !ws.search.query().is_empty())
                    .then_some(if ws.search.quiet_retry_pending {
                        now + std::time::Duration::from_millis(500)
                    } else {
                        now
                    });
            } else if let Some(job) = ws.search.background.as_mut() {
                continue_background_after_output(
                    job,
                    current_token,
                    top_line,
                    bottom_line,
                    last_column,
                );
                if !job.navigation {
                    ws.search.typing_scanned_revision = None;
                }
            } else {
                ws.search.typing_scanned_revision = None;
                ws.search.anchor = Some(search_viewport_anchor(
                    display_offset,
                    screen_lines,
                    last_column,
                    default_direction,
                ));
                ws.search.unlimited_retry_at = (!rejected && !ws.search.query().is_empty())
                    .then_some(if ws.search.quiet_retry_pending {
                        now + std::time::Duration::from_millis(500)
                    } else {
                        now
                    });
            }
            if !rejected && !ws.search.query().is_empty() {
                ws.search.set_status_at(
                    kettle_render::SearchStatus::Searching,
                    std::time::Instant::now(),
                );
            }
        }
        ws.search.scan_token = Some(current_token);
        ws.search.anchor.get_or_insert_with(|| {
            search_viewport_anchor(display_offset, screen_lines, last_column, default_direction)
        });

        let prioritize_visible = std::mem::take(&mut ws.search.visible_turn_pending);
        let mut foreground_scan_ran = false;
        let mut nearby_yielded_this_turn = false;

        // Live typing stays bounded to nearby history. The endpoint is expanded
        // to the logical line boundary so a regex can cross every soft wrap in
        // that line without crossing a hard newline.
        if !prioritize_visible && should_start_nearby_search(&ws.search) {
            let anchor = ws.search.anchor.expect("search anchor initialized");
            let edge = bounded_search_edge(
                anchor,
                default_direction,
                top_line,
                bottom_line,
                last_column,
                TYPING_SEARCH_LINES,
            );
            let edge = match default_direction {
                kettle_core::SearchDirection::Forward => {
                    kettle_core::search::bounded_line_search_right(
                        &term,
                        edge,
                        MAX_LOGICAL_LINE_EXPANSION,
                    )
                    .0
                }
                kettle_core::SearchDirection::Reverse => {
                    kettle_core::search::bounded_line_search_left(
                        &term,
                        edge,
                        MAX_LOGICAL_LINE_EXPANSION,
                    )
                    .0
                }
            };
            let result = ws
                .search
                .compiled
                .as_mut()
                .expect("compiled search checked")
                .find_in_range(
                    &term,
                    kettle_core::SearchBounds::new(anchor, edge),
                    default_direction,
                    1,
                );
            foreground_scan_ran = true;
            ws.search.focused = (!result.accuracy_limited)
                .then(|| result.matches.first().copied())
                .flatten();
            ws.search.revealed_focus = None;
            if result.accuracy_limited {
                ws.search.typing_scanned_revision = Some(ws.search.revision);
                if ws
                    .search
                    .background
                    .as_ref()
                    .is_some_and(|job| !job.navigation)
                {
                    ws.search.background = None;
                }
                ws.search.status = kettle_render::SearchStatus::Limited;
                ws.search.unlimited_retry_at = None;
            } else if ws.search.focused.is_some() {
                ws.search.typing_scanned_revision = Some(ws.search.revision);
                if ws
                    .search
                    .background
                    .as_ref()
                    .is_some_and(|job| !job.navigation)
                {
                    ws.search.background = None;
                }
                ws.search.status = kettle_render::SearchStatus::Match;
                ws.search.unlimited_retry_at = None;
            } else if let Some(cursor) = result.continuation {
                ws.search.background = Some(crate::search_input::BackgroundSearch {
                    token: current_token,
                    direction: default_direction,
                    cursor,
                    edge,
                    wrap_anchor: anchor,
                    wrapped: false,
                    nearby: true,
                    navigation: false,
                    had_focus: false,
                    output_drifted: false,
                });
                nearby_yielded_this_turn = true;
                ws.search.set_status_at(
                    kettle_render::SearchStatus::Searching,
                    std::time::Instant::now(),
                );
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            } else {
                ws.search.typing_scanned_revision = Some(ws.search.revision);
                let at_edge = match default_direction {
                    kettle_core::SearchDirection::Forward => edge.line >= bottom_line,
                    kettle_core::SearchDirection::Reverse => edge.line <= top_line,
                };
                if at_edge {
                    if ws.search.wrap {
                        ws.search.set_status_at(
                            kettle_render::SearchStatus::Searching,
                            std::time::Instant::now(),
                        );
                    } else {
                        ws.search.status = kettle_render::SearchStatus::NoMatch;
                        ws.search.unlimited_retry_at = None;
                    }
                } else {
                    ws.search.set_status_at(
                        kettle_render::SearchStatus::Searching,
                        std::time::Instant::now(),
                    );
                }
            }
        }

        // After 500 ms idle, continue in logical-line-aligned chunks. Only one
        // chunk runs per event-loop turn. A reflow or query change cancels
        // stale work; plain output advances the job's scan token instead.
        let background_due = !prioritize_visible
            && !foreground_scan_ran
            && !nearby_yielded_this_turn
            && (ws.search.background.is_some()
                || ws
                    .search
                    .unlimited_retry_at
                    .is_some_and(|deadline| now >= deadline));
        let quiet_retry_due = background_due
            && ws.search.background.is_none()
            && ws.search.quiet_retry_pending
            && ws
                .search
                .unlimited_retry_at
                .is_some_and(|deadline| now >= deadline);
        if quiet_retry_due {
            activate_quiet_search_retry(&mut ws.search);
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        } else if background_due && (ws.search.background.is_some() || ws.search.focused.is_none())
        {
            if ws.search.background.is_none() {
                let anchor = ws.search.anchor.expect("search anchor initialized");
                let searched_edge = bounded_search_edge(
                    anchor,
                    default_direction,
                    top_line,
                    bottom_line,
                    last_column,
                    TYPING_SEARCH_LINES,
                );
                let searched_edge = match default_direction {
                    kettle_core::SearchDirection::Forward => {
                        kettle_core::search::bounded_line_search_right(
                            &term,
                            searched_edge,
                            MAX_LOGICAL_LINE_EXPANSION,
                        )
                        .0
                    }
                    kettle_core::SearchDirection::Reverse => {
                        kettle_core::search::bounded_line_search_left(
                            &term,
                            searched_edge,
                            MAX_LOGICAL_LINE_EXPANSION,
                        )
                        .0
                    }
                };
                let edge = match default_direction {
                    kettle_core::SearchDirection::Forward => {
                        kettle_core::SearchPoint::new(bottom_line, last_column)
                    }
                    kettle_core::SearchDirection::Reverse => {
                        kettle_core::SearchPoint::new(top_line, 0)
                    }
                };
                if let Some(cursor) = search_point_after(
                    searched_edge,
                    default_direction,
                    top_line,
                    bottom_line,
                    last_column,
                ) {
                    ws.search.background = Some(crate::search_input::BackgroundSearch {
                        token: current_token,
                        direction: default_direction,
                        cursor,
                        edge,
                        wrap_anchor: anchor,
                        wrapped: false,
                        nearby: false,
                        navigation: false,
                        had_focus: false,
                        output_drifted: false,
                    });
                } else if ws.search.wrap {
                    ws.search.background = wrapped_background_search(
                        current_token,
                        default_direction,
                        anchor,
                        (top_line, bottom_line, last_column),
                        false,
                        false,
                        false,
                    );
                    if ws.search.background.is_some() {
                        ws.search.set_status_at(
                            kettle_render::SearchStatus::Searching,
                            std::time::Instant::now(),
                        );
                    } else {
                        ws.search.status = kettle_render::SearchStatus::NoMatch;
                    }
                } else {
                    ws.search.status = kettle_render::SearchStatus::NoMatch;
                }
                ws.search.unlimited_retry_at = None;
            }

            if let Some(mut job) = ws.search.background.take()
                && job.token == current_token
            {
                let chunk_edge = bounded_search_edge(
                    job.cursor,
                    job.direction,
                    top_line,
                    bottom_line,
                    last_column,
                    BACKGROUND_CHUNK_LINES,
                );
                let expanded_chunk_edge = match job.direction {
                    kettle_core::SearchDirection::Forward => {
                        kettle_core::search::bounded_line_search_right(
                            &term,
                            chunk_edge,
                            MAX_LOGICAL_LINE_EXPANSION,
                        )
                        .0
                    }
                    kettle_core::SearchDirection::Reverse => {
                        kettle_core::search::bounded_line_search_left(
                            &term,
                            chunk_edge,
                            MAX_LOGICAL_LINE_EXPANSION,
                        )
                        .0
                    }
                };
                let chunk_edge = match job.direction {
                    kettle_core::SearchDirection::Forward => expanded_chunk_edge.min(job.edge),
                    kettle_core::SearchDirection::Reverse => expanded_chunk_edge.max(job.edge),
                };
                let result = ws
                    .search
                    .compiled
                    .as_mut()
                    .expect("compiled search checked")
                    .find_in_range(
                        &term,
                        kettle_core::SearchBounds::new(job.cursor, chunk_edge),
                        job.direction,
                        1,
                    );
                foreground_scan_ran = true;
                if result.accuracy_limited {
                    // Exact highlights inside bounded chunks are still safe, but an omitted
                    // cross-boundary match could precede them. Do not advertise a wrong
                    // first/next result or wrap past it.
                    ws.search.status = kettle_render::SearchStatus::Limited;
                } else if let Some(found) = result.matches.first().copied() {
                    ws.search.focused = Some(found);
                    ws.search.revealed_focus = None;
                    ws.search.status = if job.output_drifted {
                        // The span exists in the currently locked grid, but output between
                        // earlier chunks can make its global first/next ordering uncertain.
                        kettle_render::SearchStatus::Limited
                    } else if job.wrapped {
                        kettle_render::SearchStatus::Wrapped
                    } else {
                        kettle_render::SearchStatus::Match
                    };
                    if prepare_initial_search_retry_after_output(
                        &mut ws.search,
                        &job,
                        search_viewport_anchor(
                            display_offset,
                            screen_lines,
                            last_column,
                            default_direction,
                        ),
                    ) {
                        ws.search.unlimited_retry_at =
                            Some(now + std::time::Duration::from_millis(500));
                    }
                } else if let Some(continuation) = result.continuation {
                    job.cursor = continuation;
                    ws.search.background = Some(job);
                    ws.search.set_status_at(
                        kettle_render::SearchStatus::Searching,
                        std::time::Instant::now(),
                    );
                    if let Some(window) = &ws.window {
                        window.request_redraw();
                    }
                } else if job.nearby {
                    if job.output_drifted {
                        let (status, retry_at) = finished_background_search(&job, now);
                        ws.search.status = status;
                        ws.search.unlimited_retry_at = retry_at;
                        prepare_initial_search_retry_after_output(
                            &mut ws.search,
                            &job,
                            search_viewport_anchor(
                                display_offset,
                                screen_lines,
                                last_column,
                                default_direction,
                            ),
                        );
                    } else {
                        ws.search.typing_scanned_revision = Some(ws.search.revision);
                        let at_edge = match job.direction {
                            kettle_core::SearchDirection::Forward => job.edge.line >= bottom_line,
                            kettle_core::SearchDirection::Reverse => job.edge.line <= top_line,
                        };
                        if at_edge && !ws.search.wrap {
                            ws.search.status = kettle_render::SearchStatus::NoMatch;
                            ws.search.unlimited_retry_at = None;
                        } else {
                            ws.search.set_status_at(
                                kettle_render::SearchStatus::Searching,
                                std::time::Instant::now(),
                            );
                        }
                    }
                } else if chunk_edge == job.edge {
                    if !job.wrapped && ws.search.wrap {
                        ws.search.background = wrapped_background_search(
                            current_token,
                            job.direction,
                            job.wrap_anchor,
                            (top_line, bottom_line, last_column),
                            job.navigation,
                            job.had_focus,
                            job.output_drifted,
                        );
                        if ws.search.background.is_some() {
                            ws.search.set_status_at(
                                kettle_render::SearchStatus::Searching,
                                std::time::Instant::now(),
                            );
                        } else {
                            let (status, retry_at) = finished_background_search(&job, now);
                            ws.search.status = status;
                            ws.search.unlimited_retry_at = retry_at;
                            prepare_initial_search_retry_after_output(
                                &mut ws.search,
                                &job,
                                search_viewport_anchor(
                                    display_offset,
                                    screen_lines,
                                    last_column,
                                    default_direction,
                                ),
                            );
                        }
                    } else {
                        let (status, retry_at) = finished_background_search(&job, now);
                        ws.search.status = status;
                        ws.search.unlimited_retry_at = retry_at;
                        prepare_initial_search_retry_after_output(
                            &mut ws.search,
                            &job,
                            search_viewport_anchor(
                                display_offset,
                                screen_lines,
                                last_column,
                                default_direction,
                            ),
                        );
                    }
                } else if let Some(next) = search_point_after(
                    chunk_edge,
                    job.direction,
                    top_line,
                    bottom_line,
                    last_column,
                ) {
                    job.cursor = next;
                    ws.search.background = Some(job);
                    ws.search.set_status_at(
                        kettle_render::SearchStatus::Searching,
                        std::time::Instant::now(),
                    );
                    if let Some(window) = &ws.window {
                        window.request_redraw();
                    }
                } else {
                    let (status, retry_at) = finished_background_search(&job, now);
                    ws.search.status = status;
                    ws.search.unlimited_retry_at = retry_at;
                    prepare_initial_search_retry_after_output(
                        &mut ws.search,
                        &job,
                        search_viewport_anchor(
                            display_offset,
                            screen_lines,
                            last_column,
                            default_direction,
                        ),
                    );
                }
            }
        }

        // Reveal only when focus changes. A user can still wheel away while
        // search stays open without the next idle frame snapping them back.
        if let Some(focused) = ws.search.focused
            && ws.search.revealed_focus != Some(focused)
        {
            let history = term.grid().history_size();
            let old_offset = term.grid().display_offset();
            let wanted = kettle_core::search::reveal_offset(
                focused.start.line,
                old_offset,
                history,
                term.screen_lines(),
            );
            if wanted != old_offset {
                term.scroll_display(kettle_core::Scroll::Delta(
                    wanted as i32 - old_offset as i32,
                ));
            }
            ws.search.revealed_focus = Some(focused);
            ws.search.visible_key = None;
        }

        // Highlight only the viewport and a small logical-line context. This is
        // bounded independently of scrollback size and invalidates on viewport
        // movement without recompiling the regex.
        let display_offset = term.grid().display_offset();
        let layout = kettle_core::SearchLayout::capture(&term);
        let visible_key = crate::search_input::VisibleSearchKey {
            revision: ws.search.revision,
            pane: pane_id,
            output_generation,
            columns: layout.columns,
            screen_lines: layout.screen_lines,
            history_size: layout.history_size,
            display_offset,
            focused: ws.search.focused,
        };
        if ws.search.visible_key != Some(visible_key) {
            if foreground_scan_ran {
                ws.search.visible_turn_pending = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
                return;
            }
            let offset = i32::try_from(display_offset).unwrap_or(i32::MAX);
            let viewport_top = (-offset).max(top_line);
            let viewport_bottom = i32::try_from(term.screen_lines().saturating_sub(1))
                .unwrap_or(i32::MAX)
                .saturating_sub(offset)
                .min(bottom_line);
            let context_top = viewport_top
                .saturating_sub(VISIBLE_CONTEXT_LINES)
                .max(top_line);
            let context_bottom = viewport_bottom
                .saturating_add(VISIBLE_CONTEXT_LINES)
                .min(bottom_line);
            let viewport_start = kettle_core::SearchPoint::new(viewport_top, 0);
            let viewport_end = kettle_core::SearchPoint::new(viewport_bottom, last_column);
            let (context_start, left_truncated) = kettle_core::search::bounded_line_search_left(
                &term,
                kettle_core::SearchPoint::new(context_top, 0),
                MAX_LOGICAL_LINE_EXPANSION,
            );
            let (context_end, right_truncated) = kettle_core::search::bounded_line_search_right(
                &term,
                kettle_core::SearchPoint::new(context_bottom, last_column),
                MAX_LOGICAL_LINE_EXPANSION,
            );
            let (viewport_logical_start, viewport_left_truncated) =
                kettle_core::search::bounded_line_search_left(
                    &term,
                    viewport_start,
                    MAX_LOGICAL_LINE_EXPANSION,
                );
            let (viewport_logical_end, viewport_right_truncated) =
                kettle_core::search::bounded_line_search_right(
                    &term,
                    viewport_end,
                    MAX_LOGICAL_LINE_EXPANSION,
                );

            // Scan the viewport before surrounding context, one deterministic core work budget
            // per frame. Dense pre-viewport matches can therefore never consume the cap before a
            // visible/active match, and an exact work yield is resumed rather than mislabeled as
            // Results limited or cached as complete.
            let mut ranges = vec![kettle_core::SearchBounds::new(viewport_start, viewport_end)];
            if viewport_logical_start < viewport_start || viewport_logical_end > viewport_end {
                ranges.push(kettle_core::SearchBounds::new(
                    viewport_logical_start,
                    viewport_logical_end,
                ));
            }
            if let Some(before_end) = search_point_after(
                viewport_logical_start,
                kettle_core::SearchDirection::Reverse,
                top_line,
                bottom_line,
                last_column,
            ) && context_start <= before_end
            {
                ranges.push(kettle_core::SearchBounds::new(context_start, before_end));
            }
            if let Some(after_start) = search_point_after(
                viewport_logical_end,
                kettle_core::SearchDirection::Forward,
                top_line,
                bottom_line,
                last_column,
            ) && after_start <= context_end
            {
                ranges.push(kettle_core::SearchBounds::new(after_start, context_end));
            }

            if ws
                .search
                .visible_scan
                .as_ref()
                .is_none_or(|scan| scan.key != visible_key)
            {
                ws.search.visible.clear();
                ws.search.visible_truncated = false;
                ws.search.visible_scan = Some(crate::search_input::VisibleSearchScan::new(
                    visible_key,
                    ranges,
                    ws.search.focused,
                    left_truncated
                        || right_truncated
                        || viewport_left_truncated
                        || viewport_right_truncated,
                ));
            }

            let (bounds, remaining) = {
                let scan = ws
                    .search
                    .visible_scan
                    .as_ref()
                    .expect("visible scan initialized");
                (
                    scan.current_bounds().expect("visible scan has a range"),
                    kettle_core::MAX_SEARCH_MATCHES.saturating_sub(scan.matches.len()),
                )
            };
            let batch = ws
                .search
                .compiled
                .as_mut()
                .expect("compiled search checked")
                .find_in_range(
                    &term,
                    bounds,
                    kettle_core::SearchDirection::Forward,
                    remaining,
                );
            let finished = if remaining == 0 {
                true
            } else {
                let scan = ws
                    .search
                    .visible_scan
                    .as_mut()
                    .expect("visible scan initialized");
                scan.apply_batch(batch)
            };

            if finished {
                let mut scan = ws
                    .search
                    .visible_scan
                    .take()
                    .expect("visible scan initialized");
                scan.matches.sort_by_key(|span| (span.start, span.end));
                ws.search.visible = scan.matches;
                ws.search.visible_truncated = scan.truncated;
                ws.search.visible_key = Some(visible_key);
            } else if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
    }

    /// Visible terminal cursor cell for IME composition/candidate placement.
    fn terminal_cursor_cell(&self, ws: &WindowState) -> Option<(usize, usize)> {
        let pane = ws.mux.active_focus().and_then(|id| ws.mux.panes.get(&id))?;
        let term = pane.term.term.lock().ok()?;
        let point = term.renderable_content().cursor.point;
        Some((point.line.0.max(0) as usize, point.column.0))
    }

    fn update_ime_cursor_area(&self, ws: &WindowState) {
        let Some(window) = &ws.window else {
            return;
        };
        let (cw, ch) = ws
            .renderer
            .as_ref()
            .map(|renderer| (renderer.cell_w, renderer.cell_h))
            .unwrap_or((8.0, 16.0));
        let (preedit, preedit_focus) = ws
            .ime_preedit
            .as_ref()
            .map(|(text, selection)| (text.as_str(), ime_preedit_focus(text, *selection)))
            .unwrap_or(("", 0));
        let preedit_before_focus = &preedit[..preedit_focus];
        let input = ws
            .palette_input
            .as_ref()
            .map(|(query, _)| (4, query.as_str()))
            .or_else(|| {
                ws.theme_picker_input.as_ref().map(|state| {
                    use unicode_width::UnicodeWidthStr as _;
                    (
                        kettle_render::theme_picker_prefix(&self.ui_text).width(),
                        state.query.as_str(),
                    )
                })
            })
            .or_else(|| {
                ws.layout_picker_input
                    .as_ref()
                    .map(|(query, _)| (12, query.as_str()))
            })
            .or_else(|| ws.ssh_input.as_ref().map(|(query, _)| (8, query.as_str())));
        let search_cursor = self.search_geometry(ws).map(|geometry| {
            let mut projected = ws.search.query().to_string();
            let replace = ws
                .search
                .editor
                .selection()
                .unwrap_or(ws.search.editor.cursor()..ws.search.editor.cursor());
            projected.replace_range(replace.clone(), preedit);
            let cursor_byte = replace.start.saturating_add(preedit_focus);
            let columns = kettle_render::search_bar_columns(geometry.editor.2, cw).max(1);
            let scroll = crate::search_input::SearchEditor::visible_scroll_for(
                &projected,
                cursor_byte,
                ws.search.editor.horizontal_scroll(),
                columns.saturating_sub(2),
            );
            let cursor_column = crate::search_input::display_width(&projected[..cursor_byte])
                .saturating_sub(scroll);
            let left = geometry.editor.0 + cw;
            let right = (geometry.editor.0 + geometry.editor.2 - cw).max(left);
            // The committed text before the composition is placed where it
            // was painted, so a CJK fallback glyph wider or narrower than two
            // cells does not drift the candidate window; the composition
            // itself counts cells.
            let stops = ws
                .renderer
                .as_ref()
                .map_or(&[][..], |renderer| renderer.search_editor_stops());
            let painted = stops
                .binary_search_by_key(&replace.start, |stop| stop.0)
                .ok()
                .map(|index| stops[index].1 + preedit_before_focus.width() as f32 * cw);
            (
                painted
                    .unwrap_or(geometry.editor.0 + (cursor_column + 1) as f32 * cw)
                    .clamp(left, right),
                geometry.editor.1 + ((geometry.editor.3 - ch) * 0.5).max(0.0),
            )
        });
        let (x, y) = if let Some((x, y)) = search_cursor {
            (x, y)
        } else if let Some((prefix_cols, input)) = input {
            use unicode_width::UnicodeWidthStr as _;

            let size = window.inner_size();
            let cols = prefix_cols + input.width() + preedit_before_focus.width();
            (
                (cols as f32 * cw).min(size.width.saturating_sub(1) as f32),
                (size.height as f32 - ch - 5.0).max(0.0),
            )
        } else if let Some(edit) = &ws.editing_title {
            let rect = self.title_edit_rect(ws);
            let caret =
                title_edit_caret_cols(edit.scope, &edit.input, preedit_before_focus, &self.ui_text);
            (
                rect.0 + caret as f32 * cw,
                rect.1 + ((rect.3 - ch) * 0.5).max(0.0),
            )
        } else if ws.settings_text_edit.is_some() {
            let size = window.inner_size();
            (size.width as f32 * 0.5, size.height as f32 * 0.5)
        } else {
            let Some((row, col)) = self.terminal_cursor_cell(ws) else {
                return;
            };
            let Some(rect) = self.focused_terminal(ws, self.area(ws)) else {
                return;
            };
            let grid_origin = (rect.0 + self.cfg.padding_x, rect.1 + self.cfg.padding_y);
            (
                grid_origin.0 + col as f32 * cw,
                grid_origin.1 + row as f32 * ch,
            )
        };
        let size = window.inner_size();
        let x = x.clamp(0.0, size.width.saturating_sub(1) as f32);
        let y = y.clamp(0.0, size.height.saturating_sub(1) as f32);
        window.set_ime_cursor_area(
            winit::dpi::PhysicalPosition::new(f64::from(x), f64::from(y)),
            winit::dpi::PhysicalSize::new(f64::from(cw.max(1.0)), f64::from(ch.max(1.0))),
        );
    }

    /// `(row, col)` of the mouse within `rect`.
    ///
    /// Clamped to the focused pane's live grid: a click in the right/bottom
    /// padding (the rect rounds up past an exact cell multiple) must report the
    /// LAST cell, never one past the edge. A mouse-tracking app that sees
    /// `col == cols` or `row == rows` mis-renders — xterm
    /// itself clamps the reported coordinate to the window.
    fn cursor_cell_in_rect(&self, ws: &WindowState, rect: Rect) -> (usize, usize) {
        // Mouse-tracking reports a cell, not a selection boundary — the sub-cell
        // side is irrelevant here, so discard it.
        let (p, _) = self.px_to_point(ws, rect, ws.cursor.x as f32, ws.cursor.y as f32);
        let (row, col) = (p.line.0.max(0) as usize, p.column.0);
        // Clamp to the terminal's grid, the size `resize_all` gave the pane's
        // PTY.
        let (cols, rows) = self.grid_of(ws, rect);
        (
            row.min(rows.saturating_sub(1)),
            col.min(cols.saturating_sub(1)),
        )
    }

    /// `(row, col)` of the mouse within the focused pane, if any.
    fn cursor_cell(&self, ws: &WindowState) -> Option<(usize, usize)> {
        let rect = self.focused_terminal(ws, self.area(ws))?;
        Some(self.cursor_cell_in_rect(ws, rect))
    }

    /// Scan the focused pane's visible grid for quick-select targets and
    /// assign each a short label.
    fn collect_hints(&mut self, ws: &mut WindowState, preview: bool) -> Vec<HintTarget> {
        use kettle_core::hints;
        use kettle_core::{Column, Dimensions, Line, Point};
        let Some(pane) = ws.mux.active_focus() else {
            return Vec::new();
        };
        let Some(p) = ws.mux.focused() else {
            return Vec::new();
        };
        let Ok(t) = p.term.term.lock() else {
            return Vec::new();
        };
        let g = t.grid();
        let (rows, cols) = (g.screen_lines(), g.columns());
        // Each card the grid shows is a target too, read from the same grid
        // as the text under the same lock, so a scroll or new output since
        // the last frame moves both alike. It is labelled at its first
        // visible cell; text inside it is its marks, not something to pick.
        let mut snap = kettle_render::PaneSnapshot::default();
        snap.capture_with_card_marks(&t, true);
        let offset = i32::try_from(g.display_offset()).unwrap_or(i32::MAX);
        let last_row = i32::try_from(rows).unwrap_or(i32::MAX).saturating_sub(1);
        let cards: Vec<CardCells> = p
            .inline_cards
            .placements(&snap)
            .into_iter()
            .filter(|card| self.media.cards.item(pane, card.nonce).is_some())
            .filter_map(|card| {
                let top = card.line.checked_add(offset)?;
                let bottom = top.checked_add(i32::from(card.rows).max(1) - 1)?;
                if bottom < 0 || top > last_row || cols == 0 {
                    return None;
                }
                let right = (card.column + usize::from(card.columns).max(1) - 1).min(cols - 1);
                Some((
                    (usize::try_from(top.max(0)).ok()?, card.column.min(cols - 1)),
                    (usize::try_from(bottom.min(last_row)).ok()?, right),
                    card.nonce,
                ))
            })
            .collect();
        // Convert each viewport row to its grid-absolute line so hint detection
        // scans the visible rows (including history when scrolled back), not the
        // active screen. Otherwise a label drawn over a visible URL would open
        // the active-screen URL at the same index. `HintTarget.row` stays
        // viewport-relative for label placement.
        let off = g.display_offset();
        let lines: Vec<i32> = (0..rows)
            .map(|r| {
                let base = viewport_point_to_grid(Point::new(Line(r as i32), Column(0)), off);
                base.line.0
            })
            .collect();
        let mut found = hint_targets_with_cards(hints::detect_rows(g, &lines, cols), &cards);
        // Quick select for previews labels only what a lane can show.
        if preview {
            found.retain(|(_, _, what)| hint_previews(what));
        }
        let labels = hints::labels(found.len(), hints::ALPHABET);
        found
            .into_iter()
            .zip(labels)
            .map(|((row, col, what), label)| HintTarget {
                row,
                col,
                label,
                pane,
                what,
            })
            .collect()
    }

    fn link_at_cursor<'a>(&self, ws: &'a WindowState) -> Option<&'a kettle_core::Link> {
        let (row, col) = self.cursor_cell(ws)?;
        ws.links
            .iter()
            .find(|l| l.row == row && col >= l.start_col && col <= l.end_col)
    }

    fn pane_mode(&self, ws: &WindowState, pane_id: u64) -> Option<kettle_core::TermMode> {
        ws.mux
            .panes
            .get(&pane_id)
            .and_then(|p| p.term.term.lock().ok().map(|t| *t.mode()))
    }

    /// Forward a mouse event to the app via the active tracking protocol.
    /// Returns `true` when it was consumed (so kettle skips local handling).
    /// Whether a mouse event at `cur` should be reported to a tracking app,
    /// given the `last` reported cell. Motion (1002/1003) coalesces to cell
    /// crossings; a press/release (`motion == false`) always reports. Pure so
    /// the coalescing rule is unit-tested without a live PTY.
    fn motion_should_report(
        motion: bool,
        last: Option<(usize, usize)>,
        cur: (usize, usize),
    ) -> bool {
        !(motion && last == Some(cur))
    }

    fn send_mouse(&mut self, ws: &mut WindowState, btn: u8, pressed: bool, motion: bool) -> bool {
        self.report_mouse(ws, btn, pressed, motion).consumed()
    }

    /// Send a mouse event to the terminal it belongs to and say what it did.
    /// A press goes to the focused pane, and a program that gets one keeps
    /// it: that button's drag and its one release go to the same pane,
    /// wherever focus has gone since, so no program is left holding half a
    /// click and no other gets a release it never had the press for. The
    /// newest press owns the drag, so a gesture of Kettle's own started
    /// since takes it. Hover goes to the focused pane.
    fn report_mouse(
        &mut self,
        ws: &mut WindowState,
        btn: u8,
        pressed: bool,
        motion: bool,
    ) -> MouseReport {
        let held = match (pressed, motion) {
            (false, _) => match ws.held_buttons.take(btn) {
                Some(held) if held.pane.is_some() => Some(held),
                // No program had its press: Kettle's own gesture did, or
                // nothing did, so no program gets its release.
                _ => return MouseReport::Declined,
            },
            (true, true) => ws.held_buttons.dragging(),
            (true, false) => None,
        };
        if let Some(held) = held
            && let Some(pane) = held.pane
        {
            let rect = self.pane_terminal(ws, self.area(ws), pane);
            let at = MouseAt::Held {
                rect,
                cell: held.cell,
            };
            let button = if motion { held.button } else { btn };
            return self.send_mouse_to(ws, pane, at, button, pressed, motion);
        }
        let Some(pane_id) = ws.mux.active_focus() else {
            return MouseReport::Declined;
        };
        let Some(rect) = self.focused_terminal(ws, self.area(ws)) else {
            return MouseReport::Declined;
        };
        // Motion over a lane is the lane's: only a drag the program's own
        // press began follows the pointer there (above).
        if motion && self.preview_lane_under_pointer(ws) {
            return MouseReport::Declined;
        }
        let report = self.send_mouse_to(ws, pane_id, MouseAt::Pointer(rect), btn, pressed, motion);
        if pressed && !motion {
            // The press is the button's gesture now: the program's if it got
            // it, else Kettle's own.
            let (pane, cell) = match (report, ws.last_mouse_cell) {
                (MouseReport::Written, Some((pane, row, col))) => (Some(pane), (row, col)),
                _ => (None, (0, 0)),
            };
            if let Some(stale) = ws.held_buttons.pressed(btn, pane, cell) {
                self.release_held(ws, stale);
            }
        }
        report
    }

    /// Send each held button `which` names its release now, in the pane its
    /// press went to, at the cell that pane last saw. Kettle is ending the
    /// gesture (focus left the window, a menu or search took the pointer,
    /// the pane's tab is leaving, or the button was pressed again after a
    /// release that went elsewhere), and the program must not be left
    /// holding a press. Kettle's own gestures just end.
    fn release_held_buttons(
        &mut self,
        ws: &mut WindowState,
        which: impl FnMut(&crate::held_buttons::Held) -> bool,
    ) {
        for held in ws.held_buttons.take_where(which) {
            self.release_held(ws, held);
        }
    }

    /// Send `held`'s program its release at the cell it last saw.
    fn release_held(&mut self, ws: &mut WindowState, held: crate::held_buttons::Held) {
        let Some(pane) = held.pane else {
            return;
        };
        let at = MouseAt::Held {
            rect: None,
            cell: held.cell,
        };
        self.send_mouse_to(ws, pane, at, held.button, false, false);
    }

    /// Release the held buttons of every pane in tab `idx` before it leaves
    /// this window, whose events can no longer reach it.
    fn release_held_buttons_in_tab(&mut self, ws: &mut WindowState, idx: usize) {
        let panes = ws.mux.tab_pane_ids(idx);
        self.release_held_buttons(ws, |held| {
            held.pane.is_some_and(|pane| panes.contains(&pane))
        });
    }

    fn send_mouse_to(
        &mut self,
        ws: &mut WindowState,
        pane_id: u64,
        at: MouseAt,
        btn: u8,
        pressed: bool,
        motion: bool,
    ) -> MouseReport {
        let held = matches!(at, MouseAt::Held { .. });
        // A held button's pane that left the screen gets its release, but
        // no drag: the pointer is nowhere over it.
        if matches!(at, MouseAt::Held { rect: None, .. }) && pressed {
            return MouseReport::Swallowed;
        }
        self.sync_pane_focus_reports(ws);
        if search_bar_blocks_mouse_report(
            self.cursor_in_search_bar(ws),
            pressed,
            motion,
            ws.held_buttons.any(),
        ) {
            return MouseReport::Swallowed;
        }
        // Shift bypasses mouse tracking so kettle handles the event locally
        // (the xterm convention). Without it, a TUI in mouse mode (htop, vim,
        // tmux) consumes every click and the user cannot select text.
        // Returning `false` lets the caller run selection, scrollbar, and
        // extend logic as if tracking were off. A button whose press the
        // program got keeps its motion and release there, Shift or not.
        if ws.mods.shift_key() && !held {
            return MouseReport::Declined;
        }
        // VTE input-enabled parity: a read-only pane gets
        // no mouse-tracking reports either. Returning false falls through to
        // kettle-local handling, so selection / scrollback still work for the
        // user — the same degradation VTE applies when input is disabled.
        if ws.mux.panes.get(&pane_id).is_some_and(|p| p.read_only) {
            return MouseReport::Declined;
        }
        let mode = self
            .pane_mode(ws, pane_id)
            .unwrap_or(kettle_core::TermMode::empty());
        let (track, sgr) = input::mouse_tracking(mode);
        if track == input::MouseTracking::Off {
            return MouseReport::Declined;
        }
        // `motion_is_reported` owns the per-mode rule; see its comment for why
        // it is stated positively.
        if motion && !input::motion_is_reported(track, held) {
            {
                // A held button means the application owns the gesture even
                // though this mode does not report the motion itself, so
                // consume it. With no button held the pointer is only
                // hovering, and kettle's own hover, scrollbar-drag and
                // link-hover handling must still run.
                return if held {
                    MouseReport::Swallowed
                } else {
                    MouseReport::Declined
                };
            }
        }
        let (row, col) = match at {
            MouseAt::Pointer(rect)
            | MouseAt::Held {
                rect: Some(rect), ..
            } => self.cursor_cell_in_rect(ws, rect),
            MouseAt::Held { rect: None, cell } => cell,
        };
        // Cell-motion coalescing: a drag that stays inside one cell must not
        // re-report. xterm fires a 1002/1003 motion event only when the
        // pointer crosses into a new cell; without this a fast drag emits one
        // SGR report per pixel of travel, flooding the TUI.
        // Press/release always report (the guard is motion-only) and refresh
        // the baseline, so the next motion is compared against the right cell.
        let last = ws
            .last_mouse_cell
            .and_then(|(pane, row, col)| (pane == pane_id).then_some((row, col)));
        if !Self::motion_should_report(motion, last, (row, col)) {
            return MouseReport::Swallowed;
        }
        let seq = input::mouse_encode(sgr, btn, pressed, motion, col, row, ws.mods);
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            return MouseReport::Declined;
        };
        // A release takes the room the program's input keeps for releases,
        // so it always lands behind its press.
        let result = if pressed || motion {
            pane.feed_input(&seq)
        } else {
            pane.feed_mouse_release(&seq)
        };
        Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
        if !result.is_queued() {
            // The program never got it: a press it missed leaves no button
            // held, so no release follows.
            self.report_input_result(result);
            return MouseReport::Swallowed;
        }
        ws.last_mouse_cell = Some((pane_id, row, col));
        ws.held_buttons.told(pane_id, (row, col));
        MouseReport::Written
    }

    fn completion_overlay_projection(
        &self,
        ws: &WindowState,
        terminal_surface: bool,
    ) -> Option<kettle_render::CompletionOverlay> {
        if !terminal_surface || !ws.window_focused || ws.ime_preedit.is_some() {
            return None;
        }
        let pane_id = ws.mux.active_focus()?;
        let pane = ws.mux.panes.get(&pane_id)?;
        if !pane.completion_overlay {
            return None;
        }
        let (mode, display_offset, columns, rows) = {
            let term = pane.term.term.lock().ok()?;
            (
                *term.mode(),
                term.grid().display_offset(),
                term.columns(),
                term.screen_lines(),
            )
        };
        if !completion_surface_available(mode, display_offset) {
            return None;
        }
        let command_rows = pane.term.completion_command_rows()?;
        let (list, completion_cursor_col) = pane.term.completion_projection()?;
        let anchor_col = completion_cursor_col
            .zip(list.input_prefix.as_deref())
            .map(|(cursor, prefix)| completion_anchor_col(cursor, prefix));
        let area = self.area(ws);
        let pane_rect = self.focused_terminal(ws, area)?;
        let grid_origin = (
            pane_rect.0 + self.cfg.padding_x,
            pane_rect.1 + self.cfg.padding_y,
        );
        let renderer = ws.renderer.as_ref()?;
        let kind = self.ui_text.text(match list.kind {
            kettle_core::CompletionKind::Completion => kettle_i18n::Text::CompletionKindCompletions,
            kettle_core::CompletionKind::Prediction => kettle_i18n::Text::CompletionKindPrediction,
        });
        Some(kettle_render::CompletionOverlay {
            tr: self.ui_text,
            pane_rect,
            grid_rect: (
                grid_origin.0,
                grid_origin.1,
                columns as f32 * renderer.cell_w,
                rows as f32 * renderer.cell_h,
            ),
            command_rows,
            anchor_col,
            kind: kind.to_string(),
            source: list.source,
            selected: list.selected,
            total: list.total,
            token: list.token,
            candidates: list
                .candidates
                .into_iter()
                .map(|candidate| kettle_render::CompletionOverlayRow {
                    label: candidate.label,
                    description: candidate.description,
                    position: candidate.position,
                })
                .collect(),
        })
    }

    fn media_paste_receipt_overlay_projection(
        &self,
        ws: &WindowState,
        terminal_surface: bool,
        now: std::time::Instant,
    ) -> Option<kettle_render::MediaPasteReceiptOverlay> {
        // The open media viewer hides the receipt until it closes: the viewer
        // owns every press, and the receipt's thumbnail and labels would
        // otherwise paint over it.
        if !terminal_surface || !ws.window_focused {
            return None;
        }
        let receipt = ws.media_paste_receipt.as_ref()?;
        let (kind, openable) = match &receipt.kind {
            crate::window_state::MediaPasteReceiptKind::Image {
                original_width,
                original_height,
            } if self.cfg.paste_image_preview => (
                kettle_render::MediaPasteReceiptKind::Image {
                    original_width: *original_width,
                    original_height: *original_height,
                },
                true,
            ),
            crate::window_state::MediaPasteReceiptKind::Video {
                candidate,
                preview_pending,
                ..
            } if self.cfg.paste_video_preview => (
                kettle_render::MediaPasteReceiptKind::Video {
                    extension: candidate.extension.clone(),
                    size: candidate.size,
                    count: candidate.count,
                    preview_pending: *preview_pending,
                },
                false,
            ),
            _ => return None,
        };
        let pane_id = ws.mux.active_focus()?;
        if pane_id != receipt.pane_id || !receipt.live(now) {
            return None;
        }
        let pane = ws.mux.panes.get(&pane_id)?;
        let (columns, rows, has_history) = {
            let term = pane.term.term.lock().ok()?;
            (
                term.columns(),
                term.screen_lines(),
                term.grid().history_size() > 0,
            )
        };
        let area = self.area(ws);
        let pane_rect = self.focused_terminal(ws, area)?;
        let grid_origin = (
            pane_rect.0 + self.cfg.padding_x,
            pane_rect.1 + self.cfg.padding_y,
        );
        let renderer = ws.renderer.as_ref()?;
        let scrollbar_present = self.cfg.scrollbar == kettle_config::ScrollbarMode::Always
            || (self.cfg.scrollbar != kettle_config::ScrollbarMode::Never && has_history);
        let right_gutter = if scrollbar_present {
            let scale = ws
                .window
                .as_ref()
                .map(|window| window.scale_factor() as f32)
                .unwrap_or(1.0);
            (self.cfg.scrollbar_width.clamp(2.0, 40.0) * scale).max(12.0 * scale)
        } else {
            0.0
        };
        Some(kettle_render::MediaPasteReceiptOverlay {
            tr: self.ui_text,
            pane_rect,
            grid_rect: (
                grid_origin.0,
                grid_origin.1,
                columns as f32 * renderer.cell_w,
                rows as f32 * renderer.cell_h,
            ),
            right_gutter,
            image: receipt.image.clone(),
            kind,
            openable,
            remote: receipt.remote,
            expanded: receipt.expanded(now),
            prefer_top: receipt.prefer_top,
        })
    }

    fn media_paste_receipt_projection(
        &self,
        ws: &WindowState,
    ) -> Option<(
        kettle_render::MediaPasteReceiptOverlay,
        Option<kettle_render::CompletionOverlay>,
    )> {
        // This is the pointer-motion path. Keep the overwhelmingly common case
        // allocation- and lock-free, then project only the two overlays whose
        // geometry can affect the receipt rather than building every piece of
        // window chrome.
        ws.media_paste_receipt.as_ref()?;
        let terminal_surface = terminal_surface_available(ws);
        let receipt = self.media_paste_receipt_overlay_projection(
            ws,
            terminal_surface,
            std::time::Instant::now(),
        )?;
        let completion = self.completion_overlay_projection(ws, terminal_surface);
        Some((receipt, completion))
    }

    fn overlay(&self, ws: &WindowState, reuse_pane_snapshots: bool) -> Overlay {
        let preedit_state = ws.ime_preedit.as_ref().filter(|(text, _)| !text.is_empty());
        let preedit = preedit_state.map(|(text, _)| text.as_str());
        let with_preedit = |input: &str| match preedit {
            Some(preedit) => format!("{input}{preedit}"),
            None => input.to_string(),
        };
        // Hovering any segment of a link wrapped across rows lights them all.
        let hovered_group = self.link_at_cursor(ws).map(|link| link.group);
        let links = ws
            .links
            .iter()
            .map(|l| kettle_render::LinkRect {
                col: l.start_col,
                row: l.row,
                width: (l.end_col + 1).saturating_sub(l.start_col).max(1),
                hover: hovered_group == Some(l.group),
            })
            .collect();

        use kettle_i18n::Text as T;
        let tr = &self.ui_text;
        let (ssh_query, ssh_hint, ssh_picker) = match &ws.ssh_input {
            Some((query, selected)) => (
                Some(with_preedit(query)),
                picker_hint(
                    tr,
                    &[
                        ("Enter", T::PickerHintConnect),
                        ("Tab", T::PickerHintComplete),
                        ("↑↓", T::PickerHintSelect),
                        ("Esc", T::PickerHintCancel),
                    ],
                ),
                Some(ssh_picker_list(query, *selected, &self.cfg.ssh_hosts, tr)),
            ),
            None => (None, String::new(), None),
        };

        let (palette_query, palette_hint, palette_picker) = match &ws.palette_input {
            Some((query, selected)) => (
                Some(with_preedit(query)),
                picker_hint(
                    tr,
                    &[
                        ("Enter", T::PickerHintRun),
                        ("Tab/↑↓", T::PickerHintSelect),
                        ("Esc", T::PickerHintCancel),
                    ],
                ),
                Some(command_picker_list(
                    query,
                    *selected,
                    &self.cfg.keybinds,
                    tr,
                )),
            ),
            None => (None, String::new(), None),
        };

        // Terminator parity (layoutlauncher.py): build the layout picker's
        // query and hint the same way as the command palette. An empty
        // layouts dir is fine; the picker shows a "No saved layouts" row
        // hinting `kettle --save-layout NAME`.
        let (layout_picker_query, layout_picker_hint, layout_picker) = match &ws.layout_picker_input
        {
            Some((query, selected)) => (
                Some(with_preedit(query)),
                picker_hint(
                    tr,
                    &[
                        ("Enter", T::PickerHintSpawn),
                        ("Tab/↑↓", T::PickerHintSelect),
                        ("Esc", T::PickerHintCancel),
                    ],
                ),
                Some(layout_picker_list(
                    query,
                    *selected,
                    &ws.layout_picker_entries,
                    tr,
                )),
            ),
            None => (None, String::new(), None),
        };
        let (theme_picker_query, theme_picker_hint, theme_picker) = match &ws.theme_picker_input {
            Some(state) => (
                Some(with_preedit(&state.query)),
                picker_hint(
                    tr,
                    &[
                        ("Enter", T::PickerHintKeep),
                        ("↑↓", T::PickerHintSelect),
                        ("Esc", T::PickerHintRestore),
                    ],
                ),
                Some(theme_picker_list(
                    &state.query,
                    state.selected,
                    &state.opened_on,
                    tr,
                )),
            ),
            None => (None, String::new(), None),
        };
        let hint_labels: Vec<HintLabel> = match &ws.hint_state {
            Some((targets, typed)) => targets
                .iter()
                .map(|t| HintLabel {
                    row: t.row,
                    col: t.col,
                    label: t.label.clone(),
                    dim: !typed.is_empty() && !t.label.starts_with(typed.as_str()),
                })
                .collect(),
            None => Vec::new(),
        };
        let terminal_surface = terminal_surface_available(ws);
        let completion = self.completion_overlay_projection(ws, terminal_surface);
        let media_paste_receipt = self.media_paste_receipt_overlay_projection(
            ws,
            terminal_surface,
            std::time::Instant::now(),
        );
        // Lanes stay drawn under every modal, which paints over them; their
        // room in the pane stays carved either way.
        let media_lanes = self.preview_lane_projections(ws);
        let media_viewer_rect = ws.preview_overlay.and_then(|open| {
            self.pane_layout(ws, self.area(ws))
                .into_iter()
                .find(|(pane, _)| *pane == open.pane)
                .and_then(|(_, partition)| crate::media::centered_preview_rect(partition.terminal))
        });
        let ime_preedit = preedit.filter(|_| terminal_surface).and_then(|text| {
            let (row, col) = self.terminal_cursor_cell(ws)?;
            Some(ImePreedit {
                text: text.to_string(),
                row,
                col,
            })
        });

        let window_focused = ws.window_focused;
        // Brighten the focused pane's scrollbar while the pointer is on the
        // gutter or the thumb is being dragged (overlay-scrollbar feel). The
        // scrolled-back case is decided per-pane in the renderer from the snapshot.
        let scrollbar_active = ws.scrollbar_hover || ws.scrollbar_drag_offset.is_some();
        // Cursor blink is the *intersection* of the user config and the
        // running app's wishes — programs flip it via DEC private mode 12
        // (`CSI ?12 h/l`), which the engine tracks per-pane on its
        // `cursor_style().blinking`. Read the active pane's live state so
        // editors like vim that disable blink for their own cursor are
        // honored even when the global config wants blink. (Goes through
        // `active_focus` + `panes.get` so the `overlay()` builder stays a
        // pure `&self` reader.)
        let pane_blink = self.pane_cursor_blinking(ws, reuse_pane_snapshots);
        let blink_enabled = self.cfg.cursor_blink && pane_blink;
        let cursor_visible = if !blink_enabled || !window_focused || modal_holds_cursor_steady(ws) {
            true
        } else {
            ws.blink_on
        };
        // The transient resize chip. `about_to_wait` drives the expiry
        // repaint and clears the state.
        let resize_overlay = ws
            .resize_overlay
            .and_then(|(c, r, t)| (t.elapsed() < RESIZE_OVERLAY_DURATION).then_some((c, r)));

        let context_menu = self.context_menu_overlay(ws).or_else(|| {
            let surface = ws
                .renderer
                .as_ref()
                .map(|renderer| {
                    let (width, height) = renderer.surface_size();
                    (width as f32, height as f32)
                })
                .unwrap_or((800.0, 600.0));
            picker_overlay_context_menu(
                [palette_picker, theme_picker, layout_picker, ssh_picker],
                surface,
                self.menu_cell(ws),
            )
        });
        // Marshal the in-progress Edit-title state for
        // the render layer so the user sees what they're typing. The
        // title-edit rect is app chrome, never a bottom overlay over terminal
        // rows.
        let edit_title: Option<kettle_render::TitleEditOverlay> =
            ws.editing_title.as_ref().map(|s| {
                let label = title_edit_label(s.scope, &self.ui_text);
                kettle_render::TitleEditOverlay {
                    label: label.to_string(),
                    input: with_preedit(&s.input),
                    hint: picker_hint(
                        &self.ui_text,
                        &[
                            ("Enter", kettle_i18n::Text::EditHintApply),
                            ("Esc", kettle_i18n::Text::PickerHintCancel),
                        ],
                    ),
                    rect: self.title_edit_rect(ws),
                }
            });
        // Project the App's confirm_dialog into the
        // renderer's projection (so it shows even when no
        // search is open — confirm modals are independent).
        let confirm_dialog_early =
            ws.confirm_dialog
                .as_ref()
                .map(|d| kettle_render::ConfirmDialogOverlay {
                    prompt: d.prompt.clone(),
                    buttons: d
                        .buttons
                        .iter()
                        .map(|b| match b {
                            ConfirmButton::Cancel => kettle_render::ConfirmDialogButton {
                                label: confirm_button_label(b, tr).to_string(),
                                destructive: false,
                            },
                            ConfirmButton::Confirm { label, destructive } => {
                                kettle_render::ConfirmDialogButton {
                                    label: label.clone(),
                                    destructive: *destructive,
                                }
                            }
                        })
                        .collect(),
                    focus_idx: d.focus_idx,
                });
        // Project the settings overlay (independent of search, like
        // the confirm dialog). Values are read from the live Config so the
        // panel reflects the current state (incl. external reloads).
        let settings_overlay = self.settings_overlay_projection(ws);
        // Terminator parity: only a LIVE drag with a latched target paints a
        // hint. An armed-but-unmoved press is still a click, and a live drag
        // over a seam has no target to preview.
        let pane_drop_hint = ws
            .pane_drag
            .as_ref()
            .filter(|drag| drag.live)
            .and_then(|drag| drag.target)
            .map(|(_, rect, dir, before)| crate::mux::pane_drop_preview(rect, dir, before));
        let card_hover = ws.card_hover;
        let s = &ws.search;
        // Both literals list every field: a defaulted overlay would paint
        // English and drop state such as the pane drop hint.
        if !s.open {
            return Overlay {
                tr: self.ui_text,
                search: None,
                highlights: Vec::new(),
                links,
                ssh_query,
                ssh_hint,
                palette_query,
                palette_hint,
                layout_picker_query,
                layout_picker_hint,
                theme_picker_query,
                theme_picker_hint,
                edit_title,
                hint_labels,
                ime_preedit,
                completion,
                media_paste_receipt,
                media_lanes,
                media_viewer_rect,
                card_hover,
                window_focused,
                scrollbar_active,
                cursor_visible,
                resize_overlay,
                context_menu,
                confirm_dialog: confirm_dialog_early,
                settings: settings_overlay,
                update_available: self.update_available.clone(),
                pane_drop_hint,
            };
        }
        let mut highlights = Vec::new();
        if let Some(pane_id) = s.target_pane
            && let Some(pane) = ws.mux.panes.get(&pane_id)
            && let Ok(term) = pane.term.term.lock()
        {
            use kettle_core::Dimensions as _;
            let display_offset = term.grid().display_offset();
            let screen_lines = term.screen_lines();
            let last_column = term.last_column().0;
            let offset = i32::try_from(display_offset).unwrap_or(i32::MAX);
            let visible_top = -offset;
            let visible_bottom = i32::try_from(screen_lines.saturating_sub(1))
                .unwrap_or(i32::MAX)
                .saturating_sub(offset);
            for span in &s.visible {
                let first_line = span.start.line.max(visible_top);
                let last_line = span.end.line.min(visible_bottom);
                if first_line > last_line {
                    continue;
                }
                let active = s.focused == Some(*span);
                for line in first_line..=last_line {
                    let start_col = if line == span.start.line {
                        span.start.column
                    } else {
                        0
                    };
                    let end_col = if line == span.end.line {
                        span.end.column.min(last_column)
                    } else {
                        last_column
                    };
                    if end_col < start_col {
                        continue;
                    }
                    if let Some(rect) = HighlightRect::from_grid_span(
                        line,
                        display_offset,
                        screen_lines,
                        start_col,
                        end_col.saturating_sub(start_col).saturating_add(1),
                        active,
                    ) {
                        highlights.push(rect);
                    }
                }
            }
        }
        let confirm_dialog = confirm_dialog_early;
        let mut search_query = s.query().to_string();
        let mut search_cursor = s.editor.cursor();
        let mut search_selection = s.editor.selection().map(|range| (range.start, range.end));
        if let Some((preedit, selection)) = preedit_state {
            let replace = s.editor.selection().unwrap_or(search_cursor..search_cursor);
            search_query.replace_range(replace.clone(), preedit);
            search_cursor = replace
                .start
                .saturating_add(ime_preedit_focus(preedit, *selection));
            search_selection = None;
        }
        let search_horizontal_scroll = self
            .search_geometry(ws)
            .and_then(|geometry| {
                let renderer = ws.renderer.as_ref()?;
                let columns =
                    kettle_render::search_bar_columns(geometry.editor.2, renderer.cell_w).max(1);
                Some(crate::search_input::SearchEditor::visible_scroll_for(
                    &search_query,
                    search_cursor,
                    s.editor.horizontal_scroll(),
                    columns.saturating_sub(2),
                ))
            })
            .unwrap_or_else(|| s.editor.horizontal_scroll());
        Overlay {
            tr: self.ui_text,
            search: Some(kettle_render::SearchOverlay {
                tr: self.ui_text,
                target_pane: s.target_pane,
                query: search_query,
                cursor_byte: search_cursor,
                selection: search_selection,
                horizontal_scroll: search_horizontal_scroll,
                wrap: s.wrap,
                case_mode: map_search_case_mode(s.case_mode),
                invert: s.invert,
                status: displayed_search_status(s, std::time::Instant::now()),
                focused: s.focused_control,
                hovered: s.hovered_control,
                pressed: s.pressed_control,
            }),
            highlights,
            links,
            ssh_query,
            ssh_hint,
            palette_query,
            palette_hint,
            layout_picker_query,
            layout_picker_hint,
            theme_picker_query,
            theme_picker_hint,
            edit_title,
            hint_labels,
            ime_preedit,
            completion: None,
            media_paste_receipt: None,
            media_lanes,
            media_viewer_rect: None,
            card_hover,
            window_focused,
            scrollbar_active,
            cursor_visible,
            resize_overlay,
            context_menu,
            confirm_dialog,
            settings: settings_overlay,
            update_available: self.update_available.clone(),
            pane_drop_hint,
        }
    }

    fn update_links(&mut self, ws: &mut WindowState) {
        scan_links(ws);
    }

    fn redraw(&mut self, ws: &mut WindowState) {
        // A frame while the window server blinks the cursor ends that blink.
        // Bring the app's phase to where the animation is first, so the frame
        // draws what the screen shows. The harness timer includes this work.
        let cursor_exit_frame = if ws.cursor_exit_log.enabled {
            ws.cursor_exit_log.begin_frame(
                ws.blink_layer.is_active(),
                crate::cursor_exit_log::raw_now_ns(),
            )
        } else {
            None
        };
        Self::materialize_layer_blink(ws, std::time::Instant::now());
        // Flush any pending chrome-geometry change before painting. A title
        // edit materialises a chrome strip (see `tab_bar_h`), so opening or
        // closing one changes the content rectangle and the PTYs must follow.
        // Doing it here rather than at each transition coalesces the
        // close-then-open pair that every modal opener performs: the child sees
        // one resize to the final geometry, or none at all when the geometry is
        // unchanged end to end, because `try_resize_geometry` already skips a
        // no-op.
        // Consume the flag only when the resize can happen. `resize_all`
        // returns early while the renderer is absent (GPU recovery), so
        // taking the flag then would drop the geometry change and the PTYs
        // would never hear of it. Leaving it set defers the resize to the
        // first frame after the renderer is rebuilt.
        if ws.pending_resize && ws.renderer.is_some() {
            ws.pending_resize = false;
            self.resize_all(ws);
        }
        // Keep the OS titlebar in step with the active palette.
        // Compare-only when nothing changed; independent of GPU health, so it
        // runs before the device-lost early-return below.
        self.maybe_sync_native_theme(ws);
        self.maybe_sync_color_scheme(ws);
        if let (Some(material), Some(window)) = (&ws.native_material, &ws.window) {
            material.sync(window, &self.cfg);
        }
        // If the GPU device was lost (a driver TDR/reset) or hit an uncaptured
        // error (VRAM exhaustion under memory pressure), rendering against it
        // cannot succeed. The wgpu error handlers installed by
        // `kettle_render::install_gpu_error_handlers` turn the fault into a
        // logged event and this flag instead of a `panic=abort` crash. Stop
        // painting so the surface-reconfigure loop does not spin;
        // about_to_wait_inner drives renderer recovery on a bounded backoff.
        if self.gpu.as_ref().is_some_and(|g| g.is_lost()) {
            let title = self.ui_text.text(kettle_i18n::Text::WindowTitleGpuLost);
            if ws.last_title != title {
                if let Some(w) = &ws.window {
                    w.set_title(title);
                }
                ws.last_title = title.to_string();
            }
            // Nothing is painted on the dead device, but pending PTY output
            // must still be marked seen and the output pacer reset. Otherwise
            // `window_has_new_output` stays true forever and a streaming pane
            // spins the event loop at 30-60 Hz during a TDR, burning CPU and
            // battery. With both cleared, the loop quiesces to
            // ControlFlow::Wait between output bursts. (`about_to_wait_inner`
            // also short-circuits animation wakes while lost.)
            ws.output_pacer.reset();
            ws.seen_output_gen.clear();
            for (id, p) in &ws.mux.panes {
                ws.seen_output_gen.insert(*id, p.term.output_generation());
            }
            return;
        }
        // Scheduled theme transitions are time-driven rather than terminal
        // output. Keep this lock-free maintenance outside the snapshot-reuse
        // branch so a stream of menu-hover frames cannot defer a boundary
        // crossing indefinitely.
        self.poll_theme_schedule(ws);
        // B (Peacock): resolve/refresh this window's accent claim (cheap in
        // the steady state; full pool walk only on first frame/theme switch).
        self.sync_window_accent(ws);
        // A context-menu hover changes only one highlight quad. When no output,
        // pane order, or grid dimensions changed, keep the prior render
        // snapshots and bypass every terminal-locking maintenance pass below.
        // The one-shot hint is invalidated by any intervening input/user event.
        let reuse_pane_snapshots = std::mem::take(&mut ws.reuse_pane_snapshots_once)
            && ws.context_menu.is_some()
            && context_menu_snapshot_reuse_safe(ws)
            && self.torn_drag.is_none()
            && self.pane_snapshots_match_current_layout(ws);
        if !reuse_pane_snapshots {
            self.drain_events(ws);
            self.poll_remote_contexts(ws);
            self.poll_focus_event(ws);
            self.poll_title_event(ws);
            if ws.ime_preedit.is_some() {
                self.update_ime_cursor_area(ws);
            }
            // Reflect the focused pane's OSC 9;4 progress onto the OS
            // taskbar button (pwsh 7 / Windows Terminal parity). No-op off Windows.
            self.poll_taskbar_progress(ws);
            // Process restart requests only after the pane iteration releases
            // its mutable borrow. Lifecycle-only wakes use this same helper in
            // about-to-wait, so hidden windows do not strand a Restart action.
            self.process_pending_pane_restarts(ws);
            // Reflect the active pane (incl. after tab/focus switches).
            self.sync_window_title(ws);
            // Capture a just-exited pane's final output before reap drops
            // its sidechannel — otherwise the shell's last line is lost from the trace.
            self.flush_recorder_output(ws);
            let reaped = ws.mux.reap();
            // `clear_stale_title_edit` mutates `ws.editing_title`, so it is
            // evaluated into a binding rather than placed on the right of the
            // `||` where a reaped layout would short-circuit past it and
            // strand a title edit pinned to a pane that no longer exists.
            let stale_title = clear_stale_title_edit(&ws.mux, &mut ws.editing_title);
            if reaped.layout_changed || stale_title {
                ws.pending_resize = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            self.hoover_groups(ws);
            if reaped.mux_empty {
                return;
            }
            ws.search_queries
                .retain(|pane_id, _| ws.mux.panes.contains_key(pane_id));
            // Track output without locking every terminal on every blink or
            // UI-only frame. The reader publishes `output_generation` after its
            // terminal mutation, so a changed generation is cheap and, unlike
            // `history_size()`, also catches in-place and alternate-screen
            // output. Only the opt-in scroll-on-output action takes a grid lock.
            let want_sob = self.cfg.scroll_on_output;
            // Track which panes produced output this frame so
            // we can latch their tab's `last_output_at`. Collected here
            // and dispatched after the borrow ends — same shape as the
            // `bell_panes` collection in `drain_events`.
            let mut output_panes: Vec<u64> = Vec::new();
            for (&pane_id, pane) in ws.mux.panes.iter_mut() {
                let generation = pane.term.output_generation();
                let advanced = output_generation_advanced(pane.last_output_generation, generation);
                if advanced {
                    output_panes.push(pane_id);
                }
                if want_sob
                    && advanced
                    && let Ok(mut t) = pane.term.term.lock()
                {
                    t.scroll_display(Scroll::Bottom);
                }
                pane.last_output_generation = Some(generation);
            }
            for id in output_panes {
                ws.mux.touch_tab_output(id);
            }
            // Auto-scroll while a selection stays at or beyond the focused
            // pane's top or bottom edge.
            // Pure `selection_autoscroll_lines` chooses the per-frame rate;
            // scrolling the viewport here naturally re-fires `update_selection`
            // below to anchor the selection's end to the new visible line.
            if ws.selecting {
                let area = self.area(ws);
                if let Some(pane_id) = ws.selecting_pane
                    && let Some(rect) = self.pane_terminal(ws, area, pane_id)
                {
                    let scale = ws
                        .window
                        .as_ref()
                        .map_or(1.0, |window| window.scale_factor() as f32);
                    let lines = if ws.selection_autoscroll_edge != 0 {
                        i32::from(ws.selection_autoscroll_edge)
                    } else {
                        selection_autoscroll_lines(
                            ws.cursor.y as f32,
                            rect.1,
                            rect.1 + rect.3,
                            scale,
                            ws.selection_dragged,
                        )
                    };
                    if lines != 0
                        && let Some(p) = ws.mux.panes.get(&pane_id)
                        && let Ok(mut t) = p.term.term.lock()
                    {
                        t.scroll_display(Scroll::Delta(lines));
                    }
                    if lines != 0 {
                        // Re-anchor the selection's end at the (now-moved)
                        // cursor row so the highlight grows in step with the
                        // scroll, not stuck on the original click-time row.
                        self.update_selection(ws, area);
                    }
                } else {
                    // The owner may still exist in an inactive tab. Preserve
                    // copy-on-select before invalidating the gesture.
                    self.finish_selection_gesture(ws);
                }
            }
            self.update_search(ws);
            self.update_links(ws);
            // Link set may have changed (scroll, output, mode flip) — re-sync
            // the cursor icon so a URL scrolling out from under a held Ctrl
            // doesn't leave the pointer-hand icon stuck on a now-empty cell.
            // Deduped via `last_cursor_icon` so this is a cheap per-frame
            // recheck when nothing changed.
            self.sync_cursor_icon(ws);
        }
        let overlay = self.overlay(ws, reuse_pane_snapshots);
        // Search and completion state are semantic accessibility state. Reuse
        // the exact projection this frame will draw instead of rebuilding the
        // full overlay twice for the accessibility key and tree. Snapshot reuse
        // skips pane maintenance, not semantic publication: a pending update
        // must not be stranded by a run of context-menu hover frames.
        self.publish_accessibility_if_due(ws, &overlay);
        let area = self.area(ws);
        let tabbar = self.tab_bar(ws);
        // Build status bar BEFORE the &mut renderer borrow
        // since `build_status_bar` reads ws.mux / self.cfg
        // immutably.
        let status = self.build_status_bar(ws);
        let layout = self.pane_layout(ws, area);
        let focus = ws.mux.active_focus();
        let window = ws.window.clone();

        // A failed acquire/render owns the next GPU attempt until its one-shot
        // deadline is polled in about_to_wait. This gate also stops unrelated
        // cursor/input/output redraw requests from bypassing the backoff. Do
        // the non-GPU state maintenance above, but neither snapshot terminal
        // contents nor touch an invisible surface except for one explicit
        // offscreen capture. That exception may bypass a transient retry, never
        // a pending renderer rebuild.
        let screenshot_may_render_offscreen = ws.renderer.as_ref().is_some_and(|renderer| {
            ws.window.as_ref().is_some_and(|window| {
                pending_screenshot_may_render_offscreen(
                    renderer.has_pending_screenshot(),
                    window.is_minimized(),
                    ws.window_shown,
                    window.is_visible(),
                )
            })
        });
        let recovery_blocks_render = ws.frame_recovery.renderer_rebuild_pending()
            || (ws.frame_recovery.has_pending() && !screenshot_may_render_offscreen);
        if !ws.dpi_resize.render_allowed()
            || recovery_blocks_render
            || (window_is_render_hidden(ws) && !screenshot_may_render_offscreen)
        {
            return;
        }

        if ws.renderer.is_none() {
            return;
        }

        // Re-open each pane's output latch only when this window is about to
        // sample generations for a real frame. Keeping the latch closed across
        // the entire deferred frame budget collapses a fast reader's many
        // chunks into one event-loop wake without losing output that races the
        // snapshot below. This must follow every early-return guard: entering
        // Presenting without attempting a frame would strand the pacer and
        // schedule a near-zero recovery loop.
        self.acknowledge_output_wakes(ws);
        // Is this paint flushing coalesced PTY output? Retained until the
        // frame outcome so the flood detector advances only after
        // presentation (see `effective_output_budget`).
        let was_coalescing_paint = ws.output_pacer.begin_frame();

        // Capture the output generations represented by this candidate frame
        // before taking any new pane snapshots. A hover-only frame reuses the
        // exact cached generations rather than sampling live generations after
        // the reuse check; output racing either path therefore causes one
        // harmless extra repaint, never a missed repaint. The recycled map is
        // committed only after the surface is presented.
        stage_output_generations_for_frame(
            &mut ws.pending_output_gen,
            &ws.seen_output_gen,
            reuse_pane_snapshots.then_some(&ws.pane_snapshot_keys),
            ws.mux
                .panes
                .iter()
                .map(|(id, pane)| (*id, pane.term.output_generation())),
        );

        // Capture each visible pane's renderable state into a pooled snapshot
        // under the Term lock, then drop the guard at once (a microsecond-scale
        // flat copy per pane). The renderer works from the snapshots, so the
        // GPU frame (shaping, surface acquire, submit, present; milliseconds)
        // never holds a Term mutex. Holding them across the frame starves the
        // PTY parser on `term.lock()` under output flood. Also pass the pane's
        // title so the per-pane titlebar can render it.
        let mut snaps = std::mem::take(&mut ws.pane_snapshots);
        let mut snapshot_keys = std::mem::take(&mut ws.pane_snapshot_keys);
        if !reuse_pane_snapshots {
            snapshot_keys.clear();
        }
        let mut metas = Vec::with_capacity(layout.len());
        let home = crate::mux::home_dir_string();
        for (id, r) in &layout {
            if let Some(p) = ws.mux.panes.get(id) {
                // Each protocol registry has its own defensive cap. Interleave
                // all three before renderer-side visibility culling so a busy
                // class cannot hide the others, while offscreen entries do not
                // consume the smaller frame-wide draw quota.
                let per_class_limit = kettle_core::GraphicsLimits::default().placements;
                let imgs = round_robin_bounded(
                    [
                        p.term.placements(),
                        p.term.placeholder_tiles(),
                        p.term.relative_tiles(),
                    ],
                    per_class_limit.saturating_mul(3),
                );
                let si = metas.len();
                let snapshot_ready = if reuse_pane_snapshots {
                    snaps.get(si).is_some()
                } else {
                    let output_generation = p.term.output_generation();
                    let Ok(g) = p.term.term.lock() else {
                        continue;
                    };
                    if snaps.len() <= si {
                        snaps.push(PaneSnapshot::default());
                    }
                    snaps[si].capture_with_card_marks(&g, p.inline_cards.needs_marks());
                    drop(g); // lock released — the render below is lock-free
                    snapshot_keys.push((
                        *id,
                        output_generation,
                        snaps[si].columns,
                        snaps[si].screen_lines,
                    ));
                    true
                };
                if snapshot_ready {
                    let cwd = p.term.current_dir_or_native();
                    let mut title_parts = pane_title_parts(
                        &self.cfg.agent_badge,
                        p.agent_attached,
                        p.read_only,
                        &p.title,
                        p.title_is_placeholder,
                        cwd.as_deref(),
                        home.as_deref(),
                    );
                    title_parts
                        .prefix
                        .push_str(&media_shelf_badge(p.media_shelf.unseen()));
                    metas.push((
                        *id,
                        *r,
                        Some(*id) == focus,
                        imgs,
                        title_parts.prefix,
                        title_parts.title,
                        title_parts.path,
                        snaps[si].columns as u16,
                        snaps[si].screen_lines as u16,
                        // Terminator parity (`icon_bell`): the pane's own bell
                        // latch drives its titlebar bell indicator.
                        p.bell,
                        ws.bell_flashes
                            .get(id)
                            .map_or(0.0, |rang| bell_flash_ramp(rang.elapsed())),
                        p.group_name.clone(),
                    ));
                }
            }
        }
        snaps.truncate(metas.len());
        snapshot_keys.truncate(metas.len());
        // Hand the renderer borrows into `metas` (which lives
        // for the whole frame) instead of a second per-pane clone of the images
        // Vec / title String / group_name. `snap` borrows the pooled snapshot
        // the same way; both outlive `panes`, which drops before the pool
        // returns to `ws.pane_snapshots`.
        // An on-to-off edge the scheduler marked hands the blink to the window
        // server (macOS) if this frame still draws the off phase with nothing
        // holding the cursor. Only a successful main present lets the renderer
        // draw the patch into the layer's surface afterward.
        let blink_handoff = ws.blink_layer.take_pending_handoff()
            && self.cfg.macos_cursor_blink_layer
            && !overlay.cursor_visible
            && overlay.window_focused
            && overlay.ime_preedit.is_none()
            && Self::pane_cursor_layer_eligible(ws)
            && Self::ensure_cursor_layer(ws);
        let panes: Vec<PaneView> = metas
            .iter()
            .zip(snaps.iter())
            .map(
                |(
                    (id, r, f, imgs, prefix, title, path, cols, rows, bell, bell_flash, group_name),
                    snap,
                )| {
                    PaneView {
                        id: *id,
                        rect: r.leaf,
                        terminal: r.terminal,
                        titlebar: r.titlebar,
                        snap,
                        focused: *f,
                        images: imgs.as_slice(),
                        inline_cards: ws.mux.panes.get(id).map(|pane| &pane.inline_cards),
                        tr: self.ui_text,
                        title_prefix: prefix.as_str(),
                        title: title.as_str(),
                        title_path: path.as_deref(),
                        size_cols: *cols,
                        size_rows: *rows,
                        bell: *bell,
                        bell_flash: *bell_flash,
                        group_name: group_name.as_deref(),
                    }
                },
            )
            .collect();
        let live_opacity_floor = ws
            .native_material
            .as_ref()
            .and_then(|material| material.live_opacity_floor());
        // Whether anything covers the cards, for the tip: no dialog, menu or
        // viewer over them.
        let cards_uncovered = !self.pointer_modal_open(ws);
        // Status bar and native fallback state are built BEFORE the &mut
        // renderer borrow (the helpers read other window state immutably).
        let Some(renderer) = ws.renderer.as_mut() else {
            drop(panes);
            ws.pane_snapshots = snaps;
            ws.pane_snapshot_keys = snapshot_keys;
            ws.output_pacer.presentation_failed();
            return;
        };
        // AppKit clips a decorated window's bottom corners after the Metal
        // scene is drawn. Tell the renderer to replace the square pane-border
        // strips at those two outer corners with one concentric antialiased
        // outline. Borderless/fullscreen windows have square content surfaces;
        // every non-macOS platform deliberately stays on the existing path.
        // Use live native state: AppKit's green button bypasses our actions,
        // and a config reload cannot retrofit an existing window's decorations.
        let live_fullscreen = window
            .as_ref()
            .is_some_and(|window| window.fullscreen().is_some());
        let live_decorated = window.as_ref().is_some_and(|window| window.is_decorated());
        renderer.set_rounded_window_corners(rounded_window_corner_policy(
            cfg!(target_os = "macos"),
            live_decorated,
            live_fullscreen,
        ));
        renderer.set_live_background_opacity_floor(live_opacity_floor);
        // Any frame while the window server blinks the cursor ends that blink.
        // The frame presents in one Core Animation transaction with hiding the
        // layer, so the screen never shows new content under a stale cursor,
        // or the old frame with no cursor.
        let layer_exit = ws.blink_layer.is_active();
        let exit_started = std::time::Instant::now();
        let mut layer_exit_presented = false;
        if layer_exit && let Some(layer) = &ws.cursor_layer {
            layer.begin_exit_frame();
        }
        if let Some(window) = window.as_ref() {
            let window = Arc::downgrade(window);
            renderer.ensure_background_redraw(move || {
                if let Some(window) = window.upgrade() {
                    window.request_redraw();
                }
            });
        }
        let frame_started = std::time::Instant::now();
        let frame_result = renderer.render_frame_with_status_and_pre_present(
            &panes,
            &tabbar,
            &self.cfg,
            &overlay,
            &status,
            || {
                if let Some(window) = &window {
                    window.pre_present_notify();
                }
            },
        );
        let frame_time = frame_started.elapsed();
        // A card has been seen once a frame showing it reached the screen.
        let presented = matches!(&frame_result, Ok(FrameOutcome::Presented));
        if presented
            && ws
                .card_sightings
                .note(renderer.painted_cards(), std::time::Instant::now())
        {
            // Assistive technology names each card on screen, and the
            // pointer may rest on one that moved or arrived.
            ws.accessibility_pending = true;
            ws.card_hover_stale = true;
        }
        // The first card a user ever sees says a click opens it, once its
        // image is on screen with nothing over it: a card that loads in
        // place, or that a dialog or the viewer uncovers, qualifies then.
        let tip_begun = if presented && cards_uncovered {
            self.cards_tip.begin(
                renderer.shown_cards().map(|card| (card.pane, card.nonce)),
                std::time::Instant::now(),
            )
        } else {
            None
        };
        // C1 records only a presented scene. Reuse that scene immediately,
        // before any renderer setter can invalidate it, and with the same cfg.
        let cursor_patch = if blink_handoff && matches!(&frame_result, Ok(FrameOutcome::Presented))
        {
            Some(renderer.present_cursor_patch(&self.cfg))
        } else {
            None
        };
        // Return the snapshot pool (cell-Vec capacity recycles next frame).
        drop(panes);
        if let Some((pane, nonce)) = tip_begun
            && let Some(state) = ws.mux.panes.get_mut(&pane)
        {
            state.inline_cards.set_tip(Some(nonce));
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        ws.pane_snapshots = snaps;
        ws.pane_snapshot_keys = snapshot_keys;
        match frame_result {
            Ok(outcome) => {
                let presented = apply_output_generation_outcome(
                    outcome,
                    &mut ws.seen_output_gen,
                    &mut ws.pending_output_gen,
                );
                match outcome {
                    FrameOutcome::Presented => {
                        debug_assert!(presented);
                        // Commit the rest of the frame transaction only after
                        // presentation. Updating the output generation before
                        // presenting would lose terminal damage whenever
                        // surface acquisition times out.
                        ws.frame_recovery.presented();

                        // Fallback reveal: normal startup reveals as soon as
                        // renderer init succeeds, then paints immediately.
                        // Keep this guard so any future path that reaches a
                        // rendered frame while still hidden cannot leave a
                        // visible-state window invisible forever. No-op after
                        // the first reveal and for `window_state = hidden`.
                        if !ws.window_shown {
                            if let Some(w) = &ws.window {
                                w.set_visible(true);
                            }
                            ws.window_shown = true;
                            if ws.startup_window {
                                crate::startup_trace::mark(
                                    crate::startup_trace::Phase::WindowRevealed,
                                );
                            }
                            log::info!(
                                "startup: window revealed at first paint, working set {:.1} MiB",
                                process_working_set_mb()
                            );
                        }
                        // The first frame is the first one the startup window
                        // presents: a frame that timed out or found the window
                        // occluded is not.
                        if ws.startup_window {
                            crate::startup_trace::mark(crate::startup_trace::Phase::FirstFrame);
                            crate::startup_trace::flush();
                        }
                        ws.last_paint = Some(std::time::Instant::now());
                        ws.output_pacer.presented();
                        // Track sustained-flood depth. A frame that flushed
                        // coalesced output bumps the counter; any other paint
                        // resets it. Failed presentation does neither because
                        // no output was actually flushed to the display.
                        ws.flood_paints = if was_coalescing_paint {
                            ws.flood_paints.saturating_add(1)
                        } else {
                            0
                        };
                        ws.blink_layer.note_presented(std::time::Instant::now());
                        if layer_exit {
                            // Commits with this frame's present in
                            // `end_exit_frame` below.
                            if let Some(layer) = &ws.cursor_layer {
                                layer.hide();
                            }
                            layer_exit_presented = true;
                        } else if blink_handoff {
                            if let Some(patch) = cursor_patch {
                                self.start_layer_blink(ws, patch, window.as_deref());
                            } else {
                                ws.blink_layer.failed_handoff();
                            }
                        }
                    }
                    FrameOutcome::RetryLater => {
                        debug_assert!(!presented);
                        ws.output_pacer.presentation_failed();
                        // A backend acquire timeout may already have blocked
                        // for close to a second; Outdated has just
                        // reconfigured the existing surface. In either case,
                        // retain damage and let the one-shot backoff schedule
                        // the next acquire.
                        ws.frame_recovery
                            .schedule_transient_retry(std::time::Instant::now());
                    }
                    FrameOutcome::Occluded => {
                        debug_assert!(!presented);
                        ws.output_pacer.presentation_failed();
                        // The wgpu result can precede winit's OS occlusion
                        // event. Keep a slow self-healing deadline for a
                        // spurious/transient result, while the state machine
                        // becomes fully quiescent as soon as the window system
                        // confirms hidden/minimized/occluded state.
                        ws.frame_recovery
                            .schedule_occluded_retry(std::time::Instant::now());
                    }
                    FrameOutcome::SurfaceLost => {
                        debug_assert!(!presented);
                        ws.output_pacer.presentation_failed();
                        // wgpu 30 requires Instance::create_surface here.
                        // Rebuild only this renderer on the healthy shared
                        // device; genuine device loss is handled separately by
                        // the process-wide recovery guard.
                        ws.frame_recovery
                            .schedule_renderer_rebuild(std::time::Instant::now());
                    }
                }
            }
            Err(e) => {
                ws.output_pacer.presentation_failed();
                log::warn!("render error: {e}");
                // Fallible glyph preparation can advance retained renderer
                // damage keys before returning (for example AtlasFull). A
                // plain redraw could therefore reuse inconsistent caches and
                // strand terminal damage. Rebuild the affected renderer on a
                // bounded schedule unless the device callback already routed
                // this failure into process-wide recovery.
                if !self.gpu.as_ref().is_some_and(|gpu| gpu.is_lost()) {
                    ws.frame_recovery
                        .schedule_renderer_rebuild(std::time::Instant::now());
                }
            }
        }
        // A frame that did not present leaves the layer blinking over the
        // off-phase frame beneath it, which is still what the screen shows.
        if layer_exit && let Some(layer) = &ws.cursor_layer {
            layer.end_exit_frame();
        }
        let cursor_exit_end = if cursor_exit_frame.is_some() && layer_exit_presented {
            crate::cursor_exit_log::raw_now_ns()
        } else {
            None
        };
        if layer_exit_presented {
            let exit_time = exit_started.elapsed();
            ws.blink_layer.exited(exit_time);
            if ws.cursor_exit_log.enabled {
                if let Some(line) = ws.cursor_exit_log.finish_frame(
                    cursor_exit_frame,
                    layer_exit_presented,
                    cursor_exit_end,
                ) {
                    crate::cursor_exit_log::emit_line(&line);
                }
            } else {
                log::info!(target: CURSOR_BLINK_LOG, "exit_frame_us={} render_frame_us={}",
                    exit_time.as_micros(), frame_time.as_micros());
            }
            if !self.cfg.macos_cursor_blink_layer {
                Self::retire_cursor_layer(ws);
            }
        }
    }

    /// Compose the status-bar contents (HH:MM:SS · theme ·
    /// focused-pane title). Returns `StatusBar::hidden` when the
    /// config has it off. The renderer's draw is a no-op on a
    /// hidden status bar so this is cheap even when never visible.
    /// Takes `ws` mutably only because `Mux::focused` does; nothing
    /// is mutated here.
    fn build_status_bar(&mut self, ws: &mut WindowState) -> kettle_render::StatusBar {
        if matches!(self.cfg.status_bar, kettle_config::StatusBarMode::Off) {
            return kettle_render::StatusBar::hidden();
        }
        let h = self.status_bar_h(ws);
        let surface_h = ws
            .renderer
            .as_ref()
            .map(|r| r.surface_size().1 as f32)
            .unwrap_or(600.0);
        let y = match self.cfg.status_bar {
            kettle_config::StatusBarMode::Top => {
                if matches!(self.cfg.tab_bar_pos, TabBarPos::Top) {
                    self.tab_bar_h(ws)
                } else {
                    0.0
                }
            }
            kettle_config::StatusBarMode::Bottom => surface_h - self.search_bar_h(ws) - h,
            kettle_config::StatusBarMode::Off => 0.0,
        };
        // Compose text: local HH:MM:SS · theme · focused pane title.
        let (hh, mm, ss) = crate::wall_clock::now_local();
        let title = ws
            .mux
            .focused()
            .map(|p| p.title.clone())
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| "kettle".to_string());
        // Cap the title at a character budget so a chatty
        // prompt that puts the full cwd in the window title
        // (e.g. `PROMPT_COMMAND='echo -ne "\033]0;$PWD\007"'`)
        // doesn't overflow the strip's 1-cell height. Pure helper
        // so we can drift-guard it in tests.
        let title_capped = cap_title_for_status_bar(&title, 60);
        let text = format!(
            "{hh:02}:{mm:02}:{ss:02}  ·  {}  ·  {title_capped}",
            self.cfg.theme_name
        );
        kettle_render::StatusBar { height: h, y, text }
    }

    /// Snapshot the focused `(tab, leaf)` pair. Paired with
    /// `note_focus_change` to detect whether an operation moved focus
    /// and, if so, reset the cursor blink phase so the new pane's
    /// cursor is visible immediately. Keyboard and mouse paths share it.
    fn focus_key(&self, ws: &WindowState) -> (usize, Option<u64>) {
        (ws.mux.active, ws.mux.active_focus())
    }

    /// If the focused `(tab, leaf)` changed since `pre`, land the
    /// cursor visible on the new pane right away.
    fn note_focus_change(&mut self, ws: &mut WindowState, pre: (usize, Option<u64>)) {
        if self.focus_key(ws) != pre {
            // Focus moved to a pane, so not to a card any more.
            if ws.card_focus.take().is_some() {
                ws.accessibility_pending = true;
            }
            // Vi mode belongs to the pane that owns alacritty_terminal's
            // engine cursor. A focus change must not leave that old pane in
            // TermMode::VI while the UI routes keys to a different pane.
            self.exit_vi_mode(ws);
            self.reset_blink_phase(ws);
            // An open search bar follows focus (see `retarget_search_to_focus`).
            self.retarget_search_to_focus(ws);
            // Repaint immediately so the focused-pane border and the cursor's
            // solid/hollow state track the new pane. Otherwise a
            // focus-follows-mouse (`focus = sloppy`) change leaves the pane
            // under the cursor looking unfocused until some other event
            // triggers a redraw.
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
    }

    fn exit_vi_mode(&mut self, ws: &mut WindowState) {
        let Some(state) = ws.vi_mode.take() else {
            return;
        };
        if let Some(pane) = ws.mux.panes.get(&state.pane_id) {
            let mut term = pane
                .term
                .term
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            term.selection = None;
            if term.mode().contains(kettle_core::TermMode::VI) {
                term.toggle_vi_mode();
            }
        }
    }

    fn enter_vi_mode(&mut self, ws: &mut WindowState) {
        self.close_all_modals(ws);
        let Some(pane_id) = ws.mux.active_focus() else {
            return;
        };
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            return;
        };
        let mut term = pane
            .term
            .term
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        term.selection = None;
        if !term.mode().contains(kettle_core::TermMode::VI) {
            term.toggle_vi_mode();
        }
        drop(term);
        ws.vi_mode = Some(ViState {
            pane_id,
            visual: false,
        });
    }

    /// Close every modal overlay (search bar, command palette, settings,
    /// layout picker, hint mode, SSH launcher, context menu, title edit,
    /// vi mode, confirm dialog). Modal-opening actions call it first to avoid
    /// stacking two visible modals. A palette opened over the SSH launcher
    /// would render both, with only the palette capturing keys.
    fn close_all_modals(&mut self, ws: &mut WindowState) {
        if let Some(open) = ws.preview_overlay {
            self.close_preview(ws, open.pane);
        }
        // Opening or switching a modal takes pointer ownership. End a terminal
        // selection drag here so later motion cannot keep extending or
        // autoscrolling behind Command Palette, Settings, SSH, or title edit.
        self.finish_selection_gesture(ws);
        // A card held under a modal that opened is not clicked, even if the
        // modal is gone by the release.
        ws.card_press = None;
        // The modal that opens takes the keyboard from a preview lane, even
        // if it closes again before the event loop looks.
        self.exit_preview_focus(ws);
        // A live title edit materialises a chrome strip (see `tab_bar_h`), so
        // dropping it here changes the content rectangle. Resize only when it
        // was actually open -- this runs before every other modal opens, and an
        // unconditional resize would fire on all 17 call sites for nothing.
        let title_edit_was_open = ws.editing_title.is_some();
        let search_was_open = ws.search.open;
        self.close_search(ws);
        if !search_was_open {
            ws.ime_focus_generation = ws.ime_focus_generation.wrapping_add(1);
        }
        ws.palette_input = None;
        ws.settings_nav = None;
        // Also drop any open inline settings text prompt (the image-path
        // editor) so it can't linger after the panel closes / reopens.
        ws.settings_text_edit = None;
        ws.layout_picker_input = None;
        ws.theme_picker_input = None;
        ws.hint_state = None;
        ws.ssh_input = None;
        ws.context_menu = None;
        ws.editing_title = None;
        // Vi mode is backed by per-terminal engine state, so closing the modal
        // must clear both the UI owner and TermMode::VI.
        self.exit_vi_mode(ws);
        // The confirm dialog ("Close this pane?", "Quit?") is a modal too.
        // Leaving it up would render two overlays with ambiguous key focus.
        // Clearing it here is safe because no confirm opener calls
        // close_all_modals after installing its dialog.
        self.cancel_confirm_dialog(ws);
        if title_edit_was_open {
            ws.pending_resize = true;
        }
    }

    fn open_search(&mut self, ws: &mut WindowState) {
        self.close_all_modals(ws);
        self.release_held_buttons(ws, |_| true);
        ws.card_press = None;
        ws.last_mouse_cell = None;
        ws.scrollbar_drag_offset = None;
        ws.dragging_split = None;
        ws.tab_drag_active = false;
        ws.tab_drag_press = None;
        ws.tab_pressed_idx = None;
        ws.detach_drag = crate::detach::DragState::default();
        ws.drag_press = None;
        ws.pane_drag = None;
        if self.torn_drag.as_ref().is_some_and(|drag| {
            drag.seq == ws.seq
                || drag.carrier == ws.seq
                || drag.dock.is_some_and(|(seq, _)| seq == ws.seq)
        }) {
            self.abandon_torn_drag(Some(ws));
        }
        if ws.ime_preedit_owner.is_some() {
            // The composition belongs to the previously focused surface. Keep
            // its owner marker for the late Commit guard, but stop painting it
            // in the newly opened search editor.
            ws.ime_preedit = None;
        }
        let Some(pane_id) = ws.mux.active_focus() else {
            return;
        };
        self.attach_search_to_pane(ws, pane_id, None);
    }

    /// Build the bar's state for `pane_id`. `carried` is the editor text and
    /// toggles an already-open bar brings along when it follows focus to
    /// another pane; a fresh open starts from the pane's remembered query and
    /// the configured defaults.
    fn attach_search_to_pane(
        &mut self,
        ws: &mut WindowState,
        pane_id: u64,
        carried: Option<SearchCarryOver>,
    ) {
        let invert = carried
            .as_ref()
            .map_or(self.cfg.invert_search, |c| c.invert);
        let direction = if invert {
            kettle_core::SearchDirection::Reverse
        } else {
            kettle_core::SearchDirection::Forward
        };
        let display_offset = ws
            .mux
            .panes
            .get(&pane_id)
            .and_then(|pane| {
                pane.term
                    .term
                    .lock()
                    .ok()
                    .map(|term| term.grid().display_offset())
            })
            .unwrap_or(0);
        let remembered = ws.search_queries.get(&pane_id).cloned().unwrap_or_default();
        let defaults = SearchCarryOver {
            query: remembered,
            wrap: self.cfg.search_wrap,
            case_mode: self.cfg.search_case_sensitive,
            invert: self.cfg.invert_search,
            focused_control: kettle_render::SearchControl::Editor,
        };
        ws.search = fresh_search_state(
            pane_id,
            carried.unwrap_or(defaults),
            display_offset,
            std::time::Instant::now(),
        );
        self.resize_all(ws);
        // Reserving the responsive Search lane can shrink the terminal by several rows. In a
        // scrolled-back grid Alacritty increases display_offset to preserve the viewed content,
        // so derive the scan anchor only after that resize has settled.
        ws.search.anchor = ws.mux.panes.get(&pane_id).and_then(|pane| {
            let term = pane.term.term.lock().ok()?;
            use kettle_core::Dimensions as _;
            Some(search_viewport_anchor(
                term.grid().display_offset(),
                term.screen_lines(),
                term.last_column().0,
                direction,
            ))
        });
    }

    /// Move the open bar to the focused pane. The bar is window-level and the
    /// grid stays clickable while it is open, so a click that focuses another
    /// pane must also make typing search that pane. The query and toggles come
    /// along. The old pane keeps the query in its remembered-query slot and,
    /// with no focused result, gets its pre-search viewport back, as closing
    /// would. The new pane is scanned afresh.
    fn retarget_search_to_focus(&mut self, ws: &mut WindowState) {
        if !ws.search.open {
            return;
        }
        let Some(pane_id) = ws.mux.active_focus() else {
            return;
        };
        if search_retarget(ws.search.target_pane, Some(pane_id)).is_none() {
            return;
        }
        let carried = SearchCarryOver {
            query: ws.search.query().to_string(),
            wrap: ws.search.wrap,
            case_mode: ws.search.case_mode,
            invert: ws.search.invert,
            focused_control: ws.search.focused_control,
        };
        self.remember_search_query(ws);
        self.restore_search_viewport(ws);
        self.attach_search_to_pane(ws, pane_id, Some(carried));
    }

    /// Park the bar's query in its target pane's remembered-query slot.
    fn remember_search_query(&mut self, ws: &mut WindowState) {
        if let Some(pane_id) = ws.search.target_pane
            && ws.mux.panes.contains_key(&pane_id)
        {
            ws.search_queries
                .insert(pane_id, ws.search.query().to_string());
        }
    }

    /// With no focused result, put the target pane's viewport back where it
    /// was before the bar opened. A focused result stays where it is: grid
    /// growth already preserves the visible content, so no coordinate
    /// arithmetic is needed and the pre-grow span is intentionally stale.
    fn restore_search_viewport(&mut self, ws: &mut WindowState) {
        if ws.search.focused.is_some() {
            return;
        }
        let fallback_offset = ws.search.pre_open_display_offset;
        if let Some(pane_id) = ws.search.target_pane
            && let Some(pane) = ws.mux.panes.get(&pane_id)
            && let Ok(mut term) = pane.term.term.lock()
        {
            let current = term.grid().display_offset();
            let wanted = fallback_offset
                .unwrap_or(current)
                .min(term.grid().history_size());
            if wanted != current {
                term.scroll_display(kettle_core::Scroll::Delta(wanted as i32 - current as i32));
            }
        }
    }

    fn close_search(&mut self, ws: &mut WindowState) {
        if !ws.search.open {
            return;
        }
        ws.ime_focus_generation = ws.ime_focus_generation.wrapping_add(1);
        self.remember_search_query(ws);
        if matches!(
            ws.ime_preedit_owner.map(|session| session.owner),
            Some(crate::window_state::ImePreeditOwner::Search)
        ) {
            // Keep the owner marker until Commit/Disabled so a late commit is
            // recognized and discarded by the IME event path.
            ws.ime_preedit = None;
        }
        ws.search.open = false;
        ws.search.background = None;
        ws.search.unlimited_retry_at = None;
        ws.search.quiet_retry_pending = false;
        ws.search.visible.clear();
        ws.search.visible_scan = None;
        ws.search.visible_turn_pending = false;
        // Dropping the lane grows the grid, and Alacritty adjusts
        // display_offset to keep the viewed content, so the viewport is
        // restored only after that resize has settled.
        self.resize_all(ws);
        self.restore_search_viewport(ws);
        self.reset_blink_phase(ws);
        // The remembered query now has a single pane-scoped owner. Drop the
        // closed editor, compiled DFA, coordinates, and cache immediately so a
        // dead pane cannot retain sensitive text for the process lifetime.
        ws.search = crate::search_input::SearchState::default();
    }

    /// Apply the in-progress title edit + clear the
    /// overlay. The scope decides which setter is invoked.
    fn apply_title_edit(&mut self, ws: &mut WindowState) {
        if let Some(state) = ws.editing_title.take() {
            ws.pending_resize = true;
            match state.scope {
                TitleEditScope::Window => {
                    let value = state.input;
                    // Empty clears the override and restores the
                    // `window-title-format` behaviour; anything else pins it
                    // as the base for `sync_window_title`.
                    ws.window_title_override = if value.trim().is_empty() {
                        None
                    } else {
                        Some(value)
                    };
                    self.sync_window_title(ws);
                }
                _ => {
                    apply_mux_title_edit(&mut ws.mux, &state);
                }
            }
        }
        self.hoover_groups(ws);
    }

    /// `true` while a modal owns the whole pointer surface. This is
    /// `any_modal_open` minus the search bar: the bar reserves its own lane
    /// below the grid and leaves the grid mouse-interactive, so it must not
    /// swallow pointer events the way the palette, settings, hints, SSH
    /// launcher, title editor, vi mode, or a confirm dialog do. Keyboard
    /// routing, focus-follows-mouse, and file drops keep using
    /// `any_modal_open`, because search does own the keyboard.
    fn pointer_modal_open(&self, ws: &WindowState) -> bool {
        self.non_search_modal_open(ws) || ws.preview_overlay.is_some()
    }

    /// Track the search control under the pointer for the hover fill, and
    /// redraw only when it changes.
    fn update_search_hover(&mut self, ws: &mut WindowState) {
        let hovered = self
            .search_geometry(ws)
            .and_then(|geometry| geometry.hit_test(ws.cursor.x as f32, ws.cursor.y as f32))
            .filter(|control| *control != kettle_render::SearchControl::Editor);
        if ws.search.hovered_control != hovered {
            ws.search.hovered_control = hovered;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
    }

    /// Whether the pointer is inside the open search bar's reserved lane.
    fn cursor_in_search_bar(&self, ws: &WindowState) -> bool {
        self.search_geometry(ws).is_some_and(|geometry| {
            rect_contains(geometry.rect, ws.cursor.x as f32, ws.cursor.y as f32)
        })
    }

    /// Every modal that owns the keyboard and more: the search bar as well
    /// as those that own the pointer too. A preview lane holding the
    /// keyboard is not one: the pointer, the wheel and file drops still work
    /// everywhere else.
    fn any_modal_open(&self, ws: &WindowState) -> bool {
        ws.search.open || self.pointer_modal_open(ws)
    }

    /// Whether the focused Settings row is a number, which Left/Right step.
    fn settings_row_steps(&self, ws: &WindowState) -> bool {
        let Some(nav) = ws.settings_nav.as_ref() else {
            return false;
        };
        crate::settings::categories(&self.gpu_choices)
            .get(nav.category)
            .and_then(|category| category.fields.get(nav.field))
            .is_some_and(|field| matches!(field.kind, crate::settings::FieldKind::Number { .. }))
    }

    /// Every modal except the search bar. The one list both
    /// `any_modal_open` and `pointer_modal_open` derive from, so the two
    /// cannot drift apart on anything but search.
    fn non_search_modal_open(&self, ws: &WindowState) -> bool {
        ws.palette_input.is_some()
            || ws.settings_nav.is_some()
            || ws.layout_picker_input.is_some()
            || ws.theme_picker_input.is_some()
            || ws.hint_state.is_some()
            || ws.ssh_input.is_some()
            || ws.context_menu.is_some()
            || ws.editing_title.is_some()
            || ws.vi_mode.is_some()
            // The confirm dialog is a modal too. Its keys have a dedicated
            // priority branch, but mouse, scroll, and cursor gating read this
            // list. Without it, clicks fall through to the terminal behind a
            // "Quit?" / "Close pane?" prompt.
            || ws.confirm_dialog.is_some()
    }

    /// Build the right-click context-menu item list. Each `Item`'s
    /// `enabled` flag is computed from current state: Copy needs a
    /// selection, the split rows need an unzoomed tab, and Ungroup needs
    /// the focused pane to be in a group. `show_context_menu` runs the list
    /// through `filter_disabled`, which hides disabled rows and the
    /// separators they would orphan (Terminator-style) instead of greying
    /// them out. That cuts visual clutter and leaves every visible row
    /// actionable.
    fn context_menu_items(&mut self, ws: &mut WindowState) -> Vec<ContextMenuItem> {
        let has_selection = ws
            .mux
            .focused()
            .and_then(|p| p.term.term.lock().ok().map(|t| t.selection.is_some()))
            .unwrap_or(false);
        // Only enable Ungroup when the focused pane has a group_name set.
        // Otherwise the row is filtered out until it's actionable, since a
        // greyed-out row confuses new users.
        let has_group = ws
            .mux
            .focused()
            .map(|p| p.group_name.as_ref().is_some_and(|g| !g.is_empty()))
            .unwrap_or(false);
        // Terminator parity, terminal_popup_menu.py "Read only":
        // checked while the focused pane drops user input.
        let read_only = ws.mux.focused().map(|p| p.read_only).unwrap_or(false);
        // Terminator parity, terminal_popup_menu.py: the split rows are offered
        // only when NOT zoomed — a zoomed pane is showing alone, so splitting it
        // has nothing to put the new pane beside. The zoom row itself swaps
        // label with the state, the way Terminator's Zoom/Restore pair does.
        let zoomed = ws
            .mux
            .tabs
            .get(ws.mux.active)
            .map(|t| t.zoomed)
            .unwrap_or(false);
        use kettle_i18n::Text as T;
        let tr = self.ui_text;
        vec![
            ContextMenuItem::Item {
                label: tr.text(T::MenuCopy),
                action: Action::Copy,
                enabled: has_selection,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuPaste),
                action: Action::Paste,
                enabled: true,
            },
            ContextMenuItem::Separator,
            // `Split Auto` splits along the pane's longer axis — Terminator
            // offers it first because it is the one that needs no decision.
            ContextMenuItem::Item {
                label: tr.text(T::MenuSplitAuto),
                action: Action::SplitAuto,
                enabled: !zoomed,
            },
            // Ghostty's four sides, in its order: Right, Left, Down, Up.
            ContextMenuItem::Item {
                label: tr.text(T::MenuSplitRight),
                action: Action::SplitRight,
                enabled: !zoomed,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuSplitLeft),
                action: Action::SplitLeft,
                enabled: !zoomed,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuSplitDown),
                action: Action::SplitDown,
                enabled: !zoomed,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuSplitUp),
                action: Action::SplitUp,
                enabled: !zoomed,
            },
            ContextMenuItem::DynamicItem {
                label: tr
                    .text(if zoomed { T::MenuRestore } else { T::MenuZoom })
                    .to_string(),
                action: Action::ToggleZoom,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuClosePane),
                action: Action::ClosePane,
                enabled: true,
            },
            ContextMenuItem::Separator,
            ContextMenuItem::Item {
                label: tr.text(T::MenuNewTab),
                action: Action::NewTab,
                enabled: true,
            },
            // Ghostty's Tab and Window submenu rows, flattened.
            ContextMenuItem::Item {
                label: tr.text(T::MenuCloseTab),
                action: Action::CloseTab,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuNewWindow),
                action: Action::NewWindow,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuCloseWindow),
                action: Action::CloseWindow,
                enabled: true,
            },
            // Terminator parity, terminal_popup_menu.py "Set Window Title".
            ContextMenuItem::Item {
                label: tr.text(T::MenuSetWindowTitle),
                action: Action::EditWindowTitle,
                enabled: true,
            },
            // The same editors as a double-click on a tab or a pane titlebar.
            ContextMenuItem::Item {
                label: tr.text(T::MenuSetTabTitle),
                action: Action::EditTabTitle,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuSetPaneTitle),
                action: Action::EditPaneTitle,
                enabled: true,
            },
            ContextMenuItem::Separator,
            // Ghostty's "Reset Terminal": RIS on this pane's terminal.
            ContextMenuItem::Item {
                label: tr.text(T::MenuResetTerminal),
                action: Action::Reset,
                enabled: true,
            },
            // Terminator parity: per-pane read-only toggle. The
            // check marker mirrors the Preferences-submenu convention
            // ("✓ on / off"); dispatch goes through the same
            // `Action::TogglePaneReadOnly` the keybind uses.
            ContextMenuItem::DynamicItem {
                label: format!(
                    "{}{}",
                    if read_only { "✓ " } else { "  " },
                    tr.text(T::MenuReadOnly)
                ),
                action: Action::TogglePaneReadOnly,
                enabled: true,
            },
            // Right-click entries for the broadcast-group surface. Layered
            // below the close-family + new-tab so they don't
            // hijack muscle memory; users who never use groups
            // see them at the bottom and can ignore.
            ContextMenuItem::Separator,
            ContextMenuItem::Item {
                label: tr.text(T::MenuSetGroup),
                action: Action::CreateGroup,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuGroupTab),
                action: Action::GroupTab,
                enabled: true,
            },
            ContextMenuItem::Item {
                label: tr.text(T::MenuUngroupTab),
                action: Action::UngroupTab,
                enabled: has_group,
            },
        ]
    }

    /// Terminator parity, `custom_commands.py`: append every
    /// `menu-item = LABEL = CMD` config entry to the context-menu item list,
    /// preceded by a separator. `open_context_menu` calls it after the
    /// built-in items and before the Lua-registered items, matching the
    /// layered priority: kettle's own, then the user's config file, then
    /// their Lua plugins.
    fn append_config_menu_items(&self, items: &mut Vec<ContextMenuItem>) {
        if self.cfg.menu_items.is_empty() {
            return;
        }
        items.push(ContextMenuItem::Separator);
        for mi in &self.cfg.menu_items {
            items.push(ContextMenuItem::ConfigItem {
                label: mi.label.clone(),
                command: mi.command.clone(),
            });
        }
    }

    /// Append runtime settings to the Preferences submenu. Each action updates
    /// the live config and persists through `persist_config_toggle`; radio and
    /// check marks are labels rather than separate state.
    fn append_preferences_submenu_items(&self, items: &mut Vec<ContextMenuItem>) {
        use kettle_i18n::Text as T;
        let tr = &self.ui_text;
        items.push(ContextMenuItem::Separator);
        let mut inner: Vec<ContextMenuItem> = Vec::new();
        let r = |sel: bool| if sel { "● " } else { "○ " };
        let c = |sel: bool| if sel { "✓ " } else { "  " };
        let dyn_item = |label: String, action: Action| ContextMenuItem::DynamicItem {
            label,
            action,
            enabled: true,
        };
        // Scrollbar radio.
        let sb = self.cfg.scrollbar;
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(sb == kettle_config::ScrollbarMode::Always),
                tr.text(T::MenuPrefScrollbarAlways)
            ),
            Action::SetScrollbarAlways,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(sb == kettle_config::ScrollbarMode::Auto),
                tr.text(T::MenuPrefScrollbarAuto)
            ),
            Action::SetScrollbarAuto,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(sb == kettle_config::ScrollbarMode::Never),
                tr.text(T::MenuPrefScrollbarHidden)
            ),
            Action::SetScrollbarNever,
        ));
        inner.push(ContextMenuItem::Separator);
        // Boolean toggles.
        inner.push(dyn_item(
            format!(
                "{}{}",
                c(self.cfg.cursor_blink),
                tr.text(T::MenuPrefCursorBlink)
            ),
            Action::ToggleCursorBlink,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                c(self.cfg.copy_on_select),
                tr.text(T::MenuPrefCopyOnSelect)
            ),
            Action::ToggleCopyOnSelect,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                c(self.cfg.mouse_hide_while_typing),
                tr.text(T::MenuPrefMouseHide)
            ),
            Action::ToggleMouseHide,
        ));
        inner.push(ContextMenuItem::Separator);
        // Close-confirmation radio. `always` is worded to say that it also
        // covers the titlebar close, because that gesture ignores the other
        // two policies by design.
        let ask_before_closing = self.cfg.ask_before_closing;
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(ask_before_closing == kettle_config::AskBeforeClosing::Always),
                tr.text(T::MenuPrefConfirmAlways)
            ),
            Action::SetAskBeforeClosingAlways,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(ask_before_closing == kettle_config::AskBeforeClosing::MultipleTerminals),
                tr.text(T::MenuPrefConfirmMultiple)
            ),
            Action::SetAskBeforeClosingMultiple,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(ask_before_closing == kettle_config::AskBeforeClosing::Never),
                tr.text(T::MenuPrefConfirmNever)
            ),
            Action::SetAskBeforeClosingNever,
        ));
        inner.push(ContextMenuItem::Separator);
        // Bell radio.
        let bell = self.cfg.bell;
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(bell == kettle_config::BellMode::Off),
                tr.text(T::MenuPrefBellOff)
            ),
            Action::SetBellOff,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(bell == kettle_config::BellMode::Visual),
                tr.text(T::MenuPrefBellVisual)
            ),
            Action::SetBellVisual,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(bell == kettle_config::BellMode::Attention),
                tr.text(T::MenuPrefBellAttention)
            ),
            Action::SetBellAttention,
        ));
        inner.push(dyn_item(
            format!(
                "{}{}",
                r(bell == kettle_config::BellMode::Both),
                tr.text(T::MenuPrefBellBoth)
            ),
            Action::SetBellBoth,
        ));
        inner.push(ContextMenuItem::Separator);
        // Font size +/- (reuse existing actions).
        inner.push(ContextMenuItem::Item {
            label: tr.text(T::MenuPrefFontBigger),
            action: kettle_config::Action::IncreaseFontSize,
            enabled: true,
        });
        inner.push(ContextMenuItem::Item {
            label: tr.text(T::MenuPrefFontSmaller),
            action: kettle_config::Action::DecreaseFontSize,
            enabled: true,
        });
        inner.push(ContextMenuItem::Separator);
        // The Advanced… escape hatch for everything not exposed as a toggle.
        inner.push(ContextMenuItem::Item {
            label: tr.text(T::MenuPrefAdvanced),
            action: kettle_config::Action::EditConfig,
            enabled: true,
        });
        items.push(ContextMenuItem::Submenu {
            label: tr.text(T::MenuPreferences).to_string(),
            items: inner,
        });
    }

    fn append_profile_submenu_items(&self, items: &mut Vec<ContextMenuItem>) {
        let profile_names = kettle_config::Config::list_profiles();
        if profile_names.is_empty() {
            return;
        }
        items.push(ContextMenuItem::Separator);
        let inner: Vec<ContextMenuItem> = profile_names
            .into_iter()
            .map(|name| ContextMenuItem::ProfileChoice {
                label: name.clone(),
                profile: name,
            })
            .collect();
        items.push(ContextMenuItem::Submenu {
            label: self
                .ui_text
                .text(kettle_i18n::Text::MenuProfile)
                .to_string(),
            items: inner,
        });
    }

    /// Append a "Theme…" entry that opens the searchable theme picker, which
    /// replaced a submenu of every bundled theme.
    fn append_theme_menu_item(&self, items: &mut Vec<ContextMenuItem>) {
        items.push(ContextMenuItem::Separator);
        items.push(ContextMenuItem::Item {
            label: self.ui_text.text(kettle_i18n::Text::MenuThemePicker),
            action: kettle_config::Action::OpenThemePicker,
            enabled: true,
        });
    }

    fn append_remote_menu_items(&mut self, ws: &mut WindowState, items: &mut Vec<ContextMenuItem>) {
        let Some(pane) = ws.mux.focused() else {
            return;
        };
        let Some(ctx) = &pane.remote_context else {
            return;
        };
        // clone_session_command returns None when a host/user/container token
        // is unsafe (control chars / shell metachars that can't be
        // neutralized). Drop the menu item and its separator rather than type
        // an unsafe line into the PTY.
        if let Some(command) = kettle_remote::clone_session_command(ctx) {
            items.push(ContextMenuItem::Separator);
            items.push(ContextMenuItem::ConfigItem {
                label: remote_reconnect_label(ctx, &self.ui_text),
                command,
            });
        }
    }

    /// Terminator plugin parity: append every Lua-registered menu item to
    /// the context-menu item list. `open_context_menu` calls it after the
    /// built-in and config-file rows. Each entry's label is shown; clicking
    /// dispatches the registered Lua callback (via
    /// `LuaEngine::invoke_menu_item`).
    fn append_lua_menu_items(&self, items: &mut Vec<ContextMenuItem>) {
        if let Some(eng) = &self.lua_engine
            && let Ok(labels) = eng.list_menu_item_labels()
            && !labels.is_empty()
        {
            items.push(ContextMenuItem::Separator);
            for (idx, label) in labels.into_iter().enumerate() {
                items.push(ContextMenuItem::LuaItem {
                    label,
                    lua_idx: idx,
                });
            }
        }
    }

    /// Open the right-click context menu at `(px, py)`. Closes every other
    /// modal except an open search bar, then `show_context_menu` sizes the
    /// panel from the cell metrics and clamps the anchor so the menu fits
    /// the surface (right-click near the bottom-right corner flips up-
    /// and-left rather than rendering off-screen).
    /// Open the right-click menu at (`px`, `py`). `offer_copied`, for a
    /// Shift+right-click only, also offers the file the clipboard names.
    fn open_context_menu(&mut self, ws: &mut WindowState, px: f32, py: f32, offer_copied: bool) {
        self.close_modals_for_context_menu(ws);
        // Terminator parity, terminal_popup_menu.py "Open link" /
        // "Copy address": when the right-click landed on a detected
        // hyperlink, lead with the URL rows. The URL is captured NOW — fresh
        // output scrolling the grid between open and click must not retarget
        // the action. `update_links` is keyed so this is a no-op
        // when the viewport hasn't changed since the last scan.
        self.update_links(ws);
        use kettle_i18n::Text as T;
        let tr = self.ui_text;
        // Only offer the rows when the click is INSIDE the
        // focused pane's rect. `cursor_cell` clamps out-of-rect coordinates to
        // the nearest cell (xterm parity — right for mouse reports), which
        // here could surface "Open Link" for a link the user never pointed at
        // (right-click on chrome / another pane mapping into the focused grid).
        let in_focused_pane = self
            .focused_terminal(ws, self.area(ws))
            .is_some_and(|(rx, ry, rw, rh)| px >= rx && px < rx + rw && py >= ry && py < ry + rh);
        let mut items = Vec::new();
        if in_focused_pane && let Some(url) = self.link_at_cursor(ws).map(|l| l.uri.clone()) {
            items.extend(link_menu_rows(&url, links_pane(ws), tr));
        }
        // A selection holding a diagram an agent printed offers it, even
        // one whose wraps will turn out not to join: picking it says why.
        let offers_diagram = |result: &Result<Vec<String>, kettle_core::DiagramCopyError>| {
            !matches!(
                result,
                Err(kettle_core::DiagramCopyError::Empty | kettle_core::DiagramCopyError::NoDiagram)
            )
        };
        // Only the user's own click reads a selection or the clipboard: a
        // control client driving the menu gets neither probed.
        let reads = !self.ctl_driving;
        let selection_pane = ws.selecting_pane.or_else(|| ws.mux.active_focus());
        if reads
            && in_focused_pane
            && let Some(pane) = selection_pane
            && offers_diagram(&self.selected_diagram(ws, pane))
        {
            items.push(ContextMenuItem::Item {
                label: tr.text(T::MenuPreviewSelectedDiagram),
                action: kettle_config::Action::RenderSelectionAsDiagram,
                enabled: true,
            });
            items.push(ContextMenuItem::Separator);
        }
        // Shift+right-click also offers the file the clipboard names, and
        // the diagram it holds. Only then is the clipboard read, so a slow
        // clipboard owner never holds up a plain right-click or a menu
        // opened from the keyboard.
        if reads
            && in_focused_pane
            && offer_copied
            && let Some(pane) = ws.mux.active_focus()
        {
            let file = self.copied_preview(ws, pane).is_some();
            let diagram = offers_diagram(&self.copied_diagram());
            if file {
                items.push(ContextMenuItem::Item {
                    label: tr.text(T::MenuPreviewCopiedFile),
                    action: kettle_config::Action::PreviewClipboardPath,
                    enabled: true,
                });
            }
            if diagram {
                items.push(ContextMenuItem::Item {
                    label: tr.text(T::MenuPreviewCopiedDiagram),
                    action: kettle_config::Action::RenderClipboardAsDiagram,
                    enabled: true,
                });
            }
            if file || diagram {
                items.push(ContextMenuItem::Separator);
            }
        }
        items.extend(self.context_menu_items(ws));
        self.append_config_menu_items(&mut items);
        self.append_lua_menu_items(&mut items);
        // Append the remote-session reconnect entry when the focused pane
        // has a detected SSH/Docker/Podman/kubectl context.
        self.append_remote_menu_items(ws, &mut items);
        self.append_theme_menu_item(&mut items);
        // Same machinery for Profile, appended only when
        // ~/.config/kettle/profiles/ has any *.config files.
        self.append_profile_submenu_items(&mut items);
        // Top-level "Settings…" entry opens the full in-app
        // settings overlay (the richer, keyboard-navigable panel). The
        // Preferences ▸ submenu below stays as the quick-toggle surface.
        items.push(ContextMenuItem::Separator);
        items.push(ContextMenuItem::Item {
            label: tr.text(T::MenuSettings),
            action: kettle_config::Action::OpenSettings,
            enabled: true,
        });
        // Preferences submenu: runtime-mutable settings + the Advanced…
        // escape hatch.
        self.append_preferences_submenu_items(&mut items);
        self.show_context_menu(ws, items, px, py);
    }

    /// Shared tail of context-menu opening — drop disabled rows +
    /// collapse orphaned separators, compute panel geometry, clamp the anchor
    /// on-screen, and install the `ContextMenuState`. Used by both the
    /// right-click menu and the new-tab `▾` dropdown so they render
    /// pixel-identically.
    /// The popup menu over the grid leaves an open search bar in place, as
    /// Terminator leaves its bar under the menu: the user right-clicks to copy
    /// what they just selected under the query, not to abandon the query.
    /// Search is the only modal that can be open together with the menu:
    /// every other opener runs `close_all_modals`, which closes search, and
    /// search's own opener closes everything else. Keys go to the menu while
    /// it is up (its arm precedes search in the key handler) and return to the
    /// editor when it closes. `show_context_menu` ends the pointer gestures a
    /// modal must not leave armed.
    fn close_modals_for_context_menu(&mut self, ws: &mut WindowState) {
        if ws.search.open {
            ws.context_menu = None;
        } else {
            self.close_all_modals(ws);
        }
    }

    fn show_context_menu(
        &mut self,
        ws: &mut WindowState,
        items: Vec<ContextMenuItem>,
        px: f32,
        py: f32,
    ) {
        // A menu takes exclusive ownership of pointer motion. Preserve the
        // completed selection itself, but end any gesture that could otherwise
        // keep mutating selection, scrollback, split geometry, or tab layout
        // behind the menu. CursorMoved deliberately preserves the hover-reuse
        // hint, so leaving one of these armed would make the cached snapshot
        // stale without changing output_generation.
        self.finish_selection_gesture(ws);
        ws.scrollbar_drag_offset = None;
        ws.dragging_split = None;
        self.release_held_buttons(ws, |_| true);
        ws.card_press = None;
        ws.last_mouse_cell = None;
        ws.tab_drag_active = false;
        ws.tab_drag_press = None;
        ws.tab_pressed_idx = None;
        ws.detach_drag = crate::detach::DragState::default();
        ws.drag_press = None;
        ws.pane_drag = None;
        ws.lane_drag = None;
        self.end_lane_resize(ws);
        ws.reuse_pane_snapshots_once = false;
        if self.torn_drag.as_ref().is_some_and(|drag| {
            drag.seq == ws.seq
                || drag.carrier == ws.seq
                || drag.dock.is_some_and(|(seq, _)| seq == ws.seq)
        }) {
            self.abandon_torn_drag(Some(ws));
        }

        // Terminator menu UX: every visible row is actionable.
        let items = filter_disabled(items);
        let highlight = items.iter().position(item_is_dispatchable).unwrap_or(0);
        let (cw, ch) = self.menu_cell(ws);
        let row_h = ch + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        let panel_h: f32 = items
            .iter()
            .map(|it| match it {
                ContextMenuItem::Separator => sep_h,
                ContextMenuItem::Item { .. }
                | ContextMenuItem::DynamicItem { .. }
                | ContextMenuItem::LuaItem { .. }
                | ContextMenuItem::ConfigItem { .. }
                | ContextMenuItem::Submenu { .. }
                | ContextMenuItem::WindowChoice { .. }
                | ContextMenuItem::ProfileChoice { .. }
                | ContextMenuItem::NewTabShell { .. }
                | ContextMenuItem::UrlItem { .. }
                | ContextMenuItem::Media { .. }
                | ContextMenuItem::Info { .. } => row_h,
            })
            .sum();
        // Dropdown parity: the width budget includes each row's
        // right-aligned shortcut hint (+2 spacer columns) — the same formula
        // the renderer's `menu_row_chars` uses, kept in lockstep.
        let hints = self.menu_item_hints(&items);
        let max_columns = items
            .iter()
            .zip(hints.iter())
            .map(|(item, hint)| context_menu_item_columns(item, hint))
            .max()
            .unwrap_or(0) as f32;
        let panel_w = kettle_render::menu::panel_width(max_columns, cw);
        let (sw, sh) = ws
            .renderer
            .as_ref()
            .map(|r| {
                let (w, h) = r.surface_size();
                (w as f32, h as f32)
            })
            .unwrap_or((800.0, 600.0));
        if !context_menu_surface_can_fit_row((sw, sh), (cw, ch)) {
            ws.context_menu = None;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
            return;
        }
        let panel = clamp_context_menu_panel((panel_w, panel_h), (sw, sh));
        let anchor = clamp_context_menu_anchor((px, py), panel, (sw, sh));
        let anchor_scale = ws
            .window
            .as_ref()
            .map(|window| window.scale_factor())
            .unwrap_or(1.0);
        ws.context_menu = Some(ContextMenuState {
            anchor,
            anchor_scale,
            items,
            highlight,
            drill_stack: Vec::new(),
            scroll_offset: 0,
            scroll_stack: Vec::new(),
            typeahead_buf: String::new(),
            typeahead_until: None,
        });
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// The renderer's FRACTIONAL cell metrics, for menu geometry. `cell_px`
    /// rounds to integers for the PTY grid, but the renderer positions menu
    /// rows with the f32 metrics. The rounded value under-measures the panel
    /// by ~0.5px per row, enough to clip the last row of a 9-row dropdown and
    /// draw a phantom "more rows" scroll marker.
    fn menu_cell(&self, ws: &WindowState) -> (f32, f32) {
        ws.renderer
            .as_ref()
            .map(|r| (r.cell_w, r.cell_h))
            .unwrap_or((8.0, 16.0))
    }

    fn overlay_text_line_height(&self, ws: &WindowState) -> f32 {
        ws.renderer
            .as_ref()
            .map(|renderer| renderer.overlay_text_line_height())
            .unwrap_or(self.menu_cell(ws).1)
    }

    fn overlay_text_cell_width(&self, ws: &WindowState) -> f32 {
        ws.renderer
            .as_ref()
            .map(|renderer| renderer.overlay_text_cell_width())
            .unwrap_or(self.menu_cell(ws).0)
    }

    /// Reconcile the live theme with the theme picker after every event (see
    /// `theme_preview_change`).
    fn sync_theme_preview(&mut self, ws: &mut WindowState) {
        if let Some((name, theme)) = theme_preview_change(ws, &self.cfg.theme_name) {
            self.set_runtime_theme_state(ws, name, theme);
        }
    }

    /// Build the renderer-side settings projection from the live `settings_nav`
    /// and config. Used by the draw path AND the mouse hit-test, so the
    /// painted panel and the clickable regions are computed from one source.
    /// The theme picker hides the panel that opened it, so the preview shows on
    /// the whole window and a click cannot reach a row it covers.
    fn settings_overlay_projection(
        &self,
        ws: &WindowState,
    ) -> Option<kettle_render::SettingsOverlay> {
        if ws.theme_picker_input.is_some() {
            return None;
        }
        let nav = ws.settings_nav.as_ref()?;
        let cats = crate::settings::categories(&self.gpu_choices);
        let cat = nav.category.min(cats.len().saturating_sub(1));
        let active = &cats[cat];
        let tr = &self.ui_text;
        let (label_cols, value_cols) = crate::settings::column_widths(&self.cfg, &cats, tr);
        let fld = nav.field.min(active.fields.len().saturating_sub(1));
        Some(kettle_render::SettingsOverlay {
            categories: cats.iter().map(|c| tr.text(c.name).to_string()).collect(),
            label_cols,
            value_cols,
            active_category: cat,
            rows: active
                .fields
                .iter()
                .enumerate()
                .map(|(i, f)| {
                    // An open inline text edit for this field shows its
                    // editable buffer + a caret instead of the stored value.
                    let editing = ws.settings_text_edit.as_ref().filter(|e| e.key == f.key);
                    let value = if let Some(e) = editing {
                        let mut input = settings_edit_display(&e.buf);
                        if let Some((preedit, _)) = &ws.ime_preedit {
                            input.push_str(preedit);
                        }
                        format!("{input}\u{258f}")
                    } else if i == fld && nav.capturing {
                        // Capture prompt on the focused keybind row.
                        tr.text(kettle_i18n::Text::SettingsPressChord).to_string()
                    } else {
                        crate::settings::read(&self.cfg, f, tr)
                    };
                    kettle_render::SettingsRow {
                        label: tr.text(f.label).to_string(),
                        value,
                        disabled: crate::settings::field_disabled(&self.cfg, f.key),
                    }
                })
                .collect(),
            focused_row: fld,
            title: tr.settings_heading(tr.text(active.name)),
            hints: settings_hints(tr, self.cfg.vim_menu_nav),
            footer_note: {
                let graphics = active.name == kettle_i18n::Text::SettingsCategoryGraphics;
                let active_gpu = graphics.then(|| {
                    self.gpu
                        .as_ref()
                        .map(|g| {
                            let i = g.adapter_info();
                            let backend = match i.backend {
                                "DX12" => "DirectX 12",
                                "GL" => "OpenGL",
                                backend => backend,
                            };
                            tr.settings_active_gpu(&i.name, gpu_kind_text(tr, i.kind), backend)
                        })
                        .unwrap_or_else(|| {
                            tr.text(kettle_i18n::Text::SettingsActiveGpuInitializing)
                                .to_string()
                        })
                });
                settings_footer_note(
                    tr,
                    active_gpu.as_deref(),
                    active.fields.get(fld).map(|f| f.key),
                    ws.settings_restart_pending,
                    self.language_change_pending(),
                    match active.fields.get(fld).map(|f| f.key) {
                        Some("agent-display-claude-code") => Some(claude_code_note(
                            self.agent_previews_live(),
                            crate::agent_plugin::refusal(),
                        )),
                        Some("agent-display-codex") => Some(codex_note(
                            self.agent_previews_live(),
                            crate::codex_shell::refusal(),
                        )),
                        _ => Some(self.agent_previews_note()),
                    },
                )
            },
        })
    }

    /// Handle a mouse interaction with the settings overlay. `dir` is
    /// the adjust direction for a field (left-click `+1`, right-click `-1`,
    /// wheel `±1`); a category-tab hit switches category. `is_click` (vs a wheel)
    /// makes a hit OUTSIDE the panel close settings and makes inert hits consume
    /// the event; a wheel outside/inert is left for the modal swallow so a stray
    /// scroll can't dismiss the panel. Returns `true` if the event was consumed.
    fn settings_mouse(&mut self, ws: &mut WindowState, dir: i32, is_click: bool) -> bool {
        if ws.settings_nav.is_none() {
            return false;
        }
        // A mouse interaction while the inline path prompt is open cancels it
        // (the typed value is discarded; re-open to edit again).
        if ws.settings_text_edit.is_some() {
            ws.settings_text_edit = None;
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
            return true;
        }
        let Some(set) = self.settings_overlay_projection(ws) else {
            return false;
        };
        let (cw, ch) = self.menu_cell(ws);
        let (sw, sh) = ws
            .renderer
            .as_ref()
            .map(|r| {
                let (w, h) = r.surface_size();
                (w as f32, h as f32)
            })
            .unwrap_or((800.0, 600.0));
        let (mx, my) = (ws.cursor.x as f32, ws.cursor.y as f32);
        let hit = kettle_render::settings_hit_test(&set, cw, ch, sw, sh, mx, my);
        match hit {
            kettle_render::SettingsHit::Outside => {
                if !is_click {
                    return false; // let a stray wheel fall through to the swallow
                }
                ws.settings_nav = None;
            }
            kettle_render::SettingsHit::Inert => {
                if !is_click {
                    return false;
                }
            }
            kettle_render::SettingsHit::Category(i) => {
                if let Some(nav) = ws.settings_nav.as_mut() {
                    let cats = crate::settings::categories(&self.gpu_choices);
                    nav.category = i.min(cats.len().saturating_sub(1));
                    // Clamp the focused field into the new category + cancel any
                    // in-progress keybind capture.
                    let fcount = cats[nav.category].fields.len().max(1);
                    nav.field = nav.field.min(fcount - 1);
                    nav.capturing = false;
                }
            }
            kettle_render::SettingsHit::Field(f) => {
                let cats = crate::settings::categories(&self.gpu_choices);
                let cat = ws
                    .settings_nav
                    .as_ref()
                    .map(|n| n.category.min(cats.len().saturating_sub(1)))
                    .unwrap_or(0);
                let fcount = cats[cat].fields.len();
                if f < fcount {
                    let key = cats[cat].fields[f].key;
                    // A dimmed/inapplicable row is a no-op (but consumes the click).
                    if !crate::settings::field_disabled(&self.cfg, key) {
                        if let Some(nav) = ws.settings_nav.as_mut() {
                            nav.field = f;
                            nav.capturing = false;
                        }
                        // Keybind + text rows ACTIVATE on click (dir 0 — capture /
                        // open prompt); a wheel just focuses them. A click on the
                        // Theme row opens the theme picker, and a wheel steps it.
                        // Other value rows cycle.
                        let field = &cats[cat].fields[f];
                        let activate =
                            crate::settings::is_keybind(field) || crate::settings::is_text(field);
                        if activate {
                            if is_click {
                                self.settings_adjust(ws, &cats, cat, f, 0);
                            }
                        } else if is_click && crate::settings::opens_theme_picker(field) {
                            self.settings_adjust(ws, &cats, cat, f, 0);
                        } else {
                            self.settings_adjust(ws, &cats, cat, f, dir);
                        }
                    }
                }
            }
        }
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        true
    }

    /// Per-row shortcut hints for a menu, from the
    /// LIVE keybind map (a user rebind shows their actual chord). `Item` /
    /// `DynamicItem` rows look up their own Action; the Nth `NewTabShell`
    /// row maps to `Action::NewTabShell(N)` (the Ctrl+Shift+N family).
    /// Everything else gets no hint. Empty string = none.
    fn menu_item_hints(&self, items: &[ContextMenuItem]) -> Vec<String> {
        let mut shell_ordinal: u8 = 0;
        items
            .iter()
            .map(|it| match it {
                ContextMenuItem::Item { action, .. }
                | ContextMenuItem::DynamicItem { action, .. } => {
                    kettle_config::keybinds::hint_label(&self.cfg.keybinds, action)
                        .unwrap_or_default()
                }
                ContextMenuItem::NewTabShell { .. } => {
                    let h = if shell_ordinal < 9 {
                        kettle_config::keybinds::hint_label(
                            &self.cfg.keybinds,
                            &Action::NewTabShell(shell_ordinal),
                        )
                        .unwrap_or_default()
                    } else {
                        String::new()
                    };
                    shell_ordinal = shell_ordinal.saturating_add(1);
                    h
                }
                _ => String::new(),
            })
            .collect()
    }

    /// The new-tab `▾` dropdown's rows — the detected
    /// shells, then Windows Terminal's bottom section (Settings / Command
    /// palette / About) behind a separator. Pure over the shell list so the
    /// menu shape is unit-testable.
    fn new_tab_menu_items(
        shells: &[kettle_core::term::ShellChoice],
        tr: &kettle_i18n::Translator,
    ) -> Vec<ContextMenuItem> {
        use kettle_i18n::Text as T;
        let mut items: Vec<ContextMenuItem> = shells
            .iter()
            .cloned()
            .map(|(label, argv)| ContextMenuItem::NewTabShell { label, argv })
            .collect();
        items.push(ContextMenuItem::Separator);
        items.push(ContextMenuItem::Item {
            label: tr.text(T::MenuSettings),
            action: Action::OpenSettings,
            enabled: true,
        });
        items.push(ContextMenuItem::Item {
            label: tr.text(T::MenuCommandPalette),
            action: Action::CommandPalette,
            enabled: true,
        });
        items.push(ContextMenuItem::Item {
            label: tr.text(T::MenuAbout),
            action: Action::About,
            enabled: true,
        });
        items
    }

    /// The About panel — version + git hash, update
    /// status, and link rows, reusing the context-menu machinery (Info rows
    /// render dimmed and are not clickable; UrlItem rows copy/open).
    fn open_about_panel(&mut self, ws: &mut WindowState) {
        self.close_all_modals(ws);
        use kettle_i18n::Text as T;
        let tr = self.ui_text;
        let v = &self.version_line;
        let mut items = vec![
            ContextMenuItem::Info {
                label: format!("kettle {v}"),
            },
            ContextMenuItem::Info {
                label: about_update_status_label(
                    self.update_available.as_ref().map(|(tag, _)| tag.as_str()),
                    &tr,
                ),
            },
            ContextMenuItem::Separator,
            ContextMenuItem::UrlItem {
                label: tr.text(T::AboutCopyVersion),
                url: format!("kettle {v}"),
                how: UrlHow::Copy,
                pane: None,
            },
            ContextMenuItem::UrlItem {
                label: tr.text(T::AboutOpenGithub),
                url: "https://github.com/Reddimus/kettle".to_string(),
                how: UrlHow::Open,
                pane: None,
            },
        ];
        if let Some((_, url)) = &self.update_available {
            items.push(ContextMenuItem::UrlItem {
                label: tr.text(T::AboutOpenRelease),
                url: url.clone(),
                how: UrlHow::Open,
                pane: None,
            });
        }
        let (sw, sh) = ws
            .renderer
            .as_ref()
            .map(|r| {
                let (w, h) = r.surface_size();
                (w as f32, h as f32)
            })
            .unwrap_or((800.0, 600.0));
        self.show_context_menu(ws, items, sw * 0.5 - 140.0, sh * 0.4);
    }

    /// Open the new-tab `▾` dropdown at
    /// `(px, py)` — detected shells (process-cached in kettle-core, prewarmed
    /// at startup) plus the Settings / Command palette / About bottom rows.
    fn open_new_tab_menu(&mut self, ws: &mut WindowState, px: f32, py: f32) {
        self.close_all_modals(ws);
        let shells = kettle_core::term::detect_shells();
        let items = Self::new_tab_menu_items(&shells, &self.ui_text);
        self.show_context_menu(ws, items, px, py);
    }

    /// Open a new tab running `argv`, inheriting the focused tab's
    /// current working directory. Shared by the new-tab `▾` dropdown's mouse +
    /// keyboard dispatch. Mirrors the `Action::NewTab` handler's pattern: log
    /// on failure, fire the `TabAdd` plugin event only when a tab was
    /// actually created.
    fn open_tab_with_argv(&mut self, ws: &mut WindowState, argv: &[String]) {
        let area = self.area(ws);
        let (cols, rows) = self.grid_of(ws, area);
        let geometry = self.pty_geometry_for_grid(ws, cols, rows);
        let waker = self.waker();
        let cwd = ws
            .mux
            .focused()
            .and_then(|p| p.term.current_dir_or_native());
        // Route through new_tab_with_launch so a WSL ▾-dropdown
        // entry's Linux cwd is carried via `wsl --cd` instead of being dropped
        // (a Windows spawn can't `cd` into a Linux path, so it fell back home).
        match ws
            .mux
            .new_tab_with_launch_geometry(&self.cfg, geometry, waker, argv.to_vec(), cwd)
        {
            Ok(()) => self.fire_tab_add_event(ws),
            Err(e) => log::warn!("could not open shell tab ({argv:?}): {e}"),
        }
    }

    /// Move the context-menu highlight by `delta` (±1), skipping
    /// `Separator` rows and disabled `Item` rows. Wraps at the ends so
    /// `↑` on the first row jumps to the last enabled row and vice
    /// versa (Chrome / Firefox menu convention). The wrap+skip math lives
    /// in the pure `next_context_menu_highlight`, so it is unit-testable
    /// without App or cursor state.
    fn step_context_menu_highlight(&mut self, ws: &mut WindowState, delta: isize) {
        let next = ws
            .context_menu
            .as_ref()
            .map(|m| next_context_menu_highlight(&m.items, m.highlight, delta));
        if let Some(next) = next {
            self.set_context_menu_highlight(ws, next);
        }
    }

    /// Move the context-menu highlight to `next` and sync `scroll_offset` so
    /// it stays visible. `step_context_menu_highlight` and the vim-menu-nav
    /// jumps (`g`/`G`, `Ctrl+d`/`Ctrl+u`) share this scroll-window math.
    fn set_context_menu_highlight(&mut self, ws: &mut WindowState, next: usize) {
        let Some(((_, _), (_, panel_h))) = self.context_menu_geometry(ws) else {
            return;
        };
        let (_, ch) = self.menu_cell(ws);
        let row_h = ch + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        let Some(menu) = ws.context_menu.as_mut() else {
            return;
        };
        menu.highlight = next;
        menu.scroll_offset = context_menu_scroll_for_highlight(
            &menu.items,
            menu.scroll_offset,
            next,
            panel_h,
            row_h,
            sep_h,
        );
        ws.reuse_pane_snapshots_once = true;
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Scroll the context-menu by `delta` rows (positive
    /// = down). Clamped so we can't scroll past the last row that
    /// would still fill the visible window.
    fn scroll_context_menu(&mut self, ws: &mut WindowState, delta: isize) {
        let Some(((_, _), (_, panel_h))) = self.context_menu_geometry(ws) else {
            return;
        };
        let (_, ch) = self.menu_cell(ws);
        let row_h = ch + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        let Some(menu) = ws.context_menu.as_mut() else {
            return;
        };
        let new_off = (menu.scroll_offset as isize + delta).max(0) as usize;
        // Clamp: never scroll past the point where the last visible
        // row is the final item.
        let max_off = context_menu_max_scroll_offset(&menu.items, panel_h, row_h, sep_h);
        let clamped = new_off.min(max_off);
        if clamped != menu.scroll_offset {
            menu.scroll_offset = clamped;
            ws.reuse_pane_snapshots_once = true;
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
    }

    /// Return the row index under the cursor when the context menu
    /// is open, `None` if the cursor is outside the panel OR landed
    /// on a separator. Thin wrapper around the pure `find_menu_row_y`
    /// helper so the row-walk is unit-testable without standing up an
    /// App. Used by `update_menu_highlight_from_cursor` on every
    /// `CursorMoved` so the highlight tracks the pointer the way every
    /// desktop menu does (GTK / macOS NSMenu / Windows).
    fn menu_row_at_cursor(&self, ws: &WindowState) -> Option<usize> {
        let menu = ws.context_menu.as_ref()?;
        let ((ax, ay), (panel_w, panel_h)) = self.context_menu_geometry(ws)?;
        let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
        if px < ax || px >= ax + panel_w || py < ay || py >= ay + panel_h {
            return None;
        }
        let (_, ch) = self.menu_cell(ws);
        let row_h = ch + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        // Row-walk starts at scroll_offset; only the
        // visible slice is hit-tested. Off-by-one is handled by
        // find_menu_row_y's half-open interval [y, y+h).
        let start = menu.scroll_offset.min(menu.items.len());
        let kinds = menu.items[start..]
            .iter()
            .map(|it| matches!(it, ContextMenuItem::Separator));
        find_menu_row_y(py, ay, panel_h, row_h, sep_h, kinds).map(|i| i + start)
    }

    /// Set `menu.highlight` to whichever row the cursor is
    /// over right now; no-op when the cursor is outside the panel or
    /// on a separator. Called from `CursorMoved`. Requests a redraw
    /// only when the highlight actually changed so we don't churn the
    /// GPU on every sub-pixel motion event.
    fn update_menu_highlight_from_cursor(&mut self, ws: &mut WindowState) {
        let Some(idx) = self.menu_row_at_cursor(ws) else {
            return;
        };
        let Some(menu) = ws.context_menu.as_mut() else {
            return;
        };
        if menu.highlight == idx {
            return;
        }
        menu.highlight = idx;
        ws.reuse_pane_snapshots_once = true;
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Dispatch one resolved context-menu selection. The single sink for
    /// mouse clicks, keyboard Enter / Space, and mnemonic / typeahead
    /// activation so all three behave identically.
    ///
    /// Every *leaf* click closes the menu first, then acts. Only
    /// `DrillIntoSubmenu` keeps the menu open — it replaces the visible
    /// level with the submenu's items (parent pushed onto `drill_stack`).
    ///
    /// Callers must not clear `ws.context_menu` before dispatching. The
    /// `DrillIntoSubmenu` arm needs `ws.context_menu.as_mut()`, so an early
    /// clear would dismiss the whole menu instead of drilling in.
    fn dispatch_context_menu_click(
        &mut self,
        ws: &mut WindowState,
        click: ContextMenuClick,
        event_loop: &ActiveEventLoop,
    ) {
        self.sync_pane_focus_reports(ws);
        match click {
            // Keep the menu open: swap the visible level for the submenu.
            ContextMenuClick::DrillIntoSubmenu(idx) => {
                if let Some(menu) = ws.context_menu.as_mut() {
                    let nested_items = match menu.items.get(idx) {
                        Some(ContextMenuItem::Submenu { items, .. }) => items.clone(),
                        _ => Vec::new(),
                    };
                    if !nested_items.is_empty() {
                        let parent = std::mem::replace(&mut menu.items, nested_items);
                        menu.drill_stack.push(parent);
                        // Each level keeps its own scroll view.
                        menu.scroll_stack.push(menu.scroll_offset);
                        menu.scroll_offset = 0;
                        // Drilling resets any in-progress typeahead so a
                        // half-typed parent prefix doesn't bleed into the
                        // child level.
                        menu.typeahead_buf.clear();
                        menu.typeahead_until = None;
                        menu.highlight = menu
                            .items
                            .iter()
                            .position(item_is_dispatchable)
                            .unwrap_or(0);
                    }
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            ContextMenuClick::Action(action) => {
                ws.context_menu = None;
                self.handle_action(ws, action, event_loop);
            }
            ContextMenuClick::Media { target, action } => {
                ws.context_menu = None;
                self.act_on_media(ws, target, action);
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            ContextMenuClick::LuaMenuItem(idx) => {
                ws.context_menu = None;
                // Invoke the Lua callback + drain any
                // LuaCommands it queued through the canonical helper.
                if let Some(eng) = &self.lua_engine {
                    eng.invoke_menu_item(idx);
                }
                self.drain_lua_hook_commands(ws, "lua menu-item");
            }
            ContextMenuClick::ConfigCommand(command) => {
                ws.context_menu = None;
                // Terminator parity: write `CMD\n` to the PTY.
                // Acts as the user — a read-only pane drops it.
                if let Some(pane_id) = ws.mux.active_focus()
                    && let Some(p) = ws.mux.panes.get(&pane_id)
                {
                    let mut bytes = command.into_bytes();
                    bytes.push(b'\n');
                    let result = p.feed_input(&bytes);
                    self.report_input_result(result);
                    Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
                }
            }
            ContextMenuClick::MoveTabToWindow { window, panes } => {
                ws.context_menu = None;
                self.move_tab_to_window(ws, window, &panes);
            }
            ContextMenuClick::SetProfile(name) => {
                ws.context_menu = None;
                if let Some(p) = kettle_config::Config::path_for_profile(&name) {
                    self.config_path = Some(p);
                    self.config_trust = ConfigTrust::VerifyDirectory;
                    self.reload_config(ws);
                }
            }
            ContextMenuClick::NewTabWithArgv(argv) => {
                ws.context_menu = None;
                self.open_tab_with_argv(ws, &argv);
            }
            // Terminator parity: the URL-aware leading rows.
            // Open routes through the `open_url` chain (Lua URL
            // handlers → custom_url_handler → system open, with the
            // `is_safe_url` guard); Copy puts the address on the clipboard.
            ContextMenuClick::Url { url, how, pane } => {
                ws.context_menu = None;
                match how {
                    UrlHow::Copy => {
                        if let Some(cb) = &mut self.clipboard
                            && let Err(e) = cb.set_text(url)
                        {
                            log::warn!("clipboard set_text failed (link address copy): {e}");
                        }
                    }
                    UrlHow::Open => self.open_pane_link(ws, pane, &url),
                    UrlHow::Preview => {
                        if let Some(pane) = pane {
                            self.preview_pane_link(ws, pane, &url);
                        }
                    }
                }
            }
        }
    }

    fn context_menu_click_action(&self, ws: &WindowState, bcode: u8) -> Option<ContextMenuClick> {
        if bcode != 0 {
            return None;
        }
        // Hover and click must resolve through the same clipped-row geometry.
        // A second row walk here would let the blank partial strip below the
        // final fully drawn row dispatch an invisible item.
        let idx = self.menu_row_at_cursor(ws)?;
        let menu = ws.context_menu.as_ref()?;
        // Shared mapper — the same row-to-click table the keyboard Enter /
        // Space and mnemonic paths use, so mouse and keyboard dispatch cannot
        // diverge.
        menu.items
            .get(idx)
            .and_then(|item| item_to_click(item, idx))
    }

    /// `(items, anchor, panel_w, panel_h)` snapshot for the click /
    /// hover hit-tests — returned in pixels so callers don't have to
    /// re-derive the layout. `None` when the menu isn't open.
    fn context_menu_geometry(&self, ws: &WindowState) -> Option<((f32, f32), (f32, f32))> {
        let menu = ws.context_menu.as_ref()?;
        let (cw, ch) = self.menu_cell(ws);
        let row_h = ch + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        // Natural height: sum every row + separator.
        let natural_h: f32 = menu
            .items
            .iter()
            .map(|it| match it {
                ContextMenuItem::Separator => sep_h,
                _ => row_h,
            })
            .sum();
        // Terminator menu UX: clamp the panel height to the surface so a
        // ~512-entry Theme submenu can't grow off-screen. Reserve 80px of
        // vertical breathing room (40px top + 40px bottom) so the menu
        // doesn't bump into the window edge.
        let (surface_w, surface_h) = ws
            .renderer
            .as_ref()
            .map(|r| {
                let (w, h) = r.surface_size();
                (w as f32, h as f32)
            })
            .unwrap_or((800.0, 600.0));
        if !context_menu_surface_can_fit_row((surface_w, surface_h), (cw, ch)) {
            return None;
        }
        let max_h = (surface_h - kettle_render::menu::PANEL_BREATHING)
            .max(1.0)
            .min((surface_h - 8.0).max(1.0));
        let panel_h = natural_h.min(max_h);
        // Dropdown parity: include the right-aligned hint budget —
        // kept in lockstep with `show_context_menu` and the renderer's
        // `menu_row_chars`.
        let hints = self.menu_item_hints(&menu.items);
        let max_columns = menu
            .items
            .iter()
            .zip(hints.iter())
            .map(|(item, hint)| context_menu_item_columns(item, hint))
            .max()
            .unwrap_or(0) as f32;
        let natural_w = kettle_render::menu::panel_width(max_columns, cw);
        let (panel_w, panel_h) =
            clamp_context_menu_panel((natural_w, panel_h), (surface_w, surface_h));
        Some((menu.anchor, (panel_w, panel_h)))
    }

    /// Keep an already-open menu reachable when a resize or DPI transition
    /// makes its old bottom/right anchor invalid. The menu's natural geometry
    /// is recomputed from the live fractional font metrics before clamping, so
    /// drawing and hit-testing continue to share one anchor.
    fn reclamp_context_menu(&self, ws: &mut WindowState, surface: (f32, f32)) {
        let current_scale = ws
            .window
            .as_ref()
            .map(|window| window.scale_factor())
            .unwrap_or(1.0);
        let previous_scale = ws
            .context_menu
            .as_ref()
            .map(|menu| menu.anchor_scale)
            .unwrap_or(current_scale);
        let Some((anchor, panel)) = self.context_menu_geometry(ws) else {
            ws.context_menu = None;
            return;
        };
        let anchor = scale_context_menu_anchor(anchor, previous_scale, current_scale);
        let anchor = clamp_context_menu_anchor(anchor, panel, surface);
        let (_, cell_h) = self.menu_cell(ws);
        let row_h = cell_h + kettle_render::menu::ROW_PAD;
        let sep_h = kettle_render::menu::SEP_H;
        if let Some(menu) = ws.context_menu.as_mut() {
            menu.anchor = anchor;
            menu.anchor_scale = current_scale;
            menu.scroll_offset = context_menu_scroll_for_highlight(
                &menu.items,
                menu.scroll_offset,
                menu.highlight,
                panel.1,
                row_h,
                sep_h,
            );
        }
    }

    /// Build the renderer-side `ContextMenu` slice from the App-side
    /// state. Splits the labels (owned `String`) from the dispatch
    /// actions so the renderer stays Action-agnostic.
    fn context_menu_overlay(&self, ws: &WindowState) -> Option<ContextMenu> {
        let menu = ws.context_menu.as_ref()?;
        // Dropdown parity: per-row shortcut hints from the LIVE keybind
        // map (computed per frame; the map only changes on reload).
        let hints = self.menu_item_hints(&menu.items);
        let mut rows: Vec<ContextMenuRow> = menu
            .items
            .iter()
            .zip(hints)
            .map(|(it, hint)| match it {
                ContextMenuItem::Item { label, enabled, .. } => ContextMenuRow {
                    label: (*label).to_string(),
                    separator: false,
                    enabled: *enabled,
                    hint,
                },
                ContextMenuItem::DynamicItem { label, enabled, .. } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: *enabled,
                    hint,
                },
                ContextMenuItem::Separator => ContextMenuRow {
                    label: String::new(),
                    separator: true,
                    enabled: false,
                    hint: String::new(),
                },
                ContextMenuItem::LuaItem { label, .. } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                ContextMenuItem::ConfigItem { label, .. } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                ContextMenuItem::Submenu { label, .. } => ContextMenuRow {
                    // Append "▸" to signal "this row opens a submenu".
                    label: format!("{label} ▸"),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                // ProfileChoice rows only live inside a Submenu, so they
                // reach menu.items (and this arm) after a drill-in swaps the
                // submenu's items in.
                ContextMenuItem::ProfileChoice { label, .. }
                | ContextMenuItem::WindowChoice { label, .. } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                // New-tab ▾ shell choice — a normal clickable row.
                ContextMenuItem::NewTabShell { label, .. } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: true,
                    hint,
                },
                // URL-aware leading rows ("Open Link" /
                // "Copy Link Address") — normal clickable rows.
                ContextMenuItem::UrlItem { label, .. } => ContextMenuRow {
                    label: (*label).to_string(),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                // A card's media rows — normal clickable rows.
                ContextMenuItem::Media { label, .. } => ContextMenuRow {
                    label: (*label).to_string(),
                    separator: false,
                    enabled: true,
                    hint: String::new(),
                },
                // Dropdown parity: Info renders as a dimmed
                // (disabled-style) static line.
                ContextMenuItem::Info { label } => ContextMenuRow {
                    label: label.clone(),
                    separator: false,
                    enabled: false,
                    hint: String::new(),
                },
            })
            .collect();
        // Terminator menu UX: pass through the scroll state + clamped panel
        // geometry the renderer needs to draw only the visible slice.
        let (panel_w_clamped, panel_h_clamped) = self
            .context_menu_geometry(ws)
            .map(|(_, panel)| panel)
            .unwrap_or((0.0, 0.0));
        let (cell_w, _) = self.menu_cell(ws);
        let max_row_columns = kettle_render::menu::panel_columns(panel_w_clamped, cell_w);
        for row in &mut rows {
            fit_context_menu_row(row, max_row_columns);
        }
        Some(ContextMenu {
            anchor: menu.anchor,
            rows,
            highlight: menu.highlight,
            scroll_offset: menu.scroll_offset,
            panel_w_clamped,
            panel_h_clamped,
        })
    }

    /// Force the next redraw to render the cursor visible. Shared by:
    /// - the focus-change path (`note_focus_change`)
    /// - `Action::Reset` so a "fresh start" cursor is visible
    /// - `CursorBlinkingChange` events (DEC ?12 program-driven toggle)
    /// - the four modal Escape handlers so closing the
    ///   search/palette/hints/SSH overlay reveals the cursor immediately
    ///   instead of waiting up to one blink interval.
    fn reset_blink_phase(&mut self, ws: &mut WindowState) {
        let now = std::time::Instant::now();
        ws.blink_on = true;
        ws.last_blink = now;
        ws.last_blink_activity = now;
        // The window server's blink was planned from the old activity time.
        // A frame ends it (see `redraw`), so it never outlives new activity.
        if ws.blink_layer.is_active()
            && let Some(window) = &ws.window
        {
            window.request_redraw();
        }
    }

    /// Bring the app's blink phase to where the window server's animation is.
    /// A writer since the hand-off (`reset_blink_phase`, a DEC mode 12
    /// change) moves `last_blink` off the anchor, and its phase wins.
    fn materialize_layer_blink(ws: &mut WindowState, now: std::time::Instant) {
        let Some((on, edge)) = ws.blink_layer.materialize(ws.blink_on, ws.last_blink, now) else {
            return;
        };
        ws.blink_on = on;
        ws.last_blink = edge;
    }

    /// The window's cursor layer, installed and given to the renderer at the
    /// first hand-off, so startup never pays for it. A failure keeps the GPU
    /// blink for this window and logs once.
    fn ensure_cursor_layer(ws: &mut WindowState) -> bool {
        if ws.cursor_layer.is_some() {
            return true;
        }
        // A window between renderers (recovery) tries again at a later edge.
        let (Some(window), Some(renderer)) = (ws.window.as_deref(), ws.renderer.as_mut()) else {
            return false;
        };
        let installed = crate::macos_cursor_layer::CursorLayer::install(window).and_then(|layer| {
            layer.attach(renderer)?;
            Ok(layer)
        });
        match installed {
            Ok(layer) => {
                ws.cursor_layer = Some(layer);
                true
            }
            Err(reason) => {
                if ws.blink_layer.fall_back(reason) {
                    log::info!(
                        target: CURSOR_BLINK_LOG,
                        "window {}: the cursor blinks on the GPU: {reason}",
                        ws.seq
                    );
                }
                false
            }
        }
    }

    /// A hand-off frame reached the screen: start the window server's blink
    /// over the patch it drew, or keep the GPU blink for this edge.
    fn start_layer_blink(
        &self,
        ws: &mut WindowState,
        patch: CursorPatchOutcome,
        window: Option<&winit::window::Window>,
    ) {
        ws.blink_layer.failed_handoff();
        // A failed patch present may leave old contents on the layer.
        // Keep them hidden until both the patch and the animation are ready.
        if let Some(layer) = &ws.cursor_layer {
            layer.hide();
        }
        let rect = match patch {
            CursorPatchOutcome::Presented(rect) => rect,
            CursorPatchOutcome::Ineligible(reason) => {
                log::debug!(
                    target: CURSOR_BLINK_LOG,
                    "window {}: cursor patch ineligible: {reason:?}",
                    ws.seq
                );
                return;
            }
            CursorPatchOutcome::Failed(reason) => {
                log::debug!(
                    target: CURSOR_BLINK_LOG,
                    "window {}: cursor patch failed: {}",
                    ws.seq,
                    reason.as_str()
                );
                if reason == CursorPatchFailure::Lost {
                    Self::retire_cursor_layer(ws);
                }
                return;
            }
        };
        let rect_px = [rect.x, rect.y, rect.width, rect.height];
        let Some(plan) = crate::cursor_blink::layer_plan(
            ws.blink_on,
            ws.last_blink,
            ws.last_blink_activity,
            std::time::Duration::from_millis(self.cfg.cursor_blink_interval),
            self.cfg.cursor_blink_timeout(),
        ) else {
            return;
        };
        let (Some(layer), Some(window)) = (&ws.cursor_layer, window) else {
            return;
        };
        match layer.show(
            rect_px,
            window.scale_factor(),
            &plan,
            std::time::Instant::now(),
        ) {
            Ok(()) => ws.blink_layer.started(plan, rect_px),
            Err(reason) => log::debug!(
                target: CURSOR_BLINK_LOG,
                "window {}: the cursor layer did not start: {reason}",
                ws.seq
            ),
        }
    }

    /// Hide the cursor layer without a frame: the window lost focus, was
    /// occluded, changed size or scale, or is rebuilding its renderer. The Metal
    /// layer beneath shows the off phase, which is right for each of these
    /// until the next frame draws the phase materialized here.
    fn hide_cursor_layer(ws: &mut WindowState) {
        if !ws.blink_layer.is_active() {
            return;
        }
        Self::materialize_layer_blink(ws, std::time::Instant::now());
        if let Some(layer) = &ws.cursor_layer {
            layer.hide();
        }
        ws.blink_layer.hidden();
        if ws.cursor_exit_log.enabled {
            ws.cursor_exit_log.hidden();
        }
    }

    /// Remove the cursor layer and the renderer's surface on it. A rebuilt
    /// surface adds its Metal layer above the old one, so the next hand-off
    /// installs a fresh cursor layer above that.
    fn retire_cursor_layer(ws: &mut WindowState) {
        Self::hide_cursor_layer(ws);
        let layer = ws.cursor_layer.take();
        if layer.is_some()
            && let Some(renderer) = ws.renderer.as_mut()
        {
            renderer.detach_cursor_layer();
        }
    }

    /// Send a broadcast from `ws`, and then to the panes in every OTHER window
    /// that the same scope selects.
    ///
    /// A named broadcast group is a set the user declared, and `group_all`
    /// already spans every window the way Terminator's does. Stopping at the
    /// focused window would reach only part of a cross-window group while the
    /// other window's panes still show the group in their titlebars.
    ///
    /// Scopes that are defined by something window-local (`Tab`, and kettle's
    /// own window-wide `All`) do not walk, so this costs a single enum test
    /// when it does not apply.
    fn broadcast_input(
        &mut self,
        ws: &mut WindowState,
        bytes: &[u8],
        scroll_to_bottom: bool,
        input_time: std::time::Instant,
    ) -> PaneInputResult {
        let receipt_pane = Self::media_paste_receipt_pane(ws);
        let local = ws
            .mux
            .broadcast_write_delivery(bytes, scroll_to_bottom, receipt_pane);
        Self::dismiss_media_paste_receipt_after_delivery(ws, local);
        stamp_accepted_input(&mut ws.last_typed, local, input_time);
        let mut result = local.result;
        if crate::mux::Mux::scope_crosses_windows(&ws.mux.broadcast) {
            let scope = ws.mux.broadcast.clone();
            for other in self.windows.values_mut() {
                let receipt_pane = Self::media_paste_receipt_pane(other);
                let delivery = other.mux.broadcast_write_foreign_delivery(
                    &scope,
                    bytes,
                    scroll_to_bottom,
                    receipt_pane,
                );
                Self::dismiss_media_paste_receipt_after_delivery(other, delivery);
                stamp_accepted_input(&mut other.last_typed, delivery, input_time);
                result = result.merge(delivery.result);
            }
        }
        result
    }

    fn populated_groups<'a>(&'a self, ws: Option<&'a WindowState>) -> HashSet<&'a str> {
        ws.into_iter()
            .chain(self.windows.values())
            .flat_map(|window| window.mux.panes.values())
            .filter_map(|pane| pane.group_name.as_deref())
            .collect()
    }

    fn hoover_groups(&mut self, ws: &mut WindowState) {
        if !any_group_scope_needs_hoover(std::iter::once(&*ws).chain(self.windows.values())) {
            return;
        }
        let populated = self.populated_groups(Some(ws));
        let reset_current =
            group_scope_is_globally_stale(ws.mux.autoclean_groups, &ws.mux.broadcast, &populated);
        let reset_windows: Vec<u64> = self
            .windows
            .iter()
            .filter_map(|(&seq, target)| {
                group_scope_is_globally_stale(
                    target.mux.autoclean_groups,
                    &target.mux.broadcast,
                    &populated,
                )
                .then_some(seq)
            })
            .collect();
        drop(populated);
        if reset_current {
            ws.mux.broadcast = BroadcastScope::Off;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        for seq in reset_windows {
            if let Some(target) = self.windows.get_mut(&seq) {
                target.mux.broadcast = BroadcastScope::Off;
                if let Some(window) = &target.window {
                    window.request_redraw();
                }
            }
        }
    }

    fn hoover_mapped_groups(&mut self) {
        if !any_group_scope_needs_hoover(self.windows.values()) {
            return;
        }
        let populated = self.populated_groups(None);
        let reset_windows: Vec<u64> = self
            .windows
            .iter()
            .filter_map(|(&seq, target)| {
                group_scope_is_globally_stale(
                    target.mux.autoclean_groups,
                    &target.mux.broadcast,
                    &populated,
                )
                .then_some(seq)
            })
            .collect();
        drop(populated);
        for seq in reset_windows {
            if let Some(target) = self.windows.get_mut(&seq) {
                target.mux.broadcast = BroadcastScope::Off;
                if let Some(window) = &target.window {
                    window.request_redraw();
                }
            }
        }
    }

    /// Write a `key = value` line to the user's active config file via the
    /// atomic `persist_config_toggle` helper. Resolves the path the same way
    /// `Action::EditConfig` does (`App::config_path`, then
    /// `Config::default_path`). Logs an I/O error so a transient FS issue
    /// doesn't kill the menu dispatch; the in-memory change still applies.
    /// Returns `true` iff the value was written to the config file. Callers
    /// of user-initiated changes (theme picks, Settings) notify the user on
    /// `false` so a change that's live this session but lost on restart isn't
    /// silent.
    fn persist_pref(&self, key: &str, value: &str) -> bool {
        let Some(path) = self
            .config_path
            .clone()
            .or_else(kettle_config::Config::default_path)
        else {
            log::warn!(
                "persist_pref: no config path resolved (set $XDG_CONFIG_HOME or pass --config)"
            );
            return false;
        };
        match kettle_config::persist_config_toggle(&path, key, value) {
            Ok(bak) => {
                log::info!(
                    "persist_pref: wrote {key} = {value} to {} (backup at {})",
                    path.display(),
                    bak.display()
                );
                true
            }
            Err(e) => {
                log::warn!(
                    "persist_pref: failed to write {key} = {value} to {}: {e}",
                    path.display()
                );
                false
            }
        }
    }

    fn persist_search_pref(&self, key: &str, value: &str) {
        if !self.persist_pref(key, value) {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleSearchNotSaved),
                self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
            );
        }
    }

    fn queue_window_resizes<'a>(windows: impl Iterator<Item = &'a mut WindowState>) {
        for ws in windows {
            ws.pending_resize = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
    }

    /// Act on the update banner: dismiss it (recording the tag so it
    /// won't re-nag) and, when `open` is true, open the release page first.
    /// Returns `false` when no banner is showing (the caller decides whether
    /// that's a no-op or worth a debug log). Shared by the banner mouse
    /// handler and the `OpenUpdate` / `DismissUpdate` keyboard
    /// actions so all three paths stay in lockstep.
    fn act_on_update_banner(&mut self, ws: &mut WindowState, open: bool) -> bool {
        let Some((tag, url)) = self.update_available.clone() else {
            return false;
        };
        if open {
            self.open_url(ws, &url, LinkSource::Kettle);
        }
        crate::update_check::record_dismissed(&tag);
        self.update_available = None;
        Self::queue_window_resizes(std::iter::once(&mut *ws).chain(self.windows.values_mut()));
        true
    }

    fn handle_action(
        &mut self,
        ws: &mut WindowState,
        action: Action,
        event_loop: &ActiveEventLoop,
    ) {
        self.sync_pane_focus_reports(ws);
        let area = self.area(ws);
        let (cols, rows) = self.grid_of(ws, area);
        let tab_geometry = self.pty_geometry_for_grid(ws, cols, rows);
        let horizontal_split_geometry = self.prospective_split_geometry(ws, Dir::Horizontal, false);
        let vertical_split_geometry = self.prospective_split_geometry(ws, Dir::Vertical, false);
        let waker = self.waker();
        // Snapshot the (tab, pane-leaf) the cursor lives in so we can detect
        // any focus change the action causes.
        let pre_focus = self.focus_key(ws);
        match action {
            Action::NewTab => {
                // Fire LuaEvent::TabAdd with the new active tab index (via
                // fire_tab_add_event) only when a tab was actually created, so
                // Lua never hears of a tab that doesn't exist. A PTY-spawn
                // failure is logged.
                match ws.mux.new_tab_geometry(&self.cfg, tab_geometry, waker) {
                    Ok(()) => self.fire_tab_add_event(ws),
                    Err(e) => log::warn!("could not open a new tab (shell spawn failed?): {e}"),
                }
            }
            Action::NewWindow => {
                // Open a real second window in this process, so tabs can move
                // live between windows and all windows share the GPU device. If
                // the window can't be created, fall back to a new tab (degraded
                // but useful).
                if let Err(_unopened) =
                    self.open_window(event_loop, WindowOpen::Fresh { cwd: None }, None, None)
                {
                    match ws.mux.new_tab_geometry(&self.cfg, tab_geometry, waker) {
                        Ok(()) => self.fire_tab_add_event(ws),
                        Err(e) => {
                            log::warn!("new-window fallback: could not open a tab: {e}")
                        }
                    }
                }
            }
            Action::SplitRight | Action::SplitLeft => {
                // Split Left puts the new pane first, as Ghostty's
                // `new_split:left` does.
                let new_first = action == Action::SplitLeft;
                let geometry = if new_first {
                    self.prospective_split_geometry(ws, Dir::Horizontal, true)
                } else {
                    horizontal_split_geometry
                };
                // If the focused pane has entered a shell it launched
                // (e.g. typed `wsl` in pwsh), clone THAT shell + its dir; else
                // clone the pane's own launch command.
                let detected = self.focused_foreground_shell(ws);
                let res = match detected {
                    Some(s) => ws.mux.split_with_geometry(
                        Dir::Horizontal,
                        new_first,
                        &self.cfg,
                        geometry,
                        waker,
                        s.argv,
                        s.cwd,
                    ),
                    None => ws.mux.split_geometry(
                        Dir::Horizontal,
                        new_first,
                        &self.cfg,
                        geometry,
                        waker,
                    ),
                };
                if let Err(e) = res {
                    report_split_failure(
                        if new_first { "left" } else { "right" },
                        &e,
                        &self.ui_text,
                    );
                }
            }
            Action::SplitDown | Action::SplitUp | Action::SplitAuto => {
                // `split_auto` cuts along the pane's LONGER axis, the way
                // Terminator does; `split_down` and `split_up` are always
                // vertical, and Split Up puts the new pane first.
                let dir = if action == Action::SplitAuto {
                    self.auto_split_dir(ws)
                } else {
                    Dir::Vertical
                };
                let new_first = action == Action::SplitUp;
                let geometry = if new_first {
                    self.prospective_split_geometry(ws, Dir::Vertical, true)
                } else if dir == Dir::Horizontal {
                    horizontal_split_geometry
                } else {
                    vertical_split_geometry
                };
                let detected = self.focused_foreground_shell(ws);
                let res = match detected {
                    Some(s) => ws.mux.split_with_geometry(
                        dir, new_first, &self.cfg, geometry, waker, s.argv, s.cwd,
                    ),
                    None => ws
                        .mux
                        .split_geometry(dir, new_first, &self.cfg, geometry, waker),
                };
                if let Err(e) = res {
                    report_split_failure(if new_first { "up" } else { "down" }, &e, &self.ui_text);
                }
            }
            Action::ClosePane => {
                // Prompt per pane when ask_before_closing = Always.
                // MultipleTerminals doesn't prompt (single pane); see
                // `should_prompt` for the matrix. Ghostty
                // `confirm-close-surface` parity: a pane idle at an
                // integrated-shell prompt has no work to lose, so skip the
                // confirm. Plain shells (no OSC 133 marks) never report idle.
                let busy = usize::from(
                    ws.mux
                        .focused()
                        .map(|p| !p.term.shell_idle())
                        .unwrap_or(true),
                );
                // Name the pane now — by the time the prompt is answered,
                // "focused" may mean a different one.
                if let Some(target) = ws.mux.active_focus()
                    && self.confirm_close(
                        ws,
                        self.ui_text
                            .text(kettle_i18n::Text::ConfirmClosePane)
                            .to_string(),
                        1,
                        busy,
                        ConfirmAction::ClosePane(target),
                    )
                {
                    return;
                }
                // Capture the focused pane id BEFORE the close —
                // afterward active_focus() returns the promoted sibling.
                let closing_pane = ws.mux.active_focus();
                if let Some(id) = closing_pane {
                    self.fire_pane_close_event(ws, id);
                }
                let was_last = ws.mux.close_focused();
                if was_last {
                    self.request_window_close(ws.seq);
                } else {
                    // Redraw and re-emit the focus event now. The split tree
                    // has collapsed (sibling promoted to root), but the
                    // renderer cache and the PaneFocus event's last-fired pane
                    // id stay stale until something schedules a frame. On
                    // Windows under wgpu DX12 this stale state was reported as
                    // a crash, most likely the tab-bar render path indexing a
                    // removed pane and panicking on its dropped
                    // Arc<Mutex<Terminal>> lock.
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    // Fire PaneFocus for the promoted sibling so plugins that
                    // observe focus drop stale per-pane state.
                    self.poll_focus_event(ws);
                }
            }
            Action::CloseTab => {
                // Close the
                // active tab via the modal when ask_before_closing
                // says so. scope_count = leaves in the active tab
                // (panes_in_tab below).
                let (panes_in_tab, busy_in_tab) = tab_close_scope(ws, ws.mux.active);
                if self.confirm_close(
                    ws,
                    self.ui_text.confirm_close_tab(panes_in_tab as u64),
                    panes_in_tab,
                    busy_in_tab,
                    ConfirmAction::CloseTabHolding(ws.mux.tab_anchor_panes(ws.mux.active)),
                ) {
                    return;
                }
                // Capture the active index BEFORE close
                // so the LuaEvent::TabClose payload is meaningful
                // (after close, ws.mux.active points at a
                // different tab), via the shared fire_tab_close_event
                // helper.
                let closing_idx = ws.mux.active;
                if ws.mux.close_tab() {
                    self.request_window_close(ws.seq);
                }
                self.fire_tab_close_event(ws, closing_idx);
            }
            Action::CloseWindow => {
                // Phase 5 of the confirm-dialog design:
                // intercept via the `should_prompt` helper.
                // When ask-before-closing fires, open the modal
                // with on_confirm=CloseWindow; the modal's Confirm
                // dispatch (in the key handler) re-runs the close
                // path below.
                let (scope, busy) = window_close_scope(ws);
                if self.confirm_close(
                    ws,
                    self.ui_text.confirm_close_window(scope as u64),
                    scope,
                    busy,
                    ConfirmAction::CloseWindow {
                        drop_panes: DropPanes::Yes,
                    },
                ) {
                    return;
                }
                // Unlike `CloseTab`, drop *every* tab and pane in this window,
                // not just the focused tab.
                self.close_window_now(ws, DropPanes::Yes);
            }
            Action::NextTab => ws.mux.next_tab(),
            Action::PrevTab => ws.mux.prev_tab(),
            Action::FocusNext => ws.mux.focus_cycle(area, true),
            Action::FocusPrev => ws.mux.focus_cycle(area, false),
            Action::FocusLeft => ws.mux.focus_dir(area, -1, 0),
            Action::FocusRight => ws.mux.focus_dir(area, 1, 0),
            // Terminator rearranges panes by dragging a terminal onto another.
            // This is the same rearrangement addressed by direction: take the
            // focused pane and put it beside whichever pane focus would have
            // moved to, on that side. The neighbour search is the one
            // `goto_split` uses, so the pane lands where you were looking.
            Action::MovePaneLeft
            | Action::MovePaneRight
            | Action::MovePaneUp
            | Action::MovePaneDown => {
                let (dx, dy, dir, before) = match action {
                    Action::MovePaneLeft => (-1, 0, Dir::Horizontal, true),
                    Action::MovePaneRight => (1, 0, Dir::Horizontal, false),
                    Action::MovePaneUp => (0, -1, Dir::Vertical, true),
                    _ => (0, 1, Dir::Vertical, false),
                };
                if let Some(target) = ws.mux.pane_in_direction(area, dx, dy)
                    && let Some(moving) = ws.mux.active_focus()
                    && ws.mux.move_pane_beside(moving, target, dir, before)
                {
                    // The rearrangement changes every pane's rect, so the PTYs
                    // have to hear about it, and the layout is worth keeping.
                    self.resize_all(ws);
                    self.save_session(ws);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
            Action::FocusUp => ws.mux.focus_dir(area, 0, -1),
            Action::FocusDown => ws.mux.focus_dir(area, 0, 1),
            Action::ResizeLeft => ws.mux.resize_focus(Dir::Horizontal, -0.03),
            Action::ResizeRight => ws.mux.resize_focus(Dir::Horizontal, 0.03),
            Action::ResizeUp => ws.mux.resize_focus(Dir::Vertical, -0.03),
            Action::ResizeDown => ws.mux.resize_focus(Dir::Vertical, 0.03),
            Action::Copy => {
                // Terminator parity (terminatorlib/config.py
                // `smart_copy` + terminal.py:real_copy_clipboard):
                //   smart_copy = true  (default) → if no selection, skip
                //     the clipboard write so the existing clipboard
                //     content is preserved. Lets a user Ctrl+Shift+C
                //     without losing a previous copy when they forgot
                //     to highlight first.
                //   smart_copy = false → always trigger the copy. If
                //     there's no selection, write empty — this CLOBBERS
                //     the clipboard. Deliberate UX choice for users who
                //     want Ctrl+Shift+C to consistently mean "the
                //     clipboard now reflects the current selection
                //     (empty or not)" without smart heuristics.
                let selection_text = ws.mux.focused().and_then(|p| {
                    p.term
                        .term
                        .lock()
                        .ok()
                        .and_then(|t| t.selection_to_string())
                });
                let payload = match copy_clipboard_decision(selection_text, self.cfg.smart_copy) {
                    Ok(payload) => payload,
                    Err(error) => {
                        log::warn!("copy: could not prepare selection text: {error}");
                        return;
                    }
                };
                let mut copied = false;
                if let Some(s) = payload
                    && let Some(cb) = &mut self.clipboard
                {
                    let had_selection = !s.is_empty();
                    match cb.set_text(s) {
                        Ok(()) => copied = had_selection,
                        Err(error) => log::warn!("clipboard set_text failed (copy): {error}"),
                    }
                }
                // Terminator parity (terminatorlib/config.py:91
                // `clear_select_on_copy`): if the config asked, drop the
                // selection so the user sees the copy "took". Default
                // false matches Terminator's default — the selection
                // stays so re-Copy still works.
                if copied && self.cfg.clear_select_on_copy {
                    self.clear_selection_on_input(ws);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
            Action::Paste => self.paste_clipboard(ws),
            // The font size is window-wide, so zooming all panes is the same
            // as zooming one.
            Action::IncreaseFontSize
            | Action::DecreaseFontSize
            | Action::ResetFontSize
            | Action::ZoomInAll
            | Action::ZoomOutAll
            | Action::ZoomNormalAll => {
                if let Some(r) = ws.renderer.as_mut() {
                    // Step the logical font size directly. Back-deriving it
                    // from `r.cell_h` (physical px) would double-apply the
                    // scale factor on HiDPI.
                    let new = match action {
                        Action::IncreaseFontSize | Action::ZoomInAll => r.font_size() + 1.0,
                        // `set_font_size` clamps to the renderer's 5..=72
                        // range; a floor of 6 here turned "decrease" at a
                        // configured 5 into an increase.
                        Action::DecreaseFontSize | Action::ZoomOutAll => r.font_size() - 1.0,
                        _ => self.cfg.font_size,
                    };
                    r.set_font_size(new);
                }
                // The user changed the font OUTSIDE a scaled-zoom
                // enter/exit, so the saved pre-zoom size is now stale — drop it
                // so a later zoom-out keeps this new chosen size instead of
                // reverting to the old one.
                ws.scaled_zoom_prev_font_size = None;
            }
            Action::StartSearch => {
                self.open_search(ws);
            }
            Action::ToggleBroadcastAll => {
                // Toggle: turn on the `broadcast-default` scope, or turn
                // broadcast off when that scope is already on. The explicit off
                // chord (`ToggleBroadcastOff`) still works.
                let on = broadcast_scope_for_default(self.cfg.broadcast_default);
                ws.mux.broadcast = if ws.mux.broadcast == on {
                    crate::mux::BroadcastScope::Off
                } else {
                    on
                };
            }
            Action::ToggleBroadcastOff => {
                ws.mux.broadcast = crate::mux::BroadcastScope::Off;
            }
            Action::ToggleBroadcastGroup => {
                // Toggle broadcast scope between Off and
                // Group(focused_pane.group_name). If focused
                // pane has no group, log + no-op.
                let focused_group = ws.mux.focused().and_then(|p| p.group_name.clone());
                let Some(group) = focused_group else {
                    log::info!(
                        "toggle-broadcast-group: focused pane has no group_name; \
                         use Action::CreateGroup or Action::GroupTab first"
                    );
                    return;
                };
                ws.mux.broadcast = match &ws.mux.broadcast {
                    crate::mux::BroadcastScope::Group(name) if name == &group => {
                        crate::mux::BroadcastScope::Off
                    }
                    _ => crate::mux::BroadcastScope::Group(group),
                };
            }
            Action::ToggleBroadcastWindow => {
                // Toggle window-wide broadcast on/off. Unlike
                // ToggleBroadcastAll, whose scope follows `broadcast-default`
                // (per-tab by default), this always targets every pane in every
                // tab.
                ws.mux.broadcast = match &ws.mux.broadcast {
                    crate::mux::BroadcastScope::All => crate::mux::BroadcastScope::Off,
                    _ => crate::mux::BroadcastScope::All,
                };
            }
            Action::ToggleZoom => {
                // A tab with one pane has nothing to expand: entering zoom
                // there would only leave a hidden flag that the first split
                // then silently cleared. A zoomed tab can always leave zoom.
                // ScaledZoom keeps its font step on a single pane.
                if ws.mux.is_zoomed() || ws.mux.active_pane_count() > 1 {
                    // Route through the helper ScaledZoom uses, so un-zooming
                    // via the plain toggle still restores or clears a pending
                    // scaled-zoom font baseline. See `toggle_zoom_with_scale`.
                    self.toggle_zoom_with_scale(ws, None);
                }
            }
            // Ghostty `equalize_splits` parity: rebalance the active tab's
            // split tree to equal pane areas, then push the new geometry into
            // the PTYs.
            Action::EqualizeSplits => {
                if let Some(t) = ws.mux.tabs.get_mut(ws.mux.active) {
                    t.root.equalize();
                }
                self.resize_all(ws);
                self.save_session(ws);
            }
            // Ghostty's `text:` action, and what gives `⌘⌫` something to mean.
            // Unlike the five other text-writing actions this goes through
            // `write_terminal_input` rather than `feed_input`: it stands in for
            // a keystroke, so it should clear the selection, scroll on
            // keystroke and reach every pane of a broadcast, exactly as typing
            // the same bytes would. That helper also invalidates the affected
            // pane's media-paste receipt, which every authored-input route owes.
            Action::SendText(text) => {
                self.write_terminal_input(ws, text.as_bytes());
            }
            Action::SendNewline => {
                if let Some(pane_id) = ws.mux.active_focus()
                    && let Some(p) = ws.mux.panes.get(&pane_id)
                {
                    // Terminator parity (`key_send_newline`): write a literal
                    // `\n` for shell line-editors that consume Enter normally
                    // but expect an explicit `\n` for line continuation
                    // (multi-line readline prompts). Typed-input semantics, so
                    // read-only drops it.
                    let result = p.feed_input(b"\n");
                    self.report_input_result(result);
                    Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
                }
            }
            // Terminator parity (`key_preferences` /
            // `key_preferences_keybindings`). Terminator opens a GUI
            // Preferences dialog; kettle's preferences live in its config file,
            // so the preferences keybind opens that file with the OS's
            // registered handler. If no config file is loaded (kettle started
            // with `--config` pointing at a missing path, or no profile
            // resolved), it falls back to `Config::default_path()`.
            Action::EditConfig => {
                let path = self
                    .config_path
                    .clone()
                    .or_else(kettle_config::Config::default_path);
                if let Some(path) = path {
                    if let Err(e) = open::that_detached(&path) {
                        log::warn!("Action::EditConfig: failed to open {}: {e}", path.display());
                        fire_notify(
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyTitleConfigNotOpened),
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyBodyConfigOpenFailed),
                        );
                    }
                } else {
                    log::warn!(
                        "Action::EditConfig: no config path resolved \
                         (set $XDG_CONFIG_HOME or pass --config)"
                    );
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleConfigNotOpened),
                        self.ui_text.text(kettle_i18n::Text::NotifyBodyConfigNoPath),
                    );
                }
            }
            // Preferences submenu toggles. Each dispatch updates `self.cfg` so
            // the change applies now, and writes `key = value` back to the
            // user's config file via the `persist_config_toggle` helper (atomic
            // temp+rename, comment-preserving, with a first-write backup at
            // `<config>.bak`). Re-opening the menu picks up the new state.
            Action::SetScrollbarAlways => {
                self.cfg.scrollbar = kettle_config::ScrollbarMode::Always;
                self.persist_pref("scrollbar", "always");
            }
            Action::SetScrollbarAuto => {
                self.cfg.scrollbar = kettle_config::ScrollbarMode::Auto;
                self.persist_pref("scrollbar", "auto");
            }
            Action::SetScrollbarNever => {
                self.cfg.scrollbar = kettle_config::ScrollbarMode::Never;
                self.persist_pref("scrollbar", "never");
            }
            // Close-confirmation policy. The confirm bar deliberately does NOT
            // carry a "don't ask again" answer: it decides the close in front
            // of you, while standing policy lives here, where the selected
            // radio IS the feedback and picking another row is the undo.
            Action::SetAskBeforeClosingAlways => {
                self.cfg.ask_before_closing = kettle_config::AskBeforeClosing::Always;
                self.persist_pref("ask-before-closing", "always");
            }
            Action::SetAskBeforeClosingMultiple => {
                self.cfg.ask_before_closing = kettle_config::AskBeforeClosing::MultipleTerminals;
                self.persist_pref("ask-before-closing", "multiple-terminals");
            }
            Action::SetAskBeforeClosingNever => {
                self.cfg.ask_before_closing = kettle_config::AskBeforeClosing::Never;
                self.persist_pref("ask-before-closing", "never");
            }
            Action::ToggleCursorBlink => {
                self.cfg.cursor_blink = !self.cfg.cursor_blink;
                // Turning blink on from the menu after the idle timeout
                // must show it blinking, not rest steady until a keystroke.
                self.reset_blink_phase(ws);
                self.persist_pref(
                    "cursor-blink",
                    if self.cfg.cursor_blink {
                        "true"
                    } else {
                        "false"
                    },
                );
            }
            Action::ToggleCopyOnSelect => {
                self.cfg.copy_on_select = !self.cfg.copy_on_select;
                self.persist_pref(
                    "copy-on-select",
                    if self.cfg.copy_on_select {
                        "true"
                    } else {
                        "false"
                    },
                );
            }
            Action::SetBellOff => {
                self.cfg.bell = kettle_config::BellMode::Off;
                self.persist_pref("bell", "off");
            }
            Action::SetBellVisual => {
                self.cfg.bell = kettle_config::BellMode::Visual;
                self.persist_pref("bell", "visual");
            }
            Action::SetBellAttention => {
                self.cfg.bell = kettle_config::BellMode::Attention;
                self.persist_pref("bell", "attention");
            }
            Action::SetBellBoth => {
                self.cfg.bell = kettle_config::BellMode::Both;
                self.persist_pref("bell", "both");
            }
            Action::ToggleMouseHide => {
                self.cfg.mouse_hide_while_typing = !self.cfg.mouse_hide_while_typing;
                self.persist_pref(
                    "mouse-hide-while-typing",
                    if self.cfg.mouse_hide_while_typing {
                        "true"
                    } else {
                        "false"
                    },
                );
            }
            // Terminator parity (`key_help`). Terminator's F1 opens its HTML
            // manual via xdg-open; kettle opens its GitHub README through
            // `open::that_detached`, the cross-platform path URL clicks use.
            Action::ShowHelp => {
                let url = "https://github.com/Reddimus/kettle#readme";
                if let Err(e) = open::that_detached(url) {
                    log::warn!("Action::ShowHelp: failed to open {url}: {e}");
                }
            }
            // Terminator parity (`key_scaled_zoom`). Toggle pane zoom and scale
            // the font 1.5x so glyphs grow with the enlarged pane, then restore
            // the saved size on exit. `ToggleZoom` shares this save/restore via
            // `toggle_zoom_with_scale`, which reads the post-toggle zoom flag
            // and pairs save/restore through one `Option<f32>`, so mixing the
            // two actions keeps the state in step.
            Action::ScaledZoom => {
                self.toggle_zoom_with_scale(ws, Some(1.5));
            }
            Action::ToggleFullscreen => {
                if let Some(w) = &ws.window {
                    w.set_fullscreen(if w.fullscreen().is_some() {
                        None
                    } else {
                        Some(Fullscreen::Borderless(None))
                    });
                }
            }
            Action::ClearHistory => {
                // CSI 3 J (ED 3) clears scrollback only and keeps the visible
                // screen and grid state, unlike Reset (`\e c`, RIS), which
                // wipes everything. kitty / iTerm2 / WezTerm all expose this as
                // "Clear Scrollback" or similar. With group input on, clear
                // every pane the user is typing into, in every window the
                // broadcast scope reaches, not just the focused one.
                const CLEAR_SCROLLBACK: &[u8] = b"\x1b[3J";
                if ws.mux.is_broadcast_on() {
                    let targets = ws.mux.broadcast_target_ids();
                    apply_terminal_control(&ws.mux, &targets, CLEAR_SCROLLBACK);
                    if crate::mux::Mux::scope_crosses_windows(&ws.mux.broadcast) {
                        let scope = ws.mux.broadcast.clone();
                        for other in self.windows.values() {
                            let targets = other.mux.foreign_target_ids(&scope);
                            apply_terminal_control(&other.mux, &targets, CLEAR_SCROLLBACK);
                        }
                    }
                } else if let Some(pane_id) = ws.mux.active_focus() {
                    apply_terminal_control(&ws.mux, &[pane_id], CLEAR_SCROLLBACK);
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::Reset => {
                // RIS (`ESC c`) full-resets the engine: clears the grid,
                // restores DEC modes to defaults, drops the alt-screen back.
                // The PTY child then sees a fresh prompt next time it draws.
                // Kettle also owns UI state OUTSIDE the engine (selection,
                // scrollback display-offset, and the search, command palette,
                // hint mode and SSH launcher overlays), so sweep that too, or a
                // stale highlight or open modal survives the reset.
                if let Some(pane_id) = ws.mux.active_focus() {
                    // The reset turns mouse reporting off, so a held button's
                    // release goes to the program first.
                    self.release_held_buttons(ws, |held| held.pane == Some(pane_id));
                    apply_terminal_control(&ws.mux, &[pane_id], b"\x1bc");
                }
                self.clear_selection_on_input(ws);
                self.close_all_modals(ws);
                // Reset the blink phase so the cursor shows at once. Otherwise
                // a Reset during the blink-off phase hides the cursor for up to
                // one blink interval, and Reset is the chord users hit to
                // recover a visually-jammed terminal. Shares `reset_blink_phase`
                // with the focus-change and modal-close paths.
                self.reset_blink_phase(ws);
            }
            Action::ScrollPageUp
            | Action::ScrollPageDown
            | Action::ScrollLineUp
            | Action::ScrollLineDown
            | Action::ScrollToTop
            | Action::ScrollToBottom => {
                if let Some(p) = ws.mux.focused()
                    && let Ok(mut t) = p.term.term.lock()
                {
                    t.scroll_display(match action {
                        Action::ScrollPageUp => Scroll::PageUp,
                        Action::ScrollPageDown => Scroll::PageDown,
                        // `Scroll::Delta(+n)` scrolls *back* (toward older
                        // lines) — same sign convention the mouse-wheel
                        // path uses; line-up = +1, line-down = -1.
                        Action::ScrollLineUp => Scroll::Delta(1),
                        Action::ScrollLineDown => Scroll::Delta(-1),
                        Action::ScrollToTop => Scroll::Top,
                        _ => Scroll::Bottom,
                    });
                }
            }
            Action::SelectAll => {
                // Select the entire buffer (scrollback + screen). Mirrors
                // `apply_smart_selection`'s Selection-building, spanning the
                // grid-absolute buffer bounds.
                if let Some(p) = ws.mux.focused()
                    && let Ok(mut t) = p.term.term.lock()
                {
                    use kettle_core::Dimensions;
                    let (top, bottom) = selection_buffer_bounds(
                        t.grid().history_size(),
                        t.grid().screen_lines(),
                        t.grid().columns(),
                    );
                    let mut sel = kettle_core::Selection::new(
                        kettle_core::SelectionType::Simple,
                        top,
                        kettle_core::Side::Left,
                    );
                    sel.update(bottom, kettle_core::Side::Right);
                    t.selection = Some(sel);
                }
            }
            Action::SelectToTop | Action::SelectToBottom => {
                // Extend the selection to the first line / last cell of the
                // buffer (the AskUbuntu "select all in terminator" gesture,
                // Shift+Home / Shift+End), then scroll to reveal the new extent.
                let to_top = matches!(action, Action::SelectToTop);
                if let Some(p) = ws.mux.focused()
                    && let Ok(mut t) = p.term.term.lock()
                {
                    use kettle_core::Dimensions;
                    let (top, bottom) = selection_buffer_bounds(
                        t.grid().history_size(),
                        t.grid().screen_lines(),
                        t.grid().columns(),
                    );
                    let (edge, side) = if to_top {
                        (top, kettle_core::Side::Left)
                    } else {
                        (bottom, kettle_core::Side::Right)
                    };
                    match t.selection.as_mut() {
                        // Grow an existing selection's active end toward the
                        // edge, keeping its anchor (editor-style range growth).
                        Some(sel) => sel.update(edge, side),
                        // No selection yet: anchor at the cursor, extend to edge.
                        None => {
                            let anchor = t.grid().cursor.point;
                            let mut sel = kettle_core::Selection::new(
                                kettle_core::SelectionType::Simple,
                                anchor,
                                kettle_core::Side::Left,
                            );
                            sel.update(edge, side);
                            t.selection = Some(sel);
                        }
                    }
                    t.scroll_display(if to_top { Scroll::Top } else { Scroll::Bottom });
                }
            }
            Action::JumpPrevPrompt | Action::JumpNextPrompt => {
                let prev = matches!(action, Action::JumpPrevPrompt);
                if let Some(p) = ws.mux.focused() {
                    p.term.jump_to_prompt(prev);
                }
            }
            Action::OpenSsh => {
                self.close_all_modals(ws);
                ws.ssh_input = Some((String::new(), 0));
            }
            Action::CommandPalette => {
                self.close_all_modals(ws);
                ws.palette_input = Some((String::new(), 0));
            }
            // Open the in-app settings overlay (Ctrl+, / right-click
            // → Settings / palette "Open settings").
            Action::OpenSettings => {
                self.close_all_modals(ws);
                // Enumerate GPUs once for the Graphics device picker and cache
                // them for the session; a wgpu adapter walk is too heavy to
                // repeat per frame.
                if self.gpu_choices.is_empty() {
                    self.gpu_choices = kettle_render::detect_gpus()
                        .into_iter()
                        .map(|g| {
                            (
                                format!("{:x}:{:x}:{}", g.vendor, g.device, g.name),
                                format!("{} ({})", g.name, g.kind),
                            )
                        })
                        .collect();
                }
                ws.settings_restart_pending = false;
                ws.settings_nav = Some(crate::settings::SettingsNav::default());
            }
            // Terminator parity (layoutlauncher.py): open the runtime layout
            // picker. With no saved layouts the modal still opens, with a hint
            // to save one with `kettle --save-layout NAME`.
            Action::OpenLayoutPicker => {
                self.close_all_modals(ws);
                ws.layout_picker_entries = crate::session::Session::list_layouts();
                ws.layout_picker_input = Some((String::new(), 0));
            }
            Action::OpenThemePicker => self.open_theme_picker(ws),
            Action::OpenMediaShelf => self.open_media_shelf(ws),
            Action::PreviewClipboardPath => self.preview_copied_file(ws),
            Action::FocusPreview => self.focus_preview(ws),
            // The silent preview, labelled as such, never the video itself.
            Action::PreviewPlay => {
                if let Some(pane) = ws.mux.active_focus()
                    && ws.preview_panels.contains_key(&pane)
                {
                    self.toggle_lane_preview(ws, pane);
                }
            }
            Action::RenderClipboardAsDiagram => self.preview_copied_diagram(ws, false),
            Action::RenderSelectionAsDiagram => self.preview_copied_diagram(ws, true),
            Action::CopyAgentSetup => self.copy_agent_setup(),
            Action::PreviewNext
            | Action::PreviewPrevious
            | Action::PreviewNextDiagram
            | Action::PreviewPreviousDiagram
            | Action::ClosePreview
            | Action::PreviewSource
            | Action::PreviewCanvas
            | Action::PreviewCopy
            | Action::PreviewReload
            | Action::VideoPlay
            | Action::VideoMute
            | Action::PreviewZoomIn
            | Action::PreviewZoomOut
            | Action::PreviewFit => {
                if let Some(hit) = lane_action_hit(&action)
                    && let Some(pane) = ws.mux.active_focus()
                    && ws.preview_panels.contains_key(&pane)
                {
                    self.act_on_preview(ws, pane, hit);
                }
            }
            Action::HintMode | Action::PreviewLink => {
                let preview = matches!(action, Action::PreviewLink);
                let targets = self.collect_hints(ws, preview);
                if targets.is_empty() {
                    // Nothing in the pane to preview: say so, as the plain
                    // quick select's empty pane needs no word. A quick select
                    // already open stays as it was.
                    if preview {
                        let tr = self.ui_text;
                        fire_notify(
                            tr.text(kettle_i18n::Text::NotifyTitlePreviewNothing),
                            tr.text(kettle_i18n::Text::NotifyBodyPreviewNothing),
                        );
                    }
                } else {
                    self.close_all_modals(ws);
                    // The purpose goes with the targets it chose.
                    ws.hint_state = Some((targets, String::new()));
                    ws.hint_preview = preview;
                }
            }
            Action::ToggleViMode => {
                if ws.vi_mode.is_some() {
                    self.exit_vi_mode(ws);
                } else {
                    self.enter_vi_mode(ws);
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::OpenContextMenu => {
                // Keyboard-triggered open: anchor at the current mouse position
                // so the menu lands where the user is looking.
                let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                self.open_context_menu(ws, px, py, false);
            }
            Action::UndoCloseTab => {
                let waker = self.waker();
                match ws
                    .mux
                    .undo_close_tab_geometry(&self.cfg, tab_geometry, waker)
                {
                    Ok(true) => {
                        self.resize_all(ws);
                        self.save_session(ws);
                    }
                    Ok(false) => {
                        log::debug!("undo_close_tab: ring is empty, nothing to restore");
                    }
                    Err(e) => log::error!("undo_close_tab failed: {e}"),
                }
            }
            Action::DuplicateTab => {
                let waker = self.waker();
                if let Err(e) =
                    ws.mux
                        .duplicate_focused_tab_geometry(&self.cfg, tab_geometry, waker)
                {
                    log::error!("duplicate_tab failed: {e}");
                } else {
                    self.resize_all(ws);
                    self.save_session(ws);
                }
            }
            Action::DuplicatePane => {
                let waker = self.waker();
                if let Err(e) = ws.mux.duplicate_focused_pane_geometry(
                    crate::mux::Dir::Horizontal,
                    &self.cfg,
                    horizontal_split_geometry,
                    waker,
                ) {
                    log::error!("duplicate_pane failed: {e}");
                } else {
                    self.resize_all(ws);
                }
            }
            Action::NextTheme | Action::PrevTheme => {
                let fwd = matches!(action, Action::NextTheme);
                // Stay with the current theme's appearance, one similar
                // look at a time; switching light and dark is its own action.
                let name = kettle_config::Theme::cycle_by_look(&self.cfg.theme_name, fwd);
                self.set_runtime_theme_name(ws, name);
                if !self.persist_pref("theme", name) {
                    // Config-governed; notify on failure.
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleThemeNotSaved),
                        self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
                    );
                }
            }
            Action::ToggleLightDark => {
                if let Some(next) = pick_light_dark_target(
                    &self.cfg.theme_name,
                    &self.cfg.light_theme,
                    &self.cfg.dark_theme,
                ) {
                    self.set_runtime_theme_name(ws, &next);
                    if !self.persist_pref("theme", &next) {
                        // Config-governed; notify on failure.
                        fire_notify(
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyTitleThemeNotSaved),
                            self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
                        );
                    }
                } else {
                    log::warn!(
                        "toggle-light-dark: needs both light-theme and dark-theme in config (current: light={:?} dark={:?})",
                        self.cfg.light_theme,
                        self.cfg.dark_theme,
                    );
                }
            }
            Action::ToggleSessionLog => {
                // Terminator parity (`plugins/logger.py`):
                // toggle the focused pane's session log. This arm computes the
                // path; the persistence worker performs all filesystem I/O.
                // Routed through `Terminal::set_log_path` so secure file
                // preparation, the reader's lock-skip flag, and the bounded
                // writer stay in one transition without filesystem I/O here.
                if let Some(pane) = ws.mux.focused() {
                    if pane.term.log_enabled() {
                        match pane.term.set_log_path(None) {
                            Ok(_) => log::info!("toggle-session-log: stopped"),
                            Err(error) => {
                                log::warn!("toggle-session-log: stop failed: {error}");
                                fire_notify(
                                    self.ui_text
                                        .text(kettle_i18n::Text::NotifyTitleSessionLogError),
                                    self.ui_text
                                        .text(kettle_i18n::Text::NotifyBodySessionLogStopFailed),
                                );
                            }
                        }
                    } else {
                        let secs = std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .map(|d| d.as_secs())
                            .unwrap_or(0);
                        let cache = cache_dir_from_env(|k| std::env::var(k).ok());
                        let path = session_log_path(secs, std::process::id(), cache.as_deref());
                        // Propagate the config's strip-ANSI choice before the
                        // log goes live, so the first admitted read honors it.
                        if let Ok(mut strip) = pane.term.log_strip_ansi.lock() {
                            *strip = self.cfg.log_strip_ansi;
                        }
                        match pane.term.set_log_path(Some(path.clone())) {
                            Ok(_) => log::info!(
                                "toggle-session-log: queued asynchronous open for {}",
                                path.display()
                            ),
                            Err(error) => {
                                log::warn!(
                                    "toggle-session-log: start {} failed: {error}",
                                    path.display()
                                );
                                fire_notify(
                                    self.ui_text
                                        .text(kettle_i18n::Text::NotifyTitleSessionLogError),
                                    self.ui_text
                                        .text(kettle_i18n::Text::NotifyBodySessionLogStartFailed),
                                );
                            }
                        }
                    }
                }
            }
            Action::TakeScreenshot => {
                // Compute the output path, queue the
                // request, then fire a desktop notification so the
                // user knows where to look. Also compute
                // the focused pane's rect at dispatch time so the
                // screenshot crops to just that pane. Computed
                // BEFORE the `&mut ws.renderer` borrow to keep
                // the borrow window narrow.
                let area = self.area(ws);
                let active = ws.mux.active;
                let focus_id = ws.mux.tabs.get(active).map(|t| t.focus).unwrap_or(0);
                let crop = ws
                    .mux
                    .leaves(active, area)
                    .into_iter()
                    .find(|(id, _)| *id == focus_id)
                    .map(|(_, rect)| rect);
                if let Some(renderer) = ws.renderer.as_mut() {
                    let secs = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_secs())
                        .unwrap_or(0);
                    let cache = cache_dir_from_env(|k| std::env::var(k).ok());
                    let path = session_screenshot_path(secs, std::process::id(), cache.as_deref());
                    let path_str = path.display().to_string();
                    let proxy = self.proxy.clone();
                    let request = kettle_render::ScreenshotRequest {
                        out_path: path,
                        output_policy: kettle_render::ScreenshotOutputPolicy::PrivateState,
                        crop,
                        completion: None,
                        cancellation: None,
                        recovery_wake: Some(kettle_render::ScreenshotRecoveryWake::new(
                            move || {
                                let _ = proxy.send_event(UserEvent::Wakeup);
                            },
                        )),
                    };
                    if renderer.set_pending_screenshot(request).is_ok() {
                        log::info!("take_screenshot: queued -> {path_str}");
                        fire_notify(
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyTitleScreenshotQueued),
                            &path_str,
                        );
                    } else {
                        log::warn!("take_screenshot: another capture is in progress");
                        fire_notify(
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyTitleScreenshotBusy),
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyBodyScreenshotWait),
                        );
                    }
                }
            }
            Action::ReloadConfig => self.reload_config(ws),
            // Terminator's `move_tab` wraps at both ends of the bar; the drag
            // path clamps instead. See `Mux::nudge_active_tab`.
            Action::MoveTabLeft | Action::MoveTabRight => {
                let delta = if action == Action::MoveTabLeft { -1 } else { 1 };
                if ws.mux.nudge_active_tab(delta) {
                    self.save_session(ws);
                }
            }
            Action::NewTabShell(n) => {
                // Ctrl+Shift+N opens the Nth dropdown
                // entry (Windows Terminal's profile shortcuts). The list is
                // process-cached + prewarmed; out-of-range is a silent no-op,
                // same as GotoTab clamping.
                let shells = kettle_core::term::detect_shells();
                if let Some((_, argv)) = shells.get(n as usize) {
                    let argv = argv.clone();
                    self.open_tab_with_argv(ws, &argv);
                }
            }
            Action::About => self.open_about_panel(ws),
            Action::GotoTab(n) => {
                let i = n as usize;
                if i < ws.mux.tabs.len() {
                    ws.mux.active = i;
                    ws.mux.touch_active_tab_seen();
                }
            }
            // Keyboard equivalents of clicking the
            // update banner — `OpenUpdate` opens the release page + dismisses,
            // `DismissUpdate` just dismisses. Both no-op (debug-logged) when no
            // banner is showing, so a bound key is harmless the rest of the time.
            Action::OpenUpdate => {
                if !self.act_on_update_banner(ws, true) {
                    log::debug!("open_update: no update banner is showing");
                }
            }
            Action::DismissUpdate => {
                if !self.act_on_update_banner(ws, false) {
                    log::debug!("dismiss_update: no update banner is showing");
                }
            }
            // Terminator parity: the Edit-title overlay. Each action opens it
            // pre-filled with the current title; Enter applies via the matching
            // setter, Esc cancels. It renders as a thin bar at the top of the
            // window, shaped like the `Action::CommandPalette` overlay.
            Action::EditWindowTitle => {
                self.close_all_modals(ws);
                ws.editing_title = begin_title_edit(
                    &ws.mux,
                    TitleEditScope::Window,
                    GroupBulkScope::Single,
                    &ws.last_title,
                );
                ws.pending_resize = true;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::EditTabTitle => {
                self.close_all_modals(ws);
                ws.editing_title = begin_title_edit(
                    &ws.mux,
                    TitleEditScope::Tab,
                    GroupBulkScope::Single,
                    &ws.last_title,
                );
                ws.pending_resize = true;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::EditPaneTitle => {
                self.close_all_modals(ws);
                ws.editing_title = begin_title_edit(
                    &ws.mux,
                    TitleEditScope::Pane,
                    GroupBulkScope::Single,
                    &ws.last_title,
                );
                ws.pending_resize = true;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::EditPaneGroup | Action::CreateGroup => {
                // Edit the focused pane's
                // broadcast-group name. Empty input → clear the
                // group. Same overlay mechanism as
                // EditPaneTitle. `CreateGroup` (Terminator name)
                // and `EditPaneGroup` (kettle name) share dispatch.
                self.close_all_modals(ws);
                ws.editing_title = begin_title_edit(
                    &ws.mux,
                    TitleEditScope::Group,
                    GroupBulkScope::Single,
                    &ws.last_title,
                );
                ws.pending_resize = true;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::GroupTab | Action::GroupWindow => {
                // Open the
                // title-edit overlay with `bulk` set to Tab/Window
                // so on Apply the typed name writes to every pane
                // in scope.
                self.close_all_modals(ws);
                let bulk = if matches!(action, Action::GroupTab) {
                    GroupBulkScope::Tab
                } else {
                    GroupBulkScope::Window
                };
                ws.editing_title =
                    begin_title_edit(&ws.mux, TitleEditScope::Group, bulk, &ws.last_title);
                ws.pending_resize = true;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::GroupAll | Action::UngroupAll | Action::ToggleGroupAll => {
                // Terminator parity (window.py:933 / :947). `group_all` puts
                // every terminal into a group literally named "All"; there is
                // no prompt, which is what separates it from `GroupWindow`.
                // `ungroup_all` is its partner.
                let all = kettle_ui_group_all_name();
                // `group_all_toggle` asks the INVOKING terminal, not the whole
                // set (window.py:940-945: `if widget.group == 'All'`). Testing
                // "is everything already grouped" instead inverted the answer
                // whenever one sibling had been ungrouped by hand: Terminator
                // ungroups everything, kettle grouped the straggler.
                let group = match action {
                    Action::GroupAll => true,
                    Action::UngroupAll => false,
                    _ => ws.mux.focused().and_then(|p| p.group_name.as_deref()) != Some(all),
                }
                .then(|| all.to_string());
                // Terminator's scope is its whole terminal collection, across
                // every window (`self.terminator.terminals`), so a second
                // kettle window must not be left out.
                for target in std::iter::once(&mut *ws).chain(self.windows.values_mut()) {
                    let pane_ids: Vec<u64> = target.mux.panes.keys().copied().collect();
                    for id in pane_ids {
                        if let Some(p) = target.mux.panes.get_mut(&id) {
                            p.group_name = group.clone();
                        }
                    }
                    if let Some(w) = &target.window {
                        w.request_redraw();
                    }
                }
            }
            Action::ToggleGroupTab | Action::ToggleGroupWindow => {
                // Terminator parity (window.py:959, :987). It tests the
                // INVOKING terminal's group and generates the name rather than
                // asking for one — `Tab N` / `Window group N` — which is what
                // makes these a toggle at all, where kettle's `GroupTab` and
                // `GroupWindow` open the name prompt.
                let tab_scope = matches!(action, Action::ToggleGroupTab);
                let name = if tab_scope {
                    format!("Tab {}", ws.mux.active + 1)
                } else {
                    format!("Window group {}", ws.seq)
                };
                let grouped = ws
                    .mux
                    .focused()
                    .and_then(|p| p.group_name.as_deref())
                    .is_some_and(|g| g == name);
                let pane_ids: Vec<u64> = if tab_scope {
                    ws.mux
                        .tabs
                        .get(ws.mux.active)
                        .map(|t| t.root.leaf_ids())
                        .unwrap_or_default()
                } else {
                    ws.mux.panes.keys().copied().collect()
                };
                for id in pane_ids {
                    if let Some(p) = ws.mux.panes.get_mut(&id) {
                        p.group_name = (!grouped).then(|| name.clone());
                    }
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Action::UngroupTab | Action::UngroupWindow => {
                // Bulk-
                // clear the group on every pane in scope. No
                // overlay needed — empty input is the "clear"
                // signal, and the action carries the scope.
                let pane_ids: Vec<u64> = if matches!(action, Action::UngroupTab) {
                    ws.mux
                        .tabs
                        .get(ws.mux.active)
                        .map(|t| t.root.leaf_ids())
                        .unwrap_or_default()
                } else {
                    ws.mux.panes.keys().copied().collect()
                };
                for id in pane_ids {
                    if let Some(p) = ws.mux.panes.get_mut(&id) {
                        p.group_name = None;
                    }
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            // Terminator parity (terminatorlib/terminal.py:
            // key_next_profile + key_previous_profile): runtime cycle
            // through profile files at <config-dir>/profiles/.
            //
            // Enumerates the profiles directory each dispatch (cheap;
            // typically <10 entries), sorts deterministically, finds
            // the current entry by basename match against the loaded
            // config-path, and loads the next/prev. Falls back to
            // log::info when no profiles directory or no entries.
            Action::NextProfile | Action::PrevProfile => {
                // Delegate listing + name extraction to
                // kettle-config so the same path math has a single
                // home (and drift guards on it). Empty list → no-op
                // with a one-line info nudge.
                let names = kettle_config::Config::list_profiles();
                if names.is_empty() {
                    log::info!(
                        "{action:?}: no profiles in <config-dir>/profiles/ — \
                         create one with `kettle --print-default-config > \
                         ~/.config/kettle/profiles/dev.config`"
                    );
                } else {
                    let current = self
                        .config_path
                        .as_deref()
                        .and_then(kettle_config::Config::profile_name_from_path);
                    let next = pick_next_profile(
                        current.as_deref(),
                        &names,
                        matches!(action, Action::NextProfile),
                    );
                    if let Some(p) = kettle_config::Config::path_for_profile(&next) {
                        self.config_path = Some(p);
                        self.config_trust = ConfigTrust::VerifyDirectory;
                        self.reload_config(ws);
                    }
                }
            }
            // Split-tree rotation (Terminator `rotate_cw` / `rotate_ccw`):
            // turn the active tab's whole layout a quarter turn. No-op on a
            // single-pane tab. Rotating changes every pane's rect, so the PTYs
            // have to be resized and the new arrangement saved — a redraw alone
            // would leave every child process believing its old geometry.
            Action::RotateCw | Action::RotateCcw => {
                if ws.mux.rotate_layout(action == Action::RotateCw) {
                    self.resize_all(ws);
                    self.save_session(ws);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
            // Runtime scrollbar toggle. Cycles
            // ScrollbarMode through Never → Always → Auto → Never.
            // Three-state cycle (vs binary) because Auto is the
            // useful steady state for most users; explicit toggle
            // is for power users with a specific preference. Same
            // shape as the `NextTheme` cycle.
            Action::ToggleScrollbar => {
                use kettle_config::ScrollbarMode::*;
                self.cfg.scrollbar = match self.cfg.scrollbar {
                    Never => Always,
                    Always => Auto,
                    Auto => Never,
                };
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            // Terminator parity: toggle the focused pane's read-only
            // state. While on, user input (keystrokes / paste / broadcast) is
            // dropped before it reaches the PTY; the child keeps producing
            // output. A `[RO]` titlebar badge shows the state.
            Action::TogglePaneReadOnly => {
                // A pane turned read-only gets no more input, so a held
                // button's release goes to it first.
                if let Some(pane) = ws.mux.active_focus()
                    && ws.mux.focused().is_some_and(|focused| !focused.read_only)
                {
                    self.release_held_buttons(ws, |held| held.pane == Some(pane));
                }
                let _ = ws.mux.toggle_focused_read_only();
                // The `[RO]` titlebar badge reflects the new state.
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            // Insert pane index. Pane index is 1-based
            // (matches Terminator's GotoTab + every user-facing
            // numbering). InsertPanePadded uses 2-digit zero-padded
            // form (Terminator default).
            Action::InsertPaneNumber => {
                let idx = ws
                    .mux
                    .focused_pane_index_in_tab()
                    .map(|i| i + 1)
                    .unwrap_or(1);
                if let Some(pane_id) = ws.mux.active_focus()
                    && let Some(p) = ws.mux.panes.get(&pane_id)
                {
                    let result = p.feed_input(idx.to_string().as_bytes());
                    self.report_input_result(result);
                    Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
                }
            }
            Action::InsertPanePadded => {
                let idx = ws
                    .mux
                    .focused_pane_index_in_tab()
                    .map(|i| i + 1)
                    .unwrap_or(1);
                if let Some(pane_id) = ws.mux.active_focus()
                    && let Some(p) = ws.mux.panes.get(&pane_id)
                {
                    let result = p.feed_input(format!("{idx:02}").as_bytes());
                    self.report_input_result(result);
                    Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
                }
            }
            // Terminator parity (`insert_term_name.py`
            // plugin → `InsertTermName` menu item + keybind). Send
            // the focused pane's title (Pane::title — same string
            // the chrome shows in the per-pane titlebar) to the
            // PTY. Useful for scripts that want to label their
            // output by source pane, or for keyboard workflows
            // that re-type the current title into the command line.
            Action::InsertPaneName => {
                if let Some(pane_id) = ws.mux.active_focus()
                    && let Some(p) = ws.mux.panes.get(&pane_id)
                {
                    let title = p.title.clone();
                    let result = p.feed_input(title.as_bytes());
                    self.report_input_result(result);
                    Self::dismiss_media_paste_receipt_after_input(ws, pane_id, result);
                }
            }
            // Terminator parity (`dir_open.py` plugin → `CurrDirOpen` menu
            // item). Open the focused pane's cwd in the OS file manager by
            // routing `file://<cwd>` through `open_url`, like a clicked
            // `file://` hyperlink, so the `LuaEvent::UrlClicked` dispatch, the
            // `custom_url_handler` config and the `is_safe_url` allowlist
            // (which accepts `file://` without `..`) all apply.
            Action::OpenCwdInFileManager => {
                match ws
                    .mux
                    .focused()
                    .and_then(|p| p.term.current_dir_or_native())
                {
                    // Refuse a non-local OSC 7 cwd before
                    // building/opening the URL (it's untrusted PTY input — a
                    // UNC path would trigger an SMB/NTLM leak on Windows). A
                    // remote pane's directory is on another machine.
                    // The URL is encoded from the path, so a directory with a
                    // space or `#` in its name opens rather than failing the
                    // URL check or naming another folder.
                    Some(cwd) if cwd_is_local(&cwd) => {
                        let pane = ws.mux.active_focus();
                        match kettle_core::links::file_url_for_path(std::path::Path::new(&cwd)) {
                            Some(url) => self.open_pane_link(ws, pane, &url),
                            None => log::warn!(
                                "Action::OpenCwdInFileManager: the cwd has no local file URL"
                            ),
                        }
                    }
                    Some(_) => {
                        log::warn!(
                            "Action::OpenCwdInFileManager: refusing a non-local cwd \
                             reported via OSC 7 (possible UNC/SSRF payload)"
                        );
                    }
                    None => {
                        log::info!("Action::OpenCwdInFileManager: focused pane has no known cwd");
                    }
                }
            }
            // Half-page scroll. Same shape as the
            // ScrollPageUp/Down handler but with half the row count.
            // Pull the row count from the focused pane's grid
            // dimensions (works for any pane size).
            Action::ScrollPageUpHalf | Action::ScrollPageDownHalf => {
                if let Some(p) = ws.mux.focused()
                    && let Ok(mut t) = p.term.term.lock()
                {
                    use kettle_core::Dimensions;
                    let rows = t.screen_lines() as i32;
                    let half = (rows / 2).max(1);
                    let dir = if matches!(action, Action::ScrollPageUpHalf) {
                        half
                    } else {
                        -half
                    };
                    t.scroll_display(Scroll::Delta(dir));
                }
            }
            // Paste the X11 PRIMARY selection (middle-click). On X11
            // PRIMARY is the last mouse-highlighted text, distinct from the
            // CLIPBOARD; `paste_primary` reads PRIMARY on Linux and falls back
            // to the clipboard on Wayland/macOS/Windows. It shares `paste_text`
            // so the LOCAL_PASTE_MAX clamp, bracketed-paste wrap, and broadcast
            // scoping all match Action::Paste.
            Action::PastePrimary => self.paste_primary(ws),
            // In-process Quake toggle. Same tri-state
            // logic as the `--toggle` remote command:
            //   hidden → show + focus
            //   visible + focused → hide
            //   visible + !focused → focus (don't hide)
            Action::ToggleWindowVisibility => {
                if let Some(w) = &ws.window {
                    let visible = w.is_visible().unwrap_or(true);
                    let focused = w.has_focus();
                    if !visible {
                        w.set_visible(true);
                        w.focus_window();
                    } else if focused {
                        w.set_visible(false);
                    } else {
                        w.focus_window();
                    }
                }
            }
            // Terminator parity (`detachable_tabs`): move the active tab into a
            // new window.
            Action::MoveTabToWindow => self.open_tab_window_chooser(ws),
            Action::MoveTabToNewWindow => {
                // Move the tab LIVE, in process. Its panes (PTYs, scrollback,
                // running programs) transfer untouched to a brand-new window
                // via detach_tab → open_window(AdoptTab). The deprecated
                // receive-side `--tab-handoff` parsing remains for an old sender
                // caught mid-upgrade.
                if !self.cfg.detachable_tabs {
                    log::info!("move_tab_to_new_window ignored because detachable-tabs = false");
                    return;
                }
                if ws.mux.tabs.len() <= 1 {
                    // Moving a lone tab out of its window is a no-op: you'd
                    // get the same window back.
                    return;
                }
                let closing_idx = ws.mux.active;
                self.release_held_buttons_in_tab(ws, closing_idx);
                let Some(dt) = ws.mux.detach_tab(closing_idx) else {
                    return;
                };
                self.release_focus_report_to(ws, &dt);
                let paste = ws.take_moved_paste_state(&dt.tab, std::time::Instant::now());
                match self
                    .open_window(
                        event_loop,
                        WindowOpen::AdoptTab {
                            tab: dt,
                            source_color: self.tear_off_source_color(ws),
                            paste: Box::new(paste),
                        },
                        None,
                        None,
                    )
                    .map_err(|open| *open)
                {
                    Ok(_) => {
                        // The tab LEFT this window, so plugins see a tab-close
                        // event.
                        self.fire_tab_close_event(ws, closing_idx);
                        // Agents subscribed to the event feed see moves.
                        self.ctl_broadcast(
                            "tab_moved",
                            None,
                            serde_json::json!({
                                "from_window": ws.seq,
                                "to_window": self.focused_seq,
                                "tab": closing_idx,
                            }),
                        );
                        self.resize_all(ws);
                        if let Some(w) = &ws.window {
                            w.request_redraw();
                        }
                    }
                    Err(WindowOpen::AdoptTab { tab: dt, paste, .. }) => {
                        // Window creation failed — put the live tab back
                        // exactly where it was; nothing is lost.
                        log::warn!(
                            "MoveTabToNewWindow: open_window failed; tab kept in source window"
                        );
                        ws.mux.attach_tab(dt, Some(closing_idx));
                        ws.restore_moved_paste_state(*paste);
                    }
                    Err(_) => unreachable!("open_window returns the WindowOpen it was given"),
                }
            }
            Action::ResetAndClear => {
                // Terminator parity (key_reset_clear): Reset (RIS, \ec) and
                // ClearHistory (CSI 3 J) in one keybind, with Reset's sweep of
                // Kettle's own UI state.
                if let Some(pane_id) = ws.mux.active_focus() {
                    // As for Reset, a held button's release goes first.
                    self.release_held_buttons(ws, |held| held.pane == Some(pane_id));
                    // One request, so a full queue cannot accept RIS but reject
                    // the paired history clear.
                    apply_terminal_control(&ws.mux, &[pane_id], b"\x1bc\x1b[3J");
                }
                self.clear_selection_on_input(ws);
                self.close_all_modals(ws);
                self.reset_blink_phase(ws);
            }
        }
        // If focus moved as a result of the action,
        // land the cursor visible on the new pane right away.
        self.hoover_groups(ws);
        self.note_focus_change(ws, pre_focus);
        // Coalesce into the per-frame flush when a frame is actually coming.
        //
        // This tail runs after EVERY action. Resizing here eagerly meant a
        // queued pair of geometry-affecting actions -- a Lua hook dispatching
        // `EditWindowTitle` then `CommandPalette`, processed before any redraw
        // -- resized twice: shrink, then grow, for a net-zero frame. The user
        // sees nothing, but the PTY child gets two `SIGWINCH`s and vim, tmux or
        // htop redraw for no reason.
        //
        // `save_session` runs immediately below and does NOT depend on this:
        // it records the OS window rect and the split tree, never the PTY grid.
        //
        // With no window there is no frame to flush on, so resize now — a
        // deferred resize that never runs is worse than an eager one that runs
        // twice.
        if ws.window.is_some() {
            ws.pending_resize = true;
        } else {
            self.resize_all(ws);
        }
        self.save_session(ws);
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Snapshot ONE window (its tabs + geometry).
    fn snapshot_window(w: &WindowState) -> crate::session::SWindow {
        let s = w.mux.snapshot();
        let geometry = w.window.as_ref().and_then(|win| {
            // A minimized window does not report where it will come back to.
            // Win32 answers `GetWindowRect` with the (-32000, -32000) sentinel
            // and `GetClientRect` with 0x0, and winit passes both through
            // verbatim, so snapshotting one persisted a geometry that the
            // restore clamp could only rescue as far as its 160x120 floor —
            // the window came back as an unusable stub. Saving no geometry
            // restores it at the default size instead, which is the honest
            // answer to "we do not know where this window was".
            //
            // The size check is not redundant with `is_minimized`: it is the
            // observable that actually breaks the restore, and it also covers
            // a window reporting a degenerate size for any other reason.
            if win.is_minimized().unwrap_or(false) {
                return None;
            }
            let size = win.inner_size();
            if size.width == 0 || size.height == 0 {
                return None;
            }
            let pos = win.outer_position().ok()?;
            Some(crate::session::SGeometry {
                x: pos.x,
                y: pos.y,
                w: size.width,
                h: size.height,
            })
        });
        crate::session::SWindow {
            tabs: s.tabs,
            active: s.active,
            geometry,
        }
    }

    fn save_session(&self, ws: &WindowState) {
        // Serialize EVERY live window (the checked-out one plus the map),
        // ordered by seq so window 1 stays first. Windows whose mux is already
        // empty (a close_window in flight) are dropped, since there is nothing
        // to restore.
        let mut wins: Vec<(u64, crate::session::SWindow)> =
            vec![(ws.seq, Self::snapshot_window(ws))];
        for w in self.windows.values() {
            wins.push((w.seq, Self::snapshot_window(w)));
        }
        wins.sort_by_key(|(seq, _)| *seq);
        let windows: Vec<crate::session::SWindow> = wins
            .into_iter()
            .map(|(_, w)| w)
            .filter(|w| !w.tabs.is_empty())
            .collect();
        // Downgrade-compat dual-write: mirror window 1 into the legacy
        // top-level fields so an older kettle reading this file still
        // restores its first window.
        let mut s = crate::session::Session {
            tabs: windows.first().map(|w| w.tabs.clone()).unwrap_or_default(),
            active: windows.first().map(|w| w.active).unwrap_or(0),
            theme: None,
            windows,
        };
        // Theme is config-governed (persisted to the config file via
        // `persist_pref`), NOT stored in the session. A session-pinned theme
        // would override the config/compile-time default on restore, so a
        // default change (or a fresh-config user) would silently keep the old
        // theme.
        s.theme = None;
        // When launched with `--layout NAME`, save to the
        // named-layout file instead of the default session.json. Lets
        // the user maintain distinct workspaces ("dev", "ops", "docs")
        // without each one clobbering the others on close.
        // Only write the DEFAULT session.json when this
        // launch is in restore mode — symmetric with the opt-in load gate. A
        // fresh (non-opted-in) window must NOT overwrite the saved layout that
        // `--restore` / `restore-session = true` exists to recover.
        match session_write_target(
            self.startup.layout.as_deref(),
            self.named_layout_writable,
            should_restore_session(self.startup.restore, self.cfg.restore_session),
            s.is_empty(),
        ) {
            SessionWriteTarget::NamedLayout(name) => s.save_layout(name),
            SessionWriteTarget::DefaultSession => s.save(),
            SessionWriteTarget::Skip => {}
        }
    }

    /// Phase 5 of [`TERMINATOR-AUTO-THEME-DESIGN.md`](
    /// ../../../docs/TERMINATOR-AUTO-THEME-DESIGN.md): poll the
    /// clock-schedule (when `cfg.theme_schedule` is `Some(Clock { … })`)
    /// and flip the theme between `light_theme` and `dark_theme` on
    /// boundary crossings.
    ///
    /// Cheap: a few u32 comparisons via
    /// `schedule_decision_clock`, run from `redraw()` per tick.
    /// State on `App::last_schedule_decision` means a single
    /// boundary fires the swap once; a follow-up could stretch the
    /// throttling further if needed.
    /// Terminator plugin parity (`LuaEvent::PaneFocus`).
    /// Detect focus boundary crossings —
    /// from any source (keybind, mouse click, new tab, close tab,
    /// remote-control IPC) — and emit a single `PaneFocus` event
    /// per crossing.
    ///
    /// Polled from `redraw()` per tick rather than wiring every
    /// focus-changing call site because (a) there are 6+
    /// such sites today and (b) future changes will add more.
    /// One diff site = one drift guard, not N.
    ///
    /// First tick after startup emits with `previous = None` so
    /// plugins can seed their state.
    fn poll_focus_event(&mut self, ws: &mut WindowState) {
        let current = ws.mux.active_focus();
        let Some(cur_id) = current else { return };
        if ws.last_emitted_focus == Some(cur_id) {
            return;
        }
        let prev = ws.last_emitted_focus;
        ws.last_emitted_focus = Some(cur_id);
        self.fire_lua_event(
            ws,
            crate::LuaEvent::PaneFocus(prev, cur_id),
            "pane_focus hook",
        );
        // Agent-first A2: mirror the focus change to ctl subscribers.
        self.ctl_broadcast(
            "pane_focus",
            Some(cur_id),
            serde_json::json!({"previous": prev}),
        );
    }

    /// Reflect the FOCUSED pane's OSC 9;4 progress onto the OS
    /// taskbar button each frame (pwsh 7 / Windows Terminal parity). Reads the
    /// focused pane the same way the cursor-blink poll does; `Taskbar` dedups
    /// internally, so an unchanged value costs nothing. No-op off Windows.
    fn poll_taskbar_progress(&mut self, ws: &mut WindowState) {
        let progress = ws
            .mux
            .active_focus()
            .and_then(|id| ws.mux.panes.get(&id))
            .and_then(|p| p.term.progress());
        if let Some(window) = ws.window.clone() {
            ws.taskbar.apply(&window, progress);
        }
    }

    /// Terminator plugin parity (`LuaEvent::TitleChanged`). Walk live panes,
    /// diff each title against `ws.last_emitted_titles`, emit on any
    /// boundary cross. One pass site, regardless of how many
    /// title-mutating sites exist in App.
    ///
    /// O(n_panes) per redraw. Even 100 panes is trivial — a
    /// hash lookup + string compare per entry. A follow-up
    /// can add a "dirty-title" bitset on Mux if pane counts
    /// grow into the thousands.
    fn poll_title_event(&mut self, ws: &mut WindowState) {
        // Also run when a ctl subscriber is present, so title changes reach
        // agents even without a Lua engine.
        let has_subscribers = self
            .ctl
            .as_ref()
            .map(|c| c.has_subscribers())
            .unwrap_or(false);
        if self.lua_engine.is_none() && !has_subscribers {
            return;
        }
        let mut changes: Vec<(u64, String)> = Vec::new();
        for (id, p) in ws.mux.panes.iter() {
            let last = ws.last_emitted_titles.get(id);
            if last.map(|s| s.as_str()) != Some(p.title.as_str()) {
                changes.push((*id, p.title.clone()));
            }
        }
        for (id, title) in changes {
            ws.last_emitted_titles.insert(id, title.clone());
            self.fire_lua_event(
                ws,
                crate::LuaEvent::TitleChanged(id, title.clone()),
                "title_changed hook",
            );
            self.ctl_broadcast("title", Some(id), serde_json::json!({"title": title}));
        }
        // Drop title state for panes that have closed so this map
        // can't grow unbounded over a long session of opening/closing panes
        // (it's only ever read for live panes). Covers every close path —
        // keybind, confirm dialog, tab close, reap. The O(1) length guard means
        // the O(n) retain runs only when there are actually stale entries.
        if ws.last_emitted_titles.len() > ws.mux.panes.len() {
            let panes = &ws.mux.panes;
            ws.last_emitted_titles
                .retain(|id, _| panes.contains_key(id));
        }
    }

    /// Whether the configured theme schedule calls for the dark theme now,
    /// or `None` without a schedule.
    fn theme_schedule_is_dark(&self) -> Option<bool> {
        let schedule = self.cfg.theme_schedule?;
        Some(match schedule {
            // Clock times are local wall-clock times.
            kettle_config::ThemeSchedule::Clock { .. } => {
                let (h, m, _) = crate::wall_clock::now_local();
                kettle_config::schedule_decision_clock((h, m), schedule)
            }
            kettle_config::ThemeSchedule::SunriseSunset { lat, long } => {
                crate::wall_clock::solar_is_dark(lat, long)
            }
        })
    }

    fn poll_theme_schedule(&mut self, ws: &mut WindowState) {
        let Some(is_dark) = self.theme_schedule_is_dark() else {
            return;
        };
        // Seed on first call so we don't flip the theme just for
        // existing on a "now's dark" tick — only boundary
        // crossings fire the swap.
        if self.last_schedule_decision == Some(is_dark) {
            return;
        }
        let was_first = self.last_schedule_decision.is_none();
        self.last_schedule_decision = Some(is_dark);
        if was_first {
            return;
        }
        // Boundary crossing: ask `resolve_theme_for_mode`
        // what to switch to. We override the ThemeMode to Light/Dark
        // for the duration of the swap so the helper picks the
        // configured light/dark theme name.
        let target_mode = if is_dark {
            kettle_config::ThemeMode::Dark
        } else {
            kettle_config::ThemeMode::Light
        };
        if let Some(next) = kettle_config::resolve_theme_for_mode(
            target_mode,
            &self.cfg.theme_name,
            &self.cfg.light_theme,
            &self.cfg.dark_theme,
            None,
        ) {
            self.apply_theme_name(ws, "theme-schedule", next);
        }
    }

    fn apply_theme_name(&mut self, ws: &mut WindowState, source: &str, next: String) {
        log::info!("{source}: switching to {next}");
        self.set_runtime_theme_name(ws, &next);
        self.save_session(ws);
    }

    /// Update the rendered palette and Lua's read-only view as one state
    /// transition. Every runtime theme mutation, including temporary menu
    /// previews and config reloads, must route through this synchronization
    /// boundary so `kettle.theme()` cannot describe a stale palette.
    fn set_runtime_theme_state(
        &mut self,
        ws: &WindowState,
        name: String,
        theme: kettle_config::Theme,
    ) {
        self.cfg.theme_name = name;
        self.cfg.theme = theme;
        self.sync_lua_active_theme();
        self.request_all_window_redraws(ws);
    }

    fn set_runtime_theme_name(&mut self, ws: &WindowState, name: &str) {
        self.set_runtime_theme_state(ws, name.to_string(), kettle_config::Theme::by_name(name));
    }

    fn request_all_window_redraws(&self, ws: &WindowState) {
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        for (&seq, window) in &self.windows {
            if seq != ws.seq
                && let Some(native) = &window.window
            {
                native.request_redraw();
            }
        }
    }

    fn sync_lua_active_theme(&self) {
        if let Some(engine) = &self.lua_engine
            && let Err(error) = engine.set_active_theme(&self.cfg.theme_name)
        {
            log::warn!(
                "active theme changed, but kettle.theme() could not be synchronized: {error:#}"
            );
        }
    }

    fn os_theme_choice(&self, theme: WindowTheme) -> Option<String> {
        if self.cfg.theme_mode != kettle_config::ThemeMode::Auto {
            return None;
        }
        if self.cfg.theme_schedule.is_some() {
            return None;
        }
        let os_dark = matches!(theme, WindowTheme::Dark);
        kettle_config::resolve_theme_for_mode(
            kettle_config::ThemeMode::Auto,
            &self.cfg.theme_name,
            &self.cfg.light_theme,
            &self.cfg.dark_theme,
            Some(os_dark),
        )
    }

    fn apply_initial_os_theme_preference(&mut self, ws: &WindowState, theme: WindowTheme) {
        if let Some(next) = self.os_theme_choice(theme) {
            log::info!("theme-mode=auto: initial OS theme selects {next}");
            self.set_runtime_theme_name(ws, &next);
        }
    }

    fn apply_os_theme_preference(&mut self, ws: &mut WindowState, theme: WindowTheme) {
        if let Some(next) = self.os_theme_choice(theme) {
            self.apply_theme_name(ws, "theme-mode=auto", next);
        }
    }

    /// The native window-theme hint for the current config. See
    /// [`native_theme_hint`] for the decision table.
    fn native_theme_hint(&self) -> Option<WindowTheme> {
        native_theme_hint(
            self.cfg.theme_mode,
            self.cfg.theme_schedule.is_some(),
            self.cfg.theme.is_dark(),
        )
    }

    /// Push the native theme and compatible live icon to every window when
    /// either changed since the last sync. Called at the top of `redraw` — every
    /// theme mutation ends in a repaint, so one lazy chokepoint covers all
    /// mutation sites (actions, context menu, Lua, settings persist+reload,
    /// schedule, OS auto-switch) without each needing to remember a call.
    /// `ws` is the checked-out window (see the `windows` field contract);
    /// the map holds only the others during dispatch.
    fn maybe_sync_native_theme(&mut self, ws: &mut WindowState) {
        let hint = self.native_theme_hint();
        // Tracked per window, not once for the process: on macOS a window can
        // only take the hint after AppKit has built its caption, so windows
        // reach that point at different times and a window opened later still
        // has to be told. See `native_theme_sync_is_due`.
        for state in std::iter::once(&mut *ws).chain(self.windows.values_mut()) {
            let Some(w) = state.window.as_ref() else {
                continue;
            };
            if state.native_theme_synced == Some(hint)
                || !native_theme_sync_is_due(
                    state.window_shown && w.has_focus(),
                    state.native_theme_synced.is_some(),
                    cfg!(target_os = "macos"),
                )
            {
                continue;
            }
            w.set_theme(hint);
            state.native_theme_synced = Some(hint);
        }
        let icon_dark = self.cfg.theme.is_dark();
        if self.window_icon_dark_synced != Some(icon_dark) {
            self.window_icon_dark_synced = Some(icon_dark);
            let icon = load_window_icon(icon_dark);
            for w in std::iter::once(&*ws)
                .chain(self.windows.values())
                .filter_map(|s| s.window.as_ref())
            {
                w.set_window_icon(icon.clone());
            }
        }
    }

    /// Tell every window's panes when the theme's colours changed, so a program
    /// following DEC mode 2031 (Claude Code's automatic theme) re-reads the
    /// background. Like `maybe_sync_native_theme`, it runs at every redraw and
    /// every theme mutation ends in one, so no mutation path (actions, menu
    /// previews, Lua, reload, schedule, OS appearance) needs its own call; it
    /// only compares when nothing changed. Hidden windows are synced too,
    /// since their programs still run.
    fn maybe_sync_color_scheme(&mut self, ws: &mut WindowState) {
        let scheme = (self.cfg.theme.is_dark(), self.cfg.theme.background);
        for state in std::iter::once(&mut *ws).chain(self.windows.values_mut()) {
            if state.color_scheme_synced != Some(scheme) {
                state.color_scheme_synced = Some(scheme);
                state.mux.set_color_scheme(Some(scheme.0));
            }
        }
    }

    /// Tear this window down for good: flush the recording, save the session,
    /// and flag the close for `finish_window_dispatch`.
    ///
    /// Every window-close path ends here, whether the user was asked first or
    /// not, so no gesture can close the window without flushing the PTY output
    /// still in flight. (`Drop for App` still finishes the recorder as a
    /// backstop for crashes; it cannot do this fan-out, because by then there
    /// is no window to fan out from.)
    fn close_window_now(&mut self, ws: &mut WindowState, drop_panes: DropPanes) {
        // Fan out in-flight shared PTY output, then hand finalization to
        // the writer before exit. Finalization can drain recorder events
        // already admitted; it cannot pull the shared sidechannel or
        // deliver its tail to Lua.
        //
        // This MUST run before anything drops panes: the flush walks
        // `ws.mux.panes` and reads each one's output sidechannel, so a caller
        // that cleared the mux first handed it an empty map and lost the whole
        // tail. `DropPanes` is why the clearing lives here rather than at the
        // call sites — the order is the point.
        self.flush_recorder_output(ws);
        // The recorder spans the whole session, so finish it only when the LAST
        // window goes (this one is checked out of the map, so empty == last).
        if self.windows.is_empty()
            && let Some(rec) = self.recorder.as_mut()
        {
            // The process may be leaving, but a vanished mount must still not
            // park winit inside a final flush or close.
            rec.begin_finish();
        }
        if drop_panes == DropPanes::Yes {
            // `close_window` means "this window is finished, do not bring it
            // back": clear the mux so the session saved below is the empty
            // one. Otherwise the multi-tab state from before the close stays
            // in session.json and silently restores on next launch.
            ws.mux.close_window();
        }
        self.save_session(ws);
        self.request_window_close(ws.seq);
    }

    /// Raise the `ask-before-closing` prompt if the policy calls for one.
    ///
    /// Returns `true` when the prompt is up and the caller must abandon its
    /// close, `false` when the close should go ahead untouched. Every close
    /// ACTION routes through here so none of them can drift out of step: the
    /// tab-bar ✕, middle-click, and the three close actions all ask the same
    /// question the same way.
    ///
    /// The titlebar ✕ and Alt+F4 are the exception. They are OS window-destroy
    /// requests rather than Kettle commands, so `WindowEvent::CloseRequested`
    /// reaches this only under `ask-before-closing = always`.
    fn confirm_close(
        &mut self,
        ws: &mut WindowState,
        prompt: String,
        scope: usize,
        busy: usize,
        on_confirm: ConfirmAction,
    ) -> bool {
        // The two questions are deliberately separate. `busy == 0` is the
        // all-idle skip — nothing is running, so there is nothing to lose and
        // no reason to interrupt. The single-vs-multiple decision then uses
        // the TOTAL scope, not the busy count, so a 3-pane tab with one busy
        // pane still prompts under `multiple-terminals` instead of silently
        // taking all three.
        if busy == 0 || !self.cfg.ask_before_closing.should_prompt(scope) {
            return false;
        }
        self.close_all_modals(ws);
        self.install_confirm_dialog(
            ws,
            ConfirmDialogState {
                prompt,
                buttons: vec![
                    ConfirmButton::Cancel,
                    ConfirmButton::Confirm {
                        label: self
                            .ui_text
                            .text(kettle_i18n::Text::ConfirmButtonClose)
                            .to_string(),
                        destructive: true,
                    },
                ],
                focus_idx: 0, // Cancel — safe default.
                on_confirm,
            },
        );
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        true
    }

    /// Phase 5 of [`TERMINATOR-CONFIRM-DIALOG-DESIGN.md`](
    /// ../../../docs/TERMINATOR-CONFIRM-DIALOG-DESIGN.md): dispatch
    /// the `ConfirmAction` after the user accepts the modal. Skips
    /// the `should_prompt` check (we wouldn't be here otherwise) so
    /// the close-family actions run their real bodies.
    fn dispatch_confirm_action(
        &mut self,
        ws: &mut WindowState,
        action: ConfirmAction,
        // Closes route through the window-scoped pending set, so the loop
        // handle is unused. It stays so the dispatch signature matches the
        // other key handlers.
        _event_loop: &winit::event_loop::ActiveEventLoop,
    ) {
        self.dispatch_confirm_action_arms(ws, action);
        self.hoover_groups(ws);
        // Resize, as `handle_action`'s tail does for every keybind and menu
        // action. A confirmed pane or tab close collapses the layout, and
        // without this the surviving PTYs keep their old rows and columns, so
        // the shell draws into part of its pane with dead space around it and
        // typing does not heal it.
        //
        // It lives here rather than in the arms so a new arm cannot forget it.
        // A window on its way out has nothing left to resize.
        if !self.window_close_pending(ws.seq) {
            self.resize_all(ws);
        }
    }

    fn cancel_confirm_dialog(&mut self, ws: &mut WindowState) {
        ws.confirm_dialog = None;
    }

    fn dispatch_confirm_action_arms(&mut self, ws: &mut WindowState, action: ConfirmAction) {
        match action {
            ConfirmAction::CloseWindow { drop_panes } => {
                // Carries the requester's intent: confirming a `close_window`
                // action must still clear the session, and confirming a
                // titlebar close must still leave it restorable. Without this
                // the answer depended on whether the prompt happened to
                // appear.
                self.close_window_now(ws, drop_panes);
            }
            ConfirmAction::CloseTabHolding(panes) => {
                // Re-resolve the tab now: the prompt may have been on screen
                // for a while, and an exiting shell can drop a tab and shift
                // every index after it. `None` means the tab this prompt was
                // about is already gone, so there is nothing left to close.
                let Some(idx) = ws.mux.tab_index_of_any_pane(&panes) else {
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                };
                let last = ws.mux.close_tab_at(idx);
                self.fire_tab_close_event(ws, idx);
                self.save_session(ws);
                if last {
                    self.request_window_close(ws.seq);
                    return;
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            ConfirmAction::ClosePane(target) => {
                // Close the pane the PROMPT was about, not whatever happens to
                // be focused now. While the prompt was up the target's own
                // shell may have exited and promoted a sibling into focus —
                // confirming then closed the sibling, which can be a tmux or
                // agent session the user never selected. A target that is
                // already gone means there is nothing left to close.
                // Re-focusing the target moves the ACTIVE TAB to wherever it
                // lives. If the user changed tabs while the prompt was up (the
                // ctl API can, even with a modal on screen), snapping them back
                // to the closed pane's tab is not something they asked for —
                // so remember where they were and put them back.
                let viewing = ws.mux.tab_anchor_panes(ws.mux.active);
                if !ws.mux.focus_pane(target) {
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                self.fire_pane_close_event(ws, target);
                let was_last = ws.mux.close_focused();
                // Resolve the viewed tab again after a removal shifts indices.
                if let Some(viewing) = ws.mux.tab_index_of_any_pane(&viewing) {
                    ws.mux.active = viewing;
                }
                // Honor close_focused()'s return like the
                // keybind ClosePane path — `true` means the last pane closed,
                // so exit; otherwise redraw the collapsed layout (the renderer
                // cache + focus id are stale until a frame is scheduled).
                if was_last {
                    self.save_session(ws);
                    self.request_window_close(ws.seq);
                    return;
                }
                self.save_session(ws);
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            ConfirmAction::RebindKeybind {
                trig,
                act,
                action_name,
            } => {
                self.apply_keybind_rebind(trig, act, action_name);
            }
        }
    }

    /// Phase 6 of [`TERMINATOR-REMOTE-DESIGN.md`](
    /// ../../../docs/TERMINATOR-REMOTE-DESIGN.md): periodic poll of
    /// every pane's process tree to detect SSH / Docker / Podman / kubectl
    /// sessions. Throttled to ~5 Hz; submissions overwrite an older queued
    /// request and the bounded scan runs entirely on its worker. A skipped
    /// poll still runs when the window ends, so the last `cd` is always seen.
    ///
    /// When the worker's snapshot shows a new or changed detection, the
    /// pane's title becomes `format_remote_title(...)`. When the detection
    /// ends (SSH exited), the title from before the remote session is
    /// restored.
    fn poll_remote_contexts(&mut self, ws: &mut WindowState) {
        let Some(worker) = self.remote_scan_worker.as_ref() else {
            return;
        };
        let now = std::time::Instant::now();
        if let Some(due) = remote_poll_deferred_until(self.last_remote_poll, now) {
            self.remote_poll_due = Some(due);
            return;
        }
        self.last_remote_poll = Some(now);
        self.remote_poll_due = None;
        stage_remote_targets(
            &mut self.remote_targets_scratch,
            ws.mux.panes.values().map(remote_probe_target),
            self.windows
                .values()
                .flat_map(|window| window.mux.panes.values())
                .map(remote_probe_target),
        );
        worker.submit(self.remote_targets_scratch.clone());
    }

    fn apply_remote_scan_snapshot(&mut self, ws: &mut WindowState) {
        let Some(snapshot) = self
            .remote_scan_worker
            .as_ref()
            .and_then(kettle_remote::RemoteScanWorker::take_latest)
        else {
            return;
        };
        self.remote_live_panes_scratch.clear();
        self.remote_live_panes_scratch
            .extend(ws.mux.panes.keys().copied());
        self.remote_live_panes_scratch.extend(
            self.windows
                .values()
                .flat_map(|window| window.mux.panes.keys())
                .copied(),
        );
        let live_panes = &self.remote_live_panes_scratch;
        self.remote_applied.retain(|(pane_id, pid), _| {
            live_panes.contains(pane_id) && snapshot.probes.contains_key(pid)
        });

        if update_window_remote_contexts(&snapshot, &mut self.remote_applied, ws) {
            ws.reuse_pane_snapshots_once = false;
            self.sync_window_title(ws);
            self.poll_title_event(ws);
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }

        // `ws` is checked out of this map. Temporarily take the remaining map
        // so title synchronization can borrow the rest of App without aliasing.
        let mut stored_windows = std::mem::take(&mut self.windows);
        for window in stored_windows.values_mut() {
            if update_window_remote_contexts(&snapshot, &mut self.remote_applied, window) {
                window.reuse_pane_snapshots_once = false;
                self.sync_window_title(window);
                self.poll_title_event(window);
                if let Some(handle) = &window.window {
                    handle.request_redraw();
                }
            }
        }
        self.windows = stored_windows;
    }

    /// Read and install the process-wide portion of a live configuration once.
    /// Returns whether the configured font size changed, which controls whether
    /// each window keeps its session-local zoom.
    fn load_reloaded_config(&mut self) -> bool {
        let previous_config_font_size = self.cfg.font_size;
        let path = self
            .config_path
            .clone()
            .or_else(Config::default_path)
            .filter(|path| path.exists());
        let (mut new, malformed) = match path {
            Some(path) => match prepare_config_directory(&path, self.config_trust)
                .and_then(|()| Config::read_from_with_trust(&path, self.config_trust))
            {
                Ok(loaded) => {
                    if !loaded.unknown_keys.is_empty() {
                        log::warn!(
                            "{}: unrecognized config keys: {}",
                            path.display(),
                            loaded.unknown_keys.join(", ")
                        );
                    }
                    (loaded.config, loaded.malformed_values)
                }
                Err(error) => {
                    log::warn!("config reload refused for {}: {error}", path.display());
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleConfigReloadRefused),
                        &self.ui_text.notify_body_config_reload_refused(
                            &path.display().to_string(),
                            &error.to_string(),
                        ),
                    );
                    return false;
                }
            },
            None => (Config::default(), Vec::new()),
        };
        // Surface malformed values (typos the parser silently ignores, e.g.
        // `cursor-style = beem`) on live reload. `--check-config` already
        // catches these at the CLI, but a live edit otherwise reverted with no
        // feedback. Edge-triggered via `should_notify_malformed` so kettle's
        // own settings-persistence writes don't spam an unchanged warning.
        if should_notify_malformed(&malformed, &self.config_malformed_last) {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleConfigValuesIgnored),
                &self
                    .ui_text
                    .notify_body_config_values_ignored(&malformed.join("\n")),
            );
        }
        self.config_malformed_last = malformed;
        // Re-compile triggers from the freshly-loaded config
        // BEFORE assigning, while `new` is still owned. Recompile
        // catches added/removed/changed patterns. Clearing the throttle stamp
        // lets a fresh edit fire immediately even mid-throttle.
        self.compiled_triggers = compile_triggers(&new.triggers);
        self.last_trigger_fire = None;
        // The accent seed is a runtime per-window value (not in the
        // config file), so carry it across a reload + re-apply the --accent
        // override (launch-time intent survives a reload).
        new.accent_seed = self.cfg.accent_seed;
        if let Some(rgb) = self.startup.accent_override {
            new.accent_color = Some(rgb);
        }
        // The launch-time window flags are launch-time intent too. Without
        // re-applying them, any live reload (including kettle's own
        // theme/settings persistence writes) would revert a `-T` pinned title
        // to `window-title-format` and drop the -m/-f/-H/-b overrides from
        // `self.cfg`, which save_session and future window ops read.
        if let Some(wstate) = self.startup.window_state_override {
            new.window_state = wstate;
        }
        if let Some(b) = self.startup.borderless_override {
            new.borderless = b;
        }
        if let Some(title) = self.startup.title_override.clone() {
            new.window_title_format = title;
        }
        let font_size_changed = (new.font_size - previous_config_font_size).abs() > f32::EPSILON;
        self.cfg = new;
        self.reconcile_agent_display();
        self.reconcile_claude_plugin();
        self.reconcile_codex_shell();
        crate::dev_record::apply_retention_config(&self.cfg);
        self.sync_lua_active_theme();
        font_size_changed
    }

    fn apply_reloaded_config(&mut self, ws: &mut WindowState, font_size_changed: bool) {
        // A config change, including a Settings edit or a menu toggle, is
        // activity: a new blink or timeout value takes effect visibly now.
        self.reset_blink_phase(ws);
        if !self.cfg.macos_cursor_blink_layer && !ws.blink_layer.is_active() {
            Self::retire_cursor_layer(ws);
        }
        #[cfg(target_os = "macos")]
        {
            refresh_macos_modifiers(ws, self.cfg.macos_option_as_alt);
            if let Some(window) = &ws.window {
                set_macos_option_as_alt(window, self.cfg.macos_option_as_alt);
            }
        }
        ws.mux.set_osc52_copy_allowed(osc52_copy_is_available(
            self.cfg.osc52,
            self.clipboard.is_some(),
        ));
        ws.mux
            .set_unnegotiated_modified_enter(self.cfg.modify_other_keys);
        ws.mux.autoclean_groups = self.cfg.autoclean_groups;
        // Push `scrollback` and `scrollback-bytes` edits (config file or
        // Settings rows) into live panes too; otherwise only panes opened
        // afterwards would use them.
        ws.mux
            .set_scrollback_limits(self.cfg.scrollback, self.cfg.scrollback_bytes);
        let runtime_font_size = ws.renderer.as_ref().map(|r| r.font_size());
        if let Some(r) = ws.renderer.as_mut() {
            // Family first: the font-size setter re-measures cells and must see
            // the new family. All setters are no-ops when unchanged.
            r.set_font_family(self.cfg.font_family.clone());
            r.set_font_size(reloaded_font_size(
                font_size_changed,
                self.cfg.font_size,
                runtime_font_size,
            ));
            r.set_cell_scale(self.cfg.cell_width, self.cfg.cell_height);
            r.set_background_compositing(&self.cfg);
        }
        // A configured size change invalidates the pre-scaled-zoom baseline;
        // a no-op reload must preserve both it and the live runtime zoom.
        if font_size_changed {
            ws.scaled_zoom_prev_font_size = None;
        }
        self.resize_all(ws);
        let direction_changed = sync_reloaded_search_preferences(
            &mut ws.search,
            self.cfg.search_wrap,
            self.cfg.search_case_sensitive,
            self.cfg.invert_search,
            std::time::Instant::now(),
        );
        if direction_changed
            && let Some(pane_id) = ws.search.target_pane
            && let Some(pane) = ws.mux.panes.get(&pane_id)
            && let Ok(term) = pane.term.term.lock()
        {
            use kettle_core::Dimensions as _;
            let direction = if ws.search.invert {
                kettle_core::SearchDirection::Reverse
            } else {
                kettle_core::SearchDirection::Forward
            };
            ws.search.anchor = Some(search_viewport_anchor(
                term.grid().display_offset(),
                term.screen_lines(),
                term.last_column().0,
                direction,
            ));
        }
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Immediate manual reload. The addressed window is checked out of the
    /// map by the dispatch wrapper, so update it plus every mapped sibling.
    fn reload_config(&mut self, ws: &mut WindowState) {
        let font_size_changed = self.load_reloaded_config();
        self.apply_reloaded_config(ws, font_size_changed);
        let seqs: Vec<u64> = self.windows.keys().copied().collect();
        for seq in seqs {
            if let Some(mut sibling) = self.windows.remove(&seq) {
                self.apply_reloaded_config(&mut sibling, font_size_changed);
                self.windows.insert(seq, sibling);
            }
        }
        log::debug!(
            "config reload applied once across {} windows",
            self.windows.len() + 1
        );
    }

    /// Debounced watcher reload when every window is still in the map.
    fn reload_config_windows(&mut self) {
        let font_size_changed = self.load_reloaded_config();
        let seqs: Vec<u64> = self.windows.keys().copied().collect();
        for seq in &seqs {
            if let Some(mut ws) = self.windows.remove(seq) {
                self.apply_reloaded_config(&mut ws, font_size_changed);
                self.windows.insert(*seq, ws);
            }
        }
        log::debug!("config reload applied once across {} windows", seqs.len());
    }

    /// The Agent previews row's footer note for the current state.
    fn agent_previews_note(&self) -> kettle_i18n::Text {
        let turned_on = self.cfg.ctl_policy().with_display();
        agent_previews_note(
            self.cfg.agent_display,
            self.ctl_policy,
            ctl_overrides(&self.startup).resolve(turned_on).display(),
            self.ctl.is_some(),
            self.ctl_start == CtlStart::Attempted,
        )
    }

    /// Whether agent previews are on now and stay on: granted to this
    /// process and still asked for. Turning them off reaches the server at
    /// the next launch, but new panes stop getting the plugin at once.
    fn agent_previews_live(&self) -> bool {
        self.ctl_policy.display()
            && ctl_overrides(&self.startup)
                .resolve(self.cfg.ctl_policy())
                .display()
    }

    /// Offer new panes Kettle's Claude Code plugin while agent previews and
    /// the Claude Code integration are both on, writing it if needed; panes
    /// already open keep what they started with.
    fn reconcile_claude_plugin(&mut self) {
        if !(self.agent_previews_live() && self.cfg.agent_display_claude_code) {
            crate::agent_plugin::offer(None, None);
            return;
        }
        let prepared = std::env::current_exe()
            .and_then(std::fs::canonicalize)
            .map_err(|_| crate::agent_plugin::PluginRefusal::UnnamedExecutable)
            .and_then(|executable| {
                crate::agent_plugin::PluginFiles::new(&executable, env!("CARGO_PKG_VERSION"))
            })
            .and_then(|files| {
                let root = crate::agent_plugin::plugins_root()
                    .ok_or(crate::agent_plugin::PluginRefusal::Unverified)?;
                crate::agent_plugin::install(&root, &files).map(|directory| (directory, files))
            })
            .and_then(|(directory, files)| {
                crate::agent_plugin::plugin_dir_entry(&directory)
                    .ok_or(crate::agent_plugin::PluginRefusal::UnnamedDirectory)?;
                Ok((directory, files))
            });
        match prepared {
            Ok(plugin) => {
                crate::agent_plugin::offer(Some(plugin), None);
                // Check now, as for a new pane with the configured `env`, so
                // Settings names a policy that forbids the plugin before the
                // next pane opens.
                let _ = crate::agent_plugin::for_new_pane(|| {
                    crate::mux::claude_config_for(&self.cfg.env)
                });
            }
            Err(refusal) => {
                log::warn!("agent previews: the Claude Code plugin is unavailable ({refusal:?})");
                crate::agent_plugin::offer(None, Some(refusal));
            }
        }
    }

    /// Prepare enabled agent functions for new panes. Existing panes keep
    /// their startup, and user-defined functions always win.
    fn reconcile_codex_shell(&mut self) {
        let agents = crate::codex_shell::Agents {
            codex: self.cfg.agent_display_codex,
            claude: cfg!(target_os = "linux") && self.cfg.agent_display_claude_code,
        };
        if !self.agent_previews_live() || !(agents.codex || agents.claude) {
            crate::codex_shell::offer(None, None);
            return;
        }
        if cfg!(not(unix)) {
            crate::codex_shell::offer(None, Some(crate::codex_shell::ShellRefusal::Unsupported));
            return;
        }
        let prepared = std::env::current_exe()
            .and_then(std::fs::canonicalize)
            .map_err(|_| crate::codex_shell::ShellRefusal::Unavailable)
            .and_then(|executable| {
                let root = crate::codex_shell::startup_root()
                    .ok_or(crate::codex_shell::ShellRefusal::Unavailable)?;
                crate::codex_shell::prepare(&root, &executable, env!("CARGO_PKG_VERSION"), agents)
            });
        match prepared {
            Ok(offered) => crate::codex_shell::offer(Some(offered), None),
            Err(refusal) => {
                log::warn!("agent previews: shell integration is unavailable ({refusal:?})");
                crate::codex_shell::offer(None, Some(refusal));
            }
        }
    }

    /// Start the control server if the policy allows anything, the first pane
    /// exists, and no start has been tried. A failed start is logged and not
    /// retried by unrelated reloads.
    fn ensure_ctl_started(&mut self) {
        if self.ctl_start != CtlStart::Ready || self.ctl.is_some() || !self.ctl_policy.runs_server()
        {
            return;
        }
        self.ctl_start = CtlStart::Attempted;
        let proxy = self.proxy.clone();
        let wake: std::sync::Arc<dyn Fn() + Send + Sync> = std::sync::Arc::new(move || {
            let _ = proxy.send_event(UserEvent::Ctl);
        });
        let started_unix = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        self.ctl = crate::ctl_server::CtlServer::start(
            self.ctl_policy,
            std::process::id(),
            env!("CARGO_PKG_VERSION"),
            started_unix,
            wake,
        );
    }

    /// Apply a reloaded `agent-display`. Turning display on takes effect at
    /// once, for open connections too, and starts the server if none runs;
    /// turning it off waits for the next launch. Launch flags keep their
    /// precedence, and `agent-server` changes wait for the next launch.
    fn reconcile_agent_display(&mut self) {
        let requested = ctl_overrides(&self.startup).resolve(self.cfg.ctl_policy());
        let Some(widened) = self.ctl_policy.latch_display(requested.display()) else {
            return;
        };
        self.ctl_policy = widened;
        log::info!("agent-server: agent previews turned on");
        match &self.ctl {
            Some(ctl) => ctl.enable_display(),
            None => {
                // Display is a new grant, so it earns one more start attempt
                // even if an earlier one failed. The latch makes this happen
                // at most once per process.
                if self.ctl_start == CtlStart::Attempted {
                    self.ctl_start = CtlStart::Ready;
                }
                self.ensure_ctl_started();
            }
        }
    }

    /// Scan every pane's recent output for configured
    /// trigger patterns. On the first match in this tick, raise the
    /// OS window's attention indicator (taskbar flash / dock bounce
    /// / WM_HINTS urgency) — but only if the window isn't focused,
    /// AND throttle to one fire per 2 seconds so a build script
    /// printing 100 error lines doesn't pulse the taskbar 100×.
    /// Agent-first A2: drain the control-server channel and
    /// dispatch each message on the main thread (the only place `ws.mux` is
    /// touched). Mirrors `drain_remote_commands` but with per-connection
    /// replies + a connection table.
    fn drain_ctl(&mut self, ws: &mut WindowState, event_loop: &ActiveEventLoop) {
        use crate::ctl_server::CtlServerMsg;
        // Pull all pending messages first so we don't hold a `&self.ctl` borrow
        // while calling `&mut self` handlers.
        let mut msgs = Vec::new();
        if let Some(ctl) = &self.ctl {
            while let Some(m) = ctl.try_recv() {
                msgs.push(m);
            }
        }
        if msgs.is_empty() {
            return;
        }
        // Only repaint when the batch could have changed visible state.
        // `wait_for` probes are pure reads arriving at up to 20/s for the
        // whole wait, and repainting an idle window for each one wastes CPU.
        let mut needs_redraw = false;
        for msg in msgs {
            match msg {
                CtlServerMsg::NewConn { conn_id, event_tx } => {
                    if let Some(ctl) = &mut self.ctl {
                        ctl.add_conn(conn_id, event_tx);
                    }
                    log::info!("agent-server: connection {conn_id} opened");
                }
                CtlServerMsg::Request {
                    conn_id,
                    request,
                    reply,
                } => {
                    // Mutations + first-time attaches change visible state
                    // (pane content, agent badge); wait_for's internal
                    // probes and `ui_geometry` reads never do.
                    if !request.internal_probe() && !ctl_method_is_pure_read(request.method()) {
                        needs_redraw = true;
                    }
                    // Nothing a control client drives stands for the user's
                    // own gesture (see `pull_preview`).
                    self.ctl_driving = true;
                    self.handle_ctl_request(ws, event_loop, conn_id, *request, reply);
                    self.ctl_driving = false;
                }
                CtlServerMsg::Disconnect { conn_id } => {
                    let panes = self
                        .ctl
                        .as_mut()
                        .map(|c| c.remove_conn(conn_id))
                        .unwrap_or_default();
                    // Only a connection that held panes can clear a badge.
                    needs_redraw |= !panes.is_empty();
                    // Clear the agent badge for panes no connection holds now.
                    for pane in panes {
                        let still = self
                            .ctl
                            .as_ref()
                            .map(|c| c.pane_is_attached(pane))
                            .unwrap_or(false);
                        if !still {
                            self.set_pane_agent_attached(ws, pane, false);
                        }
                    }
                    // Drop any pending run owned by this connection.
                    self.pending_runs
                        .retain(|_, p: &mut PendingRun| p.conn_id != conn_id);
                    // Its `show` pushes are no longer wanted.
                    self.media.disconnected(conn_id);
                    log::info!("agent-server: connection {conn_id} closed");
                }
            }
        }
        if needs_redraw && let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Dispatch one control request against the App and reply over `reply`.
    /// Most methods reply immediately; `run_command` stores `reply` and resolves
    /// it later (OSC-133 completion or the deadline).
    ///
    /// The request was admitted on its connection thread: the policy allowed
    /// its method and its params are an object or absent.
    fn handle_ctl_request(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        conn_id: u64,
        mut request: crate::ctl_server::AdmittedRequest,
        reply: crate::ctl_server::ReplyTx,
    ) {
        use kettle_ctl::protocol::{Method, Response, error_codes as ec};
        let req = request.request();
        let method = request.method();
        // Annotate the session trace with each agent action when recording
        // (cheap; only when a recorder is active). Skip wait_for's internal
        // read_screen probes, since a 300s wait at 50ms polls would add ~6000
        // markers. The client's own calls already show the wait.
        if !request.internal_probe()
            && let Some(rec) = self.recorder.as_mut()
        {
            rec.record_marker(&format!("kettle:agent {} conn={conn_id}", method.as_str()));
        }
        let resp = match method {
            Method::GetState => {
                let policy = self.ctl.as_ref().map(|c| c.policy()).unwrap_or_default();
                Response::ok(req.id, self.ctl_get_state(ws, policy, request.caller()))
            }
            Method::ListTabs => self.ctl_list_tabs(ws, req),
            Method::ListPanes => self.ctl_list_panes(ws, req),
            Method::ReadScreen => self.ctl_read_screen(ws, req),
            Method::ReadCells => self.ctl_read_cells(ws, req),
            Method::UiGeometry => self.ctl_ui_geometry(ws, req),
            Method::Screenshot => {
                self.ctl_screenshot(ws, req, reply);
                return;
            }
            Method::Subscribe => {
                if let Some(c) = &mut self.ctl {
                    c.set_subscribed(conn_id);
                }
                Response::ok(req.id, serde_json::json!({"subscribed": true}))
            }
            Method::SendText => self.ctl_send_text(ws, conn_id, req),
            Method::SendKeys => self.ctl_send_keys(ws, conn_id, req),
            Method::DispatchUiKey => self.ctl_dispatch_ui_key(ws, event_loop, req),
            Method::DispatchKeybind => self.ctl_dispatch_keybind(ws, event_loop, req),
            Method::SendMouse => self.ctl_send_mouse(ws, event_loop, req),
            Method::ResizeWindow => self.ctl_resize_window(ws, req),
            Method::PerformAction => self.ctl_perform_action(ws, event_loop, req),
            Method::RunCommand => {
                // Deferred: store `reply`; resolved on completion/deadline.
                self.ctl_run_command(ws, conn_id, req, reply);
                return;
            }
            Method::WaitFor => {
                Response::err(req.id, ec::INTERNAL, "wait_for was routed to the UI thread")
            }
            Method::AgentLaunch | Method::CardPickup => self.ctl_agent_request(ws, &mut request),
            Method::Show => {
                // Deferred: answered once the item is on its shelf.
                self.ctl_show(ws, conn_id, &mut request, reply);
                return;
            }
        };
        let _ = reply.send(resp);
    }

    fn ctl_agent_request(
        &mut self,
        ws: &WindowState,
        request: &mut crate::ctl_server::AdmittedRequest,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let id = request.request().id;
        let refused =
            || Response::err(id, ec::BAD_PARAMS, "launch-scoped card request was refused");
        #[cfg(not(target_os = "linux"))]
        {
            let _ = ws;
            refused()
        }
        #[cfg(target_os = "linux")]
        {
            use crate::ctl_server::AgentAdmission;
            let Some(admission) = request.take_agent() else {
                return refused();
            };
            match admission {
                AgentAdmission::Launch { root, files } => {
                    let Some(chain) = request.caller().chain().and_then(Result::ok) else {
                        return refused();
                    };
                    if chain.first() != Some(&root) {
                        return refused();
                    }
                    let (roots, _) = self.caller_roots(ws);
                    let Some((pane, _)) = crate::media::nearest_pane(chain, &roots) else {
                        return refused();
                    };
                    let Some(pane_root) = roots
                        .iter()
                        .find(|entry| entry.pane == pane)
                        .map(|entry| entry.root)
                    else {
                        return refused();
                    };
                    if !self.agent_launches.register(
                        root,
                        pane,
                        pane_root,
                        files,
                        std::time::Instant::now(),
                    ) {
                        return refused();
                    }
                    Response::ok(id, serde_json::json!({"enabled": true}))
                }
                AgentAdmission::Pickup {
                    sender,
                    request: pickup,
                } => {
                    let live = self
                        .scoped_card_caller(ws, request.caller(), &sender, pickup.target)
                        .is_some_and(|caller| {
                            self.agent_launches.redeem(
                                pickup.permit,
                                caller,
                                std::time::Instant::now(),
                            )
                        });
                    Response::ok(id, serde_json::json!({"live": live}))
                }
            }
        }
    }

    #[cfg(target_os = "linux")]
    fn scoped_card_caller<'a>(
        &self,
        ws: &WindowState,
        evidence: &'a crate::ctl_server::CallerEvidence,
        sender: &crate::ctl_server::SenderIdentity,
        target: kettle_ctl::show::InlineTarget,
    ) -> Option<kettle_ctl::agent_launch::CardCaller<'a>> {
        let chain = evidence.chain()?.ok()?;
        let owner = sender.asker.process;
        if owner == sender.process
            || chain.first() != Some(&sender.process)
            || chain.get(1) != Some(&owner)
        {
            return None;
        }
        let (roots, _) = self.caller_roots(ws);
        let (pane, _) = crate::media::nearest_pane(chain, &roots)?;
        let pane_root = roots.iter().find(|entry| entry.pane == pane)?.root;
        Some(kettle_ctl::agent_launch::CardCaller {
            target,
            owner,
            chain,
            pane,
            pane_root,
        })
    }

    /// `show`: route the push to its caller's pane, queue its render, and
    /// answer once its item is on that pane's shelf (see [`crate::media`]).
    fn ctl_show(
        &mut self,
        ws: &mut WindowState,
        conn_id: u64,
        request: &mut crate::ctl_server::AdmittedRequest,
        reply: crate::ctl_server::ReplyTx,
    ) {
        use kettle_media::FailureCode;
        let id = request.request().id;
        let refuse = |failure: FailureCode| {
            let _ = reply.send(kettle_ctl::show::show_failure(id, failure));
        };
        let Some(crate::ctl_server::ShowAdmission {
            request: show,
            sender,
            harness,
        }) = request.take_show()
        else {
            refuse(FailureCode::BadParams);
            return;
        };
        if let Some(failure) = media_unavailable(self.startup.media.as_deref()) {
            refuse(failure);
            return;
        }
        let full_control = self.ctl.as_ref().is_some_and(|ctl| {
            ctl.policy()
                .allows(kettle_ctl::protocol::Capability::Mutate)
        });
        let (roots, _) = self.caller_roots(ws);
        let live: Vec<(u64, u64)> = self
            .all_windows(ws)
            .flat_map(|window| {
                window
                    .mux
                    .panes
                    .iter()
                    .filter(|(_, pane)| !pane.closed && !pane.held)
                    .map(move |(&pane, _)| (pane, window.seq))
            })
            .collect();
        let route = match crate::media::route(
            request.caller(),
            show.pane,
            full_control,
            &roots,
            &live,
            std::process::id(),
        ) {
            Ok(route) => route,
            Err(failure) => {
                refuse(failure);
                return;
            }
        };
        #[cfg(target_os = "linux")]
        let _ = harness;
        #[cfg(target_os = "linux")]
        let native_grant = show
            .inline
            .zip(sender.as_ref())
            .and_then(|(target, sender)| {
                let caller = self.scoped_card_caller(ws, request.caller(), sender, target)?;
                self.agent_launches.grant(caller, std::time::Instant::now())
            });
        #[cfg(target_os = "linux")]
        let harness = native_grant.as_ref().map(|grant| grant.owner());
        // An unverified push counts against its sending process; one whose
        // sender the kernel could not name has no one to count against or
        // to show as its sender.
        let (sender, provenance) = match (route.verified, sender) {
            (true, _) => (
                crate::media::Sender::Pane(route.pane),
                crate::media::Provenance::Verified,
            ),
            // A script that runs `kettle show` many times is one sender: the
            // program that asked, not each command line it ran.
            (false, Some(sender)) => {
                let asker = sender.asker;
                (
                    crate::media::Sender::Process(asker.process),
                    crate::media::Provenance::Unverified(crate::media::UnverifiedSender {
                        executable: asker
                            .executable
                            .map(|path| crate::media::display_title(&path.to_string_lossy())),
                        pid: asker.process.pid(),
                        signer: asker.signature.as_ref().map(|signature| {
                            crate::media::display_title(&crate::media::signer_name(signature))
                        }),
                    }),
                )
            }
            (false, None) => {
                refuse(FailureCode::NotInKettlePane);
                return;
            }
        };
        let Some((theme, target)) = self.media_surface(ws, route.pane) else {
            refuse(FailureCode::NotInKettlePane);
            return;
        };
        let kettle_ctl::show::ShowRequest {
            source,
            title,
            key,
            inline,
            ..
        } = show;
        let kind = source.job_kind();
        let (source, file_name) = match source {
            kettle_ctl::show::ShowSource::Svg(text) => {
                (kettle_media::Source::Bytes(text.into_bytes()), None)
            }
            kettle_ctl::show::ShowSource::Image(bytes) => {
                (kettle_media::Source::Bytes(bytes), None)
            }
            kettle_ctl::show::ShowSource::Mermaid(text) => {
                (kettle_media::Source::Bytes(text.into_bytes()), None)
            }
            kettle_ctl::show::ShowSource::File {
                path, attestation, ..
            } => {
                let name = path.file_name_lossy();
                (
                    kettle_media::Source::Path {
                        path,
                        authorization: kettle_media::Authorization::ExternalAttested(attestation),
                    },
                    name,
                )
            }
        };
        // A file's key defaults to the file, so showing it again replaces it.
        let key = key
            .map(crate::media::ShelfKey::Explicit)
            .or_else(|| match &source {
                kettle_media::Source::Path { path, .. } => {
                    Some(crate::media::ShelfKey::Path(path.clone()))
                }
                kettle_media::Source::Bytes(_) => None,
            });
        let card_name = file_name.clone();
        let title = title
            .or(file_name)
            .map(|title| crate::media::display_title(&title))
            .filter(|title| !title.is_empty())
            .unwrap_or_else(|| {
                self.ui_text
                    .text(kettle_i18n::Text::MediaShelfUntitled)
                    .into()
            });
        // A card only for the harness Kettle checked, which runs in this very
        // pane; everyone else's push goes to the shelf alone.
        let inline = match (inline, harness) {
            (Some(target), Some(owner)) if route.verified => Some(crate::media::InlineDraft {
                #[cfg(target_os = "linux")]
                launch: native_grant,
                owner,
                harness: match target {
                    kettle_ctl::show::InlineTarget::ClaudeHook => {
                        kettle_render::CardHarness::ClaudeHook
                    }
                    kettle_ctl::show::InlineTarget::CodexHook => {
                        kettle_render::CardHarness::CodexHook
                    }
                },
                name: card_name,
            }),
            _ => None,
        };
        // The bytes a push carried are kept, charged, for the item to be
        // rendered again: no room for them is no room for the push.
        let Some(spec) = crate::media::JobSpec::from_job(kettle_media::Job {
            kind,
            source,
            theme,
            canvas: kettle_media::Canvas::Theme,
            target,
            fallback_fonts: Vec::new(),
        }) else {
            refuse(FailureCode::OverBudget);
            return;
        };
        let deadline = request.admitted_at() + kettle_ctl::show::SHOW_SERVER_DEADLINE;
        let push = crate::media::Push::new(
            crate::media::Requester::Ctl(crate::media::Origin {
                conn_id,
                request_id: id,
                reply,
            }),
            route,
            crate::media::Draft {
                key,
                title,
                provenance,
                inline,
                gallery: None,
            },
            spec,
            kettle_media::client::RenderControl::with_deadline(deadline),
        );
        self.media.admit(sender, deadline, push);
        self.media_tick(ws);
    }

    /// The theme and render target for media shown in `pane`: the pane's
    /// effective colors, and its window's size in device pixels.
    fn media_surface(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Option<(kettle_media::Theme, kettle_media::Target)> {
        let window = self
            .all_windows(ws)
            .find(|window| window.mux.panes.contains_key(&pane))?;
        let pane = window.mux.panes.get(&pane)?;
        let colors = pane.term.term.lock().ok().map(|term| *term.colors());
        let theme = &self.cfg.theme;
        let pick = |index: usize| {
            colors
                .as_ref()
                .and_then(|colors| kettle_render::resolve_query(index, theme, colors))
                .unwrap_or(match index {
                    256 => theme.foreground,
                    257 => theme.background,
                    _ => theme.palette[index.min(15)],
                })
        };
        let rgba = |color: kettle_config::Rgb| [color.r, color.g, color.b, 255];
        let background = pick(257);
        let media_theme = kettle_media::Theme {
            background: rgba(background),
            foreground: rgba(pick(256)),
            palette: std::array::from_fn(|index| rgba(pick(index))),
            accent: rgba(theme.accent),
            is_dark: kettle_render::relative_luminance(background) < 0.5,
        };
        let (width, height, scale) = window
            .window
            .as_ref()
            .map(|window| {
                let size = window.inner_size();
                (size.width, size.height, window.scale_factor())
            })
            .unwrap_or((1024, 768, 1.0));
        let edge = |value: u32| value.clamp(64, kettle_media::MAX_SVG_RENDERED_EDGE);
        let target = kettle_media::Target {
            width: edge(width),
            height: edge(height),
            scale: if scale.is_finite() && scale > 0.0 {
                scale
            } else {
                1.0
            },
            crop: None,
        };
        Some((media_theme, target))
    }

    /// Advance `show`: drop pushes whose pane is gone, publish finished
    /// renders, and start the next one.
    fn media_tick(&mut self, ws: &mut WindowState) {
        self.retire_cards(ws);
        self.tell_preview_failures(ws);
        if self.media.is_idle() {
            return;
        }
        let live: std::collections::HashSet<u64> = self
            .all_windows(ws)
            .flat_map(|window| {
                window
                    .mux
                    .panes
                    .iter()
                    .filter(|(_, pane)| !pane.closed && !pane.held)
                    .map(|(&pane, _)| pane)
            })
            .collect();
        self.media.retain_panes(|pane| live.contains(&pane));
        while let Some(finished) = self.media.take_finished() {
            self.finish_show(ws, finished);
        }
        let proxy = self.proxy.clone();
        self.media.pump(self.startup.media.as_ref(), move || {
            std::sync::Arc::new(move || {
                let _ = proxy.send_event(UserEvent::MediaRendered);
            })
        });
        self.tell_preview_failures(ws);
    }

    /// Tell the user about each preview they asked for that ended before
    /// it rendered: busy, unavailable, out of time.
    fn tell_preview_failures(&mut self, ws: &mut WindowState) {
        use crate::window_state::LaneNotice;
        let tr = self.ui_text;
        for (_, failure) in self.media.take_user_failures() {
            notify_preview_failure(tr, Some(failure));
        }
        // A lane's render that could not run, and each copy that ended, are
        // said in the lane that asked.
        for render in self.media.take_lane_failures() {
            // A preview that could not even start says so; the poster stays.
            if let Some(ticket) = render.preview {
                let failed = self
                    .window_by_seq(ws, render.window)
                    .and_then(|window| {
                        window
                            .lane_previews
                            .remove(&render.pane)
                            .filter(|preview| preview.waits_on() == Some(ticket))
                    })
                    .is_some();
                if failed {
                    self.tell_lane(
                        ws,
                        render.window,
                        render.pane,
                        render.item,
                        LaneNotice::PreviewFailed,
                    );
                }
                continue;
            }
            // Sharper pixels that could not be asked for leave the lane
            // showing its own, without a word.
            if let Some(ticket) = render.tile {
                if let Some(crop) = self
                    .window_by_seq(ws, render.window)
                    .and_then(|window| window.lane_crops.get_mut(&render.pane))
                    .filter(|crop| crop.asked == Some(ticket))
                {
                    crop.asked = None;
                }
                continue;
            }
            // A gallery page the lane no longer waits on goes unsaid.
            if !self.lane_wants(ws, &render) {
                continue;
            }
            self.forget_lane_page(ws, &render);
            self.tell_lane(
                ws,
                render.window,
                render.pane,
                render.item,
                LaneNotice::RenderFailed,
            );
        }
        let copies = self
            .preview_copy
            .as_ref()
            .map(crate::media::CopyService::take_done)
            .unwrap_or_default();
        for copy in copies {
            let current = self
                .window_by_seq(ws, copy.window)
                .and_then(|window| preview_item(window, copy.pane))
                .map(|item| (item.id, item.generation));
            if let Some(notice) = copy.notice_for(current) {
                self.tell_lane(ws, copy.window, copy.pane, copy.item, notice);
            }
        }
    }

    /// The window numbered `seq`: `ws` or another.
    fn window_by_seq<'a>(
        &'a mut self,
        ws: &'a mut WindowState,
        seq: u64,
    ) -> Option<&'a mut WindowState> {
        if ws.seq == seq {
            Some(ws)
        } else {
            self.windows.get_mut(&seq)
        }
    }

    /// Say `notice` in the lane of `pane` in window `window`, while it still
    /// shows `item`.
    fn tell_lane(
        &mut self,
        ws: &mut WindowState,
        window: u64,
        pane: u64,
        item: u64,
        notice: crate::window_state::LaneNotice,
    ) {
        let Some(window) = self.window_by_seq(ws, window) else {
            return;
        };
        if let Some(panel) = window
            .preview_panels
            .get_mut(&pane)
            .filter(|panel| panel.item == item)
        {
            panel.notice = Some(notice);
            window.accessibility_pending = true;
            if let Some(handle) = &window.window {
                handle.request_redraw();
            }
        }
    }

    /// Open, in this window, the previews the user asked for that are now
    /// on their pane's shelf, and forget those for windows that closed.
    fn open_ready_previews(&mut self, ws: &mut WindowState) {
        let seq = ws.seq;
        let ready: Vec<(u64, u64)> = self
            .previews_ready
            .iter()
            .filter(|(window, _, _)| *window == seq)
            .map(|(_, pane, item)| (*pane, *item))
            .collect();
        let windows = &self.windows;
        self.previews_ready
            .retain(|(window, _, _)| *window != seq && windows.contains_key(window));
        for (pane, item) in ready {
            if ws.mux.panes.get(&pane).is_some_and(|state| !state.closed) {
                self.show_media_item(ws, pane, item);
            }
        }
    }

    /// Preview the local file a link from pane `pane`'s output names in that
    /// pane's lane. A link from a pane that may be remote, or has gone, is
    /// refused as opening it is. The pane's origin is read now, when the user
    /// acts.
    fn preview_pane_link(&mut self, ws: &mut WindowState, pane: u64, uri: &str) {
        let tr = self.ui_text;
        let origin = ws.mux.panes.get(&pane).map(pane_path_origin);
        let Some(path) = kettle_core::links::local_file_path(uri) else {
            return notify_preview_failure(tr, Some(kettle_media::FailureCode::UnsupportedMedia));
        };
        match link_gate(uri, origin) {
            LinkGate::Open => self.pull_preview(ws, pane, &path, None),
            LinkGate::Refuse => fire_notify(
                tr.text(kettle_i18n::Text::NotifyTitleRemoteFileNotOpened),
                &tr.notify_body_remote_file_not_opened(&link_display_name(uri, 48)),
            ),
        }
    }

    /// What the clipboard names for `pane`'s lane, read now.
    fn copied_preview(&mut self, ws: &WindowState, pane: u64) -> Option<CopiedPreview> {
        let files = self.clipboard_file_paste_paths().unwrap_or_default();
        let text = files
            .is_empty()
            .then(|| self.clipboard.as_mut().and_then(|c| c.get_text().ok()))
            .flatten();
        let cwd = ws
            .mux
            .panes
            .get(&pane)
            .and_then(|state| state.term.current_dir_or_native());
        copied_preview(
            &files,
            text.as_deref(),
            cwd.as_deref(),
            crate::mux::home_dir_string().as_deref(),
        )
    }

    /// Preview, in the focused pane's lane, the Mermaid diagram the user
    /// copied (`/copy` in Claude Code or Codex) or, with `selection`,
    /// selected in a pane: the source taken back from what the agent's UI
    /// added and wrapped, rendered as the user's own pull. The first of
    /// several copied diagrams shows. A control client cannot have the
    /// clipboard or a selection read.
    fn preview_copied_diagram(&mut self, ws: &mut WindowState, selection: bool) {
        use kettle_core::DiagramCopyError as E;
        use kettle_i18n::Text as T;
        if self.ctl_driving {
            log::info!("preview: a control client cannot preview copied or selected text");
            return;
        }
        let tr = self.ui_text;
        let pane = if selection {
            ws.selecting_pane.or_else(|| ws.mux.active_focus())
        } else {
            ws.mux.active_focus()
        };
        let Some(pane) = pane else {
            return;
        };
        let sources = if selection {
            self.selected_diagram(ws, pane)
        } else {
            self.copied_diagram()
        };
        let sources = match sources {
            Ok(sources) => sources,
            Err(E::TooLarge) => {
                return notify_preview_failure(tr, Some(kettle_media::FailureCode::TooLarge));
            }
            Err(error) => {
                let body = match error {
                    E::Wrapped => T::NotifyBodyPreviewDiagramWrapped,
                    E::Unbounded => T::NotifyBodyPreviewDiagramUnbounded,
                    E::TooMany => {
                        return fire_notify(
                            tr.text(T::NotifyTitlePreviewNothing),
                            &tr.notify_body_preview_diagram_too_many(
                                kettle_core::MAX_COPIED_DIAGRAMS as u64,
                            ),
                        );
                    }
                    _ => T::NotifyBodyPreviewNoDiagram,
                };
                return fire_notify(tr.text(T::NotifyTitlePreviewNothing), tr.text(body));
            }
        };
        let count = sources.len();
        let title = match (selection, count > 1) {
            (true, false) => tr.text(T::MediaShelfSelectedDiagram).to_owned(),
            (true, true) => tr.media_shelf_selected_diagrams(count as u64),
            (false, false) => tr.text(T::MediaShelfCopiedDiagram).to_owned(),
            (false, true) => tr.media_shelf_copied_diagrams(count as u64),
        };
        let Some(first) = sources.first().cloned() else {
            return;
        };
        if let Some(failure) = media_unavailable(self.startup.media.as_deref()) {
            return notify_preview_failure(tr, Some(failure));
        }
        // Several are one gallery, each charged on its own, whose first is
        // rendered; the item keeps them all.
        let gallery = match count {
            1 => None,
            _ => match crate::media::Gallery::new(sources) {
                Some(gallery) => Some(Arc::new(gallery)),
                None => {
                    return notify_preview_failure(tr, Some(kettle_media::FailureCode::OverBudget));
                }
            },
        };
        self.admit_user_pull_of(
            ws,
            pane,
            kettle_media::JobKind::Mermaid,
            kettle_media::Source::Bytes(first.into_bytes()),
            None,
            title,
            kettle_media::Canvas::Theme,
            gallery,
        );
    }

    /// Put on the clipboard the `codex` function `kettle agent-setup --print`
    /// prints, for the shell new panes start (the configured `shell`, else
    /// the one the PTY picks for a pane with no command, from the configured
    /// `env`'s `SHELL`, Kettle's own or the user's passwd shell), and say
    /// so; or say why there is none to copy.
    fn copy_agent_setup(&mut self) {
        use kettle_i18n::Text as T;
        let tr = self.ui_text;
        let not_copied =
            |body: T| fire_notify(tr.text(T::NotifyTitleAgentSetupNotCopied), tr.text(body));
        let program = match self.cfg.shell.clone() {
            Some(shell) => Some(std::ffi::OsString::from(shell)),
            #[cfg(unix)]
            None => {
                let configured = self
                    .cfg
                    .env
                    .iter()
                    .rev()
                    .find(|(name, _)| name == "SHELL")
                    .map(|(_, value)| std::ffi::OsStr::new(value.as_str()));
                Some(kettle_core::default_pane_shell(configured).into())
            }
            #[cfg(not(unix))]
            None => None,
        };
        let shell = program
            .as_deref()
            .map(std::path::Path::new)
            .and_then(crate::codex_shell::CodexShell::from_program)
            .filter(|_| cfg!(unix));
        let Some(shell) = shell else {
            return not_copied(T::NotifyBodyAgentSetupShell);
        };
        let Ok(kettle) = std::env::current_exe() else {
            return not_copied(T::NotifyBodyAgentSetupUnnamed);
        };
        let function = match crate::codex_shell::codex_function(&kettle, shell) {
            Ok(function) => function,
            Err(crate::codex_shell::FunctionError::Translocated) => {
                return not_copied(T::NotifyBodyAgentSetupTranslocated);
            }
            Err(crate::codex_shell::FunctionError::UnnamedKettle) => {
                return not_copied(T::NotifyBodyAgentSetupUnnamed);
            }
        };
        let copied =
            self.clipboard
                .as_mut()
                .is_some_and(|clipboard| match clipboard.set_text(function) {
                    Ok(()) => true,
                    Err(error) => {
                        log::warn!("clipboard set_text failed (agent setup): {error}");
                        false
                    }
                });
        if !copied {
            return not_copied(T::NotifyBodyAgentSetupClipboard);
        }
        fire_notify(
            tr.text(T::NotifyTitleAgentSetupCopied),
            &tr.notify_body_agent_setup_copied(shell.name()),
        );
    }

    /// The Mermaid sources on the clipboard.
    fn copied_diagram(&mut self) -> Result<Vec<String>, kettle_core::DiagramCopyError> {
        let text = self
            .clipboard
            .as_mut()
            .and_then(|clipboard| clipboard.get_text().ok());
        kettle_core::diagram_sources(&text.unwrap_or_default(), None)
    }

    /// The Mermaid sources in `pane`'s selection.
    fn selected_diagram(
        &self,
        ws: &WindowState,
        pane: u64,
    ) -> Result<Vec<String>, kettle_core::DiagramCopyError> {
        let selected = ws
            .mux
            .panes
            .get(&pane)
            .and_then(|state| state.term.term.lock().ok())
            .map(|term| kettle_core::selected_diagram_sources(&term));
        match selected {
            Some(Ok(Some(sources))) => Ok(sources),
            Some(Err(error)) => Err(error),
            _ => Err(kettle_core::DiagramCopyError::Empty),
        }
    }

    /// Preview, in the focused pane's lane, the file the clipboard names. A
    /// copied path or link meets the pane's gate, as a link in its output
    /// would; a file copied in a file manager is on this computer.
    fn preview_copied_file(&mut self, ws: &mut WindowState) {
        let Some(pane) = ws.mux.active_focus() else {
            return;
        };
        match self.copied_preview(ws, pane) {
            Some(CopiedPreview::File(path)) => self.pull_preview(ws, pane, &path, None),
            Some(CopiedPreview::Link(url)) => self.preview_pane_link(ws, pane, &url),
            None => {
                let tr = self.ui_text;
                fire_notify(
                    tr.text(kettle_i18n::Text::NotifyTitlePreviewNothing),
                    tr.text(kettle_i18n::Text::NotifyBodyPreviewNothingCopied),
                );
            }
        }
    }

    /// Read `pane`'s item from its file again, on the user's gesture: the
    /// result replaces the item in place, under its key and title, on the
    /// canvas chosen for its lane, as the user's own. The worker read the file here
    /// before, so the pane's gate for files it names has nothing to add; a
    /// control client still cannot start the read (see `pull_preview`).
    fn reload_preview(&mut self, ws: &mut WindowState, pane: u64) {
        let Some((native, reload)) = preview_item(ws, pane)
            .zip(ws.preview_panels.get(&pane))
            .and_then(|(item, panel)| reload_of(item, panel))
        else {
            return;
        };
        if let Some(panel) = ws.preview_panels.get_mut(&pane) {
            panel.notice = None;
        }
        self.pull_preview(ws, pane, &native, Some(reload));
    }

    /// Ask the media worker to render the local file at `path` for `pane`'s
    /// lane: the user's own pull, which waits in the queue's slot for the
    /// user, opens the lane when it is ready, and says why when it cannot.
    fn pull_preview(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        path: &std::path::Path,
        reload: Option<ReloadOf>,
    ) {
        // A control client may drive Kettle's UI, but its input is never the
        // user's gesture, so it cannot have a file read on the GUI's word.
        if self.ctl_driving {
            log::info!("preview: a control client cannot start a preview read");
            return;
        }
        let tr = self.ui_text;
        if let Some(failure) = media_unavailable(self.startup.media.as_deref()) {
            return notify_preview_failure(tr, Some(failure));
        }
        let Ok(native) = kettle_media::NativePath::from_path(path) else {
            return notify_preview_failure(tr, Some(kettle_media::FailureCode::FileNotFound));
        };
        // A reload replaces its item in place, under the item's key and
        // title, on the canvas it shows, a gallery at the page it shows; a
        // new pull is keyed by its file.
        let (key, title, canvas, page) = match reload {
            Some(item) => (item.key, item.title, item.canvas, item.page),
            None => (
                crate::media::ShelfKey::Path(native.clone()),
                native
                    .file_name_lossy()
                    .map(|name| crate::media::display_title(&name))
                    .filter(|title| !title.is_empty())
                    .unwrap_or_else(|| tr.text(kettle_i18n::Text::MediaShelfUntitled).into()),
                kettle_media::Canvas::Theme,
                None,
            ),
        };
        let kind = match page {
            Some(index) => kettle_media::JobKind::MarkdownDiagrams { index },
            None => kettle_media::JobKind::Auto,
        };
        let source = kettle_media::Source::user_pull(
            native,
            kettle_media::GuiActionWitness::from_explicit_gui_action(),
        );
        self.admit_user_pull(ws, pane, kind, source, Some(key), title, canvas);
    }

    /// Queue the user's own pull for `pane`'s lane: `source` as `kind`,
    /// under `key` and `title`, on `canvas`. It waits in the queue's slot
    /// for the user, opens the lane when it is ready, and says why when it
    /// cannot. Its caller has refused a control client already.
    #[allow(clippy::too_many_arguments)]
    fn admit_user_pull(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        kind: kettle_media::JobKind,
        source: kettle_media::Source,
        key: Option<crate::media::ShelfKey>,
        title: String,
        canvas: kettle_media::Canvas,
    ) {
        self.admit_user_pull_of(ws, pane, kind, source, key, title, canvas, None);
    }

    /// [`Self::admit_user_pull`], for the first of `gallery`'s diagrams when
    /// there is one: its item keeps them all.
    #[allow(clippy::too_many_arguments)]
    fn admit_user_pull_of(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        kind: kettle_media::JobKind,
        source: kettle_media::Source,
        key: Option<crate::media::ShelfKey>,
        title: String,
        canvas: kettle_media::Canvas,
        gallery: Option<Arc<crate::media::Gallery>>,
    ) {
        let tr = self.ui_text;
        let Some((theme, target)) = self.media_surface(ws, pane) else {
            return;
        };
        let Some(spec) = crate::media::JobSpec::from_job(kettle_media::Job {
            kind,
            source,
            theme,
            canvas,
            target,
            fallback_fonts: Vec::new(),
        }) else {
            return notify_preview_failure(tr, Some(kettle_media::FailureCode::OverBudget));
        };
        let deadline = std::time::Instant::now() + kettle_ctl::show::SHOW_SERVER_DEADLINE;
        let push = crate::media::Push::new(
            crate::media::Requester::User,
            crate::media::Route {
                pane,
                window: ws.seq,
                verified: true,
            },
            crate::media::Draft {
                key,
                title,
                provenance: crate::media::Provenance::User,
                inline: None,
                gallery,
            },
            spec,
            kettle_media::client::RenderControl::with_deadline(deadline),
        );
        self.media.admit(crate::media::Sender::User, deadline, push);
        self.media_tick(ws);
    }

    /// Retire the cards that no longer stand for anything: their harness
    /// exited, their pane closed, or their item left the shelf or was
    /// replaced. Their text stays in the transcript and paints as unknown.
    fn retire_cards(&mut self, ws: &mut WindowState) {
        if self.media.cards.is_empty() {
            return;
        }
        let gone: Vec<kettle_ctl::process::ProcessIdentity> = self
            .media
            .cards
            .owners()
            .into_iter()
            .filter(|owner| {
                let gone = kettle_ctl::process::identity(owner.pid()) != Ok(*owner);
                #[cfg(target_os = "linux")]
                {
                    gone || !self.agent_launches.owner_live(*owner)
                }
                #[cfg(not(target_os = "linux"))]
                {
                    gone
                }
            })
            .collect();
        #[cfg(target_os = "linux")]
        if !gone.is_empty() {
            self.agent_launches.prune(std::time::Instant::now());
        }
        // Each live pane's items, by id and generation.
        let shelves: std::collections::HashMap<u64, Vec<(u64, u64)>> = self
            .all_windows(ws)
            .flat_map(|window| window.mux.panes.iter())
            .filter(|(_, pane)| !pane.closed)
            .map(|(&id, pane)| {
                let items = pane
                    .media_shelf
                    .items()
                    .iter()
                    .map(|item| (item.id, item.generation))
                    .collect();
                (id, items)
            })
            .collect();
        let retired = self.media.cards.retire(|card| {
            gone.contains(&card.owner)
                || !shelves
                    .get(&card.pane)
                    .is_some_and(|items| items.contains(&card.item))
        });
        for (pane_id, nonce) in retired {
            if let Some(window) = window_with_pane(ws, &mut self.windows, pane_id)
                && let Some(pane) = window.mux.panes.get_mut(&pane_id)
            {
                pane.inline_cards.remove(nonce);
                if let Some(handle) = &window.window {
                    handle.request_redraw();
                }
            }
        }
    }

    /// Charge rendered pixels to the preview account, releasing the pixels of
    /// the least recently viewed items not on screen while there is no room.
    fn admit_preview_pixels(
        &mut self,
        ws: &mut WindowState,
        width: u32,
        height: u32,
        mut pixels: Vec<u8>,
    ) -> Result<kettle_core::ImageData, kettle_media::FailureCode> {
        let visible = media_visible_items(self.all_windows(ws), &self.media.cards);
        loop {
            match kettle_core::ImageData::try_with_budget(
                width,
                height,
                pixels,
                &kettle_core::GraphicsBudget::previews(),
            ) {
                Ok(image) => return Ok(image),
                Err(kettle_core::ImageRefusal::Invalid) => {
                    return Err(kettle_media::FailureCode::RenderResource);
                }
                Err(kettle_core::ImageRefusal::NoRoom(back)) => {
                    if !self.evict_media_pixels(ws, &visible) {
                        return Err(kettle_media::FailureCode::OverBudget);
                    }
                    pixels = back;
                }
            }
        }
    }

    /// Take a lane's render of its item on another canvas. It replaces the
    /// item's pixels only while the item is the one asked about, unreplaced,
    /// and what was read is the source the item came from: a file changed
    /// since says so in the lane instead. The item keeps its place, id and
    /// generation; its cards show the new pixels.
    fn finish_lane_render(
        &mut self,
        ws: &mut WindowState,
        render: crate::media::LaneRender,
        spec: crate::media::JobSpec,
        result: Result<kettle_media::RenderOutput, kettle_media::client::RenderError>,
    ) {
        use crate::window_state::LaneNotice;
        use kettle_media::FailureCode;
        use kettle_media::client::RenderError;
        if let Some(ticket) = render.preview {
            return self.finish_lane_preview(ws, render, ticket, spec, result);
        }
        if let Some(ticket) = render.tile {
            return self.finish_lane_crop(ws, render, ticket, spec, result);
        }
        // A gallery page the lane no longer waits on is dropped unsaid.
        if !self.lane_wants(ws, &render) {
            return;
        }
        let control = self.ctl_driving;
        let tell = |app: &mut Self, ws: &mut WindowState, notice| {
            app.forget_lane_page(ws, &render);
            app.tell_lane(ws, render.window, render.pane, render.item, notice);
        };
        let output = match result {
            Ok(output) => output,
            Err(RenderError::Cancelled) => return self.forget_lane_page(ws, &render),
            Err(RenderError::Failure(FailureCode::Changed)) => {
                self.mark_preview_changed(ws, &render);
                return tell(self, ws, LaneNotice::Changed);
            }
            Err(RenderError::Failure(_)) => return tell(self, ws, LaneNotice::RenderFailed),
        };
        let rendered = output.rendered;
        let verdict = self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.mux.panes.get(&render.pane))
            .map_or(LaneRenderVerdict::Gone, |pane| {
                lane_render_verdict(pane.media_shelf.items(), &render, &rendered.digest)
            });
        match verdict {
            // Replaced or gone: nothing to say.
            LaneRenderVerdict::Gone => return self.forget_lane_page(ws, &render),
            LaneRenderVerdict::Changed => {
                self.mark_preview_changed(ws, &render);
                return tell(self, ws, LaneNotice::Changed);
            }
            LaneRenderVerdict::Same => {}
        }
        let (width, height, layout) = (rendered.width, rendered.height, rendered.layout);
        let warnings = rendered.warnings;
        let video = rendered.video.as_ref().map(|video| video.info);
        let image = match self.admit_preview_pixels(ws, width, height, rendered.rgba) {
            Ok(image) => image,
            Err(_) => return tell(self, ws, LaneNotice::RenderFailed),
        };
        // The item's cards show its new pixels: their posters hold the old
        // ones only weakly, and those go now.
        let cards = self
            .media
            .cards
            .cards_of(render.pane, (render.item, render.generation));
        let Some(window) = self.window_by_seq(ws, render.window) else {
            return;
        };
        let Some(pane) = window.mux.panes.get_mut(&render.pane) else {
            return;
        };
        for nonce in cards {
            pane.inline_cards.set_poster(nonce, Some(&image));
        }
        let Some(item) = pane
            .media_shelf
            .get_mut(render.item)
            .filter(|item| item.generation == render.generation)
        else {
            return;
        };
        // Another page of the gallery becomes the item's source; the page
        // shown, drawn again, stays it.
        let paged = render.page.is_some_and(|ask| {
            item.source.gallery_page().map(|(shown, _)| shown) != Some(ask.page)
        });
        if let Some(ask) = render.page
            && !item.source.select(ask.page)
        {
            return;
        }
        item.pixels = crate::media::ItemPixels::Ready(image);
        item.size = (width, height);
        item.layout = Some(layout);
        item.warnings = warnings;
        if video.is_some() {
            item.video = video;
        }
        item.source.spec.canvas = spec.canvas;
        if let Some(panel) = window
            .preview_panels
            .get_mut(&render.pane)
            .filter(|panel| panel.item == render.item)
        {
            panel.notice = None;
            if render.page.is_some() && page_waited_on(panel, render.generation) == render.page {
                panel.page = None;
            }
            if paged {
                // Another page starts fitted, its source from the top, with
                // no sharper pixels of the last.
                panel.view = kettle_render::MediaViewport::FIT;
                panel.scroll = (0, 0);
                window.lane_crops.remove(&render.pane);
            } else if !panel.view.is_fit() {
                // Sharper pixels for the old canvas no longer serve: a zoomed
                // lane asks again.
                window
                    .lane_crops
                    .entry(render.pane)
                    .or_default()
                    .again(std::time::Instant::now(), control);
            }
        }
        window.accessibility_pending = true;
        if let Some(handle) = &window.window {
            handle.request_redraw();
        }
    }

    /// Take a zoomed lane's sharper pixels: only those its lane asked for
    /// last, for the item it still shows unreplaced, read from the same
    /// source. A file changed since is said in the lane, and nothing more is
    /// read for that item until a reload makes another generation; any
    /// other failure leaves the lane showing its own pixels.
    fn finish_lane_crop(
        &mut self,
        ws: &mut WindowState,
        render: crate::media::LaneRender,
        ticket: u64,
        spec: crate::media::JobSpec,
        result: Result<kettle_media::RenderOutput, kettle_media::client::RenderError>,
    ) {
        use kettle_media::FailureCode;
        use kettle_media::client::RenderError;
        let verdict = match &result {
            Ok(output) => self
                .window_by_seq(ws, render.window)
                .and_then(|window| window.mux.panes.get(&render.pane))
                .map_or(LaneRenderVerdict::Gone, |pane| {
                    lane_render_verdict(pane.media_shelf.items(), &render, &output.rendered.digest)
                }),
            Err(RenderError::Failure(FailureCode::Changed)) => LaneRenderVerdict::Changed,
            Err(_) => LaneRenderVerdict::Gone,
        };
        // A changed file is the item's to remember, whether or not its lane
        // still wants these pixels.
        if verdict == LaneRenderVerdict::Changed {
            self.mark_preview_changed(ws, &render);
        }
        let Some(window) = self.window_by_seq(ws, render.window) else {
            return;
        };
        let Some(crop) = window
            .lane_crops
            .get_mut(&render.pane)
            .filter(|crop| crop.asked == Some(ticket))
        else {
            return;
        };
        crop.asked = None;
        match verdict {
            LaneRenderVerdict::Gone => return,
            LaneRenderVerdict::Changed => {
                crop.tile = None;
                return self.tell_lane(
                    ws,
                    render.window,
                    render.pane,
                    render.item,
                    crate::window_state::LaneNotice::Changed,
                );
            }
            LaneRenderVerdict::Same => {}
        }
        let Ok(output) = result else {
            return;
        };
        let rendered = output.rendered;
        let Some(coverage) = crate::media::crop_coverage(&rendered.layout) else {
            return;
        };
        let image_width = rendered.layout.image_in_target.width;
        // Sharper pixels are a nicety: with no room they are not kept, and
        // nothing on a shelf gives way for them.
        let Ok(image) = kettle_core::ImageData::try_with_budget(
            rendered.width,
            rendered.height,
            rendered.rgba,
            &kettle_core::GraphicsBudget::previews(),
        ) else {
            return;
        };
        crop.tile = Some(crate::media::LaneTile {
            item: render.item,
            generation: render.generation,
            canvas: spec.canvas,
            image,
            coverage,
            image_width,
        });
        if let Some(handle) = &window.window {
            handle.request_redraw();
        }
    }

    /// Note that the file `render`'s item came from changed since it was
    /// read: nothing more is read for that item unasked, whatever becomes
    /// of its lane, until a reload replaces it.
    fn mark_preview_changed(&mut self, ws: &mut WindowState, render: &crate::media::LaneRender) {
        // What the lane asked for it and is still waiting reads nothing.
        self.media.withdraw_lane_renders(render.pane, render.item);
        if let Some(item) = self
            .window_by_seq(ws, render.window)
            .and_then(|window| window.mux.panes.get_mut(&render.pane))
            .and_then(|pane| pane.media_shelf.get_mut(render.item))
            .filter(|item| item.generation == render.generation)
        {
            item.source.changed = true;
        }
    }

    /// Publish a finished render to its pane's shelf and answer its push.
    fn finish_show(&mut self, ws: &mut WindowState, finished: crate::media::Finished) {
        use kettle_media::FailureCode;
        use kettle_media::client::RenderError;
        let crate::media::Finished { push, result } = finished;
        let tr = self.ui_text;
        let (origin, route, draft, spec) = push.into_parts();
        if let crate::media::Requester::Lane(render) = origin {
            return self.finish_lane_render(ws, render, spec, result);
        }
        let output = match result {
            Ok(output) => output,
            // Cancelled because its pane went, or its client left; the user
            // who asked for a pane that went needs no word.
            Err(RenderError::Cancelled) => {
                let _ = origin.refuse(FailureCode::NotInKettlePane);
                return;
            }
            Err(RenderError::Failure(failure)) => {
                return notify_preview_failure(tr, origin.refuse(failure));
            }
        };
        let kettle_media::RenderOutput { kind, rendered } = output;
        let (width, height) = (rendered.width, rendered.height);
        let layout = rendered.layout;
        let warnings = rendered.warnings;
        let video = rendered.video.as_ref().map(|video| video.info);
        let image = match self.admit_preview_pixels(ws, width, height, rendered.rgba) {
            Ok(image) => image,
            Err(failure) => return notify_preview_failure(tr, origin.refuse(failure)),
        };
        let visible = media_visible_items(self.all_windows(ws), &self.media.cards);
        let item_id = self.media.next_item();
        let crate::media::Draft {
            key,
            title,
            provenance,
            inline,
            gallery,
        } = draft;
        let textual = matches!(
            kind,
            kettle_media::MediaKind::Svg | kettle_media::MediaKind::Mermaid
        );
        // A Markdown gallery's item is the page rendered, as the Mermaid it
        // is, with every page kept to show the others from; so is the first
        // of diagrams copied together.
        let (item_kind, source) = if let Some(gallery) = gallery {
            let Some(page) = crate::media::ItemSource::page(&spec, gallery, 0) else {
                return notify_preview_failure(tr, origin.refuse(FailureCode::OverBudget));
            };
            (kettle_media::MediaKind::Mermaid, page)
        } else if kind == kettle_media::MediaKind::Markdown {
            let page = rendered
                .fence_index
                .zip(crate::media::Gallery::new(rendered.fence_sources))
                .and_then(|(index, gallery)| {
                    crate::media::ItemSource::page(&spec, Arc::new(gallery), index)
                });
            let Some(page) = page else {
                return notify_preview_failure(tr, origin.refuse(FailureCode::OverBudget));
            };
            (kettle_media::MediaKind::Mermaid, page)
        } else {
            let source = crate::media::ItemSource::new(
                spec,
                rendered.digest,
                textual,
                rendered.exact_source,
            );
            (kind, source)
        };
        let mut item = crate::media::ShelfItem::new(
            item_id,
            key,
            title,
            provenance,
            item_kind,
            warnings.clone(),
            image,
            source,
        );
        item.layout = Some(layout);
        item.video = video;
        let Some(window) = window_with_pane(ws, &mut self.windows, route.pane) else {
            let _ = origin.refuse(FailureCode::NotInKettlePane);
            return;
        };
        let cell = window
            .renderer
            .as_ref()
            .map(|renderer| (renderer.cell_w, renderer.cell_h));
        let Some(pane) = window
            .mux
            .panes
            .get_mut(&route.pane)
            .filter(|pane| !pane.closed && !pane.held)
        else {
            let _ = origin.refuse(FailureCode::NotInKettlePane);
            return;
        };
        #[cfg(target_os = "linux")]
        let inline = inline.filter(|draft| {
            draft
                .launch
                .as_ref()
                .zip(pane.caller_root)
                .is_some_and(|(grant, root)| grant.valid(route.pane, root))
        });
        #[cfg(target_os = "linux")]
        let native_pickup = inline
            .as_ref()
            .and_then(|draft| draft.launch.clone())
            .zip(pane.caller_root);
        let shown = window
            .preview_panels
            .get(&route.pane)
            .map(|panel| panel.item);
        // A full shelf never drops an item on screen: the one its pane's lane
        // shows, or one whose card the last frame painted.
        let published = pane.media_shelf.publish(item, shown, &visible);
        // Cards of the item this one replaced, or of the item a full shelf
        // dropped, show what is gone; they never show the new pixels.
        let current = pane
            .media_shelf
            .items()
            .iter()
            .find(|item| item.id == published.id)
            .map(|item| (item.generation, item.image().cloned()));
        let cards = &mut self.media.cards;
        for (pane_id, nonce) in cards.retire(|card| {
            card.pane == route.pane
                && (Some(card.item.0) == published.dropped
                    || (card.item.0 == published.id
                        && current
                            .as_ref()
                            .is_none_or(|(generation, _)| card.item.1 != *generation)))
        }) {
            debug_assert_eq!(pane_id, route.pane);
            pane.inline_cards.remove(nonce);
        }
        let grid = pane
            .term
            .term
            .lock()
            .ok()
            .map(|term| (term.grid().columns(), term.grid().screen_lines()));
        let delivery = match (inline, current, cell, grid) {
            (Some(inline), Some((generation, Some(image))), Some(cell), Some(grid)) => {
                register_card(
                    cards,
                    (route.pane, &mut pane.inline_cards, grid),
                    cell,
                    (published.id, generation),
                    (kind, video.as_ref()),
                    &image,
                    inline,
                    std::time::Instant::now(),
                )
            }
            _ => None,
        };
        #[cfg(target_os = "linux")]
        let delivery = delivery.and_then(|mut delivery| {
            let (grant, root) = native_pickup?;
            delivery.permit = Some(self.agent_launches.issue(
                grant,
                root,
                std::time::Instant::now(),
                |bytes| getrandom::fill(bytes).is_ok(),
            )?);
            Some(delivery)
        });
        let seq = window.seq;
        if let Some(handle) = &window.window {
            handle.request_redraw();
        }
        let origin = match origin {
            crate::media::Requester::Ctl(origin) => origin,
            // What the user asked to preview opens in its pane's lane, from
            // that pane's window's next pass of the event loop.
            crate::media::Requester::User => {
                if self.previews_ready.len() < MAX_PREVIEWS_READY {
                    self.previews_ready.push((seq, route.pane, published.id));
                }
                return;
            }
            // Taken by `finish_lane_render` before publishing.
            crate::media::Requester::Lane(_) => return,
        };
        let mut result = kettle_ctl::show::ShowResult::new(
            (route.pane, route.verified, seq),
            published.id,
            kind,
            (width, height),
            &warnings,
        );
        result.inline = delivery;
        result.video = video.map(kettle_ctl::show::ShowVideo::from);
        let id = origin.request_id;
        origin.answer(kettle_ctl::protocol::Response::ok(
            id,
            serde_json::to_value(result).unwrap_or_default(),
        ));
    }

    /// Release the pixels of the least recently viewed shelf item in any
    /// window that is not on screen. False when there is none.
    fn evict_media_pixels(&mut self, ws: &mut WindowState, visible: &[u64]) -> bool {
        let oldest = self
            .all_windows(ws)
            .flat_map(|window| window.mux.panes.iter())
            .filter_map(|(&pane, state)| {
                state
                    .media_shelf
                    .eviction_candidate(visible)
                    .map(|(viewed, item)| (viewed, pane, item))
            })
            .min();
        let Some((_, pane, item)) = oldest else {
            return false;
        };
        window_with_pane(ws, &mut self.windows, pane)
            .and_then(|window| window.mux.panes.get_mut(&pane))
            .is_some_and(|pane| pane.media_shelf.evict_pixels(item))
    }

    /// Every pane as `(pane, window)`, and the live ones' own children that
    /// a caller can descend from. A closed or held pane's child no longer
    /// hosts anyone who could be calling.
    fn caller_roots(&self, ws: &WindowState) -> (Vec<crate::media::PaneRoot>, Vec<(u64, u64)>) {
        let mut roots = Vec::new();
        let mut panes = Vec::new();
        for window in self.all_windows(ws) {
            for (&id, pane) in &window.mux.panes {
                panes.push((id, window.seq));
                if let Some(root) = pane.caller_root
                    && !pane.closed
                    && !pane.held
                {
                    roots.push(crate::media::PaneRoot {
                        root,
                        pane: id,
                        window: window.seq,
                    });
                }
            }
        }
        (roots, panes)
    }

    /// `get_state`: version, theme, pid, server mode, focused pane.
    fn ctl_get_state(
        &self,
        ws: &WindowState,
        policy: kettle_ctl::CtlPolicy,
        caller: &crate::ctl_server::CallerEvidence,
    ) -> serde_json::Value {
        let (roots, panes) = self.caller_roots(ws);
        serde_json::json!({
            "caller": ctl_caller_report(caller, &roots, &panes, std::process::id()),
            "version": env!("CARGO_PKG_VERSION"),
            "pid": std::process::id(),
            // `mode` keeps its original spelling (`readonly`); `policy` uses
            // the config spellings and the display grant itself.
            "mode": format!("{:?}", policy.server()).to_lowercase(),
            "policy": {
                "server": policy.server().config_token(),
                "display": policy.display(),
            },
            "theme": self.cfg.theme_name,
            // `tabs` / `focused_pane` describe the FOCUSED window (back-
            // compat); `windows` / `focused_window` add the window dimension.
            "tabs": ws.mux.tabs.len(),
            "focused_pane": ws.mux.tabs.get(ws.mux.active).map(|t| t.focus),
            "windows": 1 + self.windows.len(),
            "focused_window": self.focused_seq,
            "window_title": self.desired_window_title(ws),
            "media": ctl_media_state(self.startup.media.as_deref()),
        })
    }

    /// `list_tabs`: index, title, active flag, pane ids.
    fn ctl_list_tabs(
        &self,
        ws: &WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{PageRequest, Response, error_codes as ec};

        let page = match PageRequest::from_params(&req.params) {
            Ok(page) => page,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let Some(capacity) = self.ctl_window_inventory_size(ws) else {
            return Response::err(
                req.id,
                ec::RESPONSE_TOO_LARGE,
                "window/tab/pane inventory exceeds the control enumeration budget",
            );
        };
        // Tabs across EVERY window, ordered by window seq. `index` and
        // `active` are in-window values; `window` disambiguates.
        let mut tabs = Vec::with_capacity(capacity.min(MAX_CTL_COLLECTION_ITEMS));
        for w in self.all_windows(ws) {
            let titles = w.mux.tab_titles();
            for (i, t) in w.mux.tabs.iter().enumerate() {
                tabs.push(serde_json::json!({
                    "window": w.seq,
                    "index": i,
                    "title": titles.get(i).cloned().unwrap_or_default(),
                    "active": i == w.mux.active,
                    "focused_pane": t.focus,
                    "panes": t.root.leaf_ids(),
                }));
            }
        }
        ctl_page_values_with_page(req, "tabs", tabs, page)
    }

    /// `list_panes`: id, tab, title, cwd, size, focused, argv, child_pid,
    /// agent_attached.
    fn ctl_list_panes(
        &self,
        ws: &WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{PageRequest, Response, error_codes as ec};

        let page = match PageRequest::from_params(&req.params) {
            Ok(page) => page,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let Some(capacity) = self.ctl_window_inventory_size(ws) else {
            return Response::err(
                req.id,
                ec::RESPONSE_TOO_LARGE,
                "window/tab/pane inventory exceeds the control enumeration budget",
            );
        };
        // Panes across EVERY window; `tab` is the in-window tab index,
        // `window` the owning window's seq, `focused` means focused WITHIN
        // its window.
        let mut panes = Vec::with_capacity(capacity.min(MAX_CTL_COLLECTION_ITEMS));
        for w in self.all_windows(ws) {
            self.ctl_list_panes_of(w, &mut panes);
        }
        ctl_page_values_with_page(req, "panes", panes, page)
    }

    fn ctl_list_panes_of(&self, ws: &WindowState, panes: &mut Vec<serde_json::Value>) {
        let focused = ws.mux.tabs.get(ws.mux.active).map(|t| t.focus);
        for (ti, tab) in ws.mux.tabs.iter().enumerate() {
            for id in tab.root.leaf_ids() {
                let Some(pane) = ws.mux.panes.get(&id) else {
                    continue;
                };
                let (cols, rows) = pane
                    .term
                    .term
                    .lock()
                    .ok()
                    .map(|t| {
                        use kettle_core::Dimensions;
                        (t.columns(), t.screen_lines())
                    })
                    .unwrap_or((0, 0));
                let attached = self
                    .ctl
                    .as_ref()
                    .map(|c| c.pane_is_attached(id))
                    .unwrap_or(false);
                panes.push(serde_json::json!({
                    "id": id,
                    "window": ws.seq,
                    "tab": ti,
                    "title": pane.title,
                    "cwd": pane.term.current_dir_or_native(),
                    "cols": cols,
                    "rows": rows,
                    "focused": Some(id) == focused,
                    "argv": pane.argv,
                    "child_pid": pane.term.child_pid(),
                    "agent_attached": attached,
                    // Surfaced so an agent can SEE the user's
                    // read-only lock before a send_text/run_command bounces
                    // with the `read_only` error code.
                    "read_only": pane.read_only,
                    // What `show` put on this pane's shelf, newest first.
                    "media_shelf": crate::media::shelf_report(&pane.media_shelf),
                }));
            }
        }
    }

    /// `read_screen`: a plain-text snapshot of a pane (default: focused).
    fn ctl_read_screen(
        &mut self,
        ws: &mut WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{PageRequest, Response, error_codes as ec};
        let page = match PageRequest::from_params(&req.params) {
            Ok(page) => page,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let pane = match self.ctl_resolve_pane(ws, &req.params) {
            Ok(p) => p,
            Err((code, message)) => return Response::err(req.id, code, message),
        };
        let scrollback = match req.params.get("scrollback_lines") {
            None | Some(serde_json::Value::Null) => 0,
            Some(value) => match value.as_u64().and_then(|n| usize::try_from(n).ok()) {
                Some(lines) => lines.min(MAX_CTL_SCROLLBACK_LINES),
                None => {
                    return Response::err(
                        req.id,
                        ec::BAD_PARAMS,
                        "'scrollback_lines' must be an unsigned integer",
                    );
                }
            },
        };
        let include_selection = match req.params.get("include_selection") {
            None | Some(serde_json::Value::Null) => false,
            Some(value) => match value.as_bool() {
                Some(include) => include,
                None => {
                    return Response::err(
                        req.id,
                        ec::BAD_PARAMS,
                        "'include_selection' must be a boolean",
                    );
                }
            },
        };
        let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) else {
            return Response::err(req.id, ec::NO_SUCH_PANE, "pane vanished");
        };
        let Ok(term) = p.term.term.lock() else {
            return Response::err(req.id, ec::INTERNAL, "could not read the grid");
        };
        use kettle_core::Dimensions as _;
        let range = term
            .selection
            .as_ref()
            .and_then(|selection| selection.to_range(&term));

        // `selection_to_string` owns an unbounded String API. Prove a
        // conservative byte upper bound from the selected grid cells first;
        // if it does not fit, omit the content and report truncation without
        // ever materializing the oversized selection.
        let selection_fits = !include_selection
            || range.as_ref().is_none_or(|range| {
                let columns = term.columns();
                let mut bytes = 0usize;
                for line in range.start.line.0..=range.end.line.0 {
                    // Newline plus wide-cell boundary behavior. Eight bytes is
                    // a conservative allowance for both.
                    bytes = bytes.saturating_add(8);
                    if bytes > MAX_CTL_SELECTION_BYTES || columns == 0 {
                        return false;
                    }
                    let start_col = (if range.is_block || line == range.start.line.0 {
                        range.start.column.0
                    } else {
                        0
                    })
                    // Alacritty includes the leading wide character when a
                    // selection starts on its spacer. Count that whole cell,
                    // including any combining marks, before allocation.
                    .saturating_sub(1)
                    .min(columns - 1);
                    let end_col = if range.is_block || line == range.end.line.0 {
                        range.end.column.0
                    } else {
                        columns - 1
                    }
                    .min(columns - 1);
                    if start_col > end_col {
                        continue;
                    }
                    for column in start_col..=end_col {
                        let cell = &term.grid()[kettle_core::Point::new(
                            kettle_core::Line(line),
                            kettle_core::Column(column),
                        )];
                        bytes = bytes.saturating_add(cell.c.len_utf8());
                        for mark in cell.zerowidth().into_iter().flatten() {
                            bytes = bytes.saturating_add(mark.len_utf8());
                        }
                        if bytes > MAX_CTL_SELECTION_BYTES {
                            return false;
                        }
                    }
                }
                true
            });
        let raw_selection = (include_selection && selection_fits)
            .then(|| term.selection_to_string())
            .flatten();
        let omitted_selection = include_selection && !selection_fits && range.is_some();
        let selection_present = term.selection.is_some();
        let selection_range = range.as_ref().map(|range| {
            serde_json::json!({
                "start": [range.start.line.0, range.start.column.0],
                "end": [range.end.line.0, range.end.column.0],
                "block": range.is_block,
            })
        });

        // Account for every cell before `screen_text` reserves and fills its
        // complete snapshot String. Each visited cell consumes at least one
        // byte, so the scan itself is bounded by the same byte budget.
        let columns = term.columns();
        let rows = term.screen_lines();
        let take = scrollback
            .min(term.grid().history_size())
            .min(MAX_CTL_SCROLLBACK_LINES);
        let display_adjust = if take == 0 {
            term.grid().display_offset() as i32
        } else {
            0
        };
        let mut screen_bytes = 0usize;
        let mut screen_fits = columns > 0;
        'screen: for row in -(take as i32)..rows as i32 {
            screen_bytes = screen_bytes.saturating_add(1);
            for column in 0..columns {
                let cell = &term.grid()[kettle_core::Point::new(
                    kettle_core::Line(row - display_adjust),
                    kettle_core::Column(column),
                )];
                screen_bytes = screen_bytes.saturating_add(cell.c.len_utf8());
                for mark in cell.zerowidth().into_iter().flatten() {
                    screen_bytes = screen_bytes.saturating_add(mark.len_utf8());
                }
                if screen_bytes > MAX_CTL_SCREEN_SNAPSHOT_BYTES {
                    screen_fits = false;
                    break 'screen;
                }
            }
        }
        if !screen_fits {
            return Response::err(
                req.id,
                ec::RESPONSE_TOO_LARGE,
                "screen snapshot exceeds the control byte budget",
            );
        }
        // Materialize under the same lock used for the byte preflight so PTY
        // output cannot race a small checked grid into an oversized snapshot.
        let s = kettle_core::term::screen_text_of(&term, scrollback);
        drop(term);
        let (selection, selection_truncated) = match raw_selection
            .map(kettle_core::scrub_card_markers)
            .transpose()
        {
            Ok(Some(text)) => {
                let (text, truncated) = cap_ctl_selection(text);
                (Some(text), truncated)
            }
            Ok(None) => (None, omitted_selection),
            Err(_) => {
                return Response::err(req.id, ec::INTERNAL, "could not prepare selection text");
            }
        };
        let snapshot = ctl_snapshot("screen", &s.text);
        if page
            .snapshot
            .as_deref()
            .is_some_and(|want| want != snapshot)
        {
            return Response::err(
                req.id,
                ec::STALE_SNAPSHOT,
                "screen changed between pages; restart without cursor/snapshot",
            );
        }
        let total = s.text.split_inclusive('\n').count();
        let start = page.offset.min(total);
        let desired_end = start.saturating_add(page.limit).min(total);
        let mut end = start;
        let mut text = String::new();
        let mut text_truncated = false;
        for line in s
            .text
            .split_inclusive('\n')
            .skip(start)
            .take(desired_end - start)
        {
            if !text.is_empty() && text.len().saturating_add(line.len()) > MAX_CTL_TEXT_PAGE_BYTES {
                break;
            }
            if text.is_empty() && line.len() > MAX_CTL_TEXT_PAGE_BYTES {
                let mut byte_end = MAX_CTL_TEXT_PAGE_BYTES;
                while !line.is_char_boundary(byte_end) {
                    byte_end -= 1;
                }
                text.push_str(&line[..byte_end]);
                text_truncated = true;
                end += 1;
                break;
            }
            text.push_str(line);
            end += 1;
        }
        let truncated = end < total;
        Response::ok(
            req.id,
            serde_json::json!({
                "pane": pane,
                "text": text,
                "cols": s.cols,
                "rows": s.rows,
                "history_size": s.history_size,
                "display_offset": s.display_offset,
                "cursor": [s.cursor.0, s.cursor.1],
                "cursor_visible": s.cursor_visible,
                "selection_present": selection_present,
                "selection": selection,
                "selection_truncated": selection_truncated,
                "selection_range": selection_range,
                "snapshot": snapshot,
                "next_cursor": truncated.then(|| end.to_string()),
                "truncated": truncated,
                "text_truncated": text_truncated,
                "total": total,
            }),
        )
    }

    /// `read_cells`: visible cell snapshot with selected render attributes.
    /// Intended for deterministic renderer/UI diagnostics without OCR.
    fn ctl_read_cells(
        &mut self,
        ws: &mut WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{PageRequest, Response, error_codes as ec};
        let page = match PageRequest::from_params(&req.params) {
            Ok(page) => page,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let pane = match self.ctl_resolve_pane(ws, &req.params) {
            Ok(p) => p,
            Err((code, message)) => return Response::err(req.id, code, message),
        };
        let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) else {
            return Response::err(req.id, ec::NO_SUCH_PANE, "pane vanished");
        };
        let Ok(t) = p.term.term.lock() else {
            return Response::err(req.id, ec::INTERNAL, "could not read the grid");
        };
        use kettle_core::Dimensions as _;
        let Some(cell_count) = t.columns().checked_mul(t.screen_lines()) else {
            return Response::err(
                req.id,
                ec::RESPONSE_TOO_LARGE,
                "visible grid dimensions overflow the control snapshot budget",
            );
        };
        if cell_count > MAX_CTL_COLLECTION_ITEMS {
            return Response::err(
                req.id,
                ec::RESPONSE_TOO_LARGE,
                "visible grid exceeds the control snapshot budget",
            );
        }
        let mut snap = PaneSnapshot::default();
        snap.capture(&t);
        drop(t);

        let mut cells = Vec::with_capacity(snap.cells.len());
        let display_off = snap.display_offset as i32;
        for sc in &snap.cells {
            let row = sc.line + display_off;
            if row < 0 || row >= snap.screen_lines as i32 {
                continue;
            }
            let flags = sc.flags.bits();
            cells.push(serde_json::json!({
                "row": row,
                "col": sc.col,
                "ch": if sc.is_card_placeholder() { ' ' } else { sc.c }.to_string(),
                "underline": flags & CELL_FLAG_UNDERLINE != 0,
                "double_underline": flags & CELL_FLAG_DOUBLE_UNDERLINE != 0,
                "undercurl": flags & CELL_FLAG_UNDERCURL != 0,
                "dotted_underline": flags & CELL_FLAG_DOTTED_UNDERLINE != 0,
                "dashed_underline": flags & CELL_FLAG_DASHED_UNDERLINE != 0,
                "any_underline": flags & CELL_FLAG_ALL_UNDERLINES != 0,
                "strikeout": flags & CELL_FLAG_STRIKEOUT != 0,
                "underline_color": sc.underline_color.is_some(),
            }));
        }
        let mut response = ctl_page_values_with_page(req, "cells", cells, page);
        if let Some(result) = response.result.as_object_mut() {
            result.insert("pane".into(), pane.into());
            result.insert("cols".into(), snap.columns.into());
            result.insert("rows".into(), snap.screen_lines.into());
            result.insert("history_size".into(), snap.history_size.into());
            result.insert("display_offset".into(), snap.display_offset.into());
            result.insert(
                "cursor".into(),
                serde_json::json!([snap.cursor.point.line.0, snap.cursor.point.column.0]),
            );
        }
        response
    }

    /// `ui_geometry`: read-only live geometry for chrome diagnostics.
    fn ctl_ui_geometry(
        &self,
        ws: &WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};

        let want_window = match optional_u64_param(&req.params, "window") {
            Ok(window) => window,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let target = match want_window {
            None => ws,
            Some(seq) if seq == ws.seq => ws,
            Some(seq) => match self.windows.get(&seq) {
                Some(target) => target,
                None => {
                    return Response::err(
                        req.id,
                        ec::BAD_PARAMS,
                        format!("no window with id {seq}"),
                    );
                }
            },
        };
        let surface = target
            .renderer
            .as_ref()
            .map(|r| r.surface_size())
            .unwrap_or((800, 600));
        let cell = target
            .renderer
            .as_ref()
            .map(|r| {
                serde_json::json!({
                    "width": r.cell_w,
                    "height": r.cell_h,
                    "font_size": r.font_size(),
                })
            })
            .unwrap_or_else(|| {
                serde_json::json!({
                    "width": 8.0,
                    "height": 16.0,
                    "font_size": 13.0,
                })
            });
        let cell_w = target.renderer.as_ref().map(|r| r.cell_w).unwrap_or(8.0);
        let cell_h = target.renderer.as_ref().map(|r| r.cell_h).unwrap_or(16.0);
        let bar = self.tab_bar(target);
        let segments: Vec<serde_json::Value> = bar
            .segments
            .iter()
            .map(|seg| {
                let fitted_title = kettle_render::fit_tab_segment_title(
                    &seg.title,
                    seg.path.as_deref(),
                    seg.idx,
                    &self.cfg.tab_format,
                    seg.title_rect.2,
                    cell_w,
                );
                serde_json::json!({
                    "index": seg.idx,
                    "title": seg.title,
                    "path": seg.path.as_deref(),
                    "fitted_title": fitted_title,
                    "active": seg.active,
                    "rect": rect_json(seg.rect),
                    "title_rect": rect_json(seg.title_rect),
                    "close": rect_json(seg.close),
                })
            })
            .collect();
        let pane_layout = self.pane_layout(target, self.area(target));
        let active_search_match_rects: Vec<serde_json::Value> = target
            .search
            .target_pane
            .filter(|_| target.search.open)
            .and_then(|pane_id| {
                pane_layout
                    .iter()
                    .find(|(candidate, _)| *candidate == pane_id)
                    .map(|(_, partition)| (pane_id, partition.terminal))
            })
            .map(|(pane_id, terminal)| {
                let origin = (
                    terminal.0 + self.cfg.padding_x,
                    terminal.1 + self.cfg.padding_y,
                );
                self.overlay(target, false)
                    .highlights
                    .into_iter()
                    .filter(|highlight| highlight.active)
                    .map(|highlight| {
                        serde_json::json!({
                            "pane": pane_id,
                            "rect": rect_json((
                                origin.0 + highlight.col as f32 * cell_w,
                                origin.1 + highlight.row as f32 * cell_h,
                                highlight.width as f32 * cell_w,
                                cell_h,
                            )),
                        })
                    })
                    .collect()
            })
            .unwrap_or_default();
        // Each pane's preview lane, by pane: where it is and how it shows.
        // Geometry only; never a path, title or pixel.
        let preview_lanes: Vec<serde_json::Value> = pane_layout
            .iter()
            .filter_map(|(id, partition)| {
                let share = partition.lane?;
                let state = match share {
                    crate::pane_partition::LaneShare::Expanded(_) => "expanded",
                    crate::pane_partition::LaneShare::Strip(_) => "strip",
                    crate::pane_partition::LaneShare::Badge => "badge",
                };
                let collapsed = matches!(share, crate::pane_partition::LaneShare::Strip(_));
                Some(self.preview_diagnostics(target, *id, share.rect(), collapsed, state))
            })
            .collect();
        let preview_overlay = target.preview_overlay.and_then(|open| {
            let partition = pane_layout.iter().find(|(pane, _)| *pane == open.pane)?.1;
            let (rect, collapsed) = self.preview_placement(target, open.pane, partition)?;
            let mut report =
                self.preview_diagnostics(target, open.pane, Some(rect), collapsed, "overlay");
            report["focused_control"] = open.control.into();
            report["modal"] = true.into();
            Some(report)
        });
        let home = crate::mux::home_dir_string();
        let focus = target.mux.active_focus();
        let pane_titlebars: Vec<serde_json::Value> = if pane_layout
            .iter()
            .any(|(_, partition)| partition.titlebar.is_some())
        {
            pane_layout
                .iter()
                .filter_map(|(pane_id, partition)| {
                    let titlebar_rect = partition.titlebar?;
                    let rect = &partition.leaf;
                    let pane = target.mux.panes.get(pane_id)?;
                    let cwd = pane.term.current_dir_or_native();
                    let mut title_parts = pane_title_parts(
                        &self.cfg.agent_badge,
                        pane.agent_attached,
                        pane.read_only,
                        &pane.title,
                        pane.title_is_placeholder,
                        cwd.as_deref(),
                        home.as_deref(),
                    );
                    title_parts
                        .prefix
                        .push_str(&media_shelf_badge(pane.media_shelf.unseen()));
                    let (cols, rows) = self.grid_of(target, partition.terminal);
                    let size_text =
                        (!self.cfg.title_hide_sizetext).then(|| format!("{}x{}", cols, rows));
                    let bell: Option<&str> = None;
                    let budget = (rect.2 / cell_w.max(1.0)).floor().max(1.0) as usize;
                    let group = pane.group_name.as_deref().filter(|g| !g.is_empty());
                    let fitted_title = kettle_render::fit_pane_titlebar_title(
                        group,
                        &title_parts.prefix,
                        &title_parts.title,
                        title_parts.path.as_deref(),
                        size_text.as_deref(),
                        bell,
                        budget,
                    );
                    Some(serde_json::json!({
                        "pane": pane_id,
                        "focused": Some(*pane_id) == focus,
                        "rect": rect_json(titlebar_rect),
                        "pane_rect": rect_json(*rect),
                        "raw_title": pane.title,
                        "title": title_parts.title,
                        "title_prefix": title_parts.prefix,
                        "path": title_parts.path,
                        "fitted_title": fitted_title,
                        "cols": cols,
                        "rows": rows,
                    }))
                })
                .collect()
        } else {
            Vec::new()
        };
        let context_menu = target.context_menu.as_ref().and_then(|menu| {
            let ((ax, ay), (panel_w, panel_h)) = self.context_menu_geometry(target)?;
            let (_, ch) = self.menu_cell(target);
            let row_h = ch + kettle_render::menu::ROW_PAD;
            let sep_h = kettle_render::menu::SEP_H;
            let mut row_y = ay;
            let start = menu.scroll_offset.min(menu.items.len());
            let visible = count_rows_fitting(&menu.items, start, panel_h, row_h, sep_h);
            let rows: Vec<serde_json::Value> = menu
                .items
                .iter()
                .enumerate()
                .skip(start)
                .take(visible)
                .map(|(idx, item)| {
                    let separator = matches!(item, ContextMenuItem::Separator);
                    let h = if separator { sep_h } else { row_h };
                    let label = match item {
                        ContextMenuItem::Item { label, .. } => *label,
                        ContextMenuItem::DynamicItem { label, .. } => label.as_str(),
                        ContextMenuItem::LuaItem { label, .. } => label.as_str(),
                        ContextMenuItem::ConfigItem { label, .. } => label.as_str(),
                        ContextMenuItem::Submenu { label, .. } => label.as_str(),
                        ContextMenuItem::ProfileChoice { label, .. }
                        | ContextMenuItem::WindowChoice { label, .. } => label.as_str(),
                        ContextMenuItem::NewTabShell { label, .. } => label.as_str(),
                        ContextMenuItem::UrlItem { label, .. } => *label,
                        ContextMenuItem::Media { label, .. } => *label,
                        ContextMenuItem::Info { label } => label.as_str(),
                        ContextMenuItem::Separator => "",
                    };
                    let row = serde_json::json!({
                        "index": idx,
                        "label": label,
                        "separator": separator,
                        "dispatchable": item_is_dispatchable(item),
                        "rect": rect_json((ax, row_y, panel_w, h)),
                    });
                    row_y += h;
                    row
                })
                .collect();
            Some(serde_json::json!({
                "anchor": {"x": ax, "y": ay},
                "rect": rect_json((ax, ay, panel_w, panel_h)),
                "highlight": menu.highlight,
                "scroll_offset": menu.scroll_offset,
                "rows": rows,
            }))
        });
        let title_edit = target.editing_title.as_ref().map(|state| {
            let scope = match state.scope {
                TitleEditScope::Window => "window",
                TitleEditScope::Tab => "tab",
                TitleEditScope::Pane => "pane",
                TitleEditScope::Group => "group",
            };
            serde_json::json!({
                "scope": scope,
                "rect": rect_json(self.title_edit_rect(target)),
            })
        });
        let search = target.search.open.then(|| {
            // The geometry is what is on screen, in the UI's language. The
            // labels below are control-protocol fields and stay English in
            // every language, like the rest of this JSON.
            let geometry = kettle_render::search_bar_geometry(
                surface.0 as f32,
                surface.1 as f32,
                cell_w,
                cell_h,
                &self.ui_text,
            );
            let english = kettle_i18n::Translator::new(kettle_i18n::Language::En);
            let controls = kettle_render::SearchControl::ALL.map(|control| {
                serde_json::json!({
                    "name": match control {
                        kettle_render::SearchControl::Editor => "editor",
                        kettle_render::SearchControl::Previous => "previous",
                        kettle_render::SearchControl::Next => "next",
                        kettle_render::SearchControl::Wrap => "wrap",
                        kettle_render::SearchControl::Case => "case",
                        kettle_render::SearchControl::Invert => "invert",
                        kettle_render::SearchControl::Close => "close",
                    },
                    "label": control.accessible_label(&english),
                    "rect": rect_json(geometry.control_rect(control)),
                    "focused": control == target.search.focused_control,
                })
            });
            serde_json::json!({
                // The query is deliberately omitted: geometry diagnostics must
                // not expose terminal-derived or user-entered search text.
                "target_pane": target.search.target_pane,
                "rect": rect_json(geometry.rect),
                "reserved_height": geometry.reserved_height,
                "rows": geometry.rows,
                "status": effective_search_status(&target.search).label(&english),
                "has_match": target.search.focused.is_some(),
                "match_rects": active_search_match_rects,
                "visible_truncated": target.search.visible_truncated,
                "wrap": target.search.wrap,
                "case": map_search_case_mode(target.search.case_mode).label(&english),
                "invert": target.search.invert,
                "status_rect": rect_json(geometry.status),
                "controls": controls,
            })
        });
        // Geometry diagnostics expose only the receipt's presentation state.
        // The retained path and thumbnail pixels stay private to the app; UI
        // automation needs the bounds to verify hover/collapse behavior, not
        // the clipboard content itself.
        let media_paste_receipt = self
            .media_paste_receipt_geometry(target)
            .and_then(|geometry| {
                let receipt = target.media_paste_receipt.as_ref()?;
                let (kind, count, original_width, original_height) = match &receipt.kind {
                    crate::window_state::MediaPasteReceiptKind::Image {
                        original_width,
                        original_height,
                    } => ("image", 1, Some(*original_width), Some(*original_height)),
                    crate::window_state::MediaPasteReceiptKind::Video { candidate, .. } => {
                        ("video", candidate.count, None, None)
                    }
                };
                Some(serde_json::json!({
                    "rect": rect_json(geometry.rect),
                    "preview_rect": geometry.preview_rect.map(rect_json),
                    "image_rect": (kind == "image").then(|| geometry.preview_rect.map(rect_json)).flatten(),
                    "dismiss_rect": rect_json(geometry.dismiss_rect),
                    "expanded": !geometry.compact,
                    "kind": kind,
                    "openable": geometry.openable,
                    "count": count,
                    "preview_ready": receipt.image.is_some(),
                    "original_width": original_width,
                    "original_height": original_height,
                    "remote": receipt.remote,
                }))
            });
        // Additive compatibility for automation written against the original
        // bitmap-only receipt. Video receipts appear only in the generic key.
        let image_paste_receipt = media_paste_receipt
            .as_ref()
            .filter(|receipt| {
                receipt.get("kind").and_then(serde_json::Value::as_str) == Some("image")
            })
            .cloned();
        let diagnostic_overlay = self.overlay(target, false);
        let settings = diagnostic_overlay.settings.as_ref().map(|settings| {
            let geometry = kettle_render::settings_panel_geometry(
                settings,
                cell_w,
                cell_h,
                surface.0 as f32,
                surface.1 as f32,
            );
            serde_json::json!({
                "rect": rect_json(geometry.rect),
                "focused_rect": rect_json(geometry.focused_rect),
                "focused_row": settings.focused_row,
                "row_count": settings.rows.len(),
                "active_category": settings.active_category,
                "first_line": geometry.first_line,
                "visible_lines": geometry.visible_lines,
            })
        });
        let modal_name = if diagnostic_overlay.confirm_dialog.is_some() {
            Some("confirm_dialog")
        } else if diagnostic_overlay.palette_query.is_some() {
            Some("palette")
        } else if diagnostic_overlay.theme_picker_query.is_some() {
            Some("theme_picker")
        } else if diagnostic_overlay.settings.is_some() {
            Some("settings")
        } else if diagnostic_overlay.layout_picker_query.is_some() {
            Some("layout_picker")
        } else if diagnostic_overlay.ssh_query.is_some() {
            Some("ssh_launcher")
        } else if diagnostic_overlay.edit_title.is_some() {
            Some("title_edit")
        } else if !diagnostic_overlay.hint_labels.is_empty() {
            Some("hint_mode")
        } else if diagnostic_overlay.context_menu.is_some() {
            Some("context_menu")
        } else if diagnostic_overlay.update_available.is_some() {
            Some("update_available")
        } else {
            None
        };
        let modal_projection = modal_accessibility_projection(
            &diagnostic_overlay,
            (surface.0 as f32, surface.1 as f32),
            &self.ui_text,
        );
        let accessibility = modal_name.map(|modal| {
            let focused = modal_projection.focus.and_then(|focus| {
                modal_projection
                    .nodes
                    .iter()
                    .find(|(id, _)| *id == focus)
                    .map(|(_, node)| {
                        serde_json::json!({
                            "role": format!("{:?}", node.role()).to_ascii_lowercase(),
                            "label": node.label(),
                        })
                    })
            });
            serde_json::json!({
                "modal": modal,
                "root_count": modal_projection.roots.len(),
                "focused": focused,
            })
        });
        // The cards on screen, by instance, never by card id, so automation
        // can find and click one as a user would.
        let now = std::time::Instant::now();
        let inline_cards: Vec<serde_json::Value> = target
            .renderer
            .as_ref()
            .map_or(&[][..], |renderer| renderer.painted_cards())
            .iter()
            .map(|card| {
                let item = self.media.cards.item(card.pane, card.nonce).and_then(|id| {
                    target
                        .mux
                        .panes
                        .get(&card.pane)?
                        .media_shelf
                        .items()
                        .iter()
                        .find(|item| item.id == id)
                });
                let [x, y, width, height] = card.rect;
                serde_json::json!({
                    "pane": card.pane,
                    "instance": target.card_sightings.instance(card),
                    "rect": {"x": x, "y": y, "width": width, "height": height},
                    "settled": target.card_sightings.settled(Some(*card), now).is_some(),
                    "item": item.map(|item| item.id),
                    "label": item.map(|item| {
                        without_card_marks(
                            self.ui_text
                                .card_a11y(&item.title, &self.card_accessibility_detail(item)),
                        )
                    }),
                })
            })
            .collect();
        let mut geometry = serde_json::json!({
                "window": target.seq,
                "window_focused": target.window_focused,
                "scale_factor": target.window.as_ref().map_or(1.0, |w| w.scale_factor()),
                "monitor": target.window.as_ref().and_then(|w| w.current_monitor()).map(|m| {
                    let size = m.size().to_logical::<f64>(m.scale_factor());
                    serde_json::json!({"width": size.width, "height": size.height})
                }),
                "surface": {"width": surface.0, "height": surface.1},
                "cell": cell,
                // Which face serves codepoints Unicode renders as text, or
                // null when this system has none that carry them. A scenario
                // checking the bullet is monochrome needs to know whether the
                // host can produce that at all.
                "text_presentation_face": target
                    .renderer
                    .as_ref()
                    .and_then(|r| r.text_presentation_face()),
                "padding": {"x": self.cfg.padding_x, "y": self.cfg.padding_y},
                "content": rect_json(self.area(target)),
                // The active tab's pane rects, in the same surface coordinates
                // `send_mouse` takes. Without these, automation can address the
                // tab bar and the modals but has no way to point at a PANE, so
                // anything pane-geometric (the drag gesture, split ratios after
                // a resize) could only be checked by eye.
                // `rect` is the pane's whole leaf and `terminal` its grid with
                // the padding, clear of its titlebar and lane.
                "panes": pane_layout
                    .iter()
                    .map(|(id, partition)| serde_json::json!({
                        "id": id,
                        "rect": rect_json(partition.leaf),
                        "terminal": rect_json(partition.terminal),
                        "focused": target.mux.active_focus() == Some(*id),
                    }))
                    .collect::<Vec<_>>(),
                "modals": {
                    "search": target.search.open,
                    "palette": target.palette_input.is_some(),
                    "settings": target.settings_nav.is_some(),
                    "settings_text_edit": target.settings_text_edit.is_some(),
                    "layout_picker": target.layout_picker_input.is_some(),
                    "theme_picker": target.theme_picker_input.is_some(),
                    "hint_mode": target.hint_state.is_some(),
                    "ssh_launcher": target.ssh_input.is_some(),
                    "context_menu": target.context_menu.is_some(),
                    "title_edit": target.editing_title.is_some(),
                    "confirm_dialog": target.confirm_dialog.is_some(),
                    "vi_mode": target.vi_mode.is_some(),
                },
                "context_menu": context_menu,
                "settings": settings,
                "accessibility": accessibility,
                "search": search,
                "image_paste_receipt": image_paste_receipt,
                "media_paste_receipt": media_paste_receipt,
                "title_edit": title_edit,
                "resize_overlay": target.resize_overlay.map(|(cols, rows, _)| serde_json::json!({
                    "cols": cols,
                    "rows": rows,
                })),
                "cursor": [target.cursor.x, target.cursor.y],
                "tab_drag_active": target.tab_drag_active,
                "tab_drag_armed": target.tab_drag_press.is_some(),
                "tab_drag_visible": target.tab_drag_active && target.tab_drag_press.is_none(),
                // Terminator parity: the pane-drag gesture, reported in the
                // same armed/live shape as the tab drag above so a headless
                // check can tell "the press was noticed" from "the pane is
                // being carried" from "releasing here would move it".
                "pane_drag_armed": target.pane_drag.is_some(),
                "pane_drag_live": target.pane_drag.as_ref().is_some_and(|d| d.live),
                "pane_drag_pane": target.pane_drag.as_ref().map(|d| d.pane),
                "pane_drag_target": target.pane_drag.as_ref().and_then(|d| d.target).map(
                    |(id, _, dir, before)| serde_json::json!({
                        "pane": id,
                        "edge": match (dir, before) {
                            (Dir::Horizontal, true) => "left",
                            (Dir::Horizontal, false) => "right",
                            (Dir::Vertical, true) => "top",
                            (Dir::Vertical, false) => "bottom",
                        },
                    }),
                ),
                "tab_bar": {
                    "height": bar.height,
                    "y": bar.y,
                    "new_tab": rect_json(bar.new_tab),
                    "new_tab_menu": rect_json(bar.new_tab_menu),
                    "drag_cursor_x": bar.drag_cursor_x,
                    // A vertical strip reports the drag on its own axis;
                    // additive, so a reader that only knows the x key still
                    // sees exactly what it saw before on a horizontal bar.
                    "drag_cursor_y": bar.drag_cursor_y,
                    // Tear-off state (pre-tear ghost escalation and dock
                    // highlight) for live-UI smokes.
                    "tear_lift": bar.tear_lift,
                    "insert_marker": bar.insert_marker,
                    "dock_highlighted": bar.insert_marker.is_some(),
                    "band": rect_json(bar.band),
                    "segments": segments,
                },
                "pane_titlebars": pane_titlebars,
                // What this window's renderer has sent to the GPU: counts
                // only, never content. A window that only blinks should add
                // frames here but no writes, and one printing on shared memory
                // mapped writes but no buffer writes (see kettle-render's
                // upload.rs).
                "render_uploads": target.renderer.as_ref().map(|r| {
                    let u = r.render_uploads();
                    serde_json::json!({
                        "frames_presented": u.frames_presented,
                        "buffer_writes": u.buffer_writes,
                        "buffer_bytes": u.buffer_bytes,
                        "texture_writes": u.texture_writes,
                        "text_prepares": u.text_prepares,
                        "chrome_prepares": u.chrome_prepares,
                        "skipped_writes": u.skipped_writes,
                        "mapped_uploads": u.mapped_uploads,
                        "mapped_writes": u.mapped_writes,
                        "mapped_bytes": u.mapped_bytes,
                    })
                }),
                // Who draws the blink: the GPU, or the window server's layer
                // (macOS). Timing, geometry and counts only.
                "cursor_blink": self.cursor_blink_diagnostics(target),
        });
        if let serde_json::Value::Object(fields) = &mut geometry {
            fields.insert(
                "fullscreen".into(),
                serde_json::Value::Bool(
                    target
                        .window
                        .as_ref()
                        .is_some_and(|window| window.fullscreen().is_some()),
                ),
            );
            fields.insert(
                "inline_cards".into(),
                serde_json::Value::Array(inline_cards),
            );
            fields.insert(
                "preview_lanes".into(),
                serde_json::Value::Array(preview_lanes),
            );
            fields.insert("preview_overlay".into(), preview_overlay.into());
            fields.insert(
                "desktop".into(),
                serde_json::json!({
                    "client_origin": target.window.as_ref()
                        .and_then(|w| w.inner_position().ok())
                        .map(|p| serde_json::json!({"x": p.x, "y": p.y})),
                    "frame_origin": target.window.as_ref()
                        .and_then(|w| w.outer_position().ok())
                        .map(|p| serde_json::json!({"x": p.x, "y": p.y})),
                }),
            );
        }
        Response::ok(req.id, geometry)
    }

    /// `ui_geometry.cursor_blink`: the phase the screen shows, when it next
    /// changes, and the layer's hand-offs, exits and exit-frame times.
    fn cursor_blink_diagnostics(&self, ws: &WindowState) -> serde_json::Value {
        let now = std::time::Instant::now();
        let layer = &ws.blink_layer;
        let (phase_on, next_edge) = match layer.active() {
            Some((anchor, plan, _)) if ws.last_blink == anchor => {
                let (on, edge) = crate::cursor_blink::materialize(
                    ws.blink_on,
                    ws.last_blink,
                    plan.activity,
                    plan.interval,
                    plan.timeout,
                    now,
                );
                let next = crate::cursor_blink::next_edge(
                    on,
                    edge,
                    plan.activity,
                    plan.interval,
                    plan.timeout,
                    now,
                );
                (on, next)
            }
            _ => {
                let running = ws.window_focused
                    && !window_is_render_hidden(ws)
                    && cursor_blink_active(
                        self.cfg.cursor_blink,
                        self.pane_cursor_blinking(ws, false),
                        ws.window_focused,
                    );
                let next = running
                    .then(|| {
                        crate::cursor_blink::next_edge(
                            ws.blink_on,
                            ws.last_blink,
                            ws.last_blink_activity,
                            std::time::Duration::from_millis(self.cfg.cursor_blink_interval),
                            self.cfg.cursor_blink_timeout(),
                            now,
                        )
                    })
                    .flatten();
                (ws.blink_on, next)
            }
        };
        let exit_frames = &layer.exit_frames;
        serde_json::json!({
            "renderer": if layer.is_active() { "layer" } else { "gpu" },
            "layer_rect": layer.active().map(|(_, _, rect)| rect),
            "phase_on": phase_on,
            "next_edge_ms": next_edge
                .map(|at| u64::try_from(at.saturating_duration_since(now).as_millis()).unwrap_or(u64::MAX)),
            "handoffs": layer.handoffs,
            "exits": layer.exits,
            "hides": layer.hides,
            "exit_frame_us": {
                "count": exit_frames.count(),
                "p50": exit_frames.percentile_us(50),
                "p95": exit_frames.percentile_us(95),
                "max": exit_frames.max_us(),
            },
            "fallback": layer.fallback(),
        })
    }

    /// `perform_action`: dispatch a named kettle app action against the focused
    /// window. This complements `send_keys`, which intentionally writes PTY
    /// bytes to the pane instead of firing global shortcuts, so diagnostics can
    /// open app chrome such as Search / Palette / Settings deterministically.
    fn ctl_perform_action(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let Some(name) = req.params.get("action").and_then(|v| v.as_str()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing 'action' string");
        };
        // Diagnostic automation needs an idempotent activation primitive.
        // Reusing the user-facing visibility toggle is racy: if winit's focus
        // event trails the native focus state, a smoke can hide the exact
        // window it is trying to raise. This control-only action never hides.
        if name == "focus_window" {
            let Some(window) = ws.window.as_ref() else {
                return Response::err(req.id, ec::INTERNAL, "target window is unavailable");
            };
            window.set_visible(true);
            window.focus_window();
            window.request_redraw();
            return Response::ok(
                req.id,
                serde_json::json!({
                    "action": "FocusWindow",
                    "requested": name,
                    "window": ws.seq,
                }),
            );
        }
        let Some(action) = kettle_config::Action::from_name(name) else {
            return Response::err(req.id, ec::BAD_PARAMS, format!("unknown action '{name}'"));
        };
        let resolved = format!("{action:?}");
        self.handle_action(ws, action, event_loop);
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        Response::ok(
            req.id,
            serde_json::json!({
                "action": resolved,
                "requested": name,
                "window": ws.seq,
            }),
        )
    }

    /// The one routing decision shared by real keyboard input and the
    /// `dispatch_keybind` control route: does this resolved chord belong to
    /// the terminal instead of the matched action? Only the non-macOS default
    /// `Alt+Arrow` focus chords are adaptive; they fall through when the mux
    /// has no visible pane in that direction, which includes every zoomed
    /// multi-pane tab because zoom collapses the layout to the focused pane.
    fn adaptive_focus_chord_falls_through(
        &self,
        ws: &WindowState,
        trigger: Trigger,
        action: &Action,
    ) -> bool {
        // A trigger the config binds itself, even to its default action, is
        // always Kettle's, as for every program key rule.
        let enabled = !cfg!(target_os = "macos") && !self.cfg.keybinds_declared.contains(&trigger);
        adaptive_alt_focus_direction(trigger, action, enabled).is_some_and(|(dx, dy)| {
            adaptive_alt_focus_falls_through(
                trigger,
                action,
                true,
                ws.mux.pane_in_direction(self.area(ws), dx, dy).is_some(),
            )
        })
    }

    /// The routing decision the real keyboard and `dispatch_keybind` share: a
    /// matched chord goes to the terminal when it is an adaptive focus chord
    /// with nowhere to go, or when a program that owns the keyboard also uses
    /// it (see [`program_key_rule`]). The search bar keeps only the first
    /// rule: while it has the keyboard, the program cannot get the key, so a
    /// Kettle action is still better than nothing.
    fn chord_falls_through(&self, ws: &WindowState, trigger: Trigger, action: &Action) -> bool {
        self.adaptive_focus_chord_falls_through(ws, trigger, action)
            || self.chord_goes_to_program(ws, trigger, action)
    }

    /// Whether a default chord that the focused pane's program also uses goes
    /// to that program: only default (trigger, action) pairs with a
    /// [`ProgramKeyRule`], only while `keybind-yield` is on, and only while a
    /// program, not an idle shell prompt, owns the pane's keyboard. Reads the
    /// pane's terminal only after the cheap pair match succeeds.
    fn chord_goes_to_program(&self, ws: &WindowState, trigger: Trigger, action: &Action) -> bool {
        let Some(rule) =
            configured_program_key_rule(&self.cfg, trigger, action, cfg!(target_os = "macos"))
        else {
            return false;
        };
        // Broadcast writes the key to every target in that target's own
        // keyboard mode, but only the focused pane is asked here, so a
        // broadcast chord stays Kettle's.
        if ws.mux.is_broadcast_on() {
            return false;
        }
        let Some(pane) = ws.mux.active_focus().and_then(|id| ws.mux.panes.get(&id)) else {
            return false;
        };
        // A pane that cannot take input would drop the key.
        if pane.read_only || pane.pty_input_failed() {
            return false;
        }
        let claims = pane.term.keyboard_claims();
        if !claims.program_owns_keyboard() {
            return false;
        }
        let kettle = KettleActionState {
            tabs: ws.mux.tabs.len(),
            current_tab: ws.mux.active,
            selection_exists: matches!(action, Action::SelectToTop | Action::SelectToBottom)
                && pane
                    .term
                    .term
                    .lock()
                    .ok()
                    .is_some_and(|t| t.selection.is_some()),
            focus_target_exists: self.focus_target_exists(ws, action),
            chord_is_distinct: rule == ProgramKeyRule::WhenKettleIdleAndDistinct
                && pane
                    .term
                    .term
                    .lock()
                    .ok()
                    .is_some_and(|t| chord_reaches_program_distinctly(trigger, *t.mode())),
        };
        program_gets_chord(rule, action, &claims, &kettle)
    }

    /// Whether a focus action has a visible pane to move to. A zoomed tab
    /// shows only its focused pane, so it has none in any direction, as a
    /// single-pane tab has none.
    fn focus_target_exists(&self, ws: &WindowState, action: &Action) -> bool {
        let direction = match action {
            Action::FocusUp => (0, -1),
            Action::FocusDown => (0, 1),
            Action::FocusLeft => (-1, 0),
            Action::FocusRight => (1, 0),
            Action::FocusNext | Action::FocusPrev => {
                return ws.mux.leaves(ws.mux.active, self.area(ws)).len() > 1;
            }
            _ => return false,
        };
        ws.mux
            .pane_in_direction(self.area(ws), direction.0, direction.1)
            .is_some()
    }

    /// `dispatch_keybind`: diagnostic route for app-level keybind matching.
    /// Unlike `send_keys`, this does not write PTY bytes; it exercises the same
    /// resolver as the real window keyboard path and dispatches the matched app
    /// action when no modal owns the keyboard. A chord the real keyboard path
    /// would hand to the terminal (an adaptive `Alt+Arrow` with no visible
    /// neighbour) is reported as `terminal_fallthrough` and not dispatched;
    /// the PTY write itself stays exclusive to `send_keys`.
    fn ctl_dispatch_keybind(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let logical = match parse_ctl_logical_key(req.params.get("logical")) {
            Ok(k) => k,
            Err(e) => return Response::err(req.id, ec::BAD_PARAMS, e),
        };
        let physical = match parse_ctl_physical_key(req.params.get("physical")) {
            Ok(k) => k,
            Err(e) => return Response::err(req.id, ec::BAD_PARAMS, e),
        };
        if logical.is_none() && physical.is_none() {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                "dispatch_keybind requires 'logical' or 'physical'",
            );
        }
        let mods = match parse_ctl_mods(req.params.get("mods")) {
            Ok(m) => m,
            Err(e) => return Response::err(req.id, ec::BAD_PARAMS, e),
        };
        let candidates = keybind_candidates(logical.as_ref(), physical.as_ref(), mods);
        let candidate_labels: Vec<String> = candidates.iter().map(Trigger::label).collect();
        let modal_blocked = self.any_modal_open(ws);
        if modal_blocked {
            return Response::ok(
                req.id,
                serde_json::json!({
                    "window": ws.seq,
                    "dispatched": false,
                    "modal_blocked": true,
                    "candidates": candidate_labels,
                }),
            );
        }
        let Some((trigger, action)) = resolve_keybind_action(
            &self.cfg.keybinds,
            logical.as_ref(),
            physical.as_ref(),
            mods,
        ) else {
            return Response::ok(
                req.id,
                serde_json::json!({
                    "window": ws.seq,
                    "dispatched": false,
                    "modal_blocked": false,
                    "candidates": candidate_labels,
                }),
            );
        };
        let trigger_label = trigger.label();
        let action_name = kettle_config::keybinds::action_label(&action);
        if self.chord_falls_through(ws, trigger, &action) {
            return Response::ok(
                req.id,
                serde_json::json!({
                    "window": ws.seq,
                    "dispatched": false,
                    "modal_blocked": false,
                    "terminal_fallthrough": true,
                    "trigger": trigger_label,
                    "action": action_name,
                    "candidates": candidate_labels,
                }),
            );
        }
        let font_size_before = ws.renderer.as_ref().map(|r| r.font_size());
        self.handle_action(ws, action, event_loop);
        let font_size_after = ws.renderer.as_ref().map(|r| r.font_size());
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        Response::ok(
            req.id,
            serde_json::json!({
                "window": ws.seq,
                "dispatched": true,
                "modal_blocked": false,
                "terminal_fallthrough": false,
                "trigger": trigger_label,
                "action": action_name,
                "font_size_before": font_size_before,
                "font_size_after": font_size_after,
                "candidates": candidate_labels,
            }),
        )
    }

    /// `dispatch_ui_key`: drive the currently open Kettle-owned modal without
    /// ever encoding a byte for the PTY. This is intentionally separate from
    /// `send_keys`: diagnostics can exercise Search even when the focused pane
    /// is running an input-sensitive TUI, and a closed modal is a hard error.
    /// The batch and token caps keep one control request bounded on the UI
    /// thread. All tokens are parsed before state is changed.
    fn ctl_dispatch_ui_key(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};

        const MAX_UI_KEYS: usize = 64;
        const MAX_UI_KEY_BYTES: usize = 64;

        // Route to whichever text modal is open, in the same precedence the
        // real `KeyboardInput` arm uses, so every modal's text-entry rules get
        // end-to-end coverage, not just search's.
        let Some(modal) = open_text_modal(ws) else {
            return Response::err(req.id, ec::BAD_PARAMS, "no supported UI modal is open");
        };
        let Some(keys) = req.params.get("keys").and_then(|value| value.as_array()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing 'keys' array");
        };
        if keys.is_empty() || keys.len() > MAX_UI_KEYS {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                format!("'keys' must contain 1..={MAX_UI_KEYS} entries"),
            );
        }

        let mut parsed = Vec::with_capacity(keys.len());
        for (index, value) in keys.iter().enumerate() {
            let Some(token) = value.as_str() else {
                return Response::err(req.id, ec::BAD_PARAMS, "non-string entry in 'keys'");
            };
            if token.is_empty() || token.len() > MAX_UI_KEY_BYTES {
                return Response::err(
                    req.id,
                    ec::BAD_PARAMS,
                    format!("UI key tokens must be 1..={MAX_UI_KEY_BYTES} bytes"),
                );
            }
            let Some((mods, key)) = parse_ui_key(token) else {
                return Response::err(
                    req.id,
                    ec::BAD_PARAMS,
                    format!("unrecognized UI key token at index {index}"),
                );
            };
            parsed.push((mods, key));
        }

        let previous_mods = ws.mods;
        #[cfg(target_os = "macos")]
        let previous_raw_mods = ws.macos_raw_mods;
        let mut applied = 0usize;
        for (mods, key) in &parsed {
            ws.mods = *mods;
            // The word-edit gates read the raw Option shadow rather than the
            // masked value (`option_physically_held`), so a control-plane
            // `alt+backspace` has to set both. Setting only `ws.mods` would let
            // a live smoke pass against code that never restores Option.
            #[cfg(target_os = "macos")]
            {
                ws.macos_raw_mods = *mods;
            }
            // Mirror `winit`: `KeyEvent::text` is present for a character key
            // under every modifier except Control, Command included.
            // Suppressing Super here would let a `cmd+v` test pass against a
            // handler that types a literal `v`. The modifier rule belongs in
            // `modal_input::accept_text`, not in the transport.
            let text = match key {
                Key::Character(text) if !mods.control_key() => Some(text.as_str()),
                _ => None,
            };
            match modal {
                TextModal::Confirm => self.confirm_dialog_key(ws, key, event_loop),
                TextModal::Hint => self.hint_key(ws, key, text),
                TextModal::Palette => self.palette_key(ws, key, text, event_loop),
                TextModal::ThemePicker => self.theme_picker_key(ws, key, text),
                TextModal::SettingsText => self.settings_text_key(ws, key, text),
                TextModal::Settings => self.settings_key(ws, key, event_loop),
                TextModal::LayoutPicker => self.layout_picker_key(ws, key, text),
                TextModal::Ssh => self.ssh_key(ws, key, text),
                TextModal::TitleEdit => self.title_edit_key(ws, key, text),
                TextModal::Search => {
                    if !self.search_key(ws, key, None, text) {
                        self.search_bar_shortcut(ws, key, None, false, event_loop);
                    }
                }
                TextModal::Preview => self.preview_focus_key(ws, key, false),
            }
            applied += 1;
            // Stop as soon as the modal this batch addressed is gone (Esc,
            // Enter, or an action that replaced it). Continuing would type the
            // remaining keys into whatever took its place — including the PTY.
            if open_text_modal(ws) != Some(modal) {
                end_modal_composition(ws);
                break;
            }
        }
        ws.mods = previous_mods;
        #[cfg(target_os = "macos")]
        {
            ws.macos_raw_mods = previous_raw_mods;
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        Response::ok(
            req.id,
            serde_json::json!({
                "window": ws.seq,
                "modal": modal.as_str(),
                "keys": applied,
                "requested_keys": parsed.len(),
                "open": open_text_modal(ws) == Some(modal),
            }),
        )
    }

    /// `resize_window`: request a live OS-window client-area resize. The real
    /// `WindowEvent::Resized` path applies renderer/surface/PTY grid changes.
    fn ctl_resize_window(
        &mut self,
        ws: &mut WindowState,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let target_seq = match optional_u64_param(&req.params, "window") {
            Ok(window) => window.unwrap_or(ws.seq),
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        let Some(width) = req.params.get("width").and_then(|v| v.as_u64()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing integer 'width'");
        };
        let Some(height) = req.params.get("height").and_then(|v| v.as_u64()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing integer 'height'");
        };
        if width == 0 || height == 0 || width > u32::MAX as u64 || height > u32::MAX as u64 {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                "'width' and 'height' must be in 1..=u32::MAX",
            );
        }
        if target_seq == ws.seq {
            return self.ctl_resize_window_for_target(ws, req.id, width as u32, height as u32);
        }
        let Some(mut target) = self.windows.remove(&target_seq) else {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                format!("no window with id {target_seq}"),
            );
        };
        let resp =
            self.ctl_resize_window_for_target(&mut target, req.id, width as u32, height as u32);
        self.windows.insert(target_seq, target);
        resp
    }

    fn ctl_resize_window_for_target(
        &mut self,
        target: &mut WindowState,
        request_id: u64,
        width: u32,
        height: u32,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let Some(window) = target.window.clone() else {
            return Response::err(request_id, ec::INTERNAL, "window is not available");
        };
        let requested = winit::dpi::PhysicalSize::new(width, height);
        let applied = window.request_inner_size(requested).unwrap_or(requested);
        self.apply_window_resize(target, applied.width, applied.height);
        window.request_redraw();
        Response::ok(
            request_id,
            serde_json::json!({
                "window": target.seq,
                "requested": {"width": width, "height": height},
                "applied": {"width": applied.width, "height": applied.height},
            }),
        )
    }

    /// `send_mouse`: deterministic local-user mouse input for diagnostics and
    /// end-to-end agent/TUI tests. Coordinates are physical pixels relative to
    /// the target kettle window's client area.
    fn ctl_send_mouse(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let target_seq = match optional_u64_param(&req.params, "window") {
            Ok(window) => window.unwrap_or(ws.seq),
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        if target_seq == ws.seq {
            return self.ctl_send_mouse_for_window(ws, event_loop, req);
        }
        let Some(mut target) = self.windows.remove(&target_seq) else {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                format!("no window with id {target_seq}"),
            );
        };
        let resp = self.ctl_send_mouse_for_window(&mut target, event_loop, req);
        // A synthetic event can close this mapped target's last tab. Consume
        // only that window's request here; the caller remains checked out and
        // must not inherit the target's close.
        if take_window_close_request(&mut self.pending_window_closes, target_seq) {
            if self
                .torn_drag
                .as_ref()
                .is_some_and(|t| t.seq == target_seq || t.carrier == target_seq)
            {
                self.abandon_torn_drag(None);
            }
            drop(target);
        } else {
            self.windows.insert(target_seq, target);
        }
        resp
    }

    fn ctl_send_mouse_for_window(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let Some(event) = req.params.get("event").and_then(|v| v.as_str()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing 'event' string");
        };
        let event = event.to_ascii_lowercase();
        if !matches!(
            event.as_str(),
            "move" | "press" | "release" | "click" | "wheel"
        ) {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                "event must be move, press, release, click, or wheel",
            );
        }
        let button = if matches!(event.as_str(), "press" | "release" | "click") {
            match ctl_mouse_button(&req.params) {
                Ok(button) => Some(button),
                Err(error) => return Response::err(req.id, ec::BAD_PARAMS, error),
            }
        } else {
            None
        };
        // A wheel event takes EITHER a pre-quantized whole-line count
        // (`wheel_lines`, the historical form) or a raw, possibly fractional
        // detent count (`wheel_delta`, the units winit actually reports).
        // `wheel_delta` is the only synthetic path that runs the real
        // sub-detent accumulator, so it is what lets a test reproduce a
        // precision-touchpad gesture.
        let mut wheel_lines = None;
        let mut wheel_delta = None;
        if event == "wheel" {
            match (
                req.params.get("wheel_delta").and_then(|v| v.as_f64()),
                req.params.get("wheel_lines").and_then(|v| v.as_i64()),
            ) {
                (Some(_), Some(_)) => {
                    return Response::err(
                        req.id,
                        ec::BAD_PARAMS,
                        "pass either 'wheel_delta' or 'wheel_lines', not both",
                    );
                }
                (Some(delta), None) => {
                    if !delta.is_finite() {
                        return Response::err(
                            req.id,
                            ec::BAD_PARAMS,
                            "'wheel_delta' must be finite",
                        );
                    }
                    wheel_delta = Some(delta);
                }
                (None, Some(lines)) => {
                    wheel_lines = Some(lines.clamp(i32::MIN as i64, i32::MAX as i64) as i32);
                }
                (None, None) => {
                    return Response::err(
                        req.id,
                        ec::BAD_PARAMS,
                        "missing 'wheel_lines' integer or 'wheel_delta' number",
                    );
                }
            }
        }
        let event_mods = if req.params.get("mods").is_some() {
            match parse_ctl_mods(req.params.get("mods")) {
                Ok(mods) => mods,
                Err(error) => return Response::err(req.id, ec::BAD_PARAMS, error),
            }
        } else {
            ws.mods
        };
        let x = req.params.get("x").and_then(|v| v.as_f64());
        let y = req.params.get("y").and_then(|v| v.as_f64());
        if !matches!(event.as_str(), "wheel") || x.is_some() || y.is_some() {
            let Some(x) = x else {
                return Response::err(req.id, ec::BAD_PARAMS, "missing numeric 'x'");
            };
            let Some(y) = y else {
                return Response::err(req.id, ec::BAD_PARAMS, "missing numeric 'y'");
            };
            if !x.is_finite() || !y.is_finite() {
                return Response::err(req.id, ec::BAD_PARAMS, "'x' and 'y' must be finite");
            }
            ws.cursor = winit::dpi::PhysicalPosition::new(x, y);
        }

        // Synthetic modifiers apply only to this control event; real winit
        // modifier state resumes immediately afterward.
        let previous_mods = std::mem::replace(&mut ws.mods, event_mods);
        let mut handled = true;
        match event.as_str() {
            "move" => {
                self.ctl_mouse_move(ws);
            }
            "press" => {
                handled = self.ctl_mouse_press(ws, event_loop, button.expect("validated button"));
            }
            "release" => {
                handled = self.ctl_mouse_release(ws, button.expect("validated button"));
            }
            "click" => {
                let bcode = button.expect("validated button");
                let pressed = self.ctl_mouse_press(ws, event_loop, bcode);
                let released = self.ctl_mouse_release(ws, bcode);
                handled = pressed || released;
            }
            "wheel" => {
                handled = match (wheel_delta, wheel_lines) {
                    (Some(delta), _) => self.ctl_mouse_wheel_delta(ws, delta),
                    (None, Some(lines)) => self.ctl_mouse_wheel(ws, lines),
                    (None, None) => unreachable!("wheel params validated above"),
                };
            }
            _ => unreachable!("event validated above"),
        }
        ws.mods = previous_mods;
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        Response::ok(
            req.id,
            serde_json::json!({
                "window": ws.seq,
                "event": event,
                "cursor": [ws.cursor.x, ws.cursor.y],
                "handled": handled,
            }),
        )
    }

    fn ctl_mouse_move(&mut self, ws: &mut WindowState) {
        // A control-driven move back inside the client supersedes a native
        // `CursorLeft` edge latch. Without this reset, mixing the two input
        // sources keeps scrolling even though the latest pointer coordinate is
        // back over the pane.
        ws.selection_autoscroll_edge = 0;
        if self.resize_preview_lane(ws) || self.drag_preview_lane(ws) {
            return;
        }
        // Like the media receipt below, the search lane's hover follows
        // control input so automation can exercise it.
        self.update_search_hover(ws);
        if search_pointer_route(ws.search.open, None, ws.search.pointer_captured())
            == SearchPointerRoute::Bar
        {
            self.search_mouse_drag(ws);
            return;
        }
        self.promote_tab_drag_if_needed(ws);
        if ws.tab_drag_active && ws.tab_drag_press.is_none() && !self.cfg.tab_bar_pos.is_vertical()
        {
            self.reorder_active_tab_for_cursor(ws);
        }
        // `None` is xterm's "no button" code 3, which with the motion bit is
        // the `CSI < 35 ; x ; y M` report DEC 1003 exists to deliver. Motion
        // reaches `send_mouse` without a held button too; otherwise 1003 acts
        // like 1002 while DECRQM still reports it set, and hover highlighting
        // in Neovim, lazygit, btop and fzf goes dead. `send_mouse` decides per
        // mode whether to report.
        // A held button's drag goes where its press did; `report_mouse`
        // picks the button.
        let _ = self.send_mouse(ws, input::MOUSE_NO_BUTTON, true, true);
        if ws.selecting {
            note_selection_drag_motion(ws);
            let area = self.area(ws);
            self.update_selection(ws, area);
        }
        // Control input may expand the receipt for deterministic automation,
        // but it must not retarget the physical cursor or unrelated tab-bar
        // hover state. Only a native CursorMoved event owns those affordances.
        self.update_media_paste_receipt_hover(ws);
    }

    fn ctl_mouse_press(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        bcode: u8,
    ) -> bool {
        // As natively: a card press whose release never came is over, as is
        // a lane's drag, a program still holding this button gets its
        // release, and the press is Kettle's own gesture until a program
        // receives it. Focus leaves any card.
        self.end_lane_resize(ws);
        ws.lane_drag = None;
        self.leave_preview_focus_for_press(ws);
        if bcode == 0 {
            ws.card_press = None;
        }
        if ws.card_focus.take().is_some() {
            ws.accessibility_pending = true;
        }
        self.release_held_buttons(ws, |held| held.button == bcode);
        ws.held_buttons.pressed(bcode, None, (0, 0));
        if self.confirm_mouse_press(ws, event_loop, bcode) {
            return true;
        }
        let bar = self.tab_bar(ws);
        let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
        if ws.context_menu.is_some()
            && let Some(click) = self.context_menu_click_action(ws, bcode)
        {
            self.dispatch_context_menu_click(ws, click, event_loop);
            return true;
        }
        if ws.context_menu.is_some() && bcode != 2 {
            ws.context_menu = None;
            return true;
        }
        if search_pointer_route(
            ws.search.open,
            Some(self.cursor_in_search_bar(ws)),
            ws.search.dragging_editor,
        ) == SearchPointerRoute::Bar
        {
            if bcode == 0 {
                self.search_mouse_press(ws);
            }
            return true;
        }
        if ws.settings_nav.is_some()
            && (bcode == 0 || bcode == 2)
            && self.settings_mouse(ws, if bcode == 2 { -1 } else { 1 }, true)
        {
            return true;
        }
        if modal_swallows_pointer(self.pointer_modal_open(ws), ws.context_menu.is_some()) {
            return true;
        }
        if self.press_preview_lane(ws, px, py, bcode) {
            return true;
        }
        if self.press_card(ws, px, py, bcode) {
            return true;
        }
        if tab_bar_pointer_region_contains(&bar, px, py) && (bcode == 0 || bcode == 1) {
            if bcode == 0 && bar.new_tab_menu.2 > 0.0 && rect_contains(bar.new_tab_menu, px, py) {
                let (ax, ay, _, ah) = bar.new_tab_menu;
                self.open_new_tab_menu(ws, ax, ay + ah);
            } else if bcode == 0 && rect_contains(bar.new_tab, px, py) {
                let area = self.area(ws);
                let (cols, rows) = self.grid_of(ws, area);
                let geometry = self.pty_geometry_for_grid(ws, cols, rows);
                match ws.mux.new_tab_geometry(&self.cfg, geometry, self.waker()) {
                    // Fire TabAdd so Lua / dev-record see tabs opened via the
                    // agent `+` click, like every other new-tab path.
                    Ok(()) => self.fire_tab_add_event(ws),
                    Err(e) => log::warn!("could not open a new tab (agent send_mouse): {e}"),
                }
            } else if bcode == 0
                && bar.scroll_left.2 > 0.0
                && rect_contains(bar.scroll_left, px, py)
            {
                ws.mux.prev_tab();
            } else if bcode == 0
                && bar.scroll_right.2 > 0.0
                && rect_contains(bar.scroll_right, px, py)
            {
                ws.mux.next_tab();
            } else if let Some(seg) = bar
                .segments
                .iter()
                .find(|seg| rect_contains(seg.rect, px, py))
            {
                let close = bcode == 1 || rect_contains(seg.close, px, py);
                if close {
                    // Same close as the GUI ✕/middle-click above, so the same
                    // `ask-before-closing` question — an agent driving the tab
                    // bar must not be a way around the user's own policy.
                    let (panes, busy) = tab_close_scope(ws, seg.idx);
                    if let Some(anchor) =
                        Some(ws.mux.tab_anchor_panes(seg.idx)).filter(|a| !a.is_empty())
                        && self.confirm_close(
                            ws,
                            self.ui_text.confirm_close_tab(panes as u64),
                            panes,
                            busy,
                            ConfirmAction::CloseTabHolding(anchor),
                        )
                    {
                        // Handled: the press raised the prompt, so it must not
                        // also reach the pane underneath.
                        return true;
                    }
                    let pre = self.focus_key(ws);
                    let closing_idx = seg.idx;
                    if ws.mux.close_tab_at(seg.idx) {
                        self.fire_tab_close_event(ws, closing_idx);
                        self.save_session(ws);
                        self.request_window_close(ws.seq);
                    } else {
                        self.fire_tab_close_event(ws, closing_idx);
                        self.note_focus_change(ws, pre);
                    }
                } else {
                    let pre = self.focus_key(ws);
                    ws.mux.active = seg.idx;
                    ws.mux.touch_active_tab_seen();
                    self.note_focus_change(ws, pre);
                    if bcode == 0 {
                        ws.tab_drag_active = true;
                        ws.tab_drag_press = Some((px, py));
                        ws.tab_pressed_idx = Some(seg.idx);
                        if self.cfg.detachable_tabs {
                            ws.detach_drag =
                                crate::detach::DragState::on_mouse_down_on_tab(seg.idx);
                            ws.drag_press = Some((px, py));
                        }
                    }
                }
            }
            self.resize_all(ws);
            return true;
        }

        let area = self.area(ws);
        if self.activate_media_paste_receipt_at(ws, px, py, bcode) {
            return true;
        }
        let pre = self.focus_key(ws);
        ws.mux.focus_at(area, px, py);
        self.note_focus_change(ws, pre);
        if bcode == 2 {
            let offer_copied = ws.mods.shift_key();
            self.open_context_menu(ws, px, py, offer_copied);
            return true;
        }
        if self.send_mouse(ws, bcode, true, false) {
            return true;
        }
        if bcode == 0 {
            self.begin_or_extend_mouse_selection(ws, area);
            return true;
        }
        false
    }

    fn ctl_mouse_release(&mut self, ws: &mut WindowState, bcode: u8) -> bool {
        // As natively: a gesture of Kettle's own ends with its release.
        ws.held_buttons.end_own(bcode);
        if bcode == 0 && ws.lane_resize.is_some() {
            self.end_lane_resize(ws);
            return true;
        }
        if bcode == 0
            && let Some(drag) = ws.lane_drag.take()
        {
            self.end_lane_drag(ws, drag);
            return true;
        }
        if bcode == 0
            && search_pointer_route(ws.search.open, None, ws.search.pointer_captured())
                == SearchPointerRoute::Bar
        {
            ws.search.dragging_editor = false;
            self.search_button_release(ws);
            return true;
        }
        let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
        if self.release_card(ws, px, py, bcode) {
            return true;
        }
        // The release goes where its press did, if a program got it.
        let mut handled = self.send_mouse(ws, bcode, false, false);
        if selection_release_matches(ws.selection_button, bcode) {
            self.finish_selection_gesture(ws);
            handled = true;
        }
        if bcode == 0 {
            ws.scrollbar_drag_offset = None;
            ws.dragging_split = None;
            ws.tab_drag_active = false;
            ws.tab_drag_press = None;
            ws.tab_pressed_idx = None;
            ws.detach_drag = std::mem::take(&mut ws.detach_drag).on_mouse_up();
            ws.drag_press = None;
            ws.pane_drag = None;
            handled = true;
        }
        handled
    }

    /// ctl/MCP `send_mouse {event:"wheel"}` with a pre-quantized whole-line
    /// count. The caller has already decided how many lines to move, so this
    /// skips the accumulator and derives detents from the historical
    /// 3-lines-per-notch ratio.
    fn ctl_mouse_wheel(&mut self, ws: &mut WindowState, lines: i32) -> bool {
        if lines == 0 {
            return false;
        }
        // At least one detent in the same direction, so callers that inject a
        // single line still cycle exactly one tab / one font step.
        let notches = match lines / 3 {
            0 => lines.signum(),
            n => n,
        };
        self.dispatch_wheel(
            ws,
            input::WheelSteps {
                notches,
                lines,
                cols: 0,
            },
        )
    }

    /// ctl/MCP `send_mouse {event:"wheel", wheel_delta:<f64>}` with a RAW,
    /// possibly fractional detent count — the same units winit reports.
    ///
    /// This is the only synthetic path that exercises the real accumulator, so
    /// it is what lets an automated test reproduce a precision-touchpad gesture
    /// (a stream of ~0.08-detent events). The integer `wheel_lines` form cannot,
    /// because it enters downstream of quantization.
    fn ctl_mouse_wheel_delta(&mut self, ws: &mut WindowState, notches: f64) -> bool {
        if self.lane_takes_wheel(ws) {
            ws.wheel.reset();
            self.wheel_over_lane(
                ws,
                &winit::event::MouseScrollDelta::LineDelta(0.0, notches as f32),
            );
            return true;
        }
        ws.lane_wheel.reset();
        let steps = ws.wheel.feed(
            &winit::event::MouseScrollDelta::LineDelta(0.0, notches as f32),
            self.cfg.scroll_multiplier,
        );
        if steps.is_zero() {
            // Banked as residue — a real gesture needs several of these before
            // the first whole step comes out.
            return false;
        }
        self.dispatch_wheel(ws, steps)
    }

    /// The shared wheel ladder, downstream of quantization.
    ///
    /// Both the real winit `MouseWheel` event and the ctl/MCP `send_mouse`
    /// injections land here so the two cannot drift apart, and automation
    /// exercises the same terminal the user does.
    ///
    /// `steps.notches` drives discrete consumers (one action per physical
    /// detent, independent of `scroll-multiplier`); `steps.lines` drives
    /// continuous ones. Returns whether the wheel was consumed.
    fn dispatch_wheel(&mut self, ws: &mut WindowState, steps: input::WheelSteps) -> bool {
        self.sync_pane_focus_reports(ws);
        // Wheel over an open context menu scrolls its rows, one row per notch
        // (Terminator menu UX). It pre-empts every other wheel dispatch so a
        // 512-entry Theme submenu scrolls instead of leaking through to the
        // pane, tab bar, or font zoom. Swallowed even mid-detent, so a slow
        // touchpad gesture can't leak past the menu while its residue builds.
        if ws.context_menu.is_some() {
            if steps.notches != 0 {
                // Wheel up = notches > 0 = scroll up = decrement
                // offset; wheel down = notches < 0 = scroll down.
                self.scroll_context_menu(ws, -(steps.notches as isize));
            }
            return true;
        }
        // A wheel over a lane is the lane's: it pans a rendered item or
        // scrolls a source, and reaches nothing behind it.
        if self.lane_takes_wheel(ws) {
            self.wheel_steps_over_lane(ws, steps);
            return true;
        }
        // Wheel over a settings field adjusts it (up = forward, down = backward).
        // A wheel outside the panel does not dismiss it; it falls through to the
        // modal swallow below. One field step per detent, so a touchpad can't
        // blow through a 512-entry Theme list.
        if ws.settings_nav.is_some()
            && steps.notches != 0
            && self.settings_mouse(ws, steps.notches.signum(), false)
        {
            return true;
        }
        // Search owns the wheel, but uses it for local scrollback
        // browsing so users can inspect nearby historical matches.
        // Never encode tracking/alternate-scroll bytes into the TUI
        // behind the lane.
        if ws.search.open {
            if steps.lines != 0 {
                self.scroll_search_viewport(ws, steps.lines);
            }
            return true;
        }
        // Any other open modal swallows the wheel too, so Ctrl+wheel can't zoom
        // the font and a plain or Shift wheel can't scroll the pane or cycle tabs
        // behind it. The context menu consumed its wheel above, so it is `None`
        // here and `modal_swallows_pointer` reduces to "any modal open".
        if modal_swallows_pointer(self.any_modal_open(ws), ws.context_menu.is_some()) {
            return true;
        }
        // Wheel over the tab bar cycles tabs (kitty / iTerm2 /
        // Ghostty parity). Each detent moves one
        // tab regardless of `scroll-multiplier` so the gesture
        // stays predictable — multiple lines from a fast scroll
        // collapse to a single tab change, like the real apps.
        //
        // A horizontal swipe over the bar cycles too: the strip has no
        // independent scroll offset (`tab_strip_layout` derives its window from
        // the ACTIVE tab), so moving the selection IS how the bar scrolls.
        // Positive = "backwards" on both axes, matching winit's documented
        // convention that +Y scrolls up and +X scrolls left.
        if self.cursor_in_tab_bar(ws) && ws.mux.tabs.len() > 1 {
            let step = if steps.notches != 0 {
                steps.notches
            } else {
                steps.cols
            };
            if step != 0 {
                if step > 0 {
                    ws.mux.prev_tab();
                } else {
                    ws.mux.next_tab();
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            return true;
        }
        // Terminator parity: Ctrl+wheel resizes the font. It runs BEFORE the
        // mouse-tracking pass-through so it works even when a TUI like tmux or
        // htop has mouse tracking on, as in gnome-terminal, Terminator, and
        // xterm. `cfg.disable_mousewheel_zoom = true` opts out for users who
        // scroll-zoom by accident on a touchpad. The step size matches the
        // keyboard IncreaseFontSize / DecreaseFontSize actions.
        let zoom_owns_wheel = ws.mods.control_key() && !self.cfg.disable_mousewheel_zoom;
        if let Some(sign) = should_zoom_font(
            ws.mods.control_key(),
            steps.notches,
            self.cfg.disable_mousewheel_zoom,
        ) && let Some(r) = ws.renderer.as_mut()
        {
            // Step logical size, not the now-physical
            // cell_h (which would double-apply the DPI scale).
            let new = if sign > 0 {
                r.font_size() + 1.0
            } else {
                r.font_size() - 1.0
            };
            r.set_font_size(new);
            self.resize_all(ws);
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
            return true;
        }
        if zoom_owns_wheel {
            // Ctrl is held and zoom is enabled, but this event was only a
            // fraction of a detent. Swallow it rather than letting a
            // mid-gesture Ctrl+wheel scroll the pane instead of zooming it.
            return true;
        }
        let Some((wheel_pane, wheel_rect)) = self.wheel_target(ws) else {
            return true;
        };
        // Shift+wheel always scrolls the kettle scrollback even
        // when a TUI has mouse-tracking on (xterm convention).
        // Without this bypass, you can't scroll back through
        // your tmux/htop session — the TUI swallows every wheel
        // notch.
        let mode = self
            .pane_mode(ws, wheel_pane)
            .unwrap_or(kettle_core::TermMode::empty());
        let (track, _) = input::mouse_tracking(mode);
        let track_active = track != input::MouseTracking::Off && !ws.mods.shift_key();
        if track_active {
            // Horizontal wheel reports as xterm buttons 6/7 (encoded 66/67)
            // alongside the vertical 64/65. `mouse_encode` passes any
            // `btn >= 64` through unchanged, so no encoder change is needed.
            let mut reported = false;
            if steps.lines != 0 {
                let btn = if steps.lines > 0 { 64 } else { 65 };
                for _ in 0..steps.lines.unsigned_abs().min(8) {
                    reported |= self
                        .send_mouse_to(
                            ws,
                            wheel_pane,
                            MouseAt::Pointer(wheel_rect),
                            btn,
                            true,
                            false,
                        )
                        .consumed();
                }
            }
            if steps.cols != 0 {
                let btn = if steps.cols > 0 { 66 } else { 67 };
                for _ in 0..steps.cols.unsigned_abs().min(8) {
                    reported |= self
                        .send_mouse_to(
                            ws,
                            wheel_pane,
                            MouseAt::Pointer(wheel_rect),
                            btn,
                            true,
                            false,
                        )
                        .consumed();
                }
            }
            if reported {
                return true;
            }
            // `send_mouse_to` declined every report because the pane is read-only
            // (or Shift re-entered mid-gesture). Fall through to local scrollback
            // so a read-only pane running a mouse-tracking TUI still scrolls.
        } else if !ws.mods.shift_key()
            && steps.lines != 0
            && let Some(bytes) = input::alternate_scroll_key(steps.lines, mode)
        {
            let result = ws
                .mux
                .panes
                .get(&wheel_pane)
                .map(|pane| pane.feed_input(&bytes))
                .unwrap_or(PaneInputResult::Queued);
            self.report_input_result(result);
            Self::dismiss_media_paste_receipt_after_input(ws, wheel_pane, result);
            if result != PaneInputResult::ReadOnly {
                return true;
            }
        }
        if steps.lines != 0 {
            if let Some(pane) = ws.mux.panes.get(&wheel_pane)
                && let Ok(mut t) = pane.term.term.lock()
            {
                t.scroll_display(Scroll::Delta(steps.lines));
            }
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
        true
    }

    fn scroll_search_viewport(&mut self, ws: &mut WindowState, lines: i32) -> bool {
        let Some(pane_id) = ws.search.target_pane else {
            return true;
        };
        if let Some(pane) = ws.mux.panes.get(&pane_id)
            && let Ok(mut term) = pane.term.term.lock()
        {
            term.scroll_display(Scroll::Delta(lines));
            ws.search.visible_key = None;
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        true
    }

    fn promote_tab_drag_if_needed(&mut self, ws: &mut WindowState) {
        if let Some((ox, oy)) = ws.tab_drag_press {
            let dx = ws.cursor.x as f32 - ox;
            let dy = ws.cursor.y as f32 - oy;
            if (dx * dx + dy * dy).sqrt() > tab_reorder_drag_threshold_px(self.tab_bar_h(ws)) {
                ws.tab_drag_press = None;
                ws.tab_pressed_idx = None;
            }
        }
    }

    fn reorder_active_tab_for_cursor(&mut self, ws: &mut WindowState) {
        let bar = self.tab_bar(ws);
        if bar.height <= 0.0 || bar.segments.is_empty() {
            return;
        }
        let target = tab_drag_target_index(ws.cursor.x as f32, ws.cursor.y as f32, &bar.segments);
        let delta = target as i32 - ws.mux.active as i32;
        if delta != 0 && ws.mux.move_active_tab(delta) {
            ws.mux.touch_active_tab_seen();
        }
    }

    /// `screenshot`: queue a live-surface PNG capture and reply when the next
    /// rendered frame saves it. Defaults to the focused pane crop; pass
    /// `{full_window:true}` to capture the whole window, pass all four `crop_*`
    /// values for a physical-pixel window region, or use `{path:"…"}` to choose
    /// the output file.
    fn ctl_screenshot(
        &mut self,
        ws: &mut WindowState,
        req: &kettle_ctl::protocol::Request,
        reply: crate::ctl_server::ReplyTx,
    ) {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let full_window = req
            .params
            .get("full_window")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let explicit_crop = match screenshot_crop(&req.params) {
            Ok(crop) => crop,
            Err(message) => {
                let _ = reply.send(Response::err(req.id, ec::BAD_PARAMS, message));
                return;
            }
        };
        if explicit_crop.is_some() && req.params.get("pane").is_some() {
            let _ = reply.send(Response::err(
                req.id,
                ec::BAD_PARAMS,
                "an explicit crop cannot be combined with pane; crop coordinates are window-relative",
            ));
            return;
        }
        if explicit_crop.is_some() && full_window {
            let _ = reply.send(Response::err(
                req.id,
                ec::BAD_PARAMS,
                "an explicit crop cannot be combined with full_window=true",
            ));
            return;
        }
        let pane = if (full_window || explicit_crop.is_some()) && req.params.get("pane").is_none() {
            None
        } else {
            match self.ctl_resolve_pane(ws, &req.params) {
                Ok(p) => Some(p),
                Err((code, message)) => {
                    let _ = reply.send(Response::err(req.id, code, message));
                    return;
                }
            }
        };
        let target_seq = match pane {
            Some(id) if ws.mux.panes.contains_key(&id) => Some(ws.seq),
            Some(id) => self
                .windows
                .values()
                .find(|w| w.mux.panes.contains_key(&id))
                .map(|w| w.seq),
            None => Some(ws.seq),
        };
        let Some(target_seq) = target_seq else {
            let _ = reply.send(Response::err(req.id, ec::NO_SUCH_PANE, "pane vanished"));
            return;
        };
        let target_accepts_capture = {
            let target = if target_seq == ws.seq {
                Some(&*ws)
            } else {
                self.windows.get(&target_seq)
            };
            target
                .and_then(|target| {
                    target
                        .window
                        .as_ref()
                        .map(|window| (window, target.window_shown))
                })
                .is_some_and(|(window, shown)| {
                    screenshot_window_accepts_control_capture(
                        window.is_minimized(),
                        shown,
                        window.is_visible(),
                    )
                })
        };
        if !target_accepts_capture {
            let _ = reply.send(Response::err(
                req.id,
                ec::BUSY,
                "target window is minimized, hidden, or not yet shown; restore it before capturing",
            ));
            return;
        }
        let crop = if let Some(crop) = explicit_crop {
            Some(crop)
        } else if full_window {
            None
        } else {
            let Some(pane_id) = pane else {
                let _ = reply.send(Response::err(req.id, ec::BAD_PARAMS, "missing pane"));
                return;
            };
            let target = if target_seq == ws.seq {
                Some(&*ws)
            } else {
                self.windows.get(&target_seq)
            };
            target.and_then(|target| {
                let area = self.area(target);
                let active = target.mux.active;
                // A pane screenshot shows the whole pane, its titlebar and
                // lane included.
                target
                    .mux
                    .leaves(active, area)
                    .into_iter()
                    .find(|(id, _)| *id == pane_id)
                    .map(|(_, rect)| rect)
            })
        };
        if !full_window && crop.is_none() {
            let _ = reply.send(Response::err(
                req.id,
                ec::BUSY,
                self.ui_text
                    .text(kettle_i18n::Text::CtlScreenshotPaneNotVisible),
            ));
            return;
        }
        // A pane in a background tab or behind another pane's zoom has no
        // rectangle to crop; refuse rather than capture the whole window.
        if !full_window && crop.is_none() {
            let _ = reply.send(Response::err(
                req.id,
                ec::BUSY,
                self.ui_text
                    .text(kettle_i18n::Text::CtlScreenshotPaneNotVisible),
            ));
            return;
        }
        let (path, output_policy) = match req.params.get("path").and_then(|v| v.as_str()) {
            // Reject an existing destination up front for a prompt response; the
            // renderer independently enforces create-new, owner-only publication
            // after this metadata probe. See `validate_screenshot_path` for the
            // full threat model.
            Some(s) => match validate_screenshot_path(s) {
                Ok(p) => (p, kettle_render::ScreenshotOutputPolicy::UserSelected),
                Err(message) => {
                    let _ = reply.send(Response::err(req.id, ec::BAD_PARAMS, message));
                    return;
                }
            },
            None => {
                let secs = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);
                let cache = cache_dir_from_env(|k| std::env::var(k).ok());
                (
                    session_screenshot_path(secs, std::process::id(), cache.as_deref()),
                    kettle_render::ScreenshotOutputPolicy::PrivateState,
                )
            }
        };
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let cancellation = kettle_render::ScreenshotCancellation::default();
        let renderer = if target_seq == ws.seq {
            ws.renderer.as_mut()
        } else {
            self.windows
                .get_mut(&target_seq)
                .and_then(|w| w.renderer.as_mut())
        };
        let Some(renderer) = renderer else {
            let _ = reply.send(Response::err(
                req.id,
                ec::INTERNAL,
                "target window has no renderer",
            ));
            return;
        };
        let screenshot = kettle_render::ScreenshotRequest {
            out_path: path.clone(),
            output_policy,
            crop,
            completion: Some(done_tx),
            cancellation: Some(cancellation.clone()),
            recovery_wake: {
                let proxy = self.proxy.clone();
                Some(kettle_render::ScreenshotRecoveryWake::new(move || {
                    let _ = proxy.send_event(UserEvent::Wakeup);
                }))
            },
        };
        if renderer.set_pending_screenshot(screenshot).is_err() {
            let _ = reply.send(Response::err(
                req.id,
                ec::BUSY,
                "another screenshot capture is already in progress",
            ));
            return;
        }
        if target_seq == ws.seq {
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
        } else if let Some(target) = self.windows.get(&target_seq)
            && let Some(w) = &target.window
        {
            w.request_redraw();
        }
        let request_id = req.id;
        std::thread::spawn(move || {
            let response_for_result = |result| match result {
                Ok(saved) => Response::ok(
                    request_id,
                    serde_json::json!({
                        "path": saved,
                        "pane": pane,
                        "window": target_seq,
                        "full_window": full_window,
                        "crop": explicit_crop,
                    }),
                ),
                Err(error) => Response::err(request_id, ec::INTERNAL, error),
            };
            let resp = match done_rx.recv_timeout(std::time::Duration::from_secs(10)) {
                Ok(result) => response_for_result(result),
                Err(std::sync::mpsc::RecvTimeoutError::Timeout) if cancellation.cancel() => {
                    Response::err(request_id, ec::INTERNAL, "screenshot capture timed out")
                }
                Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                    // The encoder already won the final publication race. Give
                    // the atomic link/rename and directory sync one finite
                    // grace period, but never turn the advertised ten-second
                    // deadline into an unbounded control thread. If even this
                    // expires, report the only honest outcome: publication may
                    // have happened and the caller must inspect the path.
                    match done_rx.recv_timeout(std::time::Duration::from_secs(5)) {
                        Ok(result) => response_for_result(result),
                        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => Response::err(
                            request_id,
                            ec::INTERNAL,
                            "screenshot publication did not finish within the extended deadline; the destination may exist",
                        ),
                        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => Response::err(
                            request_id,
                            ec::INTERNAL,
                            "screenshot worker disconnected after publication began",
                        ),
                    }
                }
                Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                    let _ = cancellation.cancel();
                    Response::err(
                        request_id,
                        ec::INTERNAL,
                        "screenshot capture worker disconnected",
                    )
                }
            };
            let _ = reply.send(resp);
        });
    }

    /// `send_text`: write text to a pane's PTY (default: focused).
    fn ctl_send_text(
        &mut self,
        ws: &mut WindowState,
        conn_id: u64,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        self.sync_pane_focus_reports(ws);
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let pane = match self.ctl_resolve_pane(ws, &req.params) {
            Ok(p) => p,
            Err((code, message)) => return Response::err(req.id, code, message),
        };
        let Some(text) = req.params.get("text").and_then(|v| v.as_str()) else {
            return Response::err(req.id, ec::BAD_PARAMS, "missing 'text' string");
        };
        if self.preview_holds_keyboard(ws, pane) {
            return Response::err(req.id, ec::BUSY, PREVIEW_HOLDS_KEYBOARD);
        }
        let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) else {
            return Response::err(req.id, ec::NO_SUCH_PANE, "pane vanished");
        };
        // An agent acts as the user — the per-pane read-only
        // toggle (Terminator parity) blocks it like any other input, with an
        // explicit error instead of a silent drop.
        let result = p.feed_input(text.as_bytes());
        if let Some((code, message)) = ctl_input_error(result) {
            return Response::err(req.id, code, message);
        }
        if !text.is_empty() {
            self.dismiss_media_paste_receipt_for_pane(ws, pane);
        }
        log::info!(
            "agent-server: send_text conn={conn_id} pane={pane} ({} bytes)",
            text.len()
        );
        self.ctl_attach(ws, conn_id, pane);
        Response::ok(
            req.id,
            serde_json::json!({"pane": pane, "bytes": text.len()}),
        )
    }

    /// `send_keys`: press named keys and chords in a pane. `send_text` only
    /// types literal characters (CR included), so it cannot press Escape,
    /// arrows, Ctrl-chords, or F-keys (the keys that drive vim, htop, fzf, and
    /// tmux). Tokens go through the SAME `input::encode` path as GUI keystrokes,
    /// against the pane's LIVE terminal mode, so arrows honor DECCKM
    /// application-cursor mode like a human's key press.
    ///
    /// Params: `{pane?: u64, keys: ["escape", "ctrl+c", "down", "G", …]}`.
    /// All tokens are parsed BEFORE any byte is written, so a typo mid-sequence
    /// cannot leave the target app half-keyed.
    fn ctl_send_keys(
        &mut self,
        ws: &mut WindowState,
        conn_id: u64,
        req: &kettle_ctl::protocol::Request,
    ) -> kettle_ctl::protocol::Response {
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let pane = match self.ctl_resolve_pane(ws, &req.params) {
            Ok(p) => p,
            Err((code, message)) => return Response::err(req.id, code, message),
        };
        let Some(keys) = req.params.get("keys").and_then(|v| v.as_array()) else {
            return Response::err(
                req.id,
                ec::BAD_PARAMS,
                "missing 'keys' array of key tokens (e.g. [\"escape\",\"ctrl+c\"])",
            );
        };
        let parsed = match parse_ctl_send_key_batch(keys) {
            Ok(parsed) => parsed,
            Err(message) => return Response::err(req.id, ec::BAD_PARAMS, message),
        };
        // The user gave the keyboard to a preview in that window: nothing
        // is typed into it until they take it back.
        if self.preview_holds_keyboard(ws, pane) {
            return Response::err(req.id, ec::BUSY, PREVIEW_HOLDS_KEYBOARD);
        }
        let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) else {
            return Response::err(req.id, ec::NO_SUCH_PANE, "pane vanished");
        };
        let mut bytes = Vec::new();
        let mut encoded_keys = Vec::with_capacity(parsed.len());
        for (token, mods, key) in &parsed {
            // The live mode decides the byte form (app-cursor arrows etc.).
            // Only modified Enter needs the termios/OSC 133 context sample.
            let mode = p.effective_key_mode(
                self.cfg.modify_other_keys,
                key_is_modified_enter(key, *mods),
            );
            if let Some(b) = crate::input::encode_key_press(key, *mods, mode) {
                // Honor the user's backspace-binding / delete-binding remap,
                // exactly like the GUI key path.
                let b = if crate::input::key_press_uses_kitty_sequence(key, *mods, mode) {
                    b
                } else {
                    apply_bs_del_binding(&self.cfg, key, b)
                };
                if let Err(message) = extend_ctl_send_key_bytes(&mut bytes, &b) {
                    return Response::err(req.id, ec::BAD_PARAMS, message);
                }
                encoded_keys.push(b);
            } else {
                let message = if mode.intersects(kettle_core::TermMode::KITTY_KEYBOARD_PROTOCOL) {
                    format!(
                        "'{token}' has no encoding in this pane's negotiated Kitty keyboard mode"
                    )
                } else {
                    format!(
                        "'{token}' has no legacy encoding; this pane has not negotiated the Kitty keyboard protocol"
                    )
                };
                return Response::err(req.id, ec::BAD_PARAMS, message);
            }
        }
        // The per-pane read-only toggle blocks agents
        // like any other input, with an explicit error.
        let result = p.feed_key_inputs(&encoded_keys);
        if let Some((code, message)) = ctl_input_error(result) {
            return Response::err(req.id, code, message);
        }
        if !encoded_keys.is_empty() {
            self.dismiss_media_paste_receipt_for_pane(ws, pane);
        }
        log::info!(
            "agent-server: send_keys conn={conn_id} pane={pane} ({} keys, {} bytes)",
            parsed.len(),
            bytes.len()
        );
        self.ctl_attach(ws, conn_id, pane);
        Response::ok(
            req.id,
            serde_json::json!({"pane": pane, "keys": parsed.len(), "bytes": bytes.len()}),
        )
    }

    /// Resolve the `pane` param to a pane id; default to the focused pane.
    /// `Err` with a message when neither resolves.
    fn ctl_resolve_pane(
        &self,
        ws: &WindowState,
        params: &serde_json::Value,
    ) -> Result<u64, (&'static str, String)> {
        use kettle_ctl::protocol::error_codes as ec;

        let pane =
            optional_u64_param(params, "pane").map_err(|message| (ec::BAD_PARAMS, message))?;
        if let Some(p) = pane {
            // An explicit pane id may live in ANY window (pane ids are
            // process-global).
            if ws.mux.panes.contains_key(&p)
                || self.windows.values().any(|w| w.mux.panes.contains_key(&p))
            {
                return Ok(p);
            }
            return Err((ec::NO_SUCH_PANE, format!("no pane with id {p}")));
        }
        ws.mux
            .tabs
            .get(ws.mux.active)
            .map(|t| t.focus)
            .filter(|f| ws.mux.panes.contains_key(f))
            .ok_or_else(|| (ec::NO_SUCH_PANE, "no focused pane".to_string()))
    }

    /// Validate the complete window/tab/pane inventory before any control
    /// method allocates a JSON collection or walks pane layout trees.
    fn ctl_window_inventory_size(&self, ws: &WindowState) -> Option<usize> {
        ctl_bounded_sum(
            self.all_windows(ws)
                .flat_map(|window| [1, window.mux.tabs.len(), window.mux.panes.len()]),
            MAX_CTL_COLLECTION_ITEMS,
        )
    }

    /// Every window, the checked-out one plus the map, ordered by seq, for the
    /// ctl read paths. It iterates without allocating, so the control-plane cap
    /// can be checked before anything is allocated.
    fn all_windows<'a>(
        &'a self,
        ws: &'a WindowState,
    ) -> impl Iterator<Item = &'a WindowState> + 'a {
        use std::ops::Bound::{Excluded, Unbounded};

        self.windows
            .range(..ws.seq)
            .map(|(_, window)| window)
            .chain(std::iter::once(ws))
            .chain(
                self.windows
                    .range((Excluded(ws.seq), Unbounded))
                    .map(|(_, window)| window),
            )
    }

    /// Borrow a pane from the checked-out window or any other window in the map
    /// (pane ids are process-global).
    fn ctl_pane_ref<'a>(
        ws: &'a WindowState,
        windows: &'a std::collections::BTreeMap<u64, WindowState>,
        id: u64,
    ) -> Option<&'a crate::mux::Pane> {
        ws.mux
            .panes
            .get(&id)
            .or_else(|| windows.values().find_map(|w| w.mux.panes.get(&id)))
    }

    /// Mark `conn_id` attached to `pane` + fire the badge transition once.
    fn ctl_attach(&mut self, ws: &mut WindowState, conn_id: u64, pane: u64) {
        let newly = self
            .ctl
            .as_mut()
            .map(|c| c.attach_pane(conn_id, pane))
            .unwrap_or(false);
        if newly {
            self.set_pane_agent_attached(ws, pane, true);
        }
    }

    /// Flip a pane's agent badge and emit the `agent_attached` event so
    /// subscribers and the titlebar update.
    fn set_pane_agent_attached(&mut self, ws: &mut WindowState, pane: u64, attached: bool) {
        // The pane may live in any window.
        let in_ws = ws.mux.panes.contains_key(&pane);
        {
            let p = if in_ws {
                ws.mux.panes.get_mut(&pane)
            } else {
                self.windows
                    .values_mut()
                    .find_map(|w| w.mux.panes.get_mut(&pane))
            };
            let Some(p) = p else { return };
            if p.agent_attached == attached {
                return;
            }
            p.agent_attached = attached;
        }
        self.ctl_broadcast(
            "agent_attached",
            Some(pane),
            serde_json::json!({"attached": attached}),
        );
        // Repaint the owning window so the titlebar badge updates.
        let owner = if in_ws {
            ws.window.as_ref()
        } else {
            self.windows
                .values()
                .find(|w| w.mux.panes.contains_key(&pane))
                .and_then(|w| w.window.as_ref())
        };
        if let Some(w) = owner {
            w.request_redraw();
        }
    }

    /// Broadcast an event to subscribed control connections (no-op when the
    /// server is off or nobody subscribed).
    fn ctl_broadcast(&self, kind: &str, pane: Option<u64>, data: serde_json::Value) {
        if let Some(ctl) = &self.ctl
            && ctl.has_subscribers()
        {
            ctl.broadcast(&kettle_ctl::protocol::Event::new(kind, pane, data));
        }
    }

    /// `run_command`: write `cmd\n` to a pane and defer the reply (stored in a
    /// `PendingRun`) until the next OSC-133 `CommandFinished` for that pane, or
    /// the deadline. A bad request replies immediately over `reply`.
    fn ctl_run_command(
        &mut self,
        ws: &mut WindowState,
        conn_id: u64,
        req: &kettle_ctl::protocol::Request,
        reply: crate::ctl_server::ReplyTx,
    ) {
        self.sync_pane_focus_reports(ws);
        use kettle_ctl::protocol::{Response, error_codes as ec};
        let pane = match self.ctl_resolve_pane(ws, &req.params) {
            Ok(p) => p,
            Err((code, message)) => {
                let _ = reply.send(Response::err(req.id, code, message));
                return;
            }
        };
        let Some(command) = req.params.get("command").and_then(|v| v.as_str()) else {
            let _ = reply.send(Response::err(
                req.id,
                ec::BAD_PARAMS,
                "missing 'command' string",
            ));
            return;
        };
        if self.pending_runs.contains_key(&pane) {
            let _ = reply.send(Response::err(
                req.id,
                ec::BUSY,
                "a run_command is already pending on this pane",
            ));
            return;
        }
        let timeout_s = req
            .params
            .get("timeout_s")
            .and_then(|v| v.as_f64())
            .unwrap_or(15.0)
            .clamp(0.1, 600.0);
        // Include evicted rows so the anchor survives a full scrollback ring.
        let start_line = Self::ctl_pane_ref(ws, &self.windows, pane)
            .and_then(|p| {
                let term = p.term.term.lock().ok()?;
                let grid = term.grid();
                Some(
                    grid.history_origin()
                        .saturating_add(grid.history_size() as u64)
                        .saturating_add(grid.cursor.point.line.0.max(0) as u64),
                )
            })
            .unwrap_or(0);
        if let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) {
            let mut line = command.to_string();
            // Submit with a CARRIAGE RETURN, not a line feed: CR is the Enter
            // key a shell's line editor acts on. Under Windows ConPTY only CR is
            // delivered as Enter (a bare LF is typed but never executes); on a
            // Unix PTY the line discipline's ICRNL maps CR→LF, so CR works on
            // both. (A trailing newline already in `command` is left as-is.)
            if !line.ends_with('\r') && !line.ends_with('\n') {
                line.push('\r');
            }
            // An agent acts as the user — the per-pane read-only
            // toggle (Terminator parity) blocks it, with an explicit error
            // (no PendingRun is registered; nothing was written).
            let result = p.feed_input(line.as_bytes());
            if let Some((code, message)) = ctl_input_error(result) {
                let _ = reply.send(Response::err(req.id, code, message));
                return;
            }
            self.dismiss_media_paste_receipt_for_pane(ws, pane);
        }
        log::info!("agent-server: run_command conn={conn_id} pane={pane}: {command:?}");
        self.ctl_attach(ws, conn_id, pane);
        self.pending_runs.insert(
            pane,
            PendingRun {
                conn_id,
                req_id: req.id,
                start_line,
                deadline: std::time::Instant::now() + std::time::Duration::from_secs_f64(timeout_s),
                reply,
            },
        );
    }

    /// An OSC-133 `CommandFinished` arrived for `pane` — if a
    /// `run_command` is pending there, reply with the exit code, duration, and
    /// the output captured since the command started.
    fn resolve_pending_run(
        &mut self,
        ws: &mut WindowState,
        pane: u64,
        ev: &kettle_core::CommandFinished,
    ) {
        let Some(run) = self.pending_runs.remove(&pane) else {
            return;
        };
        let (captured, line_truncated) = self.ctl_capture_output_since(ws, pane, run.start_line);
        let (output, byte_truncated) = cap_utf8_bytes(captured, MAX_CTL_COMMAND_OUTPUT_BYTES);
        let output_truncated = line_truncated || byte_truncated;
        let resp = kettle_ctl::protocol::Response::ok(
            run.req_id,
            serde_json::json!({
                "pane": pane,
                "exit_code": ev.exit_code,
                "duration_ms": ev.duration.as_millis() as u64,
                "timed_out": false,
                "output": output,
                "output_truncated": output_truncated,
            }),
        );
        let _ = run.reply.send(resp);
    }

    /// Reply `timed_out` to any pending run whose deadline passed
    /// (no OSC-133 completion — usually the shell lacks shell integration), and
    /// immediately resolve any pending run whose pane has CLOSED, so
    /// the agent isn't blocked for the full timeout after a pane vanishes.
    /// Called each event-loop tick from the redraw scheduler.
    fn check_pending_run_deadlines(&mut self, ws: &mut WindowState) {
        if self.pending_runs.is_empty() {
            return;
        }
        // A pending run whose pane no longer exists (closed/reaped) is resolved
        // at once with an error, freeing the blocked connection thread.
        let pending_panes: Vec<u64> = self.pending_runs.keys().copied().collect();
        let orphaned: Vec<u64> = pending_panes
            .into_iter()
            .filter(|pane| Self::ctl_pane_ref(ws, &self.windows, *pane).is_none())
            .collect();
        for pane in orphaned {
            if let Some(run) = self.pending_runs.remove(&pane) {
                let resp = kettle_ctl::protocol::Response::err(
                    run.req_id,
                    kettle_ctl::protocol::error_codes::NO_SUCH_PANE,
                    "pane closed before the command completed",
                );
                let _ = run.reply.send(resp);
            }
        }
        let now = std::time::Instant::now();
        let expired: Vec<u64> = self
            .pending_runs
            .iter()
            .filter(|(_, p)| now >= p.deadline)
            .map(|(&pane, _)| pane)
            .collect();
        for pane in expired {
            let Some(run) = self.pending_runs.remove(&pane) else {
                continue;
            };
            let (captured, line_truncated) =
                self.ctl_capture_output_since(ws, pane, run.start_line);
            let (output, byte_truncated) = cap_utf8_bytes(captured, MAX_CTL_COMMAND_OUTPUT_BYTES);
            let output_truncated = line_truncated || byte_truncated;
            let resp = kettle_ctl::protocol::Response::ok(
                run.req_id,
                serde_json::json!({
                    "pane": pane,
                    "exit_code": serde_json::Value::Null,
                    "timed_out": true,
                    "output": output,
                    "output_truncated": output_truncated,
                    "hint": "no OSC 133 command-end seen — enable shell integration \
                             (kettle --shell-integration <shell>) for exit codes",
                }),
            );
            let _ = run.reply.send(resp);
        }
    }

    /// Capture a pane's output produced since absolute line `start_line` (the
    /// lines a single `run_command` added). Best-effort; empty on a vanished
    /// pane.
    ///
    /// Slices the ABSOLUTE line range `[start_line, cursor]` out of the grid —
    /// NOT "the last N grid lines". A fresh shell's content sits at the TOP of
    /// the screen with blank rows below it, so taking the grid tail would return
    /// those trailing blanks; addressing by absolute line lands on the real
    /// content wherever it is. The cursor's absolute line is the end of the
    /// content the command produced.
    fn ctl_capture_output_since(
        &self,
        ws: &WindowState,
        pane: u64,
        start_line: u64,
    ) -> (String, bool) {
        // The pane may have moved to another window mid-run.
        let Some(p) = Self::ctl_pane_ref(ws, &self.windows, pane) else {
            return (String::new(), false);
        };
        let Ok(term) = p.term.term.lock() else {
            return (String::new(), false);
        };
        let grid = term.grid();
        let origin = grid.history_origin();
        let hist = grid.history_size();
        let screen_top = origin.saturating_add(hist as u64);
        let cursor_abs = screen_top.saturating_add(grid.cursor.point.line.0.max(0) as u64);
        // Request at least one history row so a scrolled viewport cannot shift
        // the scrape away from the active screen. Zero history clamps to zero.
        let take = screen_top
            .saturating_sub(start_line)
            .min(MAX_CTL_SCROLLBACK_LINES as u64)
            .max(1) as usize;
        let s = kettle_core::term::screen_text_of(&term, take);
        drop(term);
        let lines: Vec<&str> = s.text.lines().collect();
        let (start_idx, end_idx, head_dropped) =
            ctl_capture_bounds(origin, hist, start_line, cursor_abs, lines.len());
        if start_idx >= end_idx {
            return (String::new(), head_dropped);
        }
        (lines[start_idx..end_idx].join("\n"), head_dropped)
    }

    /// Claim one bounded remote-command batch and stage it for ordered
    /// dispatch. Sender and receiver share a cross-process lock; PTY
    /// backpressure retains the FIFO head and every suffix for a later retry.
    ///
    /// Current senders emit `send-text-json JSON_STRING`, whose decoded string
    /// is written byte-for-byte to the focused pane's PTY. The legacy
    /// `send-text TEXT` form remains accepted and decodes each `\n` character
    /// pair to newline. Unknown or malformed lines contribute only to one
    /// payload-free warning for the batch and do not count as operations.
    fn claim_remote_command_batch(&mut self, origin_window: u64, now: std::time::Instant) {
        let Some(path) = self.startup.remote_file.clone() else {
            return;
        };
        if !self.pending_remote_commands.is_empty() {
            return;
        }
        match claim_remote_command_file(&path) {
            Ok(RemoteBatchClaim::Empty) => {
                self.remote_spool_claim_pending = false;
                self.remote_command_retry.progressed();
            }
            Ok(RemoteBatchClaim::Busy) => {
                self.remote_command_retry.backpressured(now);
            }
            Ok(RemoteBatchClaim::RejectedMalformed) => {
                self.remote_spool_claim_pending = false;
                log::warn!(
                    "remote-command file at {} was not valid UTF-8 and was cleared without processing",
                    path.display()
                );
                self.remote_command_retry.progressed();
            }
            Ok(RemoteBatchClaim::RejectedOversize) => {
                self.remote_spool_claim_pending = false;
                log::warn!(
                    "remote-command file at {} exceeded the {}-byte \
                     safety limit and was cleared without processing",
                    path.display(),
                    kettle_state::MAX_REMOTE_COMMAND_BYTES
                );
                self.remote_command_retry.progressed();
            }
            Ok(RemoteBatchClaim::Claimed(text)) => {
                self.remote_spool_claim_pending = false;
                self.remote_command_retry.progressed();
                match parse_remote_command_batch(&text, origin_window) {
                    ParsedRemoteCommandBatch::Accepted {
                        commands,
                        unknown_lines,
                    } => {
                        if unknown_lines != 0 {
                            log::warn!(
                                "remote-command batch at {} ignored {unknown_lines} \
                                 unrecognized line(s)",
                                path.display()
                            );
                        }
                        self.pending_remote_commands = commands;
                        if !self.pending_remote_commands.is_empty() {
                            self.remote_command_retry.expedite_if_idle(now);
                        }
                    }
                    ParsedRemoteCommandBatch::RejectedTooMany {
                        operation_count,
                        unknown_lines,
                    } => {
                        log::warn!(
                            "remote-command batch at {} contained {operation_count} operations \
                             (cap {MAX_REMOTE_COMMANDS_PER_BATCH}) and {unknown_lines} \
                             unrecognized line(s); the whole batch was rejected before dispatch",
                            path.display()
                        );
                    }
                }
            }
            Err(error) => {
                log::warn!(
                    "remote-command file at {} could not be claimed: {error}",
                    path.display()
                );
                // A path/permission/type/read failure is not transient queue
                // backpressure. Stop polling at 4 Hz; a later watcher event
                // represents an external repair and will arm a fresh claim.
                self.remote_spool_claim_pending = false;
                self.remote_command_retry.progressed();
            }
        }
    }

    fn report_remote_target_gone(&mut self, pane_id: u64) {
        let now = std::time::Instant::now();
        if should_notify_input_rejection(
            self.last_input_rejection_notice,
            PaneInputResult::Failed,
            now,
        ) {
            let message = format!(
                "A queued remote-file send target pane ({pane_id}) closed before delivery. The command was dropped and was not rerouted."
            );
            log::warn!("{message}");
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleRemoteNotDelivered),
                &self.ui_text.notify_body_remote_not_delivered(pane_id),
            );
            self.last_input_rejection_notice = Some((PaneInputResult::Failed, now));
        }
    }

    fn poll_pending_remote_commands(
        &mut self,
        ws: &mut WindowState,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        if !self.remote_command_retry.is_ready(now) {
            return self.remote_command_retry.remaining(now);
        }
        if self.pending_remote_commands.is_empty() && self.remote_spool_claim_pending {
            self.claim_remote_command_batch(ws.seq, now);
        }
        if self.pending_remote_commands.is_empty() {
            return self.remote_command_retry.remaining(now);
        }

        let mut processed = 0usize;
        let mut processed_send_bytes = 0usize;
        while processed < AUTOMATION_WORK_ITEMS_PER_TURN
            && processed_send_bytes < AUTOMATION_WORK_BYTES_PER_TURN
        {
            let Some(origin_window) = self
                .pending_remote_commands
                .front()
                .map(PendingRemoteCommand::origin_window)
            else {
                break;
            };
            if origin_window != ws.seq {
                if !self.windows.contains_key(&origin_window) {
                    log::warn!(
                        "dropping queued remote command because its originating window \
                         {origin_window} no longer exists"
                    );
                    self.pending_remote_commands.pop_front();
                    self.remote_command_retry.progressed();
                    processed += 1;
                    continue;
                }
                return Some(AUTOMATION_YIELD);
            }

            if matches!(
                self.pending_remote_commands.front(),
                Some(PendingRemoteCommand::SendText { .. })
            ) {
                let fallback = ws.mux.active_focus();
                let target_pane = match self.pending_remote_commands.front_mut() {
                    Some(PendingRemoteCommand::SendText { target_pane, .. }) => {
                        if target_pane.is_none() {
                            *target_pane = fallback;
                        }
                        *target_pane
                    }
                    _ => unreachable!("front was checked as SendText"),
                };
                let Some(target_pane) = target_pane else {
                    self.remote_command_retry.backpressured(now);
                    return self.remote_command_retry.remaining(now);
                };
                let bytes = match self.pending_remote_commands.front() {
                    Some(PendingRemoteCommand::SendText { bytes, .. }) => bytes.clone(),
                    _ => unreachable!("front was checked as SendText"),
                };
                // An action earlier in this batch may have moved focus.
                self.sync_pane_focus_reports(ws);
                let result = if let Some(pane) = ws.mux.panes.get(&target_pane) {
                    Some(pane.feed_input_shared(bytes.clone()))
                } else {
                    self.windows
                        .values()
                        .find_map(|window| window.mux.panes.get(&target_pane))
                        .map(|pane| pane.feed_input_shared(bytes.clone()))
                };
                let Some(result) = result else {
                    self.pending_remote_commands.pop_front();
                    self.remote_command_retry.progressed();
                    self.report_remote_target_gone(target_pane);
                    processed += 1;
                    processed_send_bytes += bytes.len();
                    continue;
                };
                match result {
                    PaneInputResult::Queued | PaneInputResult::ReadOnly => {
                        self.pending_remote_commands.pop_front();
                        self.remote_command_retry.progressed();
                        processed += 1;
                        processed_send_bytes += bytes.len();
                    }
                    PaneInputResult::Backpressured => {
                        self.report_input_result(result);
                        self.remote_command_retry.backpressured(now);
                        return self.remote_command_retry.remaining(now);
                    }
                    PaneInputResult::Oversize | PaneInputResult::Failed => {
                        self.pending_remote_commands.pop_front();
                        self.remote_command_retry.progressed();
                        self.report_input_result(result);
                        processed += 1;
                        processed_send_bytes += bytes.len();
                    }
                }
                continue;
            }

            let Some(command) = self.pending_remote_commands.pop_front() else {
                break;
            };
            self.remote_command_retry.progressed();
            processed += 1;
            match command {
                PendingRemoteCommand::ToggleWindow { .. } => {
                    // Tri-state dropdown toggle (the Quake / Yakuake / Tilda
                    // tradition). A plain hide/show toggle would hide a visible
                    // but unfocused kettle, though the user usually wants it
                    // back in focus.
                    //
                    //   hidden            → show + raise + focus
                    //   visible + focused → hide
                    //   visible + !focused → raise + focus (don't hide)
                    if let Some(w) = &ws.window {
                        let visible = w.is_visible().unwrap_or(true);
                        let focused = w.has_focus();
                        if !visible {
                            w.set_visible(true);
                            w.focus_window();
                        } else if focused {
                            w.set_visible(false);
                        } else {
                            // Visible but unfocused — bring to front +
                            // focus, don't hide. The common "I clicked
                            // away" case.
                            w.focus_window();
                        }
                    }
                }
                PendingRemoteCommand::NewTab { .. } => {
                    // Terminator parity (remote-control verb):
                    // open a new tab via the remote-control IPC channel.
                    // Mirrors the Action::NewTab dispatch and
                    // also fires LuaEvent::TabAdd so plugins
                    // listening for tab_add see remote-triggered tabs
                    // the same as keyboard ones.
                    let area = self.area(ws);
                    let (cols, rows) = self.grid_of(ws, area);
                    let geometry = self.pty_geometry_for_grid(ws, cols, rows);
                    let waker = self.waker();
                    if let Err(e) = ws.mux.new_tab_geometry(&self.cfg, geometry, waker) {
                        log::warn!("remote-control: new-tab failed: {e}");
                    } else {
                        self.fire_tab_add_event(ws);
                    }
                }
                PendingRemoteCommand::SendText { .. } => {
                    unreachable!("SendText is handled without removing a retryable head")
                }
            }
        }
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
        if self.pending_remote_commands.is_empty() {
            self.remote_command_retry.progressed();
            // A watcher event can be consumed while an older suffix is
            // retained. Probe the spool once after progress so that later batch
            // cannot be stranded merely because no new filesystem event fires.
            if self.remote_spool_claim_pending {
                self.claim_remote_command_batch(ws.seq, now);
            }
        }
        if self.pending_remote_commands.is_empty() {
            self.remote_command_retry.remaining(now)
        } else {
            self.remote_command_retry.yield_soon(now);
            self.remote_command_retry.remaining(now)
        }
    }

    fn drain_remote_commands(&mut self, ws: &mut WindowState) {
        self.remote_spool_claim_pending = true;
        let _ = self.poll_pending_remote_commands(ws, std::time::Instant::now());
    }

    fn run_triggers(&mut self, ws: &mut WindowState) {
        if self.compiled_triggers.is_empty() {
            return;
        }
        // An unset throttle means no trigger has fired since construct/reload,
        // so the first match is immediately eligible.
        let now = std::time::Instant::now();
        if !throttle_elapsed(
            self.last_trigger_fire,
            now,
            std::time::Duration::from_secs(2),
        ) {
            return;
        }
        // Don't pulse the user's own window when it's already focused.
        if ws.window_focused {
            return;
        }
        // Pull each pane's bottom-of-screen text. Visible viewport
        // only — scanning the whole scrollback every wakeup would
        // burn CPU on a chatty pane. Last 50 rows is the typical
        // "what just happened" window.
        let snapshots: Vec<String> = {
            let mut out = Vec::with_capacity(ws.mux.panes.len());
            for pane in ws.mux.panes.values() {
                if let Ok(t) = pane.term.term.lock() {
                    use kettle_core::Dimensions;
                    let rows = t.screen_lines();
                    let cols = t.columns();
                    let from = rows.saturating_sub(50);
                    let mut s = String::with_capacity((rows - from) * cols);
                    for r in from..rows {
                        for c in 0..cols {
                            let p = kettle_core::Point::new(
                                kettle_core::Line(r as i32),
                                kettle_core::Column(c),
                            );
                            s.push(t.grid()[p].c);
                        }
                        // Trim the row's grid padding BEFORE the newline, or a
                        // capture group like `(.+)$` embeds up to a full row of
                        // trailing spaces in the spawned command's argv. The
                        // previous row already ends in '\n', so the trim never
                        // eats earlier rows.
                        let keep = s.trim_end_matches(' ').len();
                        s.truncate(keep);
                        s.push('\n');
                    }
                    out.push(s);
                }
            }
            out
        };
        for snap in &snapshots {
            if let Some(action) = match_triggers(snap, &self.compiled_triggers) {
                match action {
                    kettle_config::TriggerAction::Urgency => {
                        if let Some(w) = &ws.window {
                            use winit::window::UserAttentionType;
                            w.request_user_attention(Some(UserAttentionType::Critical));
                            ws.attention_active = true;
                        }
                    }
                    kettle_config::TriggerAction::RunCommand(argv) => {
                        // Terminator parity, `plugins/run_cmd_on_match.py`:
                        // fire-and-forget spawn. Argv form means no
                        // shell expansion at kettle's layer; the
                        // configured command is treated as data, not
                        // a shell string. Spawn errors are logged
                        // but otherwise ignored so a missing binary
                        // doesn't loop spawn-fail every trigger tick.
                        spawn_trigger_command(&argv);
                    }
                }
                self.last_trigger_fire = Some(std::time::Instant::now());
                break;
            }
        }
    }
}

/// The modal text fields `dispatch_ui_key` can drive, in the precedence the
/// real `KeyboardInput` arm applies.
///
/// An enum rather than strings so the dispatch `match` is exhaustive: adding a
/// variant without routing it fails to compile. That is *not* a guarantee that
/// a new modal added to the key handler reaches this enum at all — nothing
/// forces that, which is what
/// `the_control_plane_modal_order_matches_the_real_key_handler` is for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TextModal {
    Confirm,
    Hint,
    Palette,
    ThemePicker,
    SettingsText,
    Settings,
    LayoutPicker,
    Ssh,
    TitleEdit,
    Search,
    Preview,
}

/// Editor text and toggles that an open search bar brings along when it
/// follows focus to another pane (`App::retarget_search_to_focus`). A fresh
/// open fills it from the pane's remembered query and the configured defaults.
#[derive(Debug, Clone, PartialEq, Eq)]
struct SearchCarryOver {
    query: String,
    wrap: bool,
    case_mode: kettle_config::SearchCaseSensitivity,
    invert: bool,
    focused_control: kettle_render::SearchControl,
}

/// The pane an open bar must move to, if any: `None` while the bar already
/// targets the focused pane or nothing is focused.
fn search_retarget(target_pane: Option<u64>, focus: Option<u64>) -> Option<u64> {
    focus.filter(|pane| Some(*pane) != target_pane)
}

/// The bar's state for `pane_id`, scanning from `display_offset`. A non-empty
/// query starts searching immediately; the anchor is derived by the caller
/// once the lane's resize has settled.
fn fresh_search_state(
    pane_id: u64,
    carried: SearchCarryOver,
    display_offset: usize,
    now: std::time::Instant,
) -> crate::search_input::SearchState {
    let mut search = crate::search_input::SearchState {
        open: true,
        target_pane: Some(pane_id),
        editor: crate::search_input::SearchEditor::from_text(
            carried.query,
            kettle_core::MAX_SEARCH_QUERY_BYTES,
        ),
        wrap: carried.wrap,
        case_mode: carried.case_mode,
        invert: carried.invert,
        focused_control: carried.focused_control,
        anchor: None,
        pre_open_display_offset: Some(display_offset),
        ..crate::search_input::SearchState::default()
    };
    if !search.query().is_empty() {
        search.note_edit(now);
    }
    search
}

impl TextModal {
    /// Stable wire spelling, reported by `dispatch_ui_key`.
    const fn as_str(self) -> &'static str {
        match self {
            Self::Confirm => "confirm",
            Self::Hint => "hint_mode",
            Self::Palette => "palette",
            Self::ThemePicker => "theme_picker",
            Self::SettingsText => "settings_text",
            Self::Settings => "settings",
            Self::LayoutPicker => "layout_picker",
            Self::Ssh => "ssh",
            Self::TitleEdit => "title_edit",
            Self::Search => "search",
            Self::Preview => "preview",
        }
    }
}

/// The supported text surface owned by the same modal as a real key event.
fn open_text_modal(ws: &WindowState) -> Option<TextModal> {
    Some(match top_modal(ws)? {
        KeyModal::ConfirmDialog => TextModal::Confirm,
        KeyModal::ContextMenu | KeyModal::ViMode => return None,
        KeyModal::Hint => TextModal::Hint,
        KeyModal::Palette => TextModal::Palette,
        KeyModal::ThemePicker => TextModal::ThemePicker,
        KeyModal::SettingsText => TextModal::SettingsText,
        KeyModal::SettingsCapture | KeyModal::Settings => TextModal::Settings,
        KeyModal::LayoutPicker => TextModal::LayoutPicker,
        KeyModal::Ssh => TextModal::Ssh,
        KeyModal::TitleEdit => TextModal::TitleEdit,
        KeyModal::Search => TextModal::Search,
        KeyModal::Preview => TextModal::Preview,
    })
}

impl App {
    /// Route a key through the same confirmation state machine used by real
    /// winit keyboard events. Unsupported keys are swallowed by the modal.
    fn confirm_dialog_key(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        event_loop: &ActiveEventLoop,
    ) {
        let key = match key {
            Key::Named(NamedKey::Escape) => Some(ConfirmKey::Escape),
            Key::Named(NamedKey::Enter) => Some(ConfirmKey::Enter),
            Key::Named(NamedKey::Tab) => {
                if ws.mods.shift_key() {
                    Some(ConfirmKey::ShiftTab)
                } else {
                    Some(ConfirmKey::Tab)
                }
            }
            Key::Named(NamedKey::ArrowLeft) => Some(ConfirmKey::Left),
            Key::Named(NamedKey::ArrowRight) => Some(ConfirmKey::Right),
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && !ws.mods.control_key()
                    && !ws.mods.alt_key()
                    && !ws.mods.super_key() =>
            {
                match s.to_ascii_lowercase().as_str() {
                    "y" => Some(ConfirmKey::Yes),
                    "n" => Some(ConfirmKey::No),
                    "h" => Some(ConfirmKey::Left),
                    "l" => Some(ConfirmKey::Right),
                    _ => None,
                }
            }
            _ => None,
        };
        if let Some(k) = key
            && let Some(state) = ws.confirm_dialog.as_ref()
        {
            let n = state.buttons.len();
            let focus = state.focus_idx;
            let action = state.on_confirm.clone();
            match confirm_dialog_keypress(focus, n, k) {
                ConfirmKeyResult::Move(idx) => {
                    if let Some(s) = ws.confirm_dialog.as_mut() {
                        s.focus_idx = idx;
                    }
                }
                ConfirmKeyResult::Confirm => {
                    ws.confirm_dialog = None;
                    self.dispatch_confirm_action(ws, action, event_loop);
                }
                ConfirmKeyResult::Cancel => self.cancel_confirm_dialog(ws),
                ConfirmKeyResult::Ignore => {}
            }
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
    }

    /// Key handling for the title-edit overlay (`Edit tab/window/pane title`
    /// and `Edit pane group`). Esc cancels, Enter applies via
    /// [`Self::apply_title_edit`], Backspace deletes one grapheme cluster, the
    /// platform paste chord inserts the clipboard, and everything else that is
    /// real text entry appends.
    ///
    /// Shared by the `KeyboardInput` arm and `dispatch_ui_key`, so end-to-end
    /// tests type into this modal through the same rules as a real keystroke.
    fn title_edit_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        match key {
            Key::Named(NamedKey::Escape) => {
                // The chrome strip `tab_bar_h` materialised for this modal
                // disappears now, so the content rectangle changes and the PTYs
                // must follow it.
                ws.editing_title = None;
                ws.pending_resize = true;
            }
            Key::Named(NamedKey::Enter) => {
                self.apply_title_edit(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                if let Some(state) = ws.editing_title.as_mut() {
                    crate::modal_input::backspace(&mut state.input);
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && let Some(state) = ws.editing_title.as_mut()
                {
                    crate::modal_input::push_text(&mut state.input, &pasted);
                }
            }
            _ => {
                if let Some(s) = crate::modal_input::accept_text(text, ws.mods)
                    && let Some(state) = ws.editing_title.as_mut()
                {
                    crate::modal_input::push_text(&mut state.input, s);
                }
            }
        }
    }

    /// Clipboard text for a modal field, or `None` when the clipboard is empty
    /// or unreadable.
    ///
    /// This does **not** sanitize: a clipboard holding only control characters
    /// still returns `Some`. Callers pair it with `modal_input::push_text`,
    /// which drops control characters and applies the byte cap — so a
    /// control-only paste ends up a no-op there rather than here.
    ///
    /// The overlays that own a plain `String` paste through this.
    ///
    /// The search bar keeps its own paste path: it inserts at a cursor and
    /// reports truncation through `SearchStatus::TooLong`, neither of which
    /// these fields can express.
    fn modal_clipboard_text(&mut self) -> Option<String> {
        let clipboard = self.clipboard.as_mut()?;
        match clipboard.get_text() {
            Ok(text) => (!text.is_empty()).then_some(text),
            Err(error) => {
                log::warn!("modal paste: clipboard read failed: {error}");
                None
            }
        }
    }

    /// Keys for the open search bar. Returns whether the bar used the key.
    ///
    /// The bar claims the keys a native find field would: typing, caret and
    /// word movement, deletion, the clipboard, undo, and its own Enter, Tab,
    /// F3, `Cmd/Ctrl+G` and Escape. Anything else, such as a new tab, font
    /// zoom or a split's resize, goes on to Kettle's shortcuts (see
    /// `search_bar_shortcut`), as the menus of a native app keep working
    /// while its find field has focus.
    fn search_key(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        physical_key: Option<&PhysicalKey>,
        text: Option<&str>,
    ) -> bool {
        let macos = cfg!(target_os = "macos");
        let mods = ws.mods;
        let shortcut = if macos {
            mods.super_key()
        } else {
            mods.control_key()
        };
        // The shortcut key alone, with or without Shift.
        let shortcut_only = shortcut
            && !mods.alt_key()
            && if macos {
                !mods.control_key()
            } else {
                !mods.super_key()
            };
        // Linux leaves Ctrl+Shift chords to the terminal's own shortcuts
        // (`Ctrl+Shift+A` splits, `Ctrl+Shift+X` zooms), apart from the copy
        // and paste pair every Linux terminal uses.
        let shifted_shortcut = !macos && mods.shift_key();
        let word_modifier = if macos {
            option_physically_held(ws)
        } else {
            mods.control_key()
        };
        // Caret movement takes Shift and the word modifier; macOS adds Cmd
        // for the line ends. `Cmd+Opt+Arrow` and Linux's `Alt+Arrow` move
        // focus between splits instead.
        let caret_chord = if macos {
            !mods.control_key() && !(mods.super_key() && mods.alt_key())
        } else {
            !mods.alt_key() && !mods.super_key()
        };
        let no_chord = !mods.control_key() && !mods.super_key() && !mods.alt_key();
        let selecting = mods.shift_key();
        let editor = ws.search.focused_control == kettle_render::SearchControl::Editor;
        // The find shortcut pressed again, with the bar already open, returns
        // to the query and selects it. It is whatever `start_search` is bound
        // to, so a rebound shortcut works too.
        if matches!(
            resolve_keybind_action(&self.cfg.keybinds, Some(key), None, mods),
            Some((_, Action::StartSearch))
        ) {
            ws.search.focused_control = kettle_render::SearchControl::Editor;
            ws.search.editor.select_all();
            self.sync_search_editor_scroll(ws);
            return true;
        }
        let bound =
            resolve_keybind_action(&self.cfg.keybinds, Some(key), physical_key, mods).is_some();
        let typed = search_bar_text(
            crate::modal_input::accept_text(text, ws.mods),
            mods,
            bound,
            cfg!(windows),
        );
        if !search_bar_claims(key, mods, macos, editor, self.cfg.vim_menu_nav) && typed.is_none() {
            return false;
        }
        let letter = |s: &str, want: &str| s.eq_ignore_ascii_case(want);
        let mut edited = false;
        match key {
            Key::Named(NamedKey::Escape) => {
                self.close_search(ws);
            }
            Key::Named(NamedKey::Enter) if no_chord => {
                if editor {
                    let go_back = mods.shift_key() ^ ws.search.invert;
                    self.search_step_match(ws, go_back);
                } else {
                    self.activate_search_control(ws, ws.search.focused_control);
                }
            }
            Key::Named(NamedKey::F3) if no_chord => {
                self.search_step_match(ws, mods.shift_key());
            }
            Key::Named(NamedKey::Tab) if no_chord => {
                let controls = kettle_render::SearchControl::ALL;
                let current = controls
                    .iter()
                    .position(|control| *control == ws.search.focused_control)
                    .unwrap_or(0);
                let next = if mods.shift_key() {
                    (current + controls.len() - 1) % controls.len()
                } else {
                    (current + 1) % controls.len()
                };
                ws.search.focused_control = controls[next];
                ws.search.editor.clear_selection();
            }
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && mods.control_key()
                    && !mods.alt_key()
                    && matches!(s.as_str(), "j" | "k" | "n" | "p") =>
            {
                self.search_step_match(ws, matches!(s.as_str(), "k" | "p"));
            }
            // Cmd/Ctrl+G steps like Enter, as in browsers and macOS text views.
            Key::Character(s) if shortcut_only && letter(s, "g") => {
                self.search_step_match(ws, mods.shift_key());
            }
            Key::Character(s) if shortcut_only && letter(s, "z") => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                edited = if mods.shift_key() {
                    ws.search.editor.redo()
                } else {
                    ws.search.editor.undo()
                };
            }
            Key::Character(s) if shortcut_only && !shifted_shortcut && letter(s, "a") => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                ws.search.editor.select_all();
            }
            Key::Character(s) if shortcut_only && letter(s, "c") => self.search_copy(ws),
            Key::Character(s) if shortcut_only && !shifted_shortcut && letter(s, "x") => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                if let Some(selected) = ws.search.editor.selected_text().map(str::to_string) {
                    if let Some(clipboard) = self.clipboard.as_mut()
                        && let Err(error) = clipboard.set_text(selected)
                    {
                        log::warn!("search cut: clipboard write failed: {error}");
                    }
                    edited = ws
                        .search
                        .editor
                        .insert("", kettle_core::MAX_SEARCH_QUERY_BYTES)
                        .changed;
                }
            }
            Key::Character(s) if shortcut_only && letter(s, "v") => self.search_paste(ws),
            // The text-field keys every macOS text field shares: Ctrl+A / E to
            // the ends, Ctrl+B / F by a character, Ctrl+D / H delete forward and
            // back, Ctrl+K deletes to the end.
            Key::Character(s)
                if macos
                    && editor
                    && mods.control_key()
                    && !mods.super_key()
                    && !mods.alt_key()
                    && !mods.shift_key()
                    && matches!(
                        s.to_ascii_lowercase().as_str(),
                        "a" | "e" | "b" | "f" | "d" | "h" | "k"
                    ) =>
            {
                let search_editor = &mut ws.search.editor;
                match s.to_ascii_lowercase().as_str() {
                    "a" => search_editor.move_home(false),
                    "e" => search_editor.move_end(false),
                    "b" => search_editor.move_left(false, false),
                    "f" => search_editor.move_right(false, false),
                    "d" => edited = search_editor.delete(),
                    "h" => edited = search_editor.backspace(),
                    _ => edited = search_editor.delete_to_end(),
                }
            }
            Key::Named(NamedKey::ArrowLeft) if editor && caret_chord => {
                if macos && shortcut {
                    ws.search.editor.move_home(selecting);
                } else {
                    ws.search.editor.move_left(selecting, word_modifier);
                }
            }
            Key::Named(NamedKey::ArrowRight) if editor && caret_chord => {
                if macos && shortcut {
                    ws.search.editor.move_end(selecting);
                } else {
                    ws.search.editor.move_right(selecting, word_modifier);
                }
            }
            // `Ctrl+Home` / `Ctrl+End` scroll the terminal instead.
            Key::Named(NamedKey::Home) if editor && no_chord => {
                ws.search.editor.move_home(selecting);
            }
            Key::Named(NamedKey::End) if editor && no_chord => {
                ws.search.editor.move_end(selecting);
            }
            Key::Named(NamedKey::Backspace) => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                edited = if macos && shortcut {
                    ws.search.editor.delete_to_start()
                } else if word_modifier {
                    ws.search.editor.delete_word_backward()
                } else {
                    ws.search.editor.backspace()
                };
            }
            Key::Named(NamedKey::Delete) => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                edited = if macos && shortcut {
                    ws.search.editor.delete_to_end()
                } else if word_modifier {
                    ws.search.editor.delete_word_forward()
                } else {
                    ws.search.editor.delete()
                };
            }
            // winit reports the space bar as a named key; `dispatch_ui_key`
            // sends it as a character. Either one presses a focused button.
            Key::Named(NamedKey::Space) if !editor && no_chord => {
                self.activate_search_control(ws, ws.search.focused_control);
            }
            Key::Character(s) if s == " " && !editor && no_chord => {
                self.activate_search_control(ws, ws.search.focused_control);
            }
            _ => {
                // Share the modal text-entry rule with the sibling handlers.
                // The explicit shortcut arms above claim ⌘A/⌘C/⌘X/⌘V; the
                // helper rejects every other Command chord (so ⌘Q never types
                // a `q`) and control characters.
                let Some(t) = typed else {
                    return false;
                };
                ws.search.focused_control = kettle_render::SearchControl::Editor;
                let outcome = ws
                    .search
                    .editor
                    .type_text(t, kettle_core::search::MAX_SEARCH_QUERY_BYTES);
                edited = outcome.changed;
                if outcome.truncated {
                    ws.search.status = kettle_render::SearchStatus::TooLong;
                }
            }
        }
        if edited {
            ws.search.note_edit(std::time::Instant::now());
        }
        if ws.search.open {
            self.sync_search_editor_scroll(ws);
        }
        true
    }

    /// Copy for the search bar: a selection inside the query wins; otherwise
    /// the grid selection the user dragged out under the bar. A grid press
    /// clears the query's selection, so a stale range cannot shadow a fresh
    /// drag (Terminator copies the terminal selection here).
    fn search_copy(&mut self, ws: &mut WindowState) {
        if let Some(selected) = ws.search.editor.selected_text() {
            if let Some(clipboard) = self.clipboard.as_mut()
                && let Err(error) = clipboard.set_text(selected.to_string())
            {
                log::warn!("search copy: clipboard write failed: {error}");
            }
        } else {
            self.copy_selection(ws);
        }
    }

    /// Paste the clipboard into the query.
    fn search_paste(&mut self, ws: &mut WindowState) {
        ws.search.focused_control = kettle_render::SearchControl::Editor;
        let Some(clipboard) = self.clipboard.as_mut() else {
            return;
        };
        match clipboard.get_text() {
            Ok(paste) => {
                let outcome = ws
                    .search
                    .editor
                    .insert(&paste, kettle_core::MAX_SEARCH_QUERY_BYTES);
                if outcome.changed {
                    ws.search.note_edit(std::time::Instant::now());
                }
                if outcome.truncated {
                    ws.search.status = kettle_render::SearchStatus::TooLong;
                }
            }
            Err(error) => log::warn!("search paste: clipboard read failed: {error}"),
        }
    }

    /// Run the Kettle shortcut for a key the search bar did not use, as a
    /// native app's menus keep working while its find field has focus. The
    /// keyboard stays with the bar, so shortcuts that type into the terminal
    /// do nothing, and Copy and Paste act on the query. Returns whether a
    /// shortcut ran.
    fn search_bar_shortcut(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        physical_key: Option<&PhysicalKey>,
        repeat: bool,
        event_loop: &ActiveEventLoop,
    ) -> bool {
        let Some((trigger, action)) =
            resolve_keybind_action(&self.cfg.keybinds, Some(key), physical_key, ws.mods)
        else {
            return false;
        };
        match search_bar_shortcut_kind(&action) {
            SearchBarShortcut::Typing => false,
            SearchBarShortcut::Copy => {
                self.search_copy(ws);
                true
            }
            SearchBarShortcut::Paste => {
                self.search_paste(ws);
                self.sync_search_editor_scroll(ws);
                true
            }
            SearchBarShortcut::Run => {
                // An adaptive focus chord with no split in that direction
                // would go to the program, which does not have the keyboard.
                if self.adaptive_focus_chord_falls_through(ws, trigger, &action) {
                    return false;
                }
                // A held toggle chord toggles once, as on the main keyboard
                // path; its repeats are still the bar's to swallow.
                if !(repeat && toggles_once_per_press(&action)) {
                    self.handle_action(ws, action, event_loop);
                }
                true
            }
        }
    }

    /// Advance the search selection one match forward (`go_back = false`) or
    /// backward, honoring `search-wrap` (`false` stops at the ends instead of
    /// cycling). Enter, F3, the Previous/Next controls, and vim-menu-nav's
    /// Ctrl+j/k/n/p all share this stepping.
    fn search_step_match(&mut self, ws: &mut WindowState, go_back: bool) {
        let query = ws.search.query().to_string();
        if query.is_empty() {
            ws.search.status = kettle_render::SearchStatus::Typing;
            return;
        }
        if ws.search.compiled_revision != Some(ws.search.revision) {
            match kettle_core::CompiledSearch::compile(
                &query,
                map_case_sensitivity(ws.search.case_mode),
            ) {
                Ok(compiled) => {
                    ws.search.compiled = compiled;
                    ws.search.compiled_revision = Some(ws.search.revision);
                }
                Err(error) => {
                    ws.search.status = search_compile_error_status(error);
                    return;
                }
            }
        }
        if ws.search.compiled.is_none() {
            return;
        }
        // Explicit Previous/Next supersedes an idle quiet-verification even if this request is
        // already at a non-wrapping terminal edge and returns before constructing a job.
        cancel_deferred_search_retry(&mut ws.search);
        let Some(pane_id) = ws.search.target_pane else {
            return;
        };
        let Some(pane) = ws.mux.panes.get(&pane_id) else {
            ws.search.status = kettle_render::SearchStatus::NoMatch;
            return;
        };
        let output_generation = pane.term.output_generation();
        let Ok(term) = pane.term.term.lock() else {
            ws.search.set_status_at(
                kettle_render::SearchStatus::Searching,
                std::time::Instant::now(),
            );
            return;
        };
        use kettle_core::Dimensions as _;
        let direction = if go_back {
            kettle_core::SearchDirection::Reverse
        } else {
            kettle_core::SearchDirection::Forward
        };
        let top_line = term.topmost_line().0;
        let bottom_line = term.bottommost_line().0;
        let last_column = term.last_column().0;
        let had_focus = ws.search.focused.is_some();
        let edge_origin = match (direction, ws.search.focused) {
            (kettle_core::SearchDirection::Forward, Some(span)) => span.end,
            (kettle_core::SearchDirection::Reverse, Some(span)) => span.start,
            (_, None) => search_viewport_anchor(
                term.grid().display_offset(),
                term.screen_lines(),
                last_column,
                direction,
            ),
        };
        let mut forced_wrap = false;
        let origin = if ws.search.focused.is_some() {
            match search_point_after(edge_origin, direction, top_line, bottom_line, last_column) {
                Some(point) => point,
                None if ws.search.wrap => {
                    forced_wrap = true;
                    match direction {
                        kettle_core::SearchDirection::Forward => {
                            kettle_core::SearchPoint::new(top_line, 0)
                        }
                        kettle_core::SearchDirection::Reverse => {
                            kettle_core::SearchPoint::new(bottom_line, last_column)
                        }
                    }
                }
                None => {
                    ws.search.status = if go_back {
                        kettle_render::SearchStatus::Start
                    } else {
                        kettle_render::SearchStatus::End
                    };
                    return;
                }
            }
        } else {
            edge_origin
        };
        let edge = match direction {
            kettle_core::SearchDirection::Forward => {
                kettle_core::SearchPoint::new(bottom_line, last_column)
            }
            kettle_core::SearchDirection::Reverse => kettle_core::SearchPoint::new(top_line, 0),
        };
        let token =
            kettle_core::SearchScanToken::capture(&term, ws.search.revision, output_generation);
        drop(term);

        // Enter/F3 navigation uses the same one-chunk-per-event-loop continuation as the idle
        // deep scan. A miss in a multi-million-line history must never block winit while a full
        // edge-to-edge RegexIter runs synchronously.
        ws.search.scan_token = Some(token);
        ws.search.typing_scanned_revision = Some(ws.search.revision);
        ws.search.background = Some(crate::search_input::BackgroundSearch {
            token,
            direction,
            cursor: origin,
            edge,
            wrap_anchor: origin,
            wrapped: forced_wrap,
            nearby: false,
            navigation: true,
            had_focus,
            output_drifted: false,
        });
        ws.search.set_status_at(
            kettle_render::SearchStatus::Searching,
            std::time::Instant::now(),
        );
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    fn activate_search_control(
        &mut self,
        ws: &mut WindowState,
        control: kettle_render::SearchControl,
    ) {
        match control {
            kettle_render::SearchControl::Editor => {
                ws.search.focused_control = kettle_render::SearchControl::Editor;
            }
            kettle_render::SearchControl::Previous => self.search_step_match(ws, true),
            kettle_render::SearchControl::Next => self.search_step_match(ws, false),
            kettle_render::SearchControl::Wrap => {
                ws.search.wrap = !ws.search.wrap;
                self.cfg.search_wrap = ws.search.wrap;
                self.persist_search_pref(
                    "search-wrap",
                    if ws.search.wrap { "true" } else { "false" },
                );
                search_wrap_toggled(&mut ws.search, std::time::Instant::now());
            }
            kettle_render::SearchControl::Case => {
                ws.search.case_mode = match ws.search.case_mode {
                    kettle_config::SearchCaseSensitivity::Smart => {
                        kettle_config::SearchCaseSensitivity::Always
                    }
                    kettle_config::SearchCaseSensitivity::Always => {
                        kettle_config::SearchCaseSensitivity::Never
                    }
                    kettle_config::SearchCaseSensitivity::Never => {
                        kettle_config::SearchCaseSensitivity::Smart
                    }
                };
                self.cfg.search_case_sensitive = ws.search.case_mode;
                let value = match ws.search.case_mode {
                    kettle_config::SearchCaseSensitivity::Smart => "smart",
                    kettle_config::SearchCaseSensitivity::Always => "always",
                    kettle_config::SearchCaseSensitivity::Never => "never",
                };
                self.persist_search_pref("search-case-sensitive", value);
                // The match set changes, so search again, from the match or
                // viewport the user is looking at rather than from where Search
                // opened.
                Self::anchor_search_to_viewport(ws);
                ws.search.note_edit(std::time::Instant::now());
            }
            kettle_render::SearchControl::Invert => {
                ws.search.invert = !ws.search.invert;
                self.cfg.invert_search = ws.search.invert;
                self.persist_search_pref(
                    "invert-search",
                    if ws.search.invert { "true" } else { "false" },
                );
                // Invert only changes which way Enter steps. A later search
                // starts from the matching edge of the viewport; the match on
                // screen stays.
                Self::anchor_search_to_viewport(ws);
                if ws.search.focused.is_none() {
                    ws.search.note_edit(std::time::Instant::now());
                }
            }
            kettle_render::SearchControl::Close => self.close_search(ws),
        }
    }

    /// Point the next search at where the user is looking (see
    /// `search_anchor_for`).
    fn anchor_search_to_viewport(ws: &mut WindowState) {
        let viewport = ws
            .search
            .target_pane
            .and_then(|pane_id| ws.mux.panes.get(&pane_id))
            .and_then(|pane| {
                use kettle_core::Dimensions as _;
                let term = pane.term.term.lock().ok()?;
                Some((
                    term.grid().display_offset(),
                    term.screen_lines(),
                    term.last_column().0,
                ))
            });
        if let Some(anchor) = search_anchor_for(ws.search.focused, ws.search.invert, viewport) {
            ws.search.anchor = Some(anchor);
        }
    }

    fn sync_search_editor_scroll(&self, ws: &mut WindowState) {
        let Some(renderer) = ws.renderer.as_ref() else {
            return;
        };
        let (width, height) = renderer.surface_size();
        let geometry = kettle_render::search_bar_geometry(
            width as f32,
            height as f32,
            renderer.cell_w,
            renderer.cell_h,
            &self.ui_text,
        );
        let columns = kettle_render::search_bar_columns(geometry.editor.2, renderer.cell_w).max(1);
        ws.search
            .editor
            .ensure_cursor_visible(columns.saturating_sub(2));
    }

    fn search_geometry(&self, ws: &WindowState) -> Option<kettle_render::SearchBarGeometry> {
        if !ws.search.open {
            return None;
        }
        let renderer = ws.renderer.as_ref()?;
        let (width, height) = renderer.surface_size();
        Some(kettle_render::search_bar_geometry(
            width as f32,
            height as f32,
            renderer.cell_w,
            renderer.cell_h,
            &self.ui_text,
        ))
    }

    fn search_mouse_press(&mut self, ws: &mut WindowState) -> bool {
        let Some(geometry) = self.search_geometry(ws) else {
            return false;
        };
        let (x, y) = (ws.cursor.x as f32, ws.cursor.y as f32);
        let Some(control) = geometry.hit_test(x, y) else {
            return false;
        };
        // Control input can press without a move first; the press itself
        // establishes what is under the pointer.
        self.update_search_hover(ws);
        if control != kettle_render::SearchControl::Editor {
            // A button activates on release over it, like a native button, so
            // a press can be taken back by moving off before letting go. A
            // pointer click also leaves keyboard focus where it was, as macOS
            // buttons and VS Code's find widget do, so typing goes on in the
            // query and the editor keeps its caret.
            ws.search.dragging_editor = false;
            ws.search.pressed_control = Some(control);
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
            return true;
        }
        ws.search.focused_control = control;

        // The caret goes to the nearest boundary between characters; a word
        // or line selection uses the character under the pointer.
        let boundary = self.search_caret_point_at(ws, x, geometry);
        let under = self.search_char_point_at(ws, x, geometry);
        let clicks = self.click_count(ws, usize::MAX, under.click_key());
        match clicks {
            2 => {
                ws.search.editor.select_word_at(under);
                ws.search.dragging_editor = false;
            }
            3 => {
                ws.search.editor.select_all();
                ws.search.dragging_editor = false;
            }
            _ => {
                ws.search
                    .editor
                    .set_cursor_at(boundary, ws.mods.shift_key());
                ws.search.dragging_editor = true;
            }
        }
        self.sync_search_editor_scroll(ws);
        true
    }

    /// Where in the query a click at `x` puts the caret.
    ///
    /// Over the visible text it is the nearest glyph boundary the renderer
    /// painted, as a query byte, so the caret lands where it is drawn even
    /// when a fallback font gives CJK or emoji a width other than whole cells.
    /// Past either edge of the editor it counts cells, so a drag there walks
    /// a scrolled query. An IME composition paints text the editor does not
    /// hold yet, so it counts cells too.
    fn search_caret_point_at(
        &self,
        ws: &WindowState,
        x: f32,
        geometry: kettle_render::SearchBarGeometry,
    ) -> crate::search_input::QueryPoint {
        let cell_width = ws.renderer.as_ref().map_or(8.0, |renderer| renderer.cell_w);
        let by_cells =
            crate::search_input::QueryPoint::Column(crate::search_input::pointer_query_column(
                ws.search.editor.horizontal_scroll(),
                ((x - geometry.editor.0) / cell_width + 0.5).floor() as isize,
            ));
        if !Self::search_pointer_over_painted_query(ws, x, geometry) {
            return by_cells;
        }
        let stops = ws
            .renderer
            .as_ref()
            .map_or(&[][..], |renderer| renderer.search_editor_stops());
        crate::search_input::nearest_stop_byte(stops, x)
            .map_or(by_cells, crate::search_input::QueryPoint::Byte)
    }

    /// The character under `x`, for a word or line selection. Like the
    /// caret, it follows the painted glyphs over the visible text and counts
    /// cells elsewhere.
    fn search_char_point_at(
        &self,
        ws: &WindowState,
        x: f32,
        geometry: kettle_render::SearchBarGeometry,
    ) -> crate::search_input::QueryPoint {
        let cell_width = ws.renderer.as_ref().map_or(8.0, |renderer| renderer.cell_w);
        let by_cells =
            crate::search_input::QueryPoint::Column(crate::search_input::pointer_query_column(
                ws.search.editor.horizontal_scroll(),
                ((x - geometry.editor.0) / cell_width).floor() as isize,
            ));
        if !Self::search_pointer_over_painted_query(ws, x, geometry) {
            return by_cells;
        }
        let clusters = ws
            .renderer
            .as_ref()
            .map_or(&[][..], |renderer| renderer.search_editor_clusters());
        crate::search_input::cluster_byte_at(clusters, x)
            .map_or(by_cells, crate::search_input::QueryPoint::Byte)
    }

    /// Whether `x` is over the editor's text area and the painted query is
    /// the editor's text. An IME composition paints text the editor does not
    /// hold yet.
    fn search_pointer_over_painted_query(
        ws: &WindowState,
        x: f32,
        geometry: kettle_render::SearchBarGeometry,
    ) -> bool {
        if ws.ime_preedit.is_some() {
            return false;
        }
        let Some(renderer) = ws.renderer.as_ref() else {
            return false;
        };
        // A right-to-left query starts at its right end, so cells counted
        // from the left edge would pick the wrong end; it always maps through
        // the painted glyphs, the nearest of which is the right end to take.
        renderer.search_editor_rtl()
            || (x >= geometry.editor.0 + renderer.cell_w * 0.5
                && x <= geometry.editor.0 + geometry.editor.2 - renderer.cell_w * 0.5)
    }

    /// End a button press: activate the button if the pointer is still over
    /// it, otherwise drop the press.
    fn search_button_release(&mut self, ws: &mut WindowState) {
        let Some(pressed) = ws.search.pressed_control.take() else {
            return;
        };
        let over = self
            .search_geometry(ws)
            .and_then(|geometry| geometry.hit_test(ws.cursor.x as f32, ws.cursor.y as f32));
        if over == Some(pressed) {
            self.activate_search_control(ws, pressed);
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    fn search_mouse_drag(&mut self, ws: &mut WindowState) -> bool {
        if !ws.search.open || !ws.search.dragging_editor {
            return false;
        }
        let Some(geometry) = self.search_geometry(ws) else {
            return true;
        };
        let point = self.search_caret_point_at(ws, ws.cursor.x as f32, geometry);
        ws.search.editor.set_cursor_at(point, true);
        self.sync_search_editor_scroll(ws);
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        true
    }

    /// Command-palette key handling: fuzzy-filter as you type, `Tab`/`↑↓`
    /// to move the selection, `Enter` to run it, `Esc` to cancel.
    /// Quick-select hint key handling: type the label of a target to act on
    /// it (open URLs, copy paths/hashes/IPs); `Esc` cancels.
    /// Vi-mode key dispatcher backed by alacritty_terminal's native vi cursor
    /// and selection. The engine owns scrollback/reflow coordinates and keeps
    /// them stable as output rotates or evicts history.
    fn vi_mode_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        if matches!(key, Key::Named(NamedKey::Escape)) {
            self.exit_vi_mode(ws);
            return;
        }
        let Some(owner) = ws.vi_mode else {
            return;
        };
        let Some(pane) = ws.mux.panes.get(&owner.pane_id) else {
            ws.vi_mode = None;
            return;
        };
        let mut term = pane
            .term
            .term
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if !term.mode().contains(kettle_core::TermMode::VI) {
            drop(term);
            ws.vi_mode = None;
            return;
        }

        let ch = crate::modal_input::accept_text(text, ws.mods)
            .and_then(|s| s.chars().next())
            .unwrap_or('\0');
        let motion = match (ch, key) {
            ('h', _) | ('\0', Key::Named(NamedKey::ArrowLeft)) => Some(kettle_core::ViMotion::Left),
            ('l', _) | ('\0', Key::Named(NamedKey::ArrowRight)) => {
                Some(kettle_core::ViMotion::Right)
            }
            ('k', _) | ('\0', Key::Named(NamedKey::ArrowUp)) => Some(kettle_core::ViMotion::Up),
            ('j', _) | ('\0', Key::Named(NamedKey::ArrowDown)) => Some(kettle_core::ViMotion::Down),
            ('0', _) | ('\0', Key::Named(NamedKey::Home)) => Some(kettle_core::ViMotion::First),
            ('^', _) => Some(kettle_core::ViMotion::FirstOccupied),
            ('$', _) | ('\0', Key::Named(NamedKey::End)) => Some(kettle_core::ViMotion::Last),
            ('H', _) => Some(kettle_core::ViMotion::High),
            ('M', _) => Some(kettle_core::ViMotion::Middle),
            ('L', _) => Some(kettle_core::ViMotion::Low),
            ('b', _) => Some(kettle_core::ViMotion::WordLeft),
            ('w', _) => Some(kettle_core::ViMotion::WordRight),
            ('e', _) => Some(kettle_core::ViMotion::WordRightEnd),
            ('B', _) => Some(kettle_core::ViMotion::SemanticLeft),
            ('W', _) => Some(kettle_core::ViMotion::SemanticRight),
            ('E', _) => Some(kettle_core::ViMotion::SemanticRightEnd),
            ('%', _) => Some(kettle_core::ViMotion::Bracket),
            ('{', _) => Some(kettle_core::ViMotion::ParagraphUp),
            ('}', _) => Some(kettle_core::ViMotion::ParagraphDown),
            _ => None,
        };
        if let Some(motion) = motion {
            term.vi_motion(motion);
            return;
        }

        match ch {
            'g' => {
                use kettle_core::Dimensions as _;
                let point = kettle_core::Point::new(term.topmost_line(), kettle_core::Column(0));
                term.vi_goto_point(point);
            }
            'G' => {
                use kettle_core::Dimensions as _;
                let point = kettle_core::Point::new(term.bottommost_line(), kettle_core::Column(0));
                term.vi_goto_point(point);
            }
            'v' => {
                if owner.visual {
                    term.selection = None;
                } else {
                    let point = term.vi_mode_cursor.point;
                    let mut selection = kettle_core::Selection::new(
                        kettle_core::SelectionType::Simple,
                        point,
                        kettle_core::Side::Left,
                    );
                    selection.update(point, kettle_core::Side::Right);
                    term.selection = Some(selection);
                }
                if let Some(state) = ws.vi_mode.as_mut() {
                    state.visual = !owner.visual;
                }
            }
            'y' => {
                let yanked = owner
                    .visual
                    .then(|| term.selection_to_string())
                    .flatten()
                    .unwrap_or_default();
                drop(term);
                let yanked = match kettle_core::scrub_card_markers(yanked) {
                    Ok(text) => text,
                    Err(error) => {
                        log::warn!("vi-mode yank: could not prepare text: {error}");
                        return;
                    }
                };
                if !yanked.is_empty() {
                    let Some(clip) = self.clipboard.as_mut() else {
                        log::warn!(
                            "vi-mode yank: clipboard unavailable (selection of {} bytes not copied)",
                            yanked.len()
                        );
                        return;
                    };
                    if let Err(error) = clip.set_text(yanked) {
                        log::warn!("vi-mode yank: clipboard set_text failed: {error}");
                        return;
                    }
                }
                let Ok(mut term) = pane.term.term.lock() else {
                    return;
                };
                term.selection = None;
                term.toggle_vi_mode();
                drop(term);
                ws.vi_mode = None;
            }
            _ => {}
        }
    }

    fn hint_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.hint_state = None;
                self.reset_blink_phase(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                if let Some((_, typed)) = ws.hint_state.as_mut() {
                    typed.pop();
                }
            }
            _ => {
                let Some(ch) = crate::modal_input::accept_text(text, ws.mods)
                    .and_then(|t| t.chars().next())
                    .filter(|c| c.is_ascii_alphabetic())
                    .map(|c| c.to_ascii_lowercase())
                else {
                    return;
                };
                // Extend the typed prefix only if it still matches a label.
                let chosen = {
                    let Some((targets, typed)) = ws.hint_state.as_mut() else {
                        return;
                    };
                    let cand = format!("{typed}{ch}");
                    if targets.iter().any(|t| t.label.starts_with(&cand)) {
                        *typed = cand;
                    }
                    let exact: Vec<&HintTarget> =
                        targets.iter().filter(|t| t.label == *typed).collect();
                    (exact.len() == 1).then(|| exact[0].clone())
                };
                if let Some(h) = chosen {
                    ws.hint_state = None;
                    // A label typed with Shift picks the other action. The
                    // modifier, not the letter's case, so Caps Lock is not Shift.
                    let alternate = ws.mods.shift_key();
                    self.act_hint(ws, &h, alternate);
                }
            }
        }
    }

    fn act_hint(&mut self, ws: &mut WindowState, h: &HintTarget, alternate: bool) {
        // Quick select for previews previews what was picked, its pane's
        // gate permitting, from the pane's own directory.
        if std::mem::take(&mut ws.hint_preview) {
            if !hint_previews(&h.what) {
                return;
            }
            if let HintWhat::Text { kind, text, .. } = &h.what {
                let url = match kind {
                    kettle_core::hints::Kind::Url => Some(text.clone()),
                    _ => hint_path_url(
                        text,
                        ws.mux
                            .panes
                            .get(&h.pane)
                            .and_then(|pane| pane.term.current_dir_or_native())
                            .as_deref(),
                        crate::mux::home_dir_string().as_deref(),
                    ),
                };
                let tr = self.ui_text;
                match url {
                    Some(url) => self.preview_pane_link(ws, h.pane, &url),
                    None => fire_notify(
                        tr.text(kettle_i18n::Text::NotifyTitlePreviewFailed),
                        tr.text(kettle_i18n::Text::NotifyBodyPreviewUnplaced),
                    ),
                }
            }
            return;
        }
        let (kind, text, bounded) = match &h.what {
            // A card opens its item in the viewer, Shift or not.
            HintWhat::Card(nonce) => {
                self.open_card(ws, h.pane, *nonce);
                return;
            }
            HintWhat::Text {
                kind,
                text,
                bounded,
            } => (*kind, text, *bounded),
        };
        let pane = ws.mux.panes.get(&h.pane);
        // A pane that exited took its directory with it, so nothing local can
        // be resolved for it, and a remote pane's paths name files elsewhere.
        // Behind a multiplexer the path opens once the user confirms (see
        // `open_pane_link`).
        let remote = matches!(pane.map(pane_path_origin), None | Some(PathOrigin::Remote));
        let action = hint_action(kind, alternate, remote || !bounded);
        let path_url = match action {
            HintAction::OpenPath => hint_path_url(
                text,
                pane.and_then(|pane| pane.term.current_dir_or_native())
                    .as_deref(),
                crate::mux::home_dir_string().as_deref(),
            ),
            _ => None,
        };
        match (action, path_url) {
            // Route through open_pane_link so a hint honors the pane's origin,
            // the URL safety check, Lua URL handlers and the custom URL
            // handler, like a click.
            (HintAction::OpenUrl, _) => self.open_pane_link(ws, Some(h.pane), text),
            (HintAction::OpenPath, Some(url)) => self.open_pane_link(ws, Some(h.pane), &url),
            // A path Kettle will not open (a climb with `..`, an unknown base,
            // any path on Windows) is copied instead, as for a plain label.
            (HintAction::OpenPath, None) | (HintAction::Copy, _) => {
                if let Some(cb) = self.clipboard.as_mut()
                    && let Err(e) = cb.set_text(text.clone())
                {
                    // Log instead of silently swallowing.
                    log::warn!("clipboard set_text failed (hint copy): {e}");
                }
            }
        }
    }

    fn palette_key(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        text: Option<&str>,
        event_loop: &ActiveEventLoop,
    ) {
        let cmds = kettle_config::palette::commands();
        let Some((q, sel)) = ws.palette_input.as_mut() else {
            return;
        };
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.palette_input = None;
                self.reset_blink_phase(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                crate::modal_input::backspace(q);
                *sel = 0;
            }
            Key::Named(NamedKey::ArrowDown) | Key::Named(NamedKey::Tab) => {
                let n = kettle_config::palette::rank(q, &cmds, &self.ui_text).len();
                if n > 0 {
                    *sel = (*sel + 1) % n;
                }
            }
            Key::Named(NamedKey::ArrowUp) => {
                let n = kettle_config::palette::rank(q, &cmds, &self.ui_text).len();
                if n > 0 {
                    *sel = (*sel + n - 1) % n;
                }
            }
            Key::Named(NamedKey::Enter) => {
                let ranked = kettle_config::palette::rank(q, &cmds, &self.ui_text);
                let action = ranked.get(*sel).map(|&i| cmds[i].1.clone());
                ws.palette_input = None;
                if let Some(a) = action {
                    self.handle_action(ws, a, event_loop);
                }
            }
            // `vim-menu-nav`: Ctrl+j/Ctrl+k (plus the telescope/fzf
            // Ctrl+n/Ctrl+p idiom) move the selection, while bare letters keep
            // typing into the query. Other Ctrl-chords fall through to the
            // catch-all unchanged.
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && ws.mods.control_key()
                    && !ws.mods.alt_key()
                    && matches!(s.as_str(), "j" | "k" | "n" | "p") =>
            {
                let n = kettle_config::palette::rank(q, &cmds, &self.ui_text).len();
                if n > 0 {
                    *sel = match s.as_str() {
                        "j" | "n" => (*sel + 1) % n,
                        _ => (*sel + n - 1) % n,
                    };
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && crate::modal_input::push_text(q, &pasted)
                {
                    *sel = 0;
                }
            }
            _ => {
                if let Some(t) = crate::modal_input::accept_text(text, ws.mods)
                    && crate::modal_input::push_text(q, t)
                {
                    *sel = 0;
                }
            }
        }
    }

    /// Apply a Settings-captured keybind rebind live and persist it.
    /// `action_name` is the config token (`Action::from_name`'s input,
    /// e.g. `"copy"`) for the action `act` already decodes to.
    ///
    /// A rebind REPLACES the action's binding, so this first drops every
    /// OTHER chord currently mapped to `act` (else the Keybinds row could show
    /// a stale chord, since the display scans the `keybinds` HashMap
    /// non-deterministically). It persists an `unbind` for each dropped chord
    /// before the new `bind`, so a reload doesn't resurrect the old chord
    /// alongside the new one.
    ///
    /// Shared by the direct (no-conflict) rebind path and
    /// `ConfirmAction::RebindKeybind`, so the two paths can never diverge. A
    /// chord already bound to a DIFFERENT action goes through a confirm dialog
    /// first instead of being stolen silently.
    fn apply_keybind_rebind(&mut self, trig: Trigger, act: Action, action_name: &str) -> bool {
        let label = trig.label();
        let stale: Vec<String> = self
            .cfg
            .keybinds
            .iter()
            .filter(|(t, v)| **v == act && **t != trig)
            .map(|(t, _)| t.label())
            .collect();
        self.cfg.keybinds.retain(|_, v| *v != act);
        self.cfg.keybinds.insert(trig, act);
        // The saved line makes this the user's chord on the next reload; mark
        // it now so `keybind-yield` treats it the same way this session.
        self.cfg.keybinds_declared.insert(trig);
        // Persist: unbind the old chord(s), then bind the new one. This
        // also naturally covers stealing a chord from another action —
        // appending `trig=action_name` after any earlier `trig=<other>`
        // line means the last-one-wins reload resolves `trig` to the new
        // action, matching the live HashMap `insert` above.
        let path = self
            .config_path
            .clone()
            .or_else(kettle_config::Config::default_path);
        let saved = persist_keybind_rebind(path.as_deref(), &stale, &label, action_name);
        if !saved {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleKeybindNotSaved),
                self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
            );
        }
        saved
    }

    /// Keyboard routing while the settings overlay is open.
    /// ↑/↓ move between fields, Tab/Shift+Tab switch category, ←/→ change the
    /// focused field's value, Space/Enter activate (toggle / cycle forward),
    /// Esc closes. Every change persists to the config file via `persist_pref`
    /// and reloads live, so the effect is immediate (matching the right-click
    /// Preferences toggles).
    fn settings_key(&mut self, ws: &mut WindowState, key: &Key, _event_loop: &ActiveEventLoop) {
        let cats = crate::settings::categories(&self.gpu_choices);
        if cats.is_empty() {
            ws.settings_nav = None;
            return;
        }
        let (mut cat, mut fld, capturing) = match &ws.settings_nav {
            Some(n) => (n.category.min(cats.len() - 1), n.field, n.capturing),
            None => return,
        };
        let field_count = cats[cat].fields.len();
        if field_count == 0 {
            return;
        }
        if fld >= field_count {
            fld = field_count - 1;
        }

        // Chord-capture mode — the focused Keybind field is waiting
        // for the user to press a chord. Esc cancels. A bare modifier press maps
        // to `None` via `to_kkey`, so we simply stay in capture until a real key
        // arrives. Any other chord is bound to the action live AND appended to
        // the config file so it survives restart.
        if capturing {
            if matches!(key, Key::Named(NamedKey::Escape)) {
                if let Some(n) = ws.settings_nav.as_mut() {
                    n.capturing = false;
                }
                return;
            }
            if let Some(kk) = to_kkey(key) {
                let mods = to_mods(ws.mods);
                // Refuse a modifier-less binding to a
                // text/essential key — it would shadow that key in normal typing
                // everywhere, persisted, with no in-overlay unbind. Stay in
                // capture mode and tell the user instead of soft-bricking.
                if !keybind_chord_is_safe(mods, kk) {
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleKeybindNeedsModifier),
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyBodyKeybindModifier),
                    );
                    return;
                }
                if let Some(action) = crate::settings::keybind_action(&cats[cat].fields[fld])
                    && let Some(act) = Action::from_name(action)
                {
                    let trig = Trigger::new(mods, kk);
                    // A chord already bound to a DIFFERENT action must not be
                    // stolen silently, since the old action's ONLY binding
                    // could vanish with no warning and no undo path. Like the
                    // modifier-safety check above, route it through a confirm
                    // dialog instead of applying it; Cancel is the safe default.
                    if let Some(stolen_from) =
                        self.cfg.keybinds.get(&trig).filter(|v| **v != act).cloned()
                    {
                        let chord_label = trig.label();
                        let stolen_name = kettle_config::keybinds::action_label(&stolen_from);
                        let new_name = kettle_config::keybinds::action_label(&act);
                        self.install_confirm_dialog(
                            ws,
                            ConfirmDialogState {
                                prompt: self.ui_text.confirm_rebind(
                                    &chord_label,
                                    &stolen_name,
                                    &new_name,
                                ),
                                buttons: vec![
                                    ConfirmButton::Cancel,
                                    ConfirmButton::Confirm {
                                        label: self
                                            .ui_text
                                            .text(kettle_i18n::Text::ConfirmButtonReassign)
                                            .to_string(),
                                        destructive: false,
                                    },
                                ],
                                focus_idx: 0,
                                on_confirm: ConfirmAction::RebindKeybind {
                                    trig,
                                    act,
                                    action_name: action,
                                },
                            },
                        );
                    } else {
                        self.apply_keybind_rebind(trig, act, action);
                    }
                }
                if let Some(n) = ws.settings_nav.as_mut() {
                    n.capturing = false;
                }
            }
            return;
        }

        match key {
            Key::Named(NamedKey::Escape) => {
                ws.settings_nav = None;
                self.reset_blink_phase(ws);
                return;
            }
            Key::Named(NamedKey::ArrowDown) => {
                fld = crate::settings::next_enabled_field(&self.cfg, &cats[cat].fields, fld, 1)
            }
            Key::Named(NamedKey::ArrowUp) => {
                fld = crate::settings::next_enabled_field(&self.cfg, &cats[cat].fields, fld, -1)
            }
            Key::Named(NamedKey::Tab) => {
                let n = cats.len();
                cat = if ws.mods.shift_key() {
                    (cat + n - 1) % n
                } else {
                    (cat + 1) % n
                };
                fld = 0;
            }
            Key::Named(NamedKey::ArrowRight)
            | Key::Named(NamedKey::ArrowLeft)
            | Key::Named(NamedKey::Space)
            | Key::Named(NamedKey::Enter) => {
                let dir = match key {
                    Key::Named(NamedKey::ArrowRight) => 1,
                    Key::Named(NamedKey::ArrowLeft) => -1,
                    _ => 0, // Space / Enter = activate (cycle forward / toggle)
                };
                self.settings_adjust(ws, &cats, cat, fld, dir);
            }
            // `vim-menu-nav`: j/k mirror ↓/↑, h/l mirror ←/→, g/G jump to the
            // first/last field, Ctrl+d / Ctrl+u move half a page. Chord-capture
            // mode (handled before this match) already consumed the key, so
            // capturing a chord like bare `j` (refused anyway) or `Ctrl+d`
            // still reaches the capture branch.
            Key::Character(s)
                if self.cfg.vim_menu_nav && !ws.mods.alt_key() && !ws.mods.super_key() =>
            {
                let half = (field_count / 2).max(1);
                // Case-fold so CapsLock can't kill the nav layer; g-vs-G
                // derives from the physical Shift state.
                let folded = s.to_ascii_lowercase();
                match (folded.as_str(), ws.mods.control_key()) {
                    ("j", false) => {
                        fld = crate::settings::next_enabled_field(
                            &self.cfg,
                            &cats[cat].fields,
                            fld,
                            1,
                        )
                    }
                    ("k", false) => {
                        fld = crate::settings::next_enabled_field(
                            &self.cfg,
                            &cats[cat].fields,
                            fld,
                            -1,
                        )
                    }
                    ("g", false) => {
                        fld = if ws.mods.shift_key() {
                            field_count - 1
                        } else {
                            0
                        };
                    }
                    ("h", false) => self.settings_adjust(ws, &cats, cat, fld, -1),
                    ("l", false) => self.settings_adjust(ws, &cats, cat, fld, 1),
                    ("d", true) => fld = (fld + half).min(field_count - 1),
                    ("u", true) => fld = fld.saturating_sub(half),
                    _ => {}
                }
            }
            _ => {}
        }
        if let Some(n) = ws.settings_nav.as_mut() {
            n.category = cat;
            n.field = fld;
        }
    }

    /// ←/→ (`dir = ±1`) or Space/Enter (`dir = 0`) on the focused settings
    /// row. Keybind rows enter chord-capture on activate (±1 no-ops); value
    /// rows persist the stepped value, mirror padding, and live-reload.
    /// vim-menu-nav's `h`/`l` share this exact code path.
    fn settings_adjust(
        &mut self,
        ws: &mut WindowState,
        cats: &[crate::settings::Category],
        cat: usize,
        fld: usize,
        dir: i32,
    ) {
        let field = &cats[cat].fields[fld];
        // A gated/inapplicable row never changes (it's drawn dimmed).
        if crate::settings::field_disabled(&self.cfg, field.key) {
            return;
        }
        if crate::settings::is_keybind(field) {
            // Activate on a keybind row → enter chord-capture; ←/→ no-op.
            if dir == 0
                && let Some(n) = ws.settings_nav.as_mut()
            {
                n.category = cat;
                n.field = fld;
                n.capturing = true;
            }
            return;
        }
        if dir == 0 && crate::settings::opens_theme_picker(field) {
            self.open_theme_picker(ws);
            return;
        }
        // A Text row (the image path) opens an inline prompt on activate
        // (dir 0); ←/→ no-op. A gated/disabled Text row can't be edited.
        if crate::settings::is_text(field) {
            if dir == 0 && !crate::settings::field_disabled(&self.cfg, field.key) {
                if let Some(n) = ws.settings_nav.as_mut() {
                    n.category = cat;
                    n.field = fld;
                }
                self.open_settings_text_edit(ws, field.key);
            }
            return;
        }
        // Scope the cfg borrow so reload_config (&mut self) is free.
        let (key_str, new_val) = {
            (
                field.key,
                crate::settings::next_value(&self.cfg, field, dir),
            )
        };
        // The GPU device picker is one row but persists THREE keys
        // (vendor/device/name). "auto" clears the pin; "<vendor>:<device>:<name>"
        // sets it. GPU changes apply on the NEXT launch (the wgpu device/surface
        // graph can't hot-swap and every window shares one adapter), so we flag
        // a restart affordance instead of rebuilding the renderer live.
        if key_str == "gpu" {
            // Fold all three `persist_pref` results together (false on an
            // unexpected `new_val` shape). A partial or total write failure
            // (read-only config, momentarily locked file, no write permission)
            // must not claim "restart to apply" when the pin never reached
            // disk and would silently revert to auto on the next launch.
            let saved = if new_val == "auto" {
                let a = self.persist_pref("gpu-vendor-id", "0");
                let b = self.persist_pref("gpu-device-id", "0");
                let c = self.persist_pref("gpu-name", "");
                a && b && c
            } else if let Some((v, rest)) = new_val.split_once(':')
                && let Some((d, name)) = rest.split_once(':')
            {
                let a = self.persist_pref("gpu-vendor-id", &format!("0x{v}"));
                let b = self.persist_pref("gpu-device-id", &format!("0x{d}"));
                let c = self.persist_pref("gpu-name", name);
                a && b && c
            } else {
                false
            };
            if saved {
                ws.settings_restart_pending = true;
            } else {
                fire_notify(
                    self.ui_text
                        .text(kettle_i18n::Text::NotifyTitleSettingNotSaved),
                    self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
                );
            }
            self.reload_config(ws);
            return;
        }
        // Notify if the Settings change can't
        // be written — it's live this session but lost on restart.
        let saved = self.persist_pref(key_str, &new_val);
        if !saved {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleSettingNotSaved),
                self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
            );
        }
        // The single "Window padding" control sets *uniform* padding, so
        // mirror the value to the Y axis. Leaving `window-padding-y` at its
        // default gives visibly lopsided padding.
        //
        // Report a failed mirror write like the general path above. The X
        // write can succeed while this one fails (e.g. the config file becomes
        // read-only or briefly locked between the two calls), which would
        // leave lopsided padding after restart with no error shown.
        if key_str == "window-padding-x" && !self.persist_pref("window-padding-y", &new_val) {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleSettingNotSaved),
                self.ui_text
                    .text(kettle_i18n::Text::NotifyBodyPaddingPartial),
            );
        }
        // The remaining GPU policy keys (power preference / backend /
        // force-software) also only take effect on restart.
        if saved
            && matches!(
                key_str,
                "gpu-power-preference" | "gpu-backend" | "gpu-force-software"
            )
        {
            ws.settings_restart_pending = true;
        }
        if saved
            && matches!(
                key_str,
                "background-opacity" | "background-type" | "window-blur"
            )
        {
            // Winit's alpha-capable window attribute is fixed at creation.
            // Renderer colors reload immediately, but crossing the opaque /
            // translucent boundary or enabling native material needs a fresh
            // window before the OS compositor can show the result.
            ws.settings_restart_pending = true;
        }
        self.reload_config(ws);
        // A theme pick needs no `save_session()`. `persist_pref` above durably
        // writes the config `theme =` line, the single source of truth on restart.
    }

    /// Open the inline text prompt for a [`crate::settings::FieldKind::Text`]
    /// row, pre-filled with the current config value.
    fn open_settings_text_edit(&mut self, ws: &mut WindowState, key: &'static str) {
        let cur = match key {
            "background-image" => self.cfg.background_image.clone(),
            _ => String::new(),
        };
        ws.settings_text_edit = Some(crate::settings::SettingsTextEdit { key, buf: cur });
        if let Some(w) = &ws.window {
            w.request_redraw();
        }
    }

    /// Keyboard routing while the settings inline text prompt is open.
    /// Esc cancels, Enter persists + live-reloads, Backspace deletes, printable
    /// text appends (control chars filtered, like the ssh/palette inputs).
    fn settings_text_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.settings_text_edit = None;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Key::Named(NamedKey::Backspace) => {
                if let Some(e) = ws.settings_text_edit.as_mut() {
                    crate::modal_input::backspace(&mut e.buf);
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            Key::Named(NamedKey::Enter) => {
                if let Some(e) = ws.settings_text_edit.take() {
                    let val = e.buf.trim().to_string();
                    if !self.persist_pref(e.key, &val) {
                        fire_notify(
                            self.ui_text
                                .text(kettle_i18n::Text::NotifyTitleSettingNotSaved),
                            self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
                        );
                    }
                    self.reload_config(ws);
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && let Some(e) = ws.settings_text_edit.as_mut()
                {
                    crate::modal_input::push_text(&mut e.buf, &pasted);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
            _ => {
                if let Some(t) = crate::modal_input::accept_text(text, ws.mods)
                    && let Some(e) = ws.settings_text_edit.as_mut()
                {
                    crate::modal_input::push_text(&mut e.buf, t);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
        }
    }

    /// Terminator parity, `layoutlauncher.py`:
    /// keyboard routing while the layout picker overlay is open.
    /// Same shape as `palette_key` but ranks against
    /// the names captured when it opened and dispatches by spawning
    /// `kettle --layout NAME` as a new window.
    fn layout_picker_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        let layouts = &ws.layout_picker_entries;
        let Some((q, sel)) = ws.layout_picker_input.as_mut() else {
            return;
        };
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.layout_picker_input = None;
                self.reset_blink_phase(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                crate::modal_input::backspace(q);
                *sel = 0;
            }
            Key::Named(NamedKey::ArrowDown) | Key::Named(NamedKey::Tab) => {
                let n = rank_layouts(q, layouts).len();
                if n > 0 {
                    *sel = (*sel + 1) % n;
                }
            }
            Key::Named(NamedKey::ArrowUp) => {
                let n = rank_layouts(q, layouts).len();
                if n > 0 {
                    *sel = (*sel + n - 1) % n;
                }
            }
            // `vim-menu-nav`: Ctrl+j/k (+ Ctrl+n/p) move the selection; bare
            // letters keep typing into the filter.
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && ws.mods.control_key()
                    && !ws.mods.alt_key()
                    && matches!(s.as_str(), "j" | "k" | "n" | "p") =>
            {
                let n = rank_layouts(q, layouts).len();
                if n > 0 {
                    *sel = match s.as_str() {
                        "j" | "n" => (*sel + 1) % n,
                        _ => (*sel + n - 1) % n,
                    };
                }
            }
            Key::Named(NamedKey::Enter) => {
                let ranked = rank_layouts(q, layouts);
                let name = ranked.get(*sel).map(|&i| layouts[i].clone());
                ws.layout_picker_input = None;
                if let Some(name) = name {
                    let exe = std::env::current_exe()
                        .unwrap_or_else(|_| std::path::PathBuf::from("kettle"));
                    if let Err(e) = std::process::Command::new(&exe)
                        .arg("--layout")
                        .arg(&name)
                        .stdin(std::process::Stdio::null())
                        .stdout(std::process::Stdio::null())
                        .stderr(std::process::Stdio::null())
                        .spawn()
                    {
                        log::warn!("layout picker: spawn `kettle --layout {name}`: {e}");
                    }
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && crate::modal_input::push_text(q, &pasted)
                {
                    *sel = 0;
                }
            }
            _ => {
                if let Some(t) = crate::modal_input::accept_text(text, ws.mods)
                    && crate::modal_input::push_text(q, t)
                {
                    *sel = 0;
                }
            }
        }
    }

    /// Whether the saved `language` would show Kettle in another language than
    /// this process's, which keeps the one it started with.
    fn language_change_pending(&self) -> bool {
        language_change_pending(
            self.cfg.language,
            self.ui_text.language(),
            kettle_i18n::os_locale,
        )
    }

    /// Open the theme picker on the current theme. Opened from Settings, the
    /// picker sits over the panel, which comes back when the picker closes.
    fn open_theme_picker(&mut self, ws: &mut WindowState) {
        let settings = ws.settings_nav.take();
        self.close_all_modals(ws);
        ws.settings_nav = settings;
        let live = (self.cfg.theme_name.clone(), self.cfg.theme.clone());
        if let Some((name, theme)) = begin_theme_picker(ws, live) {
            self.set_runtime_theme_state(ws, name, theme);
        }
    }

    /// The theme picker's keys. Moving the selection previews that theme (see
    /// `sync_theme_preview`); Enter keeps it and Esc restores the theme the
    /// picker opened on.
    fn theme_picker_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        let Some(state) = ws.theme_picker_input.as_mut() else {
            return;
        };
        let count = |state: &crate::window_state::ThemePickerState| {
            theme_picker_matches(&state.query, &state.opened_on).len()
        };
        let step = |state: &mut crate::window_state::ThemePickerState, forward: bool, n: usize| {
            if n > 0 {
                state.selected = if forward {
                    (state.selected + 1) % n
                } else {
                    (state.selected + n - 1) % n
                };
            }
        };
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.theme_picker_input = None;
                self.reset_blink_phase(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                crate::modal_input::backspace(&mut state.query);
                state.selected = 0;
            }
            Key::Named(NamedKey::ArrowDown) | Key::Named(NamedKey::Tab) => {
                let n = count(state);
                step(state, true, n);
            }
            Key::Named(NamedKey::ArrowUp) => {
                let n = count(state);
                step(state, false, n);
            }
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && ws.mods.control_key()
                    && !ws.mods.alt_key()
                    && matches!(s.as_str(), "j" | "k" | "n" | "p") =>
            {
                let n = count(state);
                step(state, matches!(s.as_str(), "j" | "n"), n);
            }
            Key::Named(NamedKey::Enter) => {
                let pick = theme_picker_selection(state);
                ws.theme_picker_input = None;
                if let Some(name) = pick {
                    self.commit_theme(ws, name);
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && let Some(state) = ws.theme_picker_input.as_mut()
                    && crate::modal_input::push_text(&mut state.query, &pasted)
                {
                    state.selected = 0;
                }
            }
            _ => {
                if let Some(t) = crate::modal_input::accept_text(text, ws.mods)
                    && crate::modal_input::push_text(&mut state.query, t)
                {
                    state.selected = 0;
                }
            }
        }
    }

    /// Keep `name` as the theme. Dropping the preview's baseline makes the
    /// post-event `sync_theme_preview` keep this pick instead of restoring the
    /// theme the picker opened on.
    fn commit_theme(&mut self, ws: &mut WindowState, name: &str) {
        ws.theme_preview = None;
        self.set_runtime_theme_name(ws, name);
        // Theme is config-governed, so persist it to the config file, not the
        // session. A session-pinned theme would OVERRIDE the config/compile-time
        // default on restore, so neither a default change nor a fresh-config
        // user would see the new theme. Notify if the write fails so the pick
        // isn't silently lost on the next launch.
        if !self.persist_pref("theme", name) {
            fire_notify(
                self.ui_text
                    .text(kettle_i18n::Text::NotifyTitleThemeNotSaved),
                self.ui_text.text(kettle_i18n::Text::NotifyBodyNotSaved),
            );
        }
    }

    /// Esc / `h` semantics: pop a drilled-in submenu back to its parent, or
    /// close the menu when at the top level.
    fn context_menu_back(&mut self, ws: &mut WindowState) {
        if let Some(menu) = ws.context_menu.as_mut()
            && let Some(parent) = menu.drill_stack.pop()
        {
            menu.items = parent;
            // Restore the parent level's
            // scroll_offset so popping out of a deep theme
            // list doesn't snap the parent's scroll position
            // to 0.
            menu.scroll_offset = menu.scroll_stack.pop().unwrap_or(0);
            menu.highlight = menu
                .items
                .iter()
                .position(item_is_dispatchable)
                .unwrap_or(0);
            if let Some(w) = &ws.window {
                w.request_redraw();
            }
            return;
        }
        ws.context_menu = None;
        self.reset_blink_phase(ws);
    }

    /// Enter / Space / `l` semantics: dispatch the highlighted row through the
    /// shared mapper.
    fn context_menu_activate(&mut self, ws: &mut WindowState, event_loop: &ActiveEventLoop) {
        // Resolve the highlighted row through the shared mapper so Enter /
        // Space dispatches every row type (submenu drill-in, Lua item, config
        // command, theme / profile choice, new-tab ▾ shell). The mapper +
        // dispatcher also own the close-or-keep decision, so a submenu Enter
        // keeps the menu open.
        let chosen = ws.context_menu.as_ref().and_then(|m| {
            m.items
                .get(m.highlight)
                .and_then(|it| item_to_click(it, m.highlight))
        });
        self.reset_blink_phase(ws);
        match chosen {
            Some(click) => self.dispatch_context_menu_click(ws, click, event_loop),
            // Highlight on a non-dispatchable row (shouldn't happen —
            // nav skips them — but close rather than trap the user).
            None => ws.context_menu = None,
        }
    }

    /// The context menu's `vim-menu-nav` layer. Returns `true` when the key
    /// was consumed. Called BEFORE the mnemonic/typeahead catch-all (which
    /// eats every bare a–z) so nav letters always navigate;
    /// `assign_mnemonics` reserves the same letters (`VIM_NAV_RESERVED`) so
    /// no row ever points at a key this layer intercepts.
    fn context_menu_vim_key(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        event_loop: &ActiveEventLoop,
    ) -> bool {
        let Key::Character(s) = key else {
            return false;
        };
        if ws.mods.alt_key() || ws.mods.super_key() {
            return false;
        }
        let ctrl = ws.mods.control_key();
        // Case-fold so CapsLock can't kill the nav layer (letters arrive
        // uppercased); g-vs-G derives from the PHYSICAL Shift state, not
        // character case, so CapsLock+g still means "first" (the user didn't
        // press Shift).
        let folded = s.to_ascii_lowercase();
        match (folded.as_str(), ctrl) {
            ("j", false) => {
                self.step_context_menu_highlight(ws, 1);
                true
            }
            ("k", false) => {
                self.step_context_menu_highlight(ws, -1);
                true
            }
            ("g", false) => {
                let last = ws.mods.shift_key();
                let next = ws.context_menu.as_ref().and_then(|m| {
                    if last {
                        m.items.iter().rposition(item_is_dispatchable)
                    } else {
                        m.items.iter().position(item_is_dispatchable)
                    }
                });
                if let Some(next) = next {
                    self.set_context_menu_highlight(ws, next);
                }
                true
            }
            ("h", false) => {
                self.context_menu_back(ws);
                true
            }
            ("l", false) => {
                self.context_menu_activate(ws, event_loop);
                true
            }
            ("d", true) | ("u", true) => {
                // Derive direction from the case-FOLDED key, not the raw char.
                // Ctrl+Shift+D arrives as `s == "D"`, so a raw `s == "d"` test
                // would turn a half-page-DOWN into a scroll UP.
                let dir: isize = if folded == "d" { 1 } else { -1 };
                let Some(((_, _), (_, panel_h))) = self.context_menu_geometry(ws) else {
                    return true;
                };
                let (_, ch) = self.menu_cell(ws);
                let row_h = ch + kettle_render::menu::ROW_PAD;
                let sep_h = kettle_render::menu::SEP_H;
                let next = ws.context_menu.as_ref().map(|m| {
                    let visible =
                        count_rows_fitting(&m.items, m.scroll_offset, panel_h, row_h, sep_h);
                    half_page_menu_target(&m.items, m.highlight, (visible / 2).max(1), dir)
                });
                if let Some(next) = next {
                    self.set_context_menu_highlight(ws, next);
                }
                true
            }
            _ => false,
        }
    }

    fn context_menu_key(
        &mut self,
        ws: &mut WindowState,
        key: &Key,
        text: Option<&str>,
        event_loop: &ActiveEventLoop,
    ) {
        // Vim navigation intercepts BEFORE the mnemonic/typeahead catch-all
        // below, which would otherwise eat bare `j`/`k`/… as mnemonic or
        // typeahead input. With `vim-menu-nav = false` it is skipped.
        // Keyboard routing while the right-click context menu is open:
        // `Esc` closes (or pops a submenu), `↑/↓` step the highlight
        // (skipping separators + disabled rows), `Enter`/`Space` fire the
        // highlighted action, and bare letters dispatch mnemonics /
        // typeahead. Any other key is swallowed so a stray keypress doesn't
        // leak into the focused pane while the menu is expecting nav input.
        if self.cfg.vim_menu_nav && self.context_menu_vim_key(ws, key, event_loop) {
            return;
        }
        match key {
            Key::Named(NamedKey::Escape) => {
                self.context_menu_back(ws);
            }
            Key::Named(NamedKey::ArrowDown) | Key::Named(NamedKey::Tab) => {
                self.step_context_menu_highlight(ws, 1);
            }
            Key::Named(NamedKey::ArrowUp) => {
                self.step_context_menu_highlight(ws, -1);
            }
            Key::Named(NamedKey::Enter) | Key::Named(NamedKey::Space) => {
                self.context_menu_activate(ws, event_loop);
            }
            _ => {
                // Terminator menu UX: mnemonics + typeahead. A single A-Z
                // keystroke dispatches a row whose mnemonic char matches;
                // multi-char accumulates into `typeahead_buf` for
                // prefix-match. Buffer clears after 750ms of inactivity.
                let Some(t) = crate::modal_input::accept_text(text, ws.mods) else {
                    return;
                };
                let mut chars = t.chars();
                let Some(c) = chars.next() else { return };
                if chars.next().is_some() || !c.is_ascii_alphabetic() {
                    // Multi-char text events or non-alpha (digits,
                    // punctuation, IME composition) are ignored.
                    return;
                }
                let lower = c.to_ascii_lowercase();
                let now = std::time::Instant::now();
                // Clear stale typeahead buffer.
                if let Some(menu) = ws.context_menu.as_mut()
                    && menu
                        .typeahead_until
                        .map(|deadline| now > deadline)
                        .unwrap_or(false)
                {
                    menu.typeahead_buf.clear();
                    menu.typeahead_until = None;
                }
                // First key after a long pause: try mnemonic dispatch
                // (single-char). On a hit, dispatch the row + close
                // the menu (matches Win32 / GTK convention). On a
                // miss, accumulate into typeahead.
                // With vim-menu-nav on, the nav letters are reserved. They were
                // intercepted above and must never match a row.
                let reserved: &[char] = if self.cfg.vim_menu_nav {
                    VIM_NAV_RESERVED
                } else {
                    &[]
                };
                let mnemonic_hit = ws.context_menu.as_ref().and_then(|menu| {
                    if !menu.typeahead_buf.is_empty() {
                        return None;
                    }
                    let mn = assign_mnemonics(&menu.items, reserved);
                    mn.iter().enumerate().find_map(|(idx, slot)| {
                        slot.and_then(|(_, ch)| (ch == lower).then_some(idx))
                    })
                });
                if let Some(idx) = mnemonic_hit {
                    // Dispatch the matched row through the same
                    // shared mapper + sink as mouse clicks and Enter / Space,
                    // so a mnemonic reaches every row type (Lua / config /
                    // ▾ shell included) and the close-or-drill decision stays
                    // in one place.
                    let click = ws
                        .context_menu
                        .as_ref()
                        .and_then(|m| m.items.get(idx).and_then(|it| item_to_click(it, idx)));
                    if let Some(click) = click {
                        self.dispatch_context_menu_click(ws, click, event_loop);
                        return;
                    }
                }
                // Typeahead path: accumulate into the buffer, find
                // the first row whose label has this prefix, advance
                // highlight without dispatching.
                if let Some(menu) = ws.context_menu.as_mut() {
                    menu.typeahead_buf.push(lower);
                    menu.typeahead_until = Some(now + std::time::Duration::from_millis(750));
                    if let Some(idx) = typeahead_match(&menu.items, &menu.typeahead_buf) {
                        menu.highlight = idx;
                    }
                }
            }
        }
    }

    fn ssh_key(&mut self, ws: &mut WindowState, key: &Key, text: Option<&str>) {
        match key {
            Key::Named(NamedKey::Escape) => {
                ws.ssh_input = None;
                self.reset_blink_phase(ws);
            }
            Key::Named(NamedKey::Backspace) => {
                if let Some((query, selected)) = ws.ssh_input.as_mut() {
                    crate::modal_input::backspace(query);
                    *selected = 0;
                }
            }
            Key::Named(NamedKey::ArrowDown) => {
                if let Some((query, selected)) = ws.ssh_input.as_mut() {
                    let count = rank_ssh_hosts(query, &self.cfg.ssh_hosts).len();
                    if count > 0 {
                        *selected = (*selected + 1) % count;
                    }
                }
            }
            Key::Named(NamedKey::ArrowUp) => {
                if let Some((query, selected)) = ws.ssh_input.as_mut() {
                    let count = rank_ssh_hosts(query, &self.cfg.ssh_hosts).len();
                    if count > 0 {
                        *selected = (*selected + count - 1) % count;
                    }
                }
            }
            Key::Named(NamedKey::Tab) => {
                // Complete to the highlighted configured host, not merely the
                // first fuzzy result, so keyboard navigation and the input line
                // cannot disagree about what Enter will connect to.
                if let Some((query, selected)) = ws.ssh_input.as_mut() {
                    let ranked = rank_ssh_hosts(query, &self.cfg.ssh_hosts);
                    if let Some(&index) = ranked.get(*selected) {
                        query.clone_from(&self.cfg.ssh_hosts[index].0);
                        *selected = 0;
                    }
                }
            }
            Key::Named(NamedKey::Enter) => {
                let (typed, selected) = ws.ssh_input.take().unwrap_or_default();
                let target = selected_ssh_target(&typed, selected, &self.cfg.ssh_hosts);
                if let Some(target) = target {
                    let area = self.area(ws);
                    let (cols, rows) = self.grid_of(ws, area);
                    let geometry = self.pty_geometry_for_grid(ws, cols, rows);
                    if let Err(e) =
                        ws.mux
                            .new_ssh_tab_geometry(&self.cfg, geometry, self.waker(), &target)
                    {
                        log::error!("ssh launch failed: {e}");
                    }
                    self.resize_all(ws);
                    self.save_session(ws);
                }
            }
            Key::Character(s)
                if self.cfg.vim_menu_nav
                    && ws.mods.control_key()
                    && !ws.mods.alt_key()
                    && matches!(s.as_str(), "j" | "k" | "n" | "p") =>
            {
                if let Some((query, selected)) = ws.ssh_input.as_mut() {
                    let count = rank_ssh_hosts(query, &self.cfg.ssh_hosts).len();
                    if count > 0 {
                        *selected = match s.as_str() {
                            "j" | "n" => (*selected + 1) % count,
                            _ => (*selected + count - 1) % count,
                        };
                    }
                }
            }
            Key::Character(s) if crate::modal_input::is_paste_chord(Some(s.as_str()), ws.mods) => {
                if let Some(pasted) = self.modal_clipboard_text()
                    && let Some((query, selected)) = ws.ssh_input.as_mut()
                    && crate::modal_input::push_text(query, &pasted)
                {
                    *selected = 0;
                }
            }
            _ => {
                // Modifier filtering, control-character filtering and the byte
                // cap all live in `modal_input` now, shared with the palette,
                // the title editors, the layout picker and the Settings prompt.
                if let Some(t) = crate::modal_input::accept_text(text, ws.mods)
                    && let Some((query, selected)) = ws.ssh_input.as_mut()
                    && crate::modal_input::push_text(query, t)
                {
                    *selected = 0;
                }
            }
        }
    }
}

/// Terminator parity: remap encoded Backspace/Delete bytes per the user's
/// `backspace-binding`/`delete-binding`. `send_keys` uses it too, so it honors
/// the same remap as GUI keystrokes (the "same path as a human key press"
/// contract).
///
/// The binding only ever replaces the UNMODIFIED encoding, and the test for
/// that is the encoded bytes themselves, not the modifier state. Delete's
/// `CSI 3 ~` form carries a modifier parameter for *shift, alt and control
/// alike* (Super has no legacy representation and is rejected before this
/// point). With `delete-binding` defaulting to `EscapeSequence`, remapping a
/// modified Delete would rewrite it to the plain `CSI 3 ~`, so `Ctrl+Delete`
/// would equal `Delete` and readline's `kill-word` and every `<C-Del>` /
/// `<S-Del>` / `<M-Del>` editor mapping would delete one character instead.
///
/// Comparing against the plain form cannot drift from the encoder, and it is
/// right for the cases modifier logic keeps missing: a `modifyOtherKeys`
/// level-1 `Shift+Backspace` (`CSI 27;2;8~`) and any kitty-protocol encoding
/// are left alone, because an application that negotiated a precise encoding
/// must not have it overwritten by a legacy remap.
fn apply_bs_del_binding(cfg: &Config, key: &Key, bytes: Vec<u8>) -> Vec<u8> {
    let Key::Named(named) = key else {
        return bytes;
    };
    use kettle_config::{BackspaceBinding, DeleteBinding};
    /// What `input::encode` emits for an unmodified Backspace.
    const PLAIN_BACKSPACE: &[u8] = &[0x7f];
    /// What `input::encode` emits for an unmodified Delete.
    const PLAIN_DELETE: &[u8] = b"\x1b[3~";
    if *named == NamedKey::Backspace && bytes == PLAIN_BACKSPACE {
        match cfg.backspace_binding {
            BackspaceBinding::AsciiDel => vec![0x7f],
            BackspaceBinding::ControlH => vec![0x08],
            BackspaceBinding::EscapeSequence => b"\x1b[3~".to_vec(),
            BackspaceBinding::Automatic => bytes,
        }
    } else if *named == NamedKey::Delete && bytes == PLAIN_DELETE {
        match cfg.delete_binding {
            DeleteBinding::AsciiDel => vec![0x7f],
            DeleteBinding::ControlH => vec![0x08],
            DeleteBinding::EscapeSequence => b"\x1b[3~".to_vec(),
            DeleteBinding::Automatic => bytes,
        }
    } else {
        bytes
    }
}

fn encode_key_event_for_mode(
    cfg: &Config,
    event: &winit::event::KeyEvent,
    mods: ModifiersState,
    mode: kettle_core::TermMode,
) -> Option<Vec<u8>> {
    let mut bytes = input::encode_key_event(event, mods, mode)?;
    if !input::uses_kitty_sequence(event, mods, mode) {
        bytes = apply_bs_del_binding(cfg, &event.logical_key, bytes);
    }
    Some(bytes)
}

fn key_is_modified_enter(key: &Key, mods: ModifiersState) -> bool {
    matches!(key, Key::Named(NamedKey::Enter))
        && (mods.shift_key() || mods.control_key() || mods.alt_key() || mods.super_key())
}

fn parse_ctl_send_key_batch(
    keys: &[serde_json::Value],
) -> std::result::Result<Vec<(String, ModifiersState, Key)>, String> {
    if keys.is_empty() || keys.len() > MAX_CTL_SEND_KEYS {
        return Err(format!(
            "'keys' must contain 1..={MAX_CTL_SEND_KEYS} entries"
        ));
    }
    let mut parsed = Vec::with_capacity(keys.len());
    for value in keys {
        let Some(token) = value.as_str() else {
            return Err("non-string entry in 'keys'".into());
        };
        if token.is_empty() || token.len() > MAX_CTL_SEND_KEY_TOKEN_BYTES {
            return Err(format!(
                "key tokens must be 1..={MAX_CTL_SEND_KEY_TOKEN_BYTES} bytes"
            ));
        }
        let Some((mods, key)) = parse_send_key(token) else {
            return Err(format!("unrecognized key token '{token}'"));
        };
        parsed.push((token.to_owned(), mods, key));
    }
    Ok(parsed)
}

fn extend_ctl_send_key_bytes(
    bytes: &mut Vec<u8>,
    encoded: &[u8],
) -> std::result::Result<(), String> {
    if encoded.len() > MAX_CTL_SEND_KEY_BYTES.saturating_sub(bytes.len()) {
        return Err(format!(
            "encoded key sequence exceeds {MAX_CTL_SEND_KEY_BYTES} bytes"
        ));
    }
    bytes.extend_from_slice(encoded);
    Ok(())
}

/// Parse one `send_keys` token (`"escape"`, `"ctrl+c"`, `"shift+tab"`,
/// `"f5"`, `"alt+enter"`, a bare character like `"G"`) into the
/// `(mods, key)` pair the GUI's PTY encoder (`input::encode_key_press`)
/// consumes. Same `+`-separated grammar and modifier aliases as config
/// keybind triggers (`parse_trigger`), plus names the keybind grammar lacks
/// (escape, insert, comma). Character case is preserved (`"G"` sends `G`,
/// like a human holding Shift). `None` on an unrecognized token, so the
/// caller can name the bad token instead of sending wrong bytes. Pure
/// (unit-tested).
fn parse_send_key(token: &str) -> Option<(ModifiersState, Key)> {
    parse_key_token(token)
}

/// Parse a Kettle-owned UI key. Application chrome can consume Super/Command
/// character chords directly (for example Command+A on macOS).
fn parse_ui_key(token: &str) -> Option<(ModifiersState, Key)> {
    let (mods, key) = parse_key_token(token)?;
    let key = if key == Key::Named(NamedKey::Space) {
        Key::Character(" ".into())
    } else if matches!(
        &key,
        Key::Named(
            NamedKey::Escape
                | NamedKey::Enter
                | NamedKey::Tab
                | NamedKey::Backspace
                | NamedKey::Delete
                | NamedKey::ArrowUp
                | NamedKey::ArrowDown
                | NamedKey::ArrowLeft
                | NamedKey::ArrowRight
                | NamedKey::Home
                | NamedKey::End
                | NamedKey::F3
        ) | Key::Character(_)
    ) {
        key
    } else {
        return None;
    };
    Some((mods, key))
}

fn parse_key_token(token: &str) -> Option<(ModifiersState, Key)> {
    let parts: Vec<&str> = token.split('+').collect();
    let last = parts.len().checked_sub(1)?;
    let mut mods = ModifiersState::empty();
    let mut key: Option<Key> = None;
    for (i, part) in parts.iter().enumerate() {
        let raw = part.trim();
        let lower = raw.to_ascii_lowercase();
        match lower.as_str() {
            "ctrl" | "control" => mods |= ModifiersState::CONTROL,
            "alt" | "opt" | "option" => mods |= ModifiersState::ALT,
            "shift" => mods |= ModifiersState::SHIFT,
            "super" | "cmd" | "command" | "win" | "windows" | "meta" | "logo" => {
                mods |= ModifiersState::SUPER;
            }
            _ => {
                // Only the LAST slot may be a key (same rule as parse_trigger:
                // a typo'd modifier must fail loudly, not bind a plain key).
                if i != last {
                    return None;
                }
                // Named characters first, since a literal `,` can't survive the
                // CLI's comma-split `--keys` and `+` is every client's chord
                // separator. Mirrors `parse_key`'s plus/minus/equal aliases.
                match lower.as_str() {
                    "plus" => {
                        key = Some(Key::Character("+".into()));
                        continue;
                    }
                    "comma" => {
                        key = Some(Key::Character(",".into()));
                        continue;
                    }
                    "minus" => {
                        key = Some(Key::Character("-".into()));
                        continue;
                    }
                    "equal" => {
                        key = Some(Key::Character("=".into()));
                        continue;
                    }
                    _ => {}
                }
                let named = match lower.as_str() {
                    "escape" | "esc" => Some(NamedKey::Escape),
                    "enter" | "return" => Some(NamedKey::Enter),
                    "tab" => Some(NamedKey::Tab),
                    "backspace" | "bs" => Some(NamedKey::Backspace),
                    "delete" | "del" => Some(NamedKey::Delete),
                    "insert" | "ins" => Some(NamedKey::Insert),
                    "space" => Some(NamedKey::Space),
                    "up" => Some(NamedKey::ArrowUp),
                    "down" => Some(NamedKey::ArrowDown),
                    "left" => Some(NamedKey::ArrowLeft),
                    "right" => Some(NamedKey::ArrowRight),
                    "home" => Some(NamedKey::Home),
                    "end" => Some(NamedKey::End),
                    "page_up" | "pageup" | "prior" => Some(NamedKey::PageUp),
                    "page_down" | "pagedown" | "next" => Some(NamedKey::PageDown),
                    "f1" => Some(NamedKey::F1),
                    "f2" => Some(NamedKey::F2),
                    "f3" => Some(NamedKey::F3),
                    "f4" => Some(NamedKey::F4),
                    "f5" => Some(NamedKey::F5),
                    "f6" => Some(NamedKey::F6),
                    "f7" => Some(NamedKey::F7),
                    "f8" => Some(NamedKey::F8),
                    "f9" => Some(NamedKey::F9),
                    "f10" => Some(NamedKey::F10),
                    "f11" => Some(NamedKey::F11),
                    "f12" => Some(NamedKey::F12),
                    _ => None,
                };
                key = Some(match named {
                    Some(n) => Key::Named(n),
                    None => {
                        // A single character, case preserved.
                        let mut ch = raw.chars();
                        let mut c = ch.next()?;
                        if ch.next().is_some() {
                            return None;
                        }
                        // A bare uppercase ASCII token represents the same
                        // logical action as a GUI Shift+letter press. Preserve
                        // that inferred modifier so negotiated Kitty CSI-u can
                        // report the unshifted primary key and shifted
                        // alternate key instead of misreporting a Caps-Lock
                        // style unmodified uppercase key.
                        if c.is_ascii_uppercase() {
                            mods |= ModifiersState::SHIFT;
                        }
                        // Keep SHIFT on alphabetic chords while normalizing
                        // their logical character to uppercase: the legacy
                        // encoder still emits the expected byte, while Kitty
                        // CSI-u needs the live modifier bit to distinguish
                        // Ctrl+C from Ctrl+Shift+C.
                        if mods.contains(ModifiersState::SHIFT) && c.is_ascii_alphabetic() {
                            c = c.to_ascii_uppercase();
                        }
                        Key::Character(c.to_string().into())
                    }
                });
            }
        }
    }
    key.map(|k| (mods, k))
}

fn push_unique_trigger(out: &mut Vec<Trigger>, trigger: Trigger) {
    if !out.contains(&trigger) {
        out.push(trigger);
    }
}

fn physical_keybind_chars(physical: &PhysicalKey, mods: ModifiersState) -> &'static [char] {
    match physical {
        PhysicalKey::Code(KeyCode::Equal) => {
            if mods.shift_key() {
                &['=', '+']
            } else {
                &['=']
            }
        }
        PhysicalKey::Code(KeyCode::Minus) => {
            if mods.shift_key() {
                &['-', '_']
            } else {
                &['-']
            }
        }
        PhysicalKey::Code(KeyCode::NumpadAdd) => &['+'],
        PhysicalKey::Code(KeyCode::NumpadSubtract) => &['-'],
        PhysicalKey::Code(KeyCode::NumpadEqual) => &['='],
        PhysicalKey::Code(KeyCode::Digit0) | PhysicalKey::Code(KeyCode::Numpad0) => &['0'],
        _ => &[],
    }
}

fn keybind_candidates(
    logical_key: Option<&Key>,
    physical_key: Option<&PhysicalKey>,
    mods: ModifiersState,
) -> Vec<Trigger> {
    let mut out = Vec::new();
    let kmods = to_mods(mods);
    if let Some(k) = logical_key.and_then(to_kkey) {
        push_unique_trigger(&mut out, Trigger::new(kmods, k));
    }
    if let Some(physical) = physical_key {
        for c in physical_keybind_chars(physical, mods) {
            push_unique_trigger(&mut out, Trigger::new(kmods, KKey::Char(*c)));
        }
    }
    out
}

/// Whether the search bar uses a key chord itself, on macOS or elsewhere.
/// Typed text is decided separately (`modal_input::accept_text`), and any
/// other chord goes on to Kettle's shortcuts.
///
/// The bar keeps what a native find field keeps: Escape, Enter, Tab and F3
/// without Ctrl, Cmd or Alt; Backspace and Delete, alone or with the word
/// modifier (and Cmd on macOS); the caret keys with Shift
/// and the word modifier (Option on macOS, Ctrl elsewhere), plus Cmd on macOS
/// for the line ends; the shortcut key (Cmd on macOS, Ctrl elsewhere) with
/// A, C, V, X, G and Z; and on macOS the Ctrl text-field keys. `Cmd+Opt+Arrow`
/// and Linux's `Alt+Arrow` move focus between splits, `Ctrl+Home` / `Ctrl+End`
/// scroll the terminal, and on Linux `Ctrl+Shift+A` and `Ctrl+Shift+X` keep
/// their split and zoom meanings.
fn search_bar_claims(
    key: &Key,
    mods: ModifiersState,
    macos: bool,
    editor_focused: bool,
    vim_menu_nav: bool,
) -> bool {
    let (ctrl, alt, sup, shift) = (
        mods.control_key(),
        mods.alt_key(),
        mods.super_key(),
        mods.shift_key(),
    );
    let shortcut_only = if macos {
        sup && !ctrl && !alt
    } else {
        ctrl && !sup && !alt
    };
    let no_chord = !ctrl && !sup && !alt;
    let caret_chord = if macos {
        !ctrl && !(sup && alt)
    } else {
        !alt && !sup
    };
    match key {
        Key::Named(NamedKey::Escape) => true,
        // Deletion takes the word modifier, and Cmd for the line ends on
        // macOS; any other chord is left for a shortcut.
        Key::Named(NamedKey::Backspace | NamedKey::Delete) => {
            if macos {
                !ctrl
            } else {
                !alt && !sup
            }
        }
        Key::Named(NamedKey::Enter | NamedKey::F3 | NamedKey::Tab) => no_chord,
        Key::Named(NamedKey::ArrowLeft | NamedKey::ArrowRight) => editor_focused && caret_chord,
        Key::Named(NamedKey::Home | NamedKey::End) => editor_focused && no_chord,
        Key::Named(NamedKey::Space) => !editor_focused && no_chord,
        Key::Character(s) => {
            let lower = s.to_ascii_lowercase();
            let vim = vim_menu_nav && ctrl && !alt && matches!(s.as_str(), "j" | "k" | "n" | "p");
            let shortcut = shortcut_only
                && match lower.as_str() {
                    "g" | "z" | "c" | "v" => true,
                    "a" | "x" => macos || !shift,
                    _ => false,
                };
            let text_field = macos
                && editor_focused
                && ctrl
                && !sup
                && !alt
                && !shift
                && matches!(lower.as_str(), "a" | "e" | "b" | "f" | "d" | "h" | "k");
            let press = s == " " && !editor_focused && no_chord;
            vim || shortcut || text_field || press
        }
        _ => false,
    }
}

/// The text a key types into the query, from what the shared modal rule
/// accepted (`accepted`). An Alt chord that is bound to a shortcut runs the
/// shortcut instead: Linux's `Alt+1` switches to tab 1 rather than typing `1`.
/// On Windows AltGr arrives as Ctrl+Alt (`altgr_is_ctrl_alt`), and it keeps
/// typing the character it composes.
fn search_bar_text(
    accepted: Option<&str>,
    mods: ModifiersState,
    bound: bool,
    altgr_is_ctrl_alt: bool,
) -> Option<&str> {
    let altgr = altgr_is_ctrl_alt && mods.control_key();
    accepted.filter(|_| !(mods.alt_key() && !altgr && bound))
}

/// How a Kettle shortcut behaves while the search bar has the keyboard.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchBarShortcut {
    /// It types into the terminal, which does not have the keyboard.
    Typing,
    /// It copies from the query, or the grid selection under the bar.
    Copy,
    /// It pastes into the query.
    Paste,
    /// It runs as usual.
    Run,
}

fn search_bar_shortcut_kind(action: &Action) -> SearchBarShortcut {
    match action {
        Action::SendText(_)
        | Action::SendNewline
        | Action::InsertPaneNumber
        | Action::InsertPanePadded
        | Action::InsertPaneName
        | Action::PastePrimary => SearchBarShortcut::Typing,
        Action::Copy => SearchBarShortcut::Copy,
        Action::Paste => SearchBarShortcut::Paste,
        _ => SearchBarShortcut::Run,
    }
}

/// Whether a held key's repeat is dropped in the search bar. A focused
/// toggle or Close acts once per press, as a native button does, so holding
/// Space or Enter does not flip a setting (and rewrite the config) at the
/// repeat rate. Previous and Next repeat, like Enter held in the query.
fn search_button_ignores_repeat(focused: kettle_render::SearchControl, key: &Key) -> bool {
    let activates = match key {
        Key::Named(NamedKey::Space | NamedKey::Enter) => true,
        Key::Character(text) => text == " ",
        _ => false,
    };
    activates
        && !matches!(
            focused,
            kettle_render::SearchControl::Editor
                | kettle_render::SearchControl::Previous
                | kettle_render::SearchControl::Next
        )
}

/// Drop the repeats of a key that closed a Kettle modal. They belong to the
/// press the modal consumed, not to the terminal it uncovered; its release is
/// already suppressed with that press. The key's release, or a fresh press of
/// it, ends the suppression. Returns whether to drop this event.
fn drop_closing_key_repeat(
    closing: &mut HashSet<PhysicalKey>,
    physical_key: PhysicalKey,
    state: ElementState,
    repeat: bool,
) -> bool {
    if !closing.contains(&physical_key) {
        return false;
    }
    if state == ElementState::Pressed && repeat {
        return true;
    }
    closing.remove(&physical_key);
    false
}

/// The Kettle modal that owns the keyboard, in the keyboard path's dispatch
/// order (the first open one gets the key).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum KeyModal {
    ConfirmDialog,
    ContextMenu,
    ViMode,
    Hint,
    Palette,
    ThemePicker,
    SettingsText,
    SettingsCapture,
    Settings,
    LayoutPicker,
    Ssh,
    TitleEdit,
    Search,
    /// A preview lane holding the keyboard (`focus_preview`).
    Preview,
}

fn top_modal(ws: &WindowState) -> Option<KeyModal> {
    Some(if ws.confirm_dialog.is_some() {
        KeyModal::ConfirmDialog
    } else if ws.context_menu.is_some() {
        KeyModal::ContextMenu
    } else if ws.vi_mode.is_some() {
        KeyModal::ViMode
    } else if ws.hint_state.is_some() {
        KeyModal::Hint
    } else if ws.palette_input.is_some() {
        KeyModal::Palette
    } else if ws.theme_picker_input.is_some() {
        KeyModal::ThemePicker
    } else if ws.settings_nav.is_some() && ws.settings_text_edit.is_some() {
        KeyModal::SettingsText
    } else if settings_capture_active(ws) {
        KeyModal::SettingsCapture
    } else if ws.settings_nav.is_some() {
        KeyModal::Settings
    } else if ws.layout_picker_input.is_some() {
        KeyModal::LayoutPicker
    } else if ws.ssh_input.is_some() {
        KeyModal::Ssh
    } else if ws.editing_title.is_some() {
        KeyModal::TitleEdit
    } else if ws.search.open {
        KeyModal::Search
    } else if ws.preview_focus.is_some() {
        KeyModal::Preview
    } else {
        return None;
    })
}

/// Record `key` as the one that closed or replaced the modal it was pressed
/// in, so its auto-repeats are dropped (`drop_closing_key_repeat`) instead of
/// reaching whatever the modal uncovered: the terminal, the parent Settings
/// under a closed text field, or the layout picker the palette just opened.
/// The modal's input-method composition ends with it, for the same reason.
fn remember_closing_key(ws: &mut WindowState, key_modal: Option<KeyModal>, key: PhysicalKey) {
    if top_modal(ws) != key_modal {
        ws.closing_keys.insert(key);
        end_modal_composition(ws);
    }
}

/// A Kettle modal whose keys do not all repeat (see `modal_repeat_is_inert`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ModalRepeat {
    ConfirmDialog,
    /// `vim_nav`: `vim-menu-nav` is on, so `j`/`k` and Ctrl+D/U move.
    ContextMenu {
        vim_nav: bool,
    },
    ViMode,
    Hint,
    Palette,
    /// `steps`: the focused row is a number, which Left/Right step. On a
    /// toggle or a choice they flip or cycle it and persist each step.
    Settings {
        steps: bool,
    },
}

/// Whether an auto-repeat of `key` must do nothing in `modal`. Keys that
/// activate, toggle or pick act once per press: holding the Enter that opened
/// a submenu would otherwise activate its first row, and holding Space on a
/// Settings toggle would flip it at the repeat rate. Keys that move keep
/// repeating.
fn modal_repeat_is_inert(modal: ModalRepeat, repeat: bool, key: &Key, ctrl: bool) -> bool {
    if !repeat {
        return false;
    }
    let moves = |key: &Key| {
        matches!(
            key,
            Key::Named(
                NamedKey::ArrowUp
                    | NamedKey::ArrowDown
                    | NamedKey::ArrowLeft
                    | NamedKey::ArrowRight
                    | NamedKey::PageUp
                    | NamedKey::PageDown
                    | NamedKey::Tab
            )
        )
    };
    let letter = |key: &Key, letters: &[&str]| matches!(key, Key::Character(c) if letters.iter().any(|l| c.eq_ignore_ascii_case(l)));
    match modal {
        // Rows are also picked by mnemonic letters and vim `l`; only the
        // highlight moves repeat: arrows, and with vim-menu-nav `j`/`k` and
        // Ctrl+D/U half pages. Without it, `j` and `k` are mnemonics.
        ModalRepeat::ContextMenu { vim_nav } => {
            let vim_move = vim_nav
                && if ctrl {
                    letter(key, &["d", "u"])
                } else {
                    letter(key, &["j", "k"])
                };
            !(moves(key) || vim_move)
        }
        // A dialog's letters and Enter/Space answer it; focus moves repeat.
        ModalRepeat::ConfirmDialog => !moves(key),
        // The query is typed text; only Enter runs the selection.
        ModalRepeat::Palette => matches!(key, Key::Named(NamedKey::Enter)),
        // Enter and Space activate or toggle the focused row. Left/Right (and
        // vim `h`/`l`) step a number and repeat; on a toggle or a choice they
        // flip or cycle it, persisting each step, so act once per press.
        ModalRepeat::Settings { steps } => {
            matches!(key, Key::Named(NamedKey::Enter | NamedKey::Space))
                || (!steps
                    && (matches!(key, Key::Named(NamedKey::ArrowLeft | NamedKey::ArrowRight))
                        || letter(key, &["h", "l"])))
        }
        // `v` toggles visual mode; motions repeat.
        ModalRepeat::ViMode => letter(key, &["v"]),
        // Label letters only pick a target; nothing in hint mode moves.
        ModalRepeat::Hint => true,
    }
}

/// Whether the Settings overlay is waiting for a keybind chord.
fn settings_capture_active(ws: &WindowState) -> bool {
    ws.settings_nav.as_ref().is_some_and(|nav| nav.capturing)
}

/// Whether an action flips a state, so auto-repeat of its held chord must not
/// run it again: the chord would otherwise flip the state back and forth for
/// as long as it is held, and leave it wherever the last repeat fell. Such a
/// repeat is still consumed, so it never reaches the program.
fn toggles_once_per_press(action: &Action) -> bool {
    matches!(
        action,
        Action::ToggleViMode
            | Action::ToggleZoom
            | Action::ScaledZoom
            | Action::ToggleFullscreen
            | Action::ToggleBroadcastAll
            | Action::ToggleBroadcastGroup
            | Action::ToggleBroadcastOff
            | Action::ToggleBroadcastWindow
            | Action::ToggleCopyOnSelect
            | Action::ToggleCursorBlink
            | Action::ToggleMouseHide
            | Action::TogglePaneReadOnly
            | Action::ToggleScrollbar
            | Action::ToggleLightDark
            | Action::ToggleSessionLog
            | Action::ToggleGroupAll
            | Action::ToggleGroupTab
            | Action::ToggleGroupWindow
            | Action::ToggleWindowVisibility
            | Action::OpenMediaShelf
    )
}

/// Whether a key press is bound to toggling vi mode. Vi mode takes every key
/// before the keybind table is consulted, so without this check the chord
/// that entered it (`Ctrl+Shift+Space` by default) could not leave it.
fn is_vi_mode_toggle_chord(
    bindings: &Bindings,
    logical_key: &Key,
    physical_key: &PhysicalKey,
    mods: ModifiersState,
) -> bool {
    matches!(
        resolve_keybind_action(bindings, Some(logical_key), Some(physical_key), mods),
        Some((_, Action::ToggleViMode))
    )
}

fn resolve_keybind_action(
    bindings: &Bindings,
    logical_key: Option<&Key>,
    physical_key: Option<&PhysicalKey>,
    mods: ModifiersState,
) -> Option<(Trigger, Action)> {
    keybind_candidates(logical_key, physical_key, mods)
        .into_iter()
        .find_map(|trigger| {
            bindings
                .get(&trigger)
                .cloned()
                .map(|action| (trigger, action))
        })
}

/// The non-macOS default `Alt+Arrow` focus chords are adaptive at the edge of
/// the visible split tree. When a visible neighbour exists, the keybind owns
/// the chord and moves focus. When no visible pane exists in that direction,
/// the original key event falls through to the PTY, preserving application
/// bindings such as Codex's `Alt+Left`/`Alt+Right` word motion and `Alt+Up`
/// previous-message editor.
///
/// "Visible" is the operative word: a zoomed pane (`Ctrl+Shift+X`, or the
/// `scaled_zoom` action) hides its siblings, so directional focus has nowhere to go
/// and the chord belongs to the program until the zoom is released. A Kettle
/// no-op there would swallow the press and its release for nothing.
///
/// Match the trigger and action as a pair. A user who deliberately binds
/// `Alt+Up` to some other action must get that action, not an implicit terminal
/// fallback, and actions invoked from menus or automation have no physical
/// chord to reinterpret. macOS keeps its explicit focus chords
/// (`Cmd+Opt+Arrow` and `Ctrl+Cmd+Arrow`) and leaves Option+Arrow entirely to
/// the terminal.
fn adaptive_alt_focus_direction(
    trigger: Trigger,
    action: &Action,
    enabled: bool,
) -> Option<(i32, i32)> {
    if !enabled || trigger.mods != Mods::ALT {
        return None;
    }
    match (trigger.key, action) {
        (KKey::Up, Action::FocusUp) => Some((0, -1)),
        (KKey::Down, Action::FocusDown) => Some((0, 1)),
        (KKey::Left, Action::FocusLeft) => Some((-1, 0)),
        (KKey::Right, Action::FocusRight) => Some((1, 0)),
        _ => None,
    }
}

/// Whether an adaptive focus chord belongs to the terminal rather than to
/// Kettle. `visible_neighbor_exists` is the mux's answer for the chord's
/// direction; it is already `false` while zoom collapses the layout to the
/// focused pane, so no separate zoom flag is consulted.
fn adaptive_alt_focus_falls_through(
    trigger: Trigger,
    action: &Action,
    enabled: bool,
    visible_neighbor_exists: bool,
) -> bool {
    !visible_neighbor_exists && adaptive_alt_focus_direction(trigger, action, enabled).is_some()
}

/// How a default chord shares its key with a program that owns the keyboard
/// (see `chord_goes_to_program`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ProgramKeyRule {
    /// The program always gets it: Shift+Arrow split resize, which Codex
    /// (Shift+Left answers a queued question), Claude Code, Neovim, fish and
    /// every text field use too.
    ProgramFirst,
    /// The program gets it only when Kettle's action would do nothing (no
    /// prompt to jump to, nothing to scroll, one tab, no selection to extend)
    /// and the view is not scrolled into history. Copy has no rule: Codex
    /// reads Ctrl+Shift+C as Ctrl+C, which would discard a draft.
    WhenKettleIdle,
    /// As `WhenKettleIdle`, for pane-focus chords that have nowhere to go (a
    /// zoomed or single-pane tab, or no pane on that side), and only while the
    /// pane's negotiated keyboard mode tells the chord apart. Sent in plain
    /// legacy mode, Ctrl+Shift+N would arrive as Ctrl+N, a different key, and
    /// a Command chord would arrive as nothing at all.
    WhenKettleIdleAndDistinct,
}

/// The rule for this chord under the user's config: none with
/// `keybind-yield = off`, and none for a trigger the config binds itself, even
/// to its default action, so a chord the user bound is always Kettle's.
fn configured_program_key_rule(
    cfg: &kettle_config::Config,
    trigger: Trigger,
    action: &Action,
    macos: bool,
) -> Option<ProgramKeyRule> {
    if cfg.keybind_yield == kettle_config::KeybindYield::Off
        || cfg.keybinds_declared.contains(&trigger)
    {
        return None;
    }
    program_key_rule(trigger, action, macos)
}

/// The default chords a program that owns the keyboard can have, matched as
/// exact (trigger, action) pairs, as `adaptive_alt_focus_direction` does: a
/// chord the user binds to anything, or an action the user moves to another
/// chord, is always Kettle's.
fn program_key_rule(trigger: Trigger, action: &Action, macos: bool) -> Option<ProgramKeyRule> {
    use KKey::*;
    use ProgramKeyRule::*;

    let shift = Mods::SHIFT;
    let ctrl = Mods::CTRL;
    let ctrl_shift = Mods::CTRL | Mods::SHIFT;
    let rule = match (trigger.mods, trigger.key, action) {
        (m, Up, Action::ResizeUp)
        | (m, Down, Action::ResizeDown)
        | (m, Left, Action::ResizeLeft)
        | (m, Right, Action::ResizeRight)
            if m == shift =>
        {
            ProgramFirst
        }
        (m, Up, Action::JumpPrevPrompt) | (m, Down, Action::JumpNextPrompt)
            if m == ctrl || (macos && m == Mods::SUPER) =>
        {
            WhenKettleIdle
        }
        (m, PageUp, Action::ScrollPageUp)
        | (m, PageDown, Action::ScrollPageDown)
        | (m, Home, Action::SelectToTop)
        | (m, End, Action::SelectToBottom)
            if m == shift =>
        {
            WhenKettleIdle
        }
        (m, Up, Action::ScrollLineUp)
        | (m, Down, Action::ScrollLineDown)
        | (m, PageDown, Action::MoveTabRight)
        | (m, PageUp, Action::MoveTabLeft)
            if m == ctrl_shift =>
        {
            WhenKettleIdle
        }
        (m, Home, Action::ScrollToTop)
        | (m, End, Action::ScrollToBottom)
        | (m, PageDown, Action::NextTab)
        | (m, PageUp, Action::PrevTab)
            if m == ctrl =>
        {
            WhenKettleIdle
        }
        (m, Char('n'), Action::FocusNext) | (m, Char('p'), Action::FocusPrev)
            if m == ctrl_shift =>
        {
            WhenKettleIdleAndDistinct
        }
        // macOS's two directional focus chords. Alt+Arrow elsewhere already
        // falls through when it has nowhere to go
        // (`adaptive_focus_chord_falls_through`).
        (m, Up, Action::FocusUp)
        | (m, Down, Action::FocusDown)
        | (m, Left, Action::FocusLeft)
        | (m, Right, Action::FocusRight)
            if macos && (m == Mods::ALT | Mods::SUPER || m == Mods::CTRL | Mods::SUPER) =>
        {
            WhenKettleIdleAndDistinct
        }
        // Alt+1-9 everywhere, and Cmd+1-9 on macOS.
        (m, Char(digit @ '1'..='9'), Action::GotoTab(index))
            if (m == Mods::ALT || (macos && m == Mods::SUPER))
                && u32::from(*index) + 1 == digit.to_digit(10).unwrap_or(0) =>
        {
            WhenKettleIdle
        }
        _ => return None,
    };
    Some(rule)
}

/// The window state that decides whether a Kettle action would do anything.
struct KettleActionState {
    tabs: usize,
    current_tab: usize,
    /// The pane has a Kettle selection (even an empty one a click left), which
    /// `Shift+Home/End` would extend.
    selection_exists: bool,
    /// A focus action has a visible pane to move to.
    focus_target_exists: bool,
    /// The pane's keyboard mode encodes the chord as itself (see
    /// [`chord_reaches_program_distinctly`]).
    chord_is_distinct: bool,
}

/// Whether Kettle's action would change nothing if it ran now, with the view
/// at the bottom (`program_gets_chord` never asks otherwise).
fn kettle_action_is_idle(
    action: &Action,
    claims: &kettle_core::KeyboardClaims,
    kettle: &KettleActionState,
) -> bool {
    let no_history = claims.alt_screen || claims.history_size == 0;
    match action {
        Action::JumpPrevPrompt => !claims.prompt_above,
        Action::JumpNextPrompt => !claims.prompt_below,
        Action::ScrollToTop | Action::ScrollPageUp | Action::ScrollLineUp => no_history,
        Action::ScrollToBottom | Action::ScrollPageDown | Action::ScrollLineDown => true,
        // With nothing selected, Kettle would start a selection at the
        // program's cursor; a program that owns the keyboard wants the key.
        Action::SelectToTop | Action::SelectToBottom => !kettle.selection_exists,
        Action::NextTab | Action::PrevTab | Action::MoveTabLeft | Action::MoveTabRight => {
            kettle.tabs < 2
        }
        Action::GotoTab(index) => {
            let index = usize::from(*index);
            index >= kettle.tabs || index == kettle.current_tab
        }
        Action::FocusUp
        | Action::FocusDown
        | Action::FocusLeft
        | Action::FocusRight
        | Action::FocusNext
        | Action::FocusPrev => !kettle.focus_target_exists,
        _ => false,
    }
}

/// Whether a program that owns the keyboard gets a chord with this rule.
///
/// A view scrolled into history keeps every `WhenKettleIdle` chord Kettle's:
/// a key that reached the program would snap the view back to the bottom
/// (`scroll-on-keystroke`), so the user reading scrollback would lose their
/// place at its top, and a held key would bounce between the two.
fn program_gets_chord(
    rule: ProgramKeyRule,
    action: &Action,
    claims: &kettle_core::KeyboardClaims,
    kettle: &KettleActionState,
) -> bool {
    if !claims.program_owns_keyboard() {
        return false;
    }
    match rule {
        ProgramKeyRule::ProgramFirst => true,
        ProgramKeyRule::WhenKettleIdle => {
            claims.display_offset == 0 && kettle_action_is_idle(action, claims, kettle)
        }
        ProgramKeyRule::WhenKettleIdleAndDistinct => {
            kettle.chord_is_distinct
                && claims.display_offset == 0
                && kettle_action_is_idle(action, claims, kettle)
        }
    }
}

/// Whether the pane's keyboard mode sends this chord as a key of its own: it
/// encodes to bytes, and those bytes differ from the same key with any one of
/// its modifiers released. Plain legacy mode sends Ctrl+Shift+N exactly as
/// Ctrl+N and a Command chord as nothing, so a program could only mistake the
/// one for another key or never see the other.
fn chord_reaches_program_distinctly(trigger: Trigger, mode: kettle_core::TermMode) -> bool {
    // The press below carries no text. A real Ctrl+Shift+N does, its Control
    // character, and with kitty flags that neither disambiguate nor report all
    // keys (event types alone, say) that text sends it down the legacy path as
    // Ctrl+N. Only those two flags build the kitty sequence for a character
    // key whatever its text, so require one of them.
    if matches!(trigger.key, KKey::Char(_))
        && mode.intersects(kettle_core::TermMode::KITTY_KEYBOARD_PROTOCOL)
        && !mode.intersects(
            kettle_core::TermMode::DISAMBIGUATE_ESC_CODES
                | kettle_core::TermMode::REPORT_ALL_KEYS_AS_ESC,
        )
    {
        return false;
    }
    let Some(key) = chord_key(trigger.key) else {
        return false;
    };
    let mods = chord_modifiers(trigger.mods);
    let Some(bytes) = crate::input::encode_key_press(&key, mods, mode) else {
        return false;
    };
    [
        ModifiersState::SHIFT,
        ModifiersState::CONTROL,
        ModifiersState::ALT,
        ModifiersState::SUPER,
    ]
    .into_iter()
    .filter(|m| mods.contains(*m))
    .all(|m| crate::input::encode_key_press(&key, mods - m, mode).as_deref() != Some(&bytes[..]))
}

/// The winit key for the keys a [`ProgramKeyRule::WhenKettleIdleAndDistinct`]
/// chord uses. A shifted letter is the lowercase character with Shift held, as
/// winit reports it once the modifier is applied by the keybind lookup.
fn chord_key(key: KKey) -> Option<Key> {
    Some(match key {
        KKey::Up => Key::Named(NamedKey::ArrowUp),
        KKey::Down => Key::Named(NamedKey::ArrowDown),
        KKey::Left => Key::Named(NamedKey::ArrowLeft),
        KKey::Right => Key::Named(NamedKey::ArrowRight),
        KKey::Char(c) => Key::Character(c.to_string().into()),
        _ => return None,
    })
}

fn chord_modifiers(m: Mods) -> ModifiersState {
    let mut out = ModifiersState::empty();
    out.set(ModifiersState::SHIFT, m.contains(Mods::SHIFT));
    out.set(ModifiersState::CONTROL, m.contains(Mods::CTRL));
    out.set(ModifiersState::ALT, m.contains(Mods::ALT));
    out.set(ModifiersState::SUPER, m.contains(Mods::SUPER));
    out
}

fn parse_ctl_mods(
    value: Option<&serde_json::Value>,
) -> std::result::Result<ModifiersState, String> {
    let mut mods = ModifiersState::empty();
    let Some(value) = value else {
        return Ok(mods);
    };
    let parts: Vec<String> = if let Some(s) = value.as_str() {
        if s.trim().is_empty() {
            Vec::new()
        } else {
            s.split('+').map(|p| p.trim().to_string()).collect()
        }
    } else if let Some(arr) = value.as_array() {
        let mut out = Vec::with_capacity(arr.len());
        for item in arr {
            let Some(s) = item.as_str() else {
                return Err("'mods' array entries must be strings".to_string());
            };
            out.push(s.to_string());
        }
        out
    } else {
        return Err("'mods' must be a string like 'ctrl+shift' or an array".to_string());
    };
    for part in parts {
        match part.trim().to_ascii_lowercase().as_str() {
            "" => {}
            "ctrl" | "control" => mods |= ModifiersState::CONTROL,
            "alt" | "opt" | "option" => mods |= ModifiersState::ALT,
            "shift" => mods |= ModifiersState::SHIFT,
            "super" | "cmd" | "command" | "win" | "windows" | "meta" | "logo" => {
                mods |= ModifiersState::SUPER;
            }
            other => return Err(format!("unknown modifier '{other}'")),
        }
    }
    Ok(mods)
}

fn parse_ctl_logical_key(
    value: Option<&serde_json::Value>,
) -> std::result::Result<Option<Key>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    let Some(token) = value.as_str() else {
        return Err("'logical' must be a key token string".to_string());
    };
    if matches!(
        token.trim().to_ascii_lowercase().as_str(),
        "" | "none" | "unidentified"
    ) {
        return Ok(None);
    }
    let Some((mods, key)) = parse_send_key(token) else {
        return Err(format!("unrecognized logical key token '{token}'"));
    };
    if !mods.is_empty() {
        return Err("'logical' must be one key token without modifiers".to_string());
    }
    Ok(Some(key))
}

fn parse_ctl_physical_key(
    value: Option<&serde_json::Value>,
) -> std::result::Result<Option<PhysicalKey>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    let Some(raw) = value.as_str() else {
        return Err("'physical' must be a key-code string".to_string());
    };
    let normalized: String = raw
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect();
    if matches!(normalized.as_str(), "" | "none" | "unidentified") {
        return Ok(None);
    }
    let code = match normalized.as_str() {
        "equal" | "equals" => KeyCode::Equal,
        "minus" => KeyCode::Minus,
        "digit0" | "key0" | "0" => KeyCode::Digit0,
        "numpadadd" | "numpadplus" => KeyCode::NumpadAdd,
        "numpadsubtract" | "numpadminus" => KeyCode::NumpadSubtract,
        "numpadequal" | "numpadequals" => KeyCode::NumpadEqual,
        "numpad0" => KeyCode::Numpad0,
        _ => return Err(format!("unsupported physical key code '{raw}'")),
    };
    Ok(Some(PhysicalKey::Code(code)))
}

fn to_kkey(key: &Key) -> Option<KKey> {
    Some(match key {
        Key::Character(s) => KKey::Char(s.chars().next()?.to_ascii_lowercase()),
        Key::Named(n) => match n {
            NamedKey::ArrowUp => KKey::Up,
            NamedKey::ArrowDown => KKey::Down,
            NamedKey::ArrowLeft => KKey::Left,
            NamedKey::ArrowRight => KKey::Right,
            NamedKey::PageUp => KKey::PageUp,
            NamedKey::PageDown => KKey::PageDown,
            NamedKey::Home => KKey::Home,
            NamedKey::End => KKey::End,
            NamedKey::Enter => KKey::Enter,
            NamedKey::Tab => KKey::Tab,
            // winit reports the space bar as a named key, never as the
            // character " ", so without this the `ctrl+shift+space` vi-mode
            // default, and any `space` chord in a config, never matched.
            NamedKey::Space => KKey::Char(' '),
            // Without these two the `cmd+backspace` default parses out of the
            // config and then never matches a real key press.
            NamedKey::Backspace => KKey::Backspace,
            NamedKey::Delete => KKey::Delete,
            NamedKey::F1 => KKey::F(1),
            NamedKey::F2 => KKey::F(2),
            NamedKey::F3 => KKey::F(3),
            NamedKey::F4 => KKey::F(4),
            NamedKey::F5 => KKey::F(5),
            NamedKey::F6 => KKey::F(6),
            NamedKey::F7 => KKey::F(7),
            NamedKey::F8 => KKey::F(8),
            NamedKey::F9 => KKey::F(9),
            NamedKey::F10 => KKey::F(10),
            NamedKey::F11 => KKey::F(11),
            NamedKey::F12 => KKey::F(12),
            _ => return None,
        },
        _ => return None,
    })
}

/// Whether a captured `(mods, key)` chord is safe to bind from the settings
/// keybind-capture overlay.
///
/// A modifier-LESS chord is rejected unless the key is an F-key. The global
/// key path matches keybinds before text encoding, so binding a bare `a` (a
/// mis-press during capture) would make every future `a` fire the action
/// instead of typing, across all panes, persisted across restarts, with no
/// in-overlay unbind. Enter/Tab/arrows are likewise essential unmodified, so
/// only F-keys (which produce no text) may be bound without a modifier.
fn keybind_chord_is_safe(mods: Mods, key: KKey) -> bool {
    !mods.is_empty() || matches!(key, KKey::F(_))
}

fn to_mods(m: ModifiersState) -> Mods {
    let mut out = Mods::empty();
    if m.shift_key() {
        out |= Mods::SHIFT;
    }
    if m.control_key() {
        out |= Mods::CTRL;
    }
    if m.alt_key() {
        out |= Mods::ALT;
    }
    if m.super_key() {
        out |= Mods::SUPER;
    }
    out
}

/// A row hint adds dependencies or timing, rather than repeating the control.
/// Whether `saved` would show Kettle in another language than `running`.
/// `os_locale` runs only for `auto`.
fn language_change_pending(
    saved: kettle_config::LanguagePreference,
    running: kettle_i18n::Language,
    os_locale: impl FnOnce() -> Option<String>,
) -> bool {
    saved.resolve(os_locale) != running
}

fn settings_footer_note(
    tr: &kettle_i18n::Translator,
    active_gpu: Option<&str>,
    focused_key: Option<&str>,
    restart_pending: bool,
    language_pending: bool,
    agent_previews: Option<kettle_i18n::Text>,
) -> Option<String> {
    use kettle_i18n::Text;
    let mut notes = Vec::new();
    if let Some(gpu) = active_gpu {
        notes.push(gpu);
    }
    match focused_key {
        Some("agent-display" | "agent-display-claude-code" | "agent-display-codex") => {
            notes.extend(agent_previews.map(|note| tr.text(note)));
        }
        Some("window-blur" | "background-opacity") => {
            notes.push(tr.text(Text::SettingsNoteBlur));
        }
        Some("completion-overlay") => notes.push(tr.text(Text::SettingsNoteNewShells)),
        // A new window keeps the process's language, unlike the changes the
        // general restart note covers.
        Some("language") if !language_pending => {
            notes.push(tr.text(Text::SettingsNoteLanguage));
        }
        _ => {}
    }
    if language_pending {
        notes.push(tr.text(Text::SettingsNoteLanguagePending));
    }
    if restart_pending {
        // The pending flag records no cause, even when Graphics is selected.
        notes.push(tr.text(Text::SettingsNoteRestart));
    }
    (!notes.is_empty()).then(|| notes.join("\n"))
}

/// What the Claude Code row's footer says: why new panes get no plugin, or
/// else when the setting applies.
fn claude_code_note(
    display_on: bool,
    refusal: Option<crate::agent_plugin::PluginRefusal>,
) -> kettle_i18n::Text {
    use crate::agent_plugin::PluginRefusal;
    use kettle_i18n::Text;
    match refusal {
        Some(PluginRefusal::SideloadDisabled) => Text::SettingsNoteClaudeCodeForbidden,
        Some(PluginRefusal::Translocated) => Text::SettingsNoteClaudeCodeTranslocated,
        Some(
            PluginRefusal::UnnamedExecutable
            | PluginRefusal::UnnamedDirectory
            | PluginRefusal::Unverified,
        ) => Text::SettingsNoteClaudeCodeUnavailable,
        Some(PluginRefusal::Unsupported) => Text::SettingsNoteClaudeCodeUnsupported,
        None if !display_on => Text::SettingsNoteClaudeCodeNeedsPreviews,
        None => Text::SettingsNoteClaudeCodeNewPanes,
    }
}

/// What the Codex row's footer says: why new panes' shells get no `codex`,
/// or else where and when the setting applies.
fn codex_note(
    display_on: bool,
    refusal: Option<crate::codex_shell::ShellRefusal>,
) -> kettle_i18n::Text {
    use crate::codex_shell::ShellRefusal;
    use kettle_i18n::Text;
    match refusal {
        Some(ShellRefusal::Translocated) => Text::SettingsNoteCodexTranslocated,
        Some(ShellRefusal::Unavailable) => Text::SettingsNoteCodexUnavailable,
        Some(ShellRefusal::Unsupported) => Text::SettingsNoteCodexUnsupported,
        None if !display_on => Text::SettingsNoteCodexNeedsPreviews,
        None => Text::SettingsNoteCodexNewPanes,
    }
}

/// What the Agent previews row's footer says: the one fact that explains
/// the row's effect right now, most surprising first. `launch_allows` is
/// whether this launch's flags let the row turn display on at all.
fn agent_previews_note(
    saved: bool,
    policy: kettle_ctl::CtlPolicy,
    launch_allows: bool,
    server_running: bool,
    start_attempted: bool,
) -> kettle_i18n::Text {
    use kettle_i18n::Text;
    if policy.runs_server() && !server_running && start_attempted {
        Text::SettingsNoteAgentPreviewsUnavailable
    } else if policy.server() == kettle_config::AgentServer::Full {
        Text::SettingsNoteAgentPreviewsFull
    } else if !launch_allows && !policy.display() {
        Text::SettingsNoteAgentPreviewsLaunchOff
    } else if !saved && policy.display() {
        Text::SettingsNoteAgentPreviewsPendingOff
    } else {
        Text::SettingsNoteAgentPreviews
    }
}

/// The Settings footer: each key followed by what it does. The keys are the
/// same in every language; the vim keys show when `vim-menu-nav` is on.
fn settings_hints(tr: &kettle_i18n::Translator, vim_nav: bool) -> String {
    use kettle_i18n::Text;
    let hints: &[(&str, Text)] = if vim_nav {
        &[
            ("↑↓/jk", Text::SettingsHintField),
            ("←→/hl", Text::SettingsHintChange),
            ("g/G", Text::SettingsHintEnds),
            ("Tab", Text::SettingsHintCategory),
            ("Esc", Text::SettingsHintClose),
        ]
    } else {
        &[
            ("↑↓", Text::SettingsHintField),
            ("←→", Text::SettingsHintChange),
            ("Tab", Text::SettingsHintCategory),
            ("Esc", Text::SettingsHintClose),
        ]
    };
    hints
        .iter()
        .map(|(keys, what)| format!("{keys} {}", tr.text(*what)))
        .collect::<Vec<_>>()
        .join("    ")
}

/// A GPU kind from the renderer's adapter info, in the UI's language. An
/// unknown kind shows as the renderer gave it.
fn gpu_kind_text<'a>(tr: &kettle_i18n::Translator, kind: &'a str) -> &'a str {
    use kettle_i18n::Text;
    match kind {
        "Discrete" => tr.text(Text::SettingsGpuKindDiscrete),
        "Integrated" => tr.text(Text::SettingsGpuKindIntegrated),
        "Virtual" => tr.text(Text::SettingsGpuKindVirtual),
        "Software" => tr.text(Text::SettingsGpuKindSoftware),
        "Other" => tr.text(Text::SettingsGpuKindOther),
        kind => kind,
    }
}

/// How the in-settings text-edit buffer is shown in the value column. A short
/// string shows whole; a long one shows an ellipsized tail, so a long path
/// stays readable (the caret/end is what matters while typing) without
/// ballooning the panel width.
fn settings_edit_display(buf: &str) -> String {
    let count = buf.chars().count();
    if count <= 40 {
        return buf.to_string();
    }
    let tail: String = buf.chars().skip(count - 39).collect();
    format!("…{tail}")
}

/// Startup visibility policy. Windows are created hidden while renderer init
/// runs, then visible states are revealed once the wgpu surface is configured.
/// Only `window_state = hidden` remains hidden.
fn should_reveal_after_renderer_init(state: kettle_config::WindowState) -> bool {
    !matches!(state, kettle_config::WindowState::Hidden)
}

/// Some surface backends cannot acquire a first frame while their native
/// window is hidden. macOS Metal is one: `CAMetalLayer::nextDrawable` does not
/// make progress until the `NSWindow` can be ordered on screen. In that case a
/// hide-until-first-presentation policy is circular, so reveal after renderer
/// initialization and immediately before the first surface frame instead.
fn should_reveal_before_first_surface_frame(
    state: kettle_config::WindowState,
    window_shown: bool,
    surface_requires_visible_window: bool,
) -> bool {
    surface_requires_visible_window && !window_shown && should_reveal_after_renderer_init(state)
}

/// Where a session snapshot should be written, if anywhere.
#[derive(Debug, PartialEq, Eq)]
enum SessionWriteTarget<'a> {
    NamedLayout(&'a str),
    DefaultSession,
    Skip,
}

/// Decide where a snapshot goes.
///
/// The rule worth stating out loud is the first arm: **an empty snapshot never
/// overwrites a named layout.** `close_window` deliberately empties the mux
/// before saving, so the SESSION it writes is the empty one ("this window is
/// finished, do not bring it back"). That intent belongs to session.json. Sent
/// to a named layout, the empty snapshot would erase the workspace, and the
/// next `--layout NAME` would open a single default pane. Terminator, whose
/// layouts this mirrors, only ever writes one from an explicit Add/Refresh;
/// launching a layout never modifies it.
///
/// Extracted so the truth table can be driven directly; the arms below are the
/// whole of the routing decision.
fn session_write_target(
    layout: Option<&str>,
    named_layout_writable: bool,
    restore_mode: bool,
    snapshot_is_empty: bool,
) -> SessionWriteTarget<'_> {
    match layout {
        // Never clear a named workspace by quitting.
        Some(_) if snapshot_is_empty => SessionWriteTarget::Skip,
        Some(name) if named_layout_writable => SessionWriteTarget::NamedLayout(name),
        // `--layout NAME` given, but a launch override replaced it: leave the
        // file alone rather than overwriting it with a window that was never
        // restored from it.
        Some(_) => SessionWriteTarget::Skip,
        // Only write the DEFAULT session.json when this launch is in restore
        // mode — symmetric with the opt-in load gate. A fresh (non-opted-in)
        // window must NOT overwrite the saved layout that `--restore` /
        // `restore-session = true` exists to recover.
        None if restore_mode => SessionWriteTarget::DefaultSession,
        None => SessionWriteTarget::Skip,
    }
}

/// Is the default last-session (`session.json`) active for THIS launch?
/// Drives BOTH the startup restore gate (whether to `load()`) and the
/// `save_session` gate (whether to `save()` the default session). They MUST
/// agree. If *load* is opt-in but *save* is not, a fresh, non-opted-in window
/// silently overwrites the saved layout that `--restore` exists to recover.
/// Routing both through this one predicate keeps them symmetric.
/// `--layout NAME` is independent (its own file, explicit intent) and never
/// consults this gate.
fn should_restore_session(startup_restore: bool, cfg_restore_session: bool) -> bool {
    startup_restore || cfg_restore_session
}

/// How long to let the synchronous GPU adapter+device
/// init run before treating it as a hung graphics driver. Real init is ~1.5s;
/// this is deliberately generous so a slow-but-working GPU is never killed,
/// while still bounding the worst case (a wedged driver that never returns)
/// to a clean diagnostic exit instead of an infinite invisible-window hang.
const GPU_INIT_TIMEOUT_SECS: u64 = 30;

const GPU_RECOVERY_SETTLE: std::time::Duration = std::time::Duration::from_millis(700);

fn gpu_escalation_label(escalation: kettle_render::AdapterEscalation) -> &'static str {
    match escalation {
        kettle_render::AdapterEscalation::Preferred => "preferred",
        kettle_render::AdapterEscalation::AlternateBackend => "alternate_backend",
        kettle_render::AdapterEscalation::SurfacePreferred => "surface_preferred",
        kettle_render::AdapterEscalation::AnyHardware => "any_hardware",
        kettle_render::AdapterEscalation::ForceSoftware => "force_software",
    }
}

fn gpu_recovery_backoff(attempt: u32) -> std::time::Duration {
    let ms = match attempt {
        0 | 1 => 500,
        2 => 1000,
        3 => 2000,
        _ => 4000,
    };
    std::time::Duration::from_millis(ms)
}

/// How often the process scan may run. It feeds labels and new-pane
/// directories for shells that never send OSC 7.
const REMOTE_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(200);

/// `None` to poll now, or when the throttled poll must run instead. Dropping
/// it would leave a `cd` that lands inside the window unseen until a redraw.
fn remote_poll_deferred_until(
    last: Option<std::time::Instant>,
    now: std::time::Instant,
) -> Option<std::time::Instant> {
    let due = last? + REMOTE_POLL_INTERVAL;
    (now < due).then_some(due)
}

/// Whether an optional monotonic-clock throttle is eligible at `now`.
///
/// `None` represents "never run" and is immediately eligible. Saturating
/// subtraction also keeps tests and unusual clock implementations safe if a
/// caller supplies a timestamp ordered before `last`.
fn throttle_elapsed(
    last: Option<std::time::Instant>,
    now: std::time::Instant,
    interval: std::time::Duration,
) -> bool {
    last.is_none_or(|last| now.saturating_duration_since(last) >= interval)
}

/// Which pane loses and which gains the focus report when the pane holding
/// the keyboard changes from `reported` to `focused` (`None`: no pane, as
/// while the window lacks OS focus). No change, no reports.
fn focus_report_transition(
    reported: Option<u64>,
    focused: Option<u64>,
) -> (Option<u64>, Option<u64>) {
    if reported == focused {
        (None, None)
    } else {
        (reported, focused)
    }
}

fn cursor_blink_active(configured: bool, pane_requests_blink: bool, window_focused: bool) -> bool {
    configured && pane_requests_blink && window_focused
}

fn normalized_ime_preedit(
    text: String,
    selection: Option<(usize, usize)>,
) -> Option<(String, Option<(usize, usize)>)> {
    (!text.is_empty()).then_some((text, selection))
}

fn ime_preedit_focus(text: &str, selection: Option<(usize, usize)>) -> usize {
    use unicode_segmentation::UnicodeSegmentation as _;

    let requested = selection
        .map_or(text.len(), |(_, focus)| focus)
        .min(text.len());
    let mut boundary = requested;
    while boundary > 0 && !text.is_char_boundary(boundary) {
        boundary -= 1;
    }
    if boundary == text.len() {
        return boundary;
    }
    text.grapheme_indices(true)
        .map(|(index, _)| index)
        .take_while(|index| *index <= boundary)
        .last()
        .unwrap_or(0)
}

/// Watchdog body for the GPU-init guard. Polls `done` every `step`
/// until `timeout` elapses. Returns `true` if the timeout was reached without
/// `done` ever being observed set — i.e. the caller should treat the init as
/// hung — and `false` if `done` was seen in time (init finished, watchdog
/// stands down). Pulled out as a pure-ish helper so the timeout logic is
/// unit-testable without standing up a GPU or calling `process::exit`.
fn gpu_init_timed_out(
    done: &std::sync::atomic::AtomicBool,
    timeout: std::time::Duration,
    step: std::time::Duration,
) -> bool {
    use std::sync::atomic::Ordering;
    let mut waited = std::time::Duration::ZERO;
    while waited < timeout {
        if done.load(Ordering::Acquire) {
            return false;
        }
        std::thread::sleep(step);
        waited += step;
    }
    !done.load(Ordering::Acquire)
}

/// Whether terminal-owned transient chrome may be projected. Keeping this
/// predicate shared prevents a hidden receipt from retaining a hover pause
/// behind a modal surface.
fn terminal_surface_available(ws: &WindowState) -> bool {
    ws.context_menu.is_none()
        && ws.vi_mode.is_none()
        && ws.hint_state.is_none()
        && ws.palette_input.is_none()
        && ws.settings_nav.is_none()
        && ws.layout_picker_input.is_none()
        && ws.theme_picker_input.is_none()
        && ws.ssh_input.is_none()
        && ws.confirm_dialog.is_none()
        && ws.editing_title.is_none()
        && !ws.search.open
        && ws.preview_overlay.is_none()
}

/// Where a pointer event goes while the search bar is open.
///
/// The bar is a reserved lane below the grid, not an overlay: the grid above
/// it is fully visible and stays mouse-interactive, exactly as Terminator
/// keeps its VTE selectable under its search bar. A press inside the bar's
/// rectangle belongs to the bar's controls; a press anywhere else is ordinary
/// grid input (selection, links, scrollbar, mouse reporting). Motion and
/// release follow whichever gesture is live: an editor drag started in the
/// bar keeps the bar, anything else keeps the grid. Keyboard focus never
/// leaves the search editor either way.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchPointerRoute {
    /// The bar is closed; nothing here applies.
    Closed,
    /// The bar's controls own the event.
    Bar,
    /// The grid owns the event as if the bar were closed.
    Grid,
}

// Captured grid drags keep their motion and release when crossing the bar.
fn search_bar_blocks_mouse_report(in_bar: bool, pressed: bool, motion: bool, held: bool) -> bool {
    in_bar && pressed && (!motion || !held)
}

fn search_pointer_route(
    search_open: bool,
    press_in_bar: Option<bool>,
    dragging_editor: bool,
) -> SearchPointerRoute {
    if !search_open {
        return SearchPointerRoute::Closed;
    }
    match press_in_bar {
        Some(true) => SearchPointerRoute::Bar,
        Some(false) => SearchPointerRoute::Grid,
        None if dragging_editor => SearchPointerRoute::Bar,
        None => SearchPointerRoute::Grid,
    }
}

/// Should an open modal swallow a pointer event (mouse press / wheel)
/// instead of letting it fall through to the tab bar, pane focus, or
/// mouse-tracking *behind* the dialog? Otherwise a click could switch tabs or
/// focus a pane, and a wheel could zoom the font or scroll the pane, while a
/// dialog that seems to capture input sits on top. True whenever
/// `any_modal_open` is set, *except* for a lone context menu, which owns its
/// own click/scroll paths and is re-opened (relocated) by a right-click, so
/// gating it here would break that.
fn modal_swallows_pointer(any_modal_open: bool, context_menu_open: bool) -> bool {
    any_modal_open && !context_menu_open
}

impl ApplicationHandler<UserEvent> for App {
    // C1-DISPATCH-BEGIN: take-out/put-back window dispatch.
    //
    // Every per-window field lives on `WindowState` (window_state.rs). Each
    // handler removes the addressed window from the map, runs the inner
    // handler with disjoint `&mut self` (globals) + `&mut WindowState`
    // borrows, then hands the entry to `finish_window_dispatch` — which
    // reinserts it, or drops it when the inner handler flagged the
    // window closed, exiting the loop once no windows remain. A panic
    // mid-handler drops the entry, which is fine: kettle aborts on panic,
    // nothing observes the missing window.
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        let runtime_tracker = self.runtime_tracker.clone();
        let _phase = runtime_tracker.enter("resumed");
        // winit's English application menu is up by now; Kettle's, in the
        // UI's language, takes its place once.
        crate::macos_menu::install(&self.ui_text);
        let seq = self.focused_seq;
        let Some(mut ws) = self.windows.remove(&seq) else {
            return;
        };
        self.resumed_inner(&mut ws, event_loop);
        self.sync_output_wake_gate(&ws);
        self.finish_window_dispatch(event_loop, seq, ws);
        self.drain_activation_requests(event_loop);
        #[cfg(target_os = "linux")]
        {
            if self.wayland.is_none() {
                let proxy = self.proxy.clone();
                self.wayland = crate::wayland::Bridge::new(
                    event_loop.owned_display_handle(),
                    Arc::new(move || {
                        let _ = proxy.send_event(UserEvent::Wayland);
                    }),
                );
            }
            self.poll_wayland(event_loop);
        }
        runtime_tracker.set_window_count(self.windows.len());
    }

    fn user_event(&mut self, el: &ActiveEventLoop, ev: UserEvent) {
        let runtime_tracker = self.runtime_tracker.clone();
        let _phase = runtime_tracker.enter("user_event");
        match ev {
            #[cfg(target_os = "linux")]
            UserEvent::Wayland => self.poll_wayland(el),
            UserEvent::Activation => self.drain_activation_requests(el),
            UserEvent::PastedImageEncoded => self.drain_queued_pastes(el),
            // A watcher event starts a short non-blocking settle window. The
            // pending latch stays closed until about_to_wait clears it just
            // before the single process-level read.
            UserEvent::ReloadConfig => {
                self.config_reload_deadline
                    .get_or_insert_with(|| std::time::Instant::now() + CONFIG_RELOAD_DEBOUNCE);
            }
            UserEvent::LanePlayback => {
                // Each window whose lanes play takes what its sessions have.
                let seqs: Vec<u64> = self
                    .windows
                    .iter()
                    .filter(|(_, window)| !window.lane_playbacks.is_empty())
                    .map(|(&seq, _)| seq)
                    .collect();
                for seq in seqs {
                    let Some(mut ws) = self.windows.remove(&seq) else {
                        continue;
                    };
                    self.poll_lane_playbacks(&mut ws);
                    self.finish_window_dispatch(el, seq, ws);
                }
            }
            UserEvent::MediaRendered => {
                let seq = if self.windows.contains_key(&self.focused_seq) {
                    self.focused_seq
                } else if let Some(seq) = self.windows.keys().next().copied() {
                    seq
                } else {
                    return;
                };
                let Some(mut ws) = self.windows.remove(&seq) else {
                    return;
                };
                self.media_tick(&mut ws);
                self.finish_window_dispatch(el, seq, ws);
            }
            UserEvent::RemoteScanReady => {
                let seq = if self.windows.contains_key(&self.focused_seq) {
                    self.focused_seq
                } else if let Some(seq) = self.windows.keys().next().copied() {
                    seq
                } else {
                    return;
                };
                let Some(mut ws) = self.windows.remove(&seq) else {
                    return;
                };
                self.apply_remote_scan_snapshot(&mut ws);
                self.finish_window_dispatch(el, seq, ws);
            }
            // PTY wakeups carry no pane id. Fan out, with each window gated on
            // its panes' output generations.
            UserEvent::Wakeup => {
                // Reopen the wakeup latch BEFORE any generation reads below. A
                // reader that bumps its generation after this store enqueues a
                // fresh Wakeup, so the new output is painted either by this
                // pass (we see the bump) or by the next event (we already woke
                // for it). A swap with AcqRel, not a plain Release store, gives
                // the acquire edge that pairs with the reader's swap.
                self.wake_pending
                    .swap(false, std::sync::atomic::Ordering::AcqRel);
                let seqs: Vec<u64> = self.windows.keys().copied().collect();
                for seq in seqs {
                    let Some(mut ws) = self.windows.remove(&seq) else {
                        continue;
                    };
                    self.user_event_inner(&mut ws, el, ev.clone());
                    self.finish_window_dispatch(el, seq, ws);
                }
            }
            UserEvent::NativeFullscreenExited {
                window_seq,
                generation,
            } => {
                let Some(mut ws) = self.windows.remove(&window_seq) else {
                    return;
                };
                if ws.native_fullscreen.as_ref().is_some_and(|native| {
                    let fullscreen = ws
                        .window
                        .as_ref()
                        .is_some_and(|window| window.fullscreen().is_some());
                    native.finish(generation, fullscreen)
                        || (ws.dpi_resize_surface_suspended && !native.pending())
                }) && let Some(window) = &ws.window
                {
                    let size = window.inner_size();
                    self.window_event_inner(&mut ws, el, WindowEvent::Resized(size));
                }
                self.finish_window_dispatch(el, window_seq, ws);
            }
            UserEvent::AccessibilityAction {
                window_seq,
                request,
            } => {
                let Some(mut ws) = self.windows.remove(&window_seq) else {
                    return;
                };
                self.user_event_inner(
                    &mut ws,
                    el,
                    UserEvent::AccessibilityAction {
                        window_seq,
                        request,
                    },
                );
                self.finish_window_dispatch(el, window_seq, ws);
            }
            UserEvent::VideoPreviewReady {
                window_seq,
                pane_id,
                generation,
                candidate,
                preview,
            } => {
                // The pane's tab may have moved to another window since the
                // preview was requested.
                let Some(window_seq) =
                    video_preview_target_window(&self.windows, window_seq, pane_id, generation)
                else {
                    return;
                };
                let Some(mut ws) = self.windows.remove(&window_seq) else {
                    return;
                };
                self.user_event_inner(
                    &mut ws,
                    el,
                    UserEvent::VideoPreviewReady {
                        window_seq,
                        pane_id,
                        generation,
                        candidate,
                        preview,
                    },
                );
                self.finish_window_dispatch(el, window_seq, ws);
            }
            UserEvent::RemoteCommand => {
                // Re-arm before reading: a writer racing the drain can queue a
                // new notification, while commands already present are batched.
                self.remote_command_pending
                    .swap(false, std::sync::atomic::Ordering::AcqRel);
                let seq = self.focused_seq;
                let Some(mut ws) = self.windows.remove(&seq) else {
                    return;
                };
                self.user_event_inner(&mut ws, el, UserEvent::RemoteCommand);
                self.finish_window_dispatch(el, seq, ws);
            }
            // A Dock row acts on the focused window: NewWindow opens a
            // sibling of it and NewTab adds to it. Explicit rather than left to
            // the wildcard below so the no-window case is deliberate — kettle
            // exits once the last window closes, so an empty map means the
            // process is already on its way out and the row has nothing to do.
            #[cfg(target_os = "macos")]
            UserEvent::DockCommand(command) => {
                let seq = self.focused_seq;
                let Some(mut ws) = self.windows.remove(&seq) else {
                    log::debug!("dock menu: {command:?} arrived with no window to act on");
                    return;
                };
                self.user_event_inner(&mut ws, el, UserEvent::DockCommand(command));
                self.finish_window_dispatch(el, seq, ws);
            }
            // Ctl / remote / update-banner events act on the focused window.
            _ => {
                let seq = self.focused_seq;
                let Some(mut ws) = self.windows.remove(&seq) else {
                    return;
                };
                self.user_event_inner(&mut ws, el, ev);
                self.finish_window_dispatch(el, seq, ws);
            }
        }
        runtime_tracker.set_window_count(self.windows.len());
    }

    fn window_event(&mut self, event_loop: &ActiveEventLoop, id: WindowId, event: WindowEvent) {
        #[cfg(target_os = "linux")]
        self.poll_wayland(event_loop);
        let phase_name = if matches!(&event, WindowEvent::RedrawRequested) {
            "redraw"
        } else {
            "window_event"
        };
        let runtime_tracker = self.runtime_tracker.clone();
        let _phase = runtime_tracker.enter(phase_name);
        // An unknown WindowId (a late event for an already-closed window)
        // is dropped rather than misrouted to the focused window.
        let Some(seq) = self.seq_of_window(id) else {
            return;
        };
        let Some(mut ws) = self.windows.remove(&seq) else {
            return;
        };
        self.window_event_inner(&mut ws, event_loop, event);
        self.sync_output_wake_gate(&ws);
        // Single chokepoint for the live theme preview. After every event,
        // make `cfg.theme` reflect the theme picker's selection, or revert to
        // the baseline once the picker closes without committing.
        self.sync_theme_preview(&mut ws);
        self.finish_window_dispatch(event_loop, seq, ws);
        runtime_tracker.set_window_count(self.windows.len());
    }

    fn about_to_wait(&mut self, event_loop: &ActiveEventLoop) {
        #[cfg(target_os = "linux")]
        self.poll_wayland(event_loop);
        let runtime_tracker = self.runtime_tracker.clone();
        let _phase = runtime_tracker.enter("about_to_wait");
        // Opt-in cursor_exit_v1: a key that could have ended the layer blink
        // but asked for no frame is recorded before the loop sleeps.
        for ws in self.windows.values_mut() {
            if ws.cursor_exit_log.enabled {
                ws.cursor_exit_log.flush_unrequested();
            }
        }
        // Tear-off UX failsafe: torn-drag tracking that lost its
        // drop signal (an X11 release the WM swallowed, then no further
        // input) is abandoned after 120s of silence. The window is long
        // because a LIVE-but-stationary drag is indistinguishable from
        // stale tracking on X11 (about_to_wait keeps running there while
        // the WM moves the window, and a motionless hover generates no
        // Moved events) — 120s only fires on a hover no real gesture
        // holds, and the cost of waiting is bounded (the next press or
        // release also cleans stale tracking). Windows can't misfire
        // either way: the modal move loop doesn't run about_to_wait.
        if self
            .torn_drag
            .as_ref()
            .is_some_and(|t| t.last_signal.elapsed().as_secs() >= 120)
        {
            self.abandon_torn_drag(None);
        }
        // X11 tear-off frozen-drag rescue: reposition/dock from the live
        // pointer when the WM or the carrier's event stream stops delivering.
        // Returns a wait budget that keeps it ticking.
        let torn_tick_wait = self.torn_drag_pointer_tick(event_loop);
        let now = std::time::Instant::now();
        if self
            .config_reload_deadline
            .is_some_and(|deadline| deadline <= now)
        {
            self.config_reload_deadline = None;
            // Clear before the read so a genuine edit racing the reload queues
            // a follow-up; Access(Open) itself is filtered by event kind.
            self.config_reload_pending
                .swap(false, std::sync::atomic::Ordering::AcqRel);
            self.reload_config_windows();
        }
        // Every window ticks (reap, blink, coalesced-paint deadlines);
        // the per-window wait requests merge to the EARLIEST deadline so one
        // window's animation can't starve another's coalesced output flush.
        let seqs: Vec<u64> = self.windows.keys().copied().collect();
        let mut earliest_deadline: Option<std::time::Instant> = None;
        // The poll covers every window, so one checkout is enough.
        let mut remote_poll_due = self.remote_poll_due.is_some_and(|due| due <= now);
        for seq in seqs {
            let Some(mut ws) = self.windows.remove(&seq) else {
                continue;
            };
            if std::mem::take(&mut remote_poll_due) {
                self.poll_remote_contexts(&mut ws);
            }
            for pane in ws.mux.panes.values_mut() {
                if let Some(wait) = pane.term.poll_startup_geometry() {
                    let deadline = std::time::Instant::now() + wait;
                    earliest_deadline =
                        Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
                }
            }
            let wait = self.about_to_wait_inner(&mut ws, event_loop);
            self.finish_window_dispatch(event_loop, seq, ws);
            if let Some(deadline) = wait {
                earliest_deadline =
                    Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
            }
        }
        if let Some(deadline) = self.config_reload_deadline {
            let deadline =
                deadline.max(std::time::Instant::now() + std::time::Duration::from_millis(1));
            earliest_deadline =
                Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
        }
        if let Some(due) = self.remote_poll_due {
            let deadline = due.max(std::time::Instant::now() + std::time::Duration::from_millis(1));
            earliest_deadline =
                Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
        }
        if let Some(ms) = torn_tick_wait {
            let deadline = std::time::Instant::now() + std::time::Duration::from_millis(ms);
            earliest_deadline =
                Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
        }
        #[cfg(target_os = "linux")]
        if let Some(deadline) = self
            .wayland
            .as_ref()
            .and_then(crate::wayland::Bridge::deadline)
        {
            earliest_deadline =
                Some(earliest_deadline.map_or(deadline, |current| current.min(deadline)));
        }
        if self.windows.is_empty() {
            return;
        }
        match earliest_deadline {
            Some(deadline) => event_loop.set_control_flow(ControlFlow::WaitUntil(deadline)),
            None => event_loop.set_control_flow(ControlFlow::Wait),
        }
        runtime_tracker.set_window_count(self.windows.len());
    }
    // C1-DISPATCH-END
}

/// The window waiting for this pane's video preview generation: the window
/// that requested it, or the one its tab has moved to since.
fn video_preview_target_window(
    windows: &std::collections::BTreeMap<u64, WindowState>,
    hint: u64,
    pane: u64,
    generation: u64,
) -> Option<u64> {
    if windows
        .get(&hint)
        .is_some_and(|window| window.expects_video_preview(pane, generation))
    {
        return Some(hint);
    }
    windows.iter().find_map(|(&seq, window)| {
        window
            .expects_video_preview(pane, generation)
            .then_some(seq)
    })
}

/// How a new in-process window starts life.
enum WindowOpen {
    /// A fresh window with one shell tab (`Action::NewWindow`).
    Fresh { cwd: Option<String> },
    /// Adopt a tab detached from another window — the live tab move /
    /// tear-off. PTYs keep running; nothing respawns.
    AdoptTab {
        tab: crate::mux::DetachedTab,
        source_color: Option<kettle_config::Rgb>,
        /// The moved tab's paste receipt and pending video preview.
        paste: Box<crate::window_state::MovedPasteState>,
    },
    /// Respawn one saved window of a multi-window session (tabs + geometry)
    /// on `--restore` / `restore-session = true` startup.
    Restore(crate::session::SWindow),
}

/// Is this window's backend Wayland? A runtime check, since X11 vs Wayland is
/// a runtime choice on Linux and `cfg!` can't answer it. Wayland gets the
/// tear-at-release fallback (no client-side window positioning, and
/// `xdg_toplevel.move` is compositor-validated against a press serial a
/// just-created surface never saw).
fn window_is_wayland(w: &winit::window::Window) -> bool {
    use winit::raw_window_handle::{HasWindowHandle, RawWindowHandle};
    matches!(
        w.window_handle().map(|h| h.as_raw()),
        Ok(RawWindowHandle::Wayland(_))
    )
}

/// Tear-off UX, Windows: the LIVE screen cursor. The tear
/// positions the torn window from the CursorMoved event's coordinates,
/// but window creation takes ~50-150ms — by the time `drag_window()`'s
/// posted WM_NCLBUTTONDOWN starts the modal move loop, a fast-moving
/// pointer has slid well past the event position, and DefWindowProc
/// anchors the loop at the CURRENT cursor. Without re-anchoring, the
/// pointer ends up holding the window mid-body instead of at the grab
/// point (measured: ~97px of slide under a scripted drag). Re-positioning
/// from the live cursor immediately before the handoff closes the gap to
/// sub-millisecond.
#[cfg(target_os = "windows")]
fn cursor_screen_pos() -> Option<(f64, f64)> {
    use windows::Win32::Foundation::POINT;
    use windows::Win32::UI::WindowsAndMessaging::GetCursorPos;
    let mut p = POINT::default();
    unsafe { GetCursorPos(&mut p) }
        .ok()
        .map(|()| (f64::from(p.x), f64::from(p.y)))
}

/// Tear-off UX, X11: one `QueryPointer` round-trip on a lazy
/// side connection — the LIVE screen cursor (root coords ARE screen
/// coords) plus the primary button's held state from the same reply's
/// button mask. Needed because the WM's move-grab anchor drifts from the
/// tear-time `grab` offset (measured 55-86px under Mutter — enough to miss
/// the whole dock band), pointer motion stops reaching the client entirely
/// while the WM holds the move grab, and the Esc-cancel tell needs the
/// physical button state (see `primary_button_physically_held`). A Wayland
/// session (no X server for this client) fails the one-time connect and
/// yields `None` forever — callers keep their approximations. Only ever
/// exercised while torn-drag tracking is live.
#[cfg(all(unix, not(target_os = "macos")))]
fn x11_pointer_state() -> Option<((f64, f64), bool)> {
    use x11rb::connection::Connection as _;
    use x11rb::protocol::xproto::{ConnectionExt as _, KeyButMask};
    use x11rb::rust_connection::RustConnection;
    static X11: std::sync::OnceLock<Option<(RustConnection, u32)>> = std::sync::OnceLock::new();
    let (conn, root) = X11
        .get_or_init(|| {
            x11rb::connect(None).ok().map(|(conn, screen)| {
                let root = conn.setup().roots[screen].root;
                (conn, root)
            })
        })
        .as_ref()?;
    let reply = conn.query_pointer(*root).ok()?.reply().ok()?;
    // The server applies the pointer-button mapping before reporting the
    // state mask, so BUTTON1 here is the LOGICAL primary — a left-handed
    // mapping is already accounted for.
    let held = reply.mask.contains(KeyButMask::BUTTON1);
    Some(((f64::from(reply.root_x), f64::from(reply.root_y)), held))
}

/// Tear-off UX, X11: the LIVE screen cursor, counterpart of the Windows
/// `GetCursorPos` path above. See `x11_pointer_state`.
#[cfg(all(unix, not(target_os = "macos")))]
fn cursor_screen_pos() -> Option<(f64, f64)> {
    x11_pointer_state().map(|(pos, _)| pos)
}

#[cfg(target_os = "macos")]
fn cursor_screen_pos() -> Option<(f64, f64)> {
    crate::native_drag::cursor_position()
}

#[cfg(not(any(target_os = "windows", unix)))]
fn cursor_screen_pos() -> Option<(f64, f64)> {
    None
}

// AppKit's global desktop uses points; winit's physical positions multiply
// the entire desktop origin by each window's scale. Normalize before comparing
// windows so a Retina donor can dock onto a non-Retina target.
fn drag_coordinate_scale(window: &Window) -> f64 {
    if cfg!(target_os = "macos") {
        window.scale_factor()
    } else {
        1.0
    }
}

fn drag_position(window: &Window, position: winit::dpi::PhysicalPosition<i32>) -> (f64, f64) {
    let scale = drag_coordinate_scale(window);
    (f64::from(position.x) / scale, f64::from(position.y) / scale)
}

fn drag_native_position(position: (f64, f64)) -> winit::dpi::Position {
    if cfg!(target_os = "macos") {
        winit::dpi::LogicalPosition::new(position.0, position.1).into()
    } else {
        winit::dpi::PhysicalPosition::new(position.0 as i32, position.1 as i32).into()
    }
}

/// Re-dock, Windows: per-window alpha for the dock-hover
/// preview. The torn window rides UNDER the pointer, so at the moment a
/// dock target latches, the full-size torn window is covering the very
/// strip the insertion marker draws in — the user would never see it.
/// Going translucent while a target is latched shows the target strip
/// (and marker) through the dragged window, Chromium-style. Verified
/// live against kettle's wgpu flip-model swapchain (renders fine under
/// WS_EX_LAYERED + LWA_ALPHA). 255 restores and drops the layered bit.
#[cfg(target_os = "windows")]
fn set_window_alpha(hwnd: isize, alpha: u8) {
    use windows::Win32::Foundation::{COLORREF, HWND};
    use windows::Win32::UI::WindowsAndMessaging::{
        GWL_EXSTYLE, GetWindowLongPtrW, LWA_ALPHA, SetLayeredWindowAttributes, SetWindowLongPtrW,
    };
    let h = HWND(hwnd as *mut core::ffi::c_void);
    unsafe {
        let ex = GetWindowLongPtrW(h, GWL_EXSTYLE);
        if alpha == 255 {
            let _ = SetLayeredWindowAttributes(h, COLORREF(0), 255, LWA_ALPHA);
            SetWindowLongPtrW(h, GWL_EXSTYLE, ex & !(WS_EX_LAYERED_BIT));
        } else {
            SetWindowLongPtrW(h, GWL_EXSTYLE, ex | WS_EX_LAYERED_BIT);
            let _ = SetLayeredWindowAttributes(h, COLORREF(0), alpha, LWA_ALPHA);
        }
    }
}

/// Paint a freshly created window's background in the configured terminal
/// background colour, and report whether it took.
///
/// Sets the window class brush that Win32 erases with on `WM_ERASEBKGND`, so
/// the pre-paint window would match what the renderer is about to draw. This
/// is best effort only. A light-background probe showed the pre-paint window
/// stays black whatever the brush is, so the early reveal does not depend on
/// it (see `background_is_dark_enough_to_reveal_early`).
///
/// Returns false if the brush cannot be created.
#[cfg(target_os = "windows")]
fn set_window_background_brush(hwnd: isize, rgb: kettle_config::Rgb) -> bool {
    use windows::Win32::Foundation::{COLORREF, HWND};
    use windows::Win32::Graphics::Gdi::{CreateSolidBrush, DeleteObject, HBRUSH, HGDIOBJ};
    use windows::Win32::UI::WindowsAndMessaging::{GCLP_HBRBACKGROUND, SetClassLongPtrW};

    let kettle_config::Rgb { r, g, b } = rgb;
    // COLORREF is 0x00BBGGRR, not RGB order.
    let colorref = COLORREF(u32::from(r) | (u32::from(g) << 8) | (u32::from(b) << 16));
    let h = HWND(hwnd as *mut core::ffi::c_void);
    unsafe {
        let brush = CreateSolidBrush(colorref);
        if brush.is_invalid() {
            return false;
        }
        // Replaces the class brush and hands back the previous one. The class is
        // shared and outlives the window, and every kettle window wants the same
        // colour. winit registers it with no brush, so a nonzero previous brush
        // came from an earlier kettle window and is destroyed below.
        let previous = SetClassLongPtrW(h, GCLP_HBRBACKGROUND, brush.0 as isize);
        if previous != 0 {
            let _ = DeleteObject(HGDIOBJ(previous as *mut core::ffi::c_void));
        }
        let _ = HBRUSH(brush.0);
        true
    }
}

/// Non-Windows platforms have no equivalent cheap guarantee that the first
/// composited frame is the right colour, so they keep hiding until painted.
#[cfg(not(target_os = "windows"))]
fn set_window_background_brush(_hwnd: isize, _rgb: kettle_config::Rgb) -> bool {
    false
}

/// Current process working set in MiB, for startup phase accounting.
///
/// Kettle's resident footprint is large and barely moves with scrollback, font
/// or features, so it is a FIXED cost. Sampling across the phases that allocate
/// is the only way to attribute it (docs/PERFORMANCE.md has the numbers).
///
/// `0.0` where unavailable; this is diagnostics, never control flow.
#[cfg(target_os = "windows")]
fn process_working_set_mb() -> f64 {
    use windows::Win32::System::ProcessStatus::{GetProcessMemoryInfo, PROCESS_MEMORY_COUNTERS};
    use windows::Win32::System::Threading::GetCurrentProcess;
    let Ok(size) = u32::try_from(std::mem::size_of::<PROCESS_MEMORY_COUNTERS>()) else {
        // A zero size would be accepted by the signature and rejected -- or
        // worse, partially honoured -- by the API. Refuse instead of asking for
        // a struct of no bytes.
        return 0.0;
    };
    let mut counters = PROCESS_MEMORY_COUNTERS {
        // `cb` is an in-parameter: the API uses it to decide how much of the
        // struct it may write. `Default` leaves it 0, which is not a smaller
        // request, it is a malformed one.
        cb: size,
        ..Default::default()
    };
    unsafe {
        if GetProcessMemoryInfo(GetCurrentProcess(), &mut counters, size).is_ok() {
            return counters.WorkingSetSize as f64 / (1024.0 * 1024.0);
        }
    }
    0.0
}

#[cfg(not(target_os = "windows"))]
fn process_working_set_mb() -> f64 {
    0.0
}

/// May the window be shown BEFORE the first painted frame?
///
/// Only when the terminal's background is dark enough that the difference from
/// black is imperceptible, because black is what an unpainted window actually
/// shows. The class brush set alongside this does NOT decide what appears. With
/// a light background configured (`#f0e8d8`) the pre-paint window still sampled
/// `0,0,0`, because winit owns `WM_ERASEBKGND`. Revealing a light-themed window
/// early would trade a late window for a black flash.
///
/// Dark backgrounds have no such trade. `#101010` is 16 levels from black on
/// each channel, which nobody can see, and revealing early shows the window
/// during the ~730ms of renderer init instead of after it.
///
/// The threshold is deliberately strict. This is not "dark theme" detection; it
/// is "indistinguishable from black", so anything with visible colour keeps
/// hiding until painted.
fn background_is_dark_enough_to_reveal_early(bg: kettle_config::Rgb) -> bool {
    // Windows only. "An unpainted window is black" was observed on DWM and is
    // NOT a portable fact; on another compositor the pre-paint frame could as
    // easily be white or transparent.
    if !cfg!(target_os = "windows") {
        return false;
    }
    const MAX_CHANNEL: u8 = 24;
    bg.r <= MAX_CHANNEL && bg.g <= MAX_CHANNEL && bg.b <= MAX_CHANNEL
}

/// `WS_EX_LAYERED` as the isize `GetWindowLongPtrW` works in.
#[cfg(target_os = "windows")]
const WS_EX_LAYERED_BIT: isize = 0x0008_0000;

/// Torn-window alpha while a dock target is latched. Translucent enough to
/// read the target strip + insertion marker through the dragged window,
/// opaque enough that the window still reads as "the thing you're holding"
/// (probed live at several values).
#[cfg(target_os = "windows")]
const DOCK_HOVER_ALPHA: u8 = 150;

/// Is the primary mouse button PHYSICALLY held right now? Distinguishes an
/// Esc-CANCELLED move loop (button still down when the WM ends its grab)
/// from a real drop (button up); the client-visible events look identical
/// for both. Windows honors a swapped-button mouse (`SM_SWAPBUTTON`:
/// GetAsyncKeyState reports PHYSICAL buttons, so the primary button of a
/// left-handed mouse is VK_RBUTTON); X11 reads the button mask from the
/// same `QueryPointer` the live-cursor path uses (the server pre-applies
/// the pointer mapping there). macOS uses the combined session button state.
/// False elsewhere (Wayland never produces a release-while-held; an X11 query failure also
/// degrades to false, which errs toward committing a real drop rather
/// than dropping user data on a cancel we cannot prove).
fn primary_button_physically_held() -> bool {
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        x11_pointer_state().is_some_and(|(_, held)| held)
    }
    #[cfg(target_os = "windows")]
    {
        use windows::Win32::UI::Input::KeyboardAndMouse::{
            GetAsyncKeyState, VK_LBUTTON, VK_RBUTTON,
        };
        use windows::Win32::UI::WindowsAndMessaging::{GetSystemMetrics, SM_SWAPBUTTON};
        let vk = if unsafe { GetSystemMetrics(SM_SWAPBUTTON) } != 0 {
            VK_RBUTTON
        } else {
            VK_LBUTTON
        };
        (unsafe { GetAsyncKeyState(i32::from(vk.0)) } as u16) & 0x8000 != 0
    }
    #[cfg(target_os = "macos")]
    {
        crate::native_drag::primary_held()
    }
    #[cfg(not(any(target_os = "windows", unix)))]
    false
}

/// HWND of a winit window.
/// `None` off-Windows (the `Win32` raw-handle variant exists on every
/// platform, so this compiles everywhere without cfg noise).
fn window_hwnd(w: &winit::window::Window) -> Option<isize> {
    use winit::raw_window_handle::{HasWindowHandle, RawWindowHandle};
    match w.window_handle().ok().map(|h| h.as_raw()) {
        Some(RawWindowHandle::Win32(h)) => Some(h.hwnd.get()),
        _ => None,
    }
}

/// Resolve overlapping dock candidates, and foreign windows covering a band,
/// against the REAL z-order. Walks down from the torn window (topmost while
/// dragged); the first visible, uncloaked window containing the cursor
/// decides: one of ours → that's the target; a foreign window → it covers the
/// band, no dock. The cloak check matters: suspended UWP apps park full-screen
/// DWM-cloaked windows in the z-order that would otherwise always read as
/// "covered".
///
/// Known limitation (accepted): always-on-top foreign windows
/// sit ABOVE the torn window and are invisible to a downward walk — a
/// band covered by one still shows the marker (the merge itself is
/// unaffected). GetWindowRect also includes the invisible Win10/11 resize
/// borders, which mirrors real input routing (those borders DO capture
/// clicks), so near-edge "covered" verdicts match what a click would do.
#[cfg(target_os = "windows")]
fn zorder_pick(
    torn_hwnd: isize,
    cursor: (f64, f64),
    candidates: &[(isize, u64, usize)],
) -> Option<(u64, usize)> {
    use windows::Win32::Foundation::{HWND, RECT};
    use windows::Win32::Graphics::Dwm::{DWMWA_CLOAKED, DwmGetWindowAttribute};
    use windows::Win32::UI::WindowsAndMessaging::{
        GW_HWNDNEXT, GetWindow, GetWindowRect, IsWindowVisible,
    };
    let (px, py) = (cursor.0 as i32, cursor.1 as i32);
    let mut hwnd = unsafe { GetWindow(HWND(torn_hwnd as *mut core::ffi::c_void), GW_HWNDNEXT) };
    // Bounded walk: the desktop can hold hundreds of top-level windows but
    // a runaway loop must be impossible.
    for _ in 0..1024 {
        let Ok(h) = hwnd else { break };
        if unsafe { IsWindowVisible(h) }.as_bool() {
            let mut cloaked: u32 = 0;
            let _ = unsafe {
                DwmGetWindowAttribute(
                    h,
                    DWMWA_CLOAKED,
                    (&raw mut cloaked).cast(),
                    std::mem::size_of::<u32>() as u32,
                )
            };
            let mut r = RECT::default();
            if cloaked == 0
                && unsafe { GetWindowRect(h, &mut r) }.is_ok()
                && px >= r.left
                && px < r.right
                && py >= r.top
                && py < r.bottom
            {
                let found = h.0 as isize;
                return candidates
                    .iter()
                    .find(|(ch, _, _)| *ch == found)
                    .map(|&(_, s, i)| (s, i));
            }
        }
        hwnd = unsafe { GetWindow(h, GW_HWNDNEXT) };
    }
    None
}

/// The live monitor rects, for clamping a saved window geometry whose
/// monitor is gone (see `session::clamp_geometry_to_monitors`).
fn monitor_rects(event_loop: &ActiveEventLoop) -> Vec<(i32, i32, u32, u32)> {
    event_loop
        .available_monitors()
        .map(|m| {
            let p = m.position();
            let s = m.size();
            (p.x, p.y, s.width, s.height)
        })
        .collect()
}

impl App {
    /// Window attributes shared by window 1 (`resumed_inner`) and
    /// windows 2..N (`open_window`), so a second window honors borderless /
    /// always-on-top / hide-from-taskbar / geometry-hinting / WM_CLASS
    /// exactly like the first. Always returns `visible(false)`; callers
    /// decide when to reveal.
    /// `monitor` fits the default size (see `default_startup_inner_size`);
    /// a restored geometry or explicit size supplied later still overrides it.
    fn window_attributes(
        &self,
        state: kettle_config::WindowState,
        monitor: Option<StartupMonitor>,
    ) -> winit::window::WindowAttributes {
        let mut attrs = Window::default_attributes()
            .with_title("kettle")
            // Alpha-capable surfaces can cost compositor work and subtly alter
            // text blending even when every rendered pixel is opaque. Ask for
            // one only when this window can actually expose the desktop or a
            // native material. A runtime toggle takes full effect in newly
            // opened windows, as documented by the setting itself.
            .with_transparent(
                kettle_render::window_requires_alpha_surface(&self.cfg) || self.cfg.window_blur,
            )
            // Show kettle's icon in the title bar / taskbar / Alt-Tab
            // for the running window (winit leaves it unset by default).
            .with_window_icon(load_window_icon(self.cfg.theme.is_dark()))
            // Seed the native titlebar (Windows DWM caption, Wayland
            // Adwaita CSD) to match the active palette from the first frame;
            // runtime changes go through `maybe_sync_native_theme`.
            .with_theme(creation_theme_hint(
                self.native_theme_hint(),
                cfg!(target_os = "macos"),
            ));
        #[cfg(any(target_os = "linux", target_os = "freebsd", target_os = "openbsd"))]
        {
            // Wayland implements this through KWin's blur protocol. Other
            // compositors ignore the hint and retain alpha-only transparency.
            attrs = attrs.with_blur(self.cfg.window_blur);
        }
        #[cfg(target_os = "windows")]
        if self.cfg.window_blur {
            use winit::platform::windows::{BackdropType, WindowAttributesExtWindows as _};
            attrs = attrs.with_system_backdrop(BackdropType::TransientWindow);
        }
        #[cfg(target_os = "macos")]
        {
            // Keep AppKit's title, traffic lights, rounded mask and drag region.
            // Native material stays below this caption; AppKit draws the
            // opaque control strip in the selected light or dark appearance.
            // Full-size content would instead put tabs and cells under the
            // traffic lights, changing geometry and pointer hit-testing.
            attrs = apply_macos_window_chrome(attrs, self.cfg.borderless);
        }
        // Terminator parity, terminatorlib/config.py:75 +
        // 78. `borderless` removes OS chrome; `always-on-top` keeps
        // the window above other windows. Best-effort per OS; failure
        // modes degrade silently (e.g. Wayland respects compositor
        // rules over our hint).
        if self.cfg.borderless && !cfg!(target_os = "macos") {
            attrs = attrs.with_decorations(false);
        }
        if self.cfg.always_on_top {
            attrs = attrs.with_window_level(winit::window::WindowLevel::AlwaysOnTop);
        }
        // Terminator parity, terminatorlib/config.py:79
        // `hide_from_taskbar`: on Windows, winit 0.30 exposes
        // `WindowAttributesExtWindows::with_skip_taskbar`. Other platforms
        // log instead (below).
        #[cfg(target_os = "windows")]
        if self.cfg.hide_from_taskbar {
            use winit::platform::windows::WindowAttributesExtWindows;
            attrs = WindowAttributesExtWindows::with_skip_taskbar(attrs, true);
        }
        // On non-Windows the key parses but there's no winit API to
        // honor it (X11 would need a `_NET_WM_STATE_SKIP_TASKBAR` atom write).
        // Log so a user porting a Terminator config knows it's recognized but
        // not yet applied here, like the X11/Wayland `sticky` log below. A
        // silent no-op would leave them unable to tell parse-failed from
        // not-implemented.
        #[cfg(not(target_os = "windows"))]
        if self.cfg.hide_from_taskbar {
            log::info!(
                "kettle: `hide_from_taskbar = true` is not yet applied on this \
                 platform (winit 0.30 exposes the API on Windows only); the \
                 window will still appear in the taskbar/dock"
            );
        }
        // Terminator parity, terminatorlib/config.py:75
        // `window_state`. Apply initial window state at creation.
        match state {
            kettle_config::WindowState::Normal => {}
            kettle_config::WindowState::Maximise => {
                attrs = attrs.with_maximized(true);
            }
            kettle_config::WindowState::Fullscreen => {
                attrs = attrs.with_fullscreen(Some(winit::window::Fullscreen::Borderless(None)));
            }
            kettle_config::WindowState::Hidden => {
                attrs = attrs.with_visible(false);
            }
        }
        // Logical pixels on purpose: the grid is the contract, and winit
        // scales a logical size per monitor, so a 2x display opens with the
        // same columns a 1x display gets for the same config.
        let (w, h) = startup_inner_size(&self.cfg, monitor);
        attrs = attrs.with_inner_size(winit::dpi::LogicalSize::new(w, h));
        if self.cfg.window_position_x.is_some() || self.cfg.window_position_y.is_some() {
            attrs = attrs.with_position(winit::dpi::PhysicalPosition::new(
                self.cfg.window_position_x.unwrap_or(0),
                self.cfg.window_position_y.unwrap_or(0),
            ));
        }
        // Terminator parity, terminatorlib/config.py:74
        // `geometry_hinting`: when true, request that the WM resize
        // the window in font-cell increments (so a drag-resize lands
        // on exact column/row boundaries vs sub-cell sliver). Uses
        // an approximate cell size — actual font metrics aren't
        // available yet at attrs-build time, so we use 8x16 px as a
        // typical Mono baseline. Honored best-effort per OS (X11
        // honors via WM_SIZE_HINTS; Wayland varies; macOS doesn't).
        if self.cfg.geometry_hinting {
            attrs = attrs.with_resize_increments(winit::dpi::LogicalSize::new(8.0_f64, 16.0_f64));
        }
        // Set WM_CLASS / Wayland app_id explicitly so GNOME / KDE
        // task switchers, dock pins, and the `StartupWMClass=kettle`
        // line in `packaging/linux/kettle.desktop` all line up. Without
        // it, winit sets no Wayland app_id and Wayland windows show up as
        // generic "Unknown" in the activities overview.
        #[cfg(any(target_os = "linux", target_os = "freebsd", target_os = "openbsd"))]
        let attrs = {
            // Both `WindowAttributesExtWayland::with_name` and
            // `WindowAttributesExtX11::with_name` write to the same
            // `platform_specific.name` field — calling either suffices.
            // We pick X11 here and fully-qualify the call so the import
            // doesn't put both methods in scope (which would make
            // `attrs.with_name(…)` ambiguous).
            use winit::platform::x11::WindowAttributesExtX11;
            // Derive WM_CLASS from the running binary's stem
            // (default "kettle") instead of hardcoding, so a fork or renamed
            // binary groups correctly in GNOME/KDE task switchers without
            // editing code. The canonical build is `kettle`, so this matches
            // `StartupWMClass=kettle` in packaging/linux/kettle.desktop exactly.
            let wm_class = std::env::current_exe()
                .ok()
                .and_then(|p| p.file_stem().map(|s| s.to_string_lossy().into_owned()))
                .filter(|s| !s.is_empty())
                .unwrap_or_else(|| "kettle".to_string());
            WindowAttributesExtX11::with_name(attrs, wm_class.clone(), wm_class)
        };
        attrs.with_visible(false)
    }

    fn initial_accessibility_tree(tr: &kettle_i18n::Translator) -> TreeUpdate {
        let mut root = Node::new(Role::Window);
        root.set_label(tr.text(kettle_i18n::Text::A11yWindow));
        let mut tree = TreeInfo::new(ACCESSIBILITY_ROOT_ID);
        tree.toolkit_name = Some("Kettle".to_string());
        tree.toolkit_version = Some(env!("CARGO_PKG_VERSION").to_string());
        TreeUpdate {
            nodes: vec![(ACCESSIBILITY_ROOT_ID, root)],
            tree: Some(tree),
            tree_id: TreeId::ROOT,
            focus: ACCESSIBILITY_ROOT_ID,
        }
    }

    fn new_accessibility_adapter(
        event_loop: &ActiveEventLoop,
        window: &Window,
        window_seq: u64,
        proxy: EventLoopProxy<UserEvent>,
        tr: &kettle_i18n::Translator,
    ) -> accesskit_winit::Adapter {
        accesskit_winit::Adapter::with_direct_handlers(
            event_loop,
            window,
            AccessibilityActivation {
                initial: Self::initial_accessibility_tree(tr),
            },
            AccessibilityActions { proxy, window_seq },
            AccessibilityDeactivation,
        )
    }

    fn accessibility_tree(&self, ws: &WindowState, overlay: &Overlay) -> TreeUpdate {
        let area = self.area(ws);
        let layout = self.pane_layout(ws, area);
        let focused = ws.mux.active_focus();
        let cards = self.accessible_cards(ws);
        let mut children = Vec::with_capacity(layout.len());
        let mut nodes = Vec::with_capacity(layout.len() * 2 + cards.len() + 1);
        // A pane's terminal node covers its terminal, clear of its titlebar
        // and lane.
        for (pane_id, partition) in layout {
            if ws.preview_overlay.is_some() {
                continue;
            }
            let (x, y, width, height) = partition.terminal;
            let Some(pane) = ws.mux.panes.get(&pane_id) else {
                continue;
            };
            let node_id = accessibility_pane_id(pane_id);
            let text_id = accessibility_text_id(pane_id);
            children.push(node_id);
            let mut node = Node::new(Role::Terminal);
            let label = if pane.title.trim().is_empty() {
                self.ui_text.a11y_pane(pane_id)
            } else {
                pane.title.clone()
            };
            node.set_label(label);
            let mut pane_children = vec![text_id];
            for (instance, card, item) in cards.iter().filter(|(_, card, _)| card.pane == pane_id) {
                let id = accessibility_card_id(*instance);
                pane_children.push(id);
                nodes.push((
                    id,
                    card_accessibility_node(
                        card.rect,
                        &item.title,
                        &self.card_accessibility_detail(item),
                        &self.ui_text,
                    ),
                ));
            }
            node.set_children(pane_children);
            let text = pane
                .term
                .screen_text(0)
                .map(|screen| screen.text.trim_end().to_string())
                .unwrap_or_default();
            let mut text_node = Node::new(Role::TextRun);
            text_node.set_character_lengths(
                text.chars()
                    .map(|character| character.len_utf8() as u8)
                    .collect::<Vec<_>>(),
            );
            text_node.set_value(text);
            text_node.set_bounds(accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + width),
                f64::from(y + height),
            ));
            nodes.push((text_id, text_node));
            if pane.read_only {
                node.set_read_only();
            }
            node.set_bounds(accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + width),
                f64::from(y + height),
            ));
            nodes.push((node_id, node));
        }
        // Each preview lane, beside its pane's terminal, with a button for
        // each control it shows, bounded where the lane paints it.
        let ax_rect = |(x, y, width, height): kettle_render::Rect4| {
            accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + width),
                f64::from(y + height),
            )
        };
        // Under a dialog or menu a lane is out of reach, as its pointer is.
        let lanes_reachable = !self.non_search_modal_open(ws);
        for lane in overlay
            .media_lanes
            .iter()
            .filter(|_| lanes_reachable)
            .filter(|lane| ws.preview_overlay.is_none_or(|open| open.pane == lane.pane))
        {
            let Some(lane_id) = accessibility_lane_id(lane.pane, 0) else {
                continue;
            };
            children.push(lane_id);
            let mut node = Node::new(if lane.pin_label.is_some() {
                Role::Dialog
            } else {
                Role::Group
            });
            if lane.pin_label.is_some() {
                node.set_modal();
            }
            let announced = self.lane_announcement(ws, lane.pane);
            let (label, description) =
                media_lane_accessibility(lane, &self.ui_text, announced.as_deref());
            node.set_label(label);
            node.set_description(description);
            node.set_bounds(ax_rect(lane.rect));
            let mut controls = Vec::new();
            if let Some(geometry) = self.preview_lane_geometry(ws, lane) {
                for (part, rect, hit) in lane_controls(&geometry) {
                    let (Some(rect), Some(id)) = (rect, accessibility_lane_id(lane.pane, part))
                    else {
                        continue;
                    };
                    let text = match hit {
                        kettle_render::MediaLaneHit::Previous => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yPrevious)
                        }
                        kettle_render::MediaLaneHit::Next => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yNext)
                        }
                        kettle_render::MediaLaneHit::PreviousPage => self
                            .ui_text
                            .text(kettle_i18n::Text::MediaLaneA11yPreviousDiagram),
                        kettle_render::MediaLaneHit::NextPage => self
                            .ui_text
                            .text(kettle_i18n::Text::MediaLaneA11yNextDiagram),
                        kettle_render::MediaLaneHit::Pin => {
                            self.ui_text.text(kettle_i18n::Text::MediaViewerA11yPin)
                        }
                        kettle_render::MediaLaneHit::Toggle if lane.collapsed => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yExpand)
                        }
                        kettle_render::MediaLaneHit::Toggle => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yCollapse)
                        }
                        kettle_render::MediaLaneHit::Close => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yClose)
                        }
                        kettle_render::MediaLaneHit::OpenOutside => {
                            match self.preview_opens_outside(ws, lane.pane) {
                                Some(outside) => outside.label(&self.ui_text),
                                None => continue,
                            }
                        }
                        kettle_render::MediaLaneHit::Mode
                            if lane.mode == kettle_render::MediaLaneMode::Source =>
                        {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yRendered)
                        }
                        kettle_render::MediaLaneHit::Mode => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11ySource)
                        }
                        kettle_render::MediaLaneHit::Canvas => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yCanvas)
                        }
                        kettle_render::MediaLaneHit::Copy => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yCopy)
                        }
                        kettle_render::MediaLaneHit::Reload => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yReload)
                        }
                        kettle_render::MediaLaneHit::Play
                            if lane.play == Some(kettle_render::MediaLanePlay::Stop) =>
                        {
                            self.ui_text
                                .text(kettle_i18n::Text::MediaLaneA11yStopPreview)
                        }
                        kettle_render::MediaLaneHit::Play
                            if lane.play == Some(kettle_render::MediaLanePlay::Pause) =>
                        {
                            self.ui_text
                                .text(kettle_i18n::Text::MediaLaneA11yPauseVideo)
                        }
                        kettle_render::MediaLaneHit::Play => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yPlayVideo)
                        }
                        kettle_render::MediaLaneHit::Sound
                            if lane.sound == Some(kettle_render::MediaLaneSound::Muted) =>
                        {
                            self.ui_text
                                .text(kettle_i18n::Text::MediaLaneA11yUnmuteVideo)
                        }
                        kettle_render::MediaLaneHit::Sound => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yMuteVideo)
                        }
                        kettle_render::MediaLaneHit::ZoomOut => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yZoomOut)
                        }
                        kettle_render::MediaLaneHit::ZoomIn => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yZoomIn)
                        }
                        kettle_render::MediaLaneHit::Fit => {
                            self.ui_text.text(kettle_i18n::Text::MediaLaneA11yFit)
                        }
                        kettle_render::MediaLaneHit::Resize
                        | kettle_render::MediaLaneHit::Scrub
                        | kettle_render::MediaLaneHit::Inside => continue,
                    };
                    let mut button = Node::new(Role::Button);
                    button.set_label(text);
                    button.add_action(AccessibilityAction::Click);
                    if lane.pin_label.is_some() {
                        button.add_action(AccessibilityAction::Focus);
                    }
                    button.set_bounds(ax_rect(rect));
                    if !lane_control_enabled(lane, hit) {
                        button.set_disabled();
                    }
                    controls.push(id);
                    nodes.push((id, button));
                }
                // A playing video's bar: a slider in seconds, its value said
                // as a time of the video's length.
                if let (Some(rect), Some(bar), Some(id)) = (
                    geometry.scrubber,
                    lane.scrubber.as_ref(),
                    accessibility_lane_id(lane.pane, LANE_SCRUBBER_PART),
                ) {
                    let mut slider = Node::new(Role::Slider);
                    if lane.pin_label.is_some() {
                        slider.add_action(AccessibilityAction::Focus);
                    }
                    slider.set_label(
                        self.ui_text
                            .text(kettle_i18n::Text::MediaLaneA11yVideoPosition),
                    );
                    slider.set_value(self.ui_text.media_lane_a11y_video_time(
                        &kettle_render::duration_label(bar.position_ms),
                        &kettle_render::duration_label(bar.duration_ms),
                    ));
                    slider.set_numeric_value(bar.position_ms as f64 / 1000.0);
                    slider.set_min_numeric_value(0.0);
                    slider.set_max_numeric_value(bar.duration_ms as f64 / 1000.0);
                    slider.set_numeric_value_step(LANE_SEEK_STEP.as_secs_f64());
                    slider.add_action(AccessibilityAction::SetValue);
                    slider.add_action(AccessibilityAction::Increment);
                    slider.add_action(AccessibilityAction::Decrement);
                    slider.set_bounds(ax_rect(rect));
                    controls.push(id);
                    nodes.push((id, slider));
                }
            }
            node.set_children(controls);
            nodes.push((lane_id, node));
        }
        if ws.search.open
            && let Some(geometry) = self.search_geometry(ws)
        {
            let bounds = |(x, y, width, height): kettle_render::Rect4| {
                accesskit::Rect::new(
                    f64::from(x),
                    f64::from(y),
                    f64::from(x + width),
                    f64::from(y + height),
                )
            };
            children.push(ACCESSIBILITY_SEARCH_CONTAINER_ID);
            let mut search_children = Vec::with_capacity(8);
            for control in kettle_render::SearchControl::ALL {
                let id = accessibility_search_control_id(control);
                search_children.push(id);
                let mut node = Node::new(match control {
                    kettle_render::SearchControl::Editor => Role::SearchInput,
                    kettle_render::SearchControl::Wrap | kettle_render::SearchControl::Invert => {
                        Role::CheckBox
                    }
                    _ => Role::Button,
                });
                node.set_label(control.accessible_label(&self.ui_text));
                node.set_bounds(bounds(geometry.control_rect(control)));
                node.add_action(AccessibilityAction::Focus);
                node.add_action(AccessibilityAction::Click);
                match control {
                    kettle_render::SearchControl::Editor => {
                        let query = ws.search.query();
                        node.set_value(query);
                        node.set_children([ACCESSIBILITY_SEARCH_TEXT_ID]);
                        node.add_action(AccessibilityAction::SetValue);
                        node.add_action(AccessibilityAction::ReplaceSelectedText);
                        node.add_action(AccessibilityAction::SetTextSelection);

                        let mut text_node = Node::new(Role::TextRun);
                        text_node.set_value(query);
                        text_node.set_character_lengths(
                            query
                                .chars()
                                .map(|character| character.len_utf8() as u8)
                                .collect::<Vec<_>>(),
                        );
                        let byte_character_index =
                            |byte: usize| query[..byte.min(query.len())].chars().count();
                        let (anchor, focus) = ws.search.editor.directed_selection().map_or_else(
                            || {
                                let cursor = byte_character_index(ws.search.editor.cursor());
                                (cursor, cursor)
                            },
                            |(anchor, focus)| {
                                (byte_character_index(anchor), byte_character_index(focus))
                            },
                        );
                        node.set_text_selection(TextSelection {
                            anchor: TextPosition {
                                node: ACCESSIBILITY_SEARCH_TEXT_ID,
                                character_index: anchor,
                            },
                            focus: TextPosition {
                                node: ACCESSIBILITY_SEARCH_TEXT_ID,
                                character_index: focus,
                            },
                        });
                        nodes.push((ACCESSIBILITY_SEARCH_TEXT_ID, text_node));
                    }
                    kettle_render::SearchControl::Wrap => node.set_toggled(ws.search.wrap.into()),
                    kettle_render::SearchControl::Case => {
                        node.set_value(
                            map_search_case_mode(ws.search.case_mode).label(&self.ui_text),
                        );
                    }
                    kettle_render::SearchControl::Invert => {
                        node.set_toggled(ws.search.invert.into());
                    }
                    _ => {}
                }
                nodes.push((id, node));
            }
            search_children.push(ACCESSIBILITY_SEARCH_STATUS_ID);
            let mut status = Node::new(Role::Status);
            status.set_label(effective_search_status(&ws.search).label(&self.ui_text));
            status.set_live(accesskit::Live::Polite);
            status.set_bounds(bounds(geometry.status));
            nodes.push((ACCESSIBILITY_SEARCH_STATUS_ID, status));

            let mut search = Node::new(Role::Search);
            search.set_label(self.ui_text.text(kettle_i18n::Text::SearchA11yRegion));
            search.set_children(search_children);
            search.set_bounds(bounds(geometry.rect));
            nodes.push((ACCESSIBILITY_SEARCH_CONTAINER_ID, search));
        }
        if let Some(completion) = overlay.completion.as_ref()
            && let Some((x, y, width, height)) =
                kettle_render::completion_overlay_rect(completion, self.menu_cell(ws))
        {
            let cell = self.menu_cell(ws);
            let visible_rows = kettle_render::completion_overlay_row_rects(completion, cell);
            let mut row_ids = Vec::with_capacity(visible_rows.len());
            for (index, (x, y, width, height)) in visible_rows {
                let Some(candidate) = completion.candidates.get(index) else {
                    continue;
                };
                let id = accessibility_completion_row_id(candidate.position);
                row_ids.push(id);
                let mut row = Node::new(Role::ListBoxOption);
                row.set_label(if candidate.description.is_empty() {
                    candidate.label.clone()
                } else {
                    format!("{}, {}", candidate.label, candidate.description)
                });
                row.set_position_in_set(candidate.position + 1);
                if completion.selected == Some(index) {
                    row.set_selected(true);
                }
                row.set_bounds(accesskit::Rect::new(
                    f64::from(x),
                    f64::from(y),
                    f64::from(x + width),
                    f64::from(y + height),
                ));
                nodes.push((id, row));
            }
            let mut list = Node::new(Role::ListBox);
            list.set_label(
                self.ui_text
                    .completion_a11y_list(&completion.kind, &completion.source),
            );
            list.set_children(row_ids);
            list.set_size_of_set(completion.total);
            list.set_live(accesskit::Live::Polite);
            list.set_bounds(accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + width),
                f64::from(y + height),
            ));
            children.push(ACCESSIBILITY_COMPLETION_CONTAINER_ID);
            nodes.push((ACCESSIBILITY_COMPLETION_CONTAINER_ID, list));
        }
        if let Some(receipt) = overlay.media_paste_receipt.as_ref()
            && let Some(geometry) = kettle_render::media_paste_receipt_geometry(
                receipt,
                overlay.completion.as_ref(),
                self.menu_cell(ws),
                self.overlay_text_cell_width(ws),
                self.overlay_text_line_height(ws),
            )
        {
            let label =
                media_receipt_accessibility_label(&receipt.kind, receipt.remote, &receipt.tr);
            let mut node = Node::new(Role::Button);
            node.set_label(label);
            node.set_description(self.ui_text.text(if receipt.openable {
                kettle_i18n::Text::ReceiptA11yOpenImage
            } else {
                kettle_i18n::Text::ReceiptA11yHideVideo
            }));
            node.set_live(accesskit::Live::Polite);
            node.add_action(AccessibilityAction::Click);
            let (x, y, _width, height) = geometry.rect;
            let open_width = (geometry.dismiss_rect.0 - x).max(0.0);
            node.set_bounds(accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + open_width),
                f64::from(y + height),
            ));
            children.push(ACCESSIBILITY_MEDIA_RECEIPT_ID);
            nodes.push((ACCESSIBILITY_MEDIA_RECEIPT_ID, node));

            let mut dismiss = Node::new(Role::Button);
            dismiss.set_label(self.ui_text.text(kettle_i18n::Text::ReceiptA11yDismiss));
            dismiss.add_action(AccessibilityAction::Click);
            let (x, y, width, height) = geometry.dismiss_rect;
            dismiss.set_bounds(accesskit::Rect::new(
                f64::from(x),
                f64::from(y),
                f64::from(x + width),
                f64::from(y + height),
            ));
            children.push(ACCESSIBILITY_MEDIA_RECEIPT_DISMISS_ID);
            nodes.push((ACCESSIBILITY_MEDIA_RECEIPT_DISMISS_ID, dismiss));
        }
        let surface = ws
            .window
            .as_ref()
            .map(|window| {
                let size = window.inner_size();
                (size.width as f32, size.height as f32)
            })
            .or_else(|| {
                ws.renderer.as_ref().map(|renderer| {
                    let (width, height) = renderer.surface_size();
                    (width as f32, height as f32)
                })
            })
            .unwrap_or((800.0, 600.0));
        let modal = modal_accessibility_projection(overlay, surface, &self.ui_text);
        let modal_focus = modal.focus;
        children.extend(modal.roots);
        nodes.extend(modal.nodes);
        let mut root = Node::new(Role::Window);
        root.set_label(self.ui_text.text(kettle_i18n::Text::A11yWindow));
        root.set_children(children);
        if let Some(window) = &ws.window {
            let size = window.inner_size();
            root.set_bounds(accesskit::Rect::new(
                0.0,
                0.0,
                f64::from(size.width),
                f64::from(size.height),
            ));
        }
        nodes.push((ACCESSIBILITY_ROOT_ID, root));
        let focus = modal_focus.unwrap_or_else(|| {
            if ws.search.open {
                accessibility_search_control_id(ws.search.focused_control)
            } else if let Some(open) = ws.preview_overlay {
                open.control
                    .and_then(|control| accessibility_lane_id(open.pane, control))
                    .filter(|id| {
                        nodes
                            .iter()
                            .any(|(at, node)| at == id && !node.is_disabled())
                    })
                    .or_else(|| accessibility_lane_id(open.pane, 0))
                    .unwrap_or(ACCESSIBILITY_ROOT_ID)
            } else {
                ws.card_focus
                    .map(accessibility_card_id)
                    .into_iter()
                    .chain(focused.map(accessibility_pane_id))
                    .find(|id| nodes.iter().any(|(candidate, _)| candidate == id))
                    .unwrap_or(ACCESSIBILITY_ROOT_ID)
            }
        });
        TreeUpdate {
            nodes,
            tree: None,
            tree_id: TreeId::ROOT,
            focus,
        }
    }

    fn accessibility_key(&self, ws: &WindowState, overlay: &Overlay) -> u64 {
        use std::hash::{Hash as _, Hasher as _};

        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        ws.mux.active_focus().hash(&mut hasher);
        ws.preview_overlay
            .map(|open| (open.pane, open.control))
            .hash(&mut hasher);
        ws.card_focus.hash(&mut hasher);
        for (instance, card, item) in self.accessible_cards(ws) {
            instance.hash(&mut hasher);
            card.rect.map(f32::to_bits).hash(&mut hasher);
            (item.id, item.generation).hash(&mut hasher);
        }
        if let Some(window) = &ws.window {
            let size = window.inner_size();
            size.width.hash(&mut hasher);
            size.height.hash(&mut hasher);
        }
        ws.search.open.hash(&mut hasher);
        if ws.search.open {
            ws.search.query().hash(&mut hasher);
            ws.search.editor.cursor().hash(&mut hasher);
            ws.search.editor.selection().hash(&mut hasher);
            ws.search.wrap.hash(&mut hasher);
            map_search_case_mode(ws.search.case_mode)
                .label(&self.ui_text)
                .hash(&mut hasher);
            ws.search.invert.hash(&mut hasher);
            effective_search_status(&ws.search)
                .label(&self.ui_text)
                .hash(&mut hasher);
            ws.search.focused_control.hash(&mut hasher);
        }
        overlay.confirm_dialog.is_some().hash(&mut hasher);
        if let Some(dialog) = overlay.confirm_dialog.as_ref() {
            dialog.prompt.hash(&mut hasher);
            dialog.focus_idx.hash(&mut hasher);
            for button in &dialog.buttons {
                button.label.hash(&mut hasher);
                button.destructive.hash(&mut hasher);
            }
        }
        overlay.settings.is_some().hash(&mut hasher);
        if let Some(settings) = overlay.settings.as_ref() {
            settings.categories.hash(&mut hasher);
            settings.label_cols.hash(&mut hasher);
            settings.value_cols.hash(&mut hasher);
            settings.footer_note.hash(&mut hasher);
            settings.active_category.hash(&mut hasher);
            settings.focused_row.hash(&mut hasher);
            for row in &settings.rows {
                row.label.hash(&mut hasher);
                row.value.hash(&mut hasher);
                row.disabled.hash(&mut hasher);
            }
        }
        overlay.context_menu.is_some().hash(&mut hasher);
        if let Some(menu) = overlay.context_menu.as_ref() {
            menu.highlight.hash(&mut hasher);
            menu.scroll_offset.hash(&mut hasher);
            for component in [
                menu.anchor.0,
                menu.anchor.1,
                menu.panel_w_clamped,
                menu.panel_h_clamped,
            ] {
                component.to_bits().hash(&mut hasher);
            }
            for row in &menu.rows {
                row.label.hash(&mut hasher);
                row.hint.hash(&mut hasher);
                row.separator.hash(&mut hasher);
                row.enabled.hash(&mut hasher);
            }
        }
        overlay.palette_query.hash(&mut hasher);
        overlay.layout_picker_query.hash(&mut hasher);
        overlay.theme_picker_query.hash(&mut hasher);
        overlay.ssh_query.hash(&mut hasher);
        if let Some(edit) = overlay.edit_title.as_ref() {
            edit.label.hash(&mut hasher);
            edit.input.hash(&mut hasher);
            for component in [edit.rect.0, edit.rect.1, edit.rect.2, edit.rect.3] {
                component.to_bits().hash(&mut hasher);
            }
        }
        for hint in &overlay.hint_labels {
            hint.row.hash(&mut hasher);
            hint.col.hash(&mut hasher);
            hint.label.hash(&mut hasher);
            hint.dim.hash(&mut hasher);
        }
        overlay.update_available.hash(&mut hasher);
        let projected_completion = overlay.completion.as_ref();
        projected_completion.is_some().hash(&mut hasher);
        if let Some(completion) = projected_completion {
            completion.source.hash(&mut hasher);
            completion.selected.hash(&mut hasher);
            completion.total.hash(&mut hasher);
            completion.kind.hash(&mut hasher);
            completion.token.hash(&mut hasher);
            completion.command_rows.hash(&mut hasher);
            accessibility_completion_geometry_key(completion, self.menu_cell(ws)).hash(&mut hasher);
            for candidate in &completion.candidates {
                candidate.position.hash(&mut hasher);
                candidate.label.hash(&mut hasher);
                candidate.description.hash(&mut hasher);
            }
        }
        let projected_receipt = overlay.media_paste_receipt.as_ref();
        projected_receipt.is_some().hash(&mut hasher);
        if let Some(receipt) = projected_receipt {
            match &receipt.kind {
                kettle_render::MediaPasteReceiptKind::Image {
                    original_width,
                    original_height,
                } => {
                    0_u8.hash(&mut hasher);
                    original_width.hash(&mut hasher);
                    original_height.hash(&mut hasher);
                }
                kettle_render::MediaPasteReceiptKind::Video {
                    extension,
                    size,
                    count,
                    preview_pending,
                } => {
                    1_u8.hash(&mut hasher);
                    extension.hash(&mut hasher);
                    size.hash(&mut hasher);
                    count.hash(&mut hasher);
                    preview_pending.hash(&mut hasher);
                }
            }
            receipt.remote.hash(&mut hasher);
            receipt.expanded.hash(&mut hasher);
            if let Some(geometry) = kettle_render::media_paste_receipt_geometry(
                receipt,
                overlay.completion.as_ref(),
                self.menu_cell(ws),
                self.overlay_text_cell_width(ws),
                self.overlay_text_line_height(ws),
            ) {
                for component in [
                    geometry.rect.0,
                    geometry.rect.1,
                    geometry.rect.2,
                    geometry.rect.3,
                    geometry.dismiss_rect.0,
                    geometry.dismiss_rect.1,
                    geometry.dismiss_rect.2,
                    geometry.dismiss_rect.3,
                ] {
                    component.to_bits().hash(&mut hasher);
                }
            }
        }
        overlay.media_lanes.len().hash(&mut hasher);
        for lane in &overlay.media_lanes {
            lane.pane.hash(&mut hasher);
            lane.collapsed.hash(&mut hasher);
            lane.open_outside.hash(&mut hasher);
            // The play and sound buttons' names follow what they do.
            lane.play.hash(&mut hasher);
            lane.sound.hash(&mut hasher);
            let announced = self.lane_announcement(ws, lane.pane);
            media_lane_accessibility(lane, &self.ui_text, announced.as_deref()).hash(&mut hasher);
            let (x, y, width, height) = lane.rect;
            for component in [x, y, width, height] {
                component.to_bits().hash(&mut hasher);
            }
        }
        let mut layout = self.pane_layout(ws, self.area(ws));
        layout.sort_by_key(|(pane_id, _)| *pane_id);
        for (pane_id, partition) in layout {
            pane_id.hash(&mut hasher);
            let lane = partition
                .lane
                .and_then(crate::pane_partition::LaneShare::rect);
            for rect in [Some(partition.leaf), Some(partition.terminal), lane] {
                rect.is_some().hash(&mut hasher);
                for component in rect.into_iter().flat_map(|r| [r.0, r.1, r.2, r.3]) {
                    component.to_bits().hash(&mut hasher);
                }
            }
            if let Some(pane) = ws.mux.panes.get(&pane_id) {
                pane.title.hash(&mut hasher);
                pane.read_only.hash(&mut hasher);
                pane.term.output_generation().hash(&mut hasher);
                pane.term
                    .term
                    .lock()
                    .ok()
                    .map(|term| term.grid().display_offset())
                    .hash(&mut hasher);
            }
        }
        hasher.finish()
    }

    fn publish_accessibility_if_due(&self, ws: &mut WindowState, overlay: &Overlay) {
        let key = self.accessibility_key(ws, overlay);
        if ws.accessibility_key == Some(key) {
            ws.accessibility_pending = false;
            return;
        }
        let due = ws
            .accessibility_updated_at
            .is_none_or(|updated| updated.elapsed() >= ACCESSIBILITY_UPDATE_INTERVAL);
        if !due {
            ws.accessibility_pending = true;
            return;
        }
        let Some(mut adapter) = ws.accessibility.take() else {
            ws.accessibility_pending = false;
            return;
        };
        let mut published = false;
        adapter.update_if_active(|| {
            published = true;
            self.accessibility_tree(ws, overlay)
        });
        ws.accessibility = Some(adapter);
        ws.accessibility_pending = false;
        if published {
            ws.accessibility_key = Some(key);
            ws.accessibility_updated_at = Some(std::time::Instant::now());
        }
    }

    /// Post-creation window setup shared by both window-creation paths.
    #[cfg_attr(not(target_os = "macos"), allow(unused_variables))]
    fn apply_post_create(&self, window: &Window) {
        window.set_ime_allowed(true);
        #[cfg(target_os = "macos")]
        {
            set_macos_option_as_alt(window, self.cfg.macos_option_as_alt);
        }
        // Terminator parity, terminatorlib/config.py:81
        // `sticky`: show window on every workspace. winit 0.30 dropped
        // `WindowExtMacOS::set_visible_on_all_workspaces`, so macOS sets
        // `NSWindowCollectionBehavior::CanJoinAllSpaces | Stationary` through
        // the raw NSWindow handle after construction (see
        // `set_visible_on_all_spaces`).
        #[cfg(target_os = "macos")]
        if self.cfg.sticky {
            set_visible_on_all_spaces(window);
        }
        // X11/Wayland sticky needs a `_NET_WM_STATE_STICKY` atom
        // write that winit 0.30 doesn't expose; log (don't silently no-op) so
        // the user knows the key is recognized but not yet applied here.
        #[cfg(any(target_os = "linux", target_os = "freebsd", target_os = "openbsd"))]
        if self.cfg.sticky {
            log::info!(
                "kettle: `sticky = true` is not yet applied on X11/Wayland \
                 (winit 0.30 exposes no API for `_NET_WM_STATE_STICKY`); the \
                 window stays on its current workspace"
            );
        }
    }

    fn start_window_frames(&mut self, ws: &mut WindowState) {
        let Some(window) = ws.window.clone() else {
            return;
        };
        // Winit draws Wayland CSD before RedrawRequested. An earlier client
        // buffer clips the unmapped decorations out of the window geometry.
        if !window_is_wayland(&window) {
            self.redraw(ws);
        }
        window.request_redraw();
    }

    /// Open another OS window in this process (the multi-window core).
    /// Returns the new window's seq on success; returns the `WindowOpen`
    /// back on failure so an `AdoptTab` caller can re-attach the tab to its
    /// source window instead of losing live PTYs. `size` overrides the
    /// platform-default inner size (a torn-off window inherits the source
    /// window's dimensions, Windows Terminal parity).
    fn open_window(
        &mut self,
        event_loop: &ActiveEventLoop,
        open: WindowOpen,
        pos: Option<winit::dpi::Position>,
        size: Option<winit::dpi::PhysicalSize<u32>>,
    ) -> Result<u64, Box<WindowOpen>> {
        let Some(gpu) = self.gpu.clone() else {
            log::warn!("open_window: GPU context not ready (window 1 still initializing)");
            return Err(Box::new(open));
        };
        let source_color = match &open {
            WindowOpen::AdoptTab { source_color, .. } => *source_color,
            _ => None,
        };
        // A tear-off window opens Normal (it must be visible at the drop
        // point); a fresh window honors the configured window-state except
        // Hidden (an invisible NewWindow helps nobody).
        let state = match (&open, self.cfg.window_state) {
            (WindowOpen::AdoptTab { .. }, _) | (WindowOpen::Restore(_), _) => {
                kettle_config::WindowState::Normal
            }
            (_, kettle_config::WindowState::Hidden) => kettle_config::WindowState::Normal,
            (_, s) => s,
        };
        let monitor = startup_monitor(event_loop);
        let mut attrs = self.window_attributes(state, monitor);
        // Load the fonts before the window, as the first window does: a fresh
        // normal window then opens at exactly the configured grid, and the
        // renderer takes the fonts over.
        let fonts =
            kettle_render::StartupFonts::load(&self.cfg, monitor.map_or(1.0, |m| m.scale) as f32);
        if matches!(open, WindowOpen::Fresh { .. })
            && matches!(state, kettle_config::WindowState::Normal)
            && pos.is_none()
            && size.is_none()
        {
            let mut probe = WindowState::new(0, Mux::new());
            probe.startup_cell = Some(fonts.cell);
            if let Some((width, height)) = self.startup_surface(&probe, monitor) {
                attrs = attrs.with_inner_size(winit::dpi::PhysicalSize::new(width, height));
            }
        }
        // A restored window lands at its saved geometry, clamped to the
        // live monitor layout (its monitor may be unplugged).
        if let WindowOpen::Restore(sw) = &open
            && let Some(g) = sw.geometry
        {
            let g = crate::session::clamp_geometry_to_monitors(g, &monitor_rects(event_loop));
            attrs = attrs
                .with_position(winit::dpi::PhysicalPosition::new(g.x, g.y))
                .with_inner_size(winit::dpi::PhysicalSize::new(g.w, g.h));
        }
        if let Some(p) = pos {
            attrs = attrs.with_position(p);
        }
        if let Some(s) = size {
            attrs = attrs.with_inner_size(s);
        }
        let window = match event_loop.create_window(attrs) {
            Ok(w) => Arc::new(w),
            Err(e) => {
                log::error!("open_window: window creation failed: {e}");
                return Err(Box::new(open));
            }
        };
        self.apply_post_create(&window);
        let native_material = crate::native_material::NativeMaterial::install(&window, &self.cfg);
        let size = window.inner_size();
        let scale = window.scale_factor() as f32;
        // Synchronous renderer init against the shared device — no block_on,
        // no watchdog (those are window-1 costs; see Renderer::new_with_gpu).
        let renderer = match Renderer::new_with_gpu(
            &gpu,
            window.clone(),
            size.width.max(1),
            size.height.max(1),
            scale,
            &self.cfg,
            Some(fonts),
        ) {
            Ok(r) => r,
            Err(e) => {
                log::error!("open_window: renderer init failed: {e}");
                return Err(Box::new(open));
            }
        };
        let seq = self.next_window_seq;
        self.next_window_seq += 1;
        let accessibility = Self::new_accessibility_adapter(
            event_loop,
            &window,
            seq,
            self.proxy.clone(),
            &self.ui_text,
        );
        // Same Mux construction flags as run_with — process-global decisions.
        let mut mux = Mux::new();
        mux.lua_output_subscribed = self.lua_engine.is_some();
        mux.osc52_copy_allowed = osc52_copy_is_available(self.cfg.osc52, self.clipboard.is_some());
        mux.autoclean_groups = self.cfg.autoclean_groups;
        {
            mux.lua_output_subscribed |= self.recorder.is_some();
            mux.record_lossless = self.recorder.is_some();
        }
        let mut ws = WindowState::new(seq, mux);
        ws.window_shown = !should_reveal_after_renderer_init(state);
        ws.renderer = Some(renderer);
        ws.accessibility = Some(accessibility);
        ws.window = Some(window);
        ws.native_caption_drag = ws
            .window
            .as_deref()
            .map(crate::native_drag::NativeCaptionDrag::install);
        ws.native_fullscreen = ws.window.as_deref().map(|window| {
            crate::native_fullscreen::NativeFullscreen::install(window, seq, self.proxy.clone())
        });
        ws.native_material = Some(native_material);
        self.sync_output_frame_budget(&mut ws, true);
        let area = self.area(&ws);
        let (cols, rows) = self.grid_of(&ws, area);
        let geometry = self.pty_geometry_for_grid(&ws, cols, rows);
        match open {
            WindowOpen::Fresh { cwd } => {
                if let Err(e) = ws.mux.new_tab_with_geometry(
                    &self.cfg,
                    geometry,
                    self.waker(),
                    &[],
                    cwd.as_deref(),
                ) {
                    // `ws` (and its OS window) drop here; nothing was adopted.
                    log::error!("open_window: shell spawn failed: {e}");
                    return Err(Box::new(WindowOpen::Fresh { cwd }));
                }
            }
            WindowOpen::AdoptTab { tab: dt, paste, .. } => {
                ws.mux.attach_tab(dt, None);
                ws.adopt_moved_paste_state(*paste);
            }
            WindowOpen::Restore(sw) => {
                let sess = crate::session::Session {
                    tabs: sw.tabs.clone(),
                    active: sw.active,
                    theme: None,
                    windows: Vec::new(),
                };
                // Route through the LATCHED waker constructor. A hand-rolled
                // closure bypasses the wakeup-dedup latch, so restored panes
                // would bring back the one-wakeup-per-read flood it eliminates.
                let mk = || self.waker();
                let geometries = self.restore_geometries(&ws, &sess);
                let outcome = ws.mux.restore_geometry(&sess, &self.cfg, &geometries, &mk);
                if !outcome.restored_any {
                    // `ws` (and its OS window) drop here; nothing restored.
                    log::error!("open_window: saved-window restore failed");
                    return Err(Box::new(WindowOpen::Restore(sw)));
                }
                if outcome.skipped > 0 {
                    self.stash_unrestorable_session(&format!(
                        "{} tab(s) could not be rebuilt",
                        outcome.skipped
                    ));
                }
            }
        }
        // Apply a due scheduled theme switch first, as the first redraw would,
        // so a torn window excludes its source's color from the pool it will
        // paint with rather than from the outgoing theme's pool.
        self.poll_theme_schedule(&mut ws);
        if self.cfg.accent_auto && self.cfg.accent_color.is_none() {
            self.assign_window_accent(&mut ws, source_color);
        }
        self.resize_all(&mut ws);
        self.sync_output_wake_gate(&ws);
        self.focused_seq = seq;
        if should_reveal_before_first_surface_frame(
            state,
            ws.window_shown,
            cfg!(target_os = "macos"),
        ) {
            if let Some(w) = &ws.window {
                w.set_visible(true);
            }
            ws.window_shown = true;
        }
        // A successful presentation reveals the restored surface. Wayland
        // waits for Winit's CSD paint; macOS is revealed above so Metal can
        // acquire a drawable from its visible NSWindow.
        #[cfg(target_os = "linux")]
        if let (Some(bridge), Some(window)) = (self.wayland.as_mut(), ws.window.clone()) {
            bridge.attach_drag_carrier(ws.seq, window);
        }
        self.start_window_frames(&mut ws);
        self.windows.insert(seq, ws);
        Ok(seq)
    }

    /// Chromium-style tear-off. The moment the dragged tab crosses the band
    /// threshold, detach it into a live window under the cursor, inheriting
    /// the source dimensions and positioned so the pointer keeps holding the
    /// tab, then hand the drag to the OS via `drag_window()` (Windows:
    /// ReleaseCapture + WM_NCLBUTTONDOWN/HTCAPTION posted to the torn window,
    /// the exact Chromium handoff; X11: _NET_WM_MOVERESIZE). macOS follows the
    /// pointer manually instead. Returns true when the source window no longer
    /// owns the gesture.
    fn maybe_tear_off(&mut self, ws: &mut WindowState, event_loop: &ActiveEventLoop) -> bool {
        if !self.cfg.detachable_tabs {
            return false;
        }
        if !matches!(
            ws.detach_drag,
            crate::detach::DragState::DraggingInside { .. }
                | crate::detach::DragState::DraggingOutside { .. }
        ) {
            return false;
        }
        let Some(src) = ws.window.clone() else {
            return false;
        };
        let (cx, cy) = (ws.cursor.x as f32, ws.cursor.y as f32);
        let Some(band) = self.dock_band(ws) else {
            return false;
        };
        // 1.5× the bar thickness of slop in EVERY direction away from the
        // band (uniform hysteresis): drag along the strip = reorder, drag
        // past the slop = tear. ~36px at the default font.
        let threshold = 1.5 * self.tab_bar_h(ws);
        if !tear_threshold_crossed(cx, cy, band, threshold) {
            return false;
        }
        if window_is_wayland(&src) {
            #[cfg(target_os = "linux")]
            return self.begin_wayland_tab_drag(ws, event_loop, src);
            #[cfg(not(target_os = "linux"))]
            return false;
        }
        // Lone tab: the tab IS the window — drag the whole window instead
        // of tearing (Chromium semantics; tearing would just re-create the
        // same window). The torn-drag tracking still attaches, so the
        // full re-dock path applies: this is how a previously torn-off
        // window merges back into a sibling.
        if ws.mux.tabs.len() <= 1 {
            let press = ws
                .drag_press
                .map(|(x, y)| (f64::from(x), f64::from(y)))
                .unwrap_or((ws.cursor.x, ws.cursor.y));
            ws.tab_drag_active = false;
            ws.tab_drag_press = None;
            ws.tab_pressed_idx = None;
            ws.detach_drag = crate::detach::DragState::default();
            ws.drag_press = None;
            let origins = (src.inner_position(), src.outer_position());
            // AppKit requires the original mouse-down event for performDrag;
            // winit passes currentEvent here, which is already mouseDragged.
            let native = if cfg!(target_os = "macos") || tear_native_handoff_disabled() {
                false
            } else {
                match src.drag_window() {
                    Ok(()) => true,
                    Err(e) => {
                        log::info!(
                            "tab-drag window move: native drag unavailable ({e}); manual follow"
                        );
                        false
                    }
                }
            };
            // Manual follow keeps the original press under the pointer, even
            // when a native handoff failed or the first motion is the drop.
            let pointer = if native {
                (ws.cursor.x, ws.cursor.y)
            } else {
                press
            };
            let pointer_scale = drag_coordinate_scale(&src);
            let pointer = (pointer.0 / pointer_scale, pointer.1 / pointer_scale);
            let grab = match origins {
                (Ok(ip), Ok(op)) => crate::detach::frame_grab_offset(
                    drag_position(&src, ip),
                    drag_position(&src, op),
                    pointer,
                ),
                _ => (40.0, 12.0),
            };
            self.torn_drag = Some(TornDrag {
                seq: ws.seq,
                carrier: ws.seq,
                started: std::time::Instant::now(),
                grab,
                dock: None,
                native,
                caption: false,
                saw_move: false,
                last_signal: std::time::Instant::now(),
                hwnd: window_hwnd(&src),
                signal_cursor: None,
            });
            self.follow_torn_drag(ws);
            return true;
        }
        // The torn window inherits the source dimensions (WT tear-off
        // parity). A maximized/fullscreen source approximates its restored
        // size at 60% — winit exposes no restore bounds (Chromium uses
        // them; this is the closest available).
        let isz = src.inner_size();
        let scale = if src.is_maximized() || src.fullscreen().is_some() {
            0.6
        } else {
            1.0
        };
        let size = winit::dpi::PhysicalSize::new(
            ((f64::from(isz.width) * scale) as u32).max(400),
            ((f64::from(isz.height) * scale) as u32).max(300),
        );
        // Grab offset: where the pointer holds the torn window, relative to
        // its FRAME top-left (winit positions windows AND reports `Moved`
        // by the frame origin — verified against the vendored 0.30.13
        // WM_WINDOWPOSCHANGED handler). Two parts: the frame→client
        // decoration delta (caption + border, measured on the source —
        // same decoration config — so the pointer lands INSIDE the client,
        // on the strip, not on the native title bar), plus the in-strip
        // hold point in the TORN window's own layout: the strip sits at
        // the torn window's `tab-bar-pos` edge, so a Bottom/Right bar
        // anchors the pointer at the bottom/right of the torn frame —
        // without this the window hangs off the wrong side of the pointer.
        // Along the strip the pointer keeps its offset INTO the dragged
        // segment (WT's stashed drag offset, microsoft/terminal PR #14935),
        // clamped inside the torn frame.
        let ftc = match (src.inner_position(), src.outer_position()) {
            (Ok(ip), Ok(op)) => (f64::from(ip.x - op.x), f64::from(ip.y - op.y)),
            _ => (0.0, 0.0),
        };
        let bar = self.tab_bar(ws);
        let bar_h = f64::from(self.tab_bar_h(ws)).max(8.0);
        let seg = bar.segments.iter().find(|s| s.active).map(|s| s.rect);
        let in_seg_x = seg
            .map(|(sx, _, seg_w, _)| f64::from((cx - sx).clamp(16.0, (seg_w - 16.0).max(16.0))))
            .unwrap_or(40.0)
            .min(f64::from(size.width) - 24.0);
        let in_seg_y = seg
            .map(|(_, sy, _, seg_h)| f64::from((cy - sy).clamp(8.0, (seg_h - 8.0).max(8.0))))
            .unwrap_or(12.0)
            .min(f64::from(size.height) - 24.0);
        let strip_w = f64::from(self.cfg.tab_bar_width).max(8.0);
        let grab = match self.cfg.tab_bar_pos {
            TabBarPos::Top => (ftc.0 + in_seg_x, ftc.1 + bar_h * 0.5),
            TabBarPos::Bottom => (
                ftc.0 + in_seg_x,
                ftc.1 + f64::from(size.height) - bar_h * 0.5,
            ),
            TabBarPos::Left => (ftc.0 + strip_w * 0.5, ftc.1 + in_seg_y),
            TabBarPos::Right => (
                ftc.0 + f64::from(size.width) - strip_w * 0.5,
                ftc.1 + in_seg_y,
            ),
        };
        let coordinate_scale = drag_coordinate_scale(&src);
        let grab = (grab.0 / coordinate_scale, grab.1 / coordinate_scale);
        // Frame origin = screen cursor − grab. `inner_position` is the
        // client origin in screen coords, so client cursor + it = screen
        // cursor exactly; `outer_position` is the (rare) fallback.
        let pos = src
            .inner_position()
            .or_else(|_| src.outer_position())
            .ok()
            .map(|p| {
                let origin = drag_position(&src, p);
                let cursor = crate::detach::client_to_desktop(
                    origin,
                    (ws.cursor.x, ws.cursor.y),
                    coordinate_scale,
                );
                drag_native_position((cursor.0 - grab.0, cursor.1 - grab.1))
            });
        // The dragged tab is the ACTIVE tab. The drag-to-reorder gesture keeps
        // it active, while the FSM's armed index can go stale across reorders.
        let closing_idx = ws.mux.active;
        self.release_held_buttons_in_tab(ws, closing_idx);
        let Some(dt) = ws.mux.detach_tab(closing_idx) else {
            return false;
        };
        // The gesture leaves this window no matter how open_window goes.
        ws.tab_drag_active = false;
        ws.tab_drag_press = None;
        ws.tab_pressed_idx = None;
        ws.detach_drag = crate::detach::DragState::default();
        ws.drag_press = None;
        self.release_focus_report_to(ws, &dt);
        let paste = ws.take_moved_paste_state(&dt.tab, std::time::Instant::now());
        match self
            .open_window(
                event_loop,
                WindowOpen::AdoptTab {
                    tab: dt,
                    source_color: self.tear_off_source_color(ws),
                    paste: Box::new(paste),
                },
                pos,
                Some(size),
            )
            .map_err(|open| *open)
        {
            Ok(torn_seq) => {
                self.fire_tab_close_event(ws, closing_idx);
                self.ctl_broadcast(
                    "tab_moved",
                    None,
                    serde_json::json!({
                        "from_window": ws.seq,
                        "to_window": torn_seq,
                        "tab": closing_idx,
                    }),
                );
                self.resize_all(ws);
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
                // Re-anchor to the LIVE cursor: the pointer kept moving
                // during window creation, and the Windows modal move loop
                // anchors at the cursor's CURRENT position — without this
                // the grab offset drifts by however far the pointer slid
                // (see `cursor_screen_pos`).
                #[cfg(target_os = "windows")]
                if let Some((lx, ly)) = cursor_screen_pos()
                    && let Some(tw) = self.windows.get(&torn_seq).and_then(|t| t.window.as_ref())
                {
                    tw.set_outer_position(winit::dpi::PhysicalPosition::new(
                        (lx - grab.0) as i32,
                        (ly - grab.1) as i32,
                    ));
                }
                // The native handoff. On Err, manual-follow: the source
                // still holds mouse capture, so its CursorMoved stream
                // repositions the torn window until release. macOS goes
                // straight to manual-follow: performWindowDragWithEvent on
                // the TORN window would consume NSApp.currentEvent — a
                // mouseDragged belonging to the SOURCE window — which is
                // unsound for a window that never saw the press. A lone-tab
                // drag uses manual-follow too: currentEvent is a mouseDragged,
                // while AppKit requires the original mouse-down event.
                let native = if cfg!(target_os = "macos") || tear_native_handoff_disabled() {
                    false
                } else {
                    self.windows
                        .get(&torn_seq)
                        .and_then(|t| t.window.as_ref())
                        .map(|w| match w.drag_window() {
                            Ok(()) => true,
                            Err(e) => {
                                log::info!(
                                    "tear-off: native drag unavailable ({e}); manual follow"
                                );
                                false
                            }
                        })
                        .unwrap_or(false)
                };
                self.torn_drag = Some(TornDrag {
                    seq: torn_seq,
                    carrier: ws.seq,
                    started: std::time::Instant::now(),
                    grab,
                    dock: None,
                    native,
                    caption: false,
                    saw_move: false,
                    last_signal: std::time::Instant::now(),
                    hwnd: self
                        .windows
                        .get(&torn_seq)
                        .and_then(|t| t.window.as_deref())
                        .and_then(window_hwnd),
                    signal_cursor: None,
                });
                self.follow_torn_drag(ws);
            }
            Err(WindowOpen::AdoptTab { tab: dt, paste, .. }) => {
                log::warn!("tear-off: open_window failed; tab kept in source window");
                ws.mux.attach_tab(dt, Some(closing_idx));
                ws.restore_moved_paste_state(*paste);
            }
            Err(_) => unreachable!("open_window returns the WindowOpen it was given"),
        }
        true
    }

    /// Process the threshold-crossing motion too: a coalesced drag can release
    /// before another CursorMoved arrives to move the window and latch a dock.
    fn follow_torn_drag(&mut self, ws: &mut WindowState) -> bool {
        let Some(td) = self.torn_drag.as_ref() else {
            return false;
        };
        if td.native || td.carrier != ws.seq {
            return false;
        }
        let (grab, torn_seq) = (td.grab, td.seq);
        let Some(source_window) = ws.window.as_ref() else {
            return true;
        };
        let Ok(ip) = source_window.inner_position() else {
            return true;
        };
        let scale = drag_coordinate_scale(source_window);
        let step = crate::detach::manual_drag_step(
            drag_position(source_window, ip),
            (ws.cursor.x / scale, ws.cursor.y / scale),
            grab,
        );
        let torn_win = if torn_seq == ws.seq {
            ws.window.as_ref()
        } else {
            self.windows.get(&torn_seq).and_then(|t| t.window.as_ref())
        };
        let torn_hwnd = torn_win.map(|w| w.as_ref()).and_then(window_hwnd);
        if let Some(tw) = torn_win {
            tw.set_outer_position(drag_native_position(step.frame_origin));
        }
        if let Some(td) = self.torn_drag.as_mut() {
            td.saw_move = true;
            td.last_signal = std::time::Instant::now();
        }
        let extra = if torn_seq == ws.seq { None } else { Some(ws) };
        self.update_dock_target(step.cursor, torn_hwnd, extra);
        true
    }

    /// The client-px rect where a torn window can dock: the tab band,
    /// INCLUDING the would-be band of a hidden single-tab
    /// `auto` bar (the dock preview materializes it on hover). `None` when
    /// `tab-bar = off` (no strip exists to dock onto). Doubles as the tear
    /// threshold's band on the source window, where the bar is always
    /// visible (a tear needs ≥ 2 tabs).
    fn dock_band(&self, ws: &WindowState) -> Option<(f32, f32, f32, f32)> {
        if matches!(self.cfg.tab_bar, TabBarMode::Off) {
            return None;
        }
        let height = ws.renderer.as_ref().map(|r| r.cell_h + 8.0).unwrap_or(24.0);
        Some(self.tab_band(ws, height))
    }

    /// This window's tab band at `height`, shared by painting and docking.
    fn tab_band(&self, ws: &WindowState, height: f32) -> Rect {
        let surface = ws
            .renderer
            .as_ref()
            .map(|r| r.surface_size())
            .unwrap_or((800, 600));
        let bottom_status_height =
            if matches!(self.cfg.status_bar, kettle_config::StatusBarMode::Bottom) {
                self.status_bar_h(ws)
            } else {
                0.0
            };
        tab_band_rect(
            surface,
            self.cfg.tab_bar_pos,
            height,
            self.cfg.tab_bar_width,
            self.search_bar_h(ws),
            bottom_status_height,
        )
    }

    /// Insertion slot if the (approximated) screen
    /// cursor is over this window's tab band; `None` when it isn't (or
    /// the window can't host a dock right now).
    fn dock_index_at(&self, w: &WindowState, cursor: (f64, f64)) -> Option<usize> {
        let win = w.window.as_ref()?;
        if win.is_minimized().unwrap_or(false) || !win.is_visible().unwrap_or(true) {
            return None;
        }
        let ip = win.inner_position().ok()?;
        let client = crate::detach::desktop_to_client(
            drag_position(win, ip),
            cursor,
            drag_coordinate_scale(win),
        );
        self.dock_index_in_client(w, client)
    }

    fn dock_index_in_client(&self, w: &WindowState, client: (f64, f64)) -> Option<usize> {
        if !client.0.is_finite() || !client.1.is_finite() {
            return None;
        }
        let (cx, cy) = (client.0 as f32, client.1 as f32);
        let band = self.dock_band(w)?;
        if dist_to_rect(cx, cy, band) > 0.0 {
            return None;
        }
        let bar = self.tab_bar(w);
        let vertical = self.cfg.tab_bar_pos.is_vertical();
        if bar.height > 0.0 && !bar.segments.is_empty() {
            let mids: Vec<f32> = bar
                .segments
                .iter()
                .map(|s| {
                    let (x, y, sw_, sh_) = s.rect;
                    if vertical {
                        y + sh_ * 0.5
                    } else {
                        x + sw_ * 0.5
                    }
                })
                .collect();
            Some(dock_insertion_index(&mids, if vertical { cy } else { cx }))
        } else {
            // Hidden bar (single-tab auto, preview not applied yet): use
            // the geometry the bar WILL have once the preview materializes
            // it, so the slot can't flip between the first hit-test and
            // the next one. Vertically the lone segment occupies the strip's
            // first bar_h; horizontally the slot flips at the band centre.
            let bh = w.renderer.as_ref().map(|r| r.cell_h + 8.0).unwrap_or(24.0);
            let (mid, c) = if vertical {
                (bh * 0.5, cy)
            } else {
                // The tab1/tab2 boundary is the FULL band centre (the tab strip
                // divides the full width so its boundaries align with pane
                // splits — see `tab_strip_layout`), not the button-trimmed
                // strip centre; the slot flip must sit on that same boundary.
                let (bx, _, bw, _) = band;
                (bx + bw * 0.5, cx)
            };
            Some(if c < mid { 0 } else { 1 })
        }
    }

    /// Which window's tab band is under the screen
    /// cursor, and at which insertion slot. `extra` is the checked-out
    /// source window during manual-follow — it isn't in the map but is a
    /// legal (and common: drag out, change your mind, drop back) target.
    /// On Windows the candidates are resolved against the real z-order;
    /// elsewhere newest-window-first is the best approximation available
    /// (winit exposes no z-order).
    fn dock_hit_test(
        &self,
        cursor: (f64, f64),
        torn_seq: u64,
        torn_hwnd: Option<isize>,
        extra: Option<&WindowState>,
    ) -> Option<(u64, usize)> {
        let mut hits: Vec<(Option<isize>, u64, usize)> = Vec::new();
        for (seq, w) in extra
            .map(|w| (w.seq, w))
            .into_iter()
            .chain(self.windows.iter().rev().map(|(s, w)| (*s, w)))
        {
            if seq == torn_seq {
                continue;
            }
            if let Some(idx) = self.dock_index_at(w, cursor) {
                let hwnd = w.window.as_deref().and_then(window_hwnd);
                hits.push((hwnd, seq, idx));
            }
        }
        #[cfg(target_os = "windows")]
        if let Some(th) = torn_hwnd {
            let cands: Vec<(isize, u64, usize)> = hits
                .iter()
                .filter_map(|&(h, s, i)| h.map(|h| (h, s, i)))
                .collect();
            return zorder_pick(th, cursor, &cands);
        }
        #[cfg(not(target_os = "windows"))]
        let _ = torn_hwnd;
        hits.first().map(|&(_, s, i)| (s, i))
    }

    /// Re-run the hit-test for the live cursor and move
    /// the insertion preview (and the latched dock target) accordingly.
    /// `extra` = the checked-out source window in manual-follow, so the
    /// preview can land on it even though it's out of the map.
    fn update_dock_target(
        &mut self,
        cursor: (f64, f64),
        torn_hwnd: Option<isize>,
        mut extra: Option<&mut WindowState>,
    ) {
        let Some(td) = self.torn_drag.as_ref() else {
            return;
        };
        let torn_seq = td.seq;
        let prev = td.dock;
        let hit = self.dock_hit_test(cursor, torn_seq, torn_hwnd, extra.as_deref());
        if prev == hit {
            return;
        }
        if let Some((ps, _)) = prev
            && hit.map(|(s, _)| s) != Some(ps)
        {
            match extra.as_deref_mut() {
                Some(x) if x.seq == ps => self.apply_dock_preview_ws(x, None),
                _ => self.apply_dock_preview(ps, None),
            }
        }
        if let Some((ns, idx)) = hit {
            match extra {
                Some(x) if x.seq == ns => self.apply_dock_preview_ws(x, Some(idx)),
                _ => self.apply_dock_preview(ns, Some(idx)),
            }
        }
        // Dock-hover translucency (Windows): the full-size torn window is
        // covering the very strip the insertion marker draws in — go
        // see-through while a target is latched so the user can watch the
        // marker under the pointer; restore on unlatch.
        #[cfg(target_os = "windows")]
        if let Some(th) = self.torn_drag.as_ref().and_then(|t| t.hwnd) {
            match (prev.is_some(), hit.is_some()) {
                (false, true) => set_window_alpha(th, DOCK_HOVER_ALPHA),
                (true, false) => set_window_alpha(th, 255),
                _ => {}
            }
        }
        if let Some(td) = self.torn_drag.as_mut() {
            td.dock = hit;
        }
    }

    /// Does the latched dock target still hold at the
    /// moment a heuristic pointer-event commit fires? A real drop ended
    /// with the button UP; a WM-cancelled move (X11 Esc) ends its grab
    /// with the button still physically HELD — the same tell the Windows
    /// release path uses (`primary_button_physically_held`), read here
    /// from the X11 `QueryPointer` button mask. Position heuristics can't
    /// make this call: Esc doesn't move the pointer (a live-cursor
    /// hit-test still sees the band) and the WM's restore `Moved` re-syncs
    /// any frame-anchor estimate before the commit event arrives, so only
    /// the button state separates the two. `ws` = the torn window
    /// (checked out of the map).
    fn revalidate_dock_latch(&self, ws: &WindowState) -> bool {
        let Some(td) = self.torn_drag.as_ref() else {
            return false;
        };
        if td.caption
            && ws
                .native_caption_drag
                .as_ref()
                .is_some_and(|drag| drag.cancelled())
        {
            return false;
        }
        let Some((latched, _)) = td.dock else {
            // Nothing latched — commit and abandon are equivalent.
            return false;
        };
        // Esc-cancel: the WM ended its grab while the user still holds
        // the button. Abandon — the user's release hasn't happened, so
        // nothing was dropped.
        if primary_button_physically_held() {
            return false;
        }
        // Real drop: re-run the hit-test from the best cursor estimate —
        // live when available, else the legacy frame+grab approximation
        // (macOS manual-follow keeps its original self-consistent bias).
        let cursor = cursor_screen_pos().or_else(|| {
            ws.window.as_ref().and_then(|w| {
                w.outer_position().ok().map(|op| {
                    let origin = drag_position(w, op);
                    (origin.0 + td.grab.0, origin.1 + td.grab.1)
                })
            })
        });
        let Some(cursor) = cursor else {
            return true; // can't tell — trust the latch
        };
        self.dock_hit_test(cursor, td.seq, td.hwnd, None)
            .is_some_and(|(seq, _)| seq == latched)
    }

    /// The frozen-drag rescue tick, run from `about_to_wait` while torn-drag
    /// tracking is live. It covers two holes in event-driven tracking on
    /// GNOME/Mutter:
    /// - A native handoff the WM accepted but never (or no longer) acts on.
    ///   `Moved` events stop while the REAL pointer keeps travelling (e.g.
    ///   `_NET_WM_MOVERESIZE` racing a just-created, not-yet-mapped window, or
    ///   a WM that dropped the grab after a single incidental placement
    ///   `Moved`). That travel without `Moved` demotes the drag to
    ///   manual-follow.
    /// - Manual-follow starving because the pointer left the capture-holding
    ///   source window's bounds (its CursorMoved stream stops at the border).
    ///   The tick carries the torn window straight from the live pointer.
    ///
    /// Healthy native tracking (fresh `Moved` signals) is left strictly alone.
    /// Returns the wait budget (ms) that keeps the tick alive, or `None` when
    /// there is no drag or no live-cursor source (Wayland).
    fn torn_drag_pointer_tick(&mut self, event_loop: &ActiveEventLoop) -> Option<u64> {
        let td = self.torn_drag.as_ref()?;
        if td.caption {
            let seq = td.seq;
            let cancelled = self
                .windows
                .get(&seq)
                .and_then(|ws| ws.native_caption_drag.as_ref())
                .is_some_and(|drag| drag.cancelled());
            if cancelled || !primary_button_physically_held() {
                if !cancelled && let Some(cursor) = cursor_screen_pos() {
                    self.update_dock_target(cursor, None, None);
                }
                if let Some(mut ws) = self.windows.remove(&seq) {
                    let commit = !cancelled && self.revalidate_dock_latch(&ws);
                    self.finalize_torn_drag(&mut ws, commit);
                    self.finish_window_dispatch(event_loop, seq, ws);
                } else {
                    self.abandon_torn_drag(None);
                }
                return None;
            }
            if let Some(cursor) = cursor_screen_pos() {
                self.update_dock_target(cursor, None, None);
            }
            return Some(TORN_TICK_MS);
        }
        let cursor = cursor_screen_pos()?;
        if td.native {
            // Demotion evidence: the pointer travelled while the WM sent
            // no `Moved`. `signal_cursor` is the pointer at the last
            // tracking signal (or this tick's first look); `saw_move`
            // alone is NOT proof of health — a single incidental
            // placement `Moved` must not disable the rescue forever.
            let Some(reference) = td.signal_cursor else {
                if let Some(td) = self.torn_drag.as_mut() {
                    td.signal_cursor = Some(cursor);
                }
                return Some(TORN_TICK_MS);
            };
            let travelled =
                ((cursor.0 - reference.0).powi(2) + (cursor.1 - reference.1).powi(2)).sqrt();
            let waited = td.last_signal.elapsed() >= std::time::Duration::from_millis(400)
                && td.started.elapsed() >= std::time::Duration::from_millis(400);
            if !waited || travelled < DEMOTION_TRAVEL_PX {
                return Some(TORN_TICK_MS);
            }
            log::info!(
                "tear-off: pointer moved {travelled:.0}px with no WM move; demoting to manual follow"
            );
            if let Some(td) = self.torn_drag.as_mut() {
                td.native = false;
            }
        }
        let td = self.torn_drag.as_ref()?;
        // A CursorMoved-driven follow ran a moment ago — let the higher-
        // rate event stream win while it flows; the tick fills the gaps.
        if td.saw_move && td.last_signal.elapsed() < std::time::Duration::from_millis(30) {
            return Some(TORN_TICK_MS);
        }
        let (grab, torn_seq) = (td.grab, td.seq);
        let torn_win = self.windows.get(&torn_seq).and_then(|t| t.window.clone())?;
        torn_win.set_outer_position(drag_native_position((cursor.0 - grab.0, cursor.1 - grab.1)));
        let torn_hwnd = window_hwnd(&torn_win);
        if let Some(td) = self.torn_drag.as_mut() {
            td.saw_move = true;
            td.last_signal = std::time::Instant::now();
        }
        self.update_dock_target(cursor, torn_hwnd, None);
        Some(TORN_TICK_MS)
    }

    /// Set/clear a mapped window's dock preview (the
    /// checked-out variant below does the actual work).
    fn apply_dock_preview(&mut self, seq: u64, idx: Option<usize>) {
        if let Some(mut w) = self.windows.remove(&seq) {
            self.apply_dock_preview_ws(&mut w, idx);
            self.windows.insert(seq, w);
        }
    }

    /// Set/clear a window's dock preview. The preview
    /// that MATERIALIZES a hidden single-tab auto bar is render-only — the
    /// strip overlays the top of the content for the hover's duration and
    /// the PTY grids are NOT resized (hovering across the band
    /// edge would otherwise SIGWINCH-spam the target's shells with
    /// resize/restore pairs; the real resize happens once, in
    /// `dock_tab_into`, when a drop actually merges).
    fn apply_dock_preview_ws(&mut self, w: &mut WindowState, idx: Option<usize>) {
        if w.dock_preview == idx {
            return;
        }
        log::debug!("dock preview: window {} -> {idx:?}", w.seq);
        w.dock_preview = idx;
        if let Some(win) = &w.window {
            win.request_redraw();
        }
    }

    /// Drop torn-drag tracking without merging (stale
    /// tracking, cancel, or focus loss) — clears any latched insertion
    /// preview. `ws` = the checked-out window, in case the preview is on it.
    fn abandon_torn_drag(&mut self, ws: Option<&mut WindowState>) {
        if let Some(td) = self.torn_drag.take()
            && let Some((seq, _)) = td.dock
        {
            #[cfg(target_os = "windows")]
            if let Some(th) = td.hwnd {
                set_window_alpha(th, 255);
            }
            match ws {
                Some(x) if x.seq == seq => self.apply_dock_preview_ws(x, None),
                _ => self.apply_dock_preview(seq, None),
            }
        }
    }

    /// The drop. Commit the latched dock target —
    /// move the torn window's tab into the target at the insertion slot and
    /// close the emptied torn window — or just clear tracking + preview.
    /// `ws` is whatever window's dispatch observed the drop: the torn
    /// window itself for the native OS loop (winit synthesizes its
    /// left-release when the Windows modal move loop exits), or the
    /// capture-holding source for manual-follow.
    fn finalize_torn_drag(&mut self, ws: &mut WindowState, commit: bool) {
        let committable = self
            .torn_drag
            .as_ref()
            .is_some_and(|td| commit && td.saw_move && td.dock.is_some());
        if !committable {
            self.abandon_torn_drag(Some(ws));
            return;
        }
        let td = self.torn_drag.take().expect("checked committable above");
        let (target_seq, idx) = td.dock.expect("checked committable above");
        // The torn window is about to close (merge) — restoring opacity is
        // moot then, but the defensive multi-tab branch below keeps it
        // alive, and a no-op restore on a dying HWND is harmless.
        #[cfg(target_os = "windows")]
        if let Some(th) = td.hwnd {
            set_window_alpha(th, 255);
        }
        if td.seq == ws.seq {
            // Native loop: `ws` IS the torn window; the target is mapped.
            let donor_active = ws.mux.active;
            self.release_held_buttons_in_tab(ws, donor_active);
            let Some(dt) = ws.mux.detach_tab(donor_active) else {
                // Every early return after take() must clear the
                // latched preview, or the marker (and a materialized auto
                // bar) sticks to the target forever.
                self.clear_dock_preview_at(ws, target_seq);
                return;
            };
            let Some(mut target) = self.windows.remove(&target_seq) else {
                // Target vanished between latch and drop — keep the tab.
                ws.mux.attach_tab(dt, Some(donor_active));
                return;
            };
            self.release_focus_report_to(ws, &dt);
            let paste = ws.take_moved_paste_state(&dt.tab, std::time::Instant::now());
            self.dock_tab_into(&mut target, dt, paste, idx, td.seq);
            // The docked tab becomes the target's active tab; report it now,
            // since an already focused target gets no new focus event.
            self.sync_pane_focus_reports(&mut target);
            self.windows.insert(target_seq, target);
            self.focused_seq = target_seq;
            if ws.mux.tabs.is_empty() {
                // The emptied torn window closes through the normal funnel
                // (finish_window_dispatch drops it; other windows remain,
                // so no event-loop exit). Session-save pairing: every other
                // window-close path saves right before flagging the close.
                self.save_session(ws);
                self.request_window_close(ws.seq);
            }
        } else {
            // Manual-follow: `ws` is the SOURCE (capture holder); the torn
            // window is mapped. The target may be `ws` itself or another
            // mapped window (the hit-test excludes the torn window).
            let Some(mut torn) = self.windows.remove(&td.seq) else {
                // Torn window died mid-drag (reap) — the latch outlived it.
                self.clear_dock_preview_at(ws, target_seq);
                return;
            };
            let donor_active = torn.mux.active;
            self.release_held_buttons_in_tab(&mut torn, donor_active);
            let Some(dt) = torn.mux.detach_tab(donor_active) else {
                self.windows.insert(td.seq, torn);
                self.clear_dock_preview_at(ws, target_seq);
                return;
            };
            if target_seq == ws.seq {
                self.release_focus_report_to(&mut torn, &dt);
                let paste = torn.take_moved_paste_state(&dt.tab, std::time::Instant::now());
                self.dock_tab_into(ws, dt, paste, idx, td.seq);
            } else if let Some(mut target) = self.windows.remove(&target_seq) {
                self.release_focus_report_to(&mut torn, &dt);
                let paste = torn.take_moved_paste_state(&dt.tab, std::time::Instant::now());
                self.dock_tab_into(&mut target, dt, paste, idx, td.seq);
                self.sync_pane_focus_reports(&mut target);
                self.windows.insert(target_seq, target);
            } else {
                torn.mux.attach_tab(dt, Some(donor_active));
                self.windows.insert(td.seq, torn);
                return;
            }
            self.focused_seq = target_seq;
            if torn.mux.tabs.is_empty() {
                // Dropping outside finish_window_dispatch is safe here: the
                // map keeps the target (and source), so the "exit only when
                // the map is empty" invariant can't trip. Save first so the
                // session reflects the post-merge window set (the close-path
                // pairing every other close keeps).
                self.save_session(ws);
                drop(torn);
            } else {
                self.windows.insert(td.seq, torn);
            }
        }
    }

    /// Clear a latched dock preview wherever its window lives (the
    /// checked-out `ws` or the map).
    fn clear_dock_preview_at(&mut self, ws: &mut WindowState, target_seq: u64) {
        if ws.seq == target_seq {
            self.apply_dock_preview_ws(ws, None);
        } else {
            self.apply_dock_preview(target_seq, None);
        }
    }

    fn open_tab_window_chooser(&mut self, ws: &mut WindowState) {
        if !self.cfg.detachable_tabs {
            return;
        }
        let panes: Arc<[u64]> = ws.mux.tab_anchor_panes(ws.mux.active).into();
        if panes.is_empty() {
            return;
        }
        let mut destinations: Vec<_> = self
            .windows
            .iter()
            .filter(|(seq, window)| {
                **seq != ws.seq && window.window.is_some() && !self.window_close_pending(**seq)
            })
            .map(|(seq, window)| (*seq, window.last_title.clone()))
            .collect();
        destinations.sort_unstable_by_key(|(seq, _)| *seq);
        let mut items = vec![ContextMenuItem::Info {
            label: self
                .ui_text
                .text(kettle_i18n::Text::PaletteMoveTabToWindow)
                .to_owned(),
        }];
        for (window, title) in destinations {
            let title: String = sanitize_title(&title).chars().take(200).collect();
            items.push(ContextMenuItem::WindowChoice {
                label: format!("{window}: {title}"),
                window,
                panes: Arc::clone(&panes),
            });
        }
        if items.len() == 1 {
            items.push(ContextMenuItem::Info {
                label: self
                    .ui_text
                    .text(kettle_i18n::Text::WindowTransferNoTargets)
                    .to_owned(),
            });
        }
        self.close_all_modals(ws);
        self.show_context_menu(ws, items, 0.0, 0.0);
        if let Some((_, panel)) = self.context_menu_geometry(ws) {
            let surface = ws
                .renderer
                .as_ref()
                .map(|renderer| {
                    let size = renderer.surface_size();
                    (size.0 as f32, size.1 as f32)
                })
                .unwrap_or((800.0, 600.0));
            if let Some(menu) = ws.context_menu.as_mut() {
                menu.anchor = clamp_context_menu_anchor(
                    ((surface.0 - panel.0) * 0.5, (surface.1 - panel.1) * 0.5),
                    panel,
                    surface,
                );
            }
        }
    }

    #[cfg(target_os = "linux")]
    fn poll_wayland(&mut self, event_loop: &ActiveEventLoop) {
        let (files, update) = if let Some(bridge) = self.wayland.as_mut() {
            let live: std::collections::BTreeMap<_, _> = self
                .windows
                .iter()
                .filter(|(seq, _)| {
                    !self.quit_requested && !self.pending_window_closes.contains(seq)
                })
                .filter_map(|(&seq, window)| Some((seq, window.window.clone()?)))
                .collect();
            bridge.poll(&live);
            (bridge.file_updates(), bridge.drag_update())
        } else {
            (Vec::new(), None)
        };
        for file in files {
            self.deliver_wayland_files(event_loop, file);
        }
        let Some(update) = update else { return };
        let Some(drag) = self.wayland_tab_drag.as_ref() else {
            return;
        };
        let carrier = drag.carrier;
        let (point, ended, activation) = match update {
            crate::wayland::Update::Hover(point) => (point, None, None),
            crate::wayland::Update::End {
                performed,
                drop,
                activation,
            } => (drop, Some(performed), activation),
        };
        let target = point.and_then(|point| self.wayland_dock_target(point, carrier));
        let previous = self.wayland_tab_drag.as_mut().unwrap().preview.take();
        if let Some(previous) = previous
            && target.map(|(seq, _)| seq) != Some(previous)
        {
            self.apply_dock_preview(previous, None);
        }
        if ended.is_none() {
            if let Some((seq, insertion)) = target {
                self.apply_dock_preview(seq, Some(insertion));
                self.wayland_tab_drag.as_mut().unwrap().preview = Some(seq);
            }
            return;
        }
        if let Some(previous) = previous {
            self.apply_dock_preview(previous, None);
        }
        let drag = self.wayland_tab_drag.take().unwrap();
        let destination = if ended == Some(false) && drag.source != drag.carrier {
            Some((drag.source, drag.source_index))
        } else if ended == Some(true) {
            target
        } else {
            None
        };
        if let Some((seq, insertion)) = destination
            && let Some(mut carrier) = self.windows.remove(&drag.carrier)
        {
            if self.transfer_tab_to_window(&mut carrier, seq, &drag.panes, Some(insertion))
                && let (Some(bridge), Some(permit), Some(target)) = (
                    self.wayland.as_mut(),
                    activation,
                    self.windows
                        .get(&seq)
                        .and_then(|window| window.window.clone()),
                )
            {
                bridge.activate_drag(permit, seq, target);
            }
            self.finish_window_dispatch(event_loop, carrier.seq, carrier);
        }
    }

    #[cfg(target_os = "linux")]
    fn deliver_wayland_files(
        &mut self,
        event_loop: &ActiveEventLoop,
        update: crate::wayland::FileUpdate,
    ) {
        match update {
            crate::wayland::FileUpdate::Start { id, window } => {
                if !self.quit_requested
                    && !self.window_close_pending(window)
                    && let Some(ws) = self.windows.get(&window)
                    && !self.any_modal_open(ws)
                    && ws.mux.active_focus().is_some()
                {
                    self.wayland_file_drops
                        .insert(id, (window, WaylandDropTarget::capture(ws)));
                }
                log::debug!(
                    "Wayland file drop context captured: {}",
                    self.wayland_file_drops.contains_key(&id)
                );
            }
            crate::wayland::FileUpdate::Ready { id, paths } => {
                let context = self.wayland_file_drops.remove(&id);
                let valid = context.as_ref().is_some_and(|(seq, target)| {
                    !self.quit_requested
                        && !self.window_close_pending(*seq)
                        && self.windows.get(seq).is_some_and(|ws| {
                            !self.any_modal_open(ws) && *target == WaylandDropTarget::capture(ws)
                        })
                });
                log::debug!(
                    "Wayland file drop ready: parsed={}, context_current={valid}",
                    paths.is_ok()
                );
                let accepted = valid && paths.is_ok();
                if let Some(bridge) = self.wayland.as_mut() {
                    bridge.finish_files(id, accepted);
                }
                if !valid {
                    return;
                }
                let (seq, _) = context.unwrap();
                let Ok(paths) = paths else {
                    fire_notify(
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyTitleInputNotDelivered),
                        self.ui_text
                            .text(kettle_i18n::Text::NotifyBodyDropUnreadable),
                    );
                    return;
                };
                if let Some(mut ws) = self.windows.remove(&seq) {
                    self.exit_preview_focus(&mut ws);
                    let video = self.cfg.paste_video_preview.then(|| {
                        crate::video_preview::VideoPasteRequest::from_user_paths(
                            &paths,
                            crate::video_preview::VideoPasteSource::Drop,
                        )
                    });
                    self.paste_paths(&mut ws, paths, true, video.flatten());
                    if let Some(window) = &ws.window {
                        window.request_redraw();
                    }
                    self.finish_window_dispatch(event_loop, seq, ws);
                }
            }
        }
    }

    #[cfg(target_os = "linux")]
    fn wayland_dock_target(
        &self,
        point: crate::wayland::Point,
        carrier: u64,
    ) -> Option<(u64, usize)> {
        if point.window == carrier
            || self.window_close_pending(point.window)
            || self.quit_requested
            || !self.cfg.detachable_tabs
        {
            return None;
        }
        let target = self.windows.get(&point.window)?;
        if self.any_modal_open(target) {
            return None;
        }
        let scale = target.window.as_ref()?.scale_factor();
        self.dock_index_in_client(target, (point.x * scale, point.y * scale))
            .map(|index| (point.window, index))
    }

    #[cfg(target_os = "linux")]
    fn begin_wayland_tab_drag(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        window: Arc<winit::window::Window>,
    ) -> bool {
        if self.wayland_tab_drag.is_some()
            || self.window_close_pending(ws.seq)
            || self.quit_requested
            || self.any_modal_open(ws)
        {
            return false;
        }
        let index = ws.mux.active;
        let panes = ws.mux.tab_anchor_panes(index);
        if panes.is_empty() {
            return false;
        }
        let lone = ws.mux.tabs.len() == 1;
        let press = ws
            .drag_press
            .map(|(x, y)| (f64::from(x), f64::from(y)))
            .unwrap_or((ws.cursor.x, ws.cursor.y));
        let bar = self.tab_bar(ws);
        let grab = if lone {
            press
        } else {
            let segment = bar
                .segments
                .iter()
                .find(|segment| segment.active)
                .map(|segment| segment.rect);
            let (x, y, width, height) = segment.unwrap_or((0.0, 0.0, 80.0, 24.0));
            let along_x = (press.0 - f64::from(x)).clamp(8.0, f64::from(width.max(16.0)) - 8.0);
            let along_y = (press.1 - f64::from(y)).clamp(4.0, f64::from(height.max(8.0)) - 4.0);
            match self.cfg.tab_bar_pos {
                TabBarPos::Top => (along_x, along_y),
                TabBarPos::Bottom => (
                    along_x,
                    f64::from(window.inner_size().height) - f64::from(height) + along_y,
                ),
                TabBarPos::Left => (along_x, along_y),
                TabBarPos::Right => (
                    f64::from(window.inner_size().width) - f64::from(width) + along_x,
                    along_y,
                ),
            }
        };
        if !self.wayland.as_mut().is_some_and(|bridge| {
            bridge.begin_drag(
                ws.seq,
                window.clone(),
                (!lone).then_some(self.next_window_seq),
                grab,
            )
        }) {
            return false;
        }
        self.wayland_tab_drag = Some(WaylandTabDrag {
            source: ws.seq,
            source_index: index,
            panes,
            carrier: ws.seq,
            preview: None,
        });
        ws.tab_drag_active = false;
        ws.tab_drag_press = None;
        ws.tab_pressed_idx = None;
        ws.detach_drag = crate::detach::DragState::default();
        ws.drag_press = None;
        if lone {
            return true;
        }
        self.release_held_buttons_in_tab(ws, index);
        let Some(dt) = ws.mux.detach_tab(index) else {
            if let Some(bridge) = self.wayland.as_mut() {
                bridge.abandon_drag_carrier();
            }
            return true;
        };
        self.release_focus_report_to(ws, &dt);
        let paste = ws.take_moved_paste_state(&dt.tab, std::time::Instant::now());
        let color = self.tear_off_source_color(ws);
        match self
            .open_window(
                event_loop,
                WindowOpen::AdoptTab {
                    tab: dt,
                    source_color: color,
                    paste: Box::new(paste),
                },
                None,
                Some(window.inner_size()),
            )
            .map_err(|open| *open)
        {
            Ok(seq) => {
                self.wayland_tab_drag.as_mut().unwrap().carrier = seq;
                self.fire_tab_close_event(ws, index);
                self.ctl_broadcast(
                    "tab_moved",
                    None,
                    serde_json::json!({"from_window":ws.seq,"to_window":seq,"tab":index}),
                );
                self.resize_all(ws);
            }
            Err(WindowOpen::AdoptTab { tab: dt, paste, .. }) => {
                if let Some(bridge) = self.wayland.as_mut() {
                    bridge.abandon_drag_carrier();
                }
                ws.mux.attach_tab(dt, Some(index));
                ws.restore_moved_paste_state(*paste);
                self.resize_all(ws);
            }
            Err(_) => unreachable!("only an adopted tab was opened"),
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
        true
    }

    fn move_tab_to_window(&mut self, source: &mut WindowState, window: u64, panes: &[u64]) {
        if self.cfg.detachable_tabs && self.transfer_tab_to_window(source, window, panes, None) {
            #[cfg(target_os = "linux")]
            if let (Some(bridge), Some(origin), Some(target)) = (
                self.wayland.as_mut(),
                source.window.clone(),
                self.windows
                    .get(&window)
                    .and_then(|target| target.window.clone()),
            ) {
                bridge.activate(source.seq, origin, window, target);
            }
        }
    }

    fn transfer_tab_to_window(
        &mut self,
        source: &mut WindowState,
        window: u64,
        panes: &[u64],
        insertion: Option<usize>,
    ) -> bool {
        if self.quit_requested
            || source.seq == window
            || self.window_close_pending(source.seq)
            || self.window_close_pending(window)
        {
            return false;
        }
        let Some(index) = source.mux.tab_index_of_any_pane(panes) else {
            return false;
        };
        let Some(mut target) = self.windows.remove(&window) else {
            return false;
        };
        if target.window.is_none() {
            self.windows.insert(window, target);
            return false;
        }
        self.release_held_buttons_in_tab(source, index);
        let Some(dt) = source.mux.detach_tab(index) else {
            self.windows.insert(window, target);
            return false;
        };
        self.release_focus_report_to(source, &dt);
        let paste = source.take_moved_paste_state(&dt.tab, std::time::Instant::now());
        let insertion = insertion
            .unwrap_or(target.mux.tabs.len())
            .min(target.mux.tabs.len());
        self.dock_tab_into(&mut target, dt, paste, insertion, source.seq);
        self.sync_pane_focus_reports(&mut target);
        self.windows.insert(window, target);
        if source.mux.tabs.is_empty() {
            self.save_session(source);
            self.request_window_close(source.seq);
        } else {
            self.resize_all(source);
            if let Some(window) = &source.window {
                window.request_redraw();
            }
        }
        true
    }

    /// Receive a docked tab: attach at the insertion
    /// slot (attach_tab makes it active + seen), clear the preview, resize,
    /// take focus, notify agents.
    fn dock_tab_into(
        &mut self,
        target: &mut WindowState,
        dt: crate::mux::DetachedTab,
        paste: crate::window_state::MovedPasteState,
        idx: usize,
        from_seq: u64,
    ) {
        let landed = target.mux.attach_tab(dt, Some(idx));
        target.adopt_moved_paste_state(paste);
        target.dock_preview = None;
        self.resize_all(target);
        if let Some(w) = &target.window {
            w.set_visible(true);
            w.set_minimized(false);
            w.focus_window();
            w.request_redraw();
        }
        self.ctl_broadcast(
            "tab_moved",
            None,
            serde_json::json!({
                "from_window": from_seq,
                "to_window": target.seq,
                "tab": landed,
            }),
        );
    }

    /// Peacock: resolve + claim this window's accent — walk the theme's
    /// pool from the cwd-seed slot, skipping hues live windows already use:
    /// in-process siblings (authoritative) plus other kettle processes via
    /// the presence registry (best-effort; see kettle-ctl/src/presence.rs).
    fn assign_window_accent(&self, ws: &mut WindowState, avoid: Option<kettle_config::Rgb>) {
        let pool = kettle_config::peacock_pool(&self.cfg.theme);
        if pool.is_empty() {
            return;
        }
        let mut in_use = Vec::new();
        let dir = kettle_ctl::presence::presence_dir();
        let me = std::process::id();
        for e in kettle_ctl::presence::live_entries(&dir) {
            // Own-process claims are authoritative in the local registry,
            // including windows checked out during event dispatch.
            if e.pid == me {
                continue;
            }
            if let Some(c) = kettle_config::Rgb::parse(&e.rgb) {
                in_use.push(c);
            }
        }
        let Some((slot, local_claim)) =
            self.accent_registry
                .claim(&pool, self.cfg.accent_seed, &in_use, avoid)
        else {
            return;
        };
        let color = pool[slot];
        let presence = kettle_ctl::presence::claim(
            &dir,
            kettle_ctl::presence::PresenceEntry::claiming(
                me,
                ws.seq,
                crate::window_accent::rgb_hex(color),
                true,
            ),
        );
        ws.accent = Some(crate::window_state::WindowAccent {
            local_claim,
            color,
            slot,
            theme_name: self.cfg.theme_name.clone(),
            pool_candidates: kettle_config::peacock_candidates(&self.cfg.theme),
            presence,
        });
        crate::window_accent::apply_accent(ws);
    }

    /// The source window's accent for a tab leaving it, after applying any
    /// theme or palette change made since its last redraw.
    fn tear_off_source_color(&self, ws: &mut WindowState) -> Option<kettle_config::Rgb> {
        self.sync_window_accent(ws);
        ws.accent.as_ref().map(|accent| accent.color)
    }

    /// Peacock: keep this window's accent in sync, called once per frame
    /// from `redraw` — cheap steady state (an Option check + string compare).
    /// Covers: the first frame (claim), a theme switch (re-resolve the SAME
    /// pool slot against the new theme, so every window shifts consistently),
    /// and reconfiguration to a pinned hex / `accent-color = theme` (drops
    /// the claim and clears the renderer override).
    fn sync_window_accent(&self, ws: &mut WindowState) {
        crate::window_accent::refresh_accent(ws, &self.cfg);
        if ws.accent.is_none() && self.cfg.accent_auto && self.cfg.accent_color.is_none() {
            self.assign_window_accent(ws, None);
        }
    }

    /// Does any pane in this window have PTY output newer than the
    /// window's last paint? (`Terminal::output_generation` vs the snapshot
    /// `redraw` records.) Plain output emits no TermEvent, so this counter
    /// is the only reliable per-window "new output" signal for the fan-out
    /// wakeup.
    fn window_has_new_output(&self, ws: &WindowState) -> bool {
        ws.mux.panes.iter().any(|(id, p)| {
            ws.seen_output_gen.get(id).copied().unwrap_or(0) != p.term.output_generation()
        })
    }

    fn sync_output_wake_gate(&self, ws: &WindowState) {
        let render_quiesced = output_wakeup_must_quiesce(
            window_is_render_hidden(ws),
            ws.frame_recovery.has_pending(),
            ws.renderer.is_none() || self.gpu.as_ref().is_some_and(|gpu| gpu.is_lost()),
        );
        for pane in ws.mux.panes.values() {
            // A hidden surface does not need paint wakeups, but an opt-in
            // recorder/Lua sidechannel still needs event-loop service. Its
            // bounded lossless queue otherwise fills after eight PTY chunks
            // and blocks parsing indefinitely while the window is occluded.
            pane.term
                .set_output_wake_enabled(output_wake_transport_enabled(
                    render_quiesced,
                    pane.output_rx.is_some(),
                ));
        }
    }

    fn acknowledge_output_wakes(&self, ws: &WindowState) {
        for pane in ws.mux.panes.values() {
            pane.term.acknowledge_output_wake();
        }
    }

    /// Move a session aside when it loaded but could not be restored.
    ///
    /// Everything downstream of a rejected preflight behaves as if there were
    /// no session at all, including the next save, so without this the file is
    /// replaced by a single fresh tab before the user has finished looking at
    /// the window.
    fn stash_unrestorable_session(&self, reason: &str) {
        // The path this session was READ from, not a guess at where the next
        // save would go. Those are not the same question: `session_write_target`
        // routes on the snapshot being empty and on whether a named layout is
        // writable, and a `--tab-handoff` restore has no durable file at all.
        // Re-deriving it risked moving a file we never loaded.
        let Some(path) = self.restore_source.as_deref() else {
            log::warn!("session could not be restored ({reason}); it had no file to keep");
            return;
        };
        crate::session::stash_unrestorable_session(path, reason);
    }

    /// Resolve the one startup restore source before window or GPU creation.
    ///
    /// Loading and validating here lets `resumed_inner` seed the first native
    /// window with its final saved geometry. That avoids showing/configuring a
    /// default-sized swapchain and immediately replacing it after PTYs spawn.
    fn load_startup_session(&mut self) -> Option<crate::session::Session> {
        // Terminator parity (detachable tabs):
        // --tab-handoff-fd FD wins over the file handoff, named layout, and
        // default session. The option is consumed exactly once because
        // `UnixStream::from_raw_fd` takes ownership of the descriptor.
        if let Some(fd) = self.startup.tab_handoff_fd.take() {
            #[cfg(unix)]
            {
                use std::os::unix::io::FromRawFd;

                // SAFETY: the source kettle process passed this owned
                // descriptor through --tab-handoff-fd and surrendered it
                // across exec. `socket` closes it on every return path.
                let socket = unsafe { std::os::unix::net::UnixStream::from_raw_fd(fd) };
                let mut payload = vec![0u8; 1024 * 1024];
                return match crate::fd_transport::recv_fds(&socket, &mut payload, 64) {
                    Ok((n, received_fds)) => {
                        log::info!(
                            "tab-handoff-fd: received {n} bytes + {} fds",
                            received_fds.len()
                        );
                        // Adopting the received PTYs is a separate feature.
                        // Until then, explicitly close every owned descriptor.
                        for received_fd in received_fds {
                            // SAFETY: recv_fds returned ownership of each fd.
                            unsafe {
                                libc::close(received_fd);
                            }
                        }
                        payload.truncate(n);
                        match serde_json::from_slice(&payload) {
                            Ok(session) => Some(session),
                            Err(error) => {
                                log::warn!("tab-handoff-fd session JSON is invalid: {error}");
                                None
                            }
                        }
                    }
                    Err(error) => {
                        log::warn!("tab-handoff-fd recv_fds: {error}");
                        None
                    }
                };
            }
            #[cfg(not(unix))]
            {
                let _ = fd;
                log::warn!("--tab-handoff-fd unsupported on non-Unix");
                return None;
            }
        }

        // Record where the session came from as it is loaded. A rejected
        // restore has to move that exact file aside, and nothing downstream can
        // work it out afterwards: `session_write_target` routes on things this
        // function never sees, and a one-shot tab handoff has no durable file
        // by the time anyone asks.
        if let Some(path) = self.startup.tab_handoff.as_deref() {
            // Deliberately not recorded: `load_tab_handoff` deletes the file as
            // it reads, so there is nothing left to keep.
            crate::session::Session::load_tab_handoff(path)
        } else if let Some(name) = self.startup.layout.as_deref() {
            self.restore_source = crate::session::Session::path_for_layout(name);
            crate::session::Session::load_layout(name)
        } else if should_restore_session(self.startup.restore, self.cfg.restore_session) {
            self.restore_source = crate::session::Session::path();
            crate::session::Session::load()
        } else {
            None
        }
    }

    fn resumed_inner(&mut self, ws: &mut WindowState, event_loop: &ActiveEventLoop) {
        if ws.window.is_some() {
            return;
        }
        crate::startup_trace::mark(crate::startup_trace::Phase::Resumed);
        // Explicit command/cwd launches never restore a saved workspace.
        // Preserve the fields until the existing consumed-once spawn path
        // below, but decide and preflight the restore before native resources
        // are allocated.
        let has_launch_override = self.launch_override;
        // A launch override means the named layout is not loaded, so it must
        // not be written back either — otherwise the flag that names a layout
        // is the same flag that destroys it.
        self.named_layout_writable = !has_launch_override;
        let loaded_session = if ws.pre_launch.is_some() || has_launch_override {
            None
        } else {
            self.load_startup_session()
        };
        let live_monitors = monitor_rects(event_loop);
        // The size a saved window without geometry gets, in physical pixels
        // like the monitor rects it is validated against: the same startup
        // rule a fresh window uses, so a restore and a first launch agree.
        let monitor = startup_monitor(event_loop);
        if let Some(pre_launch) = ws.pre_launch {
            let matched = monitor == Some(pre_launch);
            crate::startup_trace::note_monitor_match(matched);
            if !matched {
                log::warn!("startup display changed after the pre-launch spawn");
            }
        }
        let default_surface = {
            let (w, h) = startup_inner_size(&self.cfg, monitor);
            let scale = monitor.map_or(1.0, |m| m.scale);
            (
                (w * scale).round().max(1.0) as u32,
                (h * scale).round().max(1.0) as u32,
            )
        };
        let restore_plan = loaded_session.as_ref().and_then(|session| {
            if session.is_empty() {
                return None;
            }
            let windows = match session.validated_restore_windows() {
                Ok(windows) => windows,
                Err(error) => {
                    self.stash_unrestorable_session(&error);
                    return None;
                }
            };
            let geometries = match crate::session::validated_restore_surface_geometries(
                &windows,
                &live_monitors,
                default_surface,
            ) {
                Ok(geometries) => geometries,
                Err(error) => {
                    self.stash_unrestorable_session(&error);
                    return None;
                }
            };
            Some((windows, geometries))
        });

        // Measure the fonts before the window. A pane's grid needs only the
        // cell, so a fresh window can size itself to exactly the configured
        // grid and start its first pane while the window and GPU initialize.
        // The system fonts have been loading on their own thread since
        // `run_with` began, and only the measurement needs this scale. The
        // renderer takes the fonts over.
        let startup_scale = monitor.map_or(1.0, |m| m.scale) as f32;
        if ws.pre_launch.is_none() {
            self.prepare_startup_fonts(ws, startup_scale);
        }
        // A restored window keeps its saved geometry, and a maximized or
        // full-screen one gets its size from the OS after creation. Only a
        // fresh normal or hidden window knows its size before it exists.
        let early_start = restore_plan.is_none()
            && matches!(
                self.cfg.window_state,
                kettle_config::WindowState::Normal | kettle_config::WindowState::Hidden
            );
        let startup_surface = if ws.pre_launch.is_some() {
            ws.startup_surface
        } else if early_start {
            self.startup_surface(ws, monitor)
        } else {
            None
        };
        ws.startup_surface = startup_surface;
        // The pane starts before the window only when the window will open at
        // this scale and size: on the monitor the cell was measured for, which
        // a configured position could change, and within it, where the OS
        // would shrink it. Otherwise it starts after the renderer, at the
        // window's real size.
        let spawned_early = ws.pre_launch.is_some()
            || startup_surface.is_some_and(|size| fits_monitor(size, monitor))
                && self.cfg.window_position_x.is_none()
                && self.cfg.window_position_y.is_none();
        if ws.pre_launch.is_none()
            && spawned_early
            && let Err(e) = self.spawn_first_tab(ws, has_launch_override)
        {
            log::error!("{e}");
            event_loop.exit();
            return;
        }
        if spawned_early && ws.pre_launch.is_none() {
            crate::startup_trace::mark(crate::startup_trace::Phase::PaneSpawned);
            crate::startup_trace::note_path(crate::startup_trace::StartupPath::ResumedEarly);
        }

        // Create the window hidden while renderer init runs on the event-loop
        // thread. The first successful paint reveals it; `window_state =
        // hidden` remains hidden.
        ws.window_shown = !should_reveal_after_renderer_init(self.cfg.window_state);
        ws.startup_window = true;
        let mut attrs = self.window_attributes(self.cfg.window_state, monitor);
        if let Some((width, height)) = startup_surface {
            attrs = attrs.with_inner_size(winit::dpi::PhysicalSize::new(width, height));
        }
        if let Some(geometry) = restore_plan
            .as_ref()
            .and_then(|(_, geometries)| geometries.first())
            .copied()
            .flatten()
        {
            attrs = attrs
                .with_position(winit::dpi::PhysicalPosition::new(geometry.x, geometry.y))
                .with_inner_size(winit::dpi::PhysicalSize::new(geometry.w, geometry.h));
        }
        // Startup is measured, not guessed: the window is created HIDDEN and
        // revealed at the first paint, so everything between here and that
        // reveal is time the user spends looking at nothing. A comparator
        // benchmark can only report the total.
        let t_startup = std::time::Instant::now();
        let window = match event_loop.create_window(attrs) {
            Ok(w) => Arc::new(w),
            Err(e) => {
                log::error!("failed to create window: {e}");
                ws.mux.kill_children();
                event_loop.exit();
                return;
            }
        };
        self.apply_post_create(&window);
        ws.native_fullscreen = Some(crate::native_fullscreen::NativeFullscreen::install(
            &window,
            ws.seq,
            self.proxy.clone(),
        ));
        ws.native_caption_drag = Some(crate::native_drag::NativeCaptionDrag::install(&window));
        ws.native_material = Some(crate::native_material::NativeMaterial::install(
            &window, &self.cfg,
        ));
        crate::startup_trace::mark(crate::startup_trace::Phase::WindowCreated);
        // Measured AFTER apply_post_create because the gpu figure below is
        // derived by subtraction; stopping the clock earlier would charge that
        // setup to the GPU.
        let create_window_ms = t_startup.elapsed().as_secs_f64() * 1000.0;
        let t_a11y = std::time::Instant::now();
        let accessibility = Self::new_accessibility_adapter(
            event_loop,
            &window,
            ws.seq,
            self.proxy.clone(),
            &self.ui_text,
        );
        let a11y_ms = t_a11y.elapsed().as_secs_f64() * 1000.0;

        // Reveal AFTER the accessibility adapter. AccessKit's winit adapter
        // panics if the window has already been shown when it is constructed
        // ("must be created before the window is shown (made visible) for the
        // first time"). The reveal has to sit between the adapter and renderer
        // init, and this ordering is load-bearing.
        //
        // Reveal before the GPU is ready only when the background is close
        // enough to black (see `background_is_dark_enough_to_reveal_early`).
        // Renderer init is ~730ms of startup, and on Windows an unpainted
        // window is black, so a near-black window can appear that much sooner
        // with no visible flash. Otherwise `window_shown` stays false and the
        // first paint reveals the window.
        //
        // The class brush is set to the terminal background as a best effort
        // only. The reveal does not depend on it, because winit owns
        // WM_ERASEBKGND and a light-background probe showed the pre-paint
        // window is black whatever the class brush says.
        if let Some(h) = window_hwnd(&window) {
            set_window_background_brush(h, self.cfg.theme.background);
        }
        let early_reveal = should_reveal_after_renderer_init(self.cfg.window_state)
            && background_is_dark_enough_to_reveal_early(self.cfg.theme.background);
        if early_reveal {
            window.set_visible(true);
            ws.window_shown = true;
            crate::startup_trace::mark(crate::startup_trace::Phase::WindowRevealed);
        }
        let size = window.inner_size();
        let scale = window.scale_factor() as f32;
        // Guard the synchronous GPU init against a hung
        // graphics driver. `Renderer::new` block_on's wgpu's adapter+device
        // requests on this (event-loop) thread; a wedged driver or GPU reset
        // can make those never return, leaving kettle stuck on an invisible
        // window (kept hidden until the first paint) with no
        // diagnostic — indistinguishable from a crash. A watchdog thread (which
        // only ever touches an `AtomicBool`, so there's no Send/thread-affinity
        // hazard with the GPU objects) turns that infinite hang into a clean,
        // actionable exit. `done` is set the instant init returns — success OR
        // a quick failure — so only a true never-returns hang trips it.
        let gpu_init_done = Arc::new(std::sync::atomic::AtomicBool::new(false));
        {
            let gpu_init_done = gpu_init_done.clone();
            // If the watchdog thread can't be spawned, proceed without it
            // rather than failing init.
            let _ = std::thread::Builder::new()
                .name("kettle-gpu-init-watchdog".into())
                .spawn(move || {
                    if gpu_init_timed_out(
                        &gpu_init_done,
                        std::time::Duration::from_secs(GPU_INIT_TIMEOUT_SECS),
                        std::time::Duration::from_millis(100),
                    ) {
                        log::error!(
                            "GPU initialization did not finish within {GPU_INIT_TIMEOUT_SECS}s — \
                             your graphics driver may be hung or unresponsive. Try updating the \
                             GPU driver; on Linux you can force software rendering with \
                             `LIBGL_ALWAYS_SOFTWARE=1` or pick another backend via \
                             `WGPU_BACKEND=gl`. Exiting so kettle doesn't hang invisibly."
                        );
                        // exit() skips destructors, so run_with's guard never
                        // flushes this startup's trace.
                        crate::startup_trace::flush();
                        std::process::exit(1);
                    }
                });
        }
        let init_result = {
            let runtime_tracker = self.runtime_tracker.clone();
            let _phase = runtime_tracker.enter("gpu_init");
            pollster::block_on(Renderer::new_with_display_handle(
                window.clone(),
                event_loop.owned_display_handle(),
                size.width.max(1),
                size.height.max(1),
                scale,
                &self.cfg,
                ws.startup_fonts.take(),
            ))
        };
        // Disarm the watchdog the moment init returns, on BOTH the success and
        // the quick-failure path, so a clean renderer-init error below never
        // gets a spurious "timed out" report behind it.
        gpu_init_done.store(true, std::sync::atomic::Ordering::Release);
        let renderer = match init_result {
            Ok(r) => r,
            Err(e) => {
                log::error!("renderer init failed: {e}");
                ws.mux.kill_children();
                event_loop.exit();
                return;
            }
        };
        crate::startup_trace::mark(crate::startup_trace::Phase::GpuReady);
        log::info!(
            "startup: working set after gpu init {:.1} MiB",
            process_working_set_mb()
        );
        log::info!(
            "startup: window create+setup {create_window_ms:.1}ms, accessibility {a11y_ms:.1}ms,              gpu {:.1}ms (cumulative {:.1}ms)",
            t_startup.elapsed().as_secs_f64() * 1000.0 - create_window_ms - a11y_ms,
            t_startup.elapsed().as_secs_f64() * 1000.0
        );
        // Cache the shared GPU context for open_window (windows 2..N).
        let gpu = renderer.gpu().clone();
        let recovery_proxy = self.proxy.clone();
        gpu.set_recovery_wake(kettle_render::ScreenshotRecoveryWake::new(move || {
            let _ = recovery_proxy.send_event(UserEvent::Wakeup);
        }));
        self.gpu = Some(gpu);
        ws.renderer = Some(renderer);
        ws.startup_cell = None;
        ws.startup_surface = None;
        ws.accessibility = Some(accessibility);
        ws.window = Some(window);
        self.sync_output_frame_budget(ws, true);
        if let Some(theme) = ws.window.as_ref().and_then(|w| w.theme()) {
            self.apply_initial_os_theme_preference(ws, theme);
        }

        let area = self.area(ws);
        let (cols, rows) = self.grid_of(ws, area);
        let geometry = self.pty_geometry_for_grid(ws, cols, rows);

        // CLI `-e cmd` / `-d dir` are consumed ONCE (they seed this window's
        // first tab and must not respawn on restore); take exactly those two
        // fields. The REST of `self.startup` stays intact for the whole
        // session — the explicit-restore gates below (`--tab-handoff` /
        // `--layout` / `--restore`), the save-session layout/restore gating,
        // and reload_config's launch-override re-application all
        // read it later.
        //
        // A wholesale `mem::take(&mut self.startup)` would silently default
        // those later reads, so `--layout` / `--restore` / `--tab-handoff`
        // would never load at startup and live reloads would drop the
        // `-m/-f/-b/-H/-T` overrides. Pinned by
        // `startup_is_not_taken_wholesale` below.
        let cmd_override = self.startup.command.take();
        let cwd_override = self.startup.cwd.take();
        // Resolve the session recording target for this launch: an explicit
        // `--record`/`--record-dir`/`KETTLE_RECORD*` override (in
        // `self.startup.record`) wins; otherwise the persistent `record = on`
        // config key records into `record-dir` (default `<config-dir>/recordings`).
        let dev_record = if let Some(target) = self.startup.record.clone() {
            Some((target, self.startup.record_raw_input))
        } else if self.cfg.record.enabled() {
            // `record-dir` from the config file is NOT shell-expanded, so honor a
            // leading `~`. Unset falls back to `<config-dir>/recordings`, resolved
            // from `Config::default_path()` (the base config dir, never a
            // `--profile` subdir) so it matches the documented default.
            self.cfg
                .record_dir
                .as_deref()
                .map(expand_user_path)
                .or_else(|| {
                    Config::default_path()
                        .and_then(|p| p.parent().map(|dir| dir.join("recordings")))
                })
                .map(|dir| {
                    (
                        kettle_core::record::RecordingTarget::Directory(dir),
                        self.cfg.record_raw_input,
                    )
                })
        } else {
            None
        };
        let restored = if spawned_early {
            true
        } else if has_launch_override {
            let argv = cmd_override.unwrap_or_default();
            let cwd = cwd_override
                .as_ref()
                .map(|p| p.to_string_lossy().into_owned());
            if let Err(e) = ws.mux.new_tab_with_geometry(
                &self.cfg,
                geometry,
                self.waker(),
                &argv,
                cwd.as_deref(),
            ) {
                log::error!("failed to spawn `-e` command: {e}");
                event_loop.exit();
                return;
            }
            true
        } else {
            match restore_plan.as_ref() {
                Some((wins, clamped_geometries)) => {
                    // The theme is config-governed (the config `theme =` line,
                    // with the compile-time default as fallback) and persisted
                    // via `persist_pref`. Restore never applies a
                    // session-stored theme, which would override the
                    // config/default on every restore. The session's `theme`
                    // field is ignored (kept only for back-compat parsing of
                    // older session.json files).
                    // `self.waker()` is the latched waker constructor; a
                    // hand-rolled closure would bypass the wakeup-dedup latch
                    // for every restored pane.
                    // Window 1 of the session restores into THIS window; each
                    // additional saved window opens via open_window(Restore),
                    // which works here because the GPU context was cached just
                    // above. A legacy single-window file normalizes to one
                    // entry.
                    if let Some((first, rest)) = wins.split_first() {
                        let first_session = crate::session::Session {
                            tabs: first.tabs.to_vec(),
                            active: first.active,
                            theme: None,
                            windows: Vec::new(),
                        };
                        let geometries = self.restore_geometries(ws, &first_session);
                        let mk = || self.waker();
                        let outcome =
                            ws.mux
                                .restore_geometry(&first_session, &self.cfg, &geometries, &mk);
                        // A tab that could not be rebuilt is gone from the live
                        // mux, and the next save rewrites the file from it. Keep
                        // the original so a transient failure — a command not on
                        // PATH yet, a fork refused under a process limit — costs
                        // nothing permanent.
                        if outcome.skipped > 0 {
                            self.stash_unrestorable_session(&format!(
                                "{} tab(s) could not be rebuilt",
                                outcome.skipped
                            ));
                        }
                        if outcome.restored_any {
                            for (index, sw) in rest.iter().enumerate() {
                                let sw = crate::session::SWindow {
                                    tabs: sw.tabs.to_vec(),
                                    active: sw.active,
                                    geometry: clamped_geometries.get(index + 1).copied().flatten(),
                                };
                                if self
                                    .open_window(event_loop, WindowOpen::Restore(sw), None, None)
                                    .is_err()
                                {
                                    self.stash_unrestorable_session(
                                        "could not open an additional window",
                                    );
                                    log::warn!(
                                        "session restore: could not open an additional window"
                                    );
                                }
                            }
                            // Focus comes home to window 1 (open_window moves
                            // focused_seq to each window it opens).
                            self.focused_seq = ws.seq;
                        }
                        outcome.restored_any
                    } else {
                        false
                    }
                }
                _ => false,
            }
        };
        if !restored && let Err(e) = ws.mux.new_tab_geometry(&self.cfg, geometry, self.waker()) {
            log::error!("failed to spawn shell: {e}");
            event_loop.exit();
            return;
        }
        if !spawned_early {
            crate::startup_trace::mark(crate::startup_trace::Phase::PaneSpawned);
            crate::startup_trace::note_path(crate::startup_trace::StartupPath::AfterRenderer);
        }
        if ws.cursor_exit_log.enabled
            && let Some(pane_id) = ws.mux.tabs.get(ws.mux.active).map(|tab| tab.focus)
            && let Some(window) = ws.window.as_deref()
        {
            ws.cursor_exit_log.bind(ws.seq, pane_id, window);
        }
        self.resize_all(ws);
        // Start the control server right after the first pane exists and BEFORE
        // the first GPU paint, which can take several seconds on a cold shader
        // cache. The server only needs the pid + a live proxy for its waker, so
        // binding it here makes the agent surface available as soon as the
        // window comes up. A re-resume does not start it again.
        if self.ctl_start == CtlStart::NotReady {
            self.ctl_start = CtlStart::Ready;
        }
        self.ensure_ctl_started();
        // Terminator plugin parity: fire
        // LuaEvent::Startup the first time we have an alive window
        // + at least one pane. Subsequent resumed() calls (Wayland
        // can re-emit) get short-circuited by lua_startup_fired.
        // Drains any LuaCommand the callbacks queued so a
        // `kettle.on('startup', function() kettle.send_text(...) end)`
        // takes effect immediately.
        if !self.lua_startup_fired && self.lua_engine.is_some() && ws.mux.focused().is_some() {
            self.fire_lua_event(ws, crate::LuaEvent::Startup, "startup hook");
            self.lua_startup_fired = true;
        }
        // Top-level script commands precede startup-hook commands in the same
        // FIFO. Run one bounded slice before the first paint; a stalled child
        // retains the exact head message and about_to_wait drives retries.
        let _ = self.poll_pending_lua_commands(ws, event_loop, std::time::Instant::now());
        // Start the session recorder now that the grid exists (when requested
        // via `--record` / `KETTLE_RECORD` or the `record = on` config key;
        // resolved above). Start it BEFORE the first `redraw()` below, which
        // runs the first `drain_events()` and tees PTY output into the trace. A
        // later start drops the session's opening output (e.g. a fast
        // `-e cmd`'s line).
        if let Some((target, raw)) = dev_record {
            let (cols, rows) = self.grid_of(ws, self.area(ws));
            match crate::dev_record::Recorder::start_target_async(
                &target,
                cols as u16,
                rows as u16,
                raw,
            ) {
                Ok(mut rec) => {
                    log::info!("dev-record: queued asynchronous start for {target:?}");
                    let proxy = self.proxy.clone();
                    rec.set_failure_waker(Arc::new(move || {
                        let _ = proxy.send_event(UserEvent::Wakeup);
                    }));
                    self.recording_start_failed = false;
                    self.recording_error_reported = false;
                    self.recorder = Some(rec);
                    self.sync_recording_state(ws, "");
                }
                Err(e) => {
                    log::warn!("dev-record: could not start recorder for {target:?}: {e}");
                    self.recording_start_failed = true;
                    let body = self
                        .ui_text
                        .notify_body_recording_start_failed(&e.to_string());
                    self.sync_recording_state(ws, &body);
                }
            }
        }
        if should_reveal_before_first_surface_frame(
            self.cfg.window_state,
            ws.window_shown,
            cfg!(target_os = "macos"),
        ) {
            if let Some(w) = &ws.window {
                w.set_visible(true);
            }
            ws.window_shown = true;
            crate::startup_trace::mark(crate::startup_trace::Phase::WindowRevealed);
            log::info!(
                "startup: window revealed before first macOS surface frame, working set {:.1} MiB",
                process_working_set_mb()
            );
        }
        self.start_window_frames(ws);
        // A window that starts hidden presents nothing until it is shown, so
        // its startup trace ends here, without a first frame. Any other
        // window's trace is printed by the first frame it presents.
        if !should_reveal_after_renderer_init(self.cfg.window_state) {
            crate::startup_trace::flush();
        }
        // The first frame is scheduled. The signed-feed worker skips the first
        // launch, applies the shared per-interval throttle, and honors
        // off/notify/auto. A recurring timer re-checks a long-lived window.
        crate::update_check::maybe_spawn_check(
            self.proxy.clone(),
            env!("CARGO_PKG_VERSION"),
            self.cfg.update_policy,
            self.cfg.update_check_interval_hours,
        );
        crate::update_check::spawn_update_check_timer(self.proxy.clone());
        // Warm the shell-detection cache (wsl.exe /
        // vswhere probes, bounded ~2s each) off the UI thread so the first
        // dropdown open / Ctrl+Shift+N press doesn't pay it.
        kettle_core::term::prewarm_shell_detection();
    }

    fn handle_accessibility_action(
        &mut self,
        ws: &mut WindowState,
        request: ActionRequest,
        event_loop: &ActiveEventLoop,
    ) {
        if let Some(index) = accessibility_confirm_button_index(request.target_node) {
            let Some(dialog) = ws.confirm_dialog.as_mut() else {
                return;
            };
            if index >= dialog.buttons.len() {
                return;
            }
            match request.action {
                AccessibilityAction::Focus => dialog.focus_idx = index,
                AccessibilityAction::Click => {
                    let confirm = matches!(dialog.buttons[index], ConfirmButton::Confirm { .. });
                    if confirm {
                        let action = dialog.on_confirm.clone();
                        ws.confirm_dialog = None;
                        self.dispatch_confirm_action(ws, action, event_loop);
                    } else {
                        self.cancel_confirm_dialog(ws);
                    }
                }
                _ => return,
            }
            ws.accessibility_pending = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
            return;
        }
        if request.target_node == ACCESSIBILITY_MEDIA_RECEIPT_DISMISS_ID {
            if request.action == AccessibilityAction::Click {
                ws.media_paste_receipt = None;
                ws.accessibility_pending = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            return;
        }
        if request.target_node == ACCESSIBILITY_MEDIA_RECEIPT_ID {
            if request.action == AccessibilityAction::Click {
                let openable = self
                    .media_paste_receipt_projection(ws)
                    .is_some_and(|(receipt, _)| receipt.openable);
                if openable {
                    self.open_media_paste_receipt(ws);
                } else if ws.media_paste_receipt.take().is_some() {
                    ws.accessibility_pending = true;
                    if let Some(window) = &ws.window {
                        window.request_redraw();
                    }
                }
            }
            return;
        }
        if let Some((pane, part)) = accessibility_lane_part(request.target_node) {
            if !self.preview_is_reachable(ws, pane) {
                return;
            }
            if part == LANE_SCRUBBER_PART && request.action != AccessibilityAction::Focus {
                self.seek_lane_by_accessibility(ws, pane, &request);
                return;
            }
            let hit = self
                .shown_preview_controls(ws, pane)
                .into_iter()
                .find(|(at, _, _)| *at == part)
                .map(|(_, _, hit)| hit);
            if let Some(hit) = hit {
                match request.action {
                    AccessibilityAction::Focus => {
                        if let Some(open) =
                            ws.preview_overlay.as_mut().filter(|open| open.pane == pane)
                        {
                            open.control = Some(part);
                        }
                        self.lanes_changed(ws, false);
                    }
                    AccessibilityAction::Click => self.act_on_preview(ws, pane, hit),
                    _ => {}
                }
            }
            return;
        }
        if let Some(instance) = accessibility_card_instance(request.target_node) {
            // Only a card the tree names answers: one on screen, under no
            // dialog or viewer. A stale instance names nothing, so it can
            // never focus or open another card.
            let reachable = self
                .accessible_cards(ws)
                .iter()
                .any(|(card, _, _)| *card == instance);
            if reachable && let Some((pane, nonce)) = ws.card_sightings.by_instance(instance) {
                match request.action {
                    AccessibilityAction::Focus => {
                        // The card's pane takes the keyboard with it, so text
                        // typed next goes where the screen reader is. Search
                        // would keep the keys, so it closes, remembering its
                        // query.
                        self.close_search(ws);
                        let pre = self.focus_key(ws);
                        ws.mux.focus_pane(pane);
                        self.note_focus_change(ws, pre);
                        ws.card_focus = Some(instance);
                    }
                    AccessibilityAction::Click => {
                        self.open_card(ws, pane, nonce);
                    }
                    _ => return,
                }
                ws.accessibility_pending = true;
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            return;
        }
        if !ws.search.open {
            return;
        }
        let control = if request.target_node == ACCESSIBILITY_SEARCH_TEXT_ID {
            Some(kettle_render::SearchControl::Editor)
        } else {
            accessibility_search_control_from_id(request.target_node)
        };
        let Some(control) = control else {
            return;
        };

        match request.action {
            AccessibilityAction::Focus => ws.search.focused_control = control,
            AccessibilityAction::Click => {
                ws.search.focused_control = control;
                self.activate_search_control(ws, control);
            }
            AccessibilityAction::SetValue if control == kettle_render::SearchControl::Editor => {
                if let Some(ActionData::Value(value)) = request.data {
                    let outcome = ws
                        .search
                        .editor
                        .replace_all(&value, kettle_core::MAX_SEARCH_QUERY_BYTES);
                    if outcome.changed {
                        ws.search.note_edit(std::time::Instant::now());
                    }
                    if outcome.truncated {
                        ws.search.status = kettle_render::SearchStatus::TooLong;
                    }
                }
            }
            AccessibilityAction::ReplaceSelectedText
                if control == kettle_render::SearchControl::Editor =>
            {
                if let Some(ActionData::Value(value)) = request.data {
                    let outcome = ws
                        .search
                        .editor
                        .insert(&value, kettle_core::MAX_SEARCH_QUERY_BYTES);
                    if outcome.changed {
                        ws.search.note_edit(std::time::Instant::now());
                    }
                    if outcome.truncated {
                        ws.search.status = kettle_render::SearchStatus::TooLong;
                    }
                }
            }
            AccessibilityAction::SetTextSelection
                if control == kettle_render::SearchControl::Editor =>
            {
                if let Some(ActionData::SetTextSelection(selection)) = request.data
                    && selection.anchor.node == ACCESSIBILITY_SEARCH_TEXT_ID
                    && selection.focus.node == ACCESSIBILITY_SEARCH_TEXT_ID
                {
                    ws.search.editor.set_character_selection(
                        selection.anchor.character_index,
                        selection.focus.character_index,
                    );
                }
            }
            _ => return,
        }
        if ws.search.open {
            self.sync_search_editor_scroll(ws);
        }
        if let Some(window) = &ws.window {
            window.request_redraw();
        }
    }

    fn user_event_inner(&mut self, ws: &mut WindowState, _el: &ActiveEventLoop, ev: UserEvent) {
        ws.reuse_pane_snapshots_once = false;
        match ev {
            #[cfg(target_os = "linux")]
            UserEvent::Wayland => {}
            // Consumed by the outer window-less dispatch before a WindowState
            // is checked out.
            UserEvent::Activation
            | UserEvent::PastedImageEncoded
            | UserEvent::NativeFullscreenExited { .. }
            | UserEvent::RemoteScanReady
            | UserEvent::MediaRendered
            | UserEvent::LanePlayback => {}
            UserEvent::AccessibilityAction { request, .. } => {
                self.handle_accessibility_action(ws, request, _el);
            }
            UserEvent::VideoPreviewReady {
                window_seq,
                pane_id,
                generation,
                candidate,
                preview,
            } => {
                if window_seq != ws.seq {
                    return;
                }
                use crate::window_state::VideoPreviewOutcome;
                let poster = preview.is_some();
                let outcome = ws.finish_pending_video_preview(
                    pane_id,
                    generation,
                    candidate,
                    preview,
                    std::time::Instant::now(),
                );
                log::debug!("video paste receipt for pane {pane_id}: {outcome:?}, poster {poster}");
                if matches!(
                    outcome,
                    VideoPreviewOutcome::Failed | VideoPreviewOutcome::Shown
                ) && let Some(window) = &ws.window
                {
                    window.request_redraw();
                }
            }
            UserEvent::Wakeup => {
                // Semantic terminal events and direct-child lifecycle edges
                // are not paint damage. Drain them before the output-generation
                // gate so a quiet exit is applied even when the window is
                // hidden, minimized, or has cursor blinking disabled.
                if take_window_lifecycle_wakes(ws) {
                    self.drain_events(ws);
                }
                // Apply current visibility/recovery policy, but leave enabled
                // latches closed until redraw is ready to snapshot a frame.
                // This prevents one queued event from reopening the flood gate
                // before the deferred paint budget expires.
                self.sync_output_wake_gate(ws);
                // Wakeups fan out to every window; skip windows whose
                // panes produced no output since their last paint (plain
                // text emits no TermEvent — the generation counter is the
                // only reliable per-window signal).
                if !output_wakeup_needs_paint(
                    || self.window_has_new_output(ws),
                    || self.acknowledge_output_wakes(ws),
                ) {
                    return;
                }
                // Run output triggers before the redraw —
                // a match fires window urgency so the user notices the
                // event even if they're focused on another OS window.
                // Cheap when triggers are empty (which is the default).
                self.run_triggers(ws);
                if output_wakeup_must_quiesce(
                    window_is_render_hidden(ws),
                    ws.frame_recovery.has_pending(),
                    ws.renderer.is_none() || self.gpu.as_ref().is_some_and(|gpu| gpu.is_lost()),
                ) {
                    if ws.mux.panes.values().any(|pane| pane.output_rx.is_some()) {
                        // Rearm before draining. Output racing after this point
                        // owns a new wake; output already queued is consumed by
                        // this nonblocking drain. Reversing the order leaves a
                        // drain/ack race that can strand the next lossless
                        // chunk with no event-loop wake.
                        self.acknowledge_output_wakes(ws);
                        self.drain_recorder_output_once(ws);
                    }
                    // Keep terminal damage pending while the surface is
                    // occluded, minimized, explicitly invisible, or while its
                    // one-shot repair deadline is armed.
                    // Output bursts must not bypass timeout backoff.
                    ws.output_pacer.reset();
                    return;
                }
                // Coalesce rapid PTY-output paints to ~one per
                // frame budget so a non-atomic repaint burst settles before we
                // snapshot the grid. When deferred, `about_to_wait` schedules
                // the flush at the budget deadline so the final frame still
                // paints. Input/cursor paints don't come through here, so
                // typing and the cursor stay immediate.
                let now = std::time::Instant::now();
                // Keystroke ECHO paints immediately. request_redraw is
                // vsync-coalesced, so this can't outpace the display, and the
                // coalescer's job (letting a NON-atomic output burst settle
                // before the snapshot) doesn't apply to a few echoed cells.
                // Routing echo through the WaitUntil deadline (~16ms timer
                // granularity on Windows, frequently late) makes held-key
                // repeat visibly stutter.
                if typed_recently(now, ws.last_typed, TYPING_ECHO_WINDOW) {
                    ws.output_pacer.reset();
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                } else if should_defer_output_paint(
                    now,
                    ws.last_paint,
                    effective_output_budget(ws.output_frame_budget, ws.flood_paints),
                ) {
                    ws.output_pacer.defer();
                } else if let Some(w) = &ws.window {
                    ws.output_pacer.queue_deferred_redraw();
                    w.request_redraw();
                }
            }
            // Consumed by the outer process-level debounce dispatch.
            UserEvent::ReloadConfig => {}
            UserEvent::RemoteCommand => self.drain_remote_commands(ws),
            UserEvent::Ctl => self.drain_ctl(ws, _el),
            UserEvent::UpdateAvailable { tag, url } => {
                if crate::update_check::is_dismissed(&tag) {
                    return;
                }
                // A newer release exists. Show the dismissable
                // bottom-bar banner, fire one desktop toast, and nudge the
                // taskbar/dock so the user notices even if kettle is unfocused.
                fire_notify(
                    self.ui_text
                        .text(kettle_i18n::Text::NotifyTitleUpdateAvailable),
                    &self.ui_text.notify_body_update_available(&tag),
                );
                self.update_available = Some((tag, url));
                Self::queue_window_resizes(
                    std::iter::once(&mut *ws).chain(self.windows.values_mut()),
                );
                if let Some(w) = &ws.window {
                    // Only raise OS attention (+ latch the tracker)
                    // when unfocused — mirroring the bell path — so
                    // `attention_active` keeps meaning "a flash is actually
                    // outstanding". FlashWindowEx is a no-op on the foreground
                    // window anyway, and latching the flag while focused would
                    // leave it set until an unrelated defocus/refocus.
                    if !ws.window_focused {
                        w.request_user_attention(Some(UserAttentionType::Informational));
                        ws.attention_active = true;
                    }
                }
            }
            UserEvent::UpdateInstalled {
                tag,
                staged,
                first_time,
            } => {
                let tr = &self.ui_text;
                let title = tr.text(if staged {
                    kettle_i18n::Text::NotifyTitleUpdateStaged
                } else {
                    kettle_i18n::Text::NotifyTitleUpdateInstalled
                });
                // On the first automatic install, tell the user auto-update is
                // on and how to opt out (oh-my-zsh style, one time only).
                let body = match (staged, first_time) {
                    (true, true) => tr.notify_body_update_staged_first(&tag),
                    (true, false) => tr.notify_body_update_staged(&tag),
                    (false, true) => tr.notify_body_update_installed_first(&tag),
                    (false, false) => tr.notify_body_update_installed(&tag),
                };
                fire_notify(title, &body);
            }
            UserEvent::UpdateFailed { message } => {
                log::warn!("automatic update failed: {message}");
                fire_notify(
                    self.ui_text
                        .text(kettle_i18n::Text::NotifyTitleUpdateFailed),
                    &message,
                );
            }
            UserEvent::UpdateCheckTick => {
                crate::update_check::maybe_spawn_check(
                    self.proxy.clone(),
                    env!("CARGO_PKG_VERSION"),
                    self.cfg.update_policy,
                    self.cfg.update_check_interval_hours,
                );
            }
            // Every Dock row maps onto an action kettle already has, so this
            // reuses the keybind path wholesale — including NewWindow's
            // fall-back to a new tab when a window cannot be created.
            #[cfg(target_os = "macos")]
            UserEvent::DockCommand(command) => {
                self.handle_action(ws, command.action(), _el);
            }
        }
    }

    fn window_event_inner(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
        event: WindowEvent,
    ) {
        let preserves_menu_redraw_hint = matches!(
            &event,
            WindowEvent::RedrawRequested | WindowEvent::CursorMoved { .. }
        ) && ws.context_menu.is_some();
        if !preserves_menu_redraw_hint {
            ws.reuse_pane_snapshots_once = false;
        }
        if let (Some(adapter), Some(window)) = (&mut ws.accessibility, &ws.window) {
            adapter.process_event(window, &event);
        }
        match event {
            WindowEvent::CloseRequested => {
                // The titlebar ✕ and Alt+F4 ask the window manager to destroy a
                // window; they are not Kettle commands. Ordinary applications
                // veto that only for unsaved document state, and a terminal has
                // no authoritative dirty bit ("a process exists" is not "work
                // would be lost"). A veto would also make the gesture
                // nondeterministic, and because `shell_idle()` reports busy for
                // any pane without OSC 133 integration, EVERY multi-pane window
                // would prompt. So this gesture closes.
                //
                // `ask-before-closing = always` is the opt-in for people who
                // want the question here, and the only policy that still asks
                // it. The keybind close actions (`ClosePane`, `CloseTab`,
                // `CloseWindow`) are Kettle commands, not OS requests, and keep
                // the full policy. Ask BEFORE any of the teardown below, so the
                // session is not saved and the recorder not finished while the
                // user is still deciding.
                if self.cfg.ask_before_closing == kettle_config::AskBeforeClosing::Always {
                    let (scope, busy) = window_close_scope(ws);
                    if self.confirm_close(
                        ws,
                        self.ui_text.confirm_close_window(scope as u64),
                        scope,
                        busy,
                        ConfirmAction::CloseWindow {
                            drop_panes: DropPanes::No,
                        },
                    ) {
                        return;
                    }
                }
                self.close_window_now(ws, DropPanes::No);
            }
            WindowEvent::Resized(size) => {
                self.sync_output_frame_budget(ws, false);
                // Minimizing a window delivers Resized(0, 0) on Windows.
                // Reconfiguring the surface + `resize_all` to a 0×0 area would
                // collapse every PTY to a 1×1 grid (`grid_of`'s `.max(1)`) and
                // fire a SIGWINCH storm that reflows/redraws every TUI in every
                // pane, then reflows them all back on restore. Skip a
                // degenerate size entirely: keep the last good grid so PTYs
                // hold their real dimensions; the genuine restore carries the
                // true non-zero size and reflows once.
                if size.width == 0 || size.height == 0 {
                    ws.dpi_resize_surface_suspended = true;
                    return;
                }
                // AppKit can briefly restore its stale standard frame. Wait
                // for the window-local restore before reflowing terminal grids.
                if ws
                    .native_fullscreen
                    .as_ref()
                    .is_some_and(|native| native.pending())
                {
                    ws.dpi_resize_surface_suspended = true;
                    return;
                }
                ws.dpi_resize_surface_suspended = false;
                // The Metal layer stretches its last frame to the new size
                // until the resize's frame presents, and that frame may have
                // to retry. The cursor patch would keep blinking where the
                // cell was.
                if ws
                    .renderer
                    .as_ref()
                    .is_none_or(|r| r.surface_size() != (size.width, size.height))
                {
                    Self::hide_cursor_layer(ws);
                }
                let renderer_ready = self.dpi_resize_renderer_ready(ws);
                if ws.dpi_resize.on_event(DpiResizeEvent::Resized {
                    width: size.width,
                    height: size.height,
                    renderer_ready,
                }) == DpiResizeAction::ApplyLayout
                {
                    self.commit_window_resize(ws, size.width, size.height);
                }
            }
            WindowEvent::ScaleFactorChanged { scale_factor, .. } => {
                // The patch was drawn at the old scale, and the new-scale frame
                // may wait for the paired resize.
                Self::hide_cursor_layer(ws);
                self.sync_output_frame_budget(ws, true);
                // Apply the new DPI scale so text follows >100% Windows scaling
                // and rescales when dragged to a different-DPI monitor.
                // set_scale re-derives physical font metrics + cell size. Do
                // not re-grid yet: on Windows this event precedes the
                // SetWindowPos-driven Resized, so the physical size is still
                // from the old monitor. The coalescer commits once at the
                // following usable Resized; about_to_wait is the fallback for
                // backends that do not emit one.
                ws.dpi_resize.on_event(DpiResizeEvent::ScaleFactorChanged);
                ws.frame_recovery.expedite(std::time::Instant::now());
                if !ws.frame_recovery.renderer_rebuild_pending()
                    && let Some(r) = ws.renderer.as_mut()
                {
                    r.set_scale(scale_factor as f32);
                }
            }
            WindowEvent::ThemeChanged(theme) => {
                self.apply_os_theme_preference(ws, theme);
            }
            WindowEvent::ModifiersChanged(m) => {
                #[cfg(not(target_os = "macos"))]
                {
                    ws.mods = m.state();
                }
                #[cfg(target_os = "macos")]
                {
                    use winit::keyboard::ModifiersKeyState;

                    ws.macos_raw_mods = m.state();
                    ws.macos_left_option_pressed = m.lalt_state() == ModifiersKeyState::Pressed;
                    ws.macos_right_option_pressed = m.ralt_state() == ModifiersKeyState::Pressed;
                    refresh_macos_modifiers(ws, self.cfg.macos_option_as_alt);
                }
                // Modifier change can flip the URL hover affordance from
                // text-I-beam to pointing-hand without the mouse moving
                // (Ctrl held = "this click would open"). Re-sync the
                // cursor icon so the affordance updates the moment Ctrl
                // is pressed/released over a link.
                self.sync_cursor_icon(ws);
            }
            // Terminator parity: winit CursorLeft/Entered events transition the
            // detach FSM. CursorLeft → DraggingOutside; CursorEntered →
            // DraggingInside (the user brought the cursor back, which cancels
            // the cross-window flow). Mouse-down arming on the tab bar enters
            // the FSM, and a transition on `Idle` is a harmless no-op.
            //
            // The torn window streams `Moved` during the OS move loop (Windows:
            // WM_WINDOWPOSCHANGED inside the NC modal loop; X11:
            // ConfigureNotify from the WM move, both verified). Approximate the
            // live cursor as frame origin + grab offset and drive the re-dock
            // hit-test against every sibling window's tab band.
            WindowEvent::Moved(pos) => {
                self.sync_output_frame_budget(ws, false);
                if let Some(started) = ws
                    .native_caption_drag
                    .as_ref()
                    .and_then(|drag| drag.take_start())
                    && self.torn_drag.is_none()
                    && crate::native_drag::may_dock_caption(
                        self.cfg.detachable_tabs,
                        !matches!(self.cfg.tab_bar, TabBarMode::Off),
                        ws.mux.tabs.len(),
                        self.pointer_modal_open(ws),
                    )
                    && let Some(cursor) = cursor_screen_pos()
                    && let Some(window) = ws.window.as_ref()
                    && !window.is_maximized()
                    && window.fullscreen().is_none()
                {
                    let origin = drag_position(window, pos);
                    self.torn_drag = Some(TornDrag {
                        seq: ws.seq,
                        carrier: ws.seq,
                        started,
                        grab: (cursor.0 - origin.0, cursor.1 - origin.1),
                        dock: None,
                        native: true,
                        caption: true,
                        saw_move: false,
                        last_signal: std::time::Instant::now(),
                        hwnd: window_hwnd(window),
                        signal_cursor: Some(cursor),
                    });
                }
                let Some(td) = self.torn_drag.as_mut() else {
                    return;
                };
                if td.seq != ws.seq {
                    return;
                }
                td.saw_move = true;
                td.last_signal = std::time::Instant::now();
                let grab = td.grab;
                // Frame + grab approximates the pointer, but the move
                // loop's anchor drifts from `grab` by however far the
                // pointer slid between press/tear and loop start — a
                // session recording measured 55-86px under Mutter, enough
                // to miss the whole band. The LIVE cursor is one call away
                // on Windows (GetCursorPos) AND on X11 (QueryPointer via
                // the side connection); the approximation remains the
                // fallback for a failed query. Each real-cursor + `Moved`
                // pair also refreshes `signal_cursor`, the rescue tick's
                // travel-without-`Moved` demotion reference.
                let origin = ws
                    .window
                    .as_deref()
                    .map(|window| drag_position(window, pos))
                    .unwrap_or((f64::from(pos.x), f64::from(pos.y)));
                let approx = (origin.0 + grab.0, origin.1 + grab.1);
                let real = cursor_screen_pos();
                if let Some(cur) = real {
                    td.signal_cursor = Some(cur);
                }
                let cursor = real.unwrap_or(approx);
                let torn_hwnd = ws.window.as_deref().and_then(window_hwnd);
                self.update_dock_target(cursor, torn_hwnd, None);
            }
            WindowEvent::CursorLeft { .. } => {
                let prev = std::mem::take(&mut ws.detach_drag);
                ws.detach_drag = prev.on_cursor_leave_window();
                if ws.selecting
                    && let Some(window) = &ws.window
                {
                    let size = window.inner_size();
                    ws.selection_autoscroll_edge = selection_leave_edge(
                        ws.selection_dragged,
                        ws.cursor.x as f32,
                        ws.cursor.y as f32,
                        size.width as f32,
                        size.height as f32,
                    );
                }
                // Pointer left the window → drop the scrollbar hover so
                // the overlay bar relaxes to its dim state.
                ws.scrollbar_hover = false;
                ws.hovered_close_idx = None;
                ws.hovered_new_tab = false;
                ws.hovered_new_tab_menu = false;
                ws.search.hovered_control = None;
                // No card is under a pointer that left.
                ws.native_pointer = None;
                ws.card_hover = None;
                ws.card_settle_wake = None;
                if let Some(receipt) = ws.media_paste_receipt.as_mut() {
                    receipt.set_hover(false, std::time::Instant::now());
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            WindowEvent::CursorEntered { .. } => {
                let prev = std::mem::take(&mut ws.detach_drag);
                ws.detach_drag = prev.on_cursor_reenter_window();
                ws.selection_autoscroll_edge = 0;
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            WindowEvent::CursorMoved { position, .. } => {
                ws.cursor = position;
                ws.native_pointer = Some(position);
                ws.selection_autoscroll_edge = 0;
                // A press the lane took owns the pointer's motion until its
                // release: it resizes the lane or pans its item, and nothing
                // else sees it.
                if self.resize_preview_lane(ws) || self.drag_preview_lane(ws) {
                    self.sync_cursor_icon(ws);
                    return;
                }
                self.update_search_hover(ws);
                if ws.selecting {
                    note_selection_drag_motion(ws);
                }
                // Client pointer events do NOT reach the torn window while the
                // OS moves it (Windows: NC modal loop; X11: the WM holds an
                // active pointer grab). The first CursorMoved after movement is
                // therefore the post-drop signal on platforms without Windows'
                // synthesized release (which arrives first there and wins).
                // Guards: a short post-handoff blackout absorbs a stray client
                // motion racing the WM actually taking the grab, and the latch
                // is REVALIDATED against the torn window's final resting
                // position — a WM-cancelled move (Esc) snaps the window back to
                // its origin, where frame+grab no longer hits the latched band,
                // so the cancel abandons instead of committing. Then fall
                // through — this event is real input for the now-free window.
                if let Some(td) = self.torn_drag.as_ref()
                    && td.seq == ws.seq
                    && td.native
                    && td.saw_move
                    && (!td.caption || !primary_button_physically_held())
                    && td.started.elapsed() >= std::time::Duration::from_millis(300)
                {
                    let commit = self.revalidate_dock_latch(ws);
                    self.finalize_torn_drag(ws, commit);
                    // A committed merge empties this window — it is closing;
                    // don't process the event against an empty mux.
                    if self.window_close_pending(ws.seq) {
                        return;
                    }
                }
                // Self-healing demotion. The drag_window() call succeeded as an
                // API call, but the WM never actually took the move (no Moved
                // has arrived) and the capture holder is still streaming
                // motion. An X11 WM that ignores _NET_WM_MOVERESIZE would
                // otherwise leave the torn window frozen mid-air with no path
                // to carry it.
                if let Some(td) = self.torn_drag.as_mut()
                    && td.native
                    && !td.saw_move
                    && td.carrier == ws.seq
                    && td.started.elapsed() >= std::time::Duration::from_millis(400)
                {
                    log::info!("tear-off: WM never took the drag; demoting to manual follow");
                    td.native = false;
                }
                // Manual-follow fallback. The native handoff failed, so the
                // capture holder (the tear's source window, or the dragged
                // window itself for a lone-tab whole-window drag) carries the
                // torn window. Reposition it from this cursor stream and drive
                // the re-dock hit-test. Gated on the CARRIER, so only the
                // capture holder's stream drives the follow. Without the gate,
                // stale tracking would hijack every window's cursor stream and
                // keep refreshing the failsafe forever.
                if self.follow_torn_drag(ws) {
                    return;
                }
                // An editor drag that started inside the search bar keeps the
                // motion; otherwise the grid above the bar stays live for
                // hover, selection, and mouse reporting, matching the ctl path.
                if search_pointer_route(ws.search.open, None, ws.search.pointer_captured())
                    == SearchPointerRoute::Bar
                {
                    self.show_mouse_cursor(ws);
                    self.sync_cursor_icon(ws);
                    self.search_mouse_drag(ws);
                    return;
                }
                // Dragging a split divider — recompute the
                // addressed split's ratio from the cursor and apply. The split
                // rect is re-fetched from the live seams so a mid-drag layout
                // change (a pane elsewhere closing) can't desync the math; if
                // the split has vanished, cancel the drag.
                if ws.dragging_split.is_some() {
                    let (path, dir) = {
                        let d = ws.dragging_split.as_ref().unwrap();
                        (d.path.clone(), d.dir)
                    };
                    let area = self.area(ws);
                    let seams = ws.mux.split_seams(ws.mux.active, area);
                    match seams.iter().find(|s| s.path == path).map(|s| s.rect) {
                        Some(rect) => {
                            let ratio = crate::mux::ratio_from_pos(
                                rect,
                                dir,
                                ws.cursor.x as f32,
                                ws.cursor.y as f32,
                            );
                            ws.mux.set_split_ratio(ws.mux.active, &path, ratio);
                            // The layout-tree
                            // ratio changed, but each pane's PTY grid is resized
                            // only by resize_all (the keyboard resize path reaches
                            // it via handle_action's tail). Without this the child
                            // TUIs keep their old cols/rows — rendering clipped —
                            // until some unrelated event fires a resize.
                            self.resize_all(ws);
                            if let Some(w) = &ws.window {
                                w.set_cursor(Self::resize_cursor_for(dir));
                                w.request_redraw();
                            }
                        }
                        None => ws.dragging_split = None,
                    }
                    return;
                }
                // Any real mouse movement undoes the hide-while-typing
                // state. Sub-pixel movements that winit *might* coalesce
                // are fine to ignore — the next "real" motion will fire.
                self.show_mouse_cursor(ws);
                let media_receipt_hovered = self.update_media_paste_receipt_hover(ws);
                self.sync_cursor_icon_with_media_receipt_hover(ws, media_receipt_hovered);
                // Terminator menu UX, hover-to-highlight: hovering a
                // context-menu row highlights it immediately, matching
                // GTK/NSMenu/Win32 menu conventions.
                if ws.context_menu.is_some() {
                    self.update_menu_highlight_from_cursor(ws);
                }
                // Terminator parity, terminatorlib/config.py:73
                // `focus = sloppy`: focus-follows-mouse. The pane
                // under the cursor becomes focused on every cursor
                // movement (vs default `click` mode where click is
                // required). `system` is treated like `click` for
                // kettle — winit doesn't expose the OS-level focus
                // policy.
                if matches!(self.cfg.focus, kettle_config::FocusMode::Sloppy)
                    && !ws.tab_drag_active
                    && !ws.selecting
                    && ws.scrollbar_drag_offset.is_none()
                    // Don't let focus-follows-mouse
                    // reassign pane focus while a modal is open — typing into
                    // search/palette while the cursor drifts over another pane
                    // would otherwise silently steal focus.
                    && !self.any_modal_open(ws)
                {
                    let area = self.area(ws);
                    let pre = self.focus_key(ws);
                    ws.mux
                        .focus_at(area, ws.cursor.x as f32, ws.cursor.y as f32);
                    self.note_focus_change(ws, pre);
                }
                // Drag-to-reorder tabs (kitty / iTerm2 /
                // Ghostty parity). When a left-button press in the tab
                // bar armed `tab_drag_active`, walk the bar geometry,
                // compute the target index under the cursor, and swap
                // the active tab toward it via `move_active_tab`
                // (the pure swap-with-clamp helper).
                // Horizontal bars only. Mapping cursor.x onto a vertically
                // stacked strip would silently shuffle tabs during any drag
                // (vertical drag-reorder remains deferred).
                if let Some((ox, oy)) = ws.tab_drag_press {
                    let dx = ws.cursor.x as f32 - ox;
                    let dy = ws.cursor.y as f32 - oy;
                    if (dx * dx + dy * dy).sqrt()
                        > tab_reorder_drag_threshold_px(self.tab_bar_h(ws))
                    {
                        ws.tab_drag_press = None;
                        ws.tab_pressed_idx = None;
                    }
                }
                if ws.tab_drag_active
                    && ws.tab_drag_press.is_none()
                    && !self.cfg.tab_bar_pos.is_vertical()
                {
                    let bar = self.tab_bar(ws);
                    if bar.height > 0.0 && !bar.segments.is_empty() {
                        // Use the same rendered segment
                        // rects that click hit-testing and painting use.
                        let target = tab_drag_target_index(
                            ws.cursor.x as f32,
                            ws.cursor.y as f32,
                            &bar.segments,
                        );
                        let delta = target as i32 - ws.mux.active as i32;
                        if delta != 0 && ws.mux.move_active_tab(delta) {
                            ws.mux.touch_active_tab_seen();
                            if let Some(w) = &ws.window {
                                w.request_redraw();
                            }
                        }
                    }
                }
                // Terminator parity: a titlebar press that has since moved far
                // enough is a pane drag. Recompute the drop target every move
                // from the CURRENT layout rather than caching it at press time
                // — a pane closing mid-drag reshuffles every rect, and a stale
                // target would highlight a pane that is no longer there.
                if ws.pane_drag.is_some() {
                    let area = self.area(ws);
                    let (cx, cy) = (ws.cursor.x as f32, ws.cursor.y as f32);
                    let (ox, oy) = ws.pane_drag.as_ref().map(|d| d.origin).unwrap_or((cx, cy));
                    let (dx, dy) = (cx - ox, cy - oy);
                    let live = ws.pane_drag.as_ref().is_some_and(|d| d.live)
                        || (dx * dx + dy * dy).sqrt() > PANE_DRAG_THRESHOLD_PX;
                    let moving = ws.pane_drag.as_ref().map(|d| d.pane);
                    // Computed before the &mut borrow below: `pane_rect_at`
                    // needs `&ws.mux` and the write needs `&mut ws.pane_drag`.
                    let target = if live {
                        ws.mux.pane_rect_at(area, cx, cy).and_then(|(id, rect)| {
                            // A pane cannot be dropped onto itself: the tree
                            // half refuses it, so offering the hint would
                            // promise a move that never happens.
                            (Some(id) != moving)
                                .then(|| {
                                    crate::mux::pane_drop_zone(rect, cx, cy)
                                        .map(|(dir, before)| (id, rect, dir, before))
                                })
                                .flatten()
                        })
                    } else {
                        None
                    };
                    if let Some(drag) = ws.pane_drag.as_mut() {
                        let changed = drag.live != live
                            || drag.target.map(|t| t.0) != target.map(|t| t.0)
                            || drag.target.map(|t| (t.2, t.3)) != target.map(|t| (t.2, t.3));
                        drag.live = live;
                        drag.target = target;
                        if changed && let Some(w) = &ws.window {
                            w.request_redraw();
                        }
                    }
                }
                // Drive the detach FSM from the press origin.
                // Distance decides click-vs-drag; WINDOW-BOUNDS CONTAINMENT
                // decides inside/outside — Windows' SetCapture keeps
                // streaming CursorMoved (with out-of-client coordinates)
                // while the button is held but suppresses CursorLeft, so
                // position is the reliable outside signal. The
                // CursorLeft/Entered arms above remain as supplementary
                // signals for platforms that do deliver them mid-drag.
                if let Some((ox, oy)) = ws.drag_press {
                    let (cx, cy) = (ws.cursor.x as f32, ws.cursor.y as f32);
                    let next = std::mem::take(&mut ws.detach_drag).on_mouse_move(cx - ox, cy - oy);
                    let (sw, sh) = ws
                        .renderer
                        .as_ref()
                        .map(|r| {
                            let (w, h) = r.surface_size();
                            (w as f32, h as f32)
                        })
                        .unwrap_or((800.0, 600.0));
                    let outside = cx < 0.0 || cy < 0.0 || cx >= sw || cy >= sh;
                    ws.detach_drag = if outside {
                        next.on_cursor_leave_window()
                    } else {
                        next.on_cursor_reenter_window()
                    };
                    // Tear the moment the cursor crosses the band threshold,
                    // not at release (Chromium-style). The torn window appears
                    // live under the cursor and rides the OS move loop from
                    // here.
                    if self.maybe_tear_off(ws, event_loop) {
                        return;
                    }
                }
                {
                    // Motion. `MOUSE_NO_BUTTON` is xterm's code 3, which with
                    // the motion bit is the `CSI < 35 ; x ; y M` report DEC
                    // 1003 exists to deliver; `send_mouse` decides per mode
                    // whether this motion is reportable at all, so 1002 still
                    // needs a held button and 1000 still gets nothing.
                    if self.send_mouse(ws, input::MOUSE_NO_BUTTON, true, true) {
                        return;
                    }
                }
                if let Some(grab) = ws.scrollbar_drag_offset {
                    let area = self.area(ws);
                    let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                    self.scrollbar_at(ws, area, px, py, false, Some(grab));
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Overlay-scrollbar hover-brighten. Update the focused
                // pane's hover flag and repaint only on the enter/leave edge so it
                // costs nothing while the pointer is elsewhere.
                {
                    let area = self.area(ws);
                    let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                    let hover = self.scrollbar_zone_contains(ws, area, px, py);
                    if hover != ws.scrollbar_hover {
                        ws.scrollbar_hover = hover;
                        if let Some(w) = &ws.window {
                            w.request_redraw();
                        }
                    }
                }
                if ws.selecting {
                    let area = self.area(ws);
                    self.update_selection(ws, area);
                }
                if (ws.selecting || !ws.links.is_empty())
                    && let Some(w) = &ws.window
                {
                    w.request_redraw();
                }
            }
            WindowEvent::MouseInput {
                state: ElementState::Pressed,
                button,
                ..
            } => {
                ws.resume_native_pointer();
                // A fresh press while torn-drag tracking is live. For a NATIVE
                // drag any client press means the tracking is stale (the OS
                // modal loop / WM grab swallows presses mid-drag) — abandon,
                // never merge on a click. A LEFT press during manual-follow is
                // equally impossible mid-gesture (left is held the whole
                // drag) — stale, abandon. But an OTHER-button press routed to
                // the manual-follow capture holder is live mid-drag input:
                // swallow it (Chromium swallows stray presses during a tab
                // drag) instead of killing the gesture.
                if let Some(td) = self.torn_drag.as_ref() {
                    if td.native || button == MouseButton::Left {
                        self.finalize_torn_drag(ws, false);
                    } else if td.carrier == ws.seq {
                        return;
                    }
                }
                // Forward Back / Forward (buttons 8 / 9) to a mouse-tracking
                // app rather than dropping them. No local UI meaning, so they
                // no-op when tracking is off. The same `modal_swallows_pointer`
                // gate as L/M/R + wheel keeps SGR out of a tracking TUI
                // *behind* a palette/settings/… dialog. A lone context menu
                // isn't a modal here.
                // A press of any button is the pointer's: focus is no longer
                // on a card.
                if ws.card_focus.take().is_some() {
                    ws.accessibility_pending = true;
                }
                if let Some(sgr) = extra_mouse_sgr(button) {
                    // Any press ends a lane's drag or edge drag, as below.
                    self.end_lane_resize(ws);
                    ws.lane_drag = None;
                    // One away from a lane holding the keyboard gives it back.
                    self.leave_preview_focus_for_press(ws);
                    // A press of a button still noted as held means its
                    // release went elsewhere: its program gets it now. The
                    // press is Kettle's until a program receives it.
                    self.release_held_buttons(ws, |held| held.button == sgr);
                    ws.held_buttons.pressed(sgr, None, (0, 0));
                    if self.confirm_mouse_press(ws, event_loop, sgr) {
                        return;
                    }
                    // A lone context menu must swallow the side-button press
                    // too. Dismiss the menu and DON'T forward.
                    // `modal_swallows_pointer` returns false for a lone menu,
                    // so without this a Back/Forward click would leak SGR to
                    // the tracking app *behind* the menu AND leave the menu
                    // open (every other button dismisses it).
                    if ws.context_menu.is_some() {
                        ws.context_menu = None;
                        if let Some(w) = &ws.window {
                            w.request_redraw();
                        }
                        return;
                    }
                    // A preview lane owns every press over it; a side button
                    // does nothing there.
                    let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                    if !self.press_preview_lane(ws, px, py, sgr)
                        && !modal_swallows_pointer(
                            self.pointer_modal_open(ws),
                            ws.context_menu.is_some(),
                        )
                    {
                        self.report_mouse(ws, sgr, true, false);
                    }
                    return;
                }
                let bcode = match button {
                    MouseButton::Left => 0,
                    MouseButton::Middle => 1,
                    MouseButton::Right => 2,
                    _ => return,
                };
                // Any press while a lane's drag is held means that drag's
                // release went elsewhere, or another gesture takes the
                // pointer: the drag is over. Likewise a primary press while a
                // card still holds one: the card's gesture is over.
                self.end_lane_resize(ws);
                ws.lane_drag = None;
                self.leave_preview_focus_for_press(ws);
                if bcode == 0 {
                    ws.card_press = None;
                }
                // Likewise a program still noted as holding this button gets
                // the release it missed, and the press is Kettle's own
                // gesture until a program receives it.
                self.release_held_buttons(ws, |held| held.button == bcode);
                ws.held_buttons.pressed(bcode, None, (0, 0));
                if self.confirm_mouse_press(ws, event_loop, bcode) {
                    return;
                }
                // Context menu: if the menu is open, a left-click
                // either fires the row that was hit or — if the click landed
                // outside the panel — closes the menu. Middle-click outside
                // dismisses too; only right-click falls through so it can
                // reopen/relocate the menu.
                if ws.context_menu.is_some()
                    && let Some(click) = self.context_menu_click_action(ws, bcode)
                {
                    // Route through the shared sink. It closes the menu per
                    // leaf and keeps it open for DrillIntoSubmenu, so clearing
                    // `ws.context_menu` before the dispatch would turn submenu
                    // clicks into plain dismissals.
                    self.dispatch_context_menu_click(ws, click, event_loop);
                    return;
                }
                if ws.context_menu.is_some() && bcode != 2 {
                    // Left/middle outside the panel — dismiss without firing
                    // anything (matches every modern menu).
                    ws.context_menu = None;
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Search controls are real click targets inside the reserved
                // lane; every button inside the lane stays there. A press above
                // the lane is ordinary grid input: the bar is not an overlay,
                // so selecting, opening links, and mouse reporting keep working
                // while a query is being typed (Terminator parity).
                if search_pointer_route(
                    ws.search.open,
                    Some(self.cursor_in_search_bar(ws)),
                    ws.search.dragging_editor,
                ) == SearchPointerRoute::Bar
                {
                    if bcode == 0 {
                        self.search_mouse_press(ws);
                        if let Some(window) = &ws.window {
                            window.request_redraw();
                        }
                    }
                    return;
                }
                // The settings overlay is mouse-driven (click-to-cycle).
                // Left-click a field cycles its value forward, right-click
                // backward; clicking a category tab switches category; a click
                // outside the panel closes settings. Handled before the generic
                // modal swallow below so the click actually does something.
                if ws.settings_nav.is_some()
                    && (bcode == 0 || bcode == 2)
                    && self.settings_mouse(ws, if bcode == 2 { -1 } else { 1 }, true)
                {
                    return;
                }
                // With any *other* modal open
                // (palette / ssh / settings / layout-picker / hint / confirm
                // dialog / inline title-edit / vi copy-mode) the click must be
                // consumed. Otherwise it falls through to the
                // tab-bar / pane-focus / mouse-tracking logic below, switching
                // tabs and injecting mouse events into the terminal *behind* a
                // dialog that looks like it has focus. The context menu is
                // excluded (handled + returned above; a right-click below
                // relocates it), and so is the search bar, whose lane was
                // routed above and whose grid stays live.
                if ws.preview_overlay.is_some() && !self.non_search_modal_open(ws) {
                    self.press_preview_lane(ws, ws.cursor.x as f32, ws.cursor.y as f32, bcode);
                    return;
                }
                if modal_swallows_pointer(self.pointer_modal_open(ws), ws.context_menu.is_some()) {
                    return;
                }
                let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                // A preview lane owns every press over it, so the terminal
                // beside it never gets one.
                if self.press_preview_lane(ws, px, py, bcode) {
                    return;
                }
                // An inline card takes a primary press before anything else
                // in the window does; its release opens the card's item.
                if self.press_card(ws, px, py, bcode) {
                    return;
                }
                // Tab-bar interactions (left = switch / close-✕ / new-+;
                // middle = close that tab).
                let bar = self.tab_bar(ws);
                // The update banner is the bottom bar when shown.
                // Left-click opens the release page (+ records the dismissal so
                // it won't re-nag); right-click dismisses without opening. Only
                // reachable with no modal open (the gate above returned for
                // those) — exactly when the banner is actually on screen.
                if let Some((bx, by, bw, bh)) = self.update_banner_rect(ws)
                    && px >= bx
                    && px < bx + bw
                    && py >= by
                    && py < by + bh
                    && (bcode == 0 || bcode == 2)
                {
                    // Left-click opens + dismisses; right-click only
                    // dismisses. Shared with the keyboard `OpenUpdate` /
                    // `DismissUpdate` actions.
                    self.act_on_update_banner(ws, bcode == 0);
                    return;
                }
                let in_bar = |r: kettle_render::Rect4, px: f32, py: f32| {
                    px >= r.0 && px < r.0 + r.2 && py >= r.1 && py < r.1 + r.3
                };
                if tab_bar_pointer_region_contains(&bar, px, py) && (bcode == 0 || bcode == 1) {
                    if bcode == 0 && bar.new_tab_menu.2 > 0.0 && in_bar(bar.new_tab_menu, px, py) {
                        // The `▾` dropdown — open the shell chooser
                        // anchored at the arrow's bottom-left. Checked BEFORE the
                        // `+` so the arrow region isn't swallowed by the button.
                        let (ax, ay, _, ah) = bar.new_tab_menu;
                        self.open_new_tab_menu(ws, ax, ay + ah);
                    } else if bcode == 0 && in_bar(bar.new_tab, px, py) {
                        let area = self.area(ws);
                        let (cols, rows) = self.grid_of(ws, area);
                        let geometry = self.pty_geometry_for_grid(ws, cols, rows);
                        // Log a `+`-button new-tab spawn failure rather than
                        // swallowing it, and fire TabAdd on success so Lua
                        // `TabAdd` and dev-record see the new tab.
                        match ws.mux.new_tab_geometry(&self.cfg, geometry, self.waker()) {
                            Ok(()) => self.fire_tab_add_event(ws),
                            Err(e) => log::warn!("could not open a new tab (+ button): {e}"),
                        }
                    } else if bcode == 0
                        && bar.scroll_left.2 > 0.0
                        && in_bar(bar.scroll_left, px, py)
                    {
                        // `‹` overflow arrow — step to an earlier tab
                        // (scrolls it into view via tab_strip_layout).
                        ws.mux.prev_tab();
                    } else if bcode == 0
                        && bar.scroll_right.2 > 0.0
                        && in_bar(bar.scroll_right, px, py)
                    {
                        ws.mux.next_tab();
                    } else if let Some(seg) = bar.segments.iter().find(|s| in_bar(s.rect, px, py)) {
                        let close = bcode == 1 || in_bar(seg.close, px, py);
                        if close {
                            // Both gestures that land here — the ✕ button and
                            // middle-click — destroy as much as
                            // `Action::CloseTab` and so must ask the same
                            // question. They can also target a tab that is NOT
                            // the focused one, so the prompt names the tab by a
                            // pane it holds rather than by the focused index.
                            let (panes, busy) = tab_close_scope(ws, seg.idx);
                            if let Some(anchor) =
                                Some(ws.mux.tab_anchor_panes(seg.idx)).filter(|a| !a.is_empty())
                                && self.confirm_close(
                                    ws,
                                    self.ui_text.confirm_close_tab(panes as u64),
                                    panes,
                                    busy,
                                    ConfirmAction::CloseTabHolding(anchor),
                                )
                            {
                                return;
                            }
                            // Closing a tab (middle-click or
                            // ✕) can shift focus to a different tab
                            // (`reap_tabs`'s bookkeeping).
                            // Treat it like any other focus-changing
                            // action so the cursor on the now-active
                            // tab lands visible immediately.
                            let pre = self.focus_key(ws);
                            // Fire TabClose so plugins see
                            // the ✕-click close the same as Action::CloseTab.
                            let closing_idx = seg.idx;
                            if ws.mux.close_tab_at(seg.idx) {
                                // Save the (empty) session
                                // before exit so next launch starts
                                // fresh rather than restoring the
                                // *previous* multi-tab state. Other
                                // exit paths (Action::CloseTab on the
                                // last tab, WindowEvent::CloseRequested)
                                // save too.
                                self.fire_tab_close_event(ws, closing_idx);
                                self.save_session(ws);
                                self.request_window_close(ws.seq);
                                return;
                            }
                            self.fire_tab_close_event(ws, closing_idx);
                            self.note_focus_change(ws, pre);
                        } else {
                            let pre = self.focus_key(ws);
                            ws.mux.active = seg.idx;
                            ws.mux.touch_active_tab_seen();
                            self.note_focus_change(ws, pre);
                            // Arm the drag-to-reorder
                            // handler so a subsequent CursorMoved
                            // event with the left button still held
                            // can swap the active tab toward the
                            // cursor. Cleared in the Released arm
                            // below. Only on bare left-click (bcode 0
                            // == left, not middle / close).
                            if bcode == 0 {
                                ws.tab_drag_active = true;
                                ws.tab_drag_press = Some((px, py));
                                ws.tab_pressed_idx = Some(seg.idx);
                                // Arm the detach FSM alongside the in-window
                                // reorder, for a LONE tab too. Dragging it past
                                // the band threshold moves the whole window
                                // (Chromium semantics), which is how a torn-off
                                // window re-docks into a sibling.
                                if self.cfg.detachable_tabs {
                                    ws.detach_drag =
                                        crate::detach::DragState::on_mouse_down_on_tab(seg.idx);
                                    ws.drag_press = Some((px, py));
                                } else {
                                    ws.detach_drag = crate::detach::DragState::default();
                                    ws.drag_press = None;
                                }
                            }
                        }
                    }
                    self.resize_all(ws);
                    if let Some(win) = &ws.window {
                        win.request_redraw();
                    }
                    return;
                }
                let area = self.area(ws);
                // The receipt is chrome over terminal cells. The primary
                // button acts; every other button is consumed without acting
                // so hidden terminal content cannot receive the press.
                if self.activate_media_paste_receipt_at(ws, px, py, bcode) {
                    return;
                }
                // The detached card covers terminal cells but is not a shell
                // editor. A press dismisses it and stops here so selecting text,
                // opening a link, or forwarding mouse tracking cannot act on
                // content the card hid.
                let completion_hit = {
                    let overlay = self.overlay(ws, true);
                    completion_overlay_hit_test(
                        overlay.completion.as_ref(),
                        self.menu_cell(ws),
                        (px, py),
                    )
                };
                if completion_hit {
                    if let Some(pane_id) = ws.mux.active_focus()
                        && let Some(pane) = ws.mux.panes.get(&pane_id)
                    {
                        pane.term.clear_completion();
                    }
                    if let Some(window) = &ws.window {
                        window.request_redraw();
                    }
                    return;
                }
                // Ctrl/Cmd + left-click opens a hyperlink under the cursor.
                //
                // Terminator parity, terminatorlib/config.py:120
                // `link_single_click`: when true, single-click (no
                // modifier) is enough to open URLs. Default keeps
                // kettle's Ctrl-click guard so accidental drags don't
                // navigate.
                let url_modifier =
                    self.cfg.link_single_click || ws.mods.control_key() || ws.mods.super_key();
                if bcode == 0
                    && url_modifier
                    && let Some(uri) = self.link_at_cursor(ws).map(|l| l.uri.clone())
                {
                    // Route through helper so the pane's origin and the custom
                    // URL handler config are honored.
                    self.open_pane_link(ws, links_pane(ws), &uri);
                    return;
                }
                // As in Terminator, a left-click on a pane titlebar focuses the
                // pane, and a second click opens the EditPaneTitle overlay. The
                // two-click model (focus first, edit second) avoids accidental
                // title edits on focus transitions.
                //
                // The titlebar is also the grab handle for dragging the pane
                // elsewhere in the tab, so the press only FOCUSES and arms the
                // gesture; the release decides between editing the title and
                // moving the pane. Opening the editor on press would put a text
                // field over the pane the user just picked up.
                let (cx, cy) = (ws.cursor.x as f32, ws.cursor.y as f32);
                if bcode == 0
                    && let Some(clicked_pane_id) = self.pane_at_titlebar_click(ws, cx, cy)
                {
                    let already_focused = ws.mux.active_focus() == Some(clicked_pane_id);
                    let pre = self.focus_key(ws);
                    ws.mux.focus_at(area, cx, cy);
                    self.note_focus_change(ws, pre);
                    ws.pane_drag = Some(PaneDrag {
                        pane: clicked_pane_id,
                        origin: (cx, cy),
                        live: false,
                        rename_on_click: already_focused,
                        target: None,
                    });
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // A left-press on a split divider seam starts
                // a drag-to-resize gesture rather than focusing a pane / starting
                // a selection. Seams are hit-tested over the same content `area`
                // the panes lay out in, with a small grab tolerance.
                if bcode == 0
                    && let Some(drag) = self.split_drag_at(ws, area, px, py)
                {
                    let dir = drag.dir;
                    ws.dragging_split = Some(drag);
                    if let Some(w) = &ws.window {
                        w.set_cursor(Self::resize_cursor_for(dir));
                        w.request_redraw();
                    }
                    return;
                }
                let pre = self.focus_key(ws);
                ws.mux
                    .focus_at(area, ws.cursor.x as f32, ws.cursor.y as f32);
                self.note_focus_change(ws, pre);
                if self.send_mouse(ws, bcode, true, false) {
                    return;
                }
                // Middle-click in the content area pastes the PRIMARY
                // selection when the platform exposes one; otherwise it falls
                // back to the regular clipboard.
                //
                // Mirrors Terminator's `disable_mouse_paste`
                // (terminatorlib/config.py:88): when true, middle-click does
                // not paste. Useful for terminal-of-last-resort use
                // cases where accidental middle-clicks shouldn't leak
                // clipboard content into commands.
                if bcode == 1 && !self.cfg.disable_mouse_paste {
                    self.paste_primary(ws);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Mirrors Terminator's `putty_paste_style`
                // (terminatorlib/config.py:89): right-click pastes (PuTTY/Windows
                // convention) instead of opening the context menu. The
                // companion `putty_paste_style_source_clipboard` decides
                // whether the source is CLIPBOARD or PRIMARY.
                if bcode == 2 && self.cfg.putty_paste_style {
                    match putty_paste_source(self.cfg.putty_paste_style_source_clipboard) {
                        PasteSource::Clipboard => self.paste_clipboard(ws),
                        PasteSource::Primary => self.paste_primary(ws),
                    }
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Click the scrollbar to jump the viewport, then drag it.
                // Keep this behind pane gestures and terminal mouse reporting;
                // the receipt excludes the same gutter in its own hit test.
                if bcode == 0
                    && let Some(grab) = self.scrollbar_jump(ws, area, px, py)
                {
                    ws.scrollbar_drag_offset = Some(grab);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Right-click handling, layered:
                //
                // 1. `Shift + right-click` *with* selected text, off it, keeps
                //    the extend-selection behavior (xterm convention; muscle
                //    memory for kettle's power users).
                // 2. Any other right-click opens the context menu at the
                //    click point (Terminator / GNOME / iTerm2 default),
                //    Shift+right-click on the selection or with nothing
                //    selected included, so its rows can act on them.
                //
                // Mouse-tracking already short-circuited above when the
                // focused program is consuming mouse events, so this only
                // fires for the kettle chrome; Shift bypasses tracking, so
                // Shift+right-click always reaches it.
                if bcode == 2 {
                    if ws.mods.shift_key()
                        && self.pointer_on_selection(ws, area) == Some(false)
                        && self.extend_selection_to_cursor(ws, area, bcode)
                    {
                        if self.cfg.copy_on_select {
                            self.copy_selection(ws);
                        }
                        if let Some(w) = &ws.window {
                            w.request_redraw();
                        }
                        return;
                    }
                    let offer_copied = ws.mods.shift_key();
                    self.open_context_menu(ws, px, py, offer_copied);
                    return;
                }
                if bcode == 0 {
                    self.begin_or_extend_mouse_selection(ws, area);
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            WindowEvent::MouseInput {
                state: ElementState::Released,
                button,
                ..
            } => {
                ws.resume_native_pointer();
                // Release report for the side buttons, so a tracking app sees
                // the matching button-up after the press. Only a press the
                // app saw gets one: a press that a context menu, a modal or
                // the media viewer took leaves no release behind, even when
                // that surface closed while the button was held.
                if let Some(sgr) = extra_mouse_sgr(button) {
                    ws.held_buttons.end_own(sgr);
                    self.send_mouse(ws, sgr, false, false);
                    return;
                }
                let bcode = match button {
                    MouseButton::Left => 0,
                    MouseButton::Middle => 1,
                    MouseButton::Right => 2,
                    _ => return,
                };
                // A gesture of Kettle's own ends with this release, whichever
                // handler below takes it; a program's goes on to get its
                // release from `report_mouse`.
                ws.held_buttons.end_own(bcode);
                // A release ends an editor drag inside the search bar; any
                // other release while the bar is open belongs to the grid
                // gesture it started (selection end, copy-on-select, mouse
                // reporting), like the ctl path.
                if bcode == 0
                    && search_pointer_route(ws.search.open, None, ws.search.pointer_captured())
                        == SearchPointerRoute::Bar
                {
                    ws.search.dragging_editor = false;
                    self.search_button_release(ws);
                    return;
                }
                // The release of a press a lane took is the lane's.
                if bcode == 0 && ws.lane_resize.is_some() {
                    self.end_lane_resize(ws);
                    self.sync_cursor_icon(ws);
                    return;
                }
                if bcode == 0
                    && let Some(drag) = ws.lane_drag.take()
                {
                    self.end_lane_drag(ws, drag);
                    self.sync_cursor_icon(ws);
                    return;
                }
                // The release of a press a card took is the card's too.
                let (px, py) = (ws.cursor.x as f32, ws.cursor.y as f32);
                if self.release_card(ws, px, py, bcode) {
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Terminator parity: the release is where a titlebar press
                // finally means something. Moved past the slop -> move the pane
                // to the latched drop target; never moved -> the
                // second-click-renames behaviour the press deferred.
                //
                // FIRST among the left-release handlers, ahead of the tear-off
                // and mouse-reporting branches that can return early. Those are
                // all mutually exclusive with a pane drag today -- the titlebar
                // press returns before any button is noted as held -- but "today"
                // is exactly the kind of reasoning that leaves a gesture armed
                // when one of them grows a new early return.
                if bcode == 0
                    && let Some(drag) = ws.pane_drag.take()
                {
                    if drag.live {
                        if let Some((target, _, dir, before)) = drag.target
                            && ws.mux.move_pane_beside(drag.pane, target, dir, before)
                        {
                            // Same two follow-ups every tree edit needs:
                            // re-size every PTY to its new rect, and persist the
                            // layout so a restore brings the pane back where the
                            // user put it.
                            self.resize_all(ws);
                            self.save_session(ws);
                        }
                    } else if drag.rename_on_click {
                        self.handle_action(ws, Action::EditPaneTitle, event_loop);
                    }
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
                // A left-release while a torn window is tracked is the DROP.
                // Two shapes: (a) the synthesized release winit posts to the
                // TORN window when the Windows modal move loop exits
                // (WM_EXITSIZEMOVE → WM_LBUTTONUP — verified in the vendored
                // 0.30.13 source); (b) the real release on the capture-holding
                // SOURCE in manual-follow. Commit the latched dock either way.
                // A left-release on an unrelated window while tracking is live
                // means the tracking went stale (an X11 drop we never
                // observed) — abandon it and process the release normally.
                //
                // Esc-cancel guard: WM_EXITSIZEMOVE
                // fires for EVERY modal-loop exit — Esc-cancel included —
                // and the synthesized release is indistinguishable from a
                // drop, while the latch survives the snap-back (the live
                // cursor is still over the band). The tell is PHYSICAL
                // button state: an Esc-cancel exits the loop with the
                // primary button still held; a real drop only exits after
                // it went up. Held ⇒ abandon (the user's real release later
                // arrives with tracking already cleared and flows through
                // normal processing harmlessly).
                if bcode == 0
                    && let Some(td) = self.torn_drag.as_ref()
                {
                    if td.seq == ws.seq || !td.native {
                        let commit = !primary_button_physically_held();
                        let commit = commit && (!td.caption || self.revalidate_dock_latch(ws));
                        self.finalize_torn_drag(ws, commit);
                        return;
                    }
                    self.finalize_torn_drag(ws, false);
                }
                // The release goes where its press did, if a program got it.
                if self.send_mouse(ws, bcode, false, false) {
                    return;
                }
                if selection_release_matches(ws.selection_button, bcode) {
                    self.finish_selection_gesture(ws);
                }
                if bcode == 0 {
                    ws.search.dragging_editor = false;
                    ws.scrollbar_drag_offset = None;
                    // End any split-divider drag on left-button up.
                    ws.dragging_split = None;
                    // End the drag-to-reorder gesture on
                    // left-button release. Any swaps that happened
                    // during the drag are already committed; this just
                    // disarms the CursorMoved handler.
                    ws.tab_drag_active = false;
                    ws.tab_drag_press = None;
                    ws.tab_pressed_idx = None;
                    // On Wayland only, a release while the detach FSM is
                    // OUTSIDE the window tears the dragged tab off into a new
                    // window. Everywhere else the tear fires the moment the
                    // cursor crosses the band threshold (`maybe_tear_off`), so
                    // the FSM is already Idle by release, and a release still
                    // inside the hysteresis slop deliberately does NOT tear
                    // (Chromium's within-slop = click/reorder semantics).
                    // Wayland can't position windows client-side nor hand off a
                    // drag to a surface that never saw the press, so it keeps
                    // the at-release tear.
                    let dropped_outside = matches!(
                        ws.detach_drag,
                        crate::detach::DragState::DraggingOutside { .. }
                    );
                    ws.detach_drag = std::mem::take(&mut ws.detach_drag).on_mouse_up();
                    ws.drag_press = None;
                    let wayland = ws.window.as_deref().is_some_and(window_is_wayland);
                    if self.cfg.detachable_tabs
                        && dropped_outside
                        && wayland
                        && ws.mux.tabs.len() > 1
                    {
                        let closing_idx = ws.mux.active;
                        self.release_held_buttons_in_tab(ws, closing_idx);
                        if let Some(dt) = ws.mux.detach_tab(closing_idx) {
                            // `outer_position` errs on Wayland — `None` lets
                            // the compositor place the window.
                            let pos = ws
                                .window
                                .as_ref()
                                .and_then(|w| w.outer_position().ok())
                                .map(|p| {
                                    winit::dpi::PhysicalPosition::new(
                                        p.x + ws.cursor.x as i32,
                                        p.y + ws.cursor.y as i32,
                                    )
                                    .into()
                                });
                            self.release_focus_report_to(ws, &dt);
                            let paste =
                                ws.take_moved_paste_state(&dt.tab, std::time::Instant::now());
                            match self
                                .open_window(
                                    event_loop,
                                    WindowOpen::AdoptTab {
                                        tab: dt,
                                        source_color: self.tear_off_source_color(ws),
                                        paste: Box::new(paste),
                                    },
                                    pos,
                                    None,
                                )
                                .map_err(|open| *open)
                            {
                                Ok(torn_seq) => {
                                    self.fire_tab_close_event(ws, closing_idx);
                                    // Agents see the tear-off too.
                                    self.ctl_broadcast(
                                        "tab_moved",
                                        None,
                                        serde_json::json!({
                                            "from_window": ws.seq,
                                            "to_window": torn_seq,
                                            "tab": closing_idx,
                                        }),
                                    );
                                    self.resize_all(ws);
                                    if let Some(w) = &ws.window {
                                        w.request_redraw();
                                    }
                                }
                                Err(WindowOpen::AdoptTab { tab: dt, paste, .. }) => {
                                    log::warn!(
                                        "tear-off: open_window failed; tab kept in source window"
                                    );
                                    ws.mux.attach_tab(dt, Some(closing_idx));
                                    ws.restore_moved_paste_state(*paste);
                                }
                                Err(_) => {
                                    unreachable!("open_window returns the WindowOpen it was given")
                                }
                            }
                        }
                    }
                }
            }
            // A pinch over a preview lane zooms its rendered item at the
            // pointer; anywhere else it does nothing.
            WindowEvent::PinchGesture { delta, .. } => {
                ws.resume_native_pointer();
                if self.lane_takes_wheel(ws) {
                    self.pinch_over_lane(ws, delta);
                }
            }
            WindowEvent::MouseWheel { delta, phase, .. } => {
                ws.resume_native_pointer();
                // A gesture ending (macOS momentum scroll, and any backend that
                // reports phases) drops leftover sub-detent residue so a partial
                // step can't leak into the next, unrelated gesture.
                if matches!(
                    phase,
                    winit::event::TouchPhase::Ended | winit::event::TouchPhase::Cancelled
                ) {
                    ws.wheel.reset();
                    ws.lane_wheel.reset();
                }
                // A preview lane owns the wheel over it. Its motion is dropped
                // from the terminal's account rather than banked there, so no
                // part of it reaches the terminal once the lane closes; the
                // lane keeps its own, to scroll a source. Motion over the
                // terminal is dropped from the lane's the same way.
                if self.lane_takes_wheel(ws) {
                    ws.wheel.reset();
                    self.wheel_over_lane(ws, &delta);
                    return;
                }
                ws.lane_wheel.reset();
                let steps = ws.wheel.feed(&delta, self.cfg.scroll_multiplier);
                // Numbers only — never terminal content. Makes the
                // precision-touchpad class of bug diagnosable from a user's
                // `RUST_LOG=debug` run instead of requiring a custom build.
                log::debug!(
                    "wheel: delta={delta:?} phase={phase:?} -> notches={} lines={} cols={}",
                    steps.notches,
                    steps.lines,
                    steps.cols
                );
                if steps.is_zero() {
                    // Motion too small to move anything yet — it is banked in
                    // `ws.wheel`, not discarded.
                    return;
                }
                self.dispatch_wheel(ws, steps);
            }
            WindowEvent::DroppedFile(path) => {
                // A drop is the pointer's, as a press elsewhere: the keyboard
                // goes back to the terminal first.
                self.exit_preview_focus(ws);
                // A file dropped while a modal (search /
                // palette / settings / confirm dialog / inline title-edit / vi
                // copy-mode / …) is open must NOT inject its path into the PTY
                // behind the dialog — the same pointer-leak class
                // `modal_swallows_pointer` already closes for clicks. Unlike
                // that gate, an open context menu blocks the drop too.
                if self.any_modal_open(ws) {
                    return;
                }
                // Insert a shell-quoted path plus a trailing space. The shared
                // paste path preserves bracketed paste, per-pane shell
                // formatting, broadcast scope, and WSL translation.
                let paths = vec![path];
                let video = self.cfg.paste_video_preview.then(|| {
                    crate::video_preview::VideoPasteRequest::from_user_paths(
                        &paths,
                        crate::video_preview::VideoPasteSource::Drop,
                    )
                });
                self.paste_paths(ws, paths, true, video.flatten());
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            WindowEvent::Focused(f) => {
                ws.window_focused = f;
                ws.os_focus_known = true;
                if f {
                    ws.frame_recovery.expedite(std::time::Instant::now());
                }
                // Track the OS focus in `focused_seq` so window-less events
                // (RemoteCommand, ctl "focused-window" ops, the UpdateAvailable
                // banner) and the agent-facing focused_window/to_window JSON
                // route to the window the user actually clicked — not whichever
                // window was last opened or ctl-focused. `ws.seq` is this
                // window's BTreeMap key; finish_window_dispatch re-inserts it
                // after dispatch.
                if f {
                    self.focused_seq = ws.seq;
                }
                if !f {
                    // An unfocused window draws no cursor, and the Metal layer
                    // beneath already shows the off phase.
                    Self::hide_cursor_layer(ws);
                    // Its release may never come here.
                    ws.lane_drag = None;
                    self.end_lane_resize(ws);
                    // The keyboard goes back to the terminal.
                    self.exit_preview_focus(ws);
                }
                // Non-interactive UI-state marker (OS-driven focus
                // change — a transition the PTY output stream can't show).
                if let Some(rec) = self.recorder.as_mut() {
                    rec.record_marker(if f {
                        "kettle:focus_in"
                    } else {
                        "kettle:focus_out"
                    });
                }
                // Broadcast Tab arms every target pane, including named-group
                // targets in other windows. Disarm the whole in-process fleet
                // together so a reply buffered before this focus boundary
                // cannot reopen when any sibling is focused later. The next
                // Tab explicitly arms a fresh generation.
                let completion_panes = ws.mux.panes.values().chain(
                    self.windows
                        .values()
                        .flat_map(|window| window.mux.panes.values()),
                );
                clear_completions_on_focus_loss(f, completion_panes, |pane| {
                    pane.term.invalidate_completion();
                });
                // A focus loss can swallow the button-UP that
                // ends an in-progress drag (the release lands on whatever window
                // took focus), latching `selecting` / `scrollbar_drag_offset` /
                // `tab_drag_active` / a held button. The next CursorMoved
                // then kept extending the selection or dragging a tab with no
                // button down. Disarm them on focus loss, committing any pending
                // copy-on-select first (mirrors the left-button-up path).
                if !f {
                    // The compositor may deliver held-key releases to the
                    // newly focused window. Drop UI suppression state here so
                    // a later unrelated release cannot be mistaken for the
                    // missing half of an old shortcut.
                    ws.suppressed_key_releases.clear();
                    ws.terminal_owned_key_releases.clear();
                    ws.closing_keys.clear();
                    ws.ime_preedit = None;
                    ws.ime_focus_generation = ws.ime_focus_generation.wrapping_add(1);
                    ws.search.dragging_editor = false;
                    ws.search.pressed_control = None;
                    self.finish_selection_gesture(ws);
                    ws.scrollbar_drag_offset = None;
                    ws.scrollbar_hover = false;
                    ws.tab_drag_active = false;
                    ws.tab_drag_press = None;
                    ws.tab_pressed_idx = None;
                    // A focus loss also ends any split-divider drag.
                    ws.dragging_split = None;
                    // Releases now land in another window: each program
                    // with a held button's press gets its release here.
                    self.release_held_buttons(ws, |_| true);
                    // And a card's press: its release may land elsewhere.
                    ws.card_press = None;
                    // A focus loss also cancels an in-flight tab tear-off
                    // (the release will land on whatever window took focus).
                    ws.detach_drag = crate::detach::DragState::default();
                    ws.drag_press = None;
                    ws.pane_drag = None;
                    if let Some(receipt) = ws.media_paste_receipt.as_mut()
                        && receipt.set_hover(false, std::time::Instant::now())
                    {
                        ws.accessibility_pending = true;
                    }
                    // Torn-drag tracking deliberately survives
                    // this disarm — the tear itself moves OS focus to the
                    // torn window (firing Focused(false) on the source), and
                    // manual-follow rides the source's mouse CAPTURE, which
                    // outlives focus. Stale tracking is cleaned by the
                    // press/release handlers + the about_to_wait failsafe.
                }
                // Mirrors Terminator's `hide_on_lose_focus`
                // (terminatorlib/config.py:77): Quake-style auto-hide. When
                // the user clicks away to another window, hide the
                // kettle window. Reappears via `kettle --toggle`
                // or whatever global hotkey the user
                // bound. Honors only on focus-LOSS (f == false).
                if !f
                    && self.cfg.hide_on_lose_focus
                    && let Some(w) = &ws.window
                {
                    w.set_visible(false);
                }
                // Route through the shared helper so all
                // user-driven blink-reset paths share one implementation. The
                // CursorBlinkingChange handler still inlines the body
                // because it runs inside `ws.mux.panes.values_mut()`
                // and can't borrow `self` again — that one's documented.
                self.reset_blink_phase(ws);
                // Focus-event reporting (DEC private mode ?1004) follows
                // `window_focused` in `sync_pane_focus_reports`, which runs
                // when this dispatch finishes and also covers focus moving
                // between panes and tabs.
                // winit's `request_user_attention(None)` alone does
                // not reliably stop the Win11 taskbar flash once started, so
                // when an attention request is outstanding, clear it directly
                // (FlashWindowEx FLASHW_STOP via Taskbar) on focus-gain and
                // reset the tracker.
                if f && ws.attention_active {
                    ws.attention_active = false;
                    if let Some(w) = &ws.window {
                        w.request_user_attention(None);
                        ws.taskbar.clear_attention(w);
                    }
                }
                if let Some(w) = &ws.window {
                    w.request_redraw();
                }
            }
            WindowEvent::Occluded(occluded) => {
                // Freeze the animated background (and any proactive animation
                // wake) while the window is fully hidden behind other windows.
                // An invisible window must cost zero idle, which is what makes
                // the `background-animation = always` default safe. On
                // un-occlude, repaint at once so the wallpaper catches up to
                // its true time.
                ws.window_occluded = occluded;
                if occluded {
                    Self::hide_cursor_layer(ws);
                }
                if !occluded {
                    ws.frame_recovery.expedite(std::time::Instant::now());
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                }
            }
            WindowEvent::Ime(ime) => {
                // Text through an input method returns focus from a card to
                // its pane, as a key press does; the method handles those
                // presses, so none arrives.
                let typing = match &ime {
                    winit::event::Ime::Preedit(text, _) => !text.is_empty(),
                    winit::event::Ime::Commit(_) => true,
                    _ => false,
                };
                if typing && ws.card_focus.take().is_some() {
                    ws.accessibility_pending = true;
                }
                // A preview lane holding the keyboard takes no text: what an
                // input method composes or commits meanwhile goes nowhere.
                if ws.preview_focus.is_some()
                    && matches!(
                        ime,
                        winit::event::Ime::Preedit(..) | winit::event::Ime::Commit(_)
                    )
                {
                    return;
                }
                let redraw = match ime {
                    winit::event::Ime::Enabled => {
                        if let Some(window) = &ws.window {
                            window.set_ime_allowed(ws.preview_focus.is_none());
                        }
                        self.update_ime_cursor_area(ws);
                        false
                    }
                    winit::event::Ime::Preedit(text, selection) => {
                        let next = normalized_ime_preedit(text, selection);
                        if ws.ime_preedit == next {
                            return;
                        }
                        ws.ime_preedit_owner =
                            next.as_ref()
                                .map(|_| crate::window_state::ImePreeditSession {
                                    owner: if ws.search.open {
                                        crate::window_state::ImePreeditOwner::Search
                                    } else {
                                        crate::window_state::ImePreeditOwner::Other
                                    },
                                    generation: ws.ime_focus_generation,
                                });
                        ws.ime_preedit = next;
                        self.update_ime_cursor_area(ws);
                        true
                    }
                    winit::event::Ime::Commit(text) => {
                        let redraw = ws.ime_preedit.is_some() || !text.is_empty();
                        ws.ime_preedit = None;
                        let owner = ws.ime_preedit_owner.take();
                        let current_owner = if ws.search.open {
                            crate::window_state::ImePreeditOwner::Search
                        } else {
                            crate::window_state::ImePreeditOwner::Other
                        };
                        let owns_current_surface = owner.is_none_or(|session| {
                            session.owner == current_owner
                                && session.generation == ws.ime_focus_generation
                        });
                        if owns_current_surface {
                            self.commit_ime_text(ws, &text, event_loop);
                        }
                        redraw
                    }
                    winit::event::Ime::Disabled => {
                        ws.ime_preedit_owner = None;
                        ws.ime_preedit.take().is_some()
                    }
                };
                if redraw && let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            WindowEvent::KeyboardInput { event, .. } => {
                // A key press returns focus from a card that assistive
                // technology focused to the pane, where the key goes.
                if event.state == ElementState::Pressed && ws.card_focus.take().is_some() {
                    ws.accessibility_pending = true;
                }
                let ui_owns_key = !matches!(ws.detach_drag, crate::detach::DragState::Idle)
                    || ws.context_menu.is_some()
                    || ws.vi_mode.is_some()
                    || ws.hint_state.is_some()
                    || ws.palette_input.is_some()
                    || ws.settings_nav.is_some()
                    || ws.layout_picker_input.is_some()
                    || ws.theme_picker_input.is_some()
                    || ws.ssh_input.is_some()
                    || ws.confirm_dialog.is_some()
                    || ws.editing_title.is_some()
                    || ws.search.open
                    || ws.preview_focus.is_some()
                    || ws.ime_preedit.is_some();
                // The modal that gets this press, if any; a press after which
                // it is no longer the top modal closed or replaced it.
                let key_modal = top_modal(ws);
                if drop_closing_key_repeat(
                    &mut ws.closing_keys,
                    event.physical_key,
                    event.state,
                    event.repeat,
                ) {
                    return;
                }
                if track_consumed_key_release(
                    &mut ws.suppressed_key_releases,
                    &mut ws.terminal_owned_key_releases,
                    event.physical_key,
                    event.state,
                    ui_owns_key,
                ) {
                    return;
                }
                if event.state == ElementState::Released {
                    self.write_terminal_key_event(ws, &event, false);
                    return;
                }
                if ws.ime_preedit.is_some() {
                    return;
                }
                // Typing in the torn window right after an X11 drop whose
                // release the WM swallowed commits the latched dock first (same
                // shape as the CursorMoved post-drop heuristic, including the
                // post-handoff blackout and the final-position latch
                // revalidation; on Windows the synthesized release already
                // cleared the tracking before any key can arrive).
                if let Some(td) = self.torn_drag.as_ref()
                    && td.seq == ws.seq
                    && td.native
                    && td.saw_move
                    && td.started.elapsed() >= std::time::Duration::from_millis(300)
                {
                    let commit = self.revalidate_dock_latch(ws);
                    self.finalize_torn_drag(ws, commit);
                    // A committed merge empties this window — it is closing;
                    // don't process the key against an empty mux.
                    if self.window_close_pending(ws.seq) {
                        return;
                    }
                }
                let cursor_exit_key = if ws.cursor_exit_log.enabled {
                    ws.cursor_exit_log.accepted_key(
                        ws.seq,
                        ws.mux.tabs.get(ws.mux.active).map(|tab| tab.focus),
                        event.state,
                        &event.logical_key,
                        event.physical_key,
                        ws.blink_layer.is_active(),
                    )
                } else {
                    None
                };
                // Record the keystroke (redacted token) BEFORE any
                // modal/early-return path consumes it, so the trace captures
                // every key. Pasted content never reaches here — it's a `paste`
                // marker (see the paste sites), never raw bytes.
                {
                    let mods = ws.mods;
                    if let Some(rec) = self.recorder.as_mut() {
                        dev_record_key(rec, &event.logical_key, mods);
                    }
                }
                // Terminator parity: Esc abandons an in-flight pane drag, and
                // is consumed like the tab-drag cancel below it. Only a LIVE
                // drag claims the key — an armed-but-unmoved press is still
                // just a click, and swallowing Esc for it would eat the key
                // whenever the pointer happened to rest on a titlebar.
                //
                // Dropping the state is the whole cancel: nothing has been
                // committed yet. The move only happens at release, off
                // `pane_drag.target`, so a cleared gesture releases into a
                // no-op with the tree untouched.
                if ws.pane_drag.as_ref().is_some_and(|d| d.live)
                    && matches!(&event.logical_key, Key::Named(NamedKey::Escape))
                {
                    ws.pane_drag = None;
                    // Its repeats must not go on to close a modal or reach
                    // the terminal.
                    ws.closing_keys.insert(event.physical_key);
                    if let Some(w) = &ws.window {
                        if cursor_exit_key.is_some() {
                            ws.cursor_exit_log.request_exit(cursor_exit_key);
                        }
                        w.request_redraw();
                    }
                    return;
                }
                // Esc cancels an in-flight tab drag and is consumed, so it
                // never leaks to the PTY or closes a modal.
                if !matches!(ws.detach_drag, crate::detach::DragState::Idle)
                    && matches!(&event.logical_key, Key::Named(NamedKey::Escape))
                {
                    let (next, _restored) = std::mem::take(&mut ws.detach_drag).cancel();
                    ws.detach_drag = next;
                    ws.drag_press = None;
                    ws.tab_drag_active = false;
                    ws.tab_drag_press = None;
                    ws.tab_pressed_idx = None;
                    ws.closing_keys.insert(event.physical_key);
                    if let Some(w) = &ws.window {
                        if cursor_exit_key.is_some() {
                            ws.cursor_exit_log.request_exit(cursor_exit_key);
                        }
                        w.request_redraw();
                    }
                    return;
                }
                // Esc also cancels a MANUAL-FOLLOW torn drag (native cancels
                // belong to the WM's own move loop, whose grab-end the
                // button-state revalidation sorts out). Without it, the
                // release would commit whatever dock target happened to be
                // latched. Consumed, like the pre-tear cancel above; the torn
                // window stays where the drag left it.
                if self.torn_drag.as_ref().is_some_and(|t| !t.native)
                    && matches!(&event.logical_key, Key::Named(NamedKey::Escape))
                {
                    self.abandon_torn_drag(Some(ws));
                    ws.closing_keys.insert(event.physical_key);
                    return;
                }
                // Keep the cursor solid while actively typing.
                // Routes through the shared helper so the eight
                // user-driven blink-reset paths (Reset / focus changes /
                // modal close / typing / tab close / window focus /
                // DEC ?12 toggle) stay in lock-step.
                if cursor_exit_key.is_some() {
                    ws.cursor_exit_log.request_exit(cursor_exit_key);
                }
                self.reset_blink_phase(ws);
                // Hide the OS mouse cursor (configurable; default on, like
                // every modern terminal). Re-shown on the next CursorMoved.
                self.hide_mouse_cursor(ws);
                let text = event.text.as_ref().map(|s| s.as_str());

                // Phase 5 of TERMINATOR-CONFIRM-DIALOG-DESIGN.md:
                // confirm-modal key handler. Tab/Shift+Tab/←→ move focus,
                // Enter activates the focused button, and Esc closes the
                // modal without dispatching. The modal is exclusive, so
                // non-nav keys are swallowed.
                if ws.confirm_dialog.is_some() {
                    if !modal_repeat_is_inert(
                        ModalRepeat::ConfirmDialog,
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.confirm_dialog_key(ws, &event.logical_key, event_loop);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    return;
                }
                if ws.context_menu.is_some() {
                    if !modal_repeat_is_inert(
                        ModalRepeat::ContextMenu {
                            vim_nav: self.cfg.vim_menu_nav,
                        },
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.context_menu_key(ws, &event.logical_key, text, event_loop);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                // Vi-mode key dispatch. When
                // vi_mode is Some, intercept keys for vi-style
                // navigation before they reach the PTY. h/j/k/l move
                // the vi cursor; 0/$/g/G jump; Esc exits, and so does the
                // chord that entered it.
                if ws.vi_mode.is_some() {
                    if is_vi_mode_toggle_chord(
                        &self.cfg.keybinds,
                        &event.logical_key,
                        &event.physical_key,
                        ws.mods,
                    ) {
                        // A held chord leaves once, not on every repeat.
                        if !event.repeat {
                            self.exit_vi_mode(ws);
                        }
                    } else if !modal_repeat_is_inert(
                        ModalRepeat::ViMode,
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.vi_mode_key(ws, &event.logical_key, text);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                if ws.hint_state.is_some() {
                    if !modal_repeat_is_inert(
                        ModalRepeat::Hint,
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.hint_key(ws, &event.logical_key, text);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                if ws.palette_input.is_some() {
                    if !modal_repeat_is_inert(
                        ModalRepeat::Palette,
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.palette_key(ws, &event.logical_key, text, event_loop);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                // The theme picker sits over Settings when the Theme row
                // opened it, so it takes the keys first.
                if ws.theme_picker_input.is_some() {
                    if !modal_repeat_is_inert(
                        ModalRepeat::Palette,
                        event.repeat,
                        &event.logical_key,
                        ws.mods.control_key(),
                    ) {
                        self.theme_picker_key(ws, &event.logical_key, text);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                // While the inline path prompt is open it owns the keyboard
                // (typed text → the buffer; Enter/Esc finish it).
                if ws.settings_nav.is_some() && ws.settings_text_edit.is_some() {
                    self.settings_text_key(ws, &event.logical_key, text);
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }
                // Settings overlay key handling (exclusive modal).
                if ws.settings_nav.is_some() {
                    // Chord capture waits for a new press. Auto-repeat of the
                    // Space or Enter that started it would otherwise be
                    // captured, or refused with a notification, once per repeat.
                    let inert = if settings_capture_active(ws) {
                        event.repeat
                    } else {
                        // Only a repeat needs the focused row's kind.
                        let steps = event.repeat && self.settings_row_steps(ws);
                        modal_repeat_is_inert(
                            ModalRepeat::Settings { steps },
                            event.repeat,
                            &event.logical_key,
                            ws.mods.control_key(),
                        )
                    };
                    if !inert {
                        self.settings_key(ws, &event.logical_key, event_loop);
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                if ws.layout_picker_input.is_some() {
                    self.layout_picker_key(ws, &event.logical_key, text);
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                if ws.ssh_input.is_some() {
                    self.ssh_key(ws, &event.logical_key, text);
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                // Edit-title overlay key handler. Esc
                // cancels; Enter applies via apply_title_edit;
                // Backspace removes one char; printable text appends.
                if ws.editing_title.is_some() {
                    self.title_edit_key(ws, &event.logical_key, text);
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                if ws.search.open {
                    if event.repeat
                        && search_button_ignores_repeat(
                            ws.search.focused_control,
                            &event.logical_key,
                        )
                    {
                        return;
                    }
                    if !self.search_key(ws, &event.logical_key, Some(&event.physical_key), text) {
                        self.search_bar_shortcut(
                            ws,
                            &event.logical_key,
                            Some(&event.physical_key),
                            event.repeat,
                            event_loop,
                        );
                    }
                    remember_closing_key(ws, key_modal, event.physical_key);
                    if let Some(w) = &ws.window {
                        w.request_redraw();
                    }
                    return;
                }

                // A preview lane holding the keyboard takes every key, the
                // application's shortcuts included: Esc gives it back.
                if ws.preview_focus.is_some() {
                    self.preview_focus_key(ws, &event.logical_key, event.repeat);
                    remember_closing_key(ws, key_modal, event.physical_key);
                    return;
                }

                if let Some((trigger, act)) = resolve_keybind_action(
                    &self.cfg.keybinds,
                    Some(&event.logical_key),
                    Some(&event.physical_key),
                    ws.mods,
                ) && !self.chord_falls_through(ws, trigger, &act)
                {
                    track_consumed_key_release(
                        &mut ws.suppressed_key_releases,
                        &mut ws.terminal_owned_key_releases,
                        event.physical_key,
                        event.state,
                        true,
                    );
                    if !(event.repeat && toggles_once_per_press(&act)) {
                        self.handle_action(ws, act, event_loop);
                    }
                    return;
                }

                track_terminal_key_press(
                    &mut ws.suppressed_key_releases,
                    &mut ws.terminal_owned_key_releases,
                    event.physical_key,
                );
                self.write_terminal_key_event(ws, &event, true);
            }
            WindowEvent::RedrawRequested => self.redraw(ws),
            _ => {}
        }
    }

    /// Returns the absolute wake-up deadline this window wants
    /// (`None` = wait for events). The dispatch wrapper merges every window's
    /// request to the earliest deadline and sets the control flow once.
    fn about_to_wait_inner(
        &mut self,
        ws: &mut WindowState,
        event_loop: &ActiveEventLoop,
    ) -> Option<std::time::Instant> {
        if take_window_lifecycle_wakes(ws) {
            self.drain_events(ws);
        }
        #[cfg(windows)]
        if ws
            .mux
            .panes
            .values()
            .any(|pane| !pane.exit_observed && pane.term.direct_child_exit_at().is_some())
        {
            // Direct-child timestamps remain level-triggered through both
            // deadlines. This runs even for hidden windows and does not depend
            // on output or cursor animation to keep the policy clock moving.
            self.drain_events(ws);
        }
        self.process_pending_pane_restarts(ws);
        let held_child_reap_pending = ws.mux.poll_held_child_statuses();
        // A log worker can fail after PTY output becomes silent. Its direct
        // event-loop wake reaches this poll even when output-generation gating
        // correctly decides there is no frame to paint.
        self.sync_session_log_failures(ws);
        // Drain trailing recorder output before reap removes a
        // just-exited pane (covers the shell-exit → process-exit close path,
        // e.g. a fast `-e cmd` session).
        self.flush_recorder_output(ws);
        let reaped = ws.mux.reap();
        // Binding, not an inline call on the right of `||`: see the matching
        // reap in `redraw`.
        let stale_title = clear_stale_title_edit(&ws.mux, &mut ws.editing_title);
        if reaped.layout_changed || stale_title {
            ws.pending_resize = true;
            if let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        self.hoover_groups(ws);
        if reaped.mux_empty && ws.window.is_some() {
            self.save_session(ws);
            self.request_window_close(ws.seq);
            return None;
        }
        ws.search_queries
            .retain(|pane_id, _| ws.mux.panes.contains_key(pane_id));
        if ws
            .media_paste_receipt
            .as_ref()
            .is_some_and(|receipt| !ws.mux.panes.contains_key(&receipt.pane_id))
        {
            ws.media_paste_receipt = None;
            ws.accessibility_pending = true;
        }
        if ws
            .pending_video_paste_receipt
            .as_ref()
            .is_some_and(|receipt| !ws.mux.panes.contains_key(&receipt.pane_id))
        {
            ws.pending_video_paste_receipt = None;
        }
        if !self.cfg.paste_video_preview {
            ws.pending_video_paste_receipt = None;
        }
        let now = std::time::Instant::now();
        if ws
            .pending_video_paste_receipt
            .as_ref()
            .is_some_and(|pending| pending.expired(now))
        {
            ws.pending_video_paste_receipt = None;
            ws.accessibility_pending = true;
            log::debug!("video paste receipt abandoned: preview worker response timed out");
        }
        let pending_video_receipt_wait = ws.pending_video_paste_receipt.as_ref().map(|pending| {
            pending
                .deadline()
                .saturating_duration_since(now)
                .max(std::time::Duration::from_millis(1))
        });
        #[cfg(windows)]
        let bounded_pty_exit_wait = next_bounded_pty_exit_wait(ws, now);
        // Catch the session changes no gesture announces — see `SESSION_SWEEP`.
        // Deliberately NOT part of the returned deadline: this must never be a
        // reason to wake up.
        if session_sweep_due(self.last_session_sweep, now, !ws.mux.tabs.is_empty()) {
            self.last_session_sweep = Some(now);
            self.save_session(ws);
        }
        let lua_wait = self.poll_pending_lua_commands(ws, event_loop, now);
        let remote_wait = if should_poll_remote_window(
            !self.pending_remote_commands.is_empty(),
            self.remote_spool_claim_pending,
            self.remote_command_retry.next_at.is_some(),
            ws.seq,
            self.focused_seq,
        ) {
            // An unclaimed spool belongs to the window focused when it is
            // finally claimed. Do not let the first BTreeMap window steal the
            // origin merely because a busy lock deferred the watcher event.
            self.poll_pending_remote_commands(ws, now)
        } else {
            None
        };
        let automation_wait = match (lua_wait, remote_wait) {
            (Some(lua), Some(remote)) => Some(lua.min(remote)),
            (Some(wait), None) | (None, Some(wait)) => Some(wait),
            (None, None) => None,
        };
        if self.window_close_pending(ws.seq) || self.quit_requested {
            return None;
        }
        // Once the GPU device is lost we no longer paint (see the redraw guard).
        // Drive renderer recovery from here instead of scheduling animation
        // wakes that would only re-enter the dead-device redraw path.
        if self.gpu.as_ref().is_some_and(|g| g.is_lost()) {
            // The global device-loss callback can wake the loop without a
            // window event. Quiesce pane output here before any recovery
            // backoff returns so a hot PTY cannot spin the dead render path.
            self.sync_output_wake_gate(ws);
            self.start_gpu_incident_if_needed();
            match self.gpu_recovery.poll(now, GPU_RECOVERY_SETTLE) {
                RecoveryAction::Wait(wait) => {
                    let next = wait.max(std::time::Duration::from_millis(1));
                    let next = automation_wait.map_or(next, |automation| automation.min(next));
                    let next = pending_video_receipt_wait.map_or(next, |pending| pending.min(next));
                    return Some(now + next);
                }
                RecoveryAction::Attempt { attempt_index } => {
                    let attempt = attempt_index.saturating_add(1);
                    let escalation = kettle_render::escalation_for_attempt(attempt_index);
                    let escalation_label = gpu_escalation_label(escalation);
                    if let Some(log) = self.gpu_incident.as_mut()
                        && let Err(error) = log.record_attempt(attempt, escalation_label)
                    {
                        log::warn!("GPU fault diagnostic write failed: {error}");
                    }
                    match self.try_recover_gpu(ws, event_loop, escalation, attempt) {
                        Ok(outcome) => {
                            if let Some(log) = self.gpu_incident.as_mut()
                                && let Err(error) = log.record_recovered(
                                    attempt,
                                    escalation_label,
                                    outcome.adapter,
                                    outcome.secondary_window_failures,
                                )
                            {
                                log::warn!("GPU fault diagnostic write failed: {error}");
                            }
                            self.gpu_incident = None;
                            self.gpu_incident_started_for_loss = false;
                            self.gpu_recovery.recovered();
                        }
                        Err(error) => {
                            if let Some(log) = self.gpu_incident.as_mut()
                                && let Err(write_error) =
                                    log.record_failure(attempt, escalation_label, &error)
                            {
                                log::warn!("GPU fault diagnostic write failed: {write_error}");
                            }
                            let backoff = gpu_recovery_backoff(attempt);
                            self.gpu_recovery.failed(now, backoff);
                            let next = backoff.max(std::time::Duration::from_millis(1));
                            let next =
                                automation_wait.map_or(next, |automation| automation.min(next));
                            let next = pending_video_receipt_wait
                                .map_or(next, |pending| pending.min(next));
                            return Some(now + next);
                        }
                    }
                }
            }
        }
        if ws.pty_resize_retry.take_due(now) {
            if ws.renderer.is_some() {
                self.resize_all(ws);
            } else {
                // Preserve a bounded retry while a renderer rebuild temporarily
                // makes layout metrics unavailable.
                ws.pty_resize_retry.record_result(now, true);
            }
        }
        let pty_resize_retry_wait = ws
            .pty_resize_retry
            .remaining(now)
            .map(|wait| wait.max(std::time::Duration::from_millis(1)));
        let monitor_refresh_wait = if ws.output_refresh_probe_pending {
            match monitor_refresh_probe_wait(ws.output_refresh_probe_at, now, false) {
                Some(remaining) => Some(remaining),
                None => {
                    self.sync_output_frame_budget(ws, true);
                    None
                }
            }
        } else {
            None
        };
        let render_hidden = window_is_render_hidden(ws);
        self.sync_output_wake_gate(ws);
        let mut frame_recovery_wait = None;
        match ws.frame_recovery.poll(now, render_hidden) {
            FrameRecoveryPoll::Idle | FrameRecoveryPoll::Quiescent => {}
            FrameRecoveryPoll::Wait(wait) => {
                frame_recovery_wait = Some(wait.max(std::time::Duration::from_millis(1)));
            }
            FrameRecoveryPoll::Ready(FrameRecoveryAction::Redraw) => {
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            FrameRecoveryPoll::Ready(FrameRecoveryAction::RebuildRenderer) => {
                match self.try_recover_window_renderer(ws) {
                    Ok(()) => {
                        log::info!("window {} renderer/surface recovery succeeded", ws.seq);
                        if let Some(window) = &ws.window {
                            window.request_redraw();
                        }
                    }
                    Err(error) => {
                        log::warn!(
                            "window {} renderer/surface recovery failed: {error}",
                            ws.seq
                        );
                        if self.gpu.as_ref().is_some_and(|gpu| gpu.is_lost()) {
                            // The device callback owns escalation. Ensure the
                            // event loop turns once more even if no animation
                            // or PTY event is active.
                            frame_recovery_wait = Some(std::time::Duration::from_millis(1));
                        } else {
                            ws.frame_recovery.schedule_renderer_rebuild(now);
                            match ws.frame_recovery.poll(now, render_hidden) {
                                FrameRecoveryPoll::Wait(wait) => {
                                    frame_recovery_wait =
                                        Some(wait.max(std::time::Duration::from_millis(1)));
                                }
                                FrameRecoveryPoll::Quiescent => {}
                                FrameRecoveryPoll::Idle | FrameRecoveryPoll::Ready(_) => {
                                    // A failed rebuild after the first
                                    // immediate attempt always arms a positive
                                    // backoff. Keep a defensive one-turn wake
                                    // if that invariant changes.
                                    frame_recovery_wait = Some(std::time::Duration::from_millis(1));
                                }
                            }
                        }
                    }
                }
            }
        }
        // Most backends pair ScaleFactorChanged with Resized. If one does not,
        // commit the pending DPI layout from the window's final inner size
        // here. A minimized 0x0 window and any renderer/GPU repair keep the
        // transition pending until a usable surface exists.
        let mut dpi_fallback_wait = None;
        if let Some((width, height)) = ws
            .window
            .as_ref()
            .map(|window| window.inner_size())
            .map(|size| (size.width, size.height))
        {
            let renderer_ready = self.dpi_resize_renderer_ready(ws)
                && !render_hidden
                && !ws.dpi_resize_surface_suspended;
            match ws.dpi_resize.on_event(DpiResizeEvent::AboutToWait {
                width,
                height,
                renderer_ready,
            }) {
                DpiResizeAction::ApplyLayout => self.commit_window_resize(ws, width, height),
                DpiResizeAction::DeferAndWake => {
                    // Do not render a transient new-scale/old-size frame just
                    // to turn the loop. A precise short deadline gives the
                    // backend's paired Resized event one more dispatch turn.
                    dpi_fallback_wait = Some(std::time::Duration::from_millis(1));
                }
                DpiResizeAction::Defer => {}
            }
        }
        let (completion_hide_due, completion_hide_wait) = ws
            .mux
            .active_focus()
            .and_then(|pane_id| ws.mux.panes.get(&pane_id))
            .map(|pane| pane.term.poll_completion_hide(now))
            .unwrap_or((false, None));
        // Drive cursor blink + visual-bell decay without busy-looping: only
        // schedule wake-ups while something is actually animating. A flash
        // that has fully decayed is dropped here and gets one more repaint to
        // erase its last frame, like the resize chip below.
        let bells_expired = ws
            .bell_flashes
            .values()
            .any(|rang| rang.elapsed() >= BELL_FLASH_DURATION);
        if bells_expired {
            ws.bell_flashes
                .retain(|_, rang| rang.elapsed() < BELL_FLASH_DURATION);
            if !render_hidden && let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
        let bell_active = !render_hidden && !ws.bell_flashes.is_empty();
        // The resize chip needs repaints until it expires (then one more to
        // erase it); clear the state once it has.
        let resize_chip_live = ws
            .resize_overlay
            .map(|(_, _, t)| t.elapsed() < RESIZE_OVERLAY_DURATION)
            .unwrap_or(false);
        let resize_chip_active = resize_chip_live && !render_hidden;
        if !resize_chip_live && ws.resize_overlay.is_some() {
            ws.resize_overlay = None;
            if !render_hidden && let Some(w) = &ws.window {
                w.request_redraw();
            }
        }
        let receipt_enabled = ws
            .media_paste_receipt
            .as_ref()
            .is_some_and(|receipt| match &receipt.kind {
                crate::window_state::MediaPasteReceiptKind::Image { .. } => {
                    self.cfg.paste_image_preview
                }
                crate::window_state::MediaPasteReceiptKind::Video { .. } => {
                    self.cfg.paste_video_preview
                }
            });
        let receipt_owner_visible = receipt_enabled
            && ws.window_focused
            && terminal_surface_available(ws)
            && ws
                .media_paste_receipt
                .as_ref()
                .is_some_and(|receipt| ws.mux.active_focus() == Some(receipt.pane_id));
        let mut media_receipt_redraw = false;
        if !receipt_enabled && ws.media_paste_receipt.take().is_some() {
            // A live config change to `off` is an ownership boundary, not only
            // a paint toggle. Release the bounded pixels and retained path
            // immediately instead of keeping hidden preview state until its
            // original lifetime expires.
            ws.accessibility_pending = true;
            media_receipt_redraw = true;
        }
        if !receipt_owner_visible
            && let Some(receipt) = ws.media_paste_receipt.as_mut()
            && receipt.set_hover(false, now)
        {
            ws.accessibility_pending = true;
            media_receipt_redraw = true;
        }
        if ws
            .media_paste_receipt
            .as_ref()
            .is_some_and(|receipt| !receipt.live(now))
        {
            ws.media_paste_receipt = None;
            ws.accessibility_pending = true;
            media_receipt_redraw = true;
        } else if let Some(receipt) = ws.media_paste_receipt.as_mut() {
            media_receipt_redraw |= receipt.mark_collapsed_if_due(now);
        }
        // Cards that moved under a still pointer, or one under it settling,
        // change the cursor and the hover outline without a pointer event.
        if ws.card_hover_stale || ws.card_settle_wake.is_some_and(|at| at <= now) {
            ws.card_hover_stale = false;
            self.sync_cursor_icon(ws);
        }
        // The tip leaves its card when its time is up.
        if self.cards_tip.until().is_some_and(|until| until <= now) {
            self.end_cards_tip(ws);
        }
        // A lane that can no longer use the keyboard gives it back.
        self.check_preview_focus(ws);
        // Zoomed lanes whose view settled ask for sharper pixels, and a
        // lane's edge drag that paused resizes its PTYs.
        let lane_crop_wait = self.ask_due_lane_crops(ws, now);
        let lane_resize_wait = self.flush_lane_resize(ws, now);
        // Lane previews step their frames, time out, or start on a rest.
        let lane_preview_wait = self.tick_lane_previews(ws, now);
        // Lane playbacks keep their sessions, and pause while hidden.
        let lane_playback_wait = self.tick_lane_playbacks(ws, now);
        // A menu or dialog opened from the keyboard ends a lane's drag now,
        // not at the pointer's next motion.
        if (ws.lane_drag.is_some() || ws.lane_resize.is_some())
            && (ws.context_menu.is_some() || self.non_search_modal_open(ws))
        {
            ws.lane_drag = None;
            self.end_lane_resize(ws);
        }
        let cards_tip_wait = self.cards_tip.until().map(|until| {
            until
                .saturating_duration_since(now)
                .max(std::time::Duration::from_millis(1))
        });
        let card_settle_wait = ws.card_settle_wake.map(|at| {
            at.saturating_duration_since(now)
                .max(std::time::Duration::from_millis(1))
        });
        let media_receipt_wait = ws
            .media_paste_receipt
            .as_ref()
            .and_then(|receipt| receipt.next_deadline(now))
            .map(|deadline| {
                deadline
                    .saturating_duration_since(now)
                    .max(std::time::Duration::from_millis(1))
            });
        // `about_to_wait` sits on the same input-to-present path as a queued
        // menu-hover redraw on winit backends that deliver RedrawRequested in
        // the next turn. Reuse the validated snapshot's DEC blink bit while a
        // context menu is open; otherwise this scheduler quietly reacquires the
        // focused Term mutex even though `redraw` itself is lock-free.
        let cached_menu_snapshots = ws.context_menu.is_some()
            && context_menu_snapshot_reuse_safe(ws)
            && self.torn_drag.is_none()
            && self.pane_snapshots_match_current_layout(ws);
        let pane_blink = self.pane_cursor_blinking(ws, cached_menu_snapshots);
        let blink_timed_out = cursor_blink_timed_out(
            now.saturating_duration_since(ws.last_blink_activity),
            self.cfg.cursor_blink_timeout(),
            ws.blink_on,
        );
        // While the window server blinks the cursor, the scheduler neither
        // flips the phase nor wakes for it; `redraw` materializes the phase
        // from the layer's plan instead.
        let layer_blink = ws.blink_layer.is_active();
        let blink_active = !render_hidden
            && !layer_blink
            && !blink_timed_out
            && cursor_blink_active(self.cfg.cursor_blink, pane_blink, ws.window_focused);
        let blink_interval = std::time::Duration::from_millis(self.cfg.cursor_blink_interval);
        let blink_elapsed = now.saturating_duration_since(ws.last_blink);
        let next_blink =
            next_cursor_blink_phase(blink_active, blink_elapsed, blink_interval, ws.blink_on);
        let blink_due = next_blink.is_some();
        if let Some(next_blink) = next_blink {
            // Advance at the TIMER edge, before request_redraw(). Wayland may
            // defer RedrawRequested until a compositor frame callback; leaving
            // the old timestamp in place during that gap repeatedly enqueues
            // the same blink and drains the queue at full frame rate.
            ws.blink_on = next_blink;
            ws.last_blink = now;
        }
        // Whether only the blink drew in the half-period this edge ends.
        let blink_quiet = blink_due
            && ws
                .blink_layer
                .note_edge(now, crate::cursor_blink::quiet_window(blink_interval));
        let term_anim = !render_hidden
            && ws
                .mux
                .panes
                .values()
                .any(|p| p.term.has_running_animation());
        let term_anim_finished = std::mem::replace(&mut ws.term_animation_active, term_anim)
            && !term_anim
            && !render_hidden;
        // An animated background (a starfield, or a GIF/APNG/WebP image) wakes
        // at its OWN frame rate, not a fixed 30 fps, at which an 8 fps GIF
        // would repaint the same frame ~22×/s (wasted present()s).
        // `bg_anim_interval_ms` is the ms to the next frame boundary. It is
        // `None` unless a bg is animating (and, for `when-focused`, only
        // while focused), so an unfocused window still reaches
        // `ControlFlow::Wait` at zero idle cost, unlike Ghostty's always-on
        // shaders.
        let bg_anim_interval_raw = ws
            .renderer
            .as_ref()
            .and_then(|r| r.bg_anim_interval_ms(&self.cfg, ws.window_focused));
        // An occluded, minimized, or explicitly hidden window cannot show the
        // animation, so it must cost zero idle. Reuse the visibility snapshot
        // taken for frame-recovery scheduling.
        let bg_hidden = bg_anim_interval_raw.is_some() && render_hidden;
        let bg_anim_interval = if bg_hidden {
            None
        } else {
            bg_anim_interval_raw
        };
        // Edge-trigger the bg redraw. Request it ONLY when the displayed frame
        // index changes, since requesting it on every `about_to_wait` makes
        // winit redraw continuously. This mirrors how `blink_due` gates the
        // cursor-blink redraw.
        let bg_frame = if bg_hidden {
            None
        } else {
            ws.renderer
                .as_ref()
                .and_then(|r| r.bg_current_frame_index(&self.cfg, ws.window_focused))
        };
        let bg_frame_due = bg_frame.is_some() && bg_frame != ws.last_bg_frame;
        if bg_frame_due {
            ws.last_bg_frame = bg_frame;
        }
        if bg_frame.is_none() {
            ws.last_bg_frame = None;
        }
        // Selection-autoscroll runs at the same ~30 fps as bell / image
        // animation. Without an active wake-up the edge drag freezes until
        // the user wiggles the mouse.
        let autoscroll_active = !render_hidden && ws.selecting && {
            let area = self.area(ws);
            let scale = ws
                .window
                .as_ref()
                .map_or(1.0, |window| window.scale_factor() as f32);
            ws.selecting_pane
                .and_then(|id| self.pane_terminal(ws, area, id))
                .map(|r| {
                    ws.selection_autoscroll_edge != 0
                        || selection_autoscroll_lines(
                            ws.cursor.y as f32,
                            r.1,
                            r.1 + r.3,
                            scale,
                            ws.selection_dragged,
                        ) != 0
                })
                .unwrap_or(false)
        };
        // A deferred (coalesced) output paint becomes due
        // `OUTPUT_FRAME_BUDGET` after the last frame. Until then it stays
        // pending and we wake at its deadline so the burst paints exactly once.
        let output_budget = effective_output_budget(ws.output_frame_budget, ws.flood_paints);
        let coalesce_due = !render_hidden
            && !ws.frame_recovery.has_pending()
            && ws.output_pacer.is_deferred()
            && !ws.output_pacer.redraw_queued()
            && ws
                .last_paint
                .map(|t| now.saturating_duration_since(t) >= output_budget)
                .unwrap_or(true);
        // At an edge that hides the cursor, a quiet window with nothing else
        // to draw hands its blink to the window server (macOS). The blink
        // redraw requested below becomes the hand-off frame.
        let cursor_eligible = crate::macos_cursor_layer::SUPPORTED
            && self.cfg.macos_cursor_blink_layer
            && next_blink == Some(false)
            && Self::pane_cursor_layer_eligible(ws);
        if crate::cursor_blink::handoff_allowed(crate::cursor_blink::HandoffInputs {
            enabled: crate::macos_cursor_layer::SUPPORTED
                && self.cfg.macos_cursor_blink_layer
                && ws.blink_layer.fallback().is_none(),
            edge_hides_cursor: next_blink == Some(false),
            blink_active,
            cursor_eligible,
            quiet: blink_quiet,
            other_animation: bell_active
                || term_anim
                || bg_anim_interval.is_some()
                || autoscroll_active
                || resize_chip_active
                || media_receipt_redraw
                || media_receipt_wait.is_some()
                || pending_video_receipt_wait.is_some()
                || completion_hide_due
                || completion_hide_wait.is_some(),
            ime_preedit: ws.ime_preedit.is_some(),
            modal_steady: modal_holds_cursor_steady(ws),
            work_pending: coalesce_due
                || ws.output_pacer.is_deferred()
                || ws.frame_recovery.has_pending()
                || ws.pending_resize
                || ws.accessibility_pending
                || dpi_fallback_wait.is_some()
                || pty_resize_retry_wait.is_some()
                || ws
                    .renderer
                    .as_ref()
                    .is_some_and(Renderer::has_pending_screenshot),
        }) {
            ws.blink_layer.request_handoff();
        }
        // A theme schedule flips at a wall-clock boundary, and only a redraw
        // applies it. A window that draws nothing (idle, or with its cursor
        // blinking on the window server's layer) would otherwise keep the old
        // theme until something else changes, so check the schedule at each
        // wall-clock minute and draw only when it has flipped.
        let theme_schedule_due = !render_hidden
            && theme_schedule_redraw_due(
                self.last_schedule_decision,
                self.theme_schedule_is_dark(),
            );
        let theme_schedule_wait =
            (!render_hidden && self.cfg.theme_schedule.is_some()).then(until_next_wall_minute);
        if (bell_active
            || blink_due
            || term_anim
            || term_anim_finished
            || bg_frame_due
            || autoscroll_active
            || coalesce_due
            || resize_chip_active
            || media_receipt_redraw
            || completion_hide_due
            || theme_schedule_due)
            && let Some(w) = &ws.window
        {
            w.request_redraw();
            if coalesce_due {
                ws.output_pacer.queue_deferred_redraw();
            }
        }
        // Pick the earliest wake we still need: ~30 fps for bell / animation /
        // autoscroll / the resize chip, the cursor-blink half-period deadline,
        // or the pending coalesced output paint's deadline.
        let mut wait: Option<std::time::Duration> =
            if bell_active || term_anim || autoscroll_active || resize_chip_active {
                Some(std::time::Duration::from_millis(33))
            } else if let Some(bg_ms) = bg_anim_interval {
                // Animated bg: wake exactly at its next frame boundary (its
                // own fps), not 30 fps.
                Some(std::time::Duration::from_millis(bg_ms.clamp(16, 1000)))
            } else if blink_active {
                let remaining = blink_interval.saturating_sub(blink_elapsed);
                Some(remaining.max(std::time::Duration::from_millis(1)))
            } else {
                None
            };
        if let Some(next) = frame_recovery_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = theme_schedule_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = dpi_fallback_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = pty_resize_retry_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = monitor_refresh_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = automation_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = completion_hide_wait {
            let next = next.max(std::time::Duration::from_millis(1));
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = media_receipt_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = card_settle_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = cards_tip_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = lane_crop_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = lane_resize_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = lane_preview_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = lane_playback_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(next) = pending_video_receipt_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        #[cfg(windows)]
        if let Some(next) = bounded_pty_exit_wait {
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if held_child_reap_pending {
            let next = std::time::Duration::from_secs(1);
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if ws.output_pacer.is_deferred()
            && !ws.output_pacer.redraw_queued()
            && !render_hidden
            && !ws.frame_recovery.has_pending()
        {
            let remaining = ws
                .last_paint
                .map(|t| output_budget.saturating_sub(now.saturating_duration_since(t)))
                .unwrap_or_default();
            let next = remaining.max(std::time::Duration::from_nanos(1));
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        // Search's deferred unlimited pass is deadline-driven and chunked.
        // Wake exactly when the 500 ms typing debounce expires; while a chunk
        // job remains, schedule the next event-loop turn without polling at a
        // frame-rate forever (the job clears at a match or terminal edge).
        if ws.search.open {
            // Repaint once when the bar should start saying `Searching…`.
            if let Some(at) = ws.search.searching_label_at() {
                if now < at {
                    ws.search.searching_label_wake = Some(at);
                    let next = at.saturating_duration_since(now);
                    wait = Some(wait.map_or(next, |current| current.min(next)));
                } else if ws.search.searching_label_wake.take().is_some()
                    && let Some(window) = &ws.window
                {
                    window.request_redraw();
                }
            }
            if let Some(deadline) = ws.search.unlimited_retry_at {
                let due = now >= deadline;
                let next = if due {
                    std::time::Duration::from_millis(1)
                } else {
                    deadline
                        .saturating_duration_since(now)
                        .max(std::time::Duration::from_millis(1))
                };
                wait = Some(wait.map_or(next, |current| current.min(next)));
                if due && let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
            if ws.search.background.is_some() {
                let next = std::time::Duration::from_millis(1);
                wait = Some(wait.map_or(next, |current| current.min(next)));
                if let Some(window) = &ws.window {
                    window.request_redraw();
                }
            }
        }
        if ws.accessibility_pending {
            let remaining =
                ws.accessibility_updated_at
                    .map_or(std::time::Duration::ZERO, |updated| {
                        ACCESSIBILITY_UPDATE_INTERVAL
                            .saturating_sub(now.saturating_duration_since(updated))
                    });
            let due = remaining.is_zero();
            let next = if due {
                std::time::Duration::from_millis(1)
            } else {
                remaining.max(std::time::Duration::from_millis(1))
            };
            wait = Some(wait.map_or(next, |current| current.min(next)));
            if due && let Some(window) = &ws.window {
                window.request_redraw();
            }
        }
        // Reply `timed_out` to any pending
        // run_command whose deadline has passed, and—while runs are pending—
        // schedule a wake at the soonest deadline so a fully-silent command
        // (no output to wake us) still times out on time.
        self.check_pending_run_deadlines(ws);
        // `show` pushes waiting past their deadline are answered, and those
        // whose pane closed are dropped, even when nothing else wakes us.
        self.media_tick(ws);
        self.prune_previews(ws);
        self.open_ready_previews(ws);
        if let Some(soonest) = self.media.next_deadline() {
            let next = soonest.saturating_duration_since(now).clamp(
                std::time::Duration::from_millis(1),
                std::time::Duration::from_millis(500),
            );
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        if let Some(soonest) = self.pending_runs.values().map(|p| p.deadline).min() {
            let next = soonest.saturating_duration_since(now).clamp(
                std::time::Duration::from_millis(1),
                std::time::Duration::from_millis(500),
            );
            wait = Some(wait.map_or(next, |current| current.min(next)));
        }
        // A worker failure may already be visible before this callback begins,
        // so comparing status only within this turn would miss the edge. The
        // notifier is edge-triggered; this unconditional state sync is cheap.
        if self.recorder.is_some() {
            let body = self
                .ui_text
                .text(kettle_i18n::Text::NotifyBodyRecordingFlushFailed);
            self.sync_recording_state(ws, body);
        }
        wait.map(|remaining| now + remaining)
    }
}

impl Drop for App {
    fn drop(&mut self) {
        if let Some(recorder) = self.recorder.as_mut() {
            // Fatal renderer or event-loop exits can bypass CloseRequested.
            // Marking shutdown asynchronous here keeps their cleanup path from
            // inheriting arbitrary recording-device latency.
            recorder.begin_finish();
        }
    }
}

